import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, deleteRecord, selectRecords } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { Plus, Trash2, Edit } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';

interface JobCostItem {
  id?: string;
  job_id: string;
  category: string;
  description: string;
  quantity: number;
  unit_cost: number;
  total_cost: number;
  vendor?: string | null;
  date_incurred: string;
}

interface JobCostItemsDialogProps {
  isOpen: boolean;
  onClose: () => void;
  jobId: string;
  jobTitle?: string;
  onItemsUpdated?: () => void;
}

const JobCostItemsDialog: React.FC<JobCostItemsDialogProps> = ({ 
  isOpen, 
  onClose, 
  jobId,
  jobTitle,
  onItemsUpdated 
}) => {
  const { toast } = useToast();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [items, setItems] = useState<JobCostItem[]>([]);
  const [editingItem, setEditingItem] = useState<JobCostItem | null>(null);
  const [formData, setFormData] = useState<JobCostItem>({
    job_id: jobId,
    category: '',
    description: '',
    quantity: 1,
    unit_cost: 0,
    total_cost: 0,
    vendor: '',
    date_incurred: new Date().toISOString().split('T')[0],
  });

  const costCategories = [
    'labor',
    'materials',
    'equipment',
    'overhead',
    'other'
  ];

  useEffect(() => {
    if (isOpen && jobId) {
      fetchCostItems();
      resetForm();
    }
  }, [isOpen, jobId]);

  const fetchCostItems = async () => {
    try {
      setLoading(true);
      const costItems = await selectRecords('job_cost_items', {
        where: { job_id: jobId },
        orderBy: 'date_incurred DESC, created_at DESC',
      });
      setItems(costItems || []);
    } catch (error: unknown) {
      console.error('Error fetching cost items:', error);
      toast({
        title: 'Error',
        description: 'Failed to load cost items',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      job_id: jobId,
      category: '',
      description: '',
      quantity: 1,
      unit_cost: 0,
      total_cost: 0,
      vendor: '',
      date_incurred: new Date().toISOString().split('T')[0],
    });
    setEditingItem(null);
  };

  const calculateTotal = (quantity: number, unitCost: number) => {
    return quantity * unitCost;
  };

  const handleQuantityChange = (value: number) => {
    const qty = value || 0;
    const unitCost = formData.unit_cost || 0;
    setFormData(prev => ({
      ...prev,
      quantity: qty,
      total_cost: calculateTotal(qty, unitCost),
    }));
  };

  const handleUnitCostChange = (value: number) => {
    const cost = value || 0;
    const qty = formData.quantity || 0;
    setFormData(prev => ({
      ...prev,
      unit_cost: cost,
      total_cost: calculateTotal(qty, cost),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.category.trim()) {
      toast({
        title: 'Error',
        description: 'Category is required',
        variant: 'destructive',
      });
      return;
    }

    if (!formData.description.trim()) {
      toast({
        title: 'Error',
        description: 'Description is required',
        variant: 'destructive',
      });
      return;
    }

    if (formData.quantity <= 0) {
      toast({
        title: 'Error',
        description: 'Quantity must be greater than 0',
        variant: 'destructive',
      });
      return;
    }

    if (formData.unit_cost <= 0) {
      toast({
        title: 'Error',
        description: 'Unit cost must be greater than 0',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);

    try {
      const cleanedData: unknown = {
        job_id: jobId,
        category: formData.category.trim(),
        description: formData.description.trim(),
        quantity: formData.quantity,
        unit_cost: formData.unit_cost,
        total_cost: formData.total_cost,
        vendor: formData.vendor?.trim() || null,
        date_incurred: formData.date_incurred,
      };

      if (editingItem?.id) {
        await updateRecord('job_cost_items', cleanedData, { id: editingItem.id }, user?.id);
        toast({
          title: 'Success',
          description: 'Cost item updated successfully',
        });
      } else {
        await insertRecord('job_cost_items', {
          ...cleanedData,
          created_by: user?.id || null,
        }, user?.id);
        toast({
          title: 'Success',
          description: 'Cost item added successfully',
        });
      }

      await fetchCostItems();
      resetForm();
      // Trigger update of job's actual_cost
      onItemsUpdated?.();
    } catch (error: unknown) {
      console.error('Error saving cost item:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save cost item',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (item: JobCostItem) => {
    setEditingItem(item);
    setFormData({
      job_id: jobId,
      category: item.category,
      description: item.description,
      quantity: item.quantity,
      unit_cost: item.unit_cost,
      total_cost: item.total_cost,
      vendor: item.vendor || '',
      date_incurred: item.date_incurred,
    });
  };

  const handleDelete = async (itemId: string) => {
    if (!confirm('Are you sure you want to delete this cost item?')) {
      return;
    }

    try {
      await deleteRecord('job_cost_items', { id: itemId });
      toast({
        title: 'Success',
        description: 'Cost item deleted successfully',
      });
      await fetchCostItems();
      // Trigger update of job's actual_cost
      onItemsUpdated?.();
    } catch (error: unknown) {
      console.error('Error deleting cost item:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete cost item',
        variant: 'destructive',
      });
    }
  };

  const totalCost = items.reduce((sum, item) => sum + (parseFloat(item.total_cost?.toString() || '0') || 0), 0);

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Job Cost Items - {jobTitle || 'Job'}</DialogTitle>
          <DialogDescription>
            Manage cost items for this job. Track labor, materials, equipment, and other expenses.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-6">
          {/* Add/Edit Form */}
          <Card>
            <CardContent className="pt-6">
              <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="category">Category *</Label>
                    <Select
                      value={formData.category}
                      onValueChange={(value) => setFormData(prev => ({ ...prev, category: value }))}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select category" />
                      </SelectTrigger>
                      <SelectContent>
                        {costCategories.map((cat) => (
                          <SelectItem key={cat} value={cat}>
                            {cat.charAt(0).toUpperCase() + cat.slice(1)}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="date_incurred">Date Incurred *</Label>
                    <Input
                      id="date_incurred"
                      type="date"
                      value={formData.date_incurred}
                      onChange={(e) => setFormData(prev => ({ ...prev, date_incurred: e.target.value }))}
                      required
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="description">Description *</Label>
                  <Textarea
                    id="description"
                    value={formData.description}
                    onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                    rows={2}
                    placeholder="Describe the cost item"
                    required
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                  <div className="space-y-2">
                    <Label htmlFor="quantity">Quantity *</Label>
                    <Input
                      id="quantity"
                      type="number"
                      min="0.01"
                      step="0.01"
                      value={formData.quantity || ''}
                      onChange={(e) => handleQuantityChange(parseFloat(e.target.value) || 0)}
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="unit_cost">Unit Cost (₹) *</Label>
                    <Input
                      id="unit_cost"
                      type="number"
                      min="0"
                      step="0.01"
                      value={formData.unit_cost || ''}
                      onChange={(e) => handleUnitCostChange(parseFloat(e.target.value) || 0)}
                      required
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="total_cost">Total Cost (₹)</Label>
                    <Input
                      id="total_cost"
                      type="number"
                      value={formData.total_cost.toFixed(2)}
                      disabled
                      className="bg-muted"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="vendor">Vendor</Label>
                    <Input
                      id="vendor"
                      value={formData.vendor || ''}
                      onChange={(e) => setFormData(prev => ({ ...prev, vendor: e.target.value }))}
                      placeholder="Vendor name (optional)"
                    />
                  </div>
                </div>

                <div className="flex gap-2">
                  <Button type="submit" disabled={loading}>
                    {loading ? 'Saving...' : editingItem ? 'Update Item' : 'Add Item'}
                  </Button>
                  {editingItem && (
                    <Button type="button" variant="outline" onClick={resetForm}>
                      Cancel Edit
                    </Button>
                  )}
                </div>
              </form>
            </CardContent>
          </Card>

          {/* Cost Items List */}
          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <h3 className="text-lg font-semibold">Cost Items</h3>
              <div className="text-right">
                <p className="text-sm text-muted-foreground">Total Cost</p>
                <p className="text-2xl font-bold">₹{totalCost.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
              </div>
            </div>

            {loading && items.length === 0 ? (
              <div className="text-center py-8">
                <p className="text-muted-foreground">Loading cost items...</p>
              </div>
            ) : items.length === 0 ? (
              <Card>
                <CardContent className="p-8 text-center text-muted-foreground">
                  <p>No cost items added yet. Add your first cost item above.</p>
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-2">
                {items.map((item) => (
                  <Card key={item.id} className="hover:shadow-md transition-shadow">
                    <CardContent className="p-4">
                      <div className="flex justify-between items-start">
                        <div className="flex-1">
                          <div className="flex items-center gap-2 mb-2">
                            <Badge variant="outline">{item.category}</Badge>
                            <span className="text-sm text-muted-foreground">
                              {new Date(item.date_incurred).toLocaleDateString()}
                            </span>
                          </div>
                          <p className="font-medium">{item.description}</p>
                          {item.vendor && (
                            <p className="text-sm text-muted-foreground">Vendor: {item.vendor}</p>
                          )}
                          <div className="flex gap-4 mt-2 text-sm text-muted-foreground">
                            <span>Qty: {item.quantity}</span>
                            <span>Unit: ₹{parseFloat(item.unit_cost?.toString() || '0').toLocaleString()}</span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <div className="text-right mr-4">
                            <p className="font-bold text-lg">
                              ₹{parseFloat(item.total_cost?.toString() || '0').toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                            </p>
                          </div>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleEdit(item)}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleDelete(item.id!)}
                          >
                            <Trash2 className="h-4 w-4 text-red-500" />
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            )}
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Close
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};

export default JobCostItemsDialog;

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, CheckCircle, AlertTriangle, Plus } from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { Separator } from '@/components/ui/separator';
import { db } from '@/lib/database';
import { useToast } from '@/hooks/use-toast';
import { useAsyncOperation } from '@/hooks/useAsyncOperation';
import { LoadingSpinner } from './LoadingSpinner';

interface LeaveBalance {
  leave_type_name: string;
  allocated_days: number;
  used_days: number;
  pending_days: number;
  remaining_days: number;
}

interface LeaveBalanceWidgetProps {
  employeeId?: string;
  year?: number;
  onRequestLeave?: () => void;
  compact?: boolean;
}

export const LeaveBalanceWidget: React.FC<LeaveBalanceWidgetProps> = ({
  employeeId,
  year = new Date().getFullYear(),
  onRequestLeave,
  compact = false
}) => {
  const [balances, setBalances] = useState<LeaveBalance[]>([]);
  const { toast } = useToast();

  const { execute: loadBalances, loading } = useAsyncOperation({
    onError: (error) => toast({
      variant: 'destructive',
      title: 'Failed to load leave balances',
      description: error.message
    })
  });

  const fetchBalances = async () => {
    return loadBalances(async () => {
      const { data, error } = await db.rpc('get_leave_balance_summary', {
        p_employee_id: employeeId || undefined,
        p_year: year
      });

      if (error) throw error;
      setBalances((data || []) as LeaveBalance[]);
      return data;
    });
  };

  useEffect(() => {
    fetchBalances();
  }, [employeeId, year]);

  const getUsageColor = (percentage: number) => {
    if (percentage >= 90) return 'text-red-600';
    if (percentage >= 75) return 'text-orange-600';
    if (percentage >= 50) return 'text-yellow-600';
    return 'text-green-600';
  };

  const getProgressColor = (percentage: number) => {
    if (percentage >= 90) return 'bg-red-500';
    if (percentage >= 75) return 'bg-orange-500';
    if (percentage >= 50) return 'bg-yellow-500';
    return 'bg-green-500';
  };

  const totalAllocated = balances.reduce((sum, b) => sum + Number(b.allocated_days), 0);
  const totalUsed = balances.reduce((sum, b) => sum + Number(b.used_days), 0);
  const totalPending = balances.reduce((sum, b) => sum + Number(b.pending_days), 0);
  const totalRemaining = balances.reduce((sum, b) => sum + Number(b.remaining_days), 0);

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6">
          <LoadingSpinner size="md" text="Loading leave balances..." />
        </CardContent>
      </Card>
    );
  }

  if (compact) {
    return (
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-base">Leave Balance {year}</CardTitle>
            <Calendar className="w-4 h-4 text-muted-foreground" />
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid grid-cols-3 gap-2 text-center">
            <div>
              <div className="text-lg font-semibold text-green-600">{totalRemaining}</div>
              <div className="text-xs text-muted-foreground">Available</div>
            </div>
            <div>
              <div className="text-lg font-semibold text-blue-600">{totalUsed}</div>
              <div className="text-xs text-muted-foreground">Used</div>
            </div>
            <div>
              <div className="text-lg font-semibold text-orange-600">{totalPending}</div>
              <div className="text-xs text-muted-foreground">Pending</div>
            </div>
          </div>
          
          {onRequestLeave && (
            <Button size="sm" onClick={onRequestLeave} className="w-full">
              <Plus className="w-3 h-3 mr-1" />
              Request Leave
            </Button>
          )}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Leave Balances {year}</CardTitle>
            <CardDescription>
              Your annual leave allowances and usage
            </CardDescription>
          </div>
          <Calendar className="w-5 h-5 text-muted-foreground" />
        </div>
      </CardHeader>
      
      <CardContent className="space-y-6">
        {/* Summary */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center">
            <div className="text-2xl font-bold text-green-600">{totalRemaining}</div>
            <div className="text-sm text-muted-foreground">Days Available</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-blue-600">{totalUsed}</div>
            <div className="text-sm text-muted-foreground">Days Used</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-orange-600">{totalPending}</div>
            <div className="text-sm text-muted-foreground">Days Pending</div>
          </div>
          <div className="text-center">
            <div className="text-2xl font-bold text-gray-600">{totalAllocated}</div>
            <div className="text-sm text-muted-foreground">Total Allocated</div>
          </div>
        </div>

        <Separator />

        {/* Detailed Breakdown */}
        <div className="space-y-4">
          <h4 className="font-medium">Leave Type Breakdown</h4>
          
          {balances.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <Clock className="w-8 h-8 mx-auto mb-2 opacity-50" />
              <p>No leave balances found for {year}</p>
              <p className="text-sm">Leave balances may not be initialized yet.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {balances.map((balance) => {
                const usagePercentage = totalAllocated > 0 ? 
                  ((Number(balance.used_days) + Number(balance.pending_days)) / Number(balance.allocated_days)) * 100 : 0;
                
                return (
                  <div key={balance.leave_type_name} className="space-y-2">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-2">
                        <span className="font-medium">{balance.leave_type_name}</span>
                        {usagePercentage >= 90 && (
                          <AlertTriangle className="w-4 h-4 text-red-500" />
                        )}
                      </div>
                      <div className="text-sm text-muted-foreground">
                        {balance.remaining_days} / {balance.allocated_days} days
                      </div>
                    </div>
                    
                    <div className="space-y-1">
                      <Progress 
                        value={usagePercentage} 
                        className="h-2"
                      />
                      <div className="flex justify-between text-xs text-muted-foreground">
                        <span>Used: {balance.used_days}</span>
                        {Number(balance.pending_days) > 0 && (
                          <span>Pending: {balance.pending_days}</span>
                        )}
                        <span className={getUsageColor(usagePercentage)}>
                          {usagePercentage.toFixed(1)}% used
                        </span>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Actions */}
        {onRequestLeave && (
          <>
            <Separator />
            <div className="flex justify-center">
              <Button onClick={onRequestLeave}>
                <Plus className="w-4 h-4 mr-2" />
                Request Leave
              </Button>
            </div>
          </>
        )}

        {/* Helpful Information */}
        <div className="text-xs text-muted-foreground space-y-1">
          <p>• Leave balances are updated automatically when requests are approved</p>
          <p>• Pending requests temporarily reduce your available balance</p>
          <p>• Contact HR if you notice any discrepancies</p>
        </div>
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect } from 'react';
import { Bell, Check, X, ExternalLink, Clock, AlertTriangle, Info, CheckCircle, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Link } from 'react-router-dom';
import { getApiEndpoint } from '@/config/services';
import { useToast } from '@/hooks/use-toast';
import { LoadingSpinner } from './LoadingSpinner';
import { useAsyncOperation } from '@/hooks/useAsyncOperation';
import { useAuth } from '@/hooks/useAuth';

interface Notification {
  id: string;
  type: 'email' | 'in_app' | 'push';
  category: 'approval' | 'reminder' | 'update' | 'alert' | 'system';
  title: string;
  message: string;
  metadata: unknown;
  read_at: string | null;
  sent_at: string | null;
  priority: 'low' | 'normal' | 'high' | 'urgent';
  expires_at: string | null;
  action_url: string | null;
  created_at: string;
}

export const NotificationCenter: React.FC = () => {
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);
  const [activeTab, setActiveTab] = useState('all');
  const { toast } = useToast();
  const { user } = useAuth();

  const { execute: fetchNotifications, loading: loadingNotifications } = useAsyncOperation({
    onError: (error) => {
      // Don't show error if table doesn't exist - it's expected during initial setup
      if (!error.message?.includes('does not exist') && !error.message?.includes('42P01')) {
        toast({ variant: 'destructive', title: 'Failed to load notifications', description: error.message });
      }
    }
  });

  const { execute: markAsRead, loading: markingRead } = useAsyncOperation({
    onSuccess: () => {
      setUnreadCount(prev => Math.max(0, prev - 1));
      toast({ title: 'Notification marked as read' });
    }
  });

  const getAuthHeaders = () => ({
    'Content-Type': 'application/json',
    'Authorization': `Bearer ${localStorage.getItem('auth_token') || ''}`,
  });

  const loadNotifications = async () => {
    if (!user) return;

    return fetchNotifications(async () => {
      const endpoint = getApiEndpoint('/notifications');
      const response = await fetch(endpoint, { headers: getAuthHeaders() });
      if (!response.ok) {
        if (response.status === 403) return [];
        throw new Error(`Failed to load notifications: ${response.status}`);
      }
      const json = await response.json();
      const data: Notification[] = json?.data?.notifications ?? json?.data ?? [];
      setNotifications(Array.isArray(data) ? data : []);
      setUnreadCount(json?.data?.pagination?.unreadCount ?? data.filter((n: Notification) => !n.read_at).length);
      return data;
    });
  };

  const handleMarkAsRead = async (notificationId: string) => {
    return markAsRead(async () => {
      const endpoint = getApiEndpoint(`/notifications/${notificationId}/read`);
      await fetch(endpoint, { method: 'PUT', headers: getAuthHeaders() });
      setNotifications(prev =>
        prev.map(n => n.id === notificationId ? { ...n, read_at: new Date().toISOString() } : n)
      );
    });
  };

  const handleMarkAllAsRead = async () => {
    const endpoint = getApiEndpoint('/notifications/read-all');
    await fetch(endpoint, { method: 'PUT', headers: getAuthHeaders() });
    setNotifications(prev => prev.map(n => ({ ...n, read_at: n.read_at ?? new Date().toISOString() })));
    setUnreadCount(0);
    toast({ title: 'All notifications marked as read' });
  };

  const handleNotificationClick = (notification: Notification) => {
    if (!notification.read_at) {
      handleMarkAsRead(notification.id);
    }
    
    if (notification.action_url) {
      window.open(notification.action_url, '_blank');
    }
  };

  useEffect(() => {
    if (user) {
      loadNotifications();
      
      // Set up polling for notifications (realtime not available in browser-only mode)
      const pollInterval = setInterval(() => {
        loadNotifications();
      }, 30000); // Poll every 30 seconds

      return () => {
        clearInterval(pollInterval);
      };
    }
  }, [user]);

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'urgent': return <AlertTriangle className="w-4 h-4 text-red-500" />;
      case 'high': return <AlertTriangle className="w-4 h-4 text-orange-500" />;
      case 'normal': return <Info className="w-4 h-4 text-blue-500" />;
      case 'low': return <Info className="w-4 h-4 text-gray-500" />;
      default: return <Info className="w-4 h-4 text-blue-500" />;
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'approval': return 'bg-yellow-100 text-yellow-800';
      case 'reminder': return 'bg-blue-100 text-blue-800';
      case 'update': return 'bg-green-100 text-green-800';
      case 'alert': return 'bg-red-100 text-red-800';
      case 'system': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredNotifications = notifications.filter(notification => {
    if (activeTab === 'all') return true;
    if (activeTab === 'unread') return !notification.read_at;
    return notification.category === activeTab;
  });

  return (
    <Popover open={isOpen} onOpenChange={setIsOpen}>
      <PopoverTrigger asChild>
        <Button variant="ghost" size="sm" className="relative">
          <Bell className="h-5 w-5" />
          {unreadCount > 0 && (
            <Badge 
              variant="destructive" 
              className="absolute -top-1 -right-1 h-5 w-5 rounded-full p-0 text-xs flex items-center justify-center"
            >
              {unreadCount > 99 ? '99+' : unreadCount}
            </Badge>
          )}
        </Button>
      </PopoverTrigger>
      
      <PopoverContent className="w-[90vw] sm:w-96 max-w-sm p-0" align="end">
        <Card className="border-0 shadow-none">
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg">Notifications</CardTitle>
              {unreadCount > 0 && (
                <Button 
                  variant="ghost" 
                  size="sm" 
                  onClick={handleMarkAllAsRead}
                  disabled={markingRead}
                >
                  <CheckCircle className="w-4 h-4 mr-1" />
                  Mark all read
                </Button>
              )}
            </div>
            <CardDescription>
              {unreadCount} unread notification{unreadCount !== 1 ? 's' : ''}
            </CardDescription>
          </CardHeader>
          
          <CardContent className="p-0">
            <Tabs value={activeTab} onValueChange={setActiveTab}>
              <div className="px-2 sm:px-3 pt-2 pb-2 border-b">
                <TabsList className="grid grid-cols-4 w-full h-auto p-0.5 bg-muted/50 gap-0.5">
                  <TabsTrigger 
                    value="all" 
                    className="text-[10px] sm:text-xs px-1 sm:px-2 py-1.5 whitespace-nowrap truncate"
                  >
                    All
                  </TabsTrigger>
                  <TabsTrigger 
                    value="unread" 
                    className="text-[10px] sm:text-xs px-1 sm:px-2 py-1.5 whitespace-nowrap truncate"
                  >
                    Unread
                  </TabsTrigger>
                  <TabsTrigger 
                    value="approval" 
                    className="text-[10px] sm:text-xs px-1 sm:px-2 py-1.5 whitespace-nowrap truncate"
                  >
                    Approval
                  </TabsTrigger>
                  <TabsTrigger 
                    value="alert" 
                    className="text-[10px] sm:text-xs px-1 sm:px-2 py-1.5 whitespace-nowrap truncate"
                  >
                    Alerts
                  </TabsTrigger>
                </TabsList>
              </div>
              
              <ScrollArea className="h-96">
                <TabsContent value={activeTab} className="mt-0">
                  {loadingNotifications ? (
                    <div className="flex justify-center py-8">
                      <LoadingSpinner size="md" text="Loading notifications..." />
                    </div>
                  ) : filteredNotifications.length === 0 ? (
                    <div className="text-center py-8 text-muted-foreground">
                      <Bell className="w-8 h-8 mx-auto mb-2 opacity-50" />
                      <p>No notifications</p>
                    </div>
                  ) : (
                    <div className="space-y-1">
                      {filteredNotifications.map((notification, index) => (
                        <div key={notification.id}>
                          <div 
                            className={`p-3 cursor-pointer hover:bg-muted/50 transition-colors ${
                              !notification.read_at ? 'bg-blue-50/50' : ''
                            }`}
                            onClick={() => handleNotificationClick(notification)}
                          >
                            <div className="flex items-start space-x-3">
                              <div className="flex-shrink-0 mt-1">
                                {getPriorityIcon(notification.priority)}
                              </div>
                              
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center justify-between mb-1">
                                  <h4 className="text-sm font-medium truncate">
                                    {notification.title}
                                  </h4>
                                  <div className="flex items-center space-x-1">
                                    <Badge 
                                      variant="secondary" 
                                      className={`text-xs ${getCategoryColor(notification.category)}`}
                                    >
                                      {notification.category}
                                    </Badge>
                                    {!notification.read_at && (
                                      <div className="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0" />
                                    )}
                                  </div>
                                </div>
                                
                                <p className="text-sm text-muted-foreground mb-2 line-clamp-2">
                                  {notification.message}
                                </p>
                                
                                <div className="flex items-center justify-between text-xs text-muted-foreground">
                                  <div className="flex items-center">
                                    <Clock className="w-3 h-3 mr-1" />
                                    {new Date(notification.created_at).toLocaleString()}
                                  </div>
                                  {notification.action_url && (
                                    <ExternalLink className="w-3 h-3" />
                                  )}
                                </div>
                              </div>
                            </div>
                          </div>
                          {index < filteredNotifications.length - 1 && <Separator />}
                        </div>
                      ))}
                    </div>
                  )}
                </TabsContent>
              </ScrollArea>
            </Tabs>
            
            <div className="border-t p-3">
              <Button variant="ghost" className="w-full" asChild>
                <Link to="/notifications">
                  View All Notifications
                  <ArrowRight className="w-4 h-4 ml-2" />
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      </PopoverContent>
    </Popover>
  );
};

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { Download, Printer, Mail, X, Building, MapPin, Phone, Mail as MailIcon, Calendar, FileText } from 'lucide-react';

interface Quotation {
  id: string;
  quote_number?: string;
  quotation_number?: string;
  client_id: string;
  template_id?: string | null;
  title: string;
  description?: string;
  status: string;
  issue_date?: string;
  expiry_date?: string;
  valid_until?: string;
  subtotal: number;
  tax_rate: number;
  tax_amount: number;
  discount?: number;
  total_amount: number;
  terms_conditions?: string;
  terms_and_conditions?: string;
  notes?: string;
  created_at: string;
  updated_at: string;
}

interface Client {
  id: string;
  name: string;
  company_name?: string;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  state?: string;
  postal_code?: string;
  country?: string;
  contact_person?: string;
  contact_email?: string;
  contact_phone?: string;
  billing_address?: string;
  billing_city?: string;
  billing_state?: string;
  billing_postal_code?: string;
  billing_country?: string;
  tax_id?: string;
}

interface LineItem {
  id: string;
  item_name: string;
  description?: string;
  quantity: number;
  unit_price: number;
  discount_percentage?: number;
  line_total?: number;
  sort_order?: number;
}

interface AgencyInfo {
  agency_name?: string;
  logo_url?: string;
  address?: string;
  city?: string;
  state?: string;
  postal_code?: string;
  country?: string;
  phone?: string;
  email?: string;
  website?: string;
  tax_id?: string;
}

interface QuotationPreviewDialogProps {
  isOpen: boolean;
  onClose: () => void;
  quotationId: string | null;
}

const QuotationPreviewDialog: React.FC<QuotationPreviewDialogProps> = ({
  isOpen,
  onClose,
  quotationId,
}) => {
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [quotation, setQuotation] = useState<Quotation | null>(null);
  const [client, setClient] = useState<Client | null>(null);
  const [lineItems, setLineItems] = useState<LineItem[]>([]);
  const [agencyInfo, setAgencyInfo] = useState<AgencyInfo>({});

  useEffect(() => {
    if (isOpen && quotationId) {
      fetchQuotationData();
    }
  }, [isOpen, quotationId]);

  const calculateLineTotal = (item: LineItem): number => {
    const qty = Number(item.quantity) || 0;
    const price = Number(item.unit_price) || 0;
    const subtotal = qty * price;
    const discountPct = Number(item.discount_percentage) || 0;
    const discount = subtotal * (discountPct / 100);
    return subtotal - discount;
  };

  const fetchQuotationData = async () => {
    try {
      setLoading(true);

      // Fetch quotation
      const { data: quotationData, error: quotationError } = await db
        .from('quotations')
        .select('*')
        .eq('id', quotationId)
        .single();

      if (quotationError) throw quotationError;
      if (!quotationData) {
        toast({
          title: 'Error',
          description: 'Quotation not found',
          variant: 'destructive',
        });
        return;
      }

      setQuotation(quotationData);

      // Fetch client
      if (quotationData.client_id) {
        const { data: clientData, error: clientError } = await db
          .from('clients')
          .select('*')
          .eq('id', quotationData.client_id)
          .single();

        if (!clientError && clientData) {
          setClient(clientData);
        }
      }

      // Fetch line items
      const { data: lineItemsData, error: lineItemsError } = await db
        .from('quotation_line_items')
        .select('*')
        .eq('quotation_id', quotationId)
        .order('sort_order', { ascending: true });

      if (!lineItemsError && lineItemsData) {
        // Calculate line totals if not present
        const itemsWithTotals = lineItemsData.map(item => ({
          ...item,
          line_total: item.line_total || calculateLineTotal(item),
        }));
        setLineItems(itemsWithTotals);
      }

      // Fetch agency info
      const { data: agencyData, error: agencyError } = await db
        .from('agency_settings')
        .select('*')
        .limit(1)
        .single();

      if (!agencyError && agencyData) {
        setAgencyInfo({
          agency_name: agencyData.agency_name,
          logo_url: agencyData.logo_url,
          address: agencyData.address_street || agencyData.address,
          city: agencyData.address_city || agencyData.city,
          state: agencyData.address_state || agencyData.state,
          postal_code: agencyData.address_zip || agencyData.postal_code,
          country: agencyData.address_country || agencyData.country,
          phone: agencyData.phone,
          email: agencyData.email,
          website: agencyData.website,
          tax_id: agencyData.tax_id,
        });
      }
    } catch (error: unknown) {
      console.error('Error fetching quotation data:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to load quotation',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadPDF = () => {
    // Create a printable version
    const printWindow = window.open('', '_blank');
    if (!printWindow) return;

    const content = document.getElementById('quotation-preview-content');
    if (!content) return;

    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <title>Quotation ${quotation?.quote_number}</title>
          <style>
            @page {
              margin: 1cm;
            }
            @media print {
              body { margin: 0; padding: 0; font-family: Arial, sans-serif; font-size: 12px; }
              .no-print { display: none !important; }
              .print-break { page-break-after: always; }
            }
            body { font-family: Arial, sans-serif; padding: 20px; color: #000; }
            .header { display: flex; justify-content: space-between; margin-bottom: 30px; border-bottom: 2px solid #000; padding-bottom: 20px; }
            .logo { max-width: 150px; max-height: 80px; }
            .section { margin-bottom: 20px; }
            table { width: 100%; border-collapse: collapse; margin: 20px 0; }
            th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
            th { background-color: #f5f5f5; font-weight: bold; }
            .totals { float: right; margin-top: 20px; }
            .totals table { width: 300px; border: none; }
            .totals td { padding: 5px 10px; border: none; }
            .totals .total-row { font-weight: bold; font-size: 1.2em; border-top: 2px solid #000; }
            .footer { margin-top: 40px; padding-top: 20px; border-top: 1px solid #ddd; text-align: center; font-size: 10px; color: #666; }
          </style>
        </head>
        <body>
          ${content.innerHTML}
        </body>
      </html>
    `);
    printWindow.document.close();
    printWindow.print();
  };

  const formatCurrency = (amount: number) => {
    return `₹${amount.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
  };

  const formatDate = (dateString: string) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-IN', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
    });
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'draft': return 'bg-gray-100 text-gray-800';
      case 'sent': return 'bg-blue-100 text-blue-800';
      case 'accepted': return 'bg-green-100 text-green-800';
      case 'rejected': return 'bg-red-100 text-red-800';
      case 'expired': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  if (loading) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Loading Quotation</DialogTitle>
            <DialogDescription>Please wait while we load the quotation details</DialogDescription>
          </DialogHeader>
          <div className="flex items-center justify-center py-12">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
              <p className="text-muted-foreground">Loading quotation...</p>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  if (!quotation) {
    return (
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-5xl">
          <DialogHeader>
            <DialogTitle>Quotation Not Found</DialogTitle>
            <DialogDescription>The requested quotation could not be found</DialogDescription>
          </DialogHeader>
          <div className="text-center py-8">
            <p className="text-muted-foreground">Quotation not found</p>
          </div>
        </DialogContent>
      </Dialog>
    );
  }

  return (
    <>
      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { margin: 0; padding: 0; }
          .quotation-content { padding: 0 !important; }
        }
      `}</style>
      <Dialog open={isOpen} onOpenChange={onClose}>
        <DialogContent className="max-w-6xl max-h-[95vh] overflow-y-auto p-0 print:max-w-full print:max-h-full">
          <DialogHeader className="px-6 pt-6 pb-4 border-b no-print">
            <DialogTitle>Quotation Preview</DialogTitle>
            <DialogDescription>
              Review your quotation details before sending or printing
            </DialogDescription>
          </DialogHeader>
          <div className="px-6 pt-4 pb-4 border-b no-print">
            <div className="flex justify-end gap-2">
              <Button variant="outline" size="sm" onClick={handlePrint}>
                <Printer className="h-4 w-4 mr-2" />
                Print
              </Button>
              <Button variant="outline" size="sm" onClick={handleDownloadPDF}>
                <Download className="h-4 w-4 mr-2" />
                Download PDF
              </Button>
              <Button variant="outline" size="sm" onClick={onClose}>
                <X className="h-4 w-4" />
              </Button>
            </div>
          </div>

        <div id="quotation-preview-content" className="px-6 py-8 bg-white quotation-content print:p-4">
          {/* Header */}
          <div className="flex flex-col md:flex-row justify-between items-start md:items-start gap-6 mb-8 border-b pb-6">
            <div className="flex-1">
              {agencyInfo.logo_url && (
                <img
                  src={agencyInfo.logo_url}
                  alt={agencyInfo.agency_name || 'Agency Logo'}
                  className="h-16 mb-4 object-contain"
                  onError={(e) => {
                    // Hide image if it fails to load (invalid URI)
                    const target = e.target as HTMLImageElement;
                    target.style.display = 'none';
                  }}
                />
              )}
              <h2 className="text-2xl font-bold mb-2">
                {agencyInfo.agency_name || 'Agency Name'}
              </h2>
              <div className="text-sm text-muted-foreground space-y-1">
                {agencyInfo.address && (
                  <div className="flex items-center gap-2">
                    <MapPin className="h-4 w-4" />
                    <span>
                      {agencyInfo.address}
                      {agencyInfo.city && `, ${agencyInfo.city}`}
                      {agencyInfo.state && `, ${agencyInfo.state}`}
                      {agencyInfo.postal_code && ` ${agencyInfo.postal_code}`}
                      {agencyInfo.country && `, ${agencyInfo.country}`}
                    </span>
                  </div>
                )}
                {agencyInfo.phone && (
                  <div className="flex items-center gap-2">
                    <Phone className="h-4 w-4" />
                    <span>{agencyInfo.phone}</span>
                  </div>
                )}
                {agencyInfo.email && (
                  <div className="flex items-center gap-2">
                    <MailIcon className="h-4 w-4" />
                    <span>{agencyInfo.email}</span>
                  </div>
                )}
                {agencyInfo.website && (
                  <div className="flex items-center gap-2">
                    <Building className="h-4 w-4" />
                    <span>{agencyInfo.website}</span>
                  </div>
                )}
                {agencyInfo.tax_id && (
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <span>Tax ID: {agencyInfo.tax_id}</span>
                  </div>
                )}
              </div>
            </div>
            <div className="text-left md:text-right w-full md:w-auto">
              <h1 className="text-3xl font-bold mb-3">QUOTATION</h1>
              <div className="space-y-2 text-sm">
                <div>
                  <span className="text-muted-foreground">Quote #: </span>
                  <span className="font-semibold text-base">{quotation.quote_number || quotation.quotation_number || 'N/A'}</span>
                </div>
                {quotation.issue_date && (
                  <div>
                    <span className="text-muted-foreground">Issue Date: </span>
                    <span className="font-medium">{formatDate(quotation.issue_date)}</span>
                  </div>
                )}
                {!quotation.issue_date && (
                  <div>
                    <span className="text-muted-foreground">Date: </span>
                    <span className="font-medium">{formatDate(quotation.created_at)}</span>
                  </div>
                )}
                <div className="mt-2">
                  <Badge className={getStatusColor(quotation.status)}>
                    {quotation.status.toUpperCase()}
                  </Badge>
                </div>
              </div>
            </div>
          </div>

          {/* Client Information */}
          {client && (
            <div className="mb-8 grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h3 className="font-semibold mb-2 text-sm text-muted-foreground">BILL TO:</h3>
                <div className="space-y-1">
                  <p className="font-semibold">
                    {client.company_name || client.name}
                  </p>
                  {client.contact_person && (
                    <p className="text-sm">Attn: {client.contact_person}</p>
                  )}
                  {(client.billing_address || client.address) && (
                    <p className="text-sm text-muted-foreground">
                      {client.billing_address || client.address}
                      {client.billing_city && `, ${client.billing_city}`}
                      {client.billing_state && `, ${client.billing_state}`}
                      {client.billing_postal_code && ` ${client.billing_postal_code}`}
                      {client.billing_country && `, ${client.billing_country}`}
                    </p>
                  )}
                  {client.contact_email && (
                    <p className="text-sm text-muted-foreground">
                      <MailIcon className="h-3 w-3 inline mr-1" />
                      {client.contact_email}
                    </p>
                  )}
                  {client.contact_phone && (
                    <p className="text-sm text-muted-foreground">
                      <Phone className="h-3 w-3 inline mr-1" />
                      {client.contact_phone}
                    </p>
                  )}
                  {client.tax_id && (
                    <p className="text-sm text-muted-foreground">
                      Tax ID: {client.tax_id}
                    </p>
                  )}
                </div>
              </div>
              <div>
                <h3 className="font-semibold mb-2 text-sm text-muted-foreground">QUOTATION DETAILS:</h3>
                <div className="space-y-2 text-sm">
                  <div>
                    <span className="text-muted-foreground">Title: </span>
                    <span className="font-medium">{quotation.title}</span>
                  </div>
                  {quotation.issue_date && (
                    <div>
                      <span className="text-muted-foreground">Issue Date: </span>
                      <span className="font-medium">{formatDate(quotation.issue_date)}</span>
                    </div>
                  )}
                  {quotation.expiry_date && (
                    <div>
                      <span className="text-muted-foreground">Expiry Date: </span>
                      <span className="font-medium">{formatDate(quotation.expiry_date)}</span>
                    </div>
                  )}
                  {quotation.valid_until && (
                    <div>
                      <span className="text-muted-foreground">Valid Until: </span>
                      <span className="font-medium">{formatDate(quotation.valid_until)}</span>
                    </div>
                  )}
                  {quotation.description && (
                    <div className="mt-2 pt-2 border-t">
                      <p className="text-muted-foreground whitespace-pre-line">{quotation.description}</p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* Line Items Table */}
          <div className="mb-6 overflow-x-auto">
            <table className="w-full border-collapse min-w-[800px]">
              <thead>
                <tr className="bg-muted border-b-2 border-border">
                  <th className="border border-border p-4 text-left font-semibold text-sm">#</th>
                  <th className="border border-border p-4 text-left font-semibold text-sm w-[25%]">Item Name</th>
                  <th className="border border-border p-4 text-left font-semibold text-sm w-[20%]">Description</th>
                  <th className="border border-border p-4 text-center font-semibold text-sm w-[8%]">Qty</th>
                  <th className="border border-border p-4 text-right font-semibold text-sm w-[12%]">Unit Price</th>
                  <th className="border border-border p-4 text-center font-semibold text-sm w-[10%]">Disc. %</th>
                  <th className="border border-border p-4 text-right font-semibold text-sm w-[15%]">Line Total</th>
                </tr>
              </thead>
              <tbody>
                {lineItems.length > 0 && lineItems.filter(item => item.item_name && item.item_name.trim()).length > 0 ? (
                  lineItems
                    .filter(item => item.item_name && item.item_name.trim())
                    .map((item, index) => {
                      const lineTotal = item.line_total || calculateLineTotal(item);
                      return (
                        <tr key={item.id} className={index % 2 === 0 ? 'bg-white' : 'bg-muted/20 hover:bg-muted/40 transition-colors'}>
                          <td className="border border-border p-3 text-center text-muted-foreground font-medium">{index + 1}</td>
                          <td className="border border-border p-3 font-medium">{item.item_name}</td>
                          <td className="border border-border p-3 text-sm text-muted-foreground">
                            {item.description || <span className="text-muted-foreground/50">-</span>}
                          </td>
                          <td className="border border-border p-3 text-center">{Number(item.quantity) || 0}</td>
                          <td className="border border-border p-3 text-right font-medium">{formatCurrency(Number(item.unit_price) || 0)}</td>
                          <td className="border border-border p-3 text-center">
                            {item.discount_percentage && Number(item.discount_percentage) > 0 ? (
                              <span className="text-orange-600 font-medium">{Number(item.discount_percentage).toFixed(1)}%</span>
                            ) : (
                              <span className="text-muted-foreground/50">-</span>
                            )}
                          </td>
                          <td className="border border-border p-3 text-right font-semibold text-base">
                            {formatCurrency(lineTotal)}
                          </td>
                        </tr>
                      );
                    })
                ) : (
                  <tr>
                    <td colSpan={7} className="border border-border p-8 text-center text-muted-foreground">
                      <div className="flex flex-col items-center gap-2">
                        <FileText className="h-8 w-8 text-muted-foreground/50" />
                        <p>No line items found</p>
                      </div>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>

          {/* Totals */}
          <div className="flex justify-end mb-6">
            <div className="w-full max-w-md border border-border rounded-lg overflow-hidden">
              <table className="w-full">
                <tbody>
                  <tr className="bg-muted/30">
                    <td className="p-3 text-right text-muted-foreground font-medium">Subtotal:</td>
                    <td className="p-3 text-right font-semibold">{formatCurrency(Number(quotation.subtotal) || 0)}</td>
                  </tr>
                  {quotation.discount && Number(quotation.discount) > 0 && (
                    <tr>
                      <td className="p-3 text-right text-muted-foreground">
                        <span className="text-red-600">Discount:</span>
                      </td>
                      <td className="p-3 text-right font-semibold text-red-600">
                        -{formatCurrency(Number(quotation.discount))}
                      </td>
                    </tr>
                  )}
                  <tr>
                    <td className="p-3 text-right text-muted-foreground">
                      Tax ({Number(quotation.tax_rate) || 0}%):
                    </td>
                    <td className="p-3 text-right font-semibold">{formatCurrency(Number(quotation.tax_amount) || 0)}</td>
                  </tr>
                  <tr className="border-t-2 border-foreground bg-muted/50">
                    <td className="p-4 text-right font-bold text-lg">Total Amount:</td>
                    <td className="p-4 text-right font-bold text-xl text-primary">
                      {formatCurrency(Number(quotation.total_amount) || 0)}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>

          {/* Terms & Conditions */}
          {(quotation.terms_conditions || quotation.terms_and_conditions) && (
            <div className="mb-6 p-5 bg-muted/50 rounded-lg border border-border">
              <h3 className="font-semibold mb-3 text-base flex items-center gap-2">
                <FileText className="h-4 w-4" />
                Terms & Conditions
              </h3>
              <div className="text-sm whitespace-pre-line text-foreground leading-relaxed">
                {quotation.terms_conditions || quotation.terms_and_conditions}
              </div>
            </div>
          )}

          {/* Notes */}
          {quotation.notes && (
            <div className="mb-6 p-5 bg-blue-50 dark:bg-blue-950/20 rounded-lg border border-blue-200 dark:border-blue-800">
              <h3 className="font-semibold mb-3 text-blue-900 dark:text-blue-100 flex items-center gap-2">
                <FileText className="h-4 w-4" />
                Internal Notes
              </h3>
              <p className="text-sm text-blue-800 dark:text-blue-200 whitespace-pre-line leading-relaxed">
                {quotation.notes}
              </p>
            </div>
          )}

          {/* Footer */}
          <div className="mt-10 pt-6 border-t text-center space-y-2">
            <p className="text-base font-semibold text-foreground">Thank you for your business!</p>
            <div className="text-sm text-muted-foreground space-y-1">
              {quotation.valid_until && (
                <p>
                  This quotation is valid until <span className="font-medium text-foreground">{formatDate(quotation.valid_until)}</span>
                </p>
              )}
              {(quotation.expiry_date && quotation.expiry_date !== quotation.valid_until) && (
                <p>
                  Expiry Date: <span className="font-medium text-foreground">{formatDate(quotation.expiry_date)}</span>
                </p>
              )}
              <p>
                Generated on {formatDate(quotation.created_at)}
                {quotation.updated_at !== quotation.created_at && (
                  <span> • Last updated: {formatDate(quotation.updated_at)}</span>
                )}
              </p>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
    </>
  );
};

export default QuotationPreviewDialog;

import React, { useState, useCallback } from 'react';
import { Upload, X, FileText, Image, File, AlertCircle } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { db } from '@/lib/database';
import { useToast } from '@/hooks/use-toast';
import { useAsyncOperation } from '@/hooks/useAsyncOperation';

interface ReceiptFile {
  id?: string;
  file: File;
  preview?: string;
  uploaded?: boolean;
  uploadProgress?: number;
  error?: string;
}

interface ReceiptUploadProps {
  reimbursementId: string;
  existingReceipts?: unknown[];
  onUploadComplete?: (files: unknown[]) => void;
  maxFiles?: number;
  maxFileSize?: number; // in MB
}

export const ReceiptUpload: React.FC<ReceiptUploadProps> = ({
  reimbursementId,
  existingReceipts = [],
  onUploadComplete,
  maxFiles = 5,
  maxFileSize = 10
}) => {
  const [files, setFiles] = useState<ReceiptFile[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const { toast } = useToast();

  const { execute: uploadFile, loading: uploading } = useAsyncOperation({
    onError: (error) => toast({ 
      variant: 'destructive', 
      title: 'Upload failed', 
      description: error.message 
    })
  });

  const validateFile = (file: File): string | null => {
    // Check file size
    if (file.size > maxFileSize * 1024 * 1024) {
      return `File size must be less than ${maxFileSize}MB`;
    }

    // Check file type
    const allowedTypes = [
      'image/jpeg', 'image/png', 'image/gif', 'image/webp',
      'application/pdf',
      'text/plain',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document'
    ];
    
    if (!allowedTypes.includes(file.type)) {
      return 'File type not supported. Please upload images, PDFs, or documents.';
    }

    return null;
  };

  const processFiles = useCallback((fileList: FileList) => {
    const newFiles: ReceiptFile[] = [];
    
    for (let i = 0; i < fileList.length; i++) {
      const file = fileList[i];
      const error = validateFile(file);
      
      if (error) {
        toast({ 
          variant: 'destructive', 
          title: 'Invalid file', 
          description: `${file.name}: ${error}` 
        });
        continue;
      }

      if (files.length + newFiles.length >= maxFiles) {
        toast({ 
          variant: 'destructive', 
          title: 'Too many files', 
          description: `Maximum ${maxFiles} files allowed` 
        });
        break;
      }

      const receiptFile: ReceiptFile = {
        file,
        uploadProgress: 0,
        uploaded: false
      };

      // Create preview for images
      if (file.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (e) => {
          receiptFile.preview = e.target?.result as string;
          setFiles(prev => [...prev]);
        };
        reader.readAsDataURL(file);
      }

      newFiles.push(receiptFile);
    }

    if (newFiles.length > 0) {
      setFiles(prev => [...prev, ...newFiles]);
    }
  }, [files.length, maxFiles, toast]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragActive(false);
    
    if (e.dataTransfer.files) {
      processFiles(e.dataTransfer.files);
    }
  }, [processFiles]);

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      processFiles(e.target.files);
    }
  };

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const uploadFiles = async () => {
    const uploadPromises = files
      .filter(f => !f.uploaded)
      .map(async (fileItem, index) => {
        return uploadFile(async () => {
          // Update progress
          setFiles(prev => prev.map(f => 
            f === fileItem ? { ...f, uploadProgress: 10 } : f
          ));

          const fileExt = fileItem.file.name.split('.').pop();
          const fileName = `${reimbursementId}_${Date.now()}_${index}.${fileExt}`;
          const filePath = `receipts/${fileName}`;

          // Upload to file storage
          const { data: uploadData, error: uploadError } = await db.storage
            .from('receipts')
            .upload(filePath, fileItem.file);

          if (uploadError) throw uploadError;

          // Simulate progress for UI feedback
          setFiles(prev => prev.map(f => 
            f === fileItem ? { ...f, uploadProgress: 100 } : f
          ));

          // Save attachment record
          const { data: attachmentData, error: attachmentError } = await db
            .from('reimbursement_attachments')
            .insert({
              reimbursement_id: reimbursementId,
              file_name: fileItem.file.name,
              file_path: filePath,
              file_type: fileItem.file.type,
              file_size: fileItem.file.size
            })
            .select()
            .single();

          if (attachmentError) throw attachmentError;

          // Mark as uploaded
          setFiles(prev => prev.map(f => 
            f === fileItem ? { 
              ...f, 
              uploaded: true, 
              uploadProgress: 100,
              id: attachmentData.id 
            } : f
          ));

          return attachmentData;
        });
      });

    try {
      const results = await Promise.all(uploadPromises);
      toast({ 
        title: 'Upload complete', 
        description: `${results.length} file(s) uploaded successfully` 
      });
      onUploadComplete?.(results);
    } catch (error) {
      console.error('Upload error:', error);
    }
  };

  const getFileIcon = (fileType: string) => {
    if (fileType.startsWith('image/')) return <Image className="w-6 h-6" />;
    if (fileType === 'application/pdf') return <FileText className="w-6 h-6" />;
    return <File className="w-6 h-6" />;
  };

  const hasUnuploadedFiles = files.some(f => !f.uploaded);
  const totalFiles = files.length + existingReceipts.length;

  return (
    <Card>
      <CardHeader>
        <CardTitle>Receipt Upload</CardTitle>
        <CardDescription>
          Upload receipts and supporting documents ({totalFiles}/{maxFiles} files)
        </CardDescription>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {totalFiles < maxFiles && (
          <div
            className={`border-2 border-dashed rounded-lg p-6 text-center transition-colors ${
              dragActive 
                ? 'border-primary bg-primary/5' 
                : 'border-muted-foreground/25 hover:border-muted-foreground/50'
            }`}
            onDrop={handleDrop}
            onDragOver={(e) => e.preventDefault()}
            onDragEnter={() => setDragActive(true)}
            onDragLeave={() => setDragActive(false)}
          >
            <Upload className="w-8 h-8 mx-auto mb-2 text-muted-foreground" />
            <p className="text-sm text-muted-foreground mb-2">
              Drag and drop files here, or click to select
            </p>
            <input
              type="file"
              multiple
              accept="image/*,.pdf,.doc,.docx,.txt"
              onChange={handleFileInput}
              className="hidden"
              id="file-upload"
            />
            <label htmlFor="file-upload">
              <Button variant="outline" size="sm" asChild>
                <span>Choose Files</span>
              </Button>
            </label>
            <p className="text-xs text-muted-foreground mt-2">
              Images, PDFs, Documents (max {maxFileSize}MB each)
            </p>
          </div>
        )}

        {totalFiles >= maxFiles && (
          <Alert>
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              Maximum number of files ({maxFiles}) reached. Remove files to upload more.
            </AlertDescription>
          </Alert>
        )}

        {/* File List */}
        {files.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-sm font-medium">New Files</h4>
            {files.map((fileItem, index) => (
              <div key={index} className="flex items-center space-x-3 p-3 border rounded-lg">
                <div className="flex-shrink-0 text-muted-foreground">
                  {getFileIcon(fileItem.file.type)}
                </div>
                
                {fileItem.preview && (
                  <img 
                    src={fileItem.preview} 
                    alt="Preview" 
                    className="w-12 h-12 object-cover rounded border"
                  />
                )}
                
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium truncate">{fileItem.file.name}</p>
                  <p className="text-xs text-muted-foreground">
                    {(fileItem.file.size / 1024 / 1024).toFixed(2)} MB
                  </p>
                  
                  {fileItem.uploadProgress !== undefined && !fileItem.uploaded && (
                    <div className="mt-1">
                      <Progress value={fileItem.uploadProgress} className="h-1" />
                    </div>
                  )}
                  
                  {fileItem.error && (
                    <p className="text-xs text-red-600 mt-1">{fileItem.error}</p>
                  )}
                </div>
                
                <div className="flex items-center space-x-2">
                  {fileItem.uploaded && (
                    <Badge variant="secondary" className="bg-green-100 text-green-800">
                      Uploaded
                    </Badge>
                  )}
                  
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeFile(index)}
                    disabled={uploading}
                  >
                    <X className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Existing Files */}
        {existingReceipts.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-sm font-medium">Existing Files</h4>
            {existingReceipts.map((receipt) => (
              <div key={receipt.id} className="flex items-center space-x-3 p-3 border rounded-lg">
                <div className="flex-shrink-0 text-muted-foreground">
                  {getFileIcon(receipt.file_type)}
                </div>
                
                <div className="flex-1">
                  <p className="text-sm font-medium">{receipt.file_name}</p>
                  <p className="text-xs text-muted-foreground">
                    {(receipt.file_size / 1024 / 1024).toFixed(2)} MB
                  </p>
                </div>
                
                <Badge variant="secondary" className="bg-gray-100 text-gray-800">
                  Uploaded
                </Badge>
              </div>
            ))}
          </div>
        )}

        {/* Upload Button */}
        {hasUnuploadedFiles && (
          <Button 
            onClick={uploadFiles} 
            disabled={uploading}
            className="w-full"
          >
            {uploading ? 'Uploading...' : `Upload ${files.filter(f => !f.uploaded).length} File(s)`}
          </Button>
        )}
      </CardContent>
    </Card>
  );
};

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { db } from '@/lib/database';
import { Download, Eye, X, FileText, Image, File, Loader2 } from "lucide-react";
import { format } from "date-fns";

interface Receipt {
  id: string;
  vendor: string;
  category: string;
  amount: number;
  date: string;
  status: string;
  description: string;
  receiptUrl: string | null;
  request_id?: string;
  business_purpose?: string;
}

interface ReceiptViewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  receipt: Receipt | null;
}

interface Attachment {
  id: string;
  file_name: string;
  file_path: string;
  file_type: string;
  file_size: number;
  uploaded_at: string;
}

export const ReceiptViewDialog: React.FC<ReceiptViewDialogProps> = ({
  open,
  onOpenChange,
  receipt,
}) => {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [viewingImage, setViewingImage] = useState<string | null>(null);

  useEffect(() => {
    if (open && receipt?.request_id) {
      fetchAttachments();
    }
  }, [open, receipt]);

  const fetchAttachments = async () => {
    if (!receipt?.request_id) return;

    try {
      setLoading(true);
      const { data, error } = await db
        .from('reimbursement_attachments')
        .select('*')
        .eq('reimbursement_id', receipt.request_id)
        .order('uploaded_at', { ascending: false });

      if (error) throw error;
      setAttachments((data as unknown) || []);
    } catch (error: unknown) {
      console.error("Error fetching attachments:", error);
      toast({
        title: "Error",
        description: "Failed to load attachments",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleDownload = async (attachment: Attachment) => {
    try {
      const { data, error } = await db.storage
        .from('receipts')
        .download(attachment.file_path);

      if (error) throw error;

      // Create blob URL and trigger download
      const blob = data as Blob;
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = attachment.file_name;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);

      toast({
        title: "Success",
        description: "File downloaded successfully",
      });
    } catch (error: unknown) {
      console.error("Error downloading file:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to download file",
        variant: "destructive",
      });
    }
  };

  const handleViewImage = async (attachment: Attachment) => {
    try {
      const { data, error } = await db.storage
        .from('receipts')
        .download(attachment.file_path);

      if (error) throw error;

      const blob = data as Blob;
      const url = window.URL.createObjectURL(blob);
      setViewingImage(url);
    } catch (error: unknown) {
      console.error("Error loading image:", error);
      toast({
        title: "Error",
        description: "Failed to load image",
        variant: "destructive",
      });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'approved': 
      case 'paid': return 'default';
      case 'submitted': 
      case 'manager_review':
      case 'finance_review': return 'secondary';
      case 'rejected': return 'destructive';
      case 'draft': return 'outline';
      default: return 'secondary';
    }
  };

  const getFileIcon = (fileType: string) => {
    if (fileType.startsWith('image/')) return <Image className="w-5 h-5" />;
    if (fileType === 'application/pdf') return <FileText className="w-5 h-5" />;
    return <File className="w-5 h-5" />;
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(2) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(2) + ' MB';
  };

  if (!receipt) return null;

  return (
    <>
      <Dialog open={open} onOpenChange={onOpenChange}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Receipt Details</DialogTitle>
            <DialogDescription>View receipt information and attachments</DialogDescription>
          </DialogHeader>
          
          <div className="space-y-6">
            {/* Receipt Information */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Receipt ID</p>
                <p className="text-sm font-semibold">{receipt.id}</p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Status</p>
                <Badge variant={getStatusColor(receipt.status)} className="mt-1">
                  {receipt.status}
                </Badge>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Vendor</p>
                <p className="text-sm">{receipt.vendor}</p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Category</p>
                <p className="text-sm">{receipt.category}</p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Amount</p>
                <p className="text-lg font-bold">₹{receipt.amount.toFixed(2)}</p>
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Date</p>
                <p className="text-sm">{format(new Date(receipt.date), "PPP")}</p>
              </div>
            </div>

            {/* Description */}
            <div>
              <p className="text-sm font-medium text-muted-foreground mb-2">Description</p>
              <p className="text-sm">{receipt.description || "No description"}</p>
            </div>

            {/* Business Purpose */}
            {receipt.business_purpose && (
              <div>
                <p className="text-sm font-medium text-muted-foreground mb-2">Business Purpose</p>
                <p className="text-sm">{receipt.business_purpose}</p>
              </div>
            )}

            {/* Attachments */}
            <div>
              <p className="text-sm font-medium text-muted-foreground mb-3">Attachments</p>
              {loading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-6 w-6 animate-spin" />
                </div>
              ) : attachments.length === 0 ? (
                <p className="text-sm text-muted-foreground">No attachments found</p>
              ) : (
                <div className="space-y-2">
                  {attachments.map((attachment) => (
                    <div
                      key={attachment.id}
                      className="flex items-center justify-between p-3 border rounded-lg hover:bg-muted/50 transition-colors"
                    >
                      <div className="flex items-center gap-3 flex-1 min-w-0">
                        <div className="text-muted-foreground">
                          {getFileIcon(attachment.file_type)}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm font-medium truncate">{attachment.file_name}</p>
                          <p className="text-xs text-muted-foreground">
                            {formatFileSize(attachment.file_size)} • {format(new Date(attachment.uploaded_at), "PPp")}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        {attachment.file_type.startsWith('image/') && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleViewImage(attachment)}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                        )}
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleDownload(attachment)}
                        >
                          <Download className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Image Viewer Modal */}
      {viewingImage && (
        <Dialog open={!!viewingImage} onOpenChange={() => setViewingImage(null)}>
          <DialogContent className="max-w-4xl max-h-[90vh] overflow-hidden p-0">
            <div className="relative">
              <Button
                variant="ghost"
                size="icon"
                className="absolute right-2 top-2 z-10 bg-background/80 hover:bg-background"
                onClick={() => setViewingImage(null)}
              >
                <X className="h-4 w-4" />
              </Button>
              <img
                src={viewingImage}
                alt="Receipt"
                className="w-full h-auto max-h-[85vh] object-contain"
              />
            </div>
          </DialogContent>
        </Dialog>
      )}
    </>
  );
};

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { db } from '@/lib/database';
import { useAuth } from "@/hooks/useAuth";
import { CheckCircle, XCircle, Download, Eye, DollarSign } from "lucide-react";
import { format } from "date-fns";
import { PaymentDialog } from "./PaymentDialog";

interface ReimbursementRequest {
  id: string;
  employee_id: string;
  amount: number;
  currency: string;
  expense_date: string;
  description: string;
  business_purpose: string;
  status: string;
  submitted_at: string;
  expense_categories: {
    name: string;
  };
  profiles?: {
    full_name: string;
  };
}

interface Attachment {
  id: string;
  file_name: string;
  file_path: string;
  file_type: string;
  file_size: number;
}

interface ReimbursementReviewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  request: ReimbursementRequest | null;
  onSuccess?: () => void;
}

export const ReimbursementReviewDialog: React.FC<ReimbursementReviewDialogProps> = ({
  open,
  onOpenChange,
  request,
  onSuccess,
}) => {
  const { user, userRole } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [rejectionReason, setRejectionReason] = useState("");
  const [showPaymentDialog, setShowPaymentDialog] = useState(false);

  const isFinanceUser = userRole === 'manager' || userRole === 'agency_admin' || userRole === 'super_admin';

  useEffect(() => {
    if (open && request) {
      fetchAttachments();
    }
  }, [open, request]);

  const fetchAttachments = async () => {
    if (!request) return;

    try {
      const { data, error } = await db
        .from("reimbursement_attachments")
        .select("*")
        .eq("reimbursement_id", request.id);

      if (error) throw error;
      setAttachments((data as unknown) || []);
    } catch (error) {
      console.error("Error fetching attachments:", error);
    }
  };

  const handleApprove = async () => {
    if (!request || !user) return;

    setLoading(true);
    try {
      const { error } = await db
        .from("reimbursement_requests")
        .update({
          status: "approved",
          reviewed_by: user.id,
          reviewed_at: new Date().toISOString(),
        })
        .eq("id", request.id);

      if (error) throw error;

      toast({
        title: "Success",
        description: "Reimbursement request approved",
      });

      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error("Error approving request:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to approve reimbursement request",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async () => {
    if (!request || !user || !rejectionReason.trim()) {
      toast({
        title: "Error",
        description: "Please provide a reason for rejection",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    try {
      const { error } = await db
        .from("reimbursement_requests")
        .update({
          status: "rejected",
          reviewed_by: user.id,
          reviewed_at: new Date().toISOString(),
          rejection_reason: rejectionReason,
        })
        .eq("id", request.id);

      if (error) throw error;

      toast({
        title: "Success",
        description: "Reimbursement request rejected",
      });

      setRejectionReason("");
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error("Error rejecting request:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to reject reimbursement request",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const downloadFile = async (attachment: Attachment) => {
    try {
      const { data, error } = await db.storage
        .from('receipts')
        .download(attachment.file_path);

      if (error) throw error;

      const url = URL.createObjectURL(data);
      const a = document.createElement('a');
      a.href = url;
      a.download = attachment.file_name;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Error downloading file:", error);
      toast({
        title: "Error",
        description: "Failed to download file",
        variant: "destructive",
      });
    }
  };

  const viewFile = async (attachment: Attachment) => {
    try {
      const { data, error } = await db.storage
        .from('receipts')
        .getPublicUrl(attachment.file_path);

      if (error) throw error;

      window.open(data.publicUrl, '_blank');
    } catch (error: unknown) {
      console.error("Error viewing file:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to view file",
        variant: "destructive",
      });
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  if (!request) return null;

  const getStatusColor = (status: string) => {
    switch (status) {
      case "submitted":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300";
      case "approved":
        return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300";
      case "rejected":
        return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300";
      default:
        return "bg-muted text-muted-foreground";
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Review Reimbursement Request</DialogTitle>
        </DialogHeader>
        
        <div className="space-y-6">
          {/* Request Details */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Employee</Label>
              <p className="font-medium">{request.profiles?.full_name || "Unknown Employee"}</p>
            </div>
            
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Status</Label>
              <Badge className={`${getStatusColor(request.status)} mt-1`}>
                {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
              </Badge>
            </div>

            <div>
              <Label className="text-sm font-medium text-muted-foreground">Category</Label>
              <p className="font-medium">{request.expense_categories?.name}</p>
            </div>

            <div>
              <Label className="text-sm font-medium text-muted-foreground">Amount</Label>
              <p className="font-medium text-lg">{request.currency} {Number(request.amount).toFixed(2)}</p>
            </div>

            <div>
              <Label className="text-sm font-medium text-muted-foreground">Expense Date</Label>
              <p className="font-medium">{format(new Date(request.expense_date), "MMM dd, yyyy")}</p>
            </div>

            <div>
              <Label className="text-sm font-medium text-muted-foreground">Submitted</Label>
              <p className="font-medium">{format(new Date(request.submitted_at), "MMM dd, yyyy")}</p>
            </div>
          </div>

          {/* Description */}
          <div>
            <Label className="text-sm font-medium text-muted-foreground">Description</Label>
            <p className="mt-1 p-3 bg-muted rounded-md">{request.description}</p>
          </div>

          {/* Business Purpose */}
          {request.business_purpose && (
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Business Purpose</Label>
              <p className="mt-1 p-3 bg-muted rounded-md">{request.business_purpose}</p>
            </div>
          )}

          {/* Attachments */}
          {attachments.length > 0 && (
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Receipts & Attachments</Label>
              <div className="mt-2 space-y-2">
                {attachments.map((attachment) => (
                  <div key={attachment.id} className="flex items-center justify-between p-3 border rounded-md">
                    <div>
                      <p className="font-medium">{attachment.file_name}</p>
                      <p className="text-sm text-muted-foreground">
                        {attachment.file_type} • {formatFileSize(attachment.file_size)}
                      </p>
                    </div>
                    <div className="flex gap-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => viewFile(attachment)}
                      >
                        <Eye className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => downloadFile(attachment)}
                      >
                        <Download className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Rejection Reason (if rejecting) */}
          {request.status === "submitted" && (
            <div>
              <Label htmlFor="rejection_reason">Rejection Reason (optional for rejection)</Label>
              <Textarea
                id="rejection_reason"
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
                placeholder="Provide a reason if rejecting this request..."
                className="mt-1"
              />
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
          
          {request.status === "submitted" && (
            <>
              <Button
                variant="destructive"
                onClick={handleReject}
                disabled={loading}
                className="flex items-center gap-2"
              >
                <XCircle className="h-4 w-4" />
                {loading ? "Rejecting..." : "Reject"}
              </Button>
              
              <Button
                onClick={handleApprove}
                disabled={loading}
                className="flex items-center gap-2"
              >
                <CheckCircle className="h-4 w-4" />
                {loading ? "Approving..." : "Approve"}
              </Button>
            </>
          )}

          {request.status === "approved" && isFinanceUser && (
            <Button
              onClick={() => setShowPaymentDialog(true)}
              className="flex items-center gap-2"
            >
              <DollarSign className="h-4 w-4" />
              Process Payment
            </Button>
          )}
        </DialogFooter>
      </DialogContent>

      <PaymentDialog
        open={showPaymentDialog}
        onOpenChange={setShowPaymentDialog}
        request={request}
        onSuccess={() => {
          onSuccess?.();
          onOpenChange(false);
        }}
      />
    </Dialog>
  );
};

import React, { useState, useEffect } from 'react';
import { CheckCircle, XCircle, Clock, MessageSquare, Download, Upload, Eye, DollarSign } from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Separator } from '@/components/ui/separator';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Progress } from '@/components/ui/progress';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { db } from '@/lib/database';
import { useToast } from '@/hooks/use-toast';
import { useAsyncOperation } from '@/hooks/useAsyncOperation';
import { LoadingSpinner } from './LoadingSpinner';
import { useAuth } from '@/hooks/useAuth';
import { getAgencyId } from '@/utils/agencyUtils';

interface ReimbursementRequest {
  id: string;
  employee_id: string;
  category_id: string;
  amount: number;
  expense_date: string;
  description: string;
  business_purpose: string;
  status: string;
  mileage_distance?: number;
  mileage_rate?: number;
  mileage_amount?: number;
  receipt_required: boolean;
  policy_violation?: string;
  created_at: string;
  currency: string;
  employee?: {
    full_name: string;
    department: string;
  };
  category?: {
    name: string;
  };
}

interface WorkflowState {
  id: string;
  state: string;
  actor_id: string;
  action_date: string;
  comments?: string;
  actor?: {
    full_name: string;
  };
}

interface ReimbursementWorkflowProps {
  requestId: string;
  onStatusChange?: (newStatus: string) => void;
}

const stateConfig = {
  draft: { color: 'bg-gray-100 text-gray-800', icon: Clock, label: 'Draft' },
  submitted: { color: 'bg-blue-100 text-blue-800', icon: Upload, label: 'Submitted' },
  manager_review: { color: 'bg-yellow-100 text-yellow-800', icon: Eye, label: 'Manager Review' },
  finance_review: { color: 'bg-purple-100 text-purple-800', icon: DollarSign, label: 'Finance Review' },
  approved: { color: 'bg-green-100 text-green-800', icon: CheckCircle, label: 'Approved' },
  rejected: { color: 'bg-red-100 text-red-800', icon: XCircle, label: 'Rejected' },
  paid: { color: 'bg-emerald-100 text-emerald-800', icon: DollarSign, label: 'Paid' }
};

export const ReimbursementWorkflow: React.FC<ReimbursementWorkflowProps> = ({ 
  requestId, 
  onStatusChange 
}) => {
  const { user, profile } = useAuth();
  const [request, setRequest] = useState<ReimbursementRequest | null>(null);
  const [workflowStates, setWorkflowStates] = useState<WorkflowState[]>([]);
  const [isActionDialogOpen, setIsActionDialogOpen] = useState(false);
  const [actionType, setActionType] = useState<'approve' | 'reject' | 'return'>('approve');
  const [comments, setComments] = useState('');
  const { toast } = useToast();

  const { execute: loadRequest, loading: loadingRequest } = useAsyncOperation();
  const { execute: loadWorkflow, loading: loadingWorkflow } = useAsyncOperation();
  const { execute: submitAction, loading: submittingAction } = useAsyncOperation({
    onSuccess: () => {
      toast({ title: 'Action completed successfully' });
      setIsActionDialogOpen(false);
      setComments('');
      loadRequest(fetchRequest);
      loadWorkflow(fetchWorkflow);
    }
  });

  const fetchRequest = async () => {
    // Try with employee_id foreign key first, fall back to user_id if it doesn't exist
    let data, error;
    
    try {
      const result = await db
        .from('reimbursement_requests')
        .select(`
          *,
          employee:profiles!reimbursement_requests_employee_id_fkey(full_name, department),
          category:expense_categories(name)
        `)
        .eq('id', requestId)
        .single();
      data = result.data;
      error = result.error;
    } catch (err: unknown) {
      // If employee_id foreign key doesn't exist, try with user_id
      if (err?.message?.includes('employee_id') || err?.code === '42703') {
        const result = await db
          .from('reimbursement_requests')
          .select(`
            *,
            employee:profiles!reimbursement_requests_user_id_fkey(full_name, department),
            category:expense_categories(name)
          `)
          .eq('id', requestId)
          .single();
        data = result.data;
        error = result.error;
      } else {
        throw err;
      }
    }
    
    // If still error, try without foreign key joins
    if (error) {
      const result = await db
        .from('reimbursement_requests')
        .select('*')
        .eq('id', requestId)
        .single();
      data = result.data;
      error = result.error;
    }

    if (error) throw error;
    setRequest(data as unknown as ReimbursementRequest);
    return data;
  };

  const fetchWorkflow = async () => {
    const { data, error } = await db
      .from('reimbursement_workflow_states')
      .select(`
        *,
        actor:profiles!reimbursement_workflow_states_actor_id_fkey(full_name)
      `)
      .eq('request_id', requestId)
      .order('action_date', { ascending: true });

    if (error) throw error;
    setWorkflowStates((data || []) as unknown as WorkflowState[]);
    return data;
  };

  const handleAction = async () => {
    if (!request) return;

    let nextState = '';
    switch (actionType) {
      case 'approve':
        if (request.status === 'submitted') nextState = 'manager_review';
        else if (request.status === 'manager_review') nextState = 'finance_review';
        else if (request.status === 'finance_review') nextState = 'approved';
        break;
      case 'reject':
        nextState = 'rejected';
        break;
      case 'return':
        nextState = 'submitted';
        break;
    }

    return submitAction(async () => {
      if (!user?.id) throw new Error('User not authenticated');
      
      const agencyId = await getAgencyId(profile, user.id);
      if (!agencyId) throw new Error('Agency ID not found');
      
      // Create workflow state entry
      const { error: workflowError } = await db
        .from('reimbursement_workflow_states')
        .insert({
          request_id: requestId,
          state: nextState,
          actor_id: user.id,
          comments: comments || null
        });

      if (workflowError) throw workflowError;

      // Update request status
      const { error: updateError } = await db
        .from('reimbursement_requests')
        .update({ status: nextState })
        .eq('id', requestId);

      if (updateError) throw updateError;

      // Create notification for employee
      if (nextState === 'approved' || nextState === 'rejected') {
        await db.rpc('create_notification', {
          p_user_id: request.employee_id,
          p_type: 'in_app',
          p_category: 'update',
          p_title: `Reimbursement Request ${nextState.charAt(0).toUpperCase() + nextState.slice(1)}`,
          p_message: `Your reimbursement request for $${request.amount} has been ${nextState}.`,
          p_action_url: '/reimbursements'
        });
      }

      onStatusChange?.(nextState);
    });
  };

  const calculateProgress = () => {
    if (!request) return 0;
    
    const stateOrder = ['draft', 'submitted', 'manager_review', 'finance_review', 'approved', 'paid'];
    const currentIndex = stateOrder.indexOf(request.status);
    
    if (request.status === 'rejected') return 100; // Show as complete but red
    return ((currentIndex + 1) / stateOrder.length) * 100;
  };

  const canTakeAction = () => {
    if (!request) return false;
    
    // This would need to check user roles and permissions
    // For now, returning true for demonstration
    return ['submitted', 'manager_review', 'finance_review'].includes(request.status);
  };

  useEffect(() => {
    loadRequest(fetchRequest);
    loadWorkflow(fetchWorkflow);
  }, [requestId]);

  if (loadingRequest) {
    return (
      <Card>
        <CardContent className="p-6">
          <LoadingSpinner size="md" text="Loading request details..." />
        </CardContent>
      </Card>
    );
  }

  if (!request) {
    return (
      <Card>
        <CardContent className="p-6">
          <p className="text-muted-foreground">Request not found</p>
        </CardContent>
      </Card>
    );
  }

  const StateIcon = stateConfig[request.status as keyof typeof stateConfig]?.icon || Clock;

  return (
    <div className="space-y-6">
      {/* Request Overview */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center space-x-2">
                <StateIcon className="w-5 h-5" />
                <span>Reimbursement Request</span>
              </CardTitle>
              <CardDescription>
                {request.employee?.full_name} • {request.category?.name}
              </CardDescription>
            </div>
            <Badge className={stateConfig[request.status as keyof typeof stateConfig]?.color}>
              {stateConfig[request.status as keyof typeof stateConfig]?.label}
            </Badge>
          </div>
        </CardHeader>
        
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Amount</Label>
              <p className="text-lg font-semibold">${request.amount}</p>
            </div>
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Date</Label>
              <p>{new Date(request.expense_date).toLocaleDateString()}</p>
            </div>
            {request.mileage_distance && (
              <div>
                <Label className="text-sm font-medium text-muted-foreground">Mileage</Label>
                <p>{request.mileage_distance} miles @ ${request.mileage_rate}/mile</p>
              </div>
            )}
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Receipt Required</Label>
              <p>{request.receipt_required ? 'Yes' : 'No'}</p>
            </div>
          </div>

          <div>
            <Label className="text-sm font-medium text-muted-foreground">Description</Label>
            <p className="mt-1">{request.description}</p>
          </div>

          {request.business_purpose && (
            <div>
              <Label className="text-sm font-medium text-muted-foreground">Business Purpose</Label>
              <p className="mt-1">{request.business_purpose}</p>
            </div>
          )}

          {request.policy_violation && (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-md">
              <div className="flex items-center space-x-2">
                <XCircle className="w-4 h-4 text-yellow-600" />
                <Label className="text-sm font-medium text-yellow-800">Policy Violation</Label>
              </div>
              <p className="text-sm text-yellow-700 mt-1">{request.policy_violation}</p>
            </div>
          )}

          {/* Progress Bar */}
          <div className="space-y-2">
            <div className="flex justify-between text-sm">
              <span>Request Progress</span>
              <span>{Math.round(calculateProgress())}%</span>
            </div>
            <Progress 
              value={calculateProgress()} 
              className={`h-2 ${request.status === 'rejected' ? 'bg-red-100' : ''}`}
            />
          </div>
        </CardContent>
      </Card>

      {/* Workflow History */}
      <Card>
        <CardHeader>
          <CardTitle>Workflow History</CardTitle>
          <CardDescription>Timeline of actions taken on this request</CardDescription>
        </CardHeader>
        
        <CardContent>
          {loadingWorkflow ? (
            <LoadingSpinner size="sm" text="Loading workflow..." />
          ) : (
            <ScrollArea className="h-64">
              <div className="space-y-4">
                {workflowStates.map((state, index) => {
                  const StateIcon = stateConfig[state.state as keyof typeof stateConfig]?.icon || Clock;
                  const isLast = index === workflowStates.length - 1;
                  
                  return (
                    <div key={state.id} className="flex items-start space-x-3">
                      <div className="flex flex-col items-center">
                        <div className={`p-2 rounded-full ${stateConfig[state.state as keyof typeof stateConfig]?.color}`}>
                          <StateIcon className="w-4 h-4" />
                        </div>
                        {!isLast && <div className="w-px h-6 bg-border mt-2" />}
                      </div>
                      
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between">
                          <h4 className="text-sm font-medium">
                            {stateConfig[state.state as keyof typeof stateConfig]?.label}
                          </h4>
                          <span className="text-xs text-muted-foreground">
                            {new Date(state.action_date).toLocaleString()}
                          </span>
                        </div>
                        <p className="text-sm text-muted-foreground">
                          {state.actor?.full_name || 'System'}
                        </p>
                        {state.comments && (
                          <p className="text-sm mt-1 p-2 bg-muted rounded-md">
                            {state.comments}
                          </p>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </ScrollArea>
          )}
        </CardContent>
      </Card>

      {/* Actions */}
      {canTakeAction() && (
        <Card>
          <CardHeader>
            <CardTitle>Take Action</CardTitle>
            <CardDescription>Review and approve or reject this request</CardDescription>
          </CardHeader>
          
          <CardContent>
            <div className="flex space-x-2">
              <Dialog open={isActionDialogOpen} onOpenChange={setIsActionDialogOpen}>
                <DialogTrigger asChild>
                  <Button 
                    variant="default" 
                    onClick={() => setActionType('approve')}
                  >
                    <CheckCircle className="w-4 h-4 mr-2" />
                    Approve
                  </Button>
                </DialogTrigger>
                
                <DialogTrigger asChild>
                  <Button 
                    variant="destructive" 
                    onClick={() => setActionType('reject')}
                  >
                    <XCircle className="w-4 h-4 mr-2" />
                    Reject
                  </Button>
                </DialogTrigger>

                <DialogContent>
                  <DialogHeader>
                    <DialogTitle>
                      {actionType === 'approve' ? 'Approve' : 'Reject'} Request
                    </DialogTitle>
                    <DialogDescription>
                      Add comments about your decision (optional)
                    </DialogDescription>
                  </DialogHeader>
                  
                  <div className="space-y-4">
                    <Textarea
                      placeholder="Enter your comments..."
                      value={comments}
                      onChange={(e) => setComments(e.target.value)}
                    />
                    
                    <div className="flex justify-end space-x-2">
                      <Button 
                        variant="outline" 
                        onClick={() => setIsActionDialogOpen(false)}
                      >
                        Cancel
                      </Button>
                      <Button 
                        onClick={handleAction}
                        disabled={submittingAction}
                        variant={actionType === 'approve' ? 'default' : 'destructive'}
                      >
                        {submittingAction && <LoadingSpinner size="sm" className="mr-2" />}
                        {actionType === 'approve' ? 'Approve' : 'Reject'}
                      </Button>
                    </div>
                  </div>
                </DialogContent>
              </Dialog>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { 
  Lightbulb, 
  TrendingUp, 
  AlertTriangle, 
  Users, 
  DollarSign, 
  Calendar, 
  Target,
  Zap,
  Brain,
  BarChart3
} from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { getAgencyId } from "@/utils/agencyUtils";
import { selectRecords, rawQuery } from "@/services/api/core";

interface Insight {
  id: string;
  title: string;
  description: string;
  type: 'opportunity' | 'warning' | 'trend' | 'recommendation';
  impact: 'low' | 'medium' | 'high';
  confidence: number;
  actionable: boolean;
  data: unknown;
  created_at: string;
}

export function AIInsights() {
  const { user, profile } = useAuth();
  const [insights, setInsights] = useState<Insight[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchInsights();
  }, [user?.id, profile?.agency_id]);

  const fetchInsights = async () => {
    try {
      setLoading(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        setInsights([]);
        return;
      }

      // Fetch real data to generate insights
      const [projects, invoices, clients, tasks] = await Promise.all([
        selectRecords('projects', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 500
        }).catch(() => []),
        selectRecords('invoices', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 500
        }).catch(() => []),
        selectRecords('clients', {
          where: { agency_id: agencyId, status: 'active' },
          orderBy: 'created_at DESC',
          limit: 500
        }).catch(() => []),
        selectRecords('tasks', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 500
        }).catch(() => [])
      ]);

      const generatedInsights: Insight[] = [];

      // Budget overrun warning
      const overBudgetProjects = (projects || []).filter((p: unknown) => {
        if (!p.budget || !p.actual_cost) return false;
        return p.actual_cost > p.budget;
      });
      if (overBudgetProjects.length > 0) {
        generatedInsights.push({
          id: 'insight-budget-overrun',
          title: 'Budget Overrun Detected',
          description: `${overBudgetProjects.length} project(s) have exceeded their allocated budget. Immediate review recommended.`,
          type: 'warning',
          impact: 'high',
          confidence: 95,
          actionable: true,
          data: { project_count: overBudgetProjects.length },
          created_at: new Date().toISOString()
        });
      }

      // Revenue opportunity from pending invoices
      const pendingInvoices = (invoices || []).filter((inv: unknown) => 
        inv.status === 'sent' || inv.status === 'pending'
      );
      const pendingAmount = pendingInvoices.reduce((sum: number, inv: unknown) => 
        sum + (Number(inv.total_amount) || 0), 0
      );
      if (pendingAmount > 0) {
        generatedInsights.push({
          id: 'insight-pending-revenue',
          title: 'Revenue Collection Opportunity',
          description: `$${pendingAmount.toLocaleString()} in pending invoices. Implementing automated follow-ups could improve collection rates.`,
          type: 'opportunity',
          impact: 'high',
          confidence: 85,
          actionable: true,
          data: { pending_amount: pendingAmount, invoice_count: pendingInvoices.length },
          created_at: new Date().toISOString()
        });
      }

      // Project completion trend
      const completedProjects = (projects || []).filter((p: unknown) => p.status === 'completed').length;
      const totalProjects = projects.length || 1;
      const completionRate = (completedProjects / totalProjects) * 100;
      if (completionRate < 70 && totalProjects > 5) {
        generatedInsights.push({
          id: 'insight-completion-trend',
          title: 'Project Completion Rate Below Target',
          description: `Current completion rate is ${Math.round(completionRate)}%. Consider reviewing project management processes.`,
          type: 'trend',
          impact: 'medium',
          confidence: 88,
          actionable: true,
          data: { completion_rate: Math.round(completionRate), total_projects: totalProjects },
          created_at: new Date().toISOString()
        });
      }

      // Client engagement opportunity
      const clientsWithoutRecentProjects = (clients || []).filter((c: unknown) => {
        const clientProjects = (projects || []).filter((p: unknown) => p.client_id === c.id);
        if (clientProjects.length === 0) return true;
        const lastProject = clientProjects.sort((a: unknown, b: unknown) => 
          new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
        )[0];
        const daysSinceLastProject = (Date.now() - new Date(lastProject.created_at).getTime()) / (1000 * 60 * 60 * 24);
        return daysSinceLastProject > 90;
      });
      if (clientsWithoutRecentProjects.length > 0) {
        generatedInsights.push({
          id: 'insight-client-engagement',
          title: 'Client Re-engagement Opportunity',
          description: `${clientsWithoutRecentProjects.length} active client(s) haven't had a project in 90+ days. Consider reaching out for new opportunities.`,
          type: 'opportunity',
          impact: 'medium',
          confidence: 82,
          actionable: true,
          data: { client_count: clientsWithoutRecentProjects.length },
          created_at: new Date().toISOString()
        });
      }

      // Task completion efficiency
      const overdueTasks = (tasks || []).filter((t: unknown) => {
        if (!t.due_date || t.status === 'completed') return false;
        return new Date(t.due_date) < new Date();
      });
      if (overdueTasks.length > 0) {
        const overduePercent = (overdueTasks.length / (tasks.length || 1)) * 100;
        generatedInsights.push({
          id: 'insight-task-efficiency',
          title: 'Task Completion Efficiency Alert',
          description: `${overdueTasks.length} task(s) (${Math.round(overduePercent)}%) are overdue. Consider resource reallocation or deadline adjustments.`,
          type: 'warning',
          impact: 'medium',
          confidence: 91,
          actionable: true,
          data: { overdue_count: overdueTasks.length, overdue_percent: Math.round(overduePercent) },
          created_at: new Date().toISOString()
        });
      }

      // Revenue growth recommendation
      const recentInvoices = (invoices || []).slice(0, 6);
      if (recentInvoices.length >= 3) {
        const avgRevenue = recentInvoices.reduce((sum: number, inv: unknown) => 
          sum + (Number(inv.total_amount) || 0), 0
        ) / recentInvoices.length;
        const potentialGrowth = avgRevenue * 0.2; // 20% growth potential
        generatedInsights.push({
          id: 'insight-revenue-growth',
          title: 'Revenue Growth Potential',
          description: `Based on current trends, implementing client retention strategies could increase revenue by approximately $${Math.round(potentialGrowth).toLocaleString()} per month.`,
          type: 'recommendation',
          impact: 'high',
          confidence: 78,
          actionable: true,
          data: { potential_growth: Math.round(potentialGrowth) },
          created_at: new Date().toISOString()
        });
      }

      setInsights(generatedInsights);
    } catch (error) {
      console.error('Error fetching insights:', error);
      setInsights([]);
    } finally {
      setLoading(false);
    }
  };

  const getInsightIcon = (type: string) => {
    switch (type) {
      case 'opportunity':
        return <TrendingUp className="h-5 w-5 text-green-500" />;
      case 'warning':
        return <AlertTriangle className="h-5 w-5 text-red-500" />;
      case 'trend':
        return <BarChart3 className="h-5 w-5 text-blue-500" />;
      case 'recommendation':
        return <Lightbulb className="h-5 w-5 text-yellow-500" />;
      default:
        return <Brain className="h-5 w-5 text-gray-500" />;
    }
  };

  const getInsightColor = (type: string) => {
    switch (type) {
      case 'opportunity':
        return 'bg-green-100 text-green-800';
      case 'warning':
        return 'bg-red-100 text-red-800';
      case 'trend':
        return 'bg-blue-100 text-blue-800';
      case 'recommendation':
        return 'bg-yellow-100 text-yellow-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const getImpactColor = (impact: string) => {
    switch (impact) {
      case 'high':
        return 'text-red-600';
      case 'medium':
        return 'text-yellow-600';
      case 'low':
        return 'text-green-600';
      default:
        return 'text-gray-600';
    }
  };

  const refreshInsights = async () => {
    await fetchInsights();
  };

  const implementInsight = async (insightId: string) => {
    try {
      // In a real app, this would trigger automated actions or create tasks
    } catch (error) {
      console.error('Error implementing insight:', error);
    }
  };

  // Group insights by type
  const groupedInsights = insights.reduce((groups, insight) => {
    const type = insight.type;
    if (!groups[type]) {
      groups[type] = [];
    }
    groups[type].push(insight);
    return groups;
  }, {} as Record<string, Insight[]>);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Brain className="h-5 w-5 text-primary" />
          AI-Generated Insights
        </h3>
        <Button 
          variant="outline" 
          size="sm"
          onClick={refreshInsights}
          disabled={loading}
        >
          <Zap className="h-4 w-4 mr-2" />
          {loading ? 'Analyzing...' : 'Refresh Insights'}
        </Button>
      </div>

      {/* Insight Summary */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <TrendingUp className="h-4 w-4 text-green-500" />
              <span className="text-sm font-medium">Opportunities</span>
            </div>
            <p className="text-2xl font-bold mt-2">{groupedInsights.opportunity?.length || 0}</p>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <AlertTriangle className="h-4 w-4 text-red-500" />
              <span className="text-sm font-medium">Warnings</span>
            </div>
            <p className="text-2xl font-bold mt-2">{groupedInsights.warning?.length || 0}</p>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <BarChart3 className="h-4 w-4 text-blue-500" />
              <span className="text-sm font-medium">Trends</span>
            </div>
            <p className="text-2xl font-bold mt-2">{groupedInsights.trend?.length || 0}</p>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <Lightbulb className="h-4 w-4 text-yellow-500" />
              <span className="text-sm font-medium">Recommendations</span>
            </div>
            <p className="text-2xl font-bold mt-2">{groupedInsights.recommendation?.length || 0}</p>
          </CardContent>
        </Card>
      </div>

      {/* High Priority Insights */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Target className="h-5 w-5" />
            High Priority Insights
          </CardTitle>
          <CardDescription>
            AI-identified insights requiring immediate attention
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {insights
              .filter(insight => insight.impact === 'high')
              .map((insight) => (
                <div key={insight.id} className="p-4 border rounded-lg hover:bg-muted/25">
                  <div className="flex items-start justify-between">
                    <div className="flex items-start space-x-3 flex-1">
                      {getInsightIcon(insight.type)}
                      <div className="flex-1">
                        <h4 className="font-semibold">{insight.title}</h4>
                        <p className="text-sm text-muted-foreground mt-1">
                          {insight.description}
                        </p>
                        
                        <div className="flex items-center space-x-4 mt-3">
                          <Badge className={getInsightColor(insight.type)} variant="outline">
                            {insight.type}
                          </Badge>
                          <span className={`text-sm font-medium ${getImpactColor(insight.impact)}`}>
                            {insight.impact} impact
                          </span>
                          <div className="flex items-center space-x-2">
                            <span className="text-sm text-muted-foreground">Confidence:</span>
                            <span className="text-sm font-medium">{insight.confidence}%</span>
                            <Progress value={insight.confidence} className="w-16 h-2" />
                          </div>
                        </div>
                      </div>
                    </div>
                    
                    {insight.actionable && (
                      <Button 
                        variant="outline" 
                        size="sm"
                        onClick={() => implementInsight(insight.id)}
                      >
                        Take Action
                      </Button>
                    )}
                  </div>
                </div>
              ))}
          </div>
        </CardContent>
      </Card>

      {/* All Insights by Category */}
      <div className="grid gap-6 md:grid-cols-2">
        {Object.entries(groupedInsights).map(([type, typeInsights]) => (
          <Card key={type}>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 capitalize">
                {getInsightIcon(type)}
                {type}s
              </CardTitle>
              <CardDescription>
                AI-detected {type}s for your business
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {typeInsights.map((insight) => (
                  <div key={insight.id} className="p-3 border rounded-lg">
                    <h5 className="font-medium text-sm">{insight.title}</h5>
                    <p className="text-xs text-muted-foreground mt-1">
                      {insight.description}
                    </p>
                    
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center space-x-2">
                        <span className={`text-xs ${getImpactColor(insight.impact)}`}>
                          {insight.impact}
                        </span>
                        <span className="text-xs text-muted-foreground">
                          {insight.confidence}% confidence
                        </span>
                      </div>
                      
                      {insight.actionable && (
                        <Button 
                          variant="ghost" 
                          size="sm"
                          onClick={() => implementInsight(insight.id)}
                        >
                          Act
                        </Button>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { 
  LineChart, 
  Line, 
  AreaChart, 
  Area, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  BarChart,
  Bar
} from "recharts";
import { 
  TrendingUp, 
  TrendingDown, 
  Brain, 
  Target, 
  Zap,
  Calendar,
  DollarSign,
  Users,
  AlertTriangle
} from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { getAgencyId } from "@/utils/agencyUtils";
import { selectRecords, rawQuery } from "@/services/api/core";

interface PredictionData {
  period: string;
  actual: number;
  predicted: number;
  confidence: number;
}

interface TrendData {
  metric: string;
  current: number;
  predicted: number;
  change: number;
  confidence: number;
}

export function PredictiveAnalytics() {
  const { user, profile } = useAuth();
  const [revenueData, setRevenueData] = useState<PredictionData[]>([]);
  const [projectData, setProjectData] = useState<PredictionData[]>([]);
  const [trendData, setTrendData] = useState<TrendData[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchPredictiveData();
  }, [user?.id, profile?.agency_id]);

  const fetchPredictiveData = async () => {
    try {
      setLoading(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        setRevenueData([]);
        setProjectData([]);
        setTrendData([]);
        return;
      }

      // Fetch invoices for revenue data
      let invoices: unknown[] = [];
      try {
        invoices = await selectRecords('invoices', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 1000
        }) || [];
      } catch (error: unknown) {
        if (error?.code !== '42703' && !error?.message?.includes('agency_id')) {
          console.error('Error fetching invoices:', error);
        }
      }

      // Fetch projects for project completion data
      let projects: unknown[] = [];
      try {
        projects = await selectRecords('projects', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 1000
        }) || [];
      } catch (error: unknown) {
        if (error?.code !== '42703' && !error?.message?.includes('agency_id')) {
          console.error('Error fetching projects:', error);
        }
      }

      // Generate revenue data from invoices (last 6 months)
      const now = new Date();
      const revenueDataArray: PredictionData[] = [];
      const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      
      for (let i = 5; i >= 0; i--) {
        const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const monthStart = new Date(date.getFullYear(), date.getMonth(), 1);
        const monthEnd = new Date(date.getFullYear(), date.getMonth() + 1, 0);
        
        const monthInvoices = (invoices || []).filter((inv: unknown) => {
          const invDate = new Date(inv.created_at || inv.issue_date);
          return invDate >= monthStart && invDate <= monthEnd;
        });
        
        const actual = monthInvoices.reduce((sum: number, inv: unknown) => 
          sum + (Number(inv.total_amount) || 0), 0
        );
        
        // Simple prediction: average of last 3 months + 5% growth
        const last3Months = revenueDataArray.slice(-3);
        const avgLast3 = last3Months.length > 0 
          ? last3Months.reduce((sum, d) => sum + d.actual, 0) / last3Months.length
          : actual;
        const predicted = i < 3 ? actual : avgLast3 * 1.05;
        const confidence = i < 3 ? 95 : Math.max(75, 95 - (i - 2) * 5);
        
        revenueDataArray.push({
          period: monthNames[date.getMonth()],
          actual: i < 3 ? actual : 0,
          predicted: Math.round(predicted),
          confidence: Math.round(confidence)
        });
      }

      // Generate project completion data (last 6 weeks)
      const projectDataArray: PredictionData[] = [];
      for (let i = 5; i >= 0; i--) {
        const weekStart = new Date(now.getTime() - (i * 7 * 24 * 60 * 60 * 1000));
        const weekEnd = new Date(weekStart.getTime() + (7 * 24 * 60 * 60 * 1000));
        
        const weekProjects = (projects || []).filter((p: unknown) => {
          const projDate = new Date(p.created_at);
          return projDate >= weekStart && projDate < weekEnd;
        });
        
        const actual = weekProjects.length;
        const last3Weeks = projectDataArray.slice(-3);
        const avgLast3 = last3Weeks.length > 0
          ? last3Weeks.reduce((sum, d) => sum + d.actual, 0) / last3Weeks.length
          : actual;
        const predicted = i < 3 ? actual : Math.round(avgLast3 * 1.1);
        const confidence = i < 3 ? 92 : Math.max(75, 92 - (i - 2) * 4);
        
        projectDataArray.push({
          period: `Week ${6 - i}`,
          actual: i < 3 ? actual : 0,
          predicted,
          confidence: Math.round(confidence)
        });
      }

      // Generate trend data from actual metrics
      const currentRevenue = revenueDataArray.slice(-1)[0]?.actual || 0;
      const predictedRevenue = revenueDataArray.slice(-1)[0]?.predicted || 0;
      const revenueChange = currentRevenue > 0 
        ? ((predictedRevenue - currentRevenue) / currentRevenue) * 100 
        : 0;

      const completedProjects = (projects || []).filter((p: unknown) => p.status === 'completed').length;
      const totalProjects = projects.length || 1;
      const completionRate = (completedProjects / totalProjects) * 100;
      const predictedCompletion = Math.min(100, completionRate + 5);

      const trendDataArray: TrendData[] = [
        {
          metric: 'Monthly Revenue',
          current: currentRevenue,
          predicted: predictedRevenue,
          change: Math.round(revenueChange * 10) / 10,
          confidence: 85
        },
        {
          metric: 'Project Completion',
          current: Math.round(completionRate),
          predicted: Math.round(predictedCompletion),
          change: Math.round((predictedCompletion - completionRate) * 10) / 10,
          confidence: 91
        },
        {
          metric: 'Client Acquisition',
          current: (invoices || []).length,
          predicted: Math.round((invoices || []).length * 1.2),
          change: 20,
          confidence: 78
        },
        {
          metric: 'Team Utilization',
          current: 75,
          predicted: 85,
          change: 13.3,
          confidence: 88
        }
      ];

      setRevenueData(revenueDataArray);
      setProjectData(projectDataArray);
      setTrendData(trendDataArray);
    } catch (error) {
      console.error('Error fetching predictive analytics:', error);
      setRevenueData([]);
      setProjectData([]);
      setTrendData([]);
    } finally {
      setLoading(false);
    }
  };

  const generateAdvancedPrediction = async (type: string) => {
    setLoading(true);
    try {
      // Simulate AI prediction generation
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Update data with new predictions
    } catch (error) {
      console.error('Error generating prediction:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Brain className="h-5 w-5 text-primary" />
          Advanced Predictive Analytics
        </h3>
        <div className="flex space-x-2">
          <Button 
            variant="outline" 
            size="sm"
            onClick={() => generateAdvancedPrediction('revenue')}
            disabled={loading}
          >
            <TrendingUp className="h-4 w-4 mr-2" />
            Forecast Revenue
          </Button>
          <Button 
            variant="outline" 
            size="sm"
            onClick={() => generateAdvancedPrediction('resources')}
            disabled={loading}
          >
            <Users className="h-4 w-4 mr-2" />
            Resource Planning
          </Button>
        </div>
      </div>

      {/* Key Predictions Overview */}
      <div className="grid gap-4 md:grid-cols-3">
        {trendData.slice(0, 3).map((trend, index) => (
          <Card key={index}>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium">{trend.metric}</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-2xl font-bold">
                    {trend.metric.includes('Revenue') ? `$${trend.predicted.toLocaleString()}` : 
                     trend.metric.includes('Satisfaction') ? trend.predicted.toFixed(1) : trend.predicted}
                  </p>
                  <div className="flex items-center text-sm">
                    {trend.change > 0 ? (
                      <TrendingUp className="h-4 w-4 text-green-500 mr-1" />
                    ) : (
                      <TrendingDown className="h-4 w-4 text-red-500 mr-1" />
                    )}
                    <span className={trend.change > 0 ? "text-green-600" : "text-red-600"}>
                      {Math.abs(trend.change).toFixed(1)}%
                    </span>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-xs text-muted-foreground">Confidence</p>
                  <p className="text-sm font-medium">{trend.confidence}%</p>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Revenue Prediction Chart */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <DollarSign className="h-5 w-5" />
            Revenue Prediction vs Actual
          </CardTitle>
          <CardDescription>
            AI-powered revenue forecasting with confidence intervals
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={revenueData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="period" />
              <YAxis />
              <Tooltip 
                formatter={(value, name) => [
                  `$${Number(value).toLocaleString()}`, 
                  name === 'actual' ? 'Actual' : 'Predicted'
                ]}
              />
              <Line 
                type="monotone" 
                dataKey="actual" 
                stroke="hsl(var(--primary))" 
                strokeWidth={2}
                dot={{ fill: "hsl(var(--primary))" }}
              />
              <Line 
                type="monotone" 
                dataKey="predicted" 
                stroke="hsl(var(--secondary))" 
                strokeWidth={2}
                strokeDasharray="5 5"
                dot={{ fill: "hsl(var(--secondary))" }}
              />
            </LineChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Project Completion Predictions */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Target className="h-5 w-5" />
            Project Completion Forecast
          </CardTitle>
          <CardDescription>
            Predicted project delivery timeline with risk assessment
          </CardDescription>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={250}>
            <AreaChart data={projectData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="period" />
              <YAxis />
              <Tooltip formatter={(value, name) => [value, name === 'actual' ? 'Actual' : 'Predicted']} />
              <Area 
                type="monotone" 
                dataKey="actual" 
                stackId="1"
                stroke="hsl(var(--primary))" 
                fill="hsl(var(--primary))"
                fillOpacity={0.6}
              />
              <Area 
                type="monotone" 
                dataKey="predicted" 
                stackId="2"
                stroke="hsl(var(--secondary))" 
                fill="hsl(var(--secondary))"
                fillOpacity={0.4}
              />
            </AreaChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Detailed Trend Analysis */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <BarChart className="h-5 w-5" />
            Trend Analysis & Predictions
          </CardTitle>
          <CardDescription>
            Comprehensive metrics with AI-driven insights
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {trendData.map((trend, index) => (
              <div key={index} className="flex items-center justify-between p-4 border rounded-lg">
                <div className="flex-1">
                  <h4 className="font-medium">{trend.metric}</h4>
                  <div className="flex items-center space-x-4 mt-2">
                    <div>
                      <p className="text-sm text-muted-foreground">Current</p>
                      <p className="font-medium">
                        {trend.metric.includes('Revenue') ? `$${trend.current.toLocaleString()}` : 
                         trend.metric.includes('Satisfaction') ? trend.current.toFixed(1) : trend.current}
                      </p>
                    </div>
                    <div>
                      <p className="text-sm text-muted-foreground">Predicted</p>
                      <p className="font-medium">
                        {trend.metric.includes('Revenue') ? `$${trend.predicted.toLocaleString()}` : 
                         trend.metric.includes('Satisfaction') ? trend.predicted.toFixed(1) : trend.predicted}
                      </p>
                    </div>
                  </div>
                </div>
                
                <div className="flex items-center space-x-4">
                  <div className="text-right">
                    <div className="flex items-center">
                      {trend.change > 0 ? (
                        <TrendingUp className="h-4 w-4 text-green-500 mr-1" />
                      ) : (
                        <TrendingDown className="h-4 w-4 text-red-500 mr-1" />
                      )}
                      <span className={trend.change > 0 ? "text-green-600" : "text-red-600"}>
                        {Math.abs(trend.change).toFixed(1)}%
                      </span>
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">Change</p>
                  </div>
                  
                  <div className="w-16">
                    <Progress value={trend.confidence} className="h-2" />
                    <p className="text-xs text-center mt-1">{trend.confidence}%</p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* AI Recommendations */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Zap className="h-5 w-5" />
            AI Recommendations
          </CardTitle>
          <CardDescription>
            Data-driven suggestions for optimal business outcomes
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex items-start space-x-3 p-3 bg-blue-50 rounded-lg">
              <TrendingUp className="h-5 w-5 text-blue-600 mt-0.5" />
              <div>
                <h5 className="font-medium text-blue-900">Revenue Optimization</h5>
                <p className="text-sm text-blue-700">
                  Focus on high-value clients in Q2. Predicted 23% revenue increase by targeting enterprise accounts.
                </p>
              </div>
            </div>
            
            <div className="flex items-start space-x-3 p-3 bg-yellow-50 rounded-lg">
              <AlertTriangle className="h-5 w-5 text-yellow-600 mt-0.5" />
              <div>
                <h5 className="font-medium text-yellow-900">Resource Alert</h5>
                <p className="text-sm text-yellow-700">
                  Development team will be over-capacity in 3 weeks. Consider hiring or redistributing workload.
                </p>
              </div>
            </div>
            
            <div className="flex items-start space-x-3 p-3 bg-green-50 rounded-lg">
              <Target className="h-5 w-5 text-green-600 mt-0.5" />
              <div>
                <h5 className="font-medium text-green-900">Project Optimization</h5>
                <p className="text-sm text-green-700">
                  Implementing suggested workflow changes could reduce project delivery time by 15%.
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { 
  Zap, 
  Bot, 
  CheckCircle, 
  Clock, 
  AlertTriangle, 
  Settings,
  Play,
  Pause,
  RotateCcw,
  TrendingUp,
  Users,
  FileText,
  Calendar
} from "lucide-react";
import { useAuth } from "@/hooks/useAuth";
import { getAgencyId } from "@/utils/agencyUtils";
import { selectRecords, rawQuery } from "@/services/api/core";
import { db } from "@/integrations/postgresql/client";

interface Automation {
  id: string;
  name: string;
  description: string;
  category: 'workflow' | 'notification' | 'data_entry' | 'reporting';
  enabled: boolean;
  frequency: 'real_time' | 'daily' | 'weekly' | 'monthly';
  last_run: string;
  success_rate: number;
  time_saved: number; // minutes per execution
  actions_count: number;
}

interface Recommendation {
  id: string;
  title: string;
  description: string;
  potential_impact: string;
  implementation_effort: 'low' | 'medium' | 'high';
  estimated_savings: number; // hours per month
  category: string;
  priority: number;
}

export function SmartRecommendations() {
  const { user, profile } = useAuth();
  const [automations, setAutomations] = useState<Automation[]>([]);
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    fetchData();
  }, [user?.id, profile?.agency_id]);

  const fetchData = async () => {
    try {
      setLoading(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        setAutomations([]);
        setRecommendations([]);
        return;
      }

      // Fetch real data to generate automations and recommendations
      const [projects, invoices, tasks, attendance] = await Promise.all([
        selectRecords('projects', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 100
        }).catch(() => []),
        selectRecords('invoices', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 100
        }).catch(() => []),
        selectRecords('tasks', {
          where: { agency_id: agencyId },
          orderBy: 'created_at DESC',
          limit: 100
        }).catch(() => []),
        selectRecords('attendance', {
          orderBy: 'date DESC',
          limit: 100
        }).catch(() => [])
      ]);

      // Generate automations based on real data
      const generatedAutomations: Automation[] = [];
      
      // Invoice automation - if there are completed projects without invoices
      const completedProjectsWithoutInvoices = (projects || []).filter((p: unknown) => 
        p.status === 'completed' && !invoices?.some((inv: unknown) => inv.project_id === p.id)
      );
      if (completedProjectsWithoutInvoices.length > 0) {
        generatedAutomations.push({
          id: 'auto-invoice',
          name: 'Invoice Generation',
          description: 'Automatically generate and send invoices when projects are marked as completed',
          category: 'workflow',
          enabled: false,
          frequency: 'real_time',
          last_run: new Date().toISOString(),
          success_rate: 95,
          time_saved: 15,
          actions_count: completedProjectsWithoutInvoices.length
        });
      }

      // Task reminder automation
      const overdueTasks = (tasks || []).filter((t: unknown) => {
        if (!t.due_date) return false;
        return new Date(t.due_date) < new Date() && t.status !== 'completed';
      });
      if (overdueTasks.length > 0) {
        generatedAutomations.push({
          id: 'auto-task-reminders',
          name: 'Task Reminder Notifications',
          description: 'Send automated reminders for overdue tasks',
          category: 'notification',
          enabled: false,
          frequency: 'daily',
          last_run: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
          success_rate: 90,
          time_saved: 8,
          actions_count: overdueTasks.length
        });
      }

      // Attendance tracking automation
      const recentAttendance = (attendance || []).filter((a: unknown) => {
        const date = new Date(a.date);
        const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
        return date > weekAgo;
      });
      if (recentAttendance.length > 0) {
        generatedAutomations.push({
          id: 'auto-attendance',
          name: 'Attendance Tracking',
          description: 'Automatically track and report attendance patterns',
          category: 'data_entry',
          enabled: false,
          frequency: 'daily',
          last_run: new Date().toISOString(),
          success_rate: 92,
          time_saved: 10,
          actions_count: recentAttendance.length
        });
      }

      // Generate recommendations based on real data
      const generatedRecommendations: Recommendation[] = [];
      
      // Budget alert recommendation
      const projectsNearBudget = (projects || []).filter((p: unknown) => {
        if (!p.budget || !p.actual_cost) return false;
        const budgetPercent = (p.actual_cost / p.budget) * 100;
        return budgetPercent >= 75 && budgetPercent < 100;
      });
      if (projectsNearBudget.length > 0) {
        generatedRecommendations.push({
          id: 'rec-budget-alerts',
          title: 'Smart Project Budget Alerts',
          description: `Create automated alerts when projects reach 80% of budget. ${projectsNearBudget.length} projects currently near budget limit.`,
          potential_impact: 'Prevent budget overruns and improve profitability',
          implementation_effort: 'medium',
          estimated_savings: 8,
          category: 'Financial Management',
          priority: 1
        });
      }

      // Timesheet reminder recommendation
      if (attendance && attendance.length > 0) {
        generatedRecommendations.push({
          id: 'rec-timesheet-reminders',
          title: 'Automate Timesheet Reminders',
          description: 'Set up automated reminders for employees who haven\'t submitted timesheets',
          potential_impact: 'Reduce timesheet submission delays by 85%',
          implementation_effort: 'low',
          estimated_savings: 4,
          category: 'Workflow Automation',
          priority: 2
        });
      }

      // Client follow-up recommendation
      const pendingInvoices = (invoices || []).filter((inv: unknown) => 
        inv.status === 'sent' || inv.status === 'pending'
      );
      if (pendingInvoices.length > 0) {
        generatedRecommendations.push({
          id: 'rec-client-followup',
          title: 'Client Follow-up Automation',
          description: `Automate follow-up reminders for ${pendingInvoices.length} pending invoices`,
          potential_impact: 'Improve payment collection rates by 20-30%',
          implementation_effort: 'low',
          estimated_savings: 6,
          category: 'Client Relations',
          priority: 3
        });
      }

      setAutomations(generatedAutomations);
      setRecommendations(generatedRecommendations);
    } catch (error) {
      console.error('Error fetching recommendations data:', error);
      setAutomations([]);
      setRecommendations([]);
    } finally {
      setLoading(false);
    }
  };

  const toggleAutomation = async (automationId: string) => {
    setAutomations(prev => 
      prev.map(automation => 
        automation.id === automationId 
          ? { ...automation, enabled: !automation.enabled }
          : automation
      )
    );
  };

  const implementRecommendation = async (recommendationId: string) => {
    try {
      // In a real app, this would create the automation or workflow
    } catch (error) {
      console.error('Error implementing recommendation:', error);
    }
  };

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case 'workflow':
        return <Zap className="h-4 w-4 text-blue-500" />;
      case 'notification':
        return <Bot className="h-4 w-4 text-green-500" />;
      case 'data_entry':
        return <FileText className="h-4 w-4 text-purple-500" />;
      case 'reporting':
        return <TrendingUp className="h-4 w-4 text-orange-500" />;
      default:
        return <Settings className="h-4 w-4 text-gray-500" />;
    }
  };

  const getEffortColor = (effort: string) => {
    switch (effort) {
      case 'low':
        return 'bg-green-100 text-green-800';
      case 'medium':
        return 'bg-yellow-100 text-yellow-800';
      case 'high':
        return 'bg-red-100 text-red-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };

  const totalTimeSaved = automations
    .filter(a => a.enabled)
    .reduce((total, automation) => total + (automation.time_saved * automation.actions_count), 0);

  const activeAutomations = automations.filter(a => a.enabled).length;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Bot className="h-5 w-5 text-primary" />
          Smart Automation & Recommendations
        </h3>
        <Button variant="outline" size="sm">
          <Settings className="h-4 w-4 mr-2" />
          Automation Settings
        </Button>
      </div>

      {/* Automation Summary */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <CheckCircle className="h-4 w-4 text-green-500" />
              <span className="text-sm font-medium">Active Automations</span>
            </div>
            <p className="text-2xl font-bold mt-2">{activeAutomations}</p>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <Clock className="h-4 w-4 text-blue-500" />
              <span className="text-sm font-medium">Time Saved</span>
            </div>
            <p className="text-2xl font-bold mt-2">{Math.round(totalTimeSaved / 60)}h</p>
            <p className="text-xs text-muted-foreground">This month</p>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-4">
            <div className="flex items-center space-x-2">
              <TrendingUp className="h-4 w-4 text-orange-500" />
              <span className="text-sm font-medium">Success Rate</span>
            </div>
            <p className="text-2xl font-bold mt-2">
              {Math.round(automations.reduce((sum, a) => sum + a.success_rate, 0) / automations.length)}%
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Active Automations */}
      <Card>
        <CardHeader>
          <CardTitle>Active Automations</CardTitle>
          <CardDescription>
            Manage your automated workflows and processes
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {automations.map((automation) => (
              <div key={automation.id} className="flex items-center justify-between p-4 border rounded-lg">
                <div className="flex items-center space-x-4">
                  {getCategoryIcon(automation.category)}
                  <div className="flex-1">
                    <h4 className="font-medium">{automation.name}</h4>
                    <p className="text-sm text-muted-foreground">{automation.description}</p>
                    
                    <div className="flex items-center space-x-4 mt-2 text-xs text-muted-foreground">
                      <span>Runs: {automation.frequency.replace('_', ' ')}</span>
                      <span>Success: {automation.success_rate}%</span>
                      <span>Saves: {automation.time_saved}min per run</span>
                      <span>Actions: {automation.actions_count}</span>
                    </div>
                  </div>
                </div>
                
                <div className="flex items-center space-x-3">
                  <div className="text-right">
                    <p className="text-sm font-medium">
                      {automation.enabled ? 'Active' : 'Disabled'}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      Last run: {new Date(automation.last_run).toLocaleDateString()}
                    </p>
                  </div>
                  
                  <Switch
                    checked={automation.enabled}
                    onCheckedChange={() => toggleAutomation(automation.id)}
                  />
                  
                  <Button variant="outline" size="sm">
                    <Settings className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Smart Recommendations */}
      <Card>
        <CardHeader>
          <CardTitle>Smart Recommendations</CardTitle>
          <CardDescription>
            AI-powered suggestions to improve your workflow efficiency
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {recommendations.map((rec) => (
              <div key={rec.id} className="p-4 border rounded-lg hover:bg-muted/25">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="flex items-center space-x-2 mb-2">
                      <h4 className="font-semibold">{rec.title}</h4>
                      <Badge className={getEffortColor(rec.implementation_effort)} variant="outline">
                        {rec.implementation_effort} effort
                      </Badge>
                    </div>
                    
                    <p className="text-sm text-muted-foreground mb-3">{rec.description}</p>
                    
                    <div className="flex items-center space-x-4 text-sm">
                      <div className="flex items-center space-x-1">
                        <TrendingUp className="h-4 w-4 text-green-500" />
                        <span>{rec.potential_impact}</span>
                      </div>
                      <div className="flex items-center space-x-1">
                        <Clock className="h-4 w-4 text-blue-500" />
                        <span>Saves {rec.estimated_savings}h/month</span>
                      </div>
                    </div>
                  </div>
                  
                  <div className="flex items-center space-x-2 ml-4">
                    <div className="text-right">
                      <p className="text-sm font-medium">{rec.category}</p>
                      <p className="text-xs text-muted-foreground">Priority {rec.priority}</p>
                    </div>
                    <Button 
                      variant="outline" 
                      size="sm"
                      onClick={() => implementRecommendation(rec.id)}
                    >
                      Implement
                    </Button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

