import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Plus, Settings, Download, Trash2, Edit, BarChart3, PieChart, Calendar, Table } from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { db } from '@/lib/database';
import { toast } from 'sonner';
import { getAgencyId } from '@/utils/agencyUtils';
import { selectRecords } from '@/services/api/core';
import { ResponsiveContainer, LineChart, Line, BarChart, Bar, PieChart as RechartsPieChart, Cell, XAxis, YAxis, CartesianGrid, Tooltip, Legend } from 'recharts';

interface DashboardWidget {
  id: string;
  widget_type: string;
  title: string;
  data_source: string;
  config: unknown;
  position: unknown;
  is_active: boolean;
  user_id: string;
  agency_id: string;
  created_at: string;
  updated_at: string;
}

interface CustomReport {
  id: string;
  name: string;
  description: string;
  data_sources: string[];
  filters: unknown;
  is_public: boolean;
  is_scheduled: boolean;
  user_id: string;
  agency_id: string;
  aggregations: unknown;
  group_by: string[];
  visualizations: unknown;
  schedule_config: unknown;
  created_at: string;
  updated_at: string;
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884D8'];

export function AdvancedDashboard() {
  const { user, profile } = useAuth();
  const [widgets, setWidgets] = useState<DashboardWidget[]>([]);
  const [reports, setReports] = useState<CustomReport[]>([]);
  const [loading, setLoading] = useState(true);
  const [agencyId, setAgencyId] = useState<string | null>(null);
  const [showWidgetDialog, setShowWidgetDialog] = useState(false);
  const [showReportDialog, setShowReportDialog] = useState(false);
  const [editingWidget, setEditingWidget] = useState<DashboardWidget | null>(null);
  const [editingReport, setEditingReport] = useState<CustomReport | null>(null);
  const [widgetForm, setWidgetForm] = useState({
    title: '',
    widget_type: 'chart',
    data_source: '',
    config: {}
  });
  const [reportForm, setReportForm] = useState({
    name: '',
    description: '',
    data_sources: [] as string[],
    is_public: false,
    is_scheduled: false
  });

  const fetchWidgets = async () => {
    try {
      if (!agencyId) return;
      
      const { data, error } = await db
        .from('dashboard_widgets')
        .select('*')
        .eq('is_active', true)
        .eq('agency_id', agencyId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setWidgets(data || []);
    } catch (error) {
      logError('Error fetching widgets:', error);
      toast.error('Failed to load dashboard widgets');
    }
  };

  const fetchReports = async () => {
    try {
      if (!agencyId) return;
      
      const { data, error } = await db
        .from('custom_reports')
        .select('*')
        .eq('agency_id', agencyId)
        .order('created_at', { ascending: false });

      if (error) throw error;
      setReports(data || []);
    } catch (error) {
      logError('Error fetching reports:', error);
      toast.error('Failed to load custom reports');
    }
  };

  useEffect(() => {
    const initializeAgency = async () => {
      const id = await getAgencyId(profile, user?.id);
      setAgencyId(id);
      if (id) {
        await Promise.all([fetchWidgets(), fetchReports()]);
      }
      setLoading(false);
    };
    if (user?.id) {
      initializeAgency();
    }
  }, [user?.id, profile?.agency_id]);

  const handleCreateWidget = async () => {
    if (!user || !widgetForm.title || !widgetForm.data_source || !agencyId) {
      toast.error('Please fill in all required fields');
      return;
    }

    try {
      const { error } = await db
        .from('dashboard_widgets')
        .insert({
          ...widgetForm,
          user_id: user.id,
          agency_id: agencyId
        });

      if (error) throw error;

      toast.success('Widget created successfully');
      setShowWidgetDialog(false);
      setWidgetForm({ title: '', widget_type: 'chart', data_source: '', config: {} });
      fetchWidgets();
    } catch (error) {
      logError('Error creating widget:', error);
      toast.error('Failed to create widget');
    }
  };

  const handleCreateReport = async () => {
    if (!user || !reportForm.name || reportForm.data_sources.length === 0 || !agencyId) {
      toast.error('Please fill in all required fields');
      return;
    }

    try {
      const { error } = await db
        .from('custom_reports')
        .insert({
          ...reportForm,
          user_id: user.id,
          agency_id: agencyId
        });

      if (error) throw error;

      toast.success('Report created successfully');
      setShowReportDialog(false);
      setReportForm({ name: '', description: '', data_sources: [], is_public: false, is_scheduled: false });
      fetchReports();
    } catch (error) {
      logError('Error creating report:', error);
      toast.error('Failed to create report');
    }
  };

  const handleDeleteWidget = async (widgetId: string) => {
    try {
      const { error } = await db
        .from('dashboard_widgets')
        .update({ is_active: false })
        .eq('id', widgetId);

      if (error) throw error;

      toast.success('Widget deleted successfully');
      fetchWidgets();
    } catch (error) {
      logError('Error deleting widget:', error);
      toast.error('Failed to delete widget');
    }
  };

  const getWidgetIcon = (type: string) => {
    switch (type) {
      case 'chart':
        return <BarChart3 className="h-4 w-4" />;
      case 'metric':
        return <PieChart className="h-4 w-4" />;
      case 'table':
        return <Table className="h-4 w-4" />;
      case 'calendar':
        return <Calendar className="h-4 w-4" />;
      default:
        return <BarChart3 className="h-4 w-4" />;
    }
  };

  const [widgetData, setWidgetData] = useState<Record<string, unknown>>({});

  useEffect(() => {
    if (widgets.length > 0 && agencyId) {
      fetchWidgetData();
    }
  }, [widgets, agencyId]);

  const fetchWidgetData = async () => {
    try {
      const dataMap: Record<string, unknown> = {};
      
      for (const widget of widgets) {
        try {
          let data: unknown[] = [];
          
          // Fetch data based on widget data_source
          switch (widget.data_source) {
            case 'invoices':
              data = await selectRecords('invoices', {
                where: { agency_id: agencyId },
                orderBy: 'created_at DESC',
                limit: 12
              }).catch(() => []);
              // Transform to chart data (monthly revenue)
              const monthlyData = transformToMonthlyData(data, 'total_amount', 'created_at');
              dataMap[widget.id] = monthlyData;
              break;
              
            case 'projects':
              data = await selectRecords('projects', {
                where: { agency_id: agencyId },
                orderBy: 'created_at DESC',
                limit: 12
              }).catch(() => []);
              const projectMonthlyData = transformToMonthlyData(data, 'budget', 'created_at');
              dataMap[widget.id] = projectMonthlyData;
              break;
              
            case 'clients':
              data = await selectRecords('clients', {
                where: { agency_id: agencyId, status: 'active' },
                orderBy: 'created_at DESC',
                limit: 12
              }).catch(() => []);
              const clientMonthlyData = transformToMonthlyData(data, 'id', 'created_at', true); // count
              dataMap[widget.id] = clientMonthlyData;
              break;
              
            case 'tasks':
              data = await selectRecords('tasks', {
                where: { agency_id: agencyId },
                orderBy: 'created_at DESC',
                limit: 12
              }).catch(() => []);
              const taskMonthlyData = transformToMonthlyData(data, 'id', 'created_at', true); // count
              dataMap[widget.id] = taskMonthlyData;
              break;
              
            default:
              // Default sample data if data_source not recognized
              dataMap[widget.id] = [
                { name: 'Jan', value: 0 },
                { name: 'Feb', value: 0 },
                { name: 'Mar', value: 0 },
                { name: 'Apr', value: 0 },
                { name: 'May', value: 0 }
              ];
          }
        } catch (error: unknown) {
          logError(`Error fetching data for widget ${widget.id}:`, error);
          // Set empty data on error
          dataMap[widget.id] = [
            { name: 'Jan', value: 0 },
            { name: 'Feb', value: 0 },
            { name: 'Mar', value: 0 },
            { name: 'Apr', value: 0 },
            { name: 'May', value: 0 }
          ];
        }
      }
      
      setWidgetData(dataMap);
    } catch (error) {
      logError('Error fetching widget data:', error);
    }
  };

  const transformToMonthlyData = (data: unknown[], valueKey: string, dateKey: string, isCount = false) => {
    const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const now = new Date();
    const monthlyMap: Record<string, number> = {};
    
    // Initialize last 6 months
    for (let i = 5; i >= 0; i--) {
      const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const monthKey = monthNames[date.getMonth()];
      monthlyMap[monthKey] = 0;
    }
    
    // Aggregate data by month
    (data || []).forEach((item: unknown) => {
      if (!item[dateKey]) return;
      const date = new Date(item[dateKey]);
      const monthKey = monthNames[date.getMonth()];
      if (monthlyMap.hasOwnProperty(monthKey)) {
        if (isCount) {
          monthlyMap[monthKey]++;
        } else {
          monthlyMap[monthKey] += Number(item[valueKey]) || 0;
        }
      }
    });
    
    return Object.entries(monthlyMap).map(([name, value]) => ({ name, value: Math.round(value) }));
  };

  const getWidgetMetric = async (widget: DashboardWidget): Promise<number> => {
    try {
      switch (widget.data_source) {
        case 'invoices':
          const invoices = await selectRecords('invoices', {
            where: { agency_id: agencyId },
            limit: 1000
          }).catch(() => []);
          return (invoices || []).reduce((sum: number, inv: unknown) => 
            sum + (Number(inv.total_amount) || 0), 0
          );
        case 'projects':
          const projects = await selectRecords('projects', {
            where: { agency_id: agencyId }
          }).catch(() => []);
          return (projects || []).length;
        case 'clients':
          const clients = await selectRecords('clients', {
            where: { agency_id: agencyId, status: 'active' }
          }).catch(() => []);
          return (clients || []).length;
        case 'tasks':
          const tasks = await selectRecords('tasks', {
            where: { agency_id: agencyId }
          }).catch(() => []);
          return (tasks || []).length;
        default:
          return 0;
      }
    } catch (error) {
      logError(`Error fetching metric for widget ${widget.id}:`, error);
      return 0;
    }
  };

  const renderWidget = (widget: DashboardWidget) => {
    const chartData = widgetData[widget.id] || [
      { name: 'Jan', value: 0 },
      { name: 'Feb', value: 0 },
      { name: 'Mar', value: 0 },
      { name: 'Apr', value: 0 },
      { name: 'May', value: 0 }
    ];

    return (
      <Card key={widget.id} className="relative">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <div className="flex items-center space-x-2">
            {getWidgetIcon(widget.widget_type)}
            <CardTitle className="text-sm font-medium">{widget.title}</CardTitle>
          </div>
          <div className="flex items-center space-x-1">
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                setEditingWidget(widget);
                setWidgetForm({
                  title: widget.title,
                  widget_type: widget.widget_type,
                  data_source: widget.data_source,
                  config: widget.config
                });
                setShowWidgetDialog(true);
              }}
            >
              <Edit className="h-3 w-3" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => handleDeleteWidget(widget.id)}
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="h-[200px] w-full">
            {widget.widget_type === 'chart' && (
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" />
                  <XAxis dataKey="name" />
                  <YAxis />
                  <Tooltip />
                  <Line type="monotone" dataKey="value" stroke="#8884d8" strokeWidth={2} />
                </LineChart>
              </ResponsiveContainer>
            )}
            {widget.widget_type === 'metric' && (
              <WidgetMetricDisplay widget={widget} />
            )}
            {widget.widget_type === 'table' && (
              <div className="text-center text-muted-foreground">
                <Table className="h-8 w-8 mx-auto mb-2" />
                <p className="text-sm">Table widget for {widget.data_source}</p>
              </div>
            )}
            {widget.widget_type === 'calendar' && (
              <div className="text-center text-muted-foreground">
                <Calendar className="h-8 w-8 mx-auto mb-2" />
                <p className="text-sm">Calendar widget for {widget.data_source}</p>
              </div>
            )}
          </div>
        </CardContent>
      </Card>
    );
  };

  const WidgetMetricDisplay = ({ widget }: { widget: DashboardWidget }) => {
    const [metric, setMetric] = useState<number | null>(null);
    
    useEffect(() => {
      getWidgetMetric(widget).then(setMetric);
    }, [widget.id, agencyId]);
    
    return (
      <div className="flex items-center justify-center h-full">
        <div className="text-center">
          <div className="text-3xl font-bold text-primary">
            {metric !== null ? metric.toLocaleString() : '...'}
          </div>
          <p className="text-sm text-muted-foreground">Total {widget.data_source}</p>
        </div>
      </div>
    );
  };

  if (loading) {
    return <div className="flex items-center justify-center p-8">Loading advanced dashboard...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Advanced Analytics Dashboard</h1>
          <p className="text-muted-foreground">Customize your analytics experience with widgets and reports</p>
        </div>
        <div className="flex space-x-2">
          <Button onClick={() => setShowReportDialog(true)}>
            <Plus className="h-4 w-4 mr-2" />
            Create Report
          </Button>
          <Button onClick={() => setShowWidgetDialog(true)}>
            <Plus className="h-4 w-4 mr-2" />
            Add Widget
          </Button>
        </div>
      </div>

      <Tabs defaultValue="dashboard" className="space-y-4">
        <TabsList>
          <TabsTrigger value="dashboard">Dashboard</TabsTrigger>
          <TabsTrigger value="reports">Custom Reports</TabsTrigger>
        </TabsList>

        <TabsContent value="dashboard" className="space-y-4">
          {widgets.length === 0 ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12">
                <BarChart3 className="h-12 w-12 text-muted-foreground mb-4" />
                <p className="text-lg font-medium">No widgets yet</p>
                <p className="text-muted-foreground mb-4">Create your first widget to start building your dashboard</p>
                <Button onClick={() => setShowWidgetDialog(true)}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Widget
                </Button>
              </CardContent>
            </Card>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {widgets.map(renderWidget)}
            </div>
          )}
        </TabsContent>

        <TabsContent value="reports" className="space-y-4">
          {reports.length === 0 ? (
            <Card>
              <CardContent className="flex flex-col items-center justify-center py-12">
                <PieChart className="h-12 w-12 text-muted-foreground mb-4" />
                <p className="text-lg font-medium">No custom reports</p>
                <p className="text-muted-foreground mb-4">Create custom reports to analyze your data</p>
                <Button onClick={() => setShowReportDialog(true)}>
                  <Plus className="h-4 w-4 mr-2" />
                  Create Report
                </Button>
              </CardContent>
            </Card>
          ) : (
            <div className="grid gap-4">
              {reports.map((report) => (
                <Card key={report.id}>
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="flex items-center space-x-2">
                          <span>{report.name}</span>
                          {report.is_public && <Badge variant="secondary">Public</Badge>}
                          {report.is_scheduled && <Badge variant="outline">Scheduled</Badge>}
                        </CardTitle>
                        <CardDescription>{report.description}</CardDescription>
                      </div>
                      <div className="flex items-center space-x-2">
                        <Button variant="outline" size="sm">
                          <Download className="h-4 w-4 mr-2" />
                          Export
                        </Button>
                        <Button variant="outline" size="sm">
                          <Settings className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="flex flex-wrap gap-2">
                      {report.data_sources.map((source, index) => (
                        <Badge key={index} variant="outline">{source}</Badge>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Widget Creation Dialog */}
      <Dialog open={showWidgetDialog} onOpenChange={setShowWidgetDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingWidget ? 'Edit Widget' : 'Create New Widget'}</DialogTitle>
            <DialogDescription>
              {editingWidget ? 'Update your widget configuration' : 'Add a new widget to your dashboard'}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label htmlFor="widget-title">Title</Label>
              <Input
                id="widget-title"
                value={widgetForm.title}
                onChange={(e) => setWidgetForm(prev => ({ ...prev, title: e.target.value }))}
                placeholder="Widget title"
              />
            </div>

            <div>
              <Label htmlFor="widget-type">Widget Type</Label>
              <Select
                value={widgetForm.widget_type}
                onValueChange={(value) => setWidgetForm(prev => ({ ...prev, widget_type: value as unknown }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select widget type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="chart">Chart</SelectItem>
                  <SelectItem value="metric">Metric</SelectItem>
                  <SelectItem value="table">Table</SelectItem>
                  <SelectItem value="calendar">Calendar</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label htmlFor="data-source">Data Source</Label>
              <Select
                value={widgetForm.data_source}
                onValueChange={(value) => setWidgetForm(prev => ({ ...prev, data_source: value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select data source" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="projects">Projects</SelectItem>
                  <SelectItem value="invoices">Invoices</SelectItem>
                  <SelectItem value="employees">Employees</SelectItem>
                  <SelectItem value="clients">Clients</SelectItem>
                  <SelectItem value="tasks">Tasks</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowWidgetDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateWidget}>
              {editingWidget ? 'Update Widget' : 'Create Widget'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Report Creation Dialog */}
      <Dialog open={showReportDialog} onOpenChange={setShowReportDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Custom Report</DialogTitle>
            <DialogDescription>
              Build a custom report with your preferred data sources and filters
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label htmlFor="report-name">Report Name</Label>
              <Input
                id="report-name"
                value={reportForm.name}
                onChange={(e) => setReportForm(prev => ({ ...prev, name: e.target.value }))}
                placeholder="Report name"
              />
            </div>

            <div>
              <Label htmlFor="report-description">Description</Label>
              <Textarea
                id="report-description"
                value={reportForm.description}
                onChange={(e) => setReportForm(prev => ({ ...prev, description: e.target.value }))}
                placeholder="Report description"
              />
            </div>

            <div>
              <Label>Data Sources</Label>
              <div className="flex flex-wrap gap-2 mt-2">
                {['projects', 'invoices', 'employees', 'clients', 'tasks'].map((source) => (
                  <Badge
                    key={source}
                    variant={reportForm.data_sources.includes(source) ? 'default' : 'outline'}
                    className="cursor-pointer"
                    onClick={() => {
                      setReportForm(prev => ({
                        ...prev,
                        data_sources: prev.data_sources.includes(source)
                          ? prev.data_sources.filter(s => s !== source)
                          : [...prev.data_sources, source]
                      }));
                    }}
                  >
                    {source}
                  </Badge>
                ))}
              </div>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowReportDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateReport}>
              Create Report
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import { generateUUID } from '@/lib/uuid';
import { Loader2, Eye, EyeOff, Copy, Check } from 'lucide-react';
import { Alert, AlertDescription } from '@/components/ui/alert';
import bcrypt from '@/lib/bcrypt';
import { selectRecords, insertRecord, updateRecord, selectOne } from '@/services/api/core';
import { getAgencyId } from '@/utils/agencyUtils';
import { getDepartmentsForSelectionAuto } from '@/services/api/departments';

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  position?: string;
  department?: string;
  phone?: string;
  hire_date?: string;
}

interface UserFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  user?: User | null;
  onUserSaved: () => void;
}

interface CreatedUserCredentials {
  email: string;
  temporaryPassword: string;
  userRole: string;
}

// Generate a secure temporary password
const generatePassword = () => {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$%';
  let password = '';
  for (let i = 0; i < 12; i++) {
    password += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return password;
};

const UserFormDialog = ({ isOpen, onClose, user, onUserSaved }: UserFormDialogProps) => {
  const { toast } = useToast();
  const { user: currentUser, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [showCredentials, setShowCredentials] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [copiedField, setCopiedField] = useState<string | null>(null);
  const [createdUser, setCreatedUser] = useState<CreatedUserCredentials | null>(null);
  const [departments, setDepartments] = useState<Array<{ id: string; name: string }>>([]);
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    role: '',
    position: '',
    department: '',
    phone: '',
    hire_date: '',
    is_active: true
  });

  const [passwordData, setPasswordData] = useState({
    newPassword: '',
    confirmPassword: ''
  });

  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  useEffect(() => {
    // Fetch departments when dialog opens
    const fetchDepartments = async () => {
      try {
        if (!currentUser?.id) {
          setDepartments([]);
          return;
        }
        
        // Use standardized department fetching service
        const departmentsData = await getDepartmentsForSelectionAuto(profile, currentUser.id);
        
        // Transform to component format (using name as value since profiles.department is a string)
        setDepartments(departmentsData.map(d => ({
          id: d.id,
          name: d.name
        })));
      } catch (error: unknown) {
        console.error('Error fetching departments:', error);
        setDepartments([]);
      }
    };
    
    fetchDepartments();
    
    if (user) {
      // Fetch current user status from database
      const fetchUserStatus = async () => {
        try {
          const userData = await selectRecords('users', {
            filters: [{ column: 'id', operator: 'eq', value: user.id }],
            limit: 1
          });
          const profileData = await selectRecords('profiles', {
            filters: [{ column: 'user_id', operator: 'eq', value: user.id }],
            limit: 1
          });
          
          const userIsActive = userData?.[0]?.is_active ?? true;
          const profileIsActive = profileData?.[0]?.is_active ?? true;
          const isActive = userIsActive && profileIsActive;
          
          setFormData({
            name: user.name || '',
            email: user.email || '',
            role: user.role || '',
            position: user.position || '',
            department: user.department || '',
            phone: user.phone || '',
            hire_date: user.hire_date || '',
            is_active: isActive
          });
        } catch (error) {
          console.error('Error fetching user status:', error);
          setFormData({
            name: user.name || '',
            email: user.email || '',
            role: user.role || '',
            position: user.position || '',
            department: user.department || '',
            phone: user.phone || '',
            hire_date: user.hire_date || '',
            is_active: true
          });
        }
      };
      
      fetchUserStatus();
    } else {
      setFormData({
        name: '',
        email: '',
        role: '',
        position: '',
        department: '',
        phone: '',
        hire_date: '',
        is_active: true
      });
    }
    setPasswordData({
      newPassword: '',
      confirmPassword: ''
    });
    setCreatedUser(null);
    setShowCredentials(false);
  }, [user, isOpen]);

  const copyToClipboard = async (text: string, field: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedField(field);
      setTimeout(() => setCopiedField(null), 2000);
      toast({
        title: "Copied!",
        description: `${field} copied to clipboard`,
      });
    } catch (error) {
      toast({
        title: "Copy failed",
        description: "Could not copy to clipboard",
        variant: "destructive",
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      if (user) {
        // Validate password if provided
        if (passwordData.newPassword) {
          if (passwordData.newPassword.length < 8) {
            throw new Error('Password must be at least 8 characters long');
          }
          if (passwordData.newPassword !== passwordData.confirmPassword) {
            throw new Error('Passwords do not match');
          }
        }

        // Update user profile using PostgreSQL service
        await updateRecord('profiles', {
          full_name: formData.name,
          phone: formData.phone || null,
          department: formData.department || null,
          position: formData.position || null,
          hire_date: formData.hire_date || null,
          is_active: formData.is_active
        }, { user_id: user.id }, currentUser?.id);
        
        // Update user is_active status
        await updateRecord('users', {
          is_active: formData.is_active
        }, { id: user.id }, currentUser?.id);

        // Update password if provided
        if (passwordData.newPassword) {
          const passwordHash = await bcrypt.hash(passwordData.newPassword, 10);
          await updateRecord('users', { password_hash: passwordHash }, { id: user.id }, currentUser?.id);
        }

        // Update user role - get the first role for this user and update it
        // If multiple roles exist, we update the first one
        const existingRoles = await selectRecords('user_roles', {
          select: 'id',
          filters: [{ column: 'user_id', operator: 'eq', value: user.id }],
          limit: 1
        });

        if (existingRoles && existingRoles.length > 0) {
          // Update existing role
          await updateRecord(
            'user_roles',
            { role: formData.role as unknown },
            { id: existingRoles[0].id },
            currentUser?.id
          );
        } else {
          // Insert new role if it doesn't exist
          const agencyId = await getAgencyId(profile, currentUser?.id);
          if (!agencyId) {
            throw new Error('Agency ID is required to assign a role');
          }
          await insertRecord('user_roles', {
            id: generateUUID(),
            user_id: user.id,
            role: formData.role as unknown,
            agency_id: agencyId
          }, currentUser?.id);
        }

        toast({
          title: "Success",
          description: passwordData.newPassword 
            ? "User updated successfully. Password has been changed."
            : "User updated successfully",
        });

        onUserSaved();
        onClose();
      } else {
        // Create new user
        const newUserId = generateUUID();
        const temporaryPassword = generatePassword();
        
        // Hash the password using bcrypt
        const passwordHash = await bcrypt.hash(temporaryPassword, 10);
        
        // Create user record
        await insertRecord('users', {
          id: newUserId,
          email: formData.email,
          password_hash: passwordHash,
          is_active: true,
          email_confirmed: true
        }, currentUser?.id);

        // Check if profile was created by trigger, otherwise create it
        const existingProfile = await selectOne('profiles', { user_id: newUserId });
        
        const agencyId = await getAgencyId(profile, currentUser?.id);
        if (!agencyId) {
          throw new Error('Agency ID is required to create a user');
        }

        const profileData = {
          full_name: formData.name,
          phone: formData.phone || null,
          department: formData.department || null,
          position: formData.position || null,
          hire_date: formData.hire_date || null,
          is_active: true,
          agency_id: agencyId
        };

        if (existingProfile) {
          // Update existing profile created by trigger
          await updateRecord('profiles', profileData, { user_id: newUserId }, currentUser?.id);
        } else {
          // Fallback: if trigger didn't create profile, insert it manually
          await insertRecord('profiles', {
            id: generateUUID(),
            user_id: newUserId,
            ...profileData,
          }, currentUser?.id);
        }

        // Assign role
        await insertRecord('user_roles', {
          id: generateUUID(),
          user_id: newUserId,
          role: formData.role || 'employee',
          agency_id: agencyId
        }, currentUser?.id);

        // Create minimal employee_details record so the user appears in unified employee views
        const nameParts = (formData.name || '').trim().split(/\s+/);
        const firstName = nameParts[0] || formData.name || 'User';
        const lastName = nameParts.slice(1).join(' ') || '';
        const employeeId = `EMP-${newUserId.substring(0, 8).toUpperCase()}`;

        await insertRecord('employee_details', {
          id: generateUUID(),
          user_id: newUserId,
          employee_id: employeeId,
          first_name: firstName,
          last_name: lastName,
          address: null,
          employment_type: 'full-time',
          work_location: null,
          emergency_contact_name: null,
          emergency_contact_phone: null,
          emergency_contact_relationship: null,
          skills: [],
          notes: null,
          is_active: true,
          agency_id: agencyId
        }, currentUser?.id);

        // Store the created user credentials to display
        setCreatedUser({
          email: formData.email,
          temporaryPassword: temporaryPassword,
          userRole: formData.role || 'employee'
        });

        setShowCredentials(true);

        toast({
          title: "Success",
          description: "User created successfully! Credentials are displayed below.",
        });

        onUserSaved();
      }
    } catch (error: unknown) {
      console.error('Error saving user:', error);
      toast({
        title: "Error",
        description: error.message || "Failed to save user",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleClose = () => {
    setCreatedUser(null);
    setShowCredentials(false);
    onClose();
  };

  return (
    <Dialog open={isOpen} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>{user ? 'Edit User' : 'Create New User'}</DialogTitle>
          <DialogDescription>
            {user 
              ? 'Update user information and role assignment.'
              : 'Create a new user account. Login credentials will be auto-generated.'
            }
          </DialogDescription>
        </DialogHeader>

        {showCredentials && createdUser && (
          <Alert className="mb-4 border-green-200 bg-green-50">
            <AlertDescription>
              <div className="space-y-3">
                <p className="font-semibold text-green-800">
                  User created successfully! Here are the login credentials:
                </p>
                
                <div className="space-y-2">
                  <div className="flex items-center justify-between p-2 bg-white rounded border">
                    <div>
                      <p className="text-sm font-medium">Email:</p>
                      <p className="text-sm">{createdUser.email}</p>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => copyToClipboard(createdUser.email, 'Email')}
                    >
                      {copiedField === 'Email' ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                    </Button>
                  </div>

                  <div className="flex items-center justify-between p-2 bg-white rounded border">
                    <div className="flex-1">
                      <p className="text-sm font-medium">Temporary Password:</p>
                      <p className="text-sm font-mono">
                        {showPassword ? createdUser.temporaryPassword : '••••••••••••'}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => setShowPassword(!showPassword)}
                      >
                        {showPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                      </Button>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => copyToClipboard(createdUser.temporaryPassword, 'Password')}
                      >
                        {copiedField === 'Password' ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                      </Button>
                    </div>
                  </div>

                  <div className="flex items-center justify-between p-2 bg-white rounded border">
                    <div>
                      <p className="text-sm font-medium">Role:</p>
                      <p className="text-sm capitalize">{createdUser.userRole.replace('_', ' ')}</p>
                    </div>
                  </div>
                </div>

                <p className="text-sm text-green-700">
                  ⚠️ <strong>Important:</strong> Save these credentials now - they won't be shown again!
                </p>
              </div>
            </AlertDescription>
          </Alert>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="name">Full Name *</Label>
              <Input
                id="name"
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                required
                disabled={loading}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="email">Email *</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                required={!user}
                disabled={loading || !!user}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="role">Role *</Label>
              <Select
                value={formData.role}
                onValueChange={(value) => setFormData({ ...formData, role: value })}
                disabled={loading}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select role" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="super_admin">Super Admin</SelectItem>
                  <SelectItem value="admin">Administrator</SelectItem>
                  <SelectItem value="hr">Human Resources</SelectItem>
                  <SelectItem value="finance_manager">Finance Manager</SelectItem>
                  <SelectItem value="project_manager">Project Manager</SelectItem>
                  <SelectItem value="team_lead">Team Lead</SelectItem>
                  <SelectItem value="employee">Employee</SelectItem>
                  <SelectItem value="contractor">Contractor</SelectItem>
                  <SelectItem value="intern">Intern</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="position">Position</Label>
              <Input
                id="position"
                value={formData.position}
                onChange={(e) => setFormData({ ...formData, position: e.target.value })}
                disabled={loading}
                placeholder="e.g., Senior Developer"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="department">Department</Label>
              <Select
                value={formData.department}
                onValueChange={(value) => setFormData({ ...formData, department: value === '__none__' ? '' : value })}
                disabled={loading}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select department" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">None</SelectItem>
                  {departments.map((dept) => (
                    <SelectItem key={dept.id} value={dept.name}>
                      {dept.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone">Phone</Label>
              <Input
                id="phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                disabled={loading}
                placeholder="+1 (555) 123-4567"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="hire_date">Hire Date</Label>
              <Input
                id="hire_date"
                type="date"
                value={formData.hire_date}
                onChange={(e) => setFormData({ ...formData, hire_date: e.target.value })}
                disabled={loading}
              />
            </div>
            {user && (
              <div className="space-y-2">
                <Label htmlFor="status">Status</Label>
                <Select
                  value={formData.is_active ? 'active' : 'inactive'}
                  onValueChange={(value) => setFormData({ ...formData, is_active: value === 'active' })}
                  disabled={loading}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="inactive">Trash</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            )}
          </div>

          {user && (
            <div className="space-y-4 pt-4 border-t">
              <div className="space-y-2">
                <Label className="text-base font-semibold">Change Password (Optional)</Label>
                <p className="text-sm text-muted-foreground">
                  Leave blank to keep current password. Admin can reset user password.
                </p>
              </div>
              
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="newPassword">New Password</Label>
                  <div className="relative">
                    <Input
                      id="newPassword"
                      type={showNewPassword ? "text" : "password"}
                      value={passwordData.newPassword}
                      onChange={(e) => setPasswordData({ ...passwordData, newPassword: e.target.value })}
                      disabled={loading}
                      placeholder="Min 8 characters"
                      minLength={8}
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                      onClick={() => setShowNewPassword(!showNewPassword)}
                      disabled={loading}
                    >
                      {showNewPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </Button>
                  </div>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="confirmPassword">Confirm Password</Label>
                  <div className="relative">
                    <Input
                      id="confirmPassword"
                      type={showConfirmPassword ? "text" : "password"}
                      value={passwordData.confirmPassword}
                      onChange={(e) => setPasswordData({ ...passwordData, confirmPassword: e.target.value })}
                      disabled={loading}
                      placeholder="Confirm new password"
                    />
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      className="absolute right-0 top-0 h-full px-3 py-2 hover:bg-transparent"
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      disabled={loading}
                    >
                      {showConfirmPassword ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </Button>
                  </div>
                </div>
              </div>
            </div>
          )}

          <DialogFooter>
            <Button type="button" variant="outline" onClick={handleClose} disabled={loading}>
              {showCredentials ? 'Close' : 'Cancel'}
            </Button>
            {!showCredentials && (
              <Button type="submit" disabled={loading}>
                {loading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    {user ? 'Updating...' : 'Creating...'}
                  </>
                ) : (
                  user ? 'Update User' : 'Create User'
                )}
              </Button>
            )}
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default UserFormDialog;

import React, { useState, useEffect } from 'react';
import { Calendar, Clock, Users, Gift, MapPin } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Calendar as CalendarComponent } from '@/components/ui/calendar';
import { Button } from '@/components/ui/button';
import { useAuth } from '@/hooks/useAuth';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { format, isSameDay, startOfMonth, endOfMonth } from 'date-fns';
import { CalendarEventDialog } from '@/components/shared/CalendarEventDialog';
import { EventDetailsDialog } from './EventDetailsDialog';
import { cn } from '@/lib/utils';

interface CalendarEvent {
  id: string;
  title: string;
  date: Date;
  type: 'event' | 'holiday' | 'leave' | 'birthday';
  description?: string;
  color?: string;
  employee_name?: string;
  // Additional fields for company events
  location?: string;
  event_type?: string;
  all_day?: boolean;
  start_date?: Date;
  end_date?: Date;
  is_company_event?: boolean; // Flag to identify if this is a company event that can be edited
}

interface AgencyCalendarProps {
  compact?: boolean;
}

export function AgencyCalendar({ compact = false }: AgencyCalendarProps) {
  const { userRole, profile, user } = useAuth();
  const { toast } = useToast();
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [events, setEvents] = useState<CalendarEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [showEventDialog, setShowEventDialog] = useState(false);
  const [selectedEvent, setSelectedEvent] = useState<CalendarEvent | null>(null);
  const [showEventDetails, setShowEventDetails] = useState(false);
  const [eventToEdit, setEventToEdit] = useState<CalendarEvent | null>(null);

  const canManageEvents = userRole === 'agency_admin' || userRole === 'manager' || userRole === 'super_admin';

  useEffect(() => {
    fetchCalendarData();
  }, [selectedDate, profile, user?.id]);

  const fetchCalendarData = async () => {
    try {
      setLoading(true);
      const startDate = startOfMonth(selectedDate);
      const endDate = endOfMonth(selectedDate);

      const allEvents: CalendarEvent[] = [];

      // Get agency_id for filtering
      const { getAgencyId } = await import('@/utils/agencyUtils');
      const agencyId = await getAgencyId(profile, user?.id);
      
      if (!agencyId) {
        console.warn('No agency_id available, cannot fetch calendar data');
        setLoading(false);
        return;
      }

      // Fetch company events for this agency
      const { data: companyEvents } = await db
        .from('company_events')
        .select('*')
        .eq('agency_id', agencyId)
        .gte('start_date', startDate.toISOString())
        .lte('start_date', endDate.toISOString())
        .order('start_date');

      if (companyEvents) {
        allEvents.push(...companyEvents.map(event => ({
          id: event.id,
          title: event.title,
          date: new Date(event.start_date),
          type: 'event' as const,
          description: event.description,
          color: event.color,
          location: event.location,
          event_type: event.event_type,
          all_day: event.is_all_day || event.all_day || false,
          start_date: new Date(event.start_date),
          end_date: event.end_date ? new Date(event.end_date) : undefined,
          is_company_event: true
        })));
      }

      // Fetch holidays for this agency
      const { data: holidays } = await db
        .from('holidays')
        .select('*')
        .eq('agency_id', agencyId)
        .gte('date', format(startDate, 'yyyy-MM-dd'))
        .lte('date', format(endDate, 'yyyy-MM-dd'))
        .order('date');

      if (holidays) {
        allEvents.push(...holidays.map(holiday => {
          // Map database fields to expected format
          const holidayType = holiday.is_national_holiday ? 'public' : holiday.is_company_holiday ? 'company' : 'optional';
          return {
            id: holiday.id,
            title: holiday.name,
            date: new Date(holiday.date),
            type: 'holiday' as const,
            description: holiday.description,
            color: holidayType === 'public' ? '#ef4444' : holidayType === 'company' ? '#3b82f6' : '#22c55e'
          };
        }));
      }

      // Fetch approved leave requests
      const { data: leaveRequests } = await db
        .from('leave_requests')
        .select('*')
        .eq('status', 'approved')
        .gte('start_date', format(startDate, 'yyyy-MM-dd'))
        .lte('end_date', format(endDate, 'yyyy-MM-dd'))
        .order('start_date');

      // Fetch employee details and profiles for leave requests
      const employeeProfileMap = new Map<string, string>();
      if (leaveRequests && leaveRequests.length > 0) {
        const employeeIds = leaveRequests.map(lr => lr.employee_id).filter(Boolean);
        if (employeeIds.length > 0) {
          // Try to find employee_details by id (UUID) first
          const { data: employeeDetails } = await db
            .from('employee_details')
            .select('id, user_id')
            .in('id', employeeIds);
          
          if (employeeDetails) {
            const userIds = employeeDetails.map(ed => ed.user_id).filter(Boolean);
            if (userIds.length > 0) {
              const { data: profiles } = await db
                .from('profiles')
                .select('user_id, full_name')
                .in('user_id', userIds);
              
              if (profiles) {
                const userToProfileMap = new Map(profiles.map(p => [p.user_id, p.full_name]));
                employeeDetails.forEach(ed => {
                  const fullName = userToProfileMap.get(ed.user_id);
                  if (fullName) {
                    employeeProfileMap.set(ed.id, fullName);
                  }
                });
              }
            }
          }
        }
      }

      if (leaveRequests) {
        leaveRequests.forEach(leave => {
          const startDate = new Date(leave.start_date);
          const endDate = new Date(leave.end_date);
          const currentDate = new Date(startDate);
          const employeeName = employeeProfileMap.get(leave.employee_id) || 'Employee';

          while (currentDate <= endDate) {
            allEvents.push({
              id: `${leave.id}-${currentDate.toISOString()}`,
              title: `${employeeName} - Leave`,
              date: new Date(currentDate),
              type: 'leave' as const,
              description: leave.reason,
              color: '#f59e0b',
              employee_name: employeeName
            });
            currentDate.setDate(currentDate.getDate() + 1);
          }
        });
      }

      // Fetch birthdays
      const { data: employees } = await db
        .from('employee_details')
        .select('*')
        .not('date_of_birth', 'is', null);

      // Fetch profiles for employees
      const employeeNameMap = new Map<string, string>();
      if (employees && employees.length > 0) {
        const userIds = employees.map(emp => emp.user_id).filter(Boolean);
        if (userIds.length > 0) {
          const { data: profiles } = await db
            .from('profiles')
            .select('user_id, full_name')
            .in('user_id', userIds);
          
          if (profiles) {
            profiles.forEach(profile => {
              employeeNameMap.set(profile.user_id, profile.full_name);
            });
          }
        }
      }

      if (employees) {
        employees.forEach(employee => {
          if (employee.date_of_birth) {
            const birthday = new Date(employee.date_of_birth);
            const currentYear = selectedDate.getFullYear();
            const birthdayThisYear = new Date(currentYear, birthday.getMonth(), birthday.getDate());
            const employeeName = employeeNameMap.get(employee.user_id) || 'Employee';

            if (birthdayThisYear >= startDate && birthdayThisYear <= endDate) {
              allEvents.push({
                id: `birthday-${employee.id}`,
                title: `🎂 ${employeeName}'s Birthday`,
                date: birthdayThisYear,
                type: 'birthday' as const,
                color: '#8b5cf6',
                employee_name: employeeName
              });
            }
          }
        });
      }

      setEvents(allEvents);
    } catch (error) {
      console.error('Error fetching calendar data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getEventsForDate = (date: Date) => {
    return events.filter(event => isSameDay(event.date, date));
  };

  const selectedDateEvents = getEventsForDate(selectedDate);

  const getEventIcon = (type: CalendarEvent['type']) => {
    switch (type) {
      case 'event':
        return <Calendar className="h-3 w-3" />;
      case 'holiday':
        return <MapPin className="h-3 w-3" />;
      case 'leave':
        return <Users className="h-3 w-3" />;
      case 'birthday':
        return <Gift className="h-3 w-3" />;
      default:
        return <Clock className="h-3 w-3" />;
    }
  };

  const getEventTypeLabel = (type: CalendarEvent['type']) => {
    switch (type) {
      case 'event':
        return 'Event';
      case 'holiday':
        return 'Holiday';
      case 'leave':
        return 'Leave';
      case 'birthday':
        return 'Birthday';
      default:
        return 'Event';
    }
  };

  if (compact) {
    return (
      <Card>
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Calendar</CardTitle>
          <Calendar className="h-4 w-4 text-muted-foreground" />
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {selectedDateEvents.slice(0, 3).map((event) => (
              <div key={event.id} className="flex items-center space-x-2">
                {getEventIcon(event.type)}
                <span className="text-sm truncate" style={{ color: event.color }}>
                  {event.title}
                </span>
              </div>
            ))}
            {selectedDateEvents.length > 3 && (
              <p className="text-xs text-muted-foreground">
                +{selectedDateEvents.length - 3} more events
              </p>
            )}
            {selectedDateEvents.length === 0 && (
              <p className="text-sm text-muted-foreground">No events today</p>
            )}
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      <Card>
        <CardHeader className="flex flex-row items-center justify-between pb-4 sm:pb-6">
          <CardTitle className="text-xl sm:text-2xl font-bold">Agency Calendar</CardTitle>
          {canManageEvents && (
            <Button 
              onClick={() => setShowEventDialog(true)} 
              size="sm"
              className="text-xs sm:text-sm px-3 sm:px-4 h-8 sm:h-9"
            >
              Add Event
            </Button>
          )}
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 sm:gap-6">
            <div className="lg:col-span-2">
              <div className="w-full overflow-x-auto -mx-2 sm:mx-0 px-2 sm:px-0">
                <CalendarComponent
                  mode="single"
                  selected={selectedDate}
                  onSelect={(date) => date && setSelectedDate(date)}
                  className="rounded-lg border shadow-sm bg-card w-full"
                  modifiers={{
                    hasEvents: (date) => {
                      const dateEvents = getEventsForDate(date);
                      return dateEvents.length > 0;
                    },
                    multipleEvents: (date) => {
                      const dateEvents = getEventsForDate(date);
                      return dateEvents.length > 1;
                    }
                  }}
                  modifiersClassNames={{
                    hasEvents: 'relative after:absolute after:bottom-1 sm:after:bottom-1.5 after:left-1/2 after:-translate-x-1/2 after:w-1.5 after:h-1.5 sm:after:w-2 sm:after:h-2 after:rounded-full after:bg-primary after:shadow-sm',
                    multipleEvents: 'after:w-2 after:h-2 sm:after:w-2.5 sm:after:h-2.5'
                  }}
                />
              </div>
            </div>
            
            <div className="space-y-4">
              <div className="sticky top-4">
                <div className="mb-4 pb-3 border-b">
                  <h3 className="text-lg sm:text-xl font-semibold text-foreground">
                    {format(selectedDate, 'EEEE')}
                  </h3>
                  <p className="text-sm sm:text-base text-muted-foreground mt-1">
                    {format(selectedDate, 'MMMM d, yyyy')}
                  </p>
                </div>
                <div className="space-y-2 sm:space-y-3 max-h-[400px] sm:max-h-[500px] overflow-y-auto pr-2 scrollbar-thin">
                  {selectedDateEvents.length > 0 ? (
                    selectedDateEvents.map((event) => (
                      <div
                        key={event.id}
                        onClick={() => {
                          setSelectedEvent(event);
                          setShowEventDetails(true);
                        }}
                        className={cn(
                          "p-3 sm:p-4 rounded-lg border-2 transition-all duration-200",
                          "hover:shadow-md hover:scale-[1.02] cursor-pointer active:scale-[0.98]",
                          "bg-card focus:outline-none focus:ring-2 focus:ring-primary focus:ring-offset-2"
                        )}
                        style={{
                          borderLeftColor: event.color || '#3b82f6',
                          borderLeftWidth: '4px'
                        }}
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault();
                            setSelectedEvent(event);
                            setShowEventDetails(true);
                          }
                        }}
                      >
                        <div className="flex items-start gap-3">
                          <div className="flex-shrink-0 mt-0.5 p-1.5 rounded-full bg-primary/10" style={{ color: event.color || '#3b82f6' }}>
                            {getEventIcon(event.type)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <div className="flex items-start justify-between gap-2 mb-1">
                              <h4 className="text-sm sm:text-base font-semibold text-foreground line-clamp-2">
                                {event.title}
                              </h4>
                              <Badge 
                                variant="outline" 
                                className="text-xs flex-shrink-0"
                                style={{ 
                                  borderColor: event.color || '#3b82f6',
                                  color: event.color || '#3b82f6'
                                }}
                              >
                                {getEventTypeLabel(event.type)}
                              </Badge>
                            </div>
                            {event.description && (
                              <p className="text-xs sm:text-sm text-muted-foreground mt-2 line-clamp-2">
                                {event.description}
                              </p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <div className="text-center py-8 sm:py-12">
                      <div className="inline-flex items-center justify-center w-16 h-16 sm:w-20 sm:h-20 rounded-full bg-muted/50 mb-4">
                        <Calendar className="h-8 w-8 sm:h-10 sm:w-10 text-muted-foreground" />
                      </div>
                      <p className="text-sm sm:text-base text-muted-foreground font-medium">
                        No events on this date
                      </p>
                      <p className="text-xs sm:text-sm text-muted-foreground/70 mt-1">
                        Select another date to view events
                      </p>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {showEventDialog && (
        <CalendarEventDialog
          open={showEventDialog}
          onOpenChange={(open) => {
            setShowEventDialog(open);
            if (!open) setEventToEdit(null);
          }}
          onEventCreated={fetchCalendarData}
          editEvent={eventToEdit ? {
            id: eventToEdit.id,
            title: eventToEdit.title,
            description: eventToEdit.description || '',
            event_type: eventToEdit.event_type || 'meeting',
            start_date: eventToEdit.start_date || eventToEdit.date,
            end_date: eventToEdit.end_date || eventToEdit.date,
            all_day: eventToEdit.all_day || false,
            location: eventToEdit.location || '',
            color: eventToEdit.color || '#3b82f6'
          } : null}
        />
      )}

      <EventDetailsDialog
        open={showEventDetails}
        onOpenChange={setShowEventDetails}
        event={selectedEvent}
        canEdit={canManageEvents}
        onEdit={(event) => {
          setEventToEdit(event);
          setShowEventDialog(true);
        }}
        onDelete={async (eventId) => {
          try {
            const { getAgencyId } = await import('@/utils/agencyUtils');
            const agencyId = await getAgencyId(profile, user?.id);
            
            if (!agencyId) {
              throw new Error('Agency ID is required to delete events');
            }

            const { error } = await db
              .from('company_events')
              .delete()
              .eq('id', eventId)
              .eq('agency_id', agencyId);

            if (error) throw error;

            toast({
              title: 'Success',
              description: 'Event deleted successfully'
            });

            fetchCalendarData();
          } catch (error: unknown) {
            console.error('Error deleting event:', error);
            toast({
              title: 'Error',
              description: error.message || 'Failed to delete event',
              variant: 'destructive'
            });
          }
        }}
      />
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Separator } from '@/components/ui/separator';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { 
  Upload, Download, Folder, File, Plus, Share2, Lock, Unlock, 
  Eye, Edit, Trash2, MoreHorizontal, Search, Filter, Grid, List 
} from 'lucide-react';
import { useAuth } from '@/hooks/useAuth';
import { db } from '@/lib/database';
import { toast } from 'sonner';
import { getAgencyId } from '@/utils/agencyUtils';
import { logError } from '@/utils/consoleLogger';
import { getApiRoot } from '@/config/api';

interface DocumentFolder {
  id: string;
  name: string;
  description: string;
  parent_folder_id: string | null;
  created_by: string;
  agency_id: string;
  created_at: string;
}

interface Document {
  id: string;
  name: string;
  description: string;
  file_path: string;
  file_size: number;
  file_type: string;
  uploaded_by: string;
  folder_id: string | null;
  tags: string[];
  is_public: boolean;
  download_count: number;
  agency_id: string;
  created_at: string;
  updated_at: string;
}

interface DocumentVersion {
  id: string;
  document_id: string;
  version_number: number;
  file_path: string;
  uploaded_by: string;
  upload_date: string;
  change_summary: string;
  is_current: boolean;
}

interface DocumentPermission {
  id: string;
  document_id: string;
  user_id: string;
  role: string;
  permission_type: 'read' | 'write' | 'admin';
  granted_by: string;
  created_at: string;
}

export function DocumentManager() {
  const { user, profile } = useAuth();
  const [folders, setFolders] = useState<DocumentFolder[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [currentFolder, setCurrentFolder] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [agencyId, setAgencyId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [showFolderDialog, setShowFolderDialog] = useState(false);
  const [showUploadDialog, setShowUploadDialog] = useState(false);
  const [showPermissionsDialog, setShowPermissionsDialog] = useState(false);
  const [showSettingsDialog, setShowSettingsDialog] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState<Document | null>(null);
  const [folderForm, setFolderForm] = useState({
    name: '',
    description: ''
  });

  const fetchFolders = async () => {
    try {
      if (!agencyId) return;
      
      const { data, error } = await db
        .from('document_folders')
        .select('*')
        .eq('agency_id', agencyId)
        .order('name');

      if (error) throw error;
      setFolders((data as DocumentFolder[]) || []);
    } catch (error: unknown) {
      logError('Error fetching folders:', error);
      toast.error(error?.message || 'Failed to load folders');
    }
  };

  const fetchDocuments = async () => {
    try {
      if (!agencyId) return;
      
      let query = db
        .from('documents')
        .select('*')
        .eq('agency_id', agencyId);

      if (currentFolder) {
        query = query.eq('folder_id', currentFolder);
      } else {
        query = query.is('folder_id', null);
      }

      const { data, error } = await query.order('name');

      if (error) throw error;
      // Ensure tags is always an array
      const docs = (data as Document[]) || [];
      const normalizedDocs = docs.map(doc => ({
        ...doc,
        tags: Array.isArray(doc.tags) ? doc.tags : (doc.tags ? [doc.tags] : []),
        download_count: doc.download_count || 0
      }));
      setDocuments(normalizedDocs);
    } catch (error: unknown) {
      logError('Error fetching documents:', error);
      toast.error(error?.message || 'Failed to load documents');
    }
  };

  useEffect(() => {
    const initializeAgency = async () => {
      const id = await getAgencyId(profile, user?.id);
      setAgencyId(id);
      if (id) {
        await Promise.all([fetchFolders(), fetchDocuments()]);
      }
      setLoading(false);
    };
    if (user?.id) {
      initializeAgency();
    }
  }, [user?.id, profile?.agency_id, currentFolder]);

  const handleCreateFolder = async () => {
    if (!user || !folderForm.name || !agencyId) {
      toast.error('Please provide a folder name');
      return;
    }

    try {
      const { error } = await db
        .from('document_folders')
        .insert({
          name: folderForm.name,
          description: folderForm.description || null,
          parent_folder_id: currentFolder || null,
          created_by: user.id,
          agency_id: agencyId
        });

      if (error) throw error;

      toast.success('Folder created successfully');
      setShowFolderDialog(false);
      setFolderForm({ name: '', description: '' });
      await fetchFolders();
    } catch (error: unknown) {
      logError('Error creating folder:', error);
      toast.error(error?.message || 'Failed to create folder');
    }
  };

  const handleFileUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file || !user) return;

    try {
      if (!agencyId) {
        throw new Error('Agency ID not found');
      }
      
      // Upload file to file storage
      const fileExt = file.name.split('.').pop();
      const fileName = `${Date.now()}-${file.name.replace(/[^a-zA-Z0-9.-]/g, '_')}`;
      // Store path without bucket prefix - bucket is passed separately
      const filePath = fileName;

      // Set current user ID for file upload
      (window as unknown).__currentUserId = user.id;

      const { error: uploadError, data: uploadData } = await db.storage
        .from('documents')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // Use the file path from upload result
      // uploadData.path should be in format "documents/filename.ext" from the API
      let finalFilePath = uploadData?.path;
      
      // If path doesn't include bucket, add it
      if (finalFilePath && !finalFilePath.startsWith('documents/')) {
        finalFilePath = `documents/${finalFilePath}`;
      } else if (!finalFilePath) {
        // Fallback: construct path
        finalFilePath = `documents/${filePath}`;
      }

      // Save document metadata
      const { error: dbError } = await db
        .from('documents')
        .insert({
          name: file.name,
          file_path: finalFilePath,
          file_size: file.size,
          file_type: file.type || 'application/octet-stream',
          uploaded_by: user.id,
          folder_id: currentFolder || null,
          agency_id: agencyId,
          tags: [],
          is_public: false,
          download_count: 0
        });

      if (dbError) throw dbError;

      toast.success('File uploaded successfully');
      fetchDocuments();
      
      // Reset file input
      if (event.target) {
        event.target.value = '';
      }
    } catch (error: unknown) {
      logError('Error uploading file:', error);
      toast.error(error?.message || 'Failed to upload file');
    }
  };

  const handleDownload = async (document: Document) => {
    try {
      // Extract bucket and path from file_path
      // file_path format: "documents/filename.ext"
      const pathParts = document.file_path.split('/');
      const bucket = pathParts[0] || 'documents';
      const filePath = pathParts.slice(1).join('/') || document.file_path;

      // Use API endpoint to download file
      const baseUrl = getApiRoot();
      const token = localStorage.getItem('auth_token') || '';
      
      const response = await fetch(`${baseUrl}/files/${bucket}/${encodeURIComponent(filePath)}`, {
        headers: {
          'Authorization': `Bearer ${token}`,
        },
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Download failed' }));
        throw new Error(errorData.error?.message || errorData.message || `Failed to download file: ${response.statusText}`);
      }

      // Download from API
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);
      const a = globalThis.document.createElement('a');
      a.href = url;
      a.download = document.name;
      globalThis.document.body.appendChild(a);
      a.click();
      globalThis.document.body.removeChild(a);
      URL.revokeObjectURL(url);

      // Update download count
      await db
        .from('documents')
        .update({ download_count: (document.download_count || 0) + 1 })
        .eq('id', document.id);

      toast.success('File downloaded successfully');
    } catch (error: unknown) {
      logError('Error downloading file:', error);
      toast.error(error?.message || 'Failed to download file');
    }
  };

  const handleOpen = async (document: Document) => {
    try {
      // Extract bucket and path from file_path
      // file_path format: "documents/filename.ext"
      const pathParts = document.file_path.split('/');
      const bucket = pathParts[0] || 'documents';
      const filePath = pathParts.slice(1).join('/') || document.file_path;

      // Use API endpoint to get file URL
      const baseUrl = getApiRoot();
      const token = localStorage.getItem('auth_token') || '';
      const fileUrl = `${baseUrl}/files/${bucket}/${encodeURIComponent(filePath)}`;

      // For files that can be viewed in browser (images, PDFs, etc.)
      // Create a temporary link with auth token in query param
      // Note: In production, use proper auth headers or signed URLs
      if (typeof window !== 'undefined' && window.document) {
        const link = window.document.createElement('a');
        link.href = fileUrl;
        link.target = '_blank';
        link.rel = 'noopener noreferrer';
        window.document.body.appendChild(link);
        link.click();
        window.document.body.removeChild(link);
      }
    } catch (error: unknown) {
      logError('Error opening file:', error);
      toast.error(error?.message || 'Failed to open file');
    }
  };

  const handleSettings = (document: Document) => {
    setSelectedDocument(document);
    setShowSettingsDialog(true);
  };

  const handleDeleteDocument = async (document: Document) => {
    if (!confirm(`Are you sure you want to delete "${document.name}"?`)) {
      return;
    }

    try {
      // Delete file from storage
      const pathParts = document.file_path.split('/');
      const bucket = pathParts[0] || 'documents';
      const filePath = pathParts.slice(1).join('/') || document.file_path;

      await db.storage
        .from(bucket)
        .remove([filePath]);

      // Delete document record
      const { error } = await db
        .from('documents')
        .delete()
        .eq('id', document.id);

      if (error) throw error;

      toast.success('Document deleted successfully');
      fetchDocuments();
    } catch (error: unknown) {
      logError('Error deleting document:', error);
      toast.error(error?.message || 'Failed to delete document');
    }
  };

  const handleDeleteFolder = async (folder: DocumentFolder) => {
    if (!confirm(`Are you sure you want to delete folder "${folder.name}"? This will also delete all documents inside.`)) {
      return;
    }

    try {
      // Delete folder (cascade will handle subfolders and documents)
      const { error } = await db
        .from('document_folders')
        .delete()
        .eq('id', folder.id);

      if (error) throw error;

      toast.success('Folder deleted successfully');
      if (currentFolder === folder.id) {
        setCurrentFolder(null);
      }
      await fetchFolders();
      await fetchDocuments();
    } catch (error: unknown) {
      logError('Error deleting folder:', error);
      toast.error(error?.message || 'Failed to delete folder');
    }
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const getFileIcon = (fileType: string) => {
    if (fileType.startsWith('image/')) return '🖼️';
    if (fileType.includes('pdf')) return '📄';
    if (fileType.includes('word')) return '📝';
    if (fileType.includes('excel') || fileType.includes('spreadsheet')) return '📊';
    if (fileType.includes('powerpoint') || fileType.includes('presentation')) return '📽️';
    return '📄';
  };

  const filteredDocuments = (documents || []).filter(doc =>
    doc.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (doc.tags || []).some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const currentFolderData = (folders || []).find(f => f.id === currentFolder);
  const subFolders = (folders || []).filter(f => f.parent_folder_id === currentFolder);

  if (loading) {
    return <div className="flex items-center justify-center p-8">Loading documents...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Document Management</h1>
          <p className="text-muted-foreground">Organize and manage your files with version control</p>
        </div>
        <div className="flex space-x-2">
          <Button onClick={() => setShowFolderDialog(true)}>
            <Plus className="h-4 w-4 mr-2" />
            New Folder
          </Button>
          <Button onClick={() => document.getElementById('file-upload')?.click()}>
            <Upload className="h-4 w-4 mr-2" />
            Upload File
          </Button>
          <input
            id="file-upload"
            type="file"
            className="hidden"
            onChange={handleFileUpload}
          />
        </div>
      </div>

      {/* Breadcrumb Navigation */}
      <div className="flex items-center space-x-2 text-sm text-muted-foreground">
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setCurrentFolder(null)}
          className={!currentFolder ? 'text-foreground' : ''}
        >
          Root
        </Button>
        {currentFolderData && (
          <>
            <span>/</span>
            <span className="text-foreground">{currentFolderData.name}</span>
          </>
        )}
      </div>

      {/* Search and View Controls */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-2">
          <Search className="h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search documents..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-64"
          />
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant={viewMode === 'grid' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setViewMode('grid')}
          >
            <Grid className="h-4 w-4" />
          </Button>
          <Button
            variant={viewMode === 'list' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setViewMode('list')}
          >
            <List className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Folders */}
      {subFolders.length > 0 && (
        <div>
          <h3 className="text-lg font-medium mb-3">Folders</h3>
          <div className={viewMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4' : 'space-y-2'}>
            {(subFolders || []).map((folder) => (
              <Card
                key={folder.id}
                className="cursor-pointer hover:shadow-md transition-shadow"
                onClick={() => setCurrentFolder(folder.id)}
              >
                <CardContent className="p-4">
                  <div className="flex items-center space-x-3">
                    <Folder className="h-8 w-8 text-blue-500" />
                    <div className="flex-1 min-w-0">
                      <p className="font-medium truncate">{folder.name}</p>
                      {folder.description && (
                        <p className="text-sm text-muted-foreground truncate">{folder.description}</p>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        </div>
      )}

      {/* Documents */}
      <div>
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-lg font-medium">Documents ({filteredDocuments.length})</h3>
        </div>

        {filteredDocuments.length === 0 ? (
          <Card>
            <CardContent className="flex flex-col items-center justify-center py-12">
              <File className="h-12 w-12 text-muted-foreground mb-4" />
              <p className="text-lg font-medium">No documents found</p>
              <p className="text-muted-foreground mb-4">
                {searchTerm ? 'Try adjusting your search terms' : 'Upload your first document to get started'}
              </p>
              {!searchTerm && (
                <Button onClick={() => document.getElementById('file-upload')?.click()}>
                  <Upload className="h-4 w-4 mr-2" />
                  Upload File
                </Button>
              )}
            </CardContent>
          </Card>
        ) : (
          <div className={viewMode === 'grid' ? 'grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4' : 'space-y-2'}>
            {(filteredDocuments || []).map((document) => (
              <Card key={document.id} className="group">
                <CardContent className="p-4">
                  <div className="flex items-start space-x-3">
                    <div className="text-2xl">{getFileIcon(document.file_type)}</div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between">
                        <p className="font-medium truncate">{document.name}</p>
                        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleOpen(document)}
                            title="Open/View"
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDownload(document)}
                            title="Download"
                          >
                            <Download className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleSettings(document)}
                            title="Settings"
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setSelectedDocument(document);
                              setShowPermissionsDialog(true);
                            }}
                            title="Share"
                          >
                            <Share2 className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => handleDeleteDocument(document)}
                            title="Delete"
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </div>
                      <div className="flex items-center space-x-2 mt-1">
                        <span className="text-sm text-muted-foreground">{formatFileSize(document.file_size)}</span>
                        <span className="text-sm text-muted-foreground">•</span>
                        <span className="text-sm text-muted-foreground">
                          Downloaded {document.download_count} times
                        </span>
                        {document.is_public ? (
                          <Unlock className="h-3 w-3 text-green-500" />
                        ) : (
                          <Lock className="h-3 w-3 text-gray-500" />
                        )}
                      </div>
                      {(document.tags || []).length > 0 && (
                        <div className="flex flex-wrap gap-1 mt-2">
                          {(document.tags || []).slice(0, 3).map((tag, index) => (
                            <Badge key={index} variant="secondary" className="text-xs">
                              {tag}
                            </Badge>
                          ))}
                          {(document.tags || []).length > 3 && (
                            <Badge variant="outline" className="text-xs">
                              +{(document.tags || []).length - 3}
                            </Badge>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>

      {/* Settings Dialog */}
      <Dialog open={showSettingsDialog} onOpenChange={setShowSettingsDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Document Settings</DialogTitle>
            <DialogDescription>
              Manage settings for {selectedDocument?.name}
            </DialogDescription>
          </DialogHeader>
          {selectedDocument && (
            <div className="space-y-4">
              <div>
                <Label htmlFor="doc-name">Document Name</Label>
                <Input
                  id="doc-name"
                  value={selectedDocument.name}
                  onChange={async (e) => {
                    try {
                      await db
                        .from('documents')
                        .update({ name: e.target.value })
                        .eq('id', selectedDocument.id);
                      setSelectedDocument({ ...selectedDocument, name: e.target.value });
                      fetchDocuments();
                      toast.success('Document name updated');
                    } catch (error: unknown) {
                      toast.error(error?.message || 'Failed to update name');
                    }
                  }}
                />
              </div>
              <div>
                <Label htmlFor="doc-description">Description</Label>
                <Textarea
                  id="doc-description"
                  value={selectedDocument.description || ''}
                  onChange={async (e) => {
                    try {
                      await db
                        .from('documents')
                        .update({ description: e.target.value || null })
                        .eq('id', selectedDocument.id);
                      setSelectedDocument({ ...selectedDocument, description: e.target.value || null });
                      fetchDocuments();
                    } catch (error: unknown) {
                      toast.error(error?.message || 'Failed to update description');
                    }
                  }}
                  placeholder="Add a description..."
                />
              </div>
              <div>
                <Label htmlFor="doc-public">Visibility</Label>
                <Select
                  value={selectedDocument.is_public ? 'public' : 'private'}
                  onValueChange={async (value) => {
                    try {
                      await db
                        .from('documents')
                        .update({ is_public: value === 'public' })
                        .eq('id', selectedDocument.id);
                      setSelectedDocument({ ...selectedDocument, is_public: value === 'public' });
                      fetchDocuments();
                      toast.success(`Document is now ${value}`);
                    } catch (error: unknown) {
                      toast.error(error?.message || 'Failed to update visibility');
                    }
                  }}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="public">Public</SelectItem>
                    <SelectItem value="private">Private</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>File Information</Label>
                <div className="text-sm text-muted-foreground space-y-1 mt-2">
                  <p>Type: {selectedDocument.file_type}</p>
                  <p>Size: {formatFileSize(selectedDocument.file_size)}</p>
                  <p>Path: {selectedDocument.file_path}</p>
                  <p>Downloads: {selectedDocument.download_count}</p>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowSettingsDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Folder Creation Dialog */}
      <Dialog open={showFolderDialog} onOpenChange={setShowFolderDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create New Folder</DialogTitle>
            <DialogDescription>
              Create a new folder to organize your documents
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <Label htmlFor="folder-name">Folder Name</Label>
              <Input
                id="folder-name"
                value={folderForm.name}
                onChange={(e) => setFolderForm(prev => ({ ...prev, name: e.target.value }))}
                placeholder="Folder name"
              />
            </div>

            <div>
              <Label htmlFor="folder-description">Description (Optional)</Label>
              <Textarea
                id="folder-description"
                value={folderForm.description}
                onChange={(e) => setFolderForm(prev => ({ ...prev, description: e.target.value }))}
                placeholder="Folder description"
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowFolderDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateFolder}>
              Create Folder
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Document Permissions Dialog */}
      <Dialog open={showPermissionsDialog} onOpenChange={setShowPermissionsDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Document Permissions</DialogTitle>
            <DialogDescription>
              Manage who can access "{selectedDocument?.name}"
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div className="text-center py-8 text-muted-foreground">
              <Share2 className="h-12 w-12 mx-auto mb-4" />
              <p>Permission management coming soon</p>
              <p className="text-sm">This feature will allow you to control document access</p>
            </div>
          </div>

          <DialogFooter>
            <Button onClick={() => setShowPermissionsDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { 
  Settings, 
  FileText, 
  TrendingUp, 
  Calendar,
  AlertTriangle,
  CheckCircle,
  Clock,
  Plus,
  Edit,
  Trash2,
  Eye,
  Search,
  Filter
} from 'lucide-react';
import { useGST, GSTReturn, GSTTransaction } from '@/hooks/useGST';
import { GSTSettingsDialog } from './GSTSettingsDialog';
import { GSTTransactionDialog } from './GSTTransactionDialog';
import { GSTReturnDialog } from './GSTReturnDialog';
import { useAuth } from '@/hooks/useAuth';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';

export const GSTDashboard: React.FC = () => {
  const { 
    settings, 
    returns, 
    transactions,
    liability, 
    loading, 
    saveSettings, 
    fetchLiability,
    fetchTransactions,
    createTransaction,
    updateTransaction,
    deleteTransaction,
    generateReturn,
    updateReturn,
    isAuthenticated 
  } = useGST();
  const { user, userRole, loading: authLoading } = useAuth();
  const [showSettingsDialog, setShowSettingsDialog] = useState(false);
  const [showTransactionDialog, setShowTransactionDialog] = useState(false);
  const [showReturnDialog, setShowReturnDialog] = useState(false);
  const [editingTransaction, setEditingTransaction] = useState<GSTTransaction | null>(null);
  const [deletingTransaction, setDeletingTransaction] = useState<GSTTransaction | null>(null);
  const [viewingReturn, setViewingReturn] = useState<GSTReturn | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [transactionFilter, setTransactionFilter] = useState<string>('all');
  
  // Simple currency formatter
  const formatCurrency = (amount: number, currency: string = 'INR'): string => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(amount || 0);
  };
  
  const [selectedPeriod, setSelectedPeriod] = useState(() => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  const [lastFetchedPeriod, setLastFetchedPeriod] = useState<string | null>(null);
  
  useEffect(() => {
    // Only fetch liability if user is authenticated and has selected a period
    // AND we haven't already fetched for this period
    if (isAuthenticated && selectedPeriod && selectedPeriod !== lastFetchedPeriod) {
      const [year, month] = selectedPeriod.split('-');
      const startDate = `${year}-${month}-01`;
      const endDate = new Date(parseInt(year), parseInt(month), 0).toISOString().split('T')[0];
      
      setLastFetchedPeriod(selectedPeriod);
      
      // Use a delay to prevent rapid-fire requests
      const timeoutId = setTimeout(() => {
        fetchLiability(startDate, endDate);
        fetchTransactions({ start_date: startDate, end_date: endDate });
      }, 300);
      
      return () => clearTimeout(timeoutId);
    }
  }, [selectedPeriod, isAuthenticated, lastFetchedPeriod]); // Track last fetched period

  const getStatusColor = (status: GSTReturn['status']) => {
    switch (status) {
      case 'filed': return 'bg-green-500 text-white';
      case 'pending': return 'bg-yellow-500 text-white';
      case 'late': return 'bg-red-500 text-white';
      default: return 'bg-gray-500 text-white';
    }
  };

  const getStatusIcon = (status: GSTReturn['status']) => {
    switch (status) {
      case 'filed': return <CheckCircle className="h-4 w-4" />;
      case 'pending': return <Clock className="h-4 w-4" />;
      case 'late': return <AlertTriangle className="h-4 w-4" />;
      default: return <FileText className="h-4 w-4" />;
    }
  };

  const handleCreateTransaction = async (transaction: Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at' | 'updated_at'>) => {
    await createTransaction(transaction);
    setShowTransactionDialog(false);
    setEditingTransaction(null);
  };

  const handleUpdateTransaction = async (transaction: Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at' | 'updated_at'>) => {
    if (editingTransaction?.id) {
      await updateTransaction(editingTransaction.id, transaction);
      setShowTransactionDialog(false);
      setEditingTransaction(null);
    }
  };

  const handleDeleteTransaction = async () => {
    if (deletingTransaction?.id) {
      await deleteTransaction(deletingTransaction.id);
      setDeletingTransaction(null);
    }
  };

  const handleMarkReturnAsFiled = async (returnItem: GSTReturn) => {
    if (returnItem.id) {
      await updateReturn(returnItem.id, {
        status: 'filed',
        filed_date: new Date().toISOString()
      });
    }
  };

  const filteredTransactions = (transactions || []).filter(t => {
    const matchesSearch = !searchTerm || 
      t.invoice_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
      t.customer_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (t.description && t.description.toLowerCase().includes(searchTerm.toLowerCase()));
    
    const matchesFilter = transactionFilter === 'all' || t.transaction_type === transactionFilter;
    
    return matchesSearch && matchesFilter;
  });

  // Show loading state while auth is loading or GST data is loading
  if (authLoading || loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  // Show authentication required message if user is not authenticated
  // Allow super_admin even if isAuthenticated is false (they might not have agency_id in profile)
  // userRole is already declared on line 57, no need to redeclare
  const hasAgencyContext = typeof window !== 'undefined' && localStorage.getItem('agency_database');
  const canAccess = user && (isAuthenticated || (userRole === 'super_admin' && hasAgencyContext));
  
  if (!canAccess) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="text-center">
          <h2 className="text-lg font-semibold mb-2">Authentication Required</h2>
          <p className="text-muted-foreground">Please log in to access GST compliance features.</p>
        </div>
      </div>
    );
  }

  if (!settings) {
    return (
      <div className="container mx-auto py-8">
        <div className="text-center space-y-6">
          <div className="space-y-2">
            <h1 className="text-3xl font-bold">GST Compliance</h1>
            <p className="text-muted-foreground">
              Configure your GST settings to start managing compliance and returns
            </p>
          </div>
          
          <Card className="max-w-md mx-auto">
            <CardContent className="pt-6">
              <div className="space-y-4 text-center">
                <Settings className="h-12 w-12 mx-auto text-muted-foreground" />
                <div>
                  <h3 className="font-semibold">GST Settings Required</h3>
                  <p className="text-sm text-muted-foreground">
                    Please configure your GST registration details to continue
                  </p>
                </div>
                <Button onClick={() => setShowSettingsDialog(true)}>
                  <Settings className="mr-2 h-4 w-4" />
                  Configure GST Settings
                </Button>
              </div>
            </CardContent>
          </Card>
        </div>

        <GSTSettingsDialog
          open={showSettingsDialog}
          onOpenChange={setShowSettingsDialog}
          existingSettings={settings}
          onSave={saveSettings}
          loading={loading}
        />
      </div>
    );
  }

  return (
    <div className="container mx-auto py-8">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold">GST Compliance</h1>
          <p className="text-muted-foreground">
            Manage your GST returns, liability, and compliance
          </p>
        </div>
        <Button variant="outline" onClick={() => setShowSettingsDialog(true)}>
          <Settings className="mr-2 h-4 w-4" />
          Settings
        </Button>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Tax Liability</p>
                <p className="text-2xl font-bold">
                  {liability ? formatCurrency(liability.total_tax, 'INR') : '₹0'}
                </p>
              </div>
              <TrendingUp className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Taxable Value</p>
                <p className="text-2xl font-bold">
                  {liability ? formatCurrency(liability.total_taxable_value, 'INR') : '₹0'}
                </p>
              </div>
              <FileText className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Pending Returns</p>
                <p className="text-2xl font-bold">
                  {(returns || []).filter(r => r.status === 'pending').length}
                </p>
              </div>
              <Clock className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Transactions</p>
                <p className="text-2xl font-bold">
                  {(transactions || []).length}
                </p>
              </div>
              <FileText className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs defaultValue="returns" className="space-y-6">
        <TabsList>
          <TabsTrigger value="returns">Returns</TabsTrigger>
          <TabsTrigger value="liability">Tax Liability</TabsTrigger>
          <TabsTrigger value="transactions">Transactions</TabsTrigger>
        </TabsList>

        <TabsContent value="returns" className="space-y-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>GST Returns</CardTitle>
              <Button size="sm" onClick={() => setShowReturnDialog(true)}>
                <Plus className="mr-2 h-4 w-4" />
                Generate Return
              </Button>
            </CardHeader>
            <CardContent>
              {(returns || []).length === 0 ? (
                <div className="text-center py-12">
                  <Calendar className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="font-semibold mb-2">No Returns Found</h3>
                  <p className="text-muted-foreground mb-4">
                    Start by generating your first GST return
                  </p>
                  <Button onClick={() => setShowReturnDialog(true)}>
                    <Plus className="mr-2 h-4 w-4" />
                    Generate Return
                  </Button>
                </div>
              ) : (
                <div className="space-y-4">
                  {(returns || []).map((returnItem) => (
                    <div key={returnItem.id} className="flex items-center justify-between p-4 border rounded-lg">
                      <div className="flex items-center gap-3">
                        {getStatusIcon(returnItem.status)}
                        <div>
                          <div className="font-medium">{returnItem.return_type}</div>
                          <div className="text-sm text-muted-foreground">
                            Period: {new Date(returnItem.filing_period).toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}
                          </div>
                          <div className="text-sm text-muted-foreground">
                            Due: {new Date(returnItem.due_date).toLocaleDateString()}
                          </div>
                          {returnItem.filed_date && (
                            <div className="text-sm text-muted-foreground">
                              Filed: {new Date(returnItem.filed_date).toLocaleDateString()}
                            </div>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-3">
                        <div className="text-right">
                          <div className="font-medium">
                            {formatCurrency(returnItem.total_tax_amount || 0, 'INR')}
                          </div>
                          <div className="text-sm text-muted-foreground">
                            {formatCurrency(returnItem.total_taxable_value || 0, 'INR')} taxable
                          </div>
                        </div>
                        <Badge className={getStatusColor(returnItem.status)}>
                          {returnItem.status}
                        </Badge>
                        {returnItem.status === 'pending' && (
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => handleMarkReturnAsFiled(returnItem)}
                          >
                            Mark as Filed
                          </Button>
                        )}
                        <Button 
                          variant="outline" 
                          size="sm"
                          onClick={() => setViewingReturn(returnItem)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="liability" className="space-y-6">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <CardTitle>Tax Liability Summary</CardTitle>
                <Input
                  type="month"
                  value={selectedPeriod}
                  onChange={(e) => setSelectedPeriod(e.target.value)}
                  className="w-48"
                />
              </div>
            </CardHeader>
            <CardContent>
              {liability ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  <div className="p-4 bg-muted/50 rounded-lg">
                    <h4 className="font-medium mb-2">CGST</h4>
                    <p className="text-2xl font-bold">{formatCurrency(liability.total_cgst, 'INR')}</p>
                  </div>
                  <div className="p-4 bg-muted/50 rounded-lg">
                    <h4 className="font-medium mb-2">SGST</h4>
                    <p className="text-2xl font-bold">{formatCurrency(liability.total_sgst, 'INR')}</p>
                  </div>
                  <div className="p-4 bg-muted/50 rounded-lg">
                    <h4 className="font-medium mb-2">IGST</h4>
                    <p className="text-2xl font-bold">{formatCurrency(liability.total_igst, 'INR')}</p>
                  </div>
                  <div className="p-4 bg-muted/50 rounded-lg">
                    <h4 className="font-medium mb-2">Cess</h4>
                    <p className="text-2xl font-bold">{formatCurrency(liability.total_cess, 'INR')}</p>
                  </div>
                  <div className="p-4 bg-primary/10 rounded-lg">
                    <h4 className="font-medium mb-2">Total Tax</h4>
                    <p className="text-2xl font-bold text-primary">{formatCurrency(liability.total_tax, 'INR')}</p>
                  </div>
                  <div className="p-4 bg-muted/50 rounded-lg">
                    <h4 className="font-medium mb-2">Taxable Value</h4>
                    <p className="text-2xl font-bold">{formatCurrency(liability.total_taxable_value, 'INR')}</p>
                  </div>
                </div>
              ) : (
                <div className="text-center py-12">
                  <TrendingUp className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                  <h3 className="font-semibold mb-2">No Liability Data</h3>
                  <p className="text-muted-foreground">
                    No transactions found for the selected period
                  </p>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="transactions" className="space-y-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>GST Transactions</CardTitle>
              <Button size="sm" onClick={() => {
                setEditingTransaction(null);
                setShowTransactionDialog(true);
              }}>
                <Plus className="mr-2 h-4 w-4" />
                Add Transaction
              </Button>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {/* Search and Filter */}
                <div className="flex gap-4">
                  <div className="flex-1 relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search by invoice number, customer name, or description..."
                      value={searchTerm}
                      onChange={(e) => setSearchTerm(e.target.value)}
                      className="pl-10"
                    />
                  </div>
                  <select
                    value={transactionFilter}
                    onChange={(e) => setTransactionFilter(e.target.value)}
                    className="px-3 py-2 border rounded-md"
                  >
                    <option value="all">All Types</option>
                    <option value="sale">Sale</option>
                    <option value="purchase">Purchase</option>
                    <option value="credit_note">Credit Note</option>
                    <option value="debit_note">Debit Note</option>
                  </select>
                </div>

                {filteredTransactions.length === 0 ? (
                  <div className="text-center py-12">
                    <FileText className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                    <h3 className="font-semibold mb-2">No Transactions Found</h3>
                    <p className="text-muted-foreground mb-4">
                      {(transactions || []).length === 0 
                        ? 'Start by adding your first GST transaction'
                        : 'No transactions match your search criteria'}
                    </p>
                    {(transactions || []).length === 0 && (
                      <Button onClick={() => {
                        setEditingTransaction(null);
                        setShowTransactionDialog(true);
                      }}>
                        <Plus className="mr-2 h-4 w-4" />
                        Add Transaction
                      </Button>
                    )}
                  </div>
                ) : (
                  <div className="space-y-2">
                    {(filteredTransactions || []).map((transaction) => (
                      <div key={transaction.id} className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50">
                        <div className="flex-1">
                          <div className="flex items-center gap-3">
                            <Badge variant="outline">{transaction.transaction_type}</Badge>
                            <div className="font-medium">{transaction.invoice_number}</div>
                            <div className="text-sm text-muted-foreground">
                              {new Date(transaction.invoice_date).toLocaleDateString()}
                            </div>
                          </div>
                          <div className="text-sm text-muted-foreground mt-1">
                            {transaction.customer_name}
                            {transaction.customer_gstin && ` (${transaction.customer_gstin})`}
                          </div>
                          {transaction.description && (
                            <div className="text-sm text-muted-foreground mt-1">
                              {transaction.description}
                            </div>
                          )}
                        </div>
                        <div className="flex items-center gap-4">
                          <div className="text-right">
                            <div className="font-medium">
                              {formatCurrency(transaction.total_amount || 0, 'INR')}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              Tax: {formatCurrency(
                                (transaction.cgst_amount || 0) + 
                                (transaction.sgst_amount || 0) + 
                                (transaction.igst_amount || 0) + 
                                (transaction.cess_amount || 0), 
                                'INR'
                              )}
                            </div>
                          </div>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setEditingTransaction(transaction);
                              setShowTransactionDialog(true);
                            }}
                          >
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => setDeletingTransaction(transaction)}
                          >
                            <Trash2 className="h-4 w-4 text-destructive" />
                          </Button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Dialogs */}
      <GSTSettingsDialog
        open={showSettingsDialog}
        onOpenChange={setShowSettingsDialog}
        existingSettings={settings}
        onSave={saveSettings}
        loading={loading}
      />

      <GSTTransactionDialog
        open={showTransactionDialog}
        onOpenChange={(open) => {
          setShowTransactionDialog(open);
          if (!open) setEditingTransaction(null);
        }}
        existingTransaction={editingTransaction}
        onSave={editingTransaction ? handleUpdateTransaction : handleCreateTransaction}
        loading={loading}
      />

      <GSTReturnDialog
        open={showReturnDialog}
        onOpenChange={setShowReturnDialog}
        onGenerate={generateReturn}
        loading={loading}
      />

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={!!deletingTransaction} onOpenChange={(open) => !open && setDeletingTransaction(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Transaction</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete transaction {deletingTransaction?.invoice_number}? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteTransaction} className="bg-destructive text-destructive-foreground">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* View Return Dialog */}
      {viewingReturn && (
        <Dialog open={!!viewingReturn} onOpenChange={(open) => !open && setViewingReturn(null)}>
          <DialogContent className="max-w-2xl">
            <DialogHeader>
              <DialogTitle>GST Return Details - {viewingReturn.return_type}</DialogTitle>
            </DialogHeader>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-sm text-muted-foreground">Filing Period</Label>
                  <p className="font-medium">
                    {new Date(viewingReturn.filing_period).toLocaleDateString('en-IN', { month: 'long', year: 'numeric' })}
                  </p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Due Date</Label>
                  <p className="font-medium">{new Date(viewingReturn.due_date).toLocaleDateString()}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Status</Label>
                  <Badge className={getStatusColor(viewingReturn.status)}>
                    {viewingReturn.status}
                  </Badge>
                </div>
                {viewingReturn.filed_date && (
                  <div>
                    <Label className="text-sm text-muted-foreground">Filed Date</Label>
                    <p className="font-medium">{new Date(viewingReturn.filed_date).toLocaleDateString()}</p>
                  </div>
                )}
                {viewingReturn.acknowledgment_number && (
                  <div className="col-span-2">
                    <Label className="text-sm text-muted-foreground">Acknowledgment Number</Label>
                    <p className="font-medium">{viewingReturn.acknowledgment_number}</p>
                  </div>
                )}
              </div>
              <div className="grid grid-cols-2 gap-4 pt-4 border-t">
                <div>
                  <Label className="text-sm text-muted-foreground">Taxable Value</Label>
                  <p className="text-xl font-bold">{formatCurrency(viewingReturn.total_taxable_value || 0, 'INR')}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Total Tax</Label>
                  <p className="text-xl font-bold text-primary">{formatCurrency(viewingReturn.total_tax_amount || 0, 'INR')}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">CGST</Label>
                  <p className="font-medium">{formatCurrency(viewingReturn.cgst_amount || 0, 'INR')}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">SGST</Label>
                  <p className="font-medium">{formatCurrency(viewingReturn.sgst_amount || 0, 'INR')}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">IGST</Label>
                  <p className="font-medium">{formatCurrency(viewingReturn.igst_amount || 0, 'INR')}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Cess</Label>
                  <p className="font-medium">{formatCurrency(viewingReturn.cess_amount || 0, 'INR')}</p>
                </div>
              </div>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Loader2, Info } from 'lucide-react';
import { GSTTransaction } from '@/services/api/financial';

interface GSTTransactionDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  existingTransaction?: GSTTransaction | null;
  onSave: (transaction: Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at' | 'updated_at'>) => Promise<void>;
  loading?: boolean;
}

export const GSTTransactionDialog: React.FC<GSTTransactionDialogProps> = ({
  open,
  onOpenChange,
  existingTransaction,
  onSave,
  loading = false
}) => {
  const [formData, setFormData] = useState<Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at' | 'updated_at'>>({
    transaction_type: 'sale',
    invoice_number: '',
    invoice_date: new Date().toISOString().split('T')[0],
    customer_gstin: '',
    customer_name: '',
    place_of_supply: '',
    hsn_sac_code: '',
    description: '',
    quantity: 1,
    unit_price: 0,
    taxable_value: 0,
    cgst_rate: 0,
    sgst_rate: 0,
    igst_rate: 0,
    cess_rate: 0,
    cgst_amount: 0,
    sgst_amount: 0,
    igst_amount: 0,
    cess_amount: 0,
    total_amount: 0
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  useEffect(() => {
    if (existingTransaction) {
      setFormData({
        transaction_type: existingTransaction.transaction_type,
        invoice_number: existingTransaction.invoice_number || '',
        invoice_date: existingTransaction.invoice_date || new Date().toISOString().split('T')[0],
        customer_gstin: existingTransaction.customer_gstin || '',
        customer_name: existingTransaction.customer_name || '',
        place_of_supply: existingTransaction.place_of_supply || '',
        hsn_sac_code: existingTransaction.hsn_sac_code || '',
        description: existingTransaction.description || '',
        quantity: existingTransaction.quantity || 1,
        unit_price: Number(existingTransaction.unit_price) || 0,
        taxable_value: Number(existingTransaction.taxable_value) || 0,
        cgst_rate: Number(existingTransaction.cgst_rate) || 0,
        sgst_rate: Number(existingTransaction.sgst_rate) || 0,
        igst_rate: Number(existingTransaction.igst_rate) || 0,
        cess_rate: Number(existingTransaction.cess_rate) || 0,
        cgst_amount: Number(existingTransaction.cgst_amount) || 0,
        sgst_amount: Number(existingTransaction.sgst_amount) || 0,
        igst_amount: Number(existingTransaction.igst_amount) || 0,
        cess_amount: Number(existingTransaction.cess_amount) || 0,
        total_amount: Number(existingTransaction.total_amount) || 0
      });
    } else {
      // Reset form
      setFormData({
        transaction_type: 'sale',
        invoice_number: '',
        invoice_date: new Date().toISOString().split('T')[0],
        customer_gstin: '',
        customer_name: '',
        place_of_supply: '',
        hsn_sac_code: '',
        description: '',
        quantity: 1,
        unit_price: 0,
        taxable_value: 0,
        cgst_rate: 0,
        sgst_rate: 0,
        igst_rate: 0,
        cess_rate: 0,
        cgst_amount: 0,
        sgst_amount: 0,
        igst_amount: 0,
        cess_amount: 0,
        total_amount: 0
      });
    }
    setErrors({});
  }, [existingTransaction, open]);

  const calculateTaxes = () => {
    const taxableValue = Number(formData.quantity || 1) * Number(formData.unit_price || 0);
    const cgstRate = Number(formData.cgst_rate || 0);
    const sgstRate = Number(formData.sgst_rate || 0);
    const igstRate = Number(formData.igst_rate || 0);
    const cessRate = Number(formData.cess_rate || 0);

    const cgstAmount = (taxableValue * cgstRate) / 100;
    const sgstAmount = (taxableValue * sgstRate) / 100;
    const igstAmount = (taxableValue * igstRate) / 100;
    const cessAmount = (taxableValue * cessRate) / 100;
    const totalAmount = taxableValue + cgstAmount + sgstAmount + igstAmount + cessAmount;

    setFormData(prev => ({
      ...prev,
      taxable_value: taxableValue,
      cgst_amount: cgstAmount,
      sgst_amount: sgstAmount,
      igst_amount: igstAmount,
      cess_amount: cessAmount,
      total_amount: totalAmount
    }));
  };

  useEffect(() => {
    if (formData.quantity && formData.unit_price) {
      calculateTaxes();
    }
  }, [formData.quantity, formData.unit_price, formData.cgst_rate, formData.sgst_rate, formData.igst_rate, formData.cess_rate]);

  const validate = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.invoice_number?.trim()) {
      newErrors.invoice_number = 'Invoice number is required';
    }
    if (!formData.invoice_date) {
      newErrors.invoice_date = 'Invoice date is required';
    }
    if (!formData.customer_name?.trim()) {
      newErrors.customer_name = 'Customer name is required';
    }
    if (!formData.unit_price || formData.unit_price <= 0) {
      newErrors.unit_price = 'Unit price must be greater than 0';
    }
    if (!formData.quantity || formData.quantity <= 0) {
      newErrors.quantity = 'Quantity must be greater than 0';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSave = async () => {
    if (!validate()) {
      return;
    }

    try {
      setIsSubmitting(true);
      await onSave(formData);
      onOpenChange(false);
    } catch (error) {
      console.error('Failed to save GST transaction:', error);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {existingTransaction ? 'Edit GST Transaction' : 'Add GST Transaction'}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6 py-4">
          <Alert>
            <Info className="h-4 w-4" />
            <AlertDescription>
              Enter GST transaction details. Tax amounts will be calculated automatically based on rates.
            </AlertDescription>
          </Alert>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="transaction_type">Transaction Type *</Label>
              <Select
                value={formData.transaction_type}
                onValueChange={(value: GSTTransaction['transaction_type']) => 
                  setFormData({ ...formData, transaction_type: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="sale">Sale</SelectItem>
                  <SelectItem value="purchase">Purchase</SelectItem>
                  <SelectItem value="credit_note">Credit Note</SelectItem>
                  <SelectItem value="debit_note">Debit Note</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label htmlFor="invoice_number">Invoice Number *</Label>
              <Input
                id="invoice_number"
                value={formData.invoice_number}
                onChange={(e) => setFormData({ ...formData, invoice_number: e.target.value })}
                placeholder="INV-001"
                className={errors.invoice_number ? 'border-destructive' : ''}
              />
              {errors.invoice_number && (
                <p className="text-sm text-destructive">{errors.invoice_number}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="invoice_date">Invoice Date *</Label>
              <Input
                id="invoice_date"
                type="date"
                value={formData.invoice_date}
                onChange={(e) => setFormData({ ...formData, invoice_date: e.target.value })}
                className={errors.invoice_date ? 'border-destructive' : ''}
              />
              {errors.invoice_date && (
                <p className="text-sm text-destructive">{errors.invoice_date}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="customer_name">Customer/Vendor Name *</Label>
              <Input
                id="customer_name"
                value={formData.customer_name}
                onChange={(e) => setFormData({ ...formData, customer_name: e.target.value })}
                placeholder="Enter customer or vendor name"
                className={errors.customer_name ? 'border-destructive' : ''}
              />
              {errors.customer_name && (
                <p className="text-sm text-destructive">{errors.customer_name}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="customer_gstin">Customer/Vendor GSTIN</Label>
              <Input
                id="customer_gstin"
                value={formData.customer_gstin || ''}
                onChange={(e) => setFormData({ ...formData, customer_gstin: e.target.value.toUpperCase() })}
                placeholder="22AAAAA0000A1Z5"
                maxLength={15}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="place_of_supply">Place of Supply</Label>
              <Input
                id="place_of_supply"
                value={formData.place_of_supply || ''}
                onChange={(e) => setFormData({ ...formData, place_of_supply: e.target.value })}
                placeholder="State name or code"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="hsn_sac_code">HSN/SAC Code</Label>
              <Input
                id="hsn_sac_code"
                value={formData.hsn_sac_code || ''}
                onChange={(e) => setFormData({ ...formData, hsn_sac_code: e.target.value })}
                placeholder="Enter HSN or SAC code"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Input
                id="description"
                value={formData.description || ''}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Product or service description"
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="quantity">Quantity *</Label>
              <Input
                id="quantity"
                type="number"
                step="0.01"
                min="0.01"
                value={formData.quantity || 1}
                onChange={(e) => setFormData({ ...formData, quantity: Number(e.target.value) || 1 })}
                className={errors.quantity ? 'border-destructive' : ''}
              />
              {errors.quantity && (
                <p className="text-sm text-destructive">{errors.quantity}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="unit_price">Unit Price *</Label>
              <Input
                id="unit_price"
                type="number"
                step="0.01"
                min="0.01"
                value={formData.unit_price || 0}
                onChange={(e) => setFormData({ ...formData, unit_price: Number(e.target.value) || 0 })}
                className={errors.unit_price ? 'border-destructive' : ''}
              />
              {errors.unit_price && (
                <p className="text-sm text-destructive">{errors.unit_price}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="cgst_rate">CGST Rate (%)</Label>
              <Input
                id="cgst_rate"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.cgst_rate || 0}
                onChange={(e) => setFormData({ ...formData, cgst_rate: Number(e.target.value) || 0 })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="sgst_rate">SGST Rate (%)</Label>
              <Input
                id="sgst_rate"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.sgst_rate || 0}
                onChange={(e) => setFormData({ ...formData, sgst_rate: Number(e.target.value) || 0 })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="igst_rate">IGST Rate (%)</Label>
              <Input
                id="igst_rate"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.igst_rate || 0}
                onChange={(e) => setFormData({ ...formData, igst_rate: Number(e.target.value) || 0 })}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="cess_rate">Cess Rate (%)</Label>
              <Input
                id="cess_rate"
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.cess_rate || 0}
                onChange={(e) => setFormData({ ...formData, cess_rate: Number(e.target.value) || 0 })}
              />
            </div>
          </div>

          {/* Calculated Values Display */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 p-4 bg-muted/50 rounded-lg">
            <div>
              <Label className="text-sm text-muted-foreground">Taxable Value</Label>
              <p className="text-lg font-semibold">₹{Number(formData.taxable_value || 0).toFixed(2)}</p>
            </div>
            <div>
              <Label className="text-sm text-muted-foreground">CGST</Label>
              <p className="text-lg font-semibold">₹{Number(formData.cgst_amount || 0).toFixed(2)}</p>
            </div>
            <div>
              <Label className="text-sm text-muted-foreground">SGST</Label>
              <p className="text-lg font-semibold">₹{Number(formData.sgst_amount || 0).toFixed(2)}</p>
            </div>
            <div>
              <Label className="text-sm text-muted-foreground">IGST</Label>
              <p className="text-lg font-semibold">₹{Number(formData.igst_amount || 0).toFixed(2)}</p>
            </div>
            <div>
              <Label className="text-sm text-muted-foreground">Cess</Label>
              <p className="text-lg font-semibold">₹{Number(formData.cess_amount || 0).toFixed(2)}</p>
            </div>
            <div className="col-span-2 md:col-span-1">
              <Label className="text-sm text-muted-foreground">Total Amount</Label>
              <p className="text-lg font-semibold text-primary">₹{Number(formData.total_amount || 0).toFixed(2)}</p>
            </div>
          </div>
        </div>

        <div className="flex justify-end space-x-2 pt-4 border-t">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button 
            onClick={handleSave}
            disabled={isSubmitting || loading}
          >
            {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
            {existingTransaction ? 'Update' : 'Create'} Transaction
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
};

import { useEffect, useState, useMemo, useRef } from 'react';
import { motion } from 'framer-motion';
import { Eye, EyeOff, Check, X, Mail } from 'lucide-react';
import { OnboardingFormData } from '../fragments/types';
import { cn } from '@/lib/utils';

/** Slugify name for email local part: lowercase, alphanumeric only */
function slugForEmail(name: string): string {
  return name.trim().toLowerCase().replace(/[^a-z0-9]/g, '');
}

/** Build company email from first + last name and domain (e.g. john.doe@acme.app) */
function buildCompanyEmail(first: string, last: string, domainFull: string): string {
  const firstPart = slugForEmail(first);
  const lastPart = slugForEmail(last);
  if (!domainFull) return '';
  const local = [firstPart, lastPart].filter(Boolean).join('.') || 'admin';
  return `${local}@${domainFull}`;
}

interface StepAdminProps {
  formData: OnboardingFormData;
  updateFormData: (updates: Partial<OnboardingFormData>) => void;
  setCanProceed: (can: boolean) => void;
}

export default function StepAdmin({ formData, updateFormData, setCanProceed }: StepAdminProps) {
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const domainFull = `${formData.domain || ''}${formData.domainSuffix || ''}`.toLowerCase();
  const companyEmail = useMemo(
    () => buildCompanyEmail(formData.adminFirstName, formData.adminLastName, domainFull),
    [formData.adminFirstName, formData.adminLastName, domainFull]
  );

  const migratedRef = useRef(false);
  // Migrate old draft: if adminName is set but first/last empty, split into first and last (once)
  useEffect(() => {
    if (migratedRef.current) return;
    const firstEmpty = !formData.adminFirstName?.trim();
    const lastEmpty = !formData.adminLastName?.trim();
    const nameFilled = formData.adminName?.trim();
    if (firstEmpty && lastEmpty && nameFilled) {
      migratedRef.current = true;
      const parts = nameFilled.split(/\s+/);
      const adminFirstName = parts[0] ?? '';
      const adminLastName = parts.slice(1).join(' ') ?? '';
      updateFormData({ adminFirstName, adminLastName });
    }
  }, [formData.adminName, formData.adminFirstName, formData.adminLastName, updateFormData]);

  // Sync derived adminName and adminEmail when first/last or domain change
  useEffect(() => {
    const name = [formData.adminFirstName, formData.adminLastName].filter(Boolean).join(' ').trim();
    const email = companyEmail;
    updateFormData({ adminName: name, adminEmail: email });
  }, [formData.adminFirstName, formData.adminLastName, companyEmail]);

  const validation = useMemo(() => {
    const passwordLength = formData.adminPassword.length >= 8;
    const passwordHasNumber = /\d/.test(formData.adminPassword);
    const passwordHasLetter = /[a-zA-Z]/.test(formData.adminPassword);
    const passwordsMatch = formData.adminPassword === formData.confirmPassword && formData.confirmPassword.length > 0;

    return {
      firstName: formData.adminFirstName.trim().length >= 1,
      lastName: formData.adminLastName.trim().length >= 1,
      email: companyEmail.length > 0 && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(companyEmail),
      passwordLength,
      passwordHasNumber,
      passwordHasLetter,
      passwordValid: passwordLength && passwordHasNumber && passwordHasLetter,
      passwordsMatch,
    };
  }, [formData.adminFirstName, formData.adminLastName, formData.adminPassword, formData.confirmPassword, companyEmail]);

  useEffect(() => {
    setCanProceed(!!(
      validation.firstName &&
      validation.lastName &&
      validation.email &&
      validation.passwordValid &&
      validation.passwordsMatch
    ));
  }, [validation, setCanProceed]);

  const inputClass = cn(
    "w-full h-11 px-3 rounded-md bg-white border border-zinc-300 text-zinc-900 dark:bg-zinc-900 dark:border-zinc-700 dark:text-zinc-100",
    "placeholder:text-zinc-400 focus:outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-500/20",
    "transition-shadow duration-200"
  );

  return (
    <div className="space-y-8">
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        <h1 className="text-3xl md:text-4xl font-medium text-zinc-900 dark:text-zinc-100 tracking-[-0.02em]">
          Create your account
        </h1>
        <p className="mt-3 text-lg text-zinc-600 dark:text-zinc-400 max-w-lg leading-relaxed">
          Set up the primary administrator account. You'll use this secure account to manage billing, team access, and system settings.
        </p>
      </motion.div>

      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5, delay: 0.1 }}
        className="space-y-5"
      >
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300">First Name</label>
            <input
              value={formData.adminFirstName}
              onChange={(e) => updateFormData({ adminFirstName: e.target.value })}
              placeholder="John"
              className={inputClass}
              autoComplete="given-name"
            />
          </div>
          <div className="space-y-2">
            <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300">Last Name</label>
            <input
              value={formData.adminLastName}
              onChange={(e) => updateFormData({ adminLastName: e.target.value })}
              placeholder="Smith"
              className={inputClass}
              autoComplete="family-name"
            />
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300 flex items-center gap-2">
            <Mail className="w-3.5 h-3.5" />
            Company email
          </label>
          <div
            className={cn(
              inputClass,
              "flex items-center text-zinc-500 cursor-default bg-zinc-50 dark:bg-zinc-800",
              !companyEmail && "text-zinc-400"
            )}
          >
            {companyEmail ? (
              <span className="truncate">{companyEmail}</span>
            ) : (
              <span>Enter first and last name — email will appear here</span>
            )}
          </div>
        </div>

        <div className="space-y-2">
          <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300">Password</label>
          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              value={formData.adminPassword}
              onChange={(e) => updateFormData({ adminPassword: e.target.value })}
              placeholder="Create a password"
              className={cn(inputClass, "pr-12")}
              autoComplete="new-password"
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              tabIndex={-1}
            >
              {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
          </div>

          {formData.adminPassword && (
            <div className="flex gap-4 text-xs pt-1.5 font-medium">
              <span className={cn("flex items-center gap-1", validation.passwordLength ? "text-green-600" : "text-zinc-500")}>
                {validation.passwordLength ? <Check className="w-3 h-3" /> : <X className="w-3 h-3 opacity-50" />}
                8+ chars
              </span>
              <span className={cn("flex items-center gap-1", validation.passwordHasLetter ? "text-green-600" : "text-zinc-500")}>
                {validation.passwordHasLetter ? <Check className="w-3 h-3" /> : <X className="w-3 h-3 opacity-50" />}
                Letters
              </span>
              <span className={cn("flex items-center gap-1", validation.passwordHasNumber ? "text-green-600" : "text-zinc-500")}>
                {validation.passwordHasNumber ? <Check className="w-3 h-3" /> : <X className="w-3 h-3 opacity-50" />}
                Numbers
              </span>
            </div>
          )}
        </div>

        <div className="space-y-2">
          <label className="text-sm font-medium text-zinc-700 dark:text-zinc-300">Confirm Password</label>
          <div className="relative">
            <input
              type={showConfirmPassword ? 'text' : 'password'}
              value={formData.confirmPassword}
              onChange={(e) => updateFormData({ confirmPassword: e.target.value })}
              placeholder="Confirm password"
              className={cn(
                inputClass, 
                "pr-12",
                formData.confirmPassword && !validation.passwordsMatch && "border-red-500/30"
              )}
              autoComplete="new-password"
            />
            <button
              type="button"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              className="absolute right-4 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              tabIndex={-1}
            >
              {showConfirmPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
          </div>

          {formData.confirmPassword && (
            <p className={cn(
              "text-xs flex items-center gap-1",
              validation.passwordsMatch ? "text-green-600" : "text-red-600"
            )}>
              {validation.passwordsMatch ? (
                <><Check className="w-3 h-3" /> Passwords match</>
              ) : (
                <><X className="w-3 h-3" /> Passwords don't match</>
              )}
            </p>
          )}
        </div>
      </motion.div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useAuth } from "@/hooks/useAuth";
import { getAccessibleEmployees } from "@/services/api/hr";
import { Loader2 } from "lucide-react";
import { selectRecords } from '@/services/api/core';

interface Employee {
  id: string;
  user_id: string;
  full_name: string;
  department: string | null;
}

interface EmployeeSelectorProps {
  selectedEmployeeId: string | null;
  onEmployeeChange: (employeeId: string) => void;
}

export function EmployeeSelector({ selectedEmployeeId, onEmployeeChange }: EmployeeSelectorProps) {
  const { user, userRole, profile, loading: authLoading } = useAuth();
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!authLoading && user && userRole !== undefined) {
      fetchEmployees();
    }
  }, [userRole, profile, authLoading, user]);

  const fetchEmployees = async () => {
    if (!user || !userRole) {
      setLoading(false);
      return;
    }

    try {
      setLoading(true);
      setError(null);
      
      // Check access level
      const fullAccessRoles = ['super_admin', 'agency_admin', 'manager'];
      
      if (fullAccessRoles.includes(userRole)) {
        // Full access - get all employees
        try {
          const allEmployees = await getAccessibleEmployees(userRole, null);
          setEmployees(allEmployees);
          
          // Auto-select current user if no selection
          if (!selectedEmployeeId && user.id) {
            const currentUserEmployee = allEmployees.find(emp => emp.user_id === user.id);
            if (currentUserEmployee) {
              onEmployeeChange(currentUserEmployee.user_id);
            }
          }
        } catch (err: unknown) {
          console.error('Error fetching all employees:', err);
          setError('Failed to load employees. Please try again.');
          // Fallback to self-only
          setEmployees([{
            id: user.id,
            user_id: user.id,
            full_name: profile?.full_name || 'You',
            department: profile?.department || null,
          }]);
        }
      } else {
        // Self-only access - only show current user
        setEmployees([{
          id: user.id,
          user_id: user.id,
          full_name: profile?.full_name || 'You',
          department: profile?.department || null,
        }]);
        
        // Auto-select
        if (!selectedEmployeeId) {
          onEmployeeChange(user.id);
        }
      }
    } catch (error: unknown) {
      console.error('Error fetching employees:', error);
      setError('Failed to load employees. Please refresh the page.');
      // Fallback to self-only
      if (user?.id) {
        setEmployees([{
          id: user.id,
          user_id: user.id,
          full_name: profile?.full_name || 'You',
          department: profile?.department || null,
        }]);
        if (!selectedEmployeeId) {
          onEmployeeChange(user.id);
        }
      }
    } finally {
      setLoading(false);
    }
  };

  if (authLoading || loading) {
    return (
      <div className="flex items-center gap-2">
        <Loader2 className="h-4 w-4 animate-spin" />
        <span className="text-sm text-muted-foreground">Loading employees...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className="text-sm text-destructive">
        {error}
      </div>
    );
  }

  if (!user) {
    return (
      <div className="text-sm text-muted-foreground">
        Please log in to view employees
      </div>
    );
  }

  // If only one employee (self-only access), don't show selector
  if (employees.length === 1 && employees[0].user_id === user?.id) {
    return (
      <div className="text-sm font-medium">
        {employees[0].full_name}
        {employees[0].department && (
          <span className="text-muted-foreground ml-2">({employees[0].department})</span>
        )}
      </div>
    );
  }

  return (
    <Select
      value={selectedEmployeeId || undefined}
      onValueChange={onEmployeeChange}
    >
      <SelectTrigger className="w-[250px]">
        <SelectValue placeholder="Select employee" />
      </SelectTrigger>
      <SelectContent>
        {employees.map((employee) => (
          <SelectItem key={employee.user_id} value={employee.user_id}>
            {employee.full_name}
            {employee.department && ` (${employee.department})`}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  );
}

