import { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { TaskPerformance } from "@/services/api/hr";
import { format } from "date-fns";
import { CheckCircle2, Clock, AlertCircle, XCircle, ExternalLink, ArrowUpDown } from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useToast } from "@/hooks/use-toast";

interface TaskPerformanceListProps {
  tasks: TaskPerformance[];
  loading?: boolean;
}

type TaskFilter = 'all' | 'completed' | 'in_progress' | 'overdue' | 'pending';
type SortField = 'title' | 'status' | 'priority' | 'assigned_date' | 'due_date' | 'completed_date';
type SortOrder = 'asc' | 'desc';

export function TaskPerformanceList({ tasks, loading }: TaskPerformanceListProps) {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [filter, setFilter] = useState<TaskFilter>('all');
  const [sortField, setSortField] = useState<SortField>('assigned_date');
  const [sortOrder, setSortOrder] = useState<SortOrder>('desc');

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Task Performance</CardTitle>
          <CardDescription>Loading tasks...</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2">
            {[...Array(5)].map((_, i) => (
              <div key={i} className="h-12 bg-muted rounded" />
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  // Filter tasks
  const filteredTasks = tasks.filter(task => {
    if (filter === 'all') return true;
    if (filter === 'completed') return task.status === 'completed';
    if (filter === 'in_progress') return task.status === 'in_progress';
    if (filter === 'overdue') return task.completion_status === 'overdue';
    if (filter === 'pending') return task.status === 'pending' || task.status === 'todo';
    return true;
  });

  // Sort tasks
  const sortedTasks = [...filteredTasks].sort((a, b) => {
    let aValue: unknown;
    let bValue: unknown;

    switch (sortField) {
      case 'title':
        aValue = a.title.toLowerCase();
        bValue = b.title.toLowerCase();
        break;
      case 'status':
        aValue = a.status;
        bValue = b.status;
        break;
      case 'priority':
        const priorityOrder: Record<string, number> = { urgent: 4, high: 3, medium: 2, low: 1 };
        aValue = priorityOrder[a.priority] || 0;
        bValue = priorityOrder[b.priority] || 0;
        break;
      case 'assigned_date':
        aValue = a.assigned_date ? new Date(a.assigned_date).getTime() : 0;
        bValue = b.assigned_date ? new Date(b.assigned_date).getTime() : 0;
        break;
      case 'due_date':
        aValue = a.due_date ? new Date(a.due_date).getTime() : 0;
        bValue = b.due_date ? new Date(b.due_date).getTime() : 0;
        break;
      case 'completed_date':
        aValue = a.completed_date ? new Date(a.completed_date).getTime() : 0;
        bValue = b.completed_date ? new Date(b.completed_date).getTime() : 0;
        break;
      default:
        return 0;
    }

    if (aValue < bValue) return sortOrder === 'asc' ? -1 : 1;
    if (aValue > bValue) return sortOrder === 'asc' ? 1 : -1;
    return 0;
  });

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
    } else {
      setSortField(field);
      setSortOrder('desc');
    }
  };

  const handleTaskClick = (taskId: string) => {
    // Navigate to project management page - tasks are in the tasks tab
    navigate(`/project-management`);
    toast({
      title: "Navigate to Tasks Tab",
      description: "Please switch to the 'Tasks' tab in Project Management to view all tasks.",
    });
  };

  if (tasks.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Task Performance</CardTitle>
          <CardDescription>No tasks found for the selected period</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="text-center py-8 text-muted-foreground">
            No tasks assigned during this period
          </div>
        </CardContent>
      </Card>
    );
  }

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed':
        return <CheckCircle2 className="h-4 w-4 text-green-600" />;
      case 'in_progress':
        return <Clock className="h-4 w-4 text-blue-600" />;
      case 'overdue':
        return <AlertCircle className="h-4 w-4 text-red-600" />;
      default:
        return <XCircle className="h-4 w-4 text-gray-400" />;
    }
  };

  const getPriorityBadge = (priority: string) => {
    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
      urgent: 'destructive',
      high: 'destructive',
      medium: 'secondary',
      low: 'outline',
    };
    return (
      <Badge variant={variants[priority] || 'outline'}>
        {priority}
      </Badge>
    );
  };

  const getCompletionStatusBadge = (status: TaskPerformance['completion_status']) => {
    const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
      'on-time': 'default',
      'late': 'secondary',
      'overdue': 'destructive',
      'pending': 'outline',
    };
    return (
      <Badge variant={variants[status] || 'outline'}>
        {status.replace('-', ' ')}
      </Badge>
    );
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex flex-col space-y-4 lg:flex-row lg:justify-between lg:items-center lg:space-y-0">
          <div>
            <CardTitle>Task Performance</CardTitle>
            <CardDescription>
              {filteredTasks.length} of {tasks.length} task{tasks.length !== 1 ? 's' : ''} shown
            </CardDescription>
          </div>
          <div className="flex gap-2">
            <Select value={filter} onValueChange={(value: TaskFilter) => setFilter(value)}>
              <SelectTrigger className="w-[150px]">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Tasks</SelectItem>
                <SelectItem value="completed">Completed</SelectItem>
                <SelectItem value="in_progress">In Progress</SelectItem>
                <SelectItem value="overdue">Overdue</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('title')}
                  >
                    Task
                    {sortField === 'title' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>Project</TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('status')}
                  >
                    Status
                    {sortField === 'status' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('priority')}
                  >
                    Priority
                    {sortField === 'priority' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('assigned_date')}
                  >
                    Assigned
                    {sortField === 'assigned_date' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('due_date')}
                  >
                    Due Date
                    {sortField === 'due_date' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-8 -ml-3"
                    onClick={() => handleSort('completed_date')}
                  >
                    Completed
                    {sortField === 'completed_date' && (
                      <ArrowUpDown className="ml-2 h-3 w-3" />
                    )}
                  </Button>
                </TableHead>
                <TableHead>Hours</TableHead>
                <TableHead>Completion</TableHead>
                <TableHead className="w-[50px]">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sortedTasks.map((task) => (
                <TableRow key={task.id} className="cursor-pointer hover:bg-accent" onClick={() => handleTaskClick(task.id)}>
                  <TableCell className="font-medium">{task.title}</TableCell>
                  <TableCell>{task.project_name || 'No Project'}</TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      {getStatusIcon(task.status)}
                      <span className="capitalize">{task.status.replace('_', ' ')}</span>
                    </div>
                  </TableCell>
                  <TableCell>{getPriorityBadge(task.priority)}</TableCell>
                  <TableCell>
                    {task.assigned_date
                      ? format(new Date(task.assigned_date), 'MMM dd, yyyy')
                      : '-'}
                  </TableCell>
                  <TableCell>
                    {task.due_date
                      ? format(new Date(task.due_date), 'MMM dd, yyyy')
                      : '-'}
                  </TableCell>
                  <TableCell>
                    {task.completed_date
                      ? format(new Date(task.completed_date), 'MMM dd, yyyy')
                      : '-'}
                  </TableCell>
                  <TableCell>
                    <div className="text-sm">
                      {task.estimated_hours && (
                        <div>Est: {task.estimated_hours}h</div>
                      )}
                      {task.actual_hours && (
                        <div>Act: {task.actual_hours}h</div>
                      )}
                      {task.time_taken_hours && (
                        <div className="text-muted-foreground">
                          Took: {task.time_taken_hours.toFixed(1)}h
                        </div>
                      )}
                    </div>
                  </TableCell>
                  <TableCell>
                    {getCompletionStatusBadge(task.completion_status)}
                  </TableCell>
                  <TableCell>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleTaskClick(task.id);
                      }}
                    >
                      <ExternalLink className="h-4 w-4" />
                    </Button>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import * as auditService from '@/services/api/audit';
import { toast } from 'sonner';
import { Download, Search, Loader2, Calendar } from 'lucide-react';

export function AuditLogViewer() {
  const [logs, setLogs] = useState<auditService.AuditLog[]>([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [filters, setFilters] = useState({
    table_name: '',
    action: '',
    user_id: '',
    start_date: '',
    end_date: '',
    search: '',
  });

  useEffect(() => {
    fetchLogs();
  }, [page, filters]);

  const fetchLogs = async () => {
    setLoading(true);
    try {
      const result = await auditService.getAuditLogs({
        page,
        limit: 50,
        ...filters,
      });
      setLogs(result.data);
      if (result.pagination) {
        setTotalPages(result.pagination.totalPages);
      }
    } catch (error: unknown) {
      // If API is not available, show empty state gracefully
      console.warn('Audit logs API not available:', error);
      setLogs([]);
      setTotalPages(1);
      // Don't show error toast for 404s - API might not be set up yet
      if (!error.message?.includes('404')) {
        toast.error(error.message || 'Failed to load audit logs');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleExport = async (format: 'json' | 'csv' = 'json') => {
    try {
      const result = await auditService.exportAuditLogs({
        format,
        start_date: filters.start_date || undefined,
        end_date: filters.end_date || undefined,
      });

      if (format === 'csv' && result instanceof Blob) {
        const url = window.URL.createObjectURL(result);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit_logs_${Date.now()}.csv`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
      } else if (Array.isArray(result)) {
        const dataStr = JSON.stringify(result, null, 2);
        const dataBlob = new Blob([dataStr], { type: 'application/json' });
        const url = window.URL.createObjectURL(dataBlob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit_logs_${Date.now()}.json`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
      }

      toast.success('Audit logs exported successfully');
    } catch (error: unknown) {
      toast.error(error.message || 'Failed to export audit logs');
    }
  };

  const getActionBadgeVariant = (action: string) => {
    switch (action.toUpperCase()) {
      case 'INSERT':
        return 'default';
      case 'UPDATE':
        return 'secondary';
      case 'DELETE':
        return 'destructive';
      default:
        return 'outline';
    }
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Audit Log</CardTitle>
            <CardDescription>
              View all permission changes and system activities
            </CardDescription>
          </div>
          <div className="flex gap-2">
            <Button variant="outline" size="sm" onClick={() => handleExport('json')}>
              <Download className="mr-2 h-4 w-4" />
              Export JSON
            </Button>
            <Button variant="outline" size="sm" onClick={() => handleExport('csv')}>
              <Download className="mr-2 h-4 w-4" />
              Export CSV
            </Button>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <Input
              placeholder="Search..."
              value={filters.search}
              onChange={(e) => setFilters(prev => ({ ...prev, search: e.target.value }))}
            />
          </div>
          <div>
            <Select
              value={filters.table_name || 'all'}
              onValueChange={(value) => setFilters(prev => ({ ...prev, table_name: value === 'all' ? '' : value }))}
            >
              <SelectTrigger>
                <SelectValue placeholder="Table" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Tables</SelectItem>
                <SelectItem value="role_permissions">Role Permissions</SelectItem>
                <SelectItem value="user_permissions">User Permissions</SelectItem>
                <SelectItem value="permissions">Permissions</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Select
              value={filters.action || 'all'}
              onValueChange={(value) => setFilters(prev => ({ ...prev, action: value === 'all' ? '' : value }))}
            >
              <SelectTrigger>
                <SelectValue placeholder="Action" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Actions</SelectItem>
                <SelectItem value="INSERT">Insert</SelectItem>
                <SelectItem value="UPDATE">Update</SelectItem>
                <SelectItem value="DELETE">Delete</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div>
            <Input
              type="date"
              placeholder="Start Date"
              value={filters.start_date}
              onChange={(e) => setFilters(prev => ({ ...prev, start_date: e.target.value }))}
            />
          </div>
          <div>
            <Input
              type="date"
              placeholder="End Date"
              value={filters.end_date}
              onChange={(e) => setFilters(prev => ({ ...prev, end_date: e.target.value }))}
            />
          </div>
        </div>

        {loading ? (
          <div className="flex items-center justify-center p-8">
            <Loader2 className="h-6 w-6 animate-spin" />
          </div>
        ) : (
          <>
            <div className="border rounded-lg overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Timestamp</TableHead>
                    <TableHead>Table</TableHead>
                    <TableHead>Action</TableHead>
                    <TableHead>User</TableHead>
                    <TableHead>Changes</TableHead>
                    <TableHead>IP Address</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {logs.map(log => (
                    <TableRow key={log.id}>
                      <TableCell>
                        {new Date(log.created_at).toLocaleString()}
                      </TableCell>
                      <TableCell>
                        <Badge variant="outline">{log.table_name}</Badge>
                      </TableCell>
                      <TableCell>
                        <Badge variant={getActionBadgeVariant(log.action)}>
                          {log.action}
                        </Badge>
                      </TableCell>
                      <TableCell>{log.user_id || 'System'}</TableCell>
                      <TableCell>
                        <div className="max-w-xs truncate">
                          {log.old_values && log.new_values ? (
                            <span className="text-sm text-muted-foreground">
                              Updated
                            </span>
                          ) : log.new_values ? (
                            <span className="text-sm text-green-600">Created</span>
                          ) : (
                            <span className="text-sm text-red-600">Deleted</span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-sm text-muted-foreground">
                        {log.ip_address || '-'}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>

            {logs.length === 0 && (
              <div className="text-center py-8 text-muted-foreground">
                No audit logs found matching your filters.
              </div>
            )}

            {totalPages > 1 && (
              <div className="flex items-center justify-between">
                <Button
                  variant="outline"
                  onClick={() => setPage(prev => Math.max(1, prev - 1))}
                  disabled={page === 1}
                >
                  Previous
                </Button>
                <span className="text-sm text-muted-foreground">
                  Page {page} of {totalPages}
                </span>
                <Button
                  variant="outline"
                  onClick={() => setPage(prev => Math.min(totalPages, prev + 1))}
                  disabled={page === totalPages}
                >
                  Next
                </Button>
              </div>
            )}
          </>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * Task Kanban Board
 * Comprehensive task management with multiple views and full functionality
 */

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { 
  Clock, 
  Calendar, 
  User, 
  MoreVertical, 
  Edit, 
  Trash2, 
  Search,
  Filter,
  List,
  Kanban as KanbanIcon,
  Calendar as CalendarIcon,
  GanttChart,
  Eye
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { TaskFormDialog } from "@/components/shared/TaskFormDialog";
import { projectService, Task } from "@/services/api/projects";
import { format } from "date-fns";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

const statusColumns = [
  { id: 'todo', title: 'To Do', color: 'bg-slate-100' },
  { id: 'in_progress', title: 'In Progress', color: 'bg-blue-100' },
  { id: 'in_review', title: 'In Review', color: 'bg-yellow-100' },
  { id: 'blocked', title: 'Blocked', color: 'bg-orange-100' },
  { id: 'completed', title: 'Completed', color: 'bg-green-100' },
];

const priorityColors: Record<string, string> = {
  low: 'bg-gray-100 text-gray-800',
  medium: 'bg-blue-100 text-blue-800',
  high: 'bg-orange-100 text-orange-800',
  critical: 'bg-red-100 text-red-800',
  urgent: 'bg-red-100 text-red-800',
};

interface TaskKanbanBoardProps {
  projectId?: string;
}

type ViewMode = 'kanban' | 'list' | 'calendar' | 'timeline';

export function TaskKanbanBoard({ projectId }: TaskKanbanBoardProps) {
  const navigate = useNavigate();
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [deleteTask, setDeleteTask] = useState<Task | null>(null);
  const [viewMode, setViewMode] = useState<ViewMode>('kanban');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [assigneeFilter, setAssigneeFilter] = useState<string>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const { toast } = useToast();
  const { user, profile } = useAuth();

  useEffect(() => {
    fetchTasks();
  }, [projectId]);

  const fetchTasks = async () => {
    setLoading(true);
    try {
      const filters: unknown = {};
      if (projectId) {
        filters.project_id = projectId;
      }
      if (statusFilter !== 'all') {
        filters.status = [statusFilter];
      }
      if (priorityFilter !== 'all') {
        filters.priority = [priorityFilter];
      }
      if (assigneeFilter !== 'all') {
        filters.assignee_id = assigneeFilter;
      }
      if (searchTerm) {
        filters.search = searchTerm;
      }
      
      const data = await projectService.getTasks(filters, profile, user?.id);
      setTasks(data || []);
    } catch (error: unknown) {
      console.error('Error fetching tasks:', error);
      toast({
        title: "Error",
        description: error.message || "Failed to fetch tasks",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const updateTaskStatus = async (taskId: string, newStatus: Task['status']) => {
    try {
      await projectService.updateTask(taskId, { 
        status: newStatus,
        completed_at: newStatus === 'completed' ? new Date().toISOString() : null
      } as unknown, profile, user?.id);

      setTasks(tasks.map(task => 
        task.id === taskId ? { ...task, status: newStatus } : task
      ));

      toast({
        title: "Success",
        description: "Task status updated successfully",
      });
    } catch (error: unknown) {
      toast({
        title: "Error",
        description: error.message || "Failed to update task status",
        variant: "destructive",
      });
    }
  };

  const handleDeleteTask = async () => {
    if (!deleteTask) return;

    try {
      await projectService.deleteTask(deleteTask.id, profile, user?.id);
      setTasks(tasks.filter(task => task.id !== deleteTask.id));
      setDeleteTask(null);
      toast({
        title: "Success",
        description: "Task deleted successfully",
      });
    } catch (error: unknown) {
      toast({
        title: "Error",
        description: error.message || "Failed to delete task",
        variant: "destructive",
      });
    }
  };

  const onDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData("text/plain", taskId);
  };

  const onDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const onDrop = (e: React.DragEvent, status: Task['status']) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData("text/plain");
    const task = tasks.find(t => t.id === taskId);
    
    if (task && task.status !== status) {
      updateTaskStatus(taskId, status);
    }
  };

  // Get unique assignees for filter
  const assignees = Array.from(new Set(
    tasks
      .map(t => t.assignee_id)
      .filter(Boolean)
      .concat(
        tasks.flatMap(t => t.assignments?.map(a => a.user_id) || [])
      )
  ));

  const filteredTasks = tasks.filter(task => {
    if (statusFilter !== 'all' && task.status !== statusFilter) return false;
    if (priorityFilter !== 'all' && task.priority !== priorityFilter) return false;
    if (assigneeFilter !== 'all') {
      if (task.assignee_id !== assigneeFilter && 
          !task.assignments?.some(a => a.user_id === assigneeFilter)) {
        return false;
      }
    }
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase();
      return (
        task.title.toLowerCase().includes(searchLower) ||
        task.description?.toLowerCase().includes(searchLower) ||
        task.project?.name?.toLowerCase().includes(searchLower)
      );
    }
    return true;
  });

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with Filters and Views */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center space-x-2 flex-1 min-w-[300px]">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search tasks..."
              value={searchTerm}
              onChange={(e) => {
                setSearchTerm(e.target.value);
                fetchTasks();
              }}
              className="pl-8"
            />
          </div>
          <Select value={statusFilter} onValueChange={(value) => {
            setStatusFilter(value);
            fetchTasks();
          }}>
            <SelectTrigger className="w-[150px]">
              <Filter className="h-4 w-4 mr-2" />
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              {statusColumns.map(col => (
                <SelectItem key={col.id} value={col.id}>{col.title}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={priorityFilter} onValueChange={(value) => {
            setPriorityFilter(value);
            fetchTasks();
          }}>
            <SelectTrigger className="w-[130px]">
              <SelectValue placeholder="Priority" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Priority</SelectItem>
              <SelectItem value="low">Low</SelectItem>
              <SelectItem value="medium">Medium</SelectItem>
              <SelectItem value="high">High</SelectItem>
              <SelectItem value="critical">Critical</SelectItem>
              <SelectItem value="urgent">Urgent</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant={viewMode === 'kanban' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setViewMode('kanban')}
          >
            <KanbanIcon className="h-4 w-4 mr-2" />
            Kanban
          </Button>
          <Button
            variant={viewMode === 'list' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setViewMode('list')}
          >
            <List className="h-4 w-4 mr-2" />
            List
          </Button>
          <Button
            variant={viewMode === 'calendar' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setViewMode('calendar')}
          >
            <CalendarIcon className="h-4 w-4 mr-2" />
            Calendar
          </Button>
          <TaskFormDialog onTaskSaved={fetchTasks} projectId={projectId} />
        </div>
      </div>

      {/* Kanban View */}
      {viewMode === 'kanban' && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          {statusColumns.map((column) => (
            <div
              key={column.id}
              className={`${column.color} rounded-lg p-4 min-h-[500px]`}
              onDragOver={onDragOver}
              onDrop={(e) => onDrop(e, column.id as Task['status'])}
            >
              <h4 className="font-medium mb-4 flex items-center justify-between">
                {column.title}
                <Badge variant="secondary">
                  {filteredTasks.filter(task => task.status === column.id).length}
                </Badge>
              </h4>

              <div className="space-y-3">
                {filteredTasks
                  .filter(task => task.status === column.id)
                  .map((task) => (
                    <Card
                      key={task.id}
                      className="cursor-move hover:shadow-md transition-shadow bg-white"
                      draggable
                      onDragStart={(e) => onDragStart(e, task.id)}
                    >
                      <CardHeader className="pb-2">
                        <div className="flex items-start justify-between">
                          <CardTitle 
                            className="text-sm font-medium line-clamp-2 cursor-pointer"
                            onClick={() => navigate(`/tasks/${task.id}`)}
                          >
                            {task.title}
                          </CardTitle>
                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                                <MoreVertical className="h-3 w-3" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem onClick={() => navigate(`/tasks/${task.id}`)}>
                                <Eye className="h-4 w-4 mr-2" />
                                View Details
                              </DropdownMenuItem>
                              <DropdownMenuItem asChild>
                                <TaskFormDialog
                                  task={task}
                                  onTaskSaved={fetchTasks}
                                  trigger={
                                    <div className="flex items-center cursor-pointer w-full">
                                      <Edit className="h-4 w-4 mr-2" />
                                      Edit
                                    </div>
                                  }
                                />
                              </DropdownMenuItem>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                className="text-red-600"
                                onClick={() => setDeleteTask(task)}
                              >
                                <Trash2 className="h-4 w-4 mr-2" />
                                Delete
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </div>
                      </CardHeader>
                      <CardContent className="pt-0 space-y-2">
                        {task.description && (
                          <p className="text-xs text-muted-foreground line-clamp-2">
                            {task.description}
                          </p>
                        )}

                        <div className="flex items-center justify-between">
                          <Badge
                            variant="secondary"
                            className={priorityColors[task.priority] || priorityColors.medium}
                          >
                            {task.priority}
                          </Badge>

                          {task.estimated_hours && (
                            <div className="flex items-center text-xs text-muted-foreground">
                              <Clock className="h-3 w-3 mr-1" />
                              {task.estimated_hours}h
                            </div>
                          )}
                        </div>

                        {task.due_date && (
                          <div className="flex items-center text-xs text-muted-foreground">
                            <Calendar className="h-3 w-3 mr-1" />
                            {format(new Date(task.due_date), "MMM dd")}
                          </div>
                        )}

                        {task.project?.name && (
                          <Badge variant="outline" className="text-xs">
                            {task.project.name}
                          </Badge>
                        )}

                        {/* Show assignees */}
                        {task.assignments && task.assignments.length > 0 && (
                          <div className="flex items-center gap-1 flex-wrap">
                            {task.assignments.slice(0, 3).map((assignment) => (
                              <Avatar key={assignment.id} className="h-5 w-5">
                                <AvatarImage src={assignment.user?.avatar_url} />
                                <AvatarFallback className="text-xs">
                                  {assignment.user?.full_name?.charAt(0) || 'U'}
                                </AvatarFallback>
                              </Avatar>
                            ))}
                            {task.assignments.length > 3 && (
                              <span className="text-xs text-muted-foreground">
                                +{task.assignments.length - 3}
                              </span>
                            )}
                          </div>
                        )}
                        {task.assignee_id && (!task.assignments || task.assignments.length === 0) && (
                          <div className="flex items-center text-xs">
                            <Avatar className="h-5 w-5 mr-2">
                              <AvatarImage src={task.assignee?.avatar_url} />
                              <AvatarFallback>
                                {task.assignee?.full_name?.charAt(0) || 'U'}
                              </AvatarFallback>
                            </Avatar>
                            <span className="truncate">{task.assignee?.full_name || 'Unassigned'}</span>
                          </div>
                        )}
                      </CardContent>
                    </Card>
                  ))}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* List View */}
      {viewMode === 'list' && (
        <Card>
          <CardContent className="p-0">
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead>
                  <tr className="border-b">
                    <th className="text-left p-4">Task</th>
                    <th className="text-left p-4">Project</th>
                    <th className="text-left p-4">Status</th>
                    <th className="text-left p-4">Priority</th>
                    <th className="text-left p-4">Assignees</th>
                    <th className="text-left p-4">Due Date</th>
                    <th className="text-left p-4">Hours</th>
                    <th className="text-left p-4">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredTasks.map((task) => (
                    <tr key={task.id} className="border-b hover:bg-muted/50">
                      <td className="p-4">
                        <div>
                          <p className="font-medium">{task.title}</p>
                          {task.description && (
                            <p className="text-sm text-muted-foreground line-clamp-1">
                              {task.description}
                            </p>
                          )}
                        </div>
                      </td>
                      <td className="p-4">
                        {task.project?.name || '-'}
                      </td>
                      <td className="p-4">
                        <Badge className={statusColumns.find(c => c.id === task.status)?.color || 'bg-gray-100'}>
                          {task.status.replace('_', ' ')}
                        </Badge>
                      </td>
                      <td className="p-4">
                        <Badge variant="outline" className={priorityColors[task.priority] || priorityColors.medium}>
                          {task.priority}
                        </Badge>
                      </td>
                      <td className="p-4">
                        <div className="flex items-center gap-1">
                          {task.assignments && task.assignments.length > 0 ? (
                            <>
                              {task.assignments.slice(0, 3).map((assignment) => (
                                <Avatar key={assignment.id} className="h-6 w-6">
                                  <AvatarImage src={assignment.user?.avatar_url} />
                                  <AvatarFallback className="text-xs">
                                    {assignment.user?.full_name?.charAt(0) || 'U'}
                                  </AvatarFallback>
                                </Avatar>
                              ))}
                              {task.assignments.length > 3 && (
                                <span className="text-xs">+{task.assignments.length - 3}</span>
                              )}
                            </>
                          ) : task.assignee_id ? (
                            <Avatar className="h-6 w-6">
                              <AvatarImage src={task.assignee?.avatar_url} />
                              <AvatarFallback className="text-xs">
                                {task.assignee?.full_name?.charAt(0) || 'U'}
                              </AvatarFallback>
                            </Avatar>
                          ) : (
                            <span className="text-sm text-muted-foreground">Unassigned</span>
                          )}
                        </div>
                      </td>
                      <td className="p-4">
                        {task.due_date ? format(new Date(task.due_date), "MMM dd, yyyy") : '-'}
                      </td>
                      <td className="p-4">
                        {task.estimated_hours ? `${task.estimated_hours}h` : '-'}
                      </td>
                      <td className="p-4">
                        <div className="flex items-center space-x-2">
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => navigate(`/tasks/${task.id}`)}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <TaskFormDialog
                            task={task}
                            onTaskSaved={fetchTasks}
                            trigger={
                              <Button variant="ghost" size="sm">
                                <Edit className="h-4 w-4" />
                              </Button>
                            }
                          />
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setDeleteTask(task)}
                          >
                            <Trash2 className="h-4 w-4 text-red-600" />
                          </Button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {filteredTasks.length === 0 && (
                <div className="text-center py-12 text-muted-foreground">
                  No tasks found. Create your first task to get started.
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Calendar View */}
      {viewMode === 'calendar' && (
        <Card>
          <CardHeader>
            <CardTitle>Task Calendar</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-center py-8 text-muted-foreground">
              Calendar view coming soon...
            </div>
          </CardContent>
        </Card>
      )}

      {/* Timeline View */}
      {viewMode === 'timeline' && (
        <Card>
          <CardHeader>
            <CardTitle>Task Timeline</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-center py-8 text-muted-foreground">
              Timeline view coming soon...
            </div>
          </CardContent>
        </Card>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={!!deleteTask} onOpenChange={() => setDeleteTask(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Task</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{deleteTask?.title}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteTask} className="bg-red-600 hover:bg-red-700">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { useAuth } from '@/hooks/useAuth';
import { generateUUID } from '@/lib/uuid';
import { getAgencyId } from '@/utils/agencyUtils';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';

interface Activity {
  id?: string;
  lead_id?: string;
  client_id?: string;
  activity_type: string;
  subject: string;
  description?: string;
  status: string;
  due_date: string;
  completed_date?: string;
  assigned_to?: string;
  duration?: number;
  outcome?: string;
  location?: string;
  agenda?: string;
  attendees?: string[];
}

interface ActivityFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  activity?: Activity | null;
  leadId?: string;
  onActivitySaved: () => void;
}

const formatDateTimeLocal = (dateString?: string): string => {
  if (!dateString) return '';
  try {
    const date = new Date(dateString);
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}`;
  } catch {
    return '';
  }
};

const ActivityFormDialog: React.FC<ActivityFormDialogProps> = ({ 
  isOpen, 
  onClose, 
  activity, 
  leadId,
  onActivitySaved 
}) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [leads, setLeads] = useState<unknown[]>([]);
  const [employees, setEmployees] = useState<Array<{ id: string; full_name: string }>>([]);
  const [formData, setFormData] = useState<Activity>({
    lead_id: activity?.lead_id || leadId || '',
    client_id: activity?.client_id || '',
    activity_type: activity?.activity_type || 'call',
    subject: activity?.subject || '',
    description: activity?.description || '',
    status: activity?.status || 'pending',
    due_date: activity?.due_date || '',
    completed_date: activity?.completed_date || '',
    assigned_to: activity?.assigned_to || '',
    duration: activity?.duration || undefined,
    outcome: activity?.outcome || '',
    location: activity?.location || '',
    agenda: activity?.agenda || '',
    attendees: activity?.attendees || [],
  });

  useEffect(() => {
    if (isOpen) {
      fetchLeads();
      fetchEmployees();
      if (activity && activity.id) {
        setFormData({
          lead_id: activity.lead_id || '',
          client_id: activity.client_id || '',
          activity_type: activity.activity_type || 'call',
          subject: activity.subject || '',
          description: activity.description || '',
          status: activity.status || 'pending',
          due_date: activity.due_date || '',
          completed_date: activity.completed_date || '',
          assigned_to: activity.assigned_to || '',
          duration: activity.duration || undefined,
          outcome: activity.outcome || '',
          location: activity.location || '',
          agenda: activity.agenda || '',
          attendees: activity.attendees || [],
        });
      } else {
        setFormData({
          lead_id: leadId || activity?.lead_id || '',
          client_id: '',
          activity_type: 'call',
          subject: '',
          description: '',
          status: 'pending',
          due_date: '',
          completed_date: '',
          assigned_to: '',
          duration: undefined,
          outcome: '',
          location: '',
          agenda: '',
          attendees: [],
        });
      }
    }
  }, [isOpen, activity, leadId]);

  const fetchLeads = async () => {
    try {
      const { data, error } = await db
        .from('leads')
        .select('id, company_name, lead_number')
        .order('company_name', { ascending: true });
      
      if (error) throw error;
      setLeads(data || []);
    } catch (error) {
      console.error('Error fetching leads:', error);
    }
  };

  const fetchEmployees = async () => {
    try {
      const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
      setEmployees(employeesData.map(emp => ({
        id: emp.user_id,
        full_name: emp.full_name
      })));
    } catch (error) {
      console.error('Error fetching employees:', error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId || !user?.id) {
        toast({
          title: 'Error',
          description: 'Agency ID or User ID not found. Please ensure you are logged in.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }
      const userId = user.id;

      if (activity?.id) {
        const updateData: unknown = {
          lead_id: (formData.lead_id && formData.lead_id !== '__none__') ? formData.lead_id : null,
          client_id: formData.client_id || null,
          activity_type: formData.activity_type,
          subject: formData.subject,
          description: formData.description || null,
          status: formData.status,
          due_date: formData.due_date || null,
          completed_date: formData.completed_date || null,
          assigned_to: formData.assigned_to || null,
          duration: formData.duration || null,
          outcome: formData.outcome || null,
          location: formData.location || null,
          agenda: formData.agenda || null,
          attendees: formData.attendees && formData.attendees.length > 0 ? formData.attendees : null,
          updated_at: new Date().toISOString(),
        };

        // If status is completed and completed_date is not set, set it
        if (formData.status === 'completed' && !formData.completed_date) {
          updateData.completed_date = new Date().toISOString();
        }

        // Ensure activity_date is set (use due_date if available, otherwise current time)
        if (!updateData.activity_date) {
          updateData.activity_date = formData.due_date || new Date().toISOString();
        }

        const { data, error } = await db
          .from('crm_activities')
          .update(updateData)
          .eq('id', activity.id)
          .select()
          .single();

        if (error) throw error;

        toast({
          title: 'Success',
          description: 'Activity updated successfully',
        });
      } else {
        const { data, error } = await db
          .from('crm_activities')
          .insert([{
            id: generateUUID(),
            lead_id: (formData.lead_id && formData.lead_id !== '__none__') ? formData.lead_id : null,
            client_id: formData.client_id || null,
            activity_type: formData.activity_type,
            subject: formData.subject,
            description: formData.description || null,
            status: formData.status,
            activity_date: formData.due_date || new Date().toISOString(),
            due_date: formData.due_date || null,
            completed_date: formData.completed_date || null,
            assigned_to: formData.assigned_to || null,
            duration: formData.duration || null,
            outcome: formData.outcome || null,
            location: formData.location || null,
            agenda: formData.agenda || null,
            attendees: formData.attendees && formData.attendees.length > 0 ? formData.attendees : null,
            created_by: userId,
            agency_id: agencyId,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          }])
          .select()
          .single();

        if (error) throw error;

        toast({
          title: 'Success',
          description: 'Activity created successfully',
        });
      }

      onActivitySaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving activity:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save activity',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{activity?.id ? 'Edit Activity' : 'Create New Activity'}</DialogTitle>
          <DialogDescription>
            {activity?.id ? 'Update activity details below.' : 'Fill in the details to create a new activity.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="lead_id">Lead</Label>
              <Select 
                value={formData.lead_id || undefined} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, lead_id: value === '__none__' ? '' : value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select lead (optional)" />
                </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">None</SelectItem>
                {leads.map((lead) => (
                  <SelectItem key={lead.id} value={lead.id}>
                    {lead.lead_number} - {lead.company_name}
                  </SelectItem>
                ))}
              </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="activity_type">Activity Type</Label>
              <Select 
                value={formData.activity_type} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, activity_type: value }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="call">Call</SelectItem>
                  <SelectItem value="email">Email</SelectItem>
                  <SelectItem value="meeting">Meeting</SelectItem>
                  <SelectItem value="task">Task</SelectItem>
                  <SelectItem value="note">Note</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="subject">Subject *</Label>
            <Input
              id="subject"
              value={formData.subject}
              onChange={(e) => setFormData(prev => ({ ...prev, subject: e.target.value }))}
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={3}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select 
                value={formData.status} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="due_date">Due Date & Time</Label>
              <Input
                id="due_date"
                type="datetime-local"
                value={formatDateTimeLocal(formData.due_date)}
                onChange={(e) => {
                  if (e.target.value) {
                    // Convert local datetime to ISO string
                    const localDate = new Date(e.target.value);
                    setFormData(prev => ({ ...prev, due_date: localDate.toISOString() }));
                  } else {
                    setFormData(prev => ({ ...prev, due_date: '' }));
                  }
                }}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="assigned_to">Assigned To</Label>
            <Select 
              value={formData.assigned_to || undefined} 
              onValueChange={(value) => setFormData(prev => ({ ...prev, assigned_to: value === '__none__' ? '' : value }))}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select employee (optional)" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">None</SelectItem>
                {employees.map((emp) => (
                  <SelectItem key={emp.id} value={emp.id}>
                    {emp.full_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {formData.status === 'completed' && (
            <div className="space-y-2">
              <Label htmlFor="completed_date">Completed Date & Time</Label>
              <Input
                id="completed_date"
                type="datetime-local"
                value={formatDateTimeLocal(formData.completed_date)}
                onChange={(e) => {
                  if (e.target.value) {
                    const localDate = new Date(e.target.value);
                    setFormData(prev => ({ ...prev, completed_date: localDate.toISOString() }));
                  } else {
                    setFormData(prev => ({ ...prev, completed_date: '' }));
                  }
                }}
              />
            </div>
          )}

          {formData.activity_type === 'meeting' && (
            <>
              <div className="space-y-2">
                <Label htmlFor="location">Location</Label>
                <Input
                  id="location"
                  value={formData.location || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
                  placeholder="Meeting location"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="agenda">Agenda</Label>
                <Textarea
                  id="agenda"
                  value={formData.agenda || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, agenda: e.target.value }))}
                  rows={3}
                  placeholder="Meeting agenda"
                />
              </div>
            </>
          )}

          {formData.activity_type === 'call' && (
            <div className="space-y-2">
              <Label htmlFor="duration">Duration (minutes)</Label>
              <Input
                id="duration"
                type="number"
                value={formData.duration || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, duration: Number(e.target.value) || null }))}
                placeholder="Call duration in minutes"
              />
            </div>
          )}

          {(formData.activity_type === 'call' || formData.activity_type === 'meeting') && (
            <div className="space-y-2">
              <Label htmlFor="outcome">Outcome</Label>
              <Textarea
                id="outcome"
                value={formData.outcome || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, outcome: e.target.value }))}
                rows={2}
                placeholder="Activity outcome or result"
              />
            </div>
          )}

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Saving...' : activity?.id ? 'Update Activity' : 'Create Activity'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default ActivityFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, selectRecords, selectOne } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { getAgencyId } from '@/utils/agencyUtils';

interface ChartOfAccount {
  id?: string;
  account_code: string;
  account_name: string;
  account_type: 'asset' | 'liability' | 'equity' | 'revenue' | 'expense';
  parent_account_id?: string | null;
  is_active?: boolean;
  description?: string | null;
}

interface ChartOfAccountFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  account?: ChartOfAccount | null;
  onAccountSaved: () => void;
}

const ChartOfAccountFormDialog: React.FC<ChartOfAccountFormDialogProps> = ({ 
  isOpen, 
  onClose, 
  account, 
  onAccountSaved 
}) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [parentAccounts, setParentAccounts] = useState<unknown[]>([]);
  const [formData, setFormData] = useState<ChartOfAccount>({
    account_code: account?.account_code || '',
    account_name: account?.account_name || '',
    account_type: account?.account_type || 'asset',
    parent_account_id: account?.parent_account_id || null,
    is_active: account?.is_active !== undefined ? account.is_active : true,
    description: account?.description || '',
  });

  useEffect(() => {
    if (isOpen) {
      fetchParentAccounts();
      if (account) {
        setFormData({
          account_code: account.account_code,
          account_name: account.account_name,
          account_type: account.account_type,
          parent_account_id: account.parent_account_id || null,
          is_active: account.is_active !== undefined ? account.is_active : true,
          description: account.description || '',
        });
      } else {
        setFormData({
          account_code: '',
          account_name: '',
          account_type: 'asset',
          parent_account_id: null,
          is_active: true,
          description: '',
        });
      }
    }
  }, [isOpen, account]);

  const fetchParentAccounts = async () => {
    try {
      if (!user?.id) return;
      
      // Get agency_id using utility function (handles multi-database architecture)
      const userProfile = profile || await selectOne('profiles', { user_id: user.id });
      const agencyId = await getAgencyId(userProfile, user.id);
      
      const where: Record<string, unknown> = { is_active: true };
      if (agencyId) {
        where.agency_id = agencyId;
      }
      
      const accounts = await selectRecords('chart_of_accounts', {
        where,
        orderBy: 'account_code ASC',
      });
      setParentAccounts(accounts || []);
    } catch (error: unknown) {
      // Fallback if agency_id column doesn't exist
      if (error?.code === '42703' || String(error?.message || '').includes('agency_id')) {
        const accounts = await selectRecords('chart_of_accounts', {
          where: { is_active: true },
          orderBy: 'account_code ASC',
        });
        setParentAccounts(accounts || []);
      } else {
        console.error('Error fetching parent accounts:', error);
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Validate required fields
      if (!formData.account_code.trim()) {
        toast({
          title: 'Error',
          description: 'Account code is required',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      if (!formData.account_name.trim()) {
        toast({
          title: 'Error',
          description: 'Account name is required',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      // Get agency_id using utility function (handles multi-database architecture)
      const userProfile = profile || (user?.id ? await selectOne('profiles', { user_id: user.id }) : null);
      const agencyId = await getAgencyId(userProfile, user?.id);
      
      // Check if we have agency context (either agency_id or agency_database)
      const agencyDatabase = localStorage.getItem('agency_database');
      const hasAgencyContext = agencyId || agencyDatabase;
      
      if (!hasAgencyContext && !account?.id) {
        toast({
          title: 'Error',
          description: 'Unable to determine agency. Please ensure you are logged in.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      // Validate account code is unique within agency (if creating new or changing code)
      if (!account?.id || formData.account_code !== account.account_code) {
        const where: Record<string, unknown> = { account_code: formData.account_code.trim() };
        if (agencyId) {
          where.agency_id = agencyId;
        }
        
        const existing = await selectOne('chart_of_accounts', where);
        if (existing && existing.id !== account?.id) {
          toast({
            title: 'Error',
            description: 'Account code already exists. Please use a unique code.',
            variant: 'destructive',
          });
          setLoading(false);
          return;
        }
      }

      const cleanedData: unknown = {
        account_code: formData.account_code.trim(),
        account_name: formData.account_name.trim(),
        account_type: formData.account_type,
        is_active: formData.is_active !== undefined ? formData.is_active : true,
        description: formData.description?.trim() || null,
      };

      // Handle parent_account_id (matches database column name)
      cleanedData.parent_account_id = formData.parent_account_id || null;
      
      // Add agency_id when creating new account (use getAgencyId result)
      if (!account?.id && agencyId) {
        cleanedData.agency_id = agencyId;
      }

      if (account?.id) {
        await updateRecord('chart_of_accounts', cleanedData, { id: account.id }, user?.id);
        toast({
          title: 'Success',
          description: 'Account updated successfully',
        });
      } else {
        await insertRecord('chart_of_accounts', cleanedData, user?.id);
        toast({
          title: 'Success',
          description: 'Account created successfully',
        });
      }

      onAccountSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving account:', error);
      // Check for unique constraint violation
      if (error.message?.includes('unique') || error.message?.includes('duplicate')) {
        toast({
          title: 'Error',
          description: 'Account code already exists. Please use a unique code.',
          variant: 'destructive',
        });
      } else {
        toast({
          title: 'Error',
          description: error.message || 'Failed to save account',
          variant: 'destructive',
        });
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{account?.id ? 'Edit Account' : 'Create New Account'}</DialogTitle>
          <DialogDescription>
            {account?.id ? 'Update account details below.' : 'Fill in the details to create a new chart of accounts entry.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="account_code">Account Code *</Label>
              <Input
                id="account_code"
                value={formData.account_code}
                onChange={(e) => setFormData(prev => ({ ...prev, account_code: e.target.value }))}
                placeholder="e.g., 1000, 2000"
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="account_type">Account Type *</Label>
              <Select 
                value={formData.account_type} 
                onValueChange={(value: unknown) => setFormData(prev => ({ ...prev, account_type: value }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="asset">Asset</SelectItem>
                  <SelectItem value="liability">Liability</SelectItem>
                  <SelectItem value="equity">Equity</SelectItem>
                  <SelectItem value="revenue">Revenue</SelectItem>
                  <SelectItem value="expense">Expense</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="account_name">Account Name *</Label>
            <Input
              id="account_name"
              value={formData.account_name}
              onChange={(e) => setFormData(prev => ({ ...prev, account_name: e.target.value }))}
              placeholder="e.g., Cash, Accounts Receivable"
              required
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="parent_account_id">Parent Account</Label>
            <Select
              value={formData.parent_account_id || '__none__'}
              onValueChange={(value) => setFormData(prev => ({ ...prev, parent_account_id: value === '__none__' ? null : value }))}                                                           
            >
              <SelectTrigger>
                <SelectValue placeholder="Select parent account (optional)" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="__none__">None</SelectItem>
                {parentAccounts
                  .filter(acc => !account?.id || acc.id !== account.id)
                  .map((acc) => (
                    <SelectItem key={acc.id} value={acc.id}>
                      {acc.account_code} - {acc.account_name}
                    </SelectItem>
                  ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description || ''}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={3}
              placeholder="Account description"
            />
          </div>

          <div className="flex items-center space-x-2">
            <input
              type="checkbox"
              id="is_active"
              checked={formData.is_active}
              onChange={(e) => setFormData(prev => ({ ...prev, is_active: e.target.checked }))}
              className="rounded"
            />
            <Label htmlFor="is_active" className="cursor-pointer">
              Account is active
            </Label>
          </div>

          <DialogFooter className="flex flex-col sm:flex-row gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} className="w-full sm:w-auto">
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="w-full sm:w-auto">
              {loading ? 'Saving...' : account?.id ? 'Update Account' : 'Create Account'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default ChartOfAccountFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, selectRecords } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { getClientsForSelectionAuto } from '@/services/api/selectors';
import { getProjectsForSelectionAuto } from '@/services/api/projects';

interface Invoice {
  id?: string;
  invoice_number?: string;
  client_id: string;
  title: string;
  description?: string;
  status: string;
  issue_date: string;
  due_date: string;
  subtotal: number;
  tax_rate: number;
  discount?: number;
  notes?: string;
}

interface InvoiceFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  invoice?: Invoice | null;
  onInvoiceSaved: () => void;
}

const InvoiceFormDialog: React.FC<InvoiceFormDialogProps> = ({ isOpen, onClose, invoice, onInvoiceSaved }) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [clients, setClients] = useState<unknown[]>([]);
  const [clientsLoading, setClientsLoading] = useState(true);
  const [projects, setProjects] = useState<unknown[]>([]);
  const [projectsLoading, setProjectsLoading] = useState(false);
  const [formData, setFormData] = useState<Invoice>({
    client_id: invoice?.client_id || '',
    title: invoice?.title || '',
    description: invoice?.description || '',
    status: invoice?.status || 'draft',
    issue_date: invoice?.issue_date || new Date().toISOString().split('T')[0],
    due_date: invoice?.due_date || '',
    subtotal: invoice?.subtotal || 0,
    tax_rate: invoice?.tax_rate || 18,
    discount: invoice?.discount || 0,
    notes: invoice?.notes || '',
  });

  useEffect(() => {
    if (isOpen) {
      fetchClients();
      fetchProjects();
      if (invoice) {
        setFormData({
          client_id: invoice.client_id || '',
          title: invoice.title || '',
          description: invoice.description || '',
          status: invoice.status || 'draft',
          issue_date: invoice.issue_date || new Date().toISOString().split('T')[0],
          due_date: invoice.due_date || '',
          subtotal: invoice.subtotal || 0,
          tax_rate: invoice.tax_rate || 18,
          discount: invoice.discount || 0,
          notes: invoice.notes || '',
        });
      } else {
        setFormData({
          client_id: '',
          title: '',
          description: '',
          status: 'draft',
          issue_date: new Date().toISOString().split('T')[0],
          due_date: '',
          subtotal: 0,
          tax_rate: 18,
          discount: 0,
          notes: '',
        });
      }
    }
  }, [isOpen, invoice]);

  const fetchClients = async () => {
    try {
      setClientsLoading(true);
      
      // Use standardized client fetching service
      const clientsData = await getClientsForSelectionAuto(profile, user?.id, {
        includeInactive: false,
        status: 'active'
      });
      
      // Transform to component format
      setClients(clientsData.map(c => ({
        id: c.id,
        name: c.name,
        company_name: c.company_name,
        email: c.email
      })));
    } catch (error) {
      console.error('Error fetching clients:', error);
      toast({
        title: 'Error',
        description: 'Failed to load clients',
        variant: 'destructive',
      });
      setClients([]);
    } finally {
      setClientsLoading(false);
    }
  };

  const fetchProjects = async () => {
    try {
      setProjectsLoading(true);
      
      // Use standardized project fetching service
      const projectsData = await getProjectsForSelectionAuto(profile, user?.id, {
        includeInactive: false
      });
      
      // Transform to component format
      setProjects(projectsData.map(p => ({
        id: p.id,
        name: p.name,
        project_code: p.project_code,
        client_name: p.client_name || p.client_company_name
      })));
    } catch (error) {
      console.error('Error fetching projects:', error);
      setProjects([]);
    } finally {
      setProjectsLoading(false);
    }
  };

  const calculateTotal = () => {
    const subtotal = parseFloat(String(formData.subtotal || 0));
    const discount = parseFloat(String(formData.discount || 0));
    const taxRate = parseFloat(String(formData.tax_rate || 0));
    const afterDiscount = Math.max(0, subtotal - discount);
    const taxAmount = (afterDiscount * taxRate) / 100;
    return afterDiscount + taxAmount;
  };

  // Update total when form data changes
  useEffect(() => {
    if (isOpen) {
      const total = calculateTotal();
      // This will be saved when form is submitted
    }
  }, [formData.subtotal, formData.discount, formData.tax_rate, isOpen]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const cleanedData: unknown = {
        ...formData,
        client_id: formData.client_id || null,
        subtotal: parseFloat(String(formData.subtotal || 0)),
        tax_rate: parseFloat(String(formData.tax_rate || 0)),
        discount: parseFloat(String(formData.discount || 0)) || 0,
      };

      // Remove total_amount for updates - it's a generated column
      if (invoice?.id) {
        // Exclude total_amount from update - database will calculate it automatically
        const { total_amount, ...updateData } = cleanedData;
        await updateRecord('invoices', updateData, { id: invoice.id }, user?.id);
        toast({
          title: 'Success',
          description: 'Invoice updated successfully',
        });
      } else {
        // For inserts, we can include total_amount if needed, but database will calculate it anyway
        const invoiceNumber = `INV-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
        // Don't include total_amount - let database calculate it from the generated column formula
        await insertRecord('invoices', { ...cleanedData, invoice_number: invoiceNumber }, user?.id);
        toast({
          title: 'Success',
          description: 'Invoice created successfully',
        });
      }

      onInvoiceSaved();
      onClose();
    } catch (error) {
      console.error('Error saving invoice:', error);
      toast({
        title: 'Error',
        description: 'Failed to save invoice',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto mx-4 sm:mx-auto">
        <DialogHeader>
          <DialogTitle className="text-lg sm:text-xl">{invoice?.id ? 'Edit Invoice' : 'Create New Invoice'}</DialogTitle>
          <DialogDescription className="text-sm sm:text-base">
            {invoice?.id ? 'Update invoice details below.' : 'Fill in the details to create a new invoice.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="title">Invoice Title *</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select value={formData.status} onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="paid">Paid</SelectItem>
                  <SelectItem value="overdue">Overdue</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={3}
            />
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="client_id">Client</Label>
              <Select 
                value={formData.client_id || undefined} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, client_id: value === 'none' ? null : value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select client (optional)" />
                </SelectTrigger>
                <SelectContent>
                  {!clientsLoading && clients.length > 0 ? (
                    <>
                      <SelectItem value="none">No Client</SelectItem>
                      {clients.map((client) => {
                        if (!client || !client.id) return null;
                        const clientId = String(client.id);
                        const clientName = client.name || client.company_name || 'Unnamed Client';
                        const companyName = client.company_name && client.name ? `(${client.company_name})` : '';
                        return (
                          <SelectItem key={clientId} value={clientId}>
                            {clientName} {companyName}
                          </SelectItem>
                        );
                      })}
                    </>
                  ) : clientsLoading ? (
                    <SelectItem value="loading" disabled>Loading clients...</SelectItem>
                  ) : (
                    <SelectItem value="no-clients" disabled>No clients available</SelectItem>
                  )}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="due_date">Due Date</Label>
              <Input
                id="due_date"
                type="date"
                value={formData.due_date}
                onChange={(e) => setFormData(prev => ({ ...prev, due_date: e.target.value }))}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="subtotal">Subtotal (₹) *</Label>
              <Input
                id="subtotal"
                type="number"
                step="0.01"
                value={formData.subtotal}
                onChange={(e) => setFormData(prev => ({ ...prev, subtotal: Number(e.target.value) || 0 }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="tax_rate">Tax Rate (%) *</Label>
              <Input
                id="tax_rate"
                type="number"
                step="0.01"
                value={formData.tax_rate}
                onChange={(e) => setFormData(prev => ({ ...prev, tax_rate: Number(e.target.value) || 0 }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="discount">Discount (₹)</Label>
              <Input
                id="discount"
                type="number"
                step="0.01"
                value={formData.discount || 0}
                onChange={(e) => setFormData(prev => ({ ...prev, discount: Number(e.target.value) || 0 }))}
              />
            </div>
          </div>

          <div className="p-4 bg-muted rounded-lg">
            <div className="flex justify-between items-center">
              <span className="font-semibold">Total Amount:</span>
              <span className="text-2xl font-bold">₹{calculateTotal().toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              rows={2}
            />
          </div>

          <DialogFooter className="flex flex-col sm:flex-row gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} className="w-full sm:w-auto">
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="w-full sm:w-auto">
              {loading ? 'Saving...' : invoice?.id ? 'Update Invoice' : 'Create Invoice'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

