import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, selectRecords, selectOne } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';
import { getClientsForSelectionAuto } from '@/services/api/selectors';
import { getProjectsForSelectionAuto } from '@/services/api/projects';
import { getProductsForSelectionAuto } from '@/services/api/inventory';
import { X } from 'lucide-react';

interface Job {
  id?: string;
  job_number?: string;
  title: string;
  description: string;
  client_id: string;
  category_id: string;
  status: string;
  start_date: string;
  end_date: string;
  estimated_hours: number;
  estimated_cost: number;
  budget: number;
  profit_margin: number;
  assigned_to: string;
}

interface JobFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  job?: Job | null;
  onJobSaved: () => void;
}

const JobFormDialog: React.FC<JobFormDialogProps> = ({ isOpen, onClose, job, onJobSaved }) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [dataLoading, setDataLoading] = useState(true);
  const [clients, setClients] = useState<unknown[]>([]);
  const [jobCategories, setJobCategories] = useState<unknown[]>([]);
  const [employees, setEmployees] = useState<unknown[]>([]);
  const [formData, setFormData] = useState<Job>({
    title: job?.title || '',
    description: job?.description || '',
    client_id: job?.client_id || '',
    category_id: job?.category_id || '',
    status: job?.status || 'planning',
    start_date: job?.start_date || '',
    end_date: job?.end_date || '',
    estimated_hours: job?.estimated_hours || 0,
    estimated_cost: job?.estimated_cost || 0,
    budget: job?.budget || 0,
    profit_margin: job?.profit_margin || 0,
    assigned_to: job?.assigned_to || '',
  });

  useEffect(() => {
    if (isOpen) {
      // Reset form data first
      setFormData({
        title: '',
        description: '',
        client_id: '',
        category_id: '',
        status: 'planning',
        start_date: '',
        end_date: '',
        estimated_hours: 0,
        estimated_cost: 0,
        budget: 0,
        profit_margin: 0,
        assigned_to: '',
      });
      
      // Fetch data first, then set form data after data is loaded
      const loadData = async () => {
        setDataLoading(true);
        try {
          await Promise.all([
            fetchClients(),
            fetchJobCategories(),
            fetchEmployees(),
          ]);
          
          // After data is loaded, set form data if editing
          if (job) {
            setFormData({
              title: job.title || '',
              description: job.description || '',
              client_id: job.client_id || '',
              category_id: job.category_id || '',
              status: job.status || 'planning',
              start_date: job.start_date || '',
              end_date: job.end_date || '',
              estimated_hours: job.estimated_hours || 0,
              estimated_cost: job.estimated_cost || 0,
              budget: job.budget || 0,
              profit_margin: job.profit_margin || 0,
              assigned_to: job.assigned_to || '',
            });
          }
        } finally {
          setDataLoading(false);
        }
      };
      
      loadData();
    }
  }, [isOpen, job]);

  const fetchClients = async () => {
    try {
      if (!user?.id) {
        setClients([]);
        return;
      }
      
      // Use standardized client fetching service
      const clientsData = await getClientsForSelectionAuto(profile, user.id);
      
      // Transform to component format
      setClients(clientsData.map(c => ({
        id: c.id,
        company_name: c.company_name || c.name,
        name: c.name
      })));
    } catch (error: unknown) {
      console.error('Error fetching clients:', error);
      toast({
        title: "Error",
        description: "Failed to fetch clients",
        variant: "destructive",
      });
      setClients([]);
    }
  };

  const fetchJobCategories = async () => {
    try {
      const categoriesData = await selectRecords('job_categories', {
        orderBy: 'name ASC',
      });
      setJobCategories(categoriesData || []);
    } catch (error) {
      console.error('Error fetching job categories:', error);
      setJobCategories([]);
    }
  };

  const fetchEmployees = async () => {
    try {
      if (!user?.id) {
        setEmployees([]);
        return;
      }
      
      // Use standardized employee fetching service
      const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
      
      // Transform to component format
      const transformedEmployees = employeesData.map(emp => ({
        id: emp.user_id,
        name: emp.full_name
      }));
      
      setEmployees(transformedEmployees);
    } catch (error) {
      console.error('Error fetching employees:', error);
      setEmployees([]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      // Validate required fields
      if (!formData.title.trim()) {
        toast({
          title: 'Error',
          description: 'Job title is required',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      // Clean up empty string values for UUID fields
      const cleanedData: unknown = {
        title: formData.title.trim(),
        description: formData.description.trim() || null,
        status: formData.status,
        start_date: formData.start_date || null,
        end_date: formData.end_date || null,
        estimated_hours: formData.estimated_hours || 0,
        estimated_cost: formData.estimated_cost || 0,
        budget: formData.budget || 0,
        profit_margin: formData.profit_margin || 0,
        client_id: formData.client_id || null,
        category_id: formData.category_id || null,
        assigned_to: formData.assigned_to || null,
      };

      if (job?.id) {
        // Update existing job
        await updateRecord('jobs', cleanedData, { id: job.id }, user?.id);
        toast({
          title: 'Success',
          description: 'Job updated successfully',
        });
      } else {
        // Get agency_id from profile
        const profile = user?.id ? await selectOne('profiles', { user_id: user.id }) : null;
        if (!profile?.agency_id) {
          toast({
            title: 'Error',
            description: 'Unable to determine agency. Please ensure you are logged in.',
            variant: 'destructive',
          });
          setLoading(false);
          return;
        }

        // Create new job
        const year = new Date().getFullYear();
        const timestamp = String(Date.now()).slice(-6);
        const jobNumber = `J-${year}-${timestamp}`;
        
        await insertRecord('jobs', {
          ...cleanedData,
          job_number: jobNumber,
          created_by: user?.id || null,
          agency_id: profile.agency_id,
        }, user?.id);

        toast({
          title: 'Success',
          description: 'Job created successfully',
        });
      }

      onJobSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving job:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save job',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{job?.id ? 'Edit Job' : 'Create New Job'}</DialogTitle>
          <DialogDescription>
            {job?.id ? 'Update job details below.' : 'Fill in the details to create a new job.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="title">Job Title *</Label>
              <Input
                id="title"
                value={formData.title}
                onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select value={formData.status} onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="planning">Planning</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={3}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="client_id">Client</Label>
              {dataLoading ? (
                <Input disabled placeholder="Loading clients..." />
              ) : (
                <div className="flex gap-2">
                  <Select 
                    value={
                      formData.client_id && clients.some(c => c.id === formData.client_id) 
                        ? formData.client_id 
                        : undefined
                    } 
                    onValueChange={(value) => setFormData(prev => ({ ...prev, client_id: value }))}
                    onOpenChange={(open) => {
                      if (!open && formData.client_id && !clients.some(c => c.id === formData.client_id)) {
                        // Clear invalid value when closing
                        setFormData(prev => ({ ...prev, client_id: '' }));
                      }
                    }}
                  >
                    <SelectTrigger className="flex-1">
                      <SelectValue placeholder="Select client (optional)" />
                    </SelectTrigger>
                    <SelectContent>
                      {clients.map((client) => (
                        <SelectItem key={client.id} value={client.id}>
                          {client.company_name || client.name || client.id}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {formData.client_id && (
                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      onClick={() => setFormData(prev => ({ ...prev, client_id: '' }))}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              )}
            </div>
            <div className="space-y-2">
              <Label htmlFor="category_id">Category</Label>
              {dataLoading ? (
                <Input disabled placeholder="Loading categories..." />
              ) : (
                <div className="flex gap-2">
                  <Select 
                    value={
                      formData.category_id && jobCategories.some(c => c.id === formData.category_id) 
                        ? formData.category_id 
                        : undefined
                    } 
                    onValueChange={(value) => setFormData(prev => ({ ...prev, category_id: value }))}
                    onOpenChange={(open) => {
                      if (!open && formData.category_id && !jobCategories.some(c => c.id === formData.category_id)) {
                        // Clear invalid value when closing
                        setFormData(prev => ({ ...prev, category_id: '' }));
                      }
                    }}
                  >
                    <SelectTrigger className="flex-1">
                      <SelectValue placeholder="Select category (optional)" />
                    </SelectTrigger>
                    <SelectContent>
                      {jobCategories.map((category) => (
                        <SelectItem key={category.id} value={category.id}>
                          {category.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  {formData.category_id && (
                    <Button
                      type="button"
                      variant="outline"
                      size="icon"
                      onClick={() => setFormData(prev => ({ ...prev, category_id: '' }))}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              )}
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="start_date">Start Date</Label>
              <Input
                id="start_date"
                type="date"
                value={formData.start_date}
                onChange={(e) => setFormData(prev => ({ ...prev, start_date: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="end_date">End Date</Label>
              <Input
                id="end_date"
                type="date"
                value={formData.end_date}
                onChange={(e) => setFormData(prev => ({ ...prev, end_date: e.target.value }))}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="estimated_hours">Estimated Hours</Label>
              <Input
                id="estimated_hours"
                type="number"
                value={formData.estimated_hours}
                onChange={(e) => setFormData(prev => ({ ...prev, estimated_hours: Number(e.target.value) }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="estimated_cost">Estimated Cost (₹)</Label>
              <Input
                id="estimated_cost"
                type="number"
                value={formData.estimated_cost}
                onChange={(e) => setFormData(prev => ({ ...prev, estimated_cost: Number(e.target.value) }))}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="budget">Budget (₹)</Label>
              <Input
                id="budget"
                type="number"
                value={formData.budget}
                onChange={(e) => setFormData(prev => ({ ...prev, budget: Number(e.target.value) }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="profit_margin">Profit Margin (%)</Label>
              <Input
                id="profit_margin"
                type="number"
                value={formData.profit_margin}
                onChange={(e) => setFormData(prev => ({ ...prev, profit_margin: Number(e.target.value) }))}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="assigned_to">Assigned To</Label>
            {dataLoading ? (
              <Input disabled placeholder="Loading employees..." />
            ) : (
              <div className="flex gap-2">
                <Select 
                  value={
                    formData.assigned_to && employees.some(e => e.id === formData.assigned_to) 
                      ? formData.assigned_to 
                      : undefined
                  } 
                  onValueChange={(value) => setFormData(prev => ({ ...prev, assigned_to: value }))}
                  onOpenChange={(open) => {
                    if (!open && formData.assigned_to && !employees.some(e => e.id === formData.assigned_to)) {
                      // Clear invalid value when closing
                      setFormData(prev => ({ ...prev, assigned_to: '' }));
                    }
                  }}
                >
                  <SelectTrigger className="flex-1">
                    <SelectValue placeholder="Select employee (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    {employees.map((employee) => (
                      <SelectItem key={employee.id} value={employee.id}>
                        {employee.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                {formData.assigned_to && (
                  <Button
                    type="button"
                    variant="outline"
                    size="icon"
                    onClick={() => setFormData(prev => ({ ...prev, assigned_to: '' }))}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                )}
              </div>
            )}
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Saving...' : job?.id ? 'Update Job' : 'Create Job'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default JobFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { selectRecords, selectOne, executeTransaction, insertRecord } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { Plus, Trash2 } from 'lucide-react';

interface JournalEntryLine {
  id?: string;
  account_id: string;
  description: string;
  debit_amount: number;
  credit_amount: number;
  line_number: number;
}

interface JournalEntry {
  id?: string;
  entry_number?: string;
  entry_date: string;
  description: string;
  reference?: string | null;
  status: 'draft' | 'posted' | 'reversed';
  lines: JournalEntryLine[];
}

interface JournalEntryFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  entry?: JournalEntry | null;
  onEntrySaved: () => void;
}

const JournalEntryFormDialog: React.FC<JournalEntryFormDialogProps> = ({ 
  isOpen, 
  onClose, 
  entry, 
  onEntrySaved 
}) => {
  const { toast } = useToast();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [accounts, setAccounts] = useState<unknown[]>([]);
  const [formData, setFormData] = useState<JournalEntry>({
    entry_date: entry?.entry_date || new Date().toISOString().split('T')[0],
    description: entry?.description || '',
    reference: entry?.reference || '',
    status: entry?.status || 'draft',
    lines: entry?.lines || [
      { account_id: '', description: '', debit_amount: 0, credit_amount: 0, line_number: 1 },
      { account_id: '', description: '', debit_amount: 0, credit_amount: 0, line_number: 2 },
    ],
  });

  useEffect(() => {
    if (isOpen) {
      fetchAccounts();
      if (entry) {
        setFormData({
          entry_date: entry.entry_date,
          description: entry.description,
          reference: entry.reference || '',
          status: entry.status,
          lines: entry.lines || [],
        });
      } else {
        setFormData({
          entry_date: new Date().toISOString().split('T')[0],
          description: '',
          reference: '',
          status: 'draft',
          lines: [
            { account_id: '', description: '', debit_amount: 0, credit_amount: 0, line_number: 1 },
            { account_id: '', description: '', debit_amount: 0, credit_amount: 0, line_number: 2 },
          ],
        });
      }
    }
  }, [isOpen, entry]);

  const fetchAccounts = async () => {
    try {
      if (!user?.id) return;
      // Get agency_id from profile
      const profile = await selectOne('profiles', { user_id: user.id });
      if (!profile?.agency_id) return;

      let accountsData: unknown[] = [];
      try {
        // Prefer agency-scoped accounts when the column exists
        accountsData = await selectRecords('chart_of_accounts', {
          where: { is_active: true, agency_id: profile.agency_id },
          orderBy: 'account_code ASC',
        });
      } catch (err: unknown) {
        // Fallback if agency_id column does not exist in current schema
        if (err?.code === '42703' || String(err?.message || '').includes('agency_id')) {
          console.warn('chart_of_accounts has no agency_id column, falling back to global accounts');
          accountsData = await selectRecords('chart_of_accounts', {
            where: { is_active: true },
            orderBy: 'account_code ASC',
          });
        } else {
          throw err;
        }
      }

      setAccounts(accountsData || []);
    } catch (error) {
      console.error('Error fetching accounts:', error);
    }
  };

  const addLine = () => {
    setFormData(prev => ({
      ...prev,
      lines: [
        ...prev.lines,
        {
          account_id: '',
          description: '',
          debit_amount: 0,
          credit_amount: 0,
          line_number: prev.lines.length + 1,
        },
      ],
    }));
  };

  const removeLine = (index: number) => {
    if (formData.lines.length <= 2) {
      toast({
        title: 'Error',
        description: 'Journal entry must have at least 2 lines',
        variant: 'destructive',
      });
      return;
    }
    setFormData(prev => ({
      ...prev,
      lines: prev.lines.filter((_, i) => i !== index).map((line, i) => ({ ...line, line_number: i + 1 })),
    }));
  };

  const updateLine = (index: number, field: keyof JournalEntryLine, value: unknown) => {
    setFormData(prev => ({
      ...prev,
      lines: prev.lines.map((line, i) => 
        i === index ? { ...line, [field]: value } : line
      ),
    }));
  };

  const validateEntry = (): boolean => {
    // Validate required fields
    if (!formData.description.trim()) {
      toast({
        title: 'Error',
        description: 'Description is required',
        variant: 'destructive',
      });
      return false;
    }

    if (!formData.entry_date) {
      toast({
        title: 'Error',
        description: 'Entry date is required',
        variant: 'destructive',
      });
      return false;
    }

    // Check that all lines have accounts
    if (formData.lines.some(line => !line.account_id)) {
      toast({
        title: 'Error',
        description: 'All lines must have an account selected',
        variant: 'destructive',
      });
      return false;
    }

    // Check that each line has either debit or credit (not both, not neither)
    for (const line of formData.lines) {
      const hasDebit = (line.debit_amount || 0) > 0;
      const hasCredit = (line.credit_amount || 0) > 0;
      if (!hasDebit && !hasCredit) {
        toast({
          title: 'Error',
          description: `Line ${line.line_number} must have either a debit or credit amount`,
          variant: 'destructive',
        });
        return false;
      }
      if (hasDebit && hasCredit) {
        toast({
          title: 'Error',
          description: `Line ${line.line_number} cannot have both debit and credit amounts`,
          variant: 'destructive',
        });
        return false;
      }
    }

    // Check that total debits equal total credits
    const totalDebits = formData.lines.reduce((sum, line) => sum + (parseFloat(line.debit_amount?.toString() || '0') || 0), 0);
    const totalCredits = formData.lines.reduce((sum, line) => sum + (parseFloat(line.credit_amount?.toString() || '0') || 0), 0);
    
    if (Math.abs(totalDebits - totalCredits) > 0.01) {
      toast({
        title: 'Error',
        description: `Total debits (₹${totalDebits.toFixed(2)}) must equal total credits (₹${totalCredits.toFixed(2)})`,
        variant: 'destructive',
      });
      return false;
    }

    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateEntry()) {
      return;
    }

    setLoading(true);

    try {
      const totalDebits = formData.lines.reduce((sum, line) => sum + (line.debit_amount || 0), 0);
      const totalCredits = formData.lines.reduce((sum, line) => sum + (line.credit_amount || 0), 0);

      const entryData: unknown = {
        entry_date: formData.entry_date,
        description: formData.description.trim(),
        reference: formData.reference?.trim() || null,
        status: formData.status,
        total_debit: totalDebits,
        total_credit: totalCredits,
      };

      // Use transactions for updates to ensure data consistency
      if (entry?.id) {
        
        // Use transaction for atomic update
        await executeTransaction(async (client: unknown) => {
          // Update entry
          await client.query(
            `UPDATE journal_entries 
             SET entry_date = $1, description = $2, reference = $3, status = $4, 
                 total_debit = $5, total_credit = $6, updated_at = NOW()
             WHERE id = $7`,
            [
              entryData.entry_date,
              entryData.description,
              entryData.reference,
              entryData.status,
              entryData.total_debit,
              entryData.total_credit,
              entry.id
            ]
          );

          // Delete existing lines
          await client.query(
            'DELETE FROM journal_entry_lines WHERE journal_entry_id = $1',
            [entry.id]
          );

          // Insert new lines
          for (const line of formData.lines) {
            await client.query(
              `INSERT INTO journal_entry_lines 
               (journal_entry_id, account_id, description, debit_amount, credit_amount, line_number, created_at, updated_at)
               VALUES ($1, $2, $3, $4, $5, $6, NOW(), NOW())`,
              [
                entry.id,
                line.account_id,
                line.description.trim() || formData.description.trim(),
                line.debit_amount || 0,
                line.credit_amount || 0,
                line.line_number
              ]
            );
          }
        });
      } else {
        // Get agency_id from profile
        const profile = user?.id ? await selectOne('profiles', { user_id: user.id }) : null;
        if (!profile?.agency_id) {
          toast({
            title: 'Error',
            description: 'Unable to determine agency. Please ensure you are logged in.',
            variant: 'destructive',
          });
          setLoading(false);
          return;
        }

        // Generate entry number
        const year = new Date().getFullYear();
        const timestamp = String(Date.now()).slice(-6);
        entryData.entry_number = `JE-${year}-${timestamp}`;

        // Insert new entry
        const newEntry = await insertRecord('journal_entries', {
          entry_number: entryData.entry_number,
          entry_date: entryData.entry_date,
          description: entryData.description,
          reference: entryData.reference,
          status: entryData.status,
          total_debit: entryData.total_debit,
          total_credit: entryData.total_credit,
          created_by: user?.id || null,
          agency_id: profile.agency_id,
        }, user?.id);

        const newEntryId = (newEntry as unknown).id;

        // Insert lines
        for (const line of formData.lines) {
          await insertRecord('journal_entry_lines', {
            journal_entry_id: newEntryId,
            account_id: line.account_id,
            description: line.description.trim() || formData.description.trim(),
            debit_amount: line.debit_amount || 0,
            credit_amount: line.credit_amount || 0,
            line_number: line.line_number,
          }, user?.id);
        }
      }

      toast({
        title: 'Success',
        description: entry?.id ? 'Journal entry updated successfully' : 'Journal entry created successfully',
      });

      onEntrySaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving journal entry:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save journal entry',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const totalDebits = formData.lines.reduce((sum, line) => sum + (line.debit_amount || 0), 0);
  const totalCredits = formData.lines.reduce((sum, line) => sum + (line.credit_amount || 0), 0);
  const isBalanced = Math.abs(totalDebits - totalCredits) < 0.01;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{entry?.id ? 'Edit Journal Entry' : 'Create New Journal Entry'}</DialogTitle>
          <DialogDescription>
            {entry?.id ? 'Update journal entry details below.' : 'Fill in the details to create a new journal entry. Debits must equal credits.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="entry_date">Entry Date *</Label>
              <Input
                id="entry_date"
                type="date"
                value={formData.entry_date}
                onChange={(e) => setFormData(prev => ({ ...prev, entry_date: e.target.value }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select 
                value={formData.status} 
                onValueChange={(value: unknown) => setFormData(prev => ({ ...prev, status: value }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="posted">Posted</SelectItem>
                  <SelectItem value="reversed">Reversed</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="reference">Reference</Label>
              <Input
                id="reference"
                value={formData.reference || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, reference: e.target.value }))}
                placeholder="Reference number"
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="description">Description *</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
              rows={2}
              placeholder="Journal entry description"
              required
            />
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <Label>Journal Entry Lines *</Label>
              <Button type="button" variant="outline" size="sm" onClick={addLine}>
                <Plus className="h-4 w-4 mr-1" />
                Add Line
              </Button>
            </div>

            <div className="border rounded-lg p-4 space-y-4">
              <div className="grid grid-cols-12 gap-2 text-sm font-medium text-muted-foreground pb-2 border-b">
                <div className="col-span-3">Account</div>
                <div className="col-span-4">Description</div>
                <div className="col-span-2">Debit</div>
                <div className="col-span-2">Credit</div>
                <div className="col-span-1"></div>
              </div>

              {formData.lines.map((line, index) => (
                <div key={index} className="grid grid-cols-12 gap-2 items-center">
                  <div className="col-span-3">
                    <Select
                      value={line.account_id}
                      onValueChange={(value) => updateLine(index, 'account_id', value)}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select account" />
                      </SelectTrigger>
                      <SelectContent>
                        {accounts.map((acc) => (
                          <SelectItem key={acc.id} value={acc.id}>
                            {acc.account_code} - {acc.account_name}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="col-span-4">
                    <Input
                      value={line.description}
                      onChange={(e) => updateLine(index, 'description', e.target.value)}
                      placeholder="Line description"
                    />
                  </div>
                  <div className="col-span-2">
                    <Input
                      type="number"
                      step="0.01"
                      value={line.debit_amount || ''}
                      onChange={(e) => {
                        const val = parseFloat(e.target.value) || 0;
                        updateLine(index, 'debit_amount', val);
                        updateLine(index, 'credit_amount', 0);
                      }}
                      placeholder="0.00"
                    />
                  </div>
                  <div className="col-span-2">
                    <Input
                      type="number"
                      step="0.01"
                      value={line.credit_amount || ''}
                      onChange={(e) => {
                        const val = parseFloat(e.target.value) || 0;
                        updateLine(index, 'credit_amount', val);
                        updateLine(index, 'debit_amount', 0);
                      }}
                      placeholder="0.00"
                    />
                  </div>
                  <div className="col-span-1">
                    {formData.lines.length > 2 && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => removeLine(index)}
                      >
                        <Trash2 className="h-4 w-4 text-red-500" />
                      </Button>
                    )}
                  </div>
                </div>
              ))}

              <div className="grid grid-cols-12 gap-2 pt-2 border-t font-semibold">
                <div className="col-span-7 text-right">Totals:</div>
                <div className={`col-span-2 ${isBalanced ? 'text-green-600' : 'text-red-600'}`}>
                  ₹{totalDebits.toFixed(2)}
                </div>
                <div className={`col-span-2 ${isBalanced ? 'text-green-600' : 'text-red-600'}`}>
                  ₹{totalCredits.toFixed(2)}
                </div>
                <div className="col-span-1"></div>
              </div>
              {!isBalanced && (
                <div className="text-sm text-red-600 text-center">
                  Difference: ₹{Math.abs(totalDebits - totalCredits).toFixed(2)}
                </div>
              )}
            </div>
          </div>

          <DialogFooter className="flex flex-col sm:flex-row gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} className="w-full sm:w-auto">
              Cancel
            </Button>
            <Button type="submit" disabled={loading || !isBalanced} className="w-full sm:w-auto">
              {loading ? 'Saving...' : entry?.id ? 'Update Entry' : 'Create Entry'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default JournalEntryFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { useAuth } from '@/hooks/useAuth';
import { generateUUID } from '@/lib/uuid';
import { getAgencyId } from '@/utils/agencyUtils';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';

interface Lead {
  id?: string;
  lead_number?: string;
  company_name: string;
  contact_name: string;
  email: string;
  phone: string;
  address?: string;
  website?: string;
  job_title?: string;
  industry?: string;
  location?: string;
  lead_source_id?: string;
  status: string;
  priority: string;
  estimated_value: number;
  probability: number;
  expected_close_date: string;
  due_date?: string;
  follow_up_date?: string;
  notes?: string;
  assigned_to?: string;
}

interface LeadFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  lead?: Lead | null;
  onLeadSaved: () => void;
}

const LeadFormDialog: React.FC<LeadFormDialogProps> = ({ isOpen, onClose, lead, onLeadSaved }) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [leadSources, setLeadSources] = useState<unknown[]>([]);
  const [employees, setEmployees] = useState<Array<{ id: string; full_name: string }>>([]);
  const [formData, setFormData] = useState<Lead>({
    company_name: lead?.company_name || lead?.name || '',
    contact_name: lead?.contact_name || lead?.name || '',
    email: lead?.email || '',
    phone: lead?.phone || '',
    address: lead?.address || '',
    website: lead?.website || '',
    job_title: lead?.job_title || '',
    industry: lead?.industry || '',
    location: lead?.location || '',
    lead_source_id: lead?.lead_source_id || lead?.source_id || '',
    status: lead?.status || 'new',
    priority: lead?.priority || 'medium',
    estimated_value: lead?.estimated_value || lead?.value || 0,
    probability: lead?.probability || 0,
    expected_close_date: lead?.expected_close_date || '',
    due_date: lead?.due_date || '',
    follow_up_date: lead?.follow_up_date || '',
    notes: lead?.notes || lead?.description || '',
    assigned_to: lead?.assigned_to || '',
  });

  useEffect(() => {
    if (isOpen) {
      fetchLeadSources();
      fetchEmployees();
      // Reset form when dialog opens
      if (lead) {
        setFormData({
          company_name: lead.company_name || lead.name || '',
          contact_name: lead.contact_name || lead.name || '',
          email: lead.email || '',
          phone: lead.phone || '',
          address: lead.address || '',
          website: lead.website || '',
          job_title: lead.job_title || '',
          industry: lead.industry || '',
          location: lead.location || '',
          lead_source_id: lead.lead_source_id || lead.source_id || '',
          status: lead.status || 'new',
          priority: lead.priority || 'medium',
          estimated_value: lead.estimated_value || lead.value || 0,
          probability: lead.probability || 0,
          expected_close_date: lead.expected_close_date || '',
          due_date: lead.due_date || '',
          follow_up_date: lead.follow_up_date || '',
          notes: lead.notes || lead.description || '',
          assigned_to: lead.assigned_to || '',
        });
      } else {
        setFormData({
          company_name: '',
          contact_name: '',
          email: '',
          phone: '',
          address: '',
          website: '',
          job_title: '',
          industry: '',
          location: '',
          lead_source_id: '',
          status: 'new',
          priority: 'medium',
          estimated_value: 0,
          probability: 0,
          expected_close_date: '',
          due_date: '',
          follow_up_date: '',
          notes: '',
          assigned_to: '',
        });
      }
    }
  }, [isOpen, lead]);

  const fetchLeadSources = async () => {
    try {
      const { data, error } = await db
        .from('lead_sources')
        .select('*')
        .eq('is_active', true)
        .order('name', { ascending: true });
      
      if (error) throw error;
      setLeadSources(data || []);
    } catch (error) {
      console.error('Error fetching lead sources:', error);
    }
  };

  const fetchEmployees = async () => {
    try {
      if (!user?.id) {
        setEmployees([]);
        return;
      }
      
      // Use standardized employee fetching service
      const employeesData = await getEmployeesForAssignmentAuto(profile, user.id);
      
      // Transform to component format
      const transformedEmployees = employeesData.map(emp => ({
        id: emp.user_id,
        full_name: emp.full_name
      }));
      
      setEmployees(transformedEmployees);
    } catch (error: unknown) {
      console.error('Error fetching employees:', error);
      toast({
        title: "Error",
        description: "Failed to fetch employees",
        variant: "destructive",
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId || !user?.id) {
        toast({
          title: 'Error',
          description: 'Agency ID or User ID not found. Please ensure you are logged in.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }
      const userId = user.id;

      if (lead?.id) {
        const updateData: unknown = {
          name: formData.contact_name || formData.company_name || '', // Set name for backward compatibility
          company_name: formData.company_name,
          contact_name: formData.contact_name,
          email: formData.email || null,
          phone: formData.phone || null,
          address: formData.address || null,
          website: formData.website || null,
          job_title: formData.job_title || null,
          industry: formData.industry || null,
          location: formData.location || null,
          lead_source_id: (formData.lead_source_id && formData.lead_source_id !== '__none__') ? formData.lead_source_id : null,
          source_id: (formData.lead_source_id && formData.lead_source_id !== '__none__') ? formData.lead_source_id : null,
          status: formData.status,
          priority: formData.priority,
          estimated_value: formData.estimated_value || null,
          value: formData.estimated_value || null,
          probability: formData.probability || 0,
          expected_close_date: formData.expected_close_date || null,
          due_date: formData.due_date || null,
          follow_up_date: formData.follow_up_date || null,
          notes: formData.notes || null,
          description: formData.notes || null,
          assigned_to: (formData.assigned_to && formData.assigned_to !== '__none__') ? formData.assigned_to : null,
          updated_at: new Date().toISOString(),
        };

        const { data, error } = await db
          .from('leads')
          .update(updateData)
          .eq('id', lead.id)
          .select()
          .single();

        if (error) throw error;

        toast({
          title: 'Success',
          description: 'Lead updated successfully',
        });
      } else {
        // Generate lead number
        const year = new Date().getFullYear();
        const timestamp = String(Date.now()).slice(-6);
        const leadNumber = `LEAD-${year}-${timestamp}`;

        const { data, error } = await db
          .from('leads')
          .insert([{
            id: generateUUID(),
            lead_number: leadNumber,
            name: formData.contact_name || formData.company_name || '', // Set name for backward compatibility
            company_name: formData.company_name,
            contact_name: formData.contact_name,
            email: formData.email || null,
            phone: formData.phone || null,
            address: formData.address || null,
            website: formData.website || null,
            job_title: formData.job_title || null,
            industry: formData.industry || null,
            location: formData.location || null,
            lead_source_id: (formData.lead_source_id && formData.lead_source_id !== '__none__') ? formData.lead_source_id : null,
            source_id: (formData.lead_source_id && formData.lead_source_id !== '__none__') ? formData.lead_source_id : null,
            status: formData.status,
            priority: formData.priority,
            estimated_value: formData.estimated_value || null,
            value: formData.estimated_value || null,
            probability: formData.probability || 0,
            expected_close_date: formData.expected_close_date || null,
            due_date: formData.due_date || null,
            follow_up_date: formData.follow_up_date || null,
            notes: formData.notes || null,
            description: formData.notes || null,
            assigned_to: (formData.assigned_to && formData.assigned_to !== '__none__') ? formData.assigned_to : null,
            created_by: userId,
            agency_id: agencyId,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          }])
          .select()
          .single();

        if (error) throw error;

        toast({
          title: 'Success',
          description: 'Lead created successfully',
        });
      }

      onLeadSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving lead:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save lead',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{lead?.id ? 'Edit Lead' : 'Create New Lead'}</DialogTitle>
          <DialogDescription>
            {lead?.id ? 'Update lead details below.' : 'Fill in the details to create a new lead.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="company_name">Company Name *</Label>
              <Input
                id="company_name"
                value={formData.company_name}
                onChange={(e) => setFormData(prev => ({ ...prev, company_name: e.target.value }))}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="contact_name">Contact Name *</Label>
              <Input
                id="contact_name"
                value={formData.contact_name}
                onChange={(e) => setFormData(prev => ({ ...prev, contact_name: e.target.value }))}
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="job_title">Job Title</Label>
              <Input
                id="job_title"
                value={formData.job_title || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, job_title: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="website">Website</Label>
              <Input
                id="website"
                type="url"
                value={formData.website || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, website: e.target.value }))}
                placeholder="https://example.com"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="industry">Industry</Label>
              <Input
                id="industry"
                value={formData.industry || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, industry: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="location">Location</Label>
              <Input
                id="location"
                value={formData.location || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, location: e.target.value }))}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData(prev => ({ ...prev, email: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="phone">Phone</Label>
              <Input
                id="phone"
                value={formData.phone}
                onChange={(e) => setFormData(prev => ({ ...prev, phone: e.target.value }))}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="address">Address</Label>
            <Textarea
              id="address"
              value={formData.address}
              onChange={(e) => setFormData(prev => ({ ...prev, address: e.target.value }))}
              rows={2}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="lead_source_id">Lead Source</Label>
              <Select 
                value={formData.lead_source_id || undefined} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, lead_source_id: value === '__none__' ? '' : value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select lead source (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">None</SelectItem>
                  {leadSources.map((source) => (
                    <SelectItem key={source.id} value={source.id}>
                      {source.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="assigned_to">Assigned To</Label>
              <Select 
                value={formData.assigned_to || undefined} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, assigned_to: value === '__none__' ? '' : value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select employee (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">None</SelectItem>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.full_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select value={formData.status} onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="new">New</SelectItem>
                  <SelectItem value="contacted">Contacted</SelectItem>
                  <SelectItem value="qualified">Qualified</SelectItem>
                  <SelectItem value="proposal">Proposal</SelectItem>
                  <SelectItem value="negotiation">Negotiation</SelectItem>
                  <SelectItem value="won">Won</SelectItem>
                  <SelectItem value="lost">Lost</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="priority">Priority</Label>
              <Select value={formData.priority} onValueChange={(value) => setFormData(prev => ({ ...prev, priority: value }))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="medium">Medium</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="estimated_value">Estimated Value (₹)</Label>
              <Input
                id="estimated_value"
                type="number"
                value={formData.estimated_value}
                onChange={(e) => setFormData(prev => ({ ...prev, estimated_value: Number(e.target.value) }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="probability">Probability (%)</Label>
              <Input
                id="probability"
                type="number"
                min="0"
                max="100"
                value={formData.probability}
                onChange={(e) => setFormData(prev => ({ ...prev, probability: Number(e.target.value) }))}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="expected_close_date">Expected Close Date</Label>
              <Input
                id="expected_close_date"
                type="date"
                value={formData.expected_close_date}
                onChange={(e) => setFormData(prev => ({ ...prev, expected_close_date: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="due_date">Due Date</Label>
              <Input
                id="due_date"
                type="date"
                value={formData.due_date || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, due_date: e.target.value }))}
              />
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="follow_up_date">Follow-up Date</Label>
            <Input
              id="follow_up_date"
              type="date"
              value={formData.follow_up_date || ''}
              onChange={(e) => setFormData(prev => ({ ...prev, follow_up_date: e.target.value }))}
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              rows={3}
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? 'Saving...' : lead?.id ? 'Update Lead' : 'Create Lead'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default LeadFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import { insertRecord, updateRecord, selectRecords } from '@/services/api/core';
import { LeaveRequest, LeaveType } from '@/integrations/postgresql/types';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';

interface LeaveRequestFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  leaveRequest?: LeaveRequest | null;
  onLeaveRequestSaved: () => void;
  isEmployeeView?: boolean; // If true, hide employee selector and status field
}

const LeaveRequestFormDialog: React.FC<LeaveRequestFormDialogProps> = ({
  isOpen,
  onClose,
  leaveRequest,
  onLeaveRequestSaved,
  isEmployeeView = false,
}) => {
  const { toast } = useToast();
  const { user, userRole, profile } = useAuth();
  
  // Check if user is admin/HR (can manage all requests)
  const isAdminOrHR = userRole === 'agency_admin' || userRole === 'super_admin' || userRole === 'manager';
  const canManageRequests = isAdminOrHR && !isEmployeeView;
  const [loading, setLoading] = useState(false);
  const [leaveTypes, setLeaveTypes] = useState<LeaveType[]>([]);
  const [employees, setEmployees] = useState<unknown[]>([]);
  const [loadingData, setLoadingData] = useState(false);

  const [formData, setFormData] = useState({
    employee_id: '',
    leave_type_id: '',
    start_date: '',
    end_date: '',
    reason: '',
    status: 'pending',
  });

  const [errors, setErrors] = useState<Record<string, string>>({});

  // Format date for input field (YYYY-MM-DD)
  const formatDateForInput = (dateString: string | null | undefined): string => {
    if (!dateString) return '';
    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return '';
      return date.toISOString().split('T')[0];
    } catch {
      return '';
    }
  };

  // Calculate total days between start and end date
  const calculateDays = (start: string, end: string): number => {
    if (!start || !end) return 0;
    try {
      const startDate = new Date(start);
      const endDate = new Date(end);
      if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) return 0;
      const diffTime = Math.abs(endDate.getTime() - startDate.getTime());
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
      return diffDays > 0 ? diffDays : 0;
    } catch {
      return 0;
    }
  };

  // Fetch leave types and employees when dialog opens
  useEffect(() => {
    if (isOpen) {
      fetchData();
    }
  }, [isOpen]);

  // Update form data when leaveRequest prop changes
  useEffect(() => {
    if (isOpen) {
      if (leaveRequest && leaveRequest.id) {
        // Editing existing leave request
        setFormData({
          employee_id: leaveRequest.employee_id || '',
          leave_type_id: leaveRequest.leave_type_id || '',
          start_date: formatDateForInput(leaveRequest.start_date),
          end_date: formatDateForInput(leaveRequest.end_date),
          reason: leaveRequest.reason || '',
          status: leaveRequest.status || 'pending',
        });
      } else {
        // Creating new leave request
        // For employee view, always use current user and set status to pending
        const employeeId = isEmployeeView && user?.id ? user.id : (user?.id || '');
        setFormData({
          employee_id: employeeId,
          leave_type_id: '',
          start_date: '',
          end_date: '',
          reason: '',
          status: 'pending', // Always pending for new requests from employees
        });
      }
      setErrors({});
    }
  }, [leaveRequest, isOpen, user, isEmployeeView]);

  const fetchData = async () => {
    try {
      setLoadingData(true);

      // Fetch leave types
      const types = await selectRecords<LeaveType>('leave_types', {
        filters: [{ column: 'is_active', operator: 'eq', value: true }],
        orderBy: 'name ASC'
      });
      setLeaveTypes(types);

      // Only fetch employees list if user is admin/HR and not in employee view
      if (canManageRequests) {
        // Use standardized employee fetching service
        const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
        setEmployees(employeesData.map(emp => ({
          id: emp.user_id,
          name: emp.full_name
        })));
      } else {
        // For employee view, just set current user as the only employee
        if (user?.id) {
          // Use standardized service to get current user's info
          const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
          const currentUser = employeesData.find(emp => emp.user_id === user.id);
          setEmployees([{ 
            id: user.id, 
            name: currentUser?.full_name || profile?.full_name || 'You' 
          }]);
        }
      }
    } catch (error: unknown) {
      console.error('Error fetching data:', error);
      toast({
        title: 'Error',
        description: 'Failed to load leave types and employees',
        variant: 'destructive',
      });
    } finally {
      setLoadingData(false);
    }
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    // For employee view, ensure employee_id is set to current user
    if (isEmployeeView && user?.id) {
      if (formData.employee_id !== user.id) {
        setFormData({ ...formData, employee_id: user.id });
      }
    }

    if (!formData.employee_id) {
      newErrors.employee_id = 'Employee is required';
    }

    if (!formData.leave_type_id) {
      newErrors.leave_type_id = 'Leave type is required';
    }

    if (!formData.start_date) {
      newErrors.start_date = 'Start date is required';
    }

    if (!formData.end_date) {
      newErrors.end_date = 'End date is required';
    }

    if (formData.start_date && formData.end_date) {
      const start = new Date(formData.start_date);
      const end = new Date(formData.end_date);
      if (end < start) {
        newErrors.end_date = 'End date must be after start date';
      }
    }

    if (!formData.reason || formData.reason.trim().length === 0) {
      newErrors.reason = 'Reason is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    if (!user?.id) {
      toast({
        title: 'Error',
        description: 'You must be logged in to submit leave requests',
        variant: 'destructive',
      });
      return;
    }

    try {
      setLoading(true);

      const totalDays = calculateDays(formData.start_date, formData.end_date);

      if (leaveRequest && leaveRequest.id) {
        // Update existing leave request
        await updateRecord<LeaveRequest>(
          'leave_requests',
          {
            employee_id: formData.employee_id,
            leave_type_id: formData.leave_type_id,
            start_date: formData.start_date,
            end_date: formData.end_date,
            total_days: totalDays,
            reason: formData.reason.trim(),
            status: formData.status,
          },
          { id: leaveRequest.id },
          user.id
        );

        toast({
          title: 'Success',
          description: 'Leave request updated successfully',
        });
      } else {
        // Create new leave request
        // For employee view, always set status to 'pending'
        const requestStatus = isEmployeeView ? 'pending' : formData.status;
        
        // Get agency_id from user's profile or employee_details
        let agencyId = '';
        try {
          const profile = await selectRecords('profiles', {
            where: { user_id: user.id },
            limit: 1
          });
          if (profile.length > 0 && profile[0].agency_id) {
            agencyId = profile[0].agency_id;
          } else {
            const empDetail = await selectRecords('employee_details', {
              where: { user_id: user.id },
              limit: 1
            });
            if (empDetail.length > 0 && empDetail[0].agency_id) {
              agencyId = empDetail[0].agency_id;
            }
          }
        } catch (err) {
          console.error('Error fetching agency_id:', err);
        }

        await insertRecord<LeaveRequest>(
          'leave_requests',
          {
            employee_id: formData.employee_id,
            leave_type_id: formData.leave_type_id,
            start_date: formData.start_date,
            end_date: formData.end_date,
            total_days: totalDays,
            reason: formData.reason.trim(),
            status: requestStatus, // Always pending for employees
            agency_id: agencyId || user.id, // Fallback to user.id if no agency_id found
          },
          user.id
        );

        toast({
          title: 'Success',
          description: 'Leave request created successfully',
        });
      }

      onLeaveRequestSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving leave request:', error);
      toast({
        title: 'Error',
        description: error.message || error.detail || 'Failed to save leave request',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const totalDays = calculateDays(formData.start_date, formData.end_date);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      if (!open) {
        onClose();
      }
    }}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {leaveRequest ? 'Edit Leave Request' : 'Create Leave Request'}
          </DialogTitle>
          <DialogDescription>
            {leaveRequest
              ? 'Update the leave request details below.'
              : 'Fill in the details to create a new leave request.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Employee selector - only show for admins/HR */}
          {canManageRequests ? (
            <div className="space-y-2">
              <Label htmlFor="employee_id">
                Employee <span className="text-destructive">*</span>
              </Label>
              <Select
                value={formData.employee_id}
                onValueChange={(value) => setFormData({ ...formData, employee_id: value })}
                disabled={loadingData || loading}
              >
                <SelectTrigger id="employee_id">
                  <SelectValue placeholder="Select employee" />
                </SelectTrigger>
                <SelectContent>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              {errors.employee_id && (
                <p className="text-sm text-destructive">{errors.employee_id}</p>
              )}
            </div>
          ) : (
            // For employees, show read-only employee name
            <div className="space-y-2">
              <Label>Employee</Label>
              <Input
                value={employees.find(e => e.id === formData.employee_id)?.name || 'You'}
                disabled
                className="bg-muted"
              />
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="leave_type_id">
              Leave Type <span className="text-destructive">*</span>
            </Label>
            <Select
              value={formData.leave_type_id}
              onValueChange={(value) => setFormData({ ...formData, leave_type_id: value })}
              disabled={loadingData || loading}
            >
              <SelectTrigger id="leave_type_id">
                <SelectValue placeholder="Select leave type" />
              </SelectTrigger>
              <SelectContent>
                {leaveTypes.map((type) => (
                  <SelectItem key={type.id} value={type.id}>
                    {type.name}
                    {((type as unknown).max_days_per_year || (type as unknown).max_days) && ` (Max: ${(type as unknown).max_days_per_year || (type as unknown).max_days} days)`}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.leave_type_id && (
              <p className="text-sm text-destructive">{errors.leave_type_id}</p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="start_date">
                Start Date <span className="text-destructive">*</span>
              </Label>
              <Input
                id="start_date"
                type="date"
                value={formData.start_date}
                onChange={(e) => setFormData({ ...formData, start_date: e.target.value })}
                disabled={loading}
              />
              {errors.start_date && (
                <p className="text-sm text-destructive">{errors.start_date}</p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="end_date">
                End Date <span className="text-destructive">*</span>
              </Label>
              <Input
                id="end_date"
                type="date"
                value={formData.end_date}
                onChange={(e) => setFormData({ ...formData, end_date: e.target.value })}
                disabled={loading}
                min={formData.start_date}
              />
              {errors.end_date && (
                <p className="text-sm text-destructive">{errors.end_date}</p>
              )}
            </div>
          </div>

          {totalDays > 0 && (
            <div className="text-sm text-muted-foreground">
              Total Days: <span className="font-semibold">{totalDays}</span>
            </div>
          )}

          {/* Status field - only show for admins/HR */}
          {canManageRequests && (
            <div className="space-y-2">
              <Label htmlFor="status">Status</Label>
              <Select
                value={formData.status}
                onValueChange={(value) => setFormData({ ...formData, status: value })}
                disabled={loading}
              >
                <SelectTrigger id="status">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="space-y-2">
            <Label htmlFor="reason">
              Reason <span className="text-destructive">*</span>
            </Label>
            <Textarea
              id="reason"
              value={formData.reason}
              onChange={(e) => setFormData({ ...formData, reason: e.target.value })}
              placeholder="Enter reason for leave request..."
              rows={4}
              disabled={loading}
            />
            {errors.reason && (
              <p className="text-sm text-destructive">{errors.reason}</p>
            )}
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading || loadingData}>
              {loading ? 'Saving...' : leaveRequest ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default LeaveRequestFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, selectRecords, selectOne, rawQuery, deleteRecord } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { Loader2 } from 'lucide-react';

interface Payment {
  id?: string;
  invoice_id: string;
  payment_date: string;
  amount: number;
  payment_method: string;
  reference_number?: string;
  notes?: string;
  status?: string;
}

interface PaymentFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  payment?: Payment | null;
  invoiceId?: string | null;
  onPaymentSaved: () => void;
}

const PaymentFormDialog: React.FC<PaymentFormDialogProps> = ({ 
  isOpen, 
  onClose, 
  payment, 
  invoiceId,
  onPaymentSaved 
}) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [invoices, setInvoices] = useState<unknown[]>([]);
  const [selectedInvoice, setSelectedInvoice] = useState<unknown>(null);
  const [invoicesLoading, setInvoicesLoading] = useState(true);
  const [formData, setFormData] = useState<Payment>({
    invoice_id: payment?.invoice_id || invoiceId || '',
    payment_date: payment?.payment_date || new Date().toISOString().split('T')[0],
    amount: payment?.amount || 0,
    payment_method: payment?.payment_method || 'bank_transfer',
    reference_number: payment?.reference_number || '',
    notes: payment?.notes || '',
    status: payment?.status || 'completed',
  });

  useEffect(() => {
    if (isOpen) {
      fetchInvoices();
      if (payment) {
        setFormData({
          invoice_id: payment.invoice_id || '',
          payment_date: payment.payment_date || new Date().toISOString().split('T')[0],
          amount: payment.amount || 0,
          payment_method: payment.payment_method || 'bank_transfer',
          reference_number: payment.reference_number || '',
          notes: payment.notes || '',
          status: payment.status || 'completed',
        });
      } else if (invoiceId) {
        setFormData(prev => ({
          ...prev,
          invoice_id: invoiceId,
        }));
      } else {
        setFormData({
          invoice_id: '',
          payment_date: new Date().toISOString().split('T')[0],
          amount: 0,
          payment_method: 'bank_transfer',
          reference_number: '',
          notes: '',
          status: 'completed',
        });
      }
    }
  }, [isOpen, payment, invoiceId]);

  useEffect(() => {
    if (formData.invoice_id && invoices.length > 0) {
      const invoice = invoices.find((inv: unknown) => inv.id === formData.invoice_id);
      if (invoice) {
        setSelectedInvoice(invoice);
        // Auto-fill amount if not set and not editing
        if (!payment && formData.amount === 0) {
          const totalAmount = invoice.total_amount || 
            (invoice.subtotal * (1 + (invoice.tax_rate || 0) / 100) - (invoice.discount || 0));
          setFormData(prev => ({ ...prev, amount: Number(totalAmount) || 0 }));
        }
      }
    } else if (payment && payment.invoice_id) {
      // If editing, fetch the invoice
      selectOne('invoices', { id: payment.invoice_id }).then((invoice: unknown) => {
        if (invoice) {
          setSelectedInvoice(invoice);
          setFormData(prev => ({
            ...prev,
            invoice_id: invoice.id,
            amount: payment.amount || 0,
          }));
        }
      }).catch(console.error);
    }
  }, [formData.invoice_id, invoices, payment]);

  const fetchInvoices = async () => {
    try {
      setInvoicesLoading(true);
      if (!profile?.agency_id) {
        setInvoices([]);
        return;
      }

      // Fetch unpaid or partially paid invoices
      const invoicesData = await selectRecords('invoices', {
        where: { 
          agency_id: profile.agency_id,
          status: { operator: 'in', value: ['draft', 'sent', 'overdue', 'partial'] }
        },
        orderBy: 'issue_date DESC',
      });
      
      setInvoices(invoicesData || []);
    } catch (error) {
      console.error('Error fetching invoices:', error);
      toast({
        title: 'Error',
        description: 'Failed to load invoices',
        variant: 'destructive',
      });
      setInvoices([]);
    } finally {
      setInvoicesLoading(false);
    }
  };

  const validateForm = (): boolean => {
    if (!formData.invoice_id) {
      toast({
        title: 'Validation Error',
        description: 'Please select an invoice',
        variant: 'destructive',
      });
      return false;
    }

    if (!formData.payment_date) {
      toast({
        title: 'Validation Error',
        description: 'Please select a payment date',
        variant: 'destructive',
      });
      return false;
    }

    if (!formData.amount || formData.amount <= 0) {
      toast({
        title: 'Validation Error',
        description: 'Please enter a valid payment amount',
        variant: 'destructive',
      });
      return false;
    }

    if (!formData.payment_method) {
      toast({
        title: 'Validation Error',
        description: 'Please select a payment method',
        variant: 'destructive',
      });
      return false;
    }

    // Check if payment amount exceeds invoice balance
    if (selectedInvoice) {
      const invoiceTotal = selectedInvoice.total_amount || 
        (selectedInvoice.subtotal * (1 + (selectedInvoice.tax_rate || 0) / 100) - (selectedInvoice.discount || 0));
      
      // Get existing payments for this invoice
      const existingPaymentsQuery = `
        SELECT COALESCE(SUM(amount), 0) as total_paid
        FROM journal_entries je
        JOIN journal_entry_lines jel ON je.id = jel.journal_entry_id
        JOIN chart_of_accounts coa ON jel.account_id = coa.id
        WHERE je.reference LIKE $1
        AND coa.account_type = 'Asset'
        AND coa.account_name ILIKE '%cash%'
        AND je.agency_id = $2
      `;
      
      // For now, we'll allow the payment and validate in the backend
      // The actual validation should check against all previous payments
    }

    return true;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    if (!user?.id || !profile?.agency_id) {
      toast({
        title: 'Error',
        description: 'You must be logged in to record a payment',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);
    try {
      if (!selectedInvoice && !payment) {
        toast({
          title: 'Error',
          description: 'Please select a valid invoice',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      const invoice = selectedInvoice || (payment ? await selectOne('invoices', { id: payment.invoice_id }) : null);
      if (!invoice) {
        toast({
          title: 'Error',
          description: 'Invoice not found',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      // Get cash/bank account for payment
      const cashAccounts = await selectRecords('chart_of_accounts', {
        where: {
          agency_id: profile.agency_id,
          account_type: 'Asset',
          account_name: { operator: 'ILIKE', value: '%cash%' }
        },
        limit: 1,
      });

      if (!cashAccounts || cashAccounts.length === 0) {
        toast({
          title: 'Error',
          description: 'No cash account found. Please create a cash account in Chart of Accounts first.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      const cashAccount = cashAccounts[0];

      // Get accounts receivable account
      const arAccounts = await selectRecords('chart_of_accounts', {
        where: {
          agency_id: profile.agency_id,
          account_type: 'Asset',
          account_name: { operator: 'ILIKE', value: '%receivable%' }
        },
        limit: 1,
      });

      const arAccount = arAccounts && arAccounts.length > 0 ? arAccounts[0] : cashAccount;

      if (payment && payment.id) {
        // Update existing payment (journal entry)
        // Get existing journal entry
        const existingEntry = await selectOne('journal_entries', { id: payment.id });
        if (!existingEntry) {
          throw new Error('Payment entry not found');
        }

        // Update journal entry
        await updateRecord('journal_entries', {
          entry_date: formData.payment_date,
          description: `Payment for Invoice ${invoice.invoice_number}${formData.notes ? ` - ${formData.notes}` : ''}`,
          reference: formData.reference_number || existingEntry.reference || `PAY-${invoice.invoice_number}`,
          total_debit: formData.amount,
          total_credit: formData.amount,
        }, { id: payment.id }, user.id);

        // Delete existing lines
        const existingLines = await selectRecords('journal_entry_lines', {
          where: { journal_entry_id: payment.id },
        });
        for (const line of existingLines || []) {
          await deleteRecord('journal_entry_lines', line.id, user.id);
        }

        // Create new lines
        await insertRecord('journal_entry_lines', {
          journal_entry_id: payment.id,
          account_id: cashAccount.id,
          description: `Payment received for Invoice ${invoice.invoice_number}`,
          debit_amount: formData.amount,
          credit_amount: 0,
          line_number: 1,
        }, user.id);

        await insertRecord('journal_entry_lines', {
          journal_entry_id: payment.id,
          account_id: arAccount.id,
          description: `Payment for Invoice ${invoice.invoice_number}`,
          debit_amount: 0,
          credit_amount: formData.amount,
          line_number: 2,
        }, user.id);
      } else {
        // Create new payment
        // Generate journal entry number
        const year = new Date().getFullYear();
        const timestamp = String(Date.now()).slice(-6);
        const entryNumber = `PAY-${year}-${timestamp}`;
        const reference = formData.reference_number || `PAY-${invoice.invoice_number}`;

        // Create journal entry for payment
        const journalEntry = await insertRecord('journal_entries', {
          entry_number: entryNumber,
          entry_date: formData.payment_date,
          description: `Payment for Invoice ${invoice.invoice_number}${formData.notes ? ` - ${formData.notes}` : ''}`,
          reference: reference,
          status: 'posted',
          total_debit: formData.amount,
          total_credit: formData.amount,
          created_by: user.id,
          agency_id: profile.agency_id,
        }, user.id);

        // Create debit line (Cash/Bank account)
        await insertRecord('journal_entry_lines', {
          journal_entry_id: journalEntry.id,
          account_id: cashAccount.id,
          description: `Payment received for Invoice ${invoice.invoice_number}`,
          debit_amount: formData.amount,
          credit_amount: 0,
          line_number: 1,
        }, user.id);

        // Create credit line (Accounts Receivable)
        await insertRecord('journal_entry_lines', {
          journal_entry_id: journalEntry.id,
          account_id: arAccount.id,
          description: `Payment for Invoice ${invoice.invoice_number}`,
          debit_amount: 0,
          credit_amount: formData.amount,
          line_number: 2,
        }, user.id);
      }

      // Update invoice status
      const invoiceTotal = invoice.total_amount || 
        (invoice.subtotal * (1 + (invoice.tax_rate || 0) / 100) - (invoice.discount || 0));
      
      // Get total payments for this invoice
      const paymentsQuery = `
        SELECT COALESCE(SUM(jel.debit_amount), 0) as total_paid
        FROM journal_entries je
        JOIN journal_entry_lines jel ON je.id = jel.journal_entry_id
        WHERE je.reference LIKE $1
        AND jel.account_id = $2
        AND je.agency_id = $3
        ${payment && payment.id ? `AND je.id != $4` : ''}
      `;
      
      const queryParams: unknown[] = [
        `%${invoice.invoice_number}%`,
        cashAccount.id,
        profile.agency_id
      ];
      if (payment && payment.id) {
        queryParams.push(payment.id);
      }
      
      const existingPayments = await rawQuery(paymentsQuery, queryParams);

      // Calculate total paid including this payment
      let totalPaid = Number(existingPayments[0]?.total_paid || 0);
      if (payment && payment.id) {
        // For updates, we need to subtract old amount and add new amount
        // But for simplicity, we'll recalculate from all payments
        totalPaid = totalPaid - (payment.amount || 0) + formData.amount;
      } else {
        totalPaid = totalPaid + formData.amount;
      }
      
      let newStatus = invoice.status;
      if (totalPaid >= invoiceTotal) {
        newStatus = 'paid';
      } else if (totalPaid > 0) {
        newStatus = 'partial';
      } else {
        newStatus = 'sent';
      }

      await updateRecord('invoices', {
        status: newStatus,
      }, { id: invoice.id }, user.id);

      toast({
        title: 'Success',
        description: `Payment of ₹${formData.amount.toLocaleString()} ${payment ? 'updated' : 'recorded'} successfully`,
      });

      onPaymentSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving payment:', error);
      toast({
        title: 'Error',
        description: error?.message || 'Failed to record payment. Please try again.',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{payment ? 'Edit Payment' : 'Record Payment'}</DialogTitle>
          <DialogDescription>
            {payment ? 'Update payment details' : 'Record a new payment for an invoice'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="invoice_id">Invoice *</Label>
              <Select
                value={formData.invoice_id}
                onValueChange={(value) => {
                  setFormData(prev => ({ ...prev, invoice_id: value }));
                }}
                disabled={!!invoiceId || !!payment}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select invoice">
                    {invoicesLoading ? (
                      <span className="text-muted-foreground">Loading...</span>
                    ) : selectedInvoice ? (
                      `${selectedInvoice.invoice_number} - ${selectedInvoice.title}`
                    ) : (
                      'Select invoice'
                    )}
                  </SelectValue>
                </SelectTrigger>
                <SelectContent>
                  {invoices.map((inv: unknown) => {
                    const total = inv.total_amount || 
                      (inv.subtotal * (1 + (inv.tax_rate || 0) / 100) - (inv.discount || 0));
                    return (
                      <SelectItem key={inv.id} value={inv.id}>
                        {inv.invoice_number} - {inv.title} (₹{Number(total).toLocaleString()})
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
              {selectedInvoice && (
                <p className="text-xs text-muted-foreground">
                  Total: ₹{Number(selectedInvoice.total_amount || 
                    (selectedInvoice.subtotal * (1 + (selectedInvoice.tax_rate || 0) / 100) - (selectedInvoice.discount || 0))
                  ).toLocaleString()}
                </p>
              )}
            </div>

            <div className="space-y-2">
              <Label htmlFor="payment_date">Payment Date *</Label>
              <Input
                id="payment_date"
                type="date"
                value={formData.payment_date}
                onChange={(e) => setFormData(prev => ({ ...prev, payment_date: e.target.value }))}
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="amount">Amount (₹) *</Label>
              <Input
                id="amount"
                type="number"
                step="0.01"
                min="0"
                value={formData.amount}
                onChange={(e) => setFormData(prev => ({ ...prev, amount: Number(e.target.value) || 0 }))}
                required
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="payment_method">Payment Method *</Label>
              <Select
                value={formData.payment_method}
                onValueChange={(value) => setFormData(prev => ({ ...prev, payment_method: value }))}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select payment method" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="bank_transfer">Bank Transfer</SelectItem>
                  <SelectItem value="cash">Cash</SelectItem>
                  <SelectItem value="credit_card">Credit Card</SelectItem>
                  <SelectItem value="debit_card">Debit Card</SelectItem>
                  <SelectItem value="cheque">Cheque</SelectItem>
                  <SelectItem value="upi">UPI</SelectItem>
                  <SelectItem value="online">Online Payment</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="reference_number">Reference Number</Label>
            <Input
              id="reference_number"
              value={formData.reference_number}
              onChange={(e) => setFormData(prev => ({ ...prev, reference_number: e.target.value }))}
              placeholder="Transaction ID, Cheque Number, etc."
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes}
              onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
              placeholder="Additional notes about this payment..."
              rows={3}
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={onClose} disabled={loading}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {payment ? 'Update Payment' : 'Record Payment'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default PaymentFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { insertRecord, updateRecord, selectRecords } from '@/services/api/core';
import { useAuth } from '@/hooks/useAuth';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';

interface Payroll {
  id?: string;
  employee_id: string;
  payroll_period_id: string;
  base_salary: number;
  overtime_pay?: number;
  bonuses?: number;
  deductions?: number;
  gross_pay: number;
  tax_deductions?: number;
  net_pay: number;
  hours_worked?: number;
  overtime_hours?: number;
  status: 'draft' | 'approved' | 'paid';
  notes?: string | null;
}

interface PayrollFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  payroll?: Payroll | null;
  onPayrollSaved: () => void;
  payrollPeriodId?: string;
}

const PayrollFormDialog: React.FC<PayrollFormDialogProps> = ({ 
  isOpen, 
  onClose, 
  payroll, 
  onPayrollSaved,
  payrollPeriodId 
}) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [employees, setEmployees] = useState<unknown[]>([]);
  const [payrollPeriods, setPayrollPeriods] = useState<unknown[]>([]);
  const [formData, setFormData] = useState<Payroll>({
    employee_id: payroll?.employee_id || '',
    payroll_period_id: payroll?.payroll_period_id || payrollPeriodId || '',
    base_salary: payroll?.base_salary || 0,
    overtime_pay: payroll?.overtime_pay || 0,
    bonuses: payroll?.bonuses || 0,
    deductions: payroll?.deductions || 0,
    gross_pay: payroll?.gross_pay || 0,
    tax_deductions: payroll?.tax_deductions || 0,
    net_pay: payroll?.net_pay || 0,
    hours_worked: payroll?.hours_worked || 0,
    overtime_hours: payroll?.overtime_hours || 0,
    status: payroll?.status || 'draft',
    notes: payroll?.notes || '',
  });

  useEffect(() => {
    if (isOpen) {
      fetchEmployees();
      fetchPayrollPeriods();
      if (payroll) {
        setFormData({
          employee_id: payroll.employee_id,
          payroll_period_id: payroll.payroll_period_id,
          base_salary: payroll.base_salary,
          overtime_pay: payroll.overtime_pay || 0,
          bonuses: payroll.bonuses || 0,
          deductions: payroll.deductions || 0,
          gross_pay: payroll.gross_pay,
          tax_deductions: payroll.tax_deductions || 0,
          net_pay: payroll.net_pay,
          hours_worked: payroll.hours_worked || 0,
          overtime_hours: payroll.overtime_hours || 0,
          status: payroll.status,
          notes: payroll.notes || '',
        });
      } else {
        setFormData({
          employee_id: '',
          payroll_period_id: payrollPeriodId || '',
          base_salary: 0,
          overtime_pay: 0,
          bonuses: 0,
          deductions: 0,
          gross_pay: 0,
          tax_deductions: 0,
          net_pay: 0,
          hours_worked: 0,
          overtime_hours: 0,
          status: 'draft',
          notes: '',
        });
      }
    }
  }, [isOpen, payroll, payrollPeriodId]);

  const fetchEmployees = async () => {
    try {
      // Use standardized employee fetching service
      const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
      
      // Payroll uses employee_id (from employee_details.id), so we need to fetch employee_details
      // to get the employee_id (which is employee_details.id) for each user_id
      const userIds = employeesData.map(emp => emp.user_id);
      if (userIds.length > 0) {
        const employeeDetails = await selectRecords('employee_details', {
          filters: [
            { column: 'user_id', operator: 'in', value: userIds },
            { column: 'is_active', operator: 'eq', value: true }
          ]
        });
        
        const employeeDetailsMap = new Map(employeeDetails.map((ed: unknown) => [ed.user_id, ed]));
        
        // Combine employee data with employee_details
        // IMPORTANT: employee_id in payroll table is employee_details.id, not user_id
        const employeesWithDetails = employeesData
          .filter(emp => employeeDetailsMap.has(emp.user_id))
          .map(emp => {
            const ed = employeeDetailsMap.get(emp.user_id);
            return {
              ...(ed || {}),
              user_id: emp.user_id,
              id: ed?.id, // This is the employee_details.id used in payroll table
              employee_id: ed?.id, // This is what goes into payroll.employee_id
              display_name: emp.full_name,
              employee_code: ed?.employee_id || ed?.id?.substring(0, 8)
            };
          });
        
        setEmployees(employeesWithDetails);
      } else {
        setEmployees([]);
      }
    } catch (error) {
      console.error('Error fetching employees:', error);
      setEmployees([]);
    }
  };

  const fetchPayrollPeriods = async () => {
    try {
      const periods = await selectRecords('payroll_periods', {
        orderBy: 'start_date DESC',
      });
      setPayrollPeriods(periods || []);
    } catch (error) {
      console.error('Error fetching payroll periods:', error);
    }
  };

  const calculateTotals = () => {
    const baseSalary = parseFloat(String(formData.base_salary || 0));
    const overtimePay = parseFloat(String(formData.overtime_pay || 0));
    const bonuses = parseFloat(String(formData.bonuses || 0)); // This maps to allowances in DB
    const deductions = parseFloat(String(formData.deductions || 0));
    const taxDeductions = parseFloat(String(formData.tax_deductions || 0)); // This maps to tax_amount in DB
    
    const grossPay = baseSalary + overtimePay + bonuses;
    const netPay = grossPay - deductions - taxDeductions;
    
    return { grossPay, netPay };
  };

  // Auto-fill employee salary details when employee is selected
  const handleEmployeeChange = async (employeeId: string) => {
    handleFieldChange('employee_id', employeeId);
    
    if (!employeeId) return;
    
    try {
      // Find the employee_details record
      const employeeDetail = employees.find(emp => emp.id === employeeId);
      if (!employeeDetail) return;
      
      // Fetch employee_salary_details to auto-fill base salary
      const salaryDetails = await selectRecords('employee_salary_details', {
        where: { employee_id: employeeId },
        orderBy: 'effective_date DESC',
        limit: 1
      });
      
      if (salaryDetails && salaryDetails.length > 0) {
        const latestSalary = salaryDetails[0];
        const baseSalary = parseFloat(String(latestSalary.base_salary || latestSalary.salary || 0));
        handleFieldChange('base_salary', baseSalary);
      }
      
      // Auto-calculate hours from attendance if payroll period is selected
      if (formData.payroll_period_id) {
        await calculateHoursFromAttendance(employeeId, formData.payroll_period_id);
      }
    } catch (error) {
      console.error('Error fetching employee salary details:', error);
    }
  };

  // Auto-calculate hours from attendance when period is selected
  const handlePeriodChange = async (periodId: string) => {
    handleFieldChange('payroll_period_id', periodId);
    
    if (!periodId || !formData.employee_id) return;
    
    await calculateHoursFromAttendance(formData.employee_id, periodId);
  };

  // Calculate hours worked and overtime from attendance records
  const calculateHoursFromAttendance = async (employeeId: string, periodId: string) => {
    try {
      // Get payroll period dates
      const period = payrollPeriods.find(p => p.id === periodId);
      if (!period) return;
      
      // Get employee_details to find user_id (attendance uses user_id as employee_id)
      const employeeDetail = employees.find(emp => emp.id === employeeId);
      if (!employeeDetail || !employeeDetail.user_id) return;
      
      // Fetch attendance records for the period
      // Note: attendance.employee_id is actually user_id
      // Format dates properly (YYYY-MM-DD)
      const startDate = period.start_date.split('T')[0];
      const endDate = period.end_date.split('T')[0];
      
      const attendanceRecords = await selectRecords('attendance', {
        filters: [
          { column: 'employee_id', operator: 'eq', value: employeeDetail.user_id },
          { column: 'date', operator: 'gte', value: startDate },
          { column: 'date', operator: 'lte', value: endDate }
        ]
      });
      
      // Calculate total hours and overtime
      let totalHours = 0;
      let totalOvertime = 0;
      
      attendanceRecords.forEach((record: unknown) => {
        const hours = parseFloat(String(record.hours_worked || record.total_hours || 0));
        totalHours += hours;
        
        // Calculate overtime (anything over 8 hours per day)
        const overtime = hours > 8 ? hours - 8 : 0;
        totalOvertime += overtime;
      });
      
      handleFieldChange('hours_worked', Math.round(totalHours * 10) / 10);
      handleFieldChange('overtime_hours', Math.round(totalOvertime * 10) / 10);
      
      // Auto-calculate overtime pay if hourly rate is available
      // Use current formData state
      setFormData(prev => {
        const currentBaseSalary = prev.base_salary || 0;
        if (totalOvertime > 0 && currentBaseSalary > 0) {
          // Assume monthly salary, calculate hourly rate (monthly / 160 hours)
          const hourlyRate = currentBaseSalary / 160;
          const overtimePay = totalOvertime * hourlyRate * 1.5; // 1.5x for overtime
          return {
            ...prev,
            overtime_pay: Math.round(overtimePay * 100) / 100
          };
        }
        return prev;
      });
    } catch (error) {
      console.error('Error calculating hours from attendance:', error);
    }
  };

  const handleFieldChange = (field: keyof Payroll, value: unknown) => {
    setFormData(prev => {
      const updated = { ...prev, [field]: value };
      const { grossPay, netPay } = calculateTotals();
      return {
        ...updated,
        gross_pay: grossPay,
        net_pay: netPay,
      };
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { grossPay, netPay } = calculateTotals();
      
      // Map frontend field names to database field names
      const cleanedData: unknown = {
        employee_id: formData.employee_id, // This is employee_details.id
        payroll_period_id: formData.payroll_period_id,
        base_salary: parseFloat(String(formData.base_salary || 0)),
        overtime_pay: parseFloat(String(formData.overtime_pay || 0)) || 0,
        allowances: parseFloat(String(formData.bonuses || 0)) || 0, // bonuses maps to allowances
        deductions: parseFloat(String(formData.deductions || 0)) || 0,
        gross_salary: grossPay, // gross_pay maps to gross_salary
        tax_amount: parseFloat(String(formData.tax_deductions || 0)) || 0, // tax_deductions maps to tax_amount
        net_salary: netPay, // net_pay maps to net_salary
        overtime_hours: parseFloat(String(formData.overtime_hours || 0)) || 0,
        status: formData.status,
        notes: formData.notes?.trim() || null,
      };
      
      // Add hours_worked if the column exists (it might not be in all databases)
      // We'll try to add it, but if it fails, we'll continue without it
      if (formData.hours_worked && formData.hours_worked > 0) {
        cleanedData.hours_worked = parseFloat(String(formData.hours_worked || 0));
      }

      if (payroll?.id) {
        await updateRecord('payroll', cleanedData, { id: payroll.id }, user?.id);
        toast({
          title: 'Success',
          description: 'Payroll record updated successfully',
        });
      } else {
        await insertRecord('payroll', cleanedData, user?.id);
        toast({
          title: 'Success',
          description: 'Payroll record created successfully',
        });
      }

      onPayrollSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving payroll:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save payroll record',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const { grossPay, netPay } = calculateTotals();

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{payroll?.id ? 'Edit Payroll Record' : 'Create New Payroll Record'}</DialogTitle>
          <DialogDescription>
            {payroll?.id ? 'Update payroll record details below.' : 'Fill in the details to create a new payroll record.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="employee_id">Employee *</Label>
              <Select 
                value={formData.employee_id} 
                onValueChange={handleEmployeeChange}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select employee" />
                </SelectTrigger>
                <SelectContent>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.display_name} {emp.employee_code ? `(${emp.employee_code})` : ''}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="payroll_period_id">Payroll Period *</Label>
              <Select 
                value={formData.payroll_period_id} 
                onValueChange={handlePeriodChange}
                required
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select payroll period" />
                </SelectTrigger>
                <SelectContent>
                  {payrollPeriods.map((period) => (
                    <SelectItem key={period.id} value={period.id}>
                      {period.name} ({new Date(period.start_date).toLocaleDateString()} - {new Date(period.end_date).toLocaleDateString()})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="base_salary">Base Salary (₹) *</Label>
              <Input
                id="base_salary"
                type="number"
                step="0.01"
                value={formData.base_salary}
                onChange={(e) => handleFieldChange('base_salary', parseFloat(e.target.value) || 0)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="status">Status *</Label>
              <Select 
                value={formData.status} 
                onValueChange={(value: unknown) => handleFieldChange('status', value)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="paid">Paid</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="overtime_pay">Overtime Pay (₹)</Label>
              <Input
                id="overtime_pay"
                type="number"
                step="0.01"
                value={formData.overtime_pay || 0}
                onChange={(e) => handleFieldChange('overtime_pay', parseFloat(e.target.value) || 0)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="bonuses">Bonuses (₹)</Label>
              <Input
                id="bonuses"
                type="number"
                step="0.01"
                value={formData.bonuses || 0}
                onChange={(e) => handleFieldChange('bonuses', parseFloat(e.target.value) || 0)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="deductions">Deductions (₹)</Label>
              <Input
                id="deductions"
                type="number"
                step="0.01"
                value={formData.deductions || 0}
                onChange={(e) => handleFieldChange('deductions', parseFloat(e.target.value) || 0)}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label htmlFor="tax_deductions">Tax Deductions (₹)</Label>
              <Input
                id="tax_deductions"
                type="number"
                step="0.01"
                value={formData.tax_deductions || 0}
                onChange={(e) => handleFieldChange('tax_deductions', parseFloat(e.target.value) || 0)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="hours_worked">Hours Worked</Label>
              <Input
                id="hours_worked"
                type="number"
                step="0.1"
                value={formData.hours_worked || 0}
                onChange={(e) => handleFieldChange('hours_worked', parseFloat(e.target.value) || 0)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="overtime_hours">Overtime Hours</Label>
              <Input
                id="overtime_hours"
                type="number"
                step="0.1"
                value={formData.overtime_hours || 0}
                onChange={(e) => handleFieldChange('overtime_hours', parseFloat(e.target.value) || 0)}
              />
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 p-4 bg-muted rounded-lg">
            <div>
              <Label className="text-muted-foreground">Gross Pay</Label>
              <p className="text-2xl font-bold">₹{grossPay.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
            </div>
            <div>
              <Label className="text-muted-foreground">Net Pay</Label>
              <p className="text-2xl font-bold text-green-600">₹{netPay.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</p>
            </div>
          </div>

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea
              id="notes"
              value={formData.notes || ''}
              onChange={(e) => handleFieldChange('notes', e.target.value)}
              rows={3}
              placeholder="Additional notes about this payroll record"
            />
          </div>

          <DialogFooter className="flex flex-col sm:flex-row gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} className="w-full sm:w-auto">
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="w-full sm:w-auto">
              {loading ? 'Saving...' : payroll?.id ? 'Update Payroll' : 'Create Payroll'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default PayrollFormDialog;

import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { X, Search, Plus, Loader2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import { projectService, Project as ProjectType } from '@/services/api/projects';
import { selectRecords } from '@/services/api/core';
import { getAgencyId } from '@/utils/agencyUtils';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';
import { getClientsForSelectionAuto } from '@/services/api/selectors';
import { getDepartmentsForSelectionAuto } from '@/services/api/departments';
import { Command, CommandEmpty, CommandGroup, CommandInput, CommandItem, CommandList } from '@/components/ui/command';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Checkbox } from '@/components/ui/checkbox';

interface Project {
  id?: string;
  name: string;
  description: string | null;
  project_code?: string | null;
  project_type?: string | null;
  status: string;
  priority?: 'low' | 'medium' | 'high' | 'critical';
  start_date: string | null;
  end_date: string | null;
  deadline?: string | null;
  budget: number | null;
  actual_cost?: number | null;
  allocated_budget?: number | null;
  cost_center?: string | null;
  currency?: string;
  client_id: string | null;
  project_manager_id?: string | null;
  account_manager_id?: string | null;
  assigned_team: unknown; // JSONB - array of user IDs
  departments?: string[]; // Array of department IDs
  tags?: string[];
  categories?: string[];
  progress: number;
}

interface Client {
  id: string;
  name: string;
  company_name: string | null;
  email: string | null;
}

interface Employee {
  id: string;
  user_id: string;
  full_name: string;
  display_name?: string;
  department?: string;
  position?: string;
}

interface Department {
  id: string;
  name: string;
  manager_name?: string;
  member_count?: number;
}

interface ProjectFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  project?: Project | null;
  onProjectSaved: () => void;
}

const ProjectFormDialog: React.FC<ProjectFormDialogProps> = ({ isOpen, onClose, project, onProjectSaved }) => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);
  const [loadingClients, setLoadingClients] = useState(false);
  const [clientSearchOpen, setClientSearchOpen] = useState(false);
  const [clientSearchTerm, setClientSearchTerm] = useState('');
  
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loadingEmployees, setLoadingEmployees] = useState(false);
  const [selectedTeamMembers, setSelectedTeamMembers] = useState<string[]>([]); // Array of user_ids
  const [teamMemberSearchOpen, setTeamMemberSearchOpen] = useState(false);
  const [teamMemberSearchTerm, setTeamMemberSearchTerm] = useState('');
  
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loadingDepartments, setLoadingDepartments] = useState(false);
  const [selectedDepartments, setSelectedDepartments] = useState<string[]>([]); // Array of department IDs
  
  const [tagInput, setTagInput] = useState('');
  const [categoryInput, setCategoryInput] = useState('');

  const [formData, setFormData] = useState<Project>({
    name: '',
    description: '',
    project_code: null,
    project_type: null,
    status: 'planning',
    priority: 'medium',
    start_date: null,
    end_date: null,
    deadline: null,
    budget: null,
    actual_cost: 0,
    allocated_budget: null,
    cost_center: null,
    currency: 'USD',
    client_id: null,
    project_manager_id: null,
    account_manager_id: null,
    assigned_team: [],
    departments: [],
    tags: [],
    categories: [],
    progress: 0,
  });

  // Normalize status value for display (convert database format to form format)
  const normalizeStatusForDisplay = (status: string | undefined): string => {
    if (!status) return 'planning';
    if (status === 'in_progress') return 'in-progress';
    if (status === 'on_hold') return 'on-hold';
    return status;
  };

  // Normalize status value for database (convert form format to database format)
  const normalizeStatusForDatabase = (status: string): string => {
    if (status === 'in-progress') return 'in_progress';
    if (status === 'on-hold') return 'on_hold';
    return status;
  };

  // Format date for input field (YYYY-MM-DD)
  const formatDateForInput = (dateString: string | null | undefined): string | null => {
    if (!dateString) return null;
    try {
      // Handle date strings that might already be in YYYY-MM-DD format
      if (typeof dateString === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
        // Validate it's a reasonable date (after 2000)
        if (dateString < '2000-01-01') {
          console.warn('Invalid date detected (too old):', dateString);
          return null;
        }
        return dateString;
      }
      
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return null;
      
      // Check if date is reasonable (after year 2000)
      const year = date.getFullYear();
      if (year < 2000 || year > 2100) {
        console.warn('Invalid date detected (out of range):', dateString, 'Year:', year);
        return null;
      }
      
      return date.toISOString().split('T')[0];
    } catch (error) {
      console.warn('Error formatting date:', dateString, error);
      return null;
    }
  };

  // Update form data when project prop changes or dialog opens
  useEffect(() => {
    if (isOpen) {
      if (project && project.id) {
        // Editing existing project - populate form with project data
        const proj = project as unknown;
        setFormData({
          name: proj.name || '',
          description: proj.description || '',
          project_code: proj.project_code || null,
          project_type: proj.project_type || null,
          status: normalizeStatusForDisplay(proj.status),
          priority: proj.priority || 'medium',
          start_date: formatDateForInput(proj.start_date),
          end_date: formatDateForInput(proj.end_date),
          deadline: formatDateForInput(proj.deadline),
          budget: proj.budget || null,
          actual_cost: proj.actual_cost || 0,
          allocated_budget: proj.allocated_budget || null,
          cost_center: proj.cost_center || null,
          currency: proj.currency || 'USD',
          client_id: proj.client_id || null,
          project_manager_id: proj.project_manager_id || null,
          account_manager_id: proj.account_manager_id || null,
          assigned_team: [],
          departments: Array.isArray(proj.departments) ? proj.departments : [],
          tags: Array.isArray(proj.tags) ? proj.tags : [],
          categories: Array.isArray(proj.categories) ? proj.categories : [],
          progress: proj.progress || 0,
        });

        // Parse assigned_team from project - expect array of user IDs
        if (proj.assigned_team) {
          let parsed: string[] = [];
          if (typeof proj.assigned_team === 'string') {
            try {
              const parsedJson = JSON.parse(proj.assigned_team);
              if (Array.isArray(parsedJson)) {
                // Extract user IDs from objects or use strings directly
                parsed = parsedJson.map((m: unknown) => 
                  typeof m === 'string' ? m : m.user_id || m.id || String(m)
                );
              }
            } catch {
              parsed = [];
            }
          } else if (Array.isArray(proj.assigned_team)) {
            parsed = proj.assigned_team.map((m: unknown) => 
              typeof m === 'string' ? m : m.user_id || m.id || String(m)
            );
          }
          setSelectedTeamMembers(parsed);
        } else {
          setSelectedTeamMembers([]);
        }

        // Set selected departments
        if (proj.departments && Array.isArray(proj.departments)) {
          setSelectedDepartments(proj.departments);
        } else {
          setSelectedDepartments([]);
        }
      } else {
        // Creating new project - reset form
        setFormData({
          name: '',
          description: '',
          project_code: null,
          project_type: null,
          status: 'planning',
          priority: 'medium',
          start_date: null,
          end_date: null,
          deadline: null,
          budget: null,
          actual_cost: 0,
          allocated_budget: null,
          cost_center: null,
          currency: 'USD',
          client_id: null,
          project_manager_id: null,
          account_manager_id: null,
          assigned_team: [],
          departments: [],
          tags: [],
          categories: [],
          progress: 0,
        });
        setSelectedTeamMembers([]);
        setSelectedDepartments([]);
        setTagInput('');
        setCategoryInput('');
      }
    }
  }, [project, isOpen]);

  // Fetch clients, employees, and departments when dialog opens
  useEffect(() => {
    if (isOpen) {
      fetchClients();
      fetchEmployees();
      fetchDepartments();
    }
  }, [isOpen]);

  const fetchClients = async () => {
    try {
      setLoadingClients(true);
      
      // Use standardized client fetching service
      const clientsData = await getClientsForSelectionAuto(profile, user?.id, {
        includeInactive: false
      });
      
      // Transform to Client interface format
      setClients(clientsData.map(c => ({
        id: c.id,
        name: c.name,
        company_name: c.company_name,
        email: c.email
      })));
    } catch (error: unknown) {
      console.error('Error fetching clients:', error);
      toast({
        title: 'Error',
        description: 'Failed to load clients',
        variant: 'destructive',
      });
    } finally {
      setLoadingClients(false);
    }
  };

  const fetchEmployees = async () => {
    try {
      setLoadingEmployees(true);
      
      // Use standardized employee fetching service
      const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
      
      // Transform to Employee interface format
      const transformedEmployees: Employee[] = employeesData.map(emp => ({
        id: emp.user_id,
        user_id: emp.user_id,
        full_name: emp.full_name,
        display_name: emp.display_name || emp.full_name,
        department: emp.department,
        position: emp.position
      }));
      
      setEmployees(transformedEmployees);
    } catch (error: unknown) {
      console.error('Error fetching employees:', error);
      toast({
        title: 'Error',
        description: 'Failed to load employees',
        variant: 'destructive',
      });
    } finally {
      setLoadingEmployees(false);
    }
  };

  const fetchDepartments = async () => {
    try {
      setLoadingDepartments(true);
      
      // Use standardized department fetching service
      const departmentsData = await getDepartmentsForSelectionAuto(profile, user?.id, {
        includeInactive: false
      });
      
      // Transform to Department interface format
      setDepartments(departmentsData.map(d => ({
        id: d.id,
        name: d.name,
        manager_name: d.manager_name || undefined,
        member_count: d.member_count || undefined
      })));
    } catch (error: unknown) {
      console.error('Error fetching departments:', error);
      toast({
        title: 'Error',
        description: 'Failed to load departments',
        variant: 'destructive',
      });
    } finally {
      setLoadingDepartments(false);
    }
  };

  const addTag = () => {
    if (tagInput.trim() && !formData.tags?.includes(tagInput.trim())) {
      setFormData(prev => ({
        ...prev,
        tags: [...(prev.tags || []), tagInput.trim()]
      }));
      setTagInput('');
    }
  };

  const removeTag = (tag: string) => {
    setFormData(prev => ({
      ...prev,
      tags: (prev.tags || []).filter(t => t !== tag)
    }));
  };

  const addCategory = () => {
    if (categoryInput.trim() && !formData.categories?.includes(categoryInput.trim())) {
      setFormData(prev => ({
        ...prev,
        categories: [...(prev.categories || []), categoryInput.trim()]
      }));
      setCategoryInput('');
    }
  };

  const removeCategory = (category: string) => {
    setFormData(prev => ({
      ...prev,
      categories: (prev.categories || []).filter(c => c !== category)
    }));
  };

  const toggleTeamMember = (userId: string) => {
    setSelectedTeamMembers(prev => {
      if (prev.includes(userId)) {
        return prev.filter(id => id !== userId);
      } else {
        return [...prev, userId];
      }
    });
  };

  const toggleDepartment = (deptId: string) => {
    setSelectedDepartments(prev => {
      if (prev.includes(deptId)) {
        return prev.filter(id => id !== deptId);
      } else {
        return [...prev, deptId];
      }
    });
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    // Validation
    if (!formData.name.trim()) {
      toast({
        title: 'Validation Error',
        description: 'Project name is required',
        variant: 'destructive',
      });
      return;
    }

    if (formData.progress < 0 || formData.progress > 100) {
      toast({
        title: 'Validation Error',
        description: 'Progress must be between 0 and 100',
        variant: 'destructive',
      });
      return;
    }

    // Date validation
    const today = new Date().toISOString().split('T')[0]; // YYYY-MM-DD format
    const minDate = '2000-01-01'; // Reasonable minimum date
    
    if (formData.start_date) {
      // Check if start date is too old (before 2000)
      if (formData.start_date < minDate) {
        toast({
          title: 'Validation Error',
          description: 'Start date cannot be before year 2000. Please enter a valid date.',
          variant: 'destructive',
        });
        return;
      }
    }

    if (formData.end_date) {
      // Check if end date is too old
      if (formData.end_date < minDate) {
        toast({
          title: 'Validation Error',
          description: 'End date cannot be before year 2000. Please enter a valid date.',
          variant: 'destructive',
        });
        return;
      }
    }

    if (formData.deadline) {
      // Check if deadline is too old
      if (formData.deadline < minDate) {
        toast({
          title: 'Validation Error',
          description: 'Deadline cannot be before year 2000. Please enter a valid date.',
          variant: 'destructive',
        });
        return;
      }
    }

    if (formData.start_date && formData.end_date && formData.start_date > formData.end_date) {
      toast({
        title: 'Validation Error',
        description: 'End date must be after start date',
        variant: 'destructive',
      });
      return;
    }

    if (formData.start_date && formData.deadline && formData.start_date > formData.deadline) {
      toast({
        title: 'Validation Error',
        description: 'Deadline must be after start date',
        variant: 'destructive',
      });
      return;
    }

    if (formData.allocated_budget && formData.budget && formData.allocated_budget > formData.budget) {
      toast({
        title: 'Validation Error',
        description: 'Allocated budget cannot exceed total budget',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);

    try {
      const projectData: Partial<ProjectType> = {
        name: formData.name.trim(),
        description: formData.description?.trim() || null,
        project_code: formData.project_code || undefined,
        project_type: formData.project_type || undefined,
        status: normalizeStatusForDatabase(formData.status) as unknown,
        priority: formData.priority || 'medium',
        start_date: formData.start_date || null,
        end_date: formData.end_date || null,
        deadline: formData.deadline || null,
        budget: formData.budget || null,
        actual_cost: formData.actual_cost || 0,
        allocated_budget: formData.allocated_budget || null,
        cost_center: formData.cost_center || null,
        currency: formData.currency || 'USD',
        client_id: formData.client_id || null,
        project_manager_id: formData.project_manager_id || null,
        account_manager_id: formData.account_manager_id || null,
        assigned_team: selectedTeamMembers, // Array of user IDs
        departments: selectedDepartments, // Array of department IDs
        tags: formData.tags || [],
        categories: formData.categories || [],
        progress: formData.progress,
      };

      if (project?.id) {
        // Update existing project
        await projectService.updateProject(project.id, projectData, profile, user?.id);
        toast({
          title: 'Success',
          description: 'Project updated successfully',
        });
      } else {
        // Create new project
        await projectService.createProject(projectData, profile, user?.id);
        toast({
          title: 'Success',
          description: 'Project created successfully',
        });
      }

      onProjectSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving project:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save project',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  // Filter clients based on search term
  const filteredClients = clients.filter(client =>
    client.name.toLowerCase().includes(clientSearchTerm.toLowerCase()) ||
    client.company_name?.toLowerCase().includes(clientSearchTerm.toLowerCase()) ||
    client.email?.toLowerCase().includes(clientSearchTerm.toLowerCase())
  );

  // Filter employees based on search term
  const filteredEmployees = employees.filter(emp =>
    emp.full_name.toLowerCase().includes(teamMemberSearchTerm.toLowerCase()) ||
    emp.display_name?.toLowerCase().includes(teamMemberSearchTerm.toLowerCase()) ||
    emp.department?.toLowerCase().includes(teamMemberSearchTerm.toLowerCase())
  );

  const selectedClient = clients.find(c => c.id === formData.client_id);
  const selectedTeamMemberObjects = employees.filter(e => selectedTeamMembers.includes(e.user_id));
  const selectedDepartmentObjects = departments.filter(d => selectedDepartments.includes(d.id));

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto mx-4 sm:mx-auto">
        <DialogHeader>
          <DialogTitle className="text-lg sm:text-xl">{project?.id ? 'Edit Project' : 'Create New Project'}</DialogTitle>
          <DialogDescription className="text-sm sm:text-base">
            {project?.id ? 'Update project details below.' : 'Fill in the details to create a new project.'}
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Basic Information */}
          <div className="space-y-4 border-b pb-4">
            <h3 className="font-semibold text-sm">Basic Information</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="name">Project Name *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  required
                  placeholder="Enter project name"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="project_code">Project Code</Label>
                <Input
                  id="project_code"
                  value={formData.project_code || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, project_code: e.target.value || null }))}
                  placeholder="Auto-generated if empty"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="project_type">Project Type</Label>
                <Input
                  id="project_type"
                  value={formData.project_type || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, project_type: e.target.value || null }))}
                  placeholder="e.g., Web Development, Construction, Marketing"
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="status">Status</Label>
                <Select value={formData.status} onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="planning">Planning</SelectItem>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="in-progress">In Progress</SelectItem>
                    <SelectItem value="on-hold">On Hold</SelectItem>
                    <SelectItem value="completed">Completed</SelectItem>
                    <SelectItem value="cancelled">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="priority">Priority</Label>
                <Select value={formData.priority || 'medium'} onValueChange={(value: unknown) => setFormData(prev => ({ ...prev, priority: value }))}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="critical">Critical</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="progress">Progress (%)</Label>
                <Input
                  id="progress"
                  type="number"
                  min="0"
                  max="100"
                  value={formData.progress}
                  onChange={(e) => setFormData(prev => ({ ...prev, progress: Number(e.target.value) }))}
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description || ''}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                rows={3}
                placeholder="Enter project description"
              />
            </div>
          </div>

          {/* Client & Team Assignment */}
          <div className="space-y-4 border-b pb-4">
            <h3 className="font-semibold text-sm">Client & Team Assignment</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="client_id">Client</Label>
                <Popover open={clientSearchOpen} onOpenChange={setClientSearchOpen}>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      role="combobox"
                      className="w-full justify-between"
                      disabled={loadingClients}
                    >
                      {selectedClient ? (selectedClient.company_name || selectedClient.name) : "Select client..."}
                      <Search className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-full p-0" align="start">
                    <Command>
                      <CommandInput 
                        placeholder="Search clients..." 
                        value={clientSearchTerm}
                        onValueChange={setClientSearchTerm}
                      />
                      <CommandList>
                        <CommandEmpty>No clients found.</CommandEmpty>
                        <CommandGroup>
                          <CommandItem
                            value="__none__"
                            onSelect={() => {
                              setFormData(prev => ({ ...prev, client_id: null }));
                              setClientSearchOpen(false);
                            }}
                          >
                            No Client
                          </CommandItem>
                          {filteredClients.map((client) => (
                            <CommandItem
                              key={client.id}
                              value={client.id}
                              onSelect={() => {
                                setFormData(prev => ({ ...prev, client_id: client.id }));
                                setClientSearchOpen(false);
                                setClientSearchTerm('');
                              }}
                            >
                              {client.company_name || client.name}
                              {client.email && <span className="text-xs text-muted-foreground ml-2">({client.email})</span>}
                            </CommandItem>
                          ))}
                        </CommandGroup>
                      </CommandList>
                    </Command>
                  </PopoverContent>
                </Popover>
              </div>
              <div className="space-y-2">
                <Label htmlFor="project_manager_id">Project Manager</Label>
                <Select 
                  value={formData.project_manager_id || '__none__'} 
                  onValueChange={(value) => setFormData(prev => ({ ...prev, project_manager_id: value === '__none__' ? null : value }))}
                  disabled={loadingEmployees}
                >
                  <SelectTrigger>
                    <SelectValue placeholder={loadingEmployees ? "Loading..." : "Select project manager"} />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="__none__">No Project Manager</SelectItem>
                    {employees.map((emp) => (
                      <SelectItem key={emp.id} value={emp.id}>
                        {emp.full_name} {emp.department && `(${emp.department})`}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="account_manager_id">Account Manager</Label>
              <Select 
                value={formData.account_manager_id || '__none__'} 
                onValueChange={(value) => setFormData(prev => ({ ...prev, account_manager_id: value === '__none__' ? null : value }))}
                disabled={loadingEmployees}
              >
                <SelectTrigger>
                  <SelectValue placeholder={loadingEmployees ? "Loading..." : "Select account manager"} />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="__none__">No Account Manager</SelectItem>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.full_name} {emp.department && `(${emp.department})`}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Team Members</Label>
              <Popover open={teamMemberSearchOpen} onOpenChange={setTeamMemberSearchOpen}>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    role="combobox"
                    className="w-full justify-between"
                    disabled={loadingEmployees}
                  >
                    {selectedTeamMemberObjects.length > 0 
                      ? `${selectedTeamMemberObjects.length} member(s) selected`
                      : "Select team members..."}
                    <Search className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-full p-0" align="start">
                  <Command>
                    <CommandInput 
                      placeholder="Search employees..." 
                      value={teamMemberSearchTerm}
                      onValueChange={setTeamMemberSearchTerm}
                    />
                    <CommandList>
                      <CommandEmpty>No employees found.</CommandEmpty>
                      <CommandGroup>
                        {filteredEmployees.map((emp) => (
                          <CommandItem
                            key={emp.id}
                            value={emp.id}
                            onSelect={() => {
                              toggleTeamMember(emp.user_id);
                            }}
                          >
                            <Checkbox
                              checked={selectedTeamMembers.includes(emp.user_id)}
                              onCheckedChange={() => toggleTeamMember(emp.user_id)}
                              className="mr-2"
                            />
                            {emp.full_name}
                            {emp.department && <span className="text-xs text-muted-foreground ml-2">({emp.department})</span>}
                          </CommandItem>
                        ))}
                      </CommandGroup>
                    </CommandList>
                  </Command>
                </PopoverContent>
              </Popover>
              {selectedTeamMemberObjects.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {selectedTeamMemberObjects.map((emp) => (
                    <Badge key={emp.id} variant="secondary" className="flex items-center gap-1">
                      {emp.full_name}
                      <button
                        type="button"
                        onClick={() => toggleTeamMember(emp.user_id)}
                        className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                </div>
              )}
            </div>

            <div className="space-y-2">
              <Label>Departments</Label>
              <div className="border rounded-md p-2 max-h-48 overflow-y-auto">
                {loadingDepartments ? (
                  <div className="flex items-center justify-center py-4">
                    <Loader2 className="h-4 w-4 animate-spin" />
                  </div>
                ) : departments.length === 0 ? (
                  <p className="text-sm text-muted-foreground py-2">No departments available</p>
                ) : (
                  <div className="space-y-2">
                    {departments.map((dept) => (
                      <div key={dept.id} className="flex items-center space-x-2">
                        <Checkbox
                          id={`dept-${dept.id}`}
                          checked={selectedDepartments.includes(dept.id)}
                          onCheckedChange={() => toggleDepartment(dept.id)}
                        />
                        <label
                          htmlFor={`dept-${dept.id}`}
                          className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer flex-1"
                        >
                          {dept.name}
                          {dept.member_count !== undefined && (
                            <span className="text-xs text-muted-foreground ml-2">({dept.member_count} members)</span>
                          )}
                        </label>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              {selectedDepartmentObjects.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {selectedDepartmentObjects.map((dept) => (
                    <Badge key={dept.id} variant="outline" className="flex items-center gap-1">
                      {dept.name}
                      <button
                        type="button"
                        onClick={() => toggleDepartment(dept.id)}
                        className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Timeline & Dates */}
          <div className="space-y-4 border-b pb-4">
            <h3 className="font-semibold text-sm">Timeline & Dates</h3>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="start_date">Start Date</Label>
                <Input
                  id="start_date"
                  type="date"
                  min="2000-01-01"
                  max="2100-12-31"
                  value={formData.start_date || ''}
                  onChange={(e) => {
                    const value = e.target.value || null;
                    // Validate date is reasonable
                    if (value && value < '2000-01-01') {
                      toast({
                        title: 'Invalid Date',
                        description: 'Start date cannot be before year 2000',
                        variant: 'destructive',
                      });
                      return;
                    }
                    setFormData(prev => ({ ...prev, start_date: value }));
                  }}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="end_date">End Date</Label>
                <Input
                  id="end_date"
                  type="date"
                  min={formData.start_date || '2000-01-01'}
                  max="2100-12-31"
                  value={formData.end_date || ''}
                  onChange={(e) => {
                    const value = e.target.value || null;
                    // Validate date is reasonable and after start date
                    if (value) {
                      if (value < '2000-01-01') {
                        toast({
                          title: 'Invalid Date',
                          description: 'End date cannot be before year 2000',
                          variant: 'destructive',
                        });
                        return;
                      }
                      if (formData.start_date && value < formData.start_date) {
                        toast({
                          title: 'Invalid Date',
                          description: 'End date must be after start date',
                          variant: 'destructive',
                        });
                        return;
                      }
                    }
                    setFormData(prev => ({ ...prev, end_date: value }));
                  }}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="deadline">Deadline</Label>
                <Input
                  id="deadline"
                  type="date"
                  min={formData.start_date || '2000-01-01'}
                  max="2100-12-31"
                  value={formData.deadline || ''}
                  onChange={(e) => {
                    const value = e.target.value || null;
                    // Validate date is reasonable and after start date
                    if (value) {
                      if (value < '2000-01-01') {
                        toast({
                          title: 'Invalid Date',
                          description: 'Deadline cannot be before year 2000',
                          variant: 'destructive',
                        });
                        return;
                      }
                      if (formData.start_date && value < formData.start_date) {
                        toast({
                          title: 'Invalid Date',
                          description: 'Deadline must be after start date',
                          variant: 'destructive',
                        });
                        return;
                      }
                    }
                    setFormData(prev => ({ ...prev, deadline: value }));
                  }}
                />
              </div>
            </div>
          </div>

          {/* Budget & Financial */}
          <div className="space-y-4 border-b pb-4">
            <h3 className="font-semibold text-sm">Budget & Financial</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="currency">Currency</Label>
                <Select value={formData.currency || 'USD'} onValueChange={(value) => setFormData(prev => ({ ...prev, currency: value }))}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="USD">USD ($)</SelectItem>
                    <SelectItem value="EUR">EUR (€)</SelectItem>
                    <SelectItem value="GBP">GBP (£)</SelectItem>
                    <SelectItem value="INR">INR (₹)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="budget">Total Budget</Label>
                <Input
                  id="budget"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.budget || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, budget: e.target.value ? Number(e.target.value) : null }))}
                  placeholder="0.00"
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="allocated_budget">Allocated Budget</Label>
                <Input
                  id="allocated_budget"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.allocated_budget || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, allocated_budget: e.target.value ? Number(e.target.value) : null }))}
                  placeholder="0.00"
                />
                {formData.allocated_budget && formData.budget && formData.allocated_budget > formData.budget && (
                  <p className="text-xs text-destructive">Allocated budget cannot exceed total budget</p>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="cost_center">Cost Center</Label>
                <Input
                  id="cost_center"
                  value={formData.cost_center || ''}
                  onChange={(e) => setFormData(prev => ({ ...prev, cost_center: e.target.value || null }))}
                  placeholder="e.g., Engineering, Marketing"
                />
              </div>
            </div>

            {project?.id && (
              <div className="space-y-2">
                <Label htmlFor="actual_cost">Actual Cost</Label>
                <Input
                  id="actual_cost"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.actual_cost || 0}
                  onChange={(e) => setFormData(prev => ({ ...prev, actual_cost: Number(e.target.value) }))}
                  placeholder="0.00"
                />
              </div>
            )}
          </div>

          {/* Tags & Categories */}
          <div className="space-y-4">
            <h3 className="font-semibold text-sm">Tags & Categories</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="tags">Tags</Label>
                <div className="flex gap-2">
                  <Input
                    id="tags"
                    value={tagInput}
                    onChange={(e) => setTagInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        addTag();
                      }
                    }}
                    placeholder="Enter tag and press Enter"
                  />
                  <Button type="button" onClick={addTag} variant="outline" size="icon">
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
                {formData.tags && formData.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-2">
                    {formData.tags.map((tag, index) => (
                      <Badge key={index} variant="secondary" className="flex items-center gap-1">
                        {tag}
                        <button
                          type="button"
                          onClick={() => removeTag(tag)}
                          className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                        >
                          <X className="h-3 w-3" />
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
              <div className="space-y-2">
                <Label htmlFor="categories">Categories</Label>
                <div className="flex gap-2">
                  <Input
                    id="categories"
                    value={categoryInput}
                    onChange={(e) => setCategoryInput(e.target.value)}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter') {
                        e.preventDefault();
                        addCategory();
                      }
                    }}
                    placeholder="Enter category and press Enter"
                  />
                  <Button type="button" onClick={addCategory} variant="outline" size="icon">
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
                {formData.categories && formData.categories.length > 0 && (
                  <div className="flex flex-wrap gap-2 mt-2">
                    {formData.categories.map((category, index) => (
                      <Badge key={index} variant="secondary" className="flex items-center gap-1">
                        {category}
                        <button
                          type="button"
                          onClick={() => removeCategory(category)}
                          className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                        >
                          <X className="h-3 w-3" />
                        </button>
                      </Badge>
                    ))}
                  </div>
                )}
              </div>
            </div>
          </div>

          <DialogFooter className="flex flex-col sm:flex-row gap-2 sm:gap-0">
            <Button type="button" variant="outline" onClick={onClose} className="w-full sm:w-auto">
              Cancel
            </Button>
            <Button type="submit" disabled={loading} className="w-full sm:w-auto">
              {loading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Saving...
                </>
              ) : project?.id ? 'Update Project' : 'Create Project'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default ProjectFormDialog;

import React, { useState, useEffect, useCallback } from 'react';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { generateUUID } from '@/lib/uuid';
import { useAuth } from '@/hooks/useAuth';
import { getAgencyId } from '@/utils/agencyUtils';
import { getClientsForSelectionAuto } from '@/services/api/selectors';
import { Plus, Trash2, X } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

interface QuotationLineItem {
  id: string;
  quotation_id?: string;
  item_name: string;
  description?: string;
  quantity: number;
  unit_price: number;
  discount_percentage?: number;
  line_total?: number;
  sort_order?: number;
}

interface Quotation {
  id?: string;
  quote_number?: string;
  quotation_number?: string;
  client_id: string;
  template_id?: string | null;
  title: string;
  description?: string;
  status: string;
  issue_date?: string;
  expiry_date?: string;
  valid_until: string;
  subtotal: number;
  tax_rate: number;
  tax_amount: number;
  discount?: number;
  total_amount: number;
  terms_conditions?: string;
  terms_and_conditions?: string;
  notes?: string;
  created_by?: string;
  agency_id?: string;
}

interface Client {
  id: string;
  name: string;
  company_name?: string;
}

interface QuotationTemplate {
  id: string;
  name: string;
  description?: string;
  template_data?: unknown;
}

interface QuotationFormDialogProps {
  isOpen: boolean;
  onClose: () => void;
  quotation?: Quotation | null;
  onQuotationSaved: () => void;
}

const QuotationFormDialog: React.FC<QuotationFormDialogProps> = ({ isOpen, onClose, quotation, onQuotationSaved }) => {
  const { toast } = useToast();
  const auth = useAuth();
  const user = auth?.user;
  const profile = auth?.profile;
  const [loading, setLoading] = useState(false);
  const [clients, setClients] = useState<Client[]>([]);
  const [templates, setTemplates] = useState<QuotationTemplate[]>([]);
  const [loadingClients, setLoadingClients] = useState(false);
  const [lineItems, setLineItems] = useState<QuotationLineItem[]>([]);
  const [formData, setFormData] = useState<Quotation>({
    client_id: quotation?.client_id || '',
    title: quotation?.title || '',
    description: quotation?.description || '',
    status: quotation?.status || 'draft',
    issue_date: quotation?.issue_date || '',
    expiry_date: quotation?.expiry_date || '',
    valid_until: quotation?.valid_until || '',
    subtotal: Number(quotation?.subtotal) || 0,
    tax_rate: Number(quotation?.tax_rate) || 18,
    tax_amount: Number(quotation?.tax_amount) || 0,
    discount: Number(quotation?.discount) || 0,
    total_amount: Number(quotation?.total_amount) || 0,
    terms_conditions: quotation?.terms_conditions || quotation?.terms_and_conditions || '',
    notes: quotation?.notes || '',
    template_id: quotation?.template_id || null,
  });
  const [savingDraft, setSavingDraft] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);

  // Format date for HTML date input (YYYY-MM-DD)
  const formatDateForInput = (dateString?: string): string => {
    if (!dateString) return '';
    try {
      const date = new Date(dateString);
      if (!isNaN(date.getTime())) {
        return date.toISOString().split('T')[0];
      }
    } catch (e) {
      console.error('Error formatting date:', e);
    }
    return '';
  };

  // Update formData when quotation prop changes
  useEffect(() => {
    if (quotation && quotation.id) {
      setFormData({
        client_id: quotation.client_id || '',
        title: quotation.title || '',
        description: quotation.description || '',
        status: quotation.status || 'draft',
        issue_date: formatDateForInput(quotation.issue_date),
        expiry_date: formatDateForInput(quotation.expiry_date),
        valid_until: formatDateForInput(quotation.valid_until),
        subtotal: Number(quotation.subtotal) || 0,
        tax_rate: Number(quotation.tax_rate) || 18,
        tax_amount: Number(quotation.tax_amount) || 0,
        discount: Number(quotation.discount) || 0,
        total_amount: Number(quotation.total_amount) || 0,
        terms_conditions: quotation.terms_conditions || quotation.terms_and_conditions || '',
        notes: quotation.notes || '',
        template_id: quotation.template_id || null,
      });
    } else if (!quotation) {
      // Reset form for new quotation
      const today = new Date().toISOString().split('T')[0];
      setFormData({
        client_id: '',
        title: '',
        description: '',
        status: 'draft',
        issue_date: today,
        expiry_date: '',
        valid_until: '',
        subtotal: 0,
        tax_rate: 18,
        tax_amount: 0,
        discount: 0,
        total_amount: 0,
        terms_conditions: '',
        notes: '',
        template_id: null,
      });
      setLastSaved(null);
    }
  }, [quotation]);

  useEffect(() => {
    if (isOpen) {
      fetchClients();
      fetchTemplates();
      if (quotation?.id) {
        fetchLineItems(quotation.id);
      } else {
        // Add one empty line item for new quotations
        setLineItems([{
          id: generateUUID(),
          item_name: '',
          description: '',
          quantity: 1,
          unit_price: 0,
          discount_percentage: 0,
          sort_order: 0,
        }]);
      }
    }
  }, [isOpen, quotation?.id]);

  const fetchClients = async () => {
    try {
      setLoadingClients(true);
      if (!user?.id) {
        setClients([]);
        return;
      }

      // Use standardized client fetching service
      const clientsData = await getClientsForSelectionAuto(profile, user.id);
      
      // Transform to component format
      setClients(clientsData.map(c => ({
        id: c.id,
        name: c.name,
        company_name: c.company_name || c.name
      })));
    } catch (error: unknown) {
      console.error('Error fetching clients:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch clients',
        variant: 'destructive',
      });
      setClients([]);
    } finally {
      setLoadingClients(false);
    }
  };

  const fetchTemplates = async () => {
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        console.warn('No agency_id available for fetching templates');
        setTemplates([]);
        return;
      }

      const { data, error } = await db
        .from('quotation_templates')
        .select('id, name, description, template_data')
        .eq('is_active', true)
        .eq('agency_id', agencyId)
        .order('name', { ascending: true });

      if (error) throw error;
      setTemplates(data || []);
    } catch (error: unknown) {
      console.error('Error fetching templates:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch templates',
        variant: 'destructive',
      });
    }
  };

  const fetchLineItems = async (quotationId: string) => {
    try {
      const { data, error } = await db
        .from('quotation_line_items')
        .select('*')
        .eq('quotation_id', quotationId)
        .order('sort_order', { ascending: true });

      if (error) throw error;
      setLineItems(data && data.length > 0 ? data : [{
        id: generateUUID(),
        item_name: '',
        description: '',
        quantity: 1,
        unit_price: 0,
        discount_percentage: 0,
        sort_order: 0,
      }]);
    } catch (error: unknown) {
      console.error('Error fetching line items:', error);
      setLineItems([{
        id: generateUUID(),
        item_name: '',
        description: '',
        quantity: 1,
        unit_price: 0,
        discount_percentage: 0,
        sort_order: 0,
      }]);
    }
  };

  const calculateLineTotal = (item: QuotationLineItem): number => {
    const subtotal = item.quantity * item.unit_price;
    const discount = subtotal * ((item.discount_percentage || 0) / 100);
    return subtotal - discount;
  };

  // Calculate totals when line items, tax rate, or discount changes
  useEffect(() => {
    const subtotal = lineItems.reduce((sum, item) => {
      if (item.item_name && item.item_name.trim()) {
        const itemSubtotal = item.quantity * item.unit_price;
        const itemDiscount = itemSubtotal * ((item.discount_percentage || 0) / 100);
        return sum + (itemSubtotal - itemDiscount);
      }
      return sum;
    }, 0);
    
    const discountAmount = Number(formData.discount) || 0;
    const subtotalAfterDiscount = Math.max(0, subtotal - discountAmount);
    const taxAmount = subtotalAfterDiscount * (formData.tax_rate / 100);
    const totalAmount = subtotalAfterDiscount + taxAmount;

    setFormData(prev => {
      // Only update if values actually changed to prevent infinite loops
      const prevSubtotal = Number(prev.subtotal) || 0;
      const prevTaxAmount = Number(prev.tax_amount) || 0;
      const prevTotalAmount = Number(prev.total_amount) || 0;
      
      if (Math.abs(prevSubtotal - subtotal) > 0.01 || 
          Math.abs(prevTaxAmount - taxAmount) > 0.01 || 
          Math.abs(prevTotalAmount - totalAmount) > 0.01) {
        return {
          ...prev,
          subtotal: Number(subtotal.toFixed(2)),
          tax_amount: Number(taxAmount.toFixed(2)),
          total_amount: Number(totalAmount.toFixed(2)),
        };
      }
      return prev;
    });
  }, [lineItems, formData.tax_rate, formData.discount]);

  // Auto-save draft functionality
  const saveDraft = useCallback(async () => {
    if (!formData.title.trim() || !formData.client_id) {
      return; // Don't save if required fields are missing
    }

    try {
      setSavingDraft(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId || !user?.id) {
        return;
      }

      const draftData = {
        ...formData,
        status: 'draft',
        agency_id: agencyId,
        created_by: user.id,
      };

      if (quotation?.id) {
        // Update existing draft
        await db
          .from('quotations')
          .update(draftData)
          .eq('id', quotation.id)
          .eq('agency_id', agencyId);
      } else {
        // Create new draft (only if title and client are filled)
        const quoteNumber = `Q-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
        const newDraft = {
          id: generateUUID(),
          quote_number: quoteNumber,
          ...draftData,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };

        const { data: insertedDraft } = await db
          .from('quotations')
          .insert([newDraft])
          .select()
          .single();

        if (insertedDraft) {
          // Update the quotation prop reference for future saves
          setFormData(prev => ({ ...prev, id: insertedDraft.id }));
        }
      }

      setLastSaved(new Date());
    } catch (error: unknown) {
      console.error('Error saving draft:', error);
      // Don't show error toast for auto-save failures
    } finally {
      setSavingDraft(false);
    }
  }, [formData, quotation, profile, user]);

  // Auto-save draft every 30 seconds when form has changes
  useEffect(() => {
    if (!isOpen || !formData.title.trim() || !formData.client_id) {
      return;
    }

    const autoSaveInterval = setInterval(() => {
      saveDraft();
    }, 30000); // Auto-save every 30 seconds

    return () => clearInterval(autoSaveInterval);
  }, [isOpen, formData.title, formData.client_id, saveDraft]);

  const handleLineItemChange = (id: string, field: keyof QuotationLineItem, value: unknown) => {
    setLineItems(prev => prev.map(item => {
      if (item.id === id) {
        const updated = { ...item, [field]: value };
        return { ...updated, line_total: calculateLineTotal(updated) };
      }
      return item;
    }));
  };

  const addLineItem = () => {
    setLineItems(prev => [...prev, {
      id: generateUUID(),
      item_name: '',
      description: '',
      quantity: 1,
      unit_price: 0,
      discount_percentage: 0,
      sort_order: prev.length,
    }]);
  };

  const removeLineItem = (id: string) => {
    setLineItems(prev => {
      const filtered = prev.filter(item => item.id !== id);
      if (filtered.length === 0) {
        return [{
          id: generateUUID(),
          item_name: '',
          description: '',
          quantity: 1,
          unit_price: 0,
          discount_percentage: 0,
          sort_order: 0,
        }];
      }
      return filtered.map((item, index) => ({ ...item, sort_order: index }));
    });
  };

  const useTemplate = async (templateId: string) => {
    try {
      const template = templates.find(t => t.id === templateId);
      if (!template || !template.template_data) return;

      const content = typeof template.template_data === 'string' 
        ? JSON.parse(template.template_data) 
        : template.template_data;

      if (content.lineItems && Array.isArray(content.lineItems)) {
        setLineItems(content.lineItems.map((item: unknown, index: number) => ({
          id: generateUUID(),
          item_name: item.item_name || '',
          description: item.description || '',
          quantity: item.quantity || 1,
          unit_price: item.unit_price || 0,
          discount_percentage: item.discount_percentage || 0,
          sort_order: index,
        })));
      }

      if (content.terms_conditions) {
        setFormData(prev => ({ ...prev, terms_conditions: content.terms_conditions }));
      }

      if (content.tax_rate) {
        setFormData(prev => ({ ...prev, tax_rate: content.tax_rate }));
      }

      setFormData(prev => ({ ...prev, template_id: templateId }));

      toast({
        title: 'Success',
        description: 'Template applied successfully',
      });
    } catch (error: unknown) {
      console.error('Error applying template:', error);
      toast({
        title: 'Error',
        description: 'Failed to apply template',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.title.trim()) {
      toast({
        title: 'Error',
        description: 'Quotation title is required',
        variant: 'destructive',
      });
      return;
    }

    if (!formData.client_id) {
      toast({
        title: 'Error',
        description: 'Please select a client',
        variant: 'destructive',
      });
      return;
    }

    const hasValidLineItems = lineItems.some(item => item.item_name && item.item_name.trim());
    if (!hasValidLineItems) {
      toast({
        title: 'Error',
        description: 'Please add at least one line item',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);

    try {
      const validLineItems = lineItems.filter(item => item.item_name && item.item_name.trim());
      
      if (quotation?.id) {
        // Update existing quotation
        // Exclude generated columns (tax_amount, total_amount)
        // updated_at is automatically set by database trigger
        const agencyId = await getAgencyId(profile, user?.id);
        if (!agencyId) {
          toast({
            title: 'Error',
            description: 'Agency ID not found. Please ensure you are logged in.',
            variant: 'destructive',
          });
          setLoading(false);
          return;
        }

        const { tax_amount, total_amount, ...updateData } = formData;
        
        // Format dates properly
        const issueDate = formData.issue_date ? new Date(formData.issue_date).toISOString().split('T')[0] : null;
        const expiryDate = formData.expiry_date ? new Date(formData.expiry_date).toISOString().split('T')[0] : null;
        const validUntil = formData.valid_until ? new Date(formData.valid_until).toISOString().split('T')[0] : null;

        const { error: updateError } = await db
          .from('quotations')
          .update({
            ...updateData,
            issue_date: issueDate,
            expiry_date: expiryDate,
            valid_until: validUntil,
            discount: formData.discount || 0,
          })
          .eq('id', quotation.id)
          .eq('agency_id', agencyId);

        if (updateError) throw updateError;

        // Delete existing line items
        await db
          .from('quotation_line_items')
          .delete()
          .eq('quotation_id', quotation.id);

        // Insert new line items
        if (validLineItems.length > 0) {
          const lineItemsToInsert = validLineItems.map((item, index) => {
            // Ensure all numeric values are properly converted and rounded
            const quantity = typeof item.quantity === 'string' 
              ? (item.quantity === '' ? 0 : parseFloat(item.quantity) || 0)
              : (Number(item.quantity) || 0);
            
            const unitPrice = typeof item.unit_price === 'string'
              ? (item.unit_price === '' ? 0 : parseFloat(item.unit_price) || 0)
              : (Number(item.unit_price) || 0);
            
            const discountPct = typeof item.discount_percentage === 'string'
              ? (item.discount_percentage === '' ? 0 : parseFloat(item.discount_percentage) || 0)
              : (Number(item.discount_percentage) || 0);
            
            // Round to appropriate decimal places
            const roundedQuantity = Math.round(quantity * 100) / 100;
            const roundedUnitPrice = Math.round(unitPrice * 100) / 100;
            const roundedDiscountPct = Math.round(discountPct * 100) / 100;
            
            return {
              id: generateUUID(),
              quotation_id: quotation.id,
              item_name: item.item_name.trim(),
              description: item.description?.trim() || null,
              quantity: roundedQuantity,
              unit_price: roundedUnitPrice,
              discount_percentage: roundedDiscountPct,
              sort_order: index,
            };
          });

          // Insert all line items in a single batch
          const { error: lineItemsError } = await db
            .from('quotation_line_items')
            .insert(lineItemsToInsert);

          if (lineItemsError) throw lineItemsError;
        }

        toast({
          title: 'Success',
          description: 'Quotation updated successfully',
        });
      } else {
        // Create new quotation
        // Exclude generated columns (tax_amount, total_amount)
        const { tax_amount, total_amount, ...quotationData } = formData;
        const quoteNumber = `Q-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
        // Get user ID and agency ID from auth context, or use defaults
        const agencyId = await getAgencyId(profile, user?.id);
        if (!agencyId || !user?.id) {
          toast({
            title: 'Error',
            description: 'Agency ID or User ID not found. Please ensure you are logged in.',
            variant: 'destructive',
          });
          setLoading(false);
          return;
        }
        const userId = user.id;

        // Format dates properly
        const issueDate = formData.issue_date ? new Date(formData.issue_date).toISOString().split('T')[0] : null;
        const expiryDate = formData.expiry_date ? new Date(formData.expiry_date).toISOString().split('T')[0] : null;
        const validUntil = formData.valid_until ? new Date(formData.valid_until).toISOString().split('T')[0] : null;

        const newQuotation = {
          id: generateUUID(),
          quote_number: quoteNumber,
          quotation_number: quoteNumber, // Also set quotation_number for compatibility
          ...quotationData,
          issue_date: issueDate,
          expiry_date: expiryDate,
          valid_until: validUntil,
          discount: formData.discount || 0,
          created_by: userId,
          agency_id: agencyId,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        };

        const { data: insertedQuotation, error: insertError } = await db
          .from('quotations')
          .insert([newQuotation])
          .select()
          .single();

        if (insertError) throw insertError;

        // Insert line items
        if (validLineItems.length > 0 && insertedQuotation) {
          const lineItemsToInsert = validLineItems.map((item, index) => {
            // Ensure all numeric values are properly converted and rounded
            const quantity = typeof item.quantity === 'string' 
              ? (item.quantity === '' ? 0 : parseFloat(item.quantity) || 0)
              : (Number(item.quantity) || 0);
            
            const unitPrice = typeof item.unit_price === 'string'
              ? (item.unit_price === '' ? 0 : parseFloat(item.unit_price) || 0)
              : (Number(item.unit_price) || 0);
            
            const discountPct = typeof item.discount_percentage === 'string'
              ? (item.discount_percentage === '' ? 0 : parseFloat(item.discount_percentage) || 0)
              : (Number(item.discount_percentage) || 0);
            
            // Round to appropriate decimal places
            const roundedQuantity = Math.round(quantity * 100) / 100;
            const roundedUnitPrice = Math.round(unitPrice * 100) / 100;
            const roundedDiscountPct = Math.round(discountPct * 100) / 100;
            
            return {
              id: generateUUID(),
              quotation_id: insertedQuotation.id,
              item_name: item.item_name.trim(),
              description: item.description?.trim() || null,
              quantity: roundedQuantity,
              unit_price: roundedUnitPrice,
              discount_percentage: roundedDiscountPct,
              sort_order: index,
            };
          });

          // Insert all line items in a single batch
          const { error: lineItemsError } = await db
            .from('quotation_line_items')
            .insert(lineItemsToInsert);

          if (lineItemsError) throw lineItemsError;
        }

        toast({
          title: 'Success',
          description: 'Quotation created successfully',
        });
      }

      onQuotationSaved();
      onClose();
    } catch (error: unknown) {
      console.error('Error saving quotation:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to save quotation',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-5xl max-h-[95vh] overflow-y-auto">

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Header with Save Status */}
          <div className="flex justify-between items-center pb-2 border-b">
            <div>
              <DialogTitle className="text-xl font-semibold">
                {quotation?.id ? 'Edit Quotation' : 'Create New Quotation'}
              </DialogTitle>
              <DialogDescription className="mt-1">
                {quotation?.id ? 'Update quotation details below.' : 'Fill in the details to create a new quotation. Your work is automatically saved as draft.'}
              </DialogDescription>
            </div>
            {lastSaved && (
              <div className="text-xs text-muted-foreground">
                Last saved: {lastSaved.toLocaleTimeString()}
              </div>
            )}
          </div>

          {/* Template Selection */}
          {templates.length > 0 && (
            <Card>
              <CardHeader className="pb-3">
                <CardTitle className="text-sm">Quick Start: Use Template</CardTitle>
              </CardHeader>
              <CardContent>
                <Select onValueChange={useTemplate} value={formData.template_id || undefined}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select a template to pre-fill form (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    {templates.map(template => (
                      <SelectItem key={template.id} value={template.id}>
                        {template.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </CardContent>
            </Card>
          )}

          {/* Basic Information Section */}
          <Card>
            <CardHeader>
              <CardTitle>Basic Information</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="title">Quotation Title *</Label>
                  <Input
                    id="title"
                    value={formData.title}
                    onChange={(e) => setFormData(prev => ({ ...prev, title: e.target.value }))}
                    placeholder="e.g., Website Development Project"
                    required
                  />
                  <p className="text-xs text-muted-foreground">A clear title for this quotation</p>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="client_id">Client *</Label>
                  <Select
                    value={formData.client_id}
                    onValueChange={(value) => setFormData(prev => ({ ...prev, client_id: value }))}
                    disabled={loadingClients}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select a client" />
                    </SelectTrigger>
                    <SelectContent>
                      {clients.map(client => (
                        <SelectItem key={client.id} value={client.id}>
                          {client.company_name || client.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">The client this quotation is for</p>
                </div>
              </div>

              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={formData.description}
                  onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                  placeholder="Brief description of the quotation..."
                  rows={3}
                />
                <p className="text-xs text-muted-foreground">Optional description of what this quotation covers</p>
              </div>

              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="issue_date">Issue Date *</Label>
                  <Input
                    id="issue_date"
                    type="date"
                    value={formData.issue_date}
                    onChange={(e) => setFormData(prev => ({ ...prev, issue_date: e.target.value }))}
                    required
                  />
                  <p className="text-xs text-muted-foreground">When this quotation is issued</p>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="valid_until">Valid Until</Label>
                  <Input
                    id="valid_until"
                    type="date"
                    value={formData.valid_until}
                    onChange={(e) => setFormData(prev => ({ ...prev, valid_until: e.target.value }))}
                  />
                  <p className="text-xs text-muted-foreground">Expiry date for this quotation</p>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="status">Status</Label>
                  <Select value={formData.status} onValueChange={(value) => setFormData(prev => ({ ...prev, status: value }))}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="draft">Draft</SelectItem>
                      <SelectItem value="sent">Sent</SelectItem>
                      <SelectItem value="accepted">Accepted</SelectItem>
                      <SelectItem value="rejected">Rejected</SelectItem>
                      <SelectItem value="expired">Expired</SelectItem>
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">Current status of quotation</p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Line Items */}
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <CardTitle>Line Items</CardTitle>
                <Button type="button" variant="outline" size="sm" onClick={addLineItem}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Item
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              {lineItems.map((item, index) => (
                <div key={item.id} className="grid grid-cols-12 gap-2 items-end p-3 border rounded-lg">
                  <div className="col-span-4">
                    <Label className="text-xs">Item Name *</Label>
                    <Input
                      value={item.item_name}
                      onChange={(e) => handleLineItemChange(item.id, 'item_name', e.target.value)}
                      placeholder="Item name"
                    />
                  </div>
                  <div className="col-span-3">
                    <Label className="text-xs">Description</Label>
                    <Input
                      value={item.description || ''}
                      onChange={(e) => handleLineItemChange(item.id, 'description', e.target.value)}
                      placeholder="Description"
                    />
                  </div>
                  <div className="col-span-1">
                    <Label className="text-xs">Qty</Label>
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      value={item.quantity}
                      onChange={(e) => handleLineItemChange(item.id, 'quantity', Number(e.target.value))}
                    />
                  </div>
                  <div className="col-span-1">
                    <Label className="text-xs">Unit Price</Label>
                    <Input
                      type="number"
                      min="0"
                      step="0.01"
                      value={item.unit_price}
                      onChange={(e) => handleLineItemChange(item.id, 'unit_price', Number(e.target.value))}
                    />
                  </div>
                  <div className="col-span-1">
                    <Label className="text-xs">Disc. %</Label>
                    <Input
                      type="number"
                      min="0"
                      max="100"
                      step="0.01"
                      value={item.discount_percentage || 0}
                      onChange={(e) => handleLineItemChange(item.id, 'discount_percentage', Number(e.target.value))}
                    />
                  </div>
                  <div className="col-span-1">
                    <Label className="text-xs">Total</Label>
                    <Input
                      value={calculateLineTotal(item).toFixed(2)}
                      readOnly
                      className="bg-muted"
                    />
                  </div>
                  <div className="col-span-1">
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => removeLineItem(item.id)}
                      disabled={lineItems.length === 1}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>

          {/* Pricing & Totals Section */}
          <Card>
            <CardHeader>
              <CardTitle>Pricing & Totals</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="tax_rate">Tax Rate (%)</Label>
                  <Input
                    id="tax_rate"
                    type="number"
                    min="0"
                    max="100"
                    step="0.01"
                    value={formData.tax_rate}
                    onChange={(e) => setFormData(prev => ({ ...prev, tax_rate: Number(e.target.value) }))}
                    placeholder="18"
                  />
                  <p className="text-xs text-muted-foreground">Tax percentage to apply</p>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="discount">Overall Discount (₹)</Label>
                  <Input
                    id="discount"
                    type="number"
                    min="0"
                    step="0.01"
                    value={formData.discount || 0}
                    onChange={(e) => setFormData(prev => ({ ...prev, discount: Number(e.target.value) }))}
                    placeholder="0.00"
                  />
                  <p className="text-xs text-muted-foreground">Total discount amount (applied before tax)</p>
                </div>
              </div>

              {/* Totals Summary */}
              <div className="grid grid-cols-4 gap-4 p-4 bg-muted rounded-lg">
                <div>
                  <Label className="text-sm text-muted-foreground">Subtotal</Label>
                  <p className="text-lg font-semibold">₹{(Number(formData.subtotal) || 0).toFixed(2)}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Discount</Label>
                  <p className="text-lg font-semibold text-red-600">-₹{(Number(formData.discount) || 0).toFixed(2)}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Tax ({Number(formData.tax_rate) || 0}%)</Label>
                  <p className="text-lg font-semibold">₹{(Number(formData.tax_amount) || 0).toFixed(2)}</p>
                </div>
                <div>
                  <Label className="text-sm text-muted-foreground">Total Amount</Label>
                  <p className="text-2xl font-bold">₹{(Number(formData.total_amount) || 0).toFixed(2)}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Additional Information Section */}
          <Card>
            <CardHeader>
              <CardTitle>Additional Information</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="terms_conditions">Terms & Conditions</Label>
                <Textarea
                  id="terms_conditions"
                  value={formData.terms_conditions}
                  onChange={(e) => setFormData(prev => ({ ...prev, terms_conditions: e.target.value }))}
                  placeholder="Enter payment terms, delivery conditions, etc."
                  rows={4}
                />
                <p className="text-xs text-muted-foreground">Standard terms and conditions for this quotation</p>
              </div>

              <div className="space-y-2">
                <Label htmlFor="notes">Internal Notes</Label>
                <Textarea
                  id="notes"
                  value={formData.notes}
                  onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                  placeholder="Internal notes (not visible to client)..."
                  rows={3}
                />
                <p className="text-xs text-muted-foreground">Private notes for your reference only</p>
              </div>
            </CardContent>
          </Card>

          <DialogFooter className="flex justify-between items-center">
            <div className="flex gap-2">
              <Button 
                type="button" 
                variant="outline" 
                onClick={saveDraft}
                disabled={savingDraft || !formData.title.trim() || !formData.client_id}
              >
                {savingDraft ? 'Saving Draft...' : 'Save Draft'}
              </Button>
            </div>
            <div className="flex gap-2">
              <Button type="button" variant="outline" onClick={onClose}>
                Cancel
              </Button>
              <Button type="submit" disabled={loading}>
                {loading ? 'Saving...' : quotation?.id ? 'Update Quotation' : 'Create Quotation'}
              </Button>
            </div>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

export default QuotationFormDialog;

import React, { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { insertRecord, updateRecord, selectRecords } from '@/services/api/core';
import { useAuth } from "@/hooks/useAuth";
import { Upload, X, Loader2 } from "lucide-react";
import { db } from '@/lib/database';

interface Receipt {
  id: string;
  vendor: string;
  category: string;
  amount: number;
  date: string;
  status: string;
  description: string;
  receiptUrl: string | null;
  request_id?: string;
  category_id?: string;
  business_purpose?: string;
}

interface ReceiptFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
  receipt?: Receipt | null;
}

interface ExpenseCategory {
  id: string;
  name: string;
  description: string | null;
}

export const ReceiptFormDialog: React.FC<ReceiptFormDialogProps> = ({
  open,
  onOpenChange,
  onSuccess,
  receipt,
}) => {
  const { user, profile } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<ExpenseCategory[]>([]);
  const [selectedFiles, setSelectedFiles] = useState<FileList | null>(null);
  
  const [formData, setFormData] = useState({
    category_id: "",
    amount: "",
    expense_date: "",
    description: "",
    business_purpose: "",
  });

  useEffect(() => {
    if (open) {
      fetchCategories();
      if (receipt) {
        // Load receipt data for editing
        setFormData({
          category_id: receipt.category_id || "",
          amount: receipt.amount.toString(),
          expense_date: receipt.date,
          description: receipt.description || "",
          business_purpose: receipt.business_purpose || "",
        });
      } else {
        // Reset form for new receipt
        setFormData({
          category_id: "",
          amount: "",
          expense_date: new Date().toISOString().split('T')[0],
          description: "",
          business_purpose: "",
        });
      }
      setSelectedFiles(null);
    }
  }, [open, receipt]);

  const fetchCategories = async () => {
    try {
      if (!profile?.agency_id) {
        setCategories([]);
        return;
      }

      const categoriesData = await selectRecords('expense_categories', {
        where: { 
          agency_id: profile.agency_id,
          is_active: true 
        },
        orderBy: 'name ASC',
      });
      
      setCategories((categoriesData || []).map((cat: unknown) => ({
        id: cat.id,
        name: cat.name,
        description: cat.description
      })));
    } catch (error: unknown) {
      console.error("Error fetching categories:", error);
      toast({
        title: "Error",
        description: "Failed to load expense categories",
        variant: "destructive",
      });
      setCategories([]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedFiles(e.target.files);
  };

  const uploadFiles = async (reimbursementRequestId: string) => {
    if (!selectedFiles || !user?.id) return;

    // Set userId for file storage
    (window as unknown).__currentUserId = user.id;

    const uploadPromises = Array.from(selectedFiles).map(async (file) => {
      const fileExt = file.name.split('.').pop();
      const fileName = `receipts/${user.id}/${reimbursementRequestId}/${Date.now()}.${fileExt}`;

      // Upload file to storage using the wrapper
      const { data: uploadData, error: uploadError } = await db.storage
        .from('receipts')
        .upload(fileName, file);

      if (uploadError) {
        console.error('Upload error:', uploadError);
        throw uploadError;
      }

      // Save file info to database
      await insertRecord('reimbursement_attachments', {
        reimbursement_id: reimbursementRequestId,
        file_name: file.name,
        file_path: fileName,
        file_type: file.type,
        file_size: file.size,
        uploaded_at: new Date().toISOString(),
      }, user.id);
    });

    await Promise.all(uploadPromises);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user?.id) {
      toast({
        title: "Error",
        description: "You must be logged in to create a receipt",
        variant: "destructive",
      });
      return;
    }

    if (!profile?.agency_id) {
      toast({
        title: "Error",
        description: "Unable to determine agency. Please ensure you are logged in.",
        variant: "destructive",
      });
      return;
    }

    // Validation
    if (!formData.category_id) {
      toast({
        title: "Validation Error",
        description: "Please select an expense category",
        variant: "destructive",
      });
      return;
    }

    if (!formData.amount || parseFloat(formData.amount) <= 0) {
      toast({
        title: "Validation Error",
        description: "Please enter a valid amount",
        variant: "destructive",
      });
      return;
    }

    if (!formData.expense_date) {
      toast({
        title: "Validation Error",
        description: "Please select an expense date",
        variant: "destructive",
      });
      return;
    }

    if (!formData.description.trim()) {
      toast({
        title: "Validation Error",
        description: "Please enter a description",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);
    try {
      if (receipt && receipt.request_id) {
        // Update existing receipt
        await updateRecord('reimbursement_requests', {
          category_id: formData.category_id,
          amount: parseFloat(formData.amount),
          expense_date: formData.expense_date,
          description: formData.description,
          business_purpose: formData.business_purpose || null,
        }, { id: receipt.request_id }, user.id);

        // Upload new files if any
        if (selectedFiles && selectedFiles.length > 0) {
          await uploadFiles(receipt.request_id);
        }

        toast({
          title: "Success",
          description: "Receipt updated successfully",
        });
      } else {
        // Create new receipt
        const reimbursement = await insertRecord('reimbursement_requests', {
          employee_id: user.id,
          category_id: formData.category_id,
          amount: parseFloat(formData.amount),
          currency: "INR",
          expense_date: formData.expense_date,
          description: formData.description,
          business_purpose: formData.business_purpose || null,
          status: "submitted",
          submitted_at: new Date().toISOString(),
          agency_id: profile.agency_id,
        }, user.id);

        // Upload files if any
        if (selectedFiles && selectedFiles.length > 0) {
          await uploadFiles(reimbursement.id);
        }

        toast({
          title: "Success",
          description: "Receipt created successfully",
        });
      }

      // Reset form
      setFormData({
        category_id: "",
        amount: "",
        expense_date: new Date().toISOString().split('T')[0],
        description: "",
        business_purpose: "",
      });
      setSelectedFiles(null);
      
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error("Error saving receipt:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to save receipt",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{receipt ? "Edit Receipt" : "Add New Receipt"}</DialogTitle>
          <DialogDescription>
            {receipt ? "Update receipt information" : "Create a new expense receipt"}
          </DialogDescription>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="category">Expense Category *</Label>
            <Select
              value={formData.category_id}
              onValueChange={(value) => setFormData({ ...formData, category_id: value })}
              required
            >
              <SelectTrigger className="bg-background border-input">
                <SelectValue placeholder="Select expense category" />
              </SelectTrigger>
              <SelectContent className="bg-background border-border shadow-lg z-50 max-h-60 overflow-y-auto">
                {categories.length === 0 ? (
                  <div className="p-2 text-sm text-muted-foreground">
                    {profile?.agency_id ? "Loading categories..." : "No categories available"}
                  </div>
                ) : (
                  categories.map((category) => (
                    <SelectItem key={category.id} value={category.id} className="hover:bg-muted cursor-pointer">
                      <div className="flex flex-col items-start">
                        <span className="font-medium">{category.name}</span>
                        {category.description && (
                          <span className="text-xs text-muted-foreground line-clamp-2">
                            {category.description}
                          </span>
                        )}
                      </div>
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          <div>
            <Label htmlFor="amount">Amount (₹) *</Label>
            <Input
              id="amount"
              type="number"
              step="0.01"
              min="0"
              value={formData.amount}
              onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="expense_date">Expense Date *</Label>
            <Input
              id="expense_date"
              type="date"
              value={formData.expense_date}
              onChange={(e) => setFormData({ ...formData, expense_date: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description *</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="What was this expense for?"
              required
            />
          </div>

          <div>
            <Label htmlFor="business_purpose">Business Purpose (Optional)</Label>
            <Textarea
              id="business_purpose"
              value={formData.business_purpose}
              onChange={(e) => setFormData({ ...formData, business_purpose: e.target.value })}
              placeholder="How does this relate to business activities?"
            />
          </div>

          <div>
            <Label htmlFor="receipts">Upload Receipts</Label>
            <div className="mt-2">
              <input
                id="receipts"
                type="file"
                multiple
                accept="image/*,.pdf"
                onChange={handleFileChange}
                className="hidden"
              />
              <Button
                type="button"
                variant="outline"
                onClick={() => document.getElementById('receipts')?.click()}
                className="w-full"
              >
                <Upload className="h-4 w-4 mr-2" />
                Upload Receipts
              </Button>
              {selectedFiles && selectedFiles.length > 0 && (
                <div className="mt-2 space-y-1">
                  {Array.from(selectedFiles).map((file, index) => (
                    <div key={index} className="flex items-center justify-between text-sm text-muted-foreground p-2 bg-muted rounded">
                      <span className="truncate flex-1">{file.name}</span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          const dt = new DataTransfer();
                          Array.from(selectedFiles).forEach((f, i) => {
                            if (i !== index) dt.items.add(f);
                          });
                          setSelectedFiles(dt.files.length > 0 ? dt.files : null);
                        }}
                      >
                        <X className="h-3 w-3" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)} disabled={loading}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  {receipt ? "Updating..." : "Creating..."}
                </>
              ) : (
                receipt ? "Update Receipt" : "Create Receipt"
              )}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

import React, { useState } from "react";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { db } from '@/lib/database';
import { useAuth } from "@/hooks/useAuth";
import { Upload, X } from "lucide-react";

interface ReimbursementRequest {
  id: string;
  employee_id: string;
  category_id: string;
  amount: number;
  currency: string;
  expense_date: string;
  description: string;
  business_purpose: string;
  status: string;
}

interface ReimbursementFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onSuccess?: () => void;
  request?: ReimbursementRequest | null;
}

interface ExpenseCategory {
  id: string;
  name: string;
  description: string;
}

export const ReimbursementFormDialog: React.FC<ReimbursementFormDialogProps> = ({
  open,
  onOpenChange,
  onSuccess,
  request,
}) => {
  const { user } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState<ExpenseCategory[]>([]);
  const [selectedFiles, setSelectedFiles] = useState<FileList | null>(null);
  
  const [formData, setFormData] = useState({
    category_id: "",
    amount: "",
    currency: "USD",
    expense_date: "",
    description: "",
    business_purpose: "",
  });

  const isEditMode = !!request;

  React.useEffect(() => {
    if (open) {
      fetchCategories();
      if (request) {
        // Populate form with existing data
        setFormData({
          category_id: request.category_id || "",
          amount: request.amount?.toString() || "",
          currency: request.currency || "USD",
          expense_date: request.expense_date || "",
          description: request.description || "",
          business_purpose: request.business_purpose || "",
        });
      } else {
        // Reset form for new request
        setFormData({
          category_id: "",
          amount: "",
          currency: "USD",
          expense_date: "",
          description: "",
          business_purpose: "",
        });
      }
      setSelectedFiles(null);
    }
  }, [open, request]);

  const fetchCategories = async () => {
    try {
      const { data, error } = await db
        .from("expense_categories")
        .select("id, name, description")
        .eq("is_active", true)
        .order("name", { ascending: true });

      if (error) {
        console.error("Error fetching categories:", error);
        throw error;
      }
      
      setCategories((data as unknown) || []);
    } catch (error) {
      console.error("Error fetching categories:", error);
      toast({
        title: "Error",
        description: "Failed to load expense categories",
        variant: "destructive",
      });
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedFiles(e.target.files);
  };

  const uploadFiles = async (reimbursementId: string) => {
    if (!selectedFiles || !user) return;

    const uploadPromises = Array.from(selectedFiles).map(async (file) => {
      const fileExt = file.name.split('.').pop();
      const fileName = `${user.id}/${reimbursementId}/${Date.now()}.${fileExt}`;

      const { error: uploadError } = await db.storage
        .from('receipts')
        .upload(fileName, file);

      if (uploadError) throw uploadError;

      // Save file info to database - use reimbursement_id
      const { error: dbError } = await db
        .from('reimbursement_attachments')
        .insert({
          reimbursement_id: reimbursementId,
          file_name: file.name,
          file_path: fileName,
          file_type: file.type,
          file_size: file.size,
          uploaded_at: new Date().toISOString(),
        });

      if (dbError) throw dbError;
    });

    await Promise.all(uploadPromises);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) return;

    setLoading(true);
    try {
      if (isEditMode && request) {
        // Update existing reimbursement request
        const { data: reimbursement, error: reimbursementError } = await db
          .from("reimbursement_requests")
          .update({
            category_id: formData.category_id,
            amount: parseFloat(formData.amount),
            currency: formData.currency,
            expense_date: formData.expense_date,
            description: formData.description,
            business_purpose: formData.business_purpose || null,
          })
          .eq("id", request.id)
          .select()
          .single();

        if (reimbursementError) throw reimbursementError;

        // Upload new files if any
        if (selectedFiles && selectedFiles.length > 0 && reimbursement) {
          await uploadFiles((reimbursement as unknown).id);
        }

        toast({
          title: "Success",
          description: "Reimbursement request updated successfully",
        });
      } else {
        // Create new reimbursement request
        const { data: reimbursement, error: reimbursementError } = await db
          .from("reimbursement_requests")
          .insert({
            employee_id: user.id,
            category_id: formData.category_id,
            amount: parseFloat(formData.amount),
            currency: formData.currency,
            expense_date: formData.expense_date,
            description: formData.description,
            business_purpose: formData.business_purpose || null,
            status: "submitted",
            submitted_at: new Date().toISOString(),
          })
          .select()
          .single();

        if (reimbursementError) throw reimbursementError;

        // Upload files if any
        if (selectedFiles && selectedFiles.length > 0 && reimbursement) {
          await uploadFiles((reimbursement as unknown).id);
        }

        toast({
          title: "Success",
          description: "Reimbursement request submitted successfully",
        });
      }

      // Reset form
      setFormData({
        category_id: "",
        amount: "",
        currency: "USD",
        expense_date: "",
        description: "",
        business_purpose: "",
      });
      setSelectedFiles(null);
      
      onSuccess?.();
      onOpenChange(false);
    } catch (error: unknown) {
      console.error("Error submitting reimbursement:", error);
      toast({
        title: "Error",
        description: error?.message || `Failed to ${isEditMode ? 'update' : 'submit'} reimbursement request`,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{isEditMode ? "Edit Reimbursement Request" : "New Reimbursement Request"}</DialogTitle>
        </DialogHeader>
        
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <Label htmlFor="category">Expense Category</Label>
            <Select
              value={formData.category_id}
              onValueChange={(value) => setFormData({ ...formData, category_id: value })}
              required
            >
              <SelectTrigger className="bg-background border-input">
                <SelectValue placeholder="Select expense category" />
              </SelectTrigger>
              <SelectContent className="bg-background border-border shadow-lg z-50 max-h-60 overflow-y-auto">
                {categories.length === 0 ? (
                  <div className="p-2 text-sm text-muted-foreground">
                    {loading ? "Loading categories..." : "No categories available"}
                  </div>
                ) : (
                  categories.map((category) => (
                    <SelectItem key={category.id} value={category.id} className="hover:bg-muted cursor-pointer">
                      <div className="flex flex-col items-start">
                        <span className="font-medium">{category.name}</span>
                        {category.description && (
                          <span className="text-xs text-muted-foreground line-clamp-2">
                            {category.description}
                          </span>
                        )}
                      </div>
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
            {categories.length > 0 && (
              <p className="text-xs text-muted-foreground mt-1">
                {categories.length} categories available
              </p>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <Label htmlFor="currency">Currency</Label>
              <Select
                value={formData.currency}
                onValueChange={(value) => setFormData({ ...formData, currency: value })}
                required
              >
                <SelectTrigger className="bg-background border-input">
                  <SelectValue placeholder="Select currency" />
                </SelectTrigger>
                <SelectContent className="bg-background border-border shadow-lg z-50">
                  <SelectItem value="USD">USD ($)</SelectItem>
                  <SelectItem value="EUR">EUR (€)</SelectItem>
                  <SelectItem value="GBP">GBP (£)</SelectItem>
                  <SelectItem value="INR">INR (₹)</SelectItem>
                  <SelectItem value="CAD">CAD (C$)</SelectItem>
                  <SelectItem value="AUD">AUD (A$)</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label htmlFor="amount">Amount</Label>
              <Input
                id="amount"
                type="number"
                step="0.01"
                min="0"
                value={formData.amount}
                onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                required
              />
            </div>
          </div>

          <div>
            <Label htmlFor="expense_date">Expense Date</Label>
            <Input
              id="expense_date"
              type="date"
              value={formData.expense_date}
              onChange={(e) => setFormData({ ...formData, expense_date: e.target.value })}
              required
            />
          </div>

          <div>
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="What was this expense for?"
              required
            />
          </div>

          <div>
            <Label htmlFor="business_purpose">Business Purpose (Optional)</Label>
            <Textarea
              id="business_purpose"
              value={formData.business_purpose}
              onChange={(e) => setFormData({ ...formData, business_purpose: e.target.value })}
              placeholder="How does this relate to business activities?"
            />
          </div>

          <div>
            <Label htmlFor="receipts">Upload Receipts</Label>
            <div className="mt-2">
              <input
                id="receipts"
                type="file"
                multiple
                accept="image/*,.pdf"
                onChange={handleFileChange}
                className="hidden"
              />
              <Button
                type="button"
                variant="outline"
                onClick={() => document.getElementById('receipts')?.click()}
                className="w-full"
              >
                <Upload className="h-4 w-4 mr-2" />
                Upload Receipts
              </Button>
              {selectedFiles && selectedFiles.length > 0 && (
                <div className="mt-2 space-y-1">
                  {Array.from(selectedFiles).map((file, index) => (
                    <div key={index} className="flex items-center justify-between text-sm text-muted-foreground">
                      <span>{file.name}</span>
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          const dt = new DataTransfer();
                          Array.from(selectedFiles).forEach((f, i) => {
                            if (i !== index) dt.items.add(f);
                          });
                          setSelectedFiles(dt.files.length > 0 ? dt.files : null);
                        }}
                      >
                        <X className="h-3 w-3" />
                      </Button>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? (isEditMode ? "Updating..." : "Submitting...") : (isEditMode ? "Update Request" : "Submit Request")}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
};

/**
 * Task Form Dialog
 * Comprehensive task creation and editing with all enterprise features
 */

import { useState, useEffect } from "react";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Calendar } from "@/components/ui/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Badge } from "@/components/ui/badge";
import { CalendarIcon, Plus, Edit, X, Clock, Users, Link2, FileText, CheckSquare } from "lucide-react";
import { format } from "date-fns";
import { useToast } from "@/hooks/use-toast";
import { cn } from "@/lib/utils";
import { useAuth } from '@/hooks/useAuth';
import { projectService, Task } from '@/services/api/projects';
import { selectRecords } from '@/services/api/core';
import { getEmployeesForAssignmentAuto } from '@/services/api/selectors';
import { getProjectsForSelectionAuto } from '@/services/api/projects';

interface TaskFormDialogProps {
  task?: Task;
  onTaskSaved: () => void;
  trigger?: React.ReactNode;
  projectId?: string; // Pre-select project if provided
  open?: boolean; // Controlled open state
  onOpenChange?: (open: boolean) => void; // Controlled open change handler
}

export function TaskFormDialog({ task, onTaskSaved, trigger, projectId, open: controlledOpen, onOpenChange }: TaskFormDialogProps) {
  const { user, profile } = useAuth();
  const [internalOpen, setInternalOpen] = useState(false);
  
  // Use controlled open if provided, otherwise use internal state
  const open = controlledOpen !== undefined ? controlledOpen : internalOpen;
  const setOpen = onOpenChange || setInternalOpen;
  const [loading, setLoading] = useState(false);
  const [projects, setProjects] = useState<Array<{ id: string; name: string }>>([]);
  const [employees, setEmployees] = useState<Array<{ id: string; full_name: string }>>([]);
  const [assignees, setAssignees] = useState<string[]>([]);
  const [assigneeInput, setAssigneeInput] = useState('none');
  const [tags, setTags] = useState<string[]>([]);
  const [tagInput, setTagInput] = useState('');
  const [dependencies, setDependencies] = useState<string[]>([]);
  const [checklistItems, setChecklistItems] = useState<Array<{ id: string; text: string; completed: boolean }>>([]);
  const [checklistInput, setChecklistInput] = useState('');
  const { toast } = useToast();

  const [formData, setFormData] = useState<Partial<Task>>({
    title: "",
    description: "",
    project_id: projectId || null,
    assignee_id: null,
    status: "todo",
    priority: "medium",
    due_date: null,
    start_date: null,
    estimated_hours: undefined,
    task_type: "",
  });

  // Load task data when editing
  useEffect(() => {
    if (task && open) {
      setFormData({
        title: task.title || "",
        description: task.description || "",
        project_id: task.project_id || null,
        assignee_id: task.assignee_id || null,
        status: task.status || "todo",
        priority: task.priority || "medium",
        due_date: task.due_date || null,
        start_date: task.start_date || null,
        estimated_hours: task.estimated_hours || undefined,
        task_type: task.task_type || "",
      });
      
      // Load assignees from task assignments
      if (task.assignments && task.assignments.length > 0) {
        setAssignees(task.assignments.map(a => a.user_id));
      } else if (task.assignee_id) {
        setAssignees([task.assignee_id]);
      } else {
        setAssignees([]);
      }
      
      // Load tags, dependencies, checklist
      setTags(Array.isArray(task.tags) ? task.tags : []);
      setDependencies(Array.isArray(task.dependencies) ? task.dependencies : []);
      setChecklistItems(Array.isArray(task.checklist) 
        ? task.checklist.map((item: unknown, idx: number) => ({
            id: item.id || `item-${idx}`,
            text: typeof item === 'string' ? item : item.text || '',
            completed: typeof item === 'object' ? (item.completed || false) : false
          }))
        : []);
    } else if (open && !task) {
      // Reset form for new task
      setFormData({
        title: "",
        description: "",
        project_id: projectId || null,
        assignee_id: null,
        status: "todo",
        priority: "medium",
        due_date: null,
        start_date: null,
        estimated_hours: undefined,
        task_type: "",
      });
      setAssignees([]);
      setTags([]);
      setDependencies([]);
      setChecklistItems([]);
      setAssigneeInput("none");
    }
  }, [task, open, projectId]);

  // Fetch projects and employees when dialog opens
  useEffect(() => {
    if (open) {
      fetchProjects();
      fetchEmployees();
    }
  }, [open]);

  const fetchProjects = async () => {
    try {
      // Use standardized project fetching service
      const projectsData = await getProjectsForSelectionAuto(profile, user?.id, {
        includeInactive: false
      });
      
      // Transform to component format
      setProjects(projectsData.map(p => ({ 
        id: p.id, 
        name: p.name 
      })));
    } catch (error: unknown) {
      console.error('Error fetching projects:', error);
      toast({
        title: "Error",
        description: "Failed to fetch projects",
        variant: "destructive",
      });
    }
  };

  const fetchEmployees = async () => {
    try {
      // Use standardized employee fetching service
      const employeesData = await getEmployeesForAssignmentAuto(profile, user?.id);
      
      // Transform to component format
      const transformedEmployees = employeesData.map(emp => ({
        id: emp.user_id,
        full_name: emp.full_name
      }));
      
      setEmployees(transformedEmployees);
    } catch (error: unknown) {
      console.error('Error fetching employees:', error);
      toast({
        title: "Error",
        description: "Failed to fetch employees",
        variant: "destructive",
      });
    }
  };

  const addAssignee = (userId: string) => {
    if (userId && !assignees.includes(userId)) {
      setAssignees([...assignees, userId]);
      setAssigneeInput('');
    }
  };

  const removeAssignee = (userId: string) => {
    setAssignees(assignees.filter(id => id !== userId));
  };

  const addTag = () => {
    if (tagInput.trim() && !tags.includes(tagInput.trim())) {
      setTags([...tags, tagInput.trim()]);
      setTagInput('');
    }
  };

  const removeTag = (tag: string) => {
    setTags(tags.filter(t => t !== tag));
  };

  const addDependency = (taskId: string) => {
    if (taskId && taskId !== task?.id && !dependencies.includes(taskId)) {
      setDependencies([...dependencies, taskId]);
    }
  };

  const removeDependency = (taskId: string) => {
    setDependencies(dependencies.filter(id => id !== taskId));
  };

  const addChecklistItem = () => {
    if (checklistInput.trim()) {
      setChecklistItems([...checklistItems, {
        id: `item-${Date.now()}`,
        text: checklistInput.trim(),
        completed: false
      }]);
      setChecklistInput('');
    }
  };

  const toggleChecklistItem = (itemId: string) => {
    setChecklistItems(checklistItems.map(item =>
      item.id === itemId ? { ...item, completed: !item.completed } : item
    ));
  };

  const removeChecklistItem = (itemId: string) => {
    setChecklistItems(checklistItems.filter(item => item.id !== itemId));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!formData.title?.trim()) {
      toast({
        title: "Validation Error",
        description: "Task title is required",
        variant: "destructive",
      });
      return;
    }

    setLoading(true);

    try {
      const taskData: Partial<Task> = {
        title: formData.title.trim(),
        description: formData.description?.trim() || null,
        project_id: formData.project_id || null,
        assignee_id: formData.assignee_id || null,
        status: formData.status || "todo",
        priority: formData.priority || "medium",
        due_date: formData.due_date || null,
        start_date: formData.start_date || null,
        estimated_hours: formData.estimated_hours || null,
        task_type: formData.task_type || null,
        tags: tags,
        dependencies: dependencies,
        checklist: checklistItems,
      };

      if (task?.id) {
        // Update existing task
        await projectService.updateTask(task.id, taskData, profile, user?.id);
        
        // Update assignees
        if (assignees.length > 0) {
          // Get current assignments
          const existingTask = await projectService.getTask(task.id, profile, user?.id);
          const existingAssigneeIds = existingTask?.assignments?.map((a: unknown) => a.user_id) || [];
          
          // Remove assignments that are no longer in the list
          for (const existingId of existingAssigneeIds) {
            if (!assignees.includes(existingId)) {
              await projectService.unassignTask(task.id, existingId, profile, user?.id);
            }
          }
          
          // Add new assignments (only for users not already assigned)
          for (const userId of assignees) {
            if (!existingAssigneeIds.includes(userId)) {
              await projectService.assignTask(task.id, userId, user?.id || '', profile);
            }
          }
        } else {
          // If no assignees, remove all existing assignments
          const existingTask = await projectService.getTask(task.id, profile, user?.id);
          if (existingTask?.assignments) {
            for (const assignment of existingTask.assignments) {
              await projectService.unassignTask(task.id, assignment.user_id, profile, user?.id);
            }
          }
        }
        
        toast({
          title: "Success",
          description: "Task updated successfully",
        });
      } else {
        // Create new task
        const newTask = await projectService.createTask(taskData, profile, user?.id);
        
        // Add assignees (only if not already assigned via assignee_id)
        if (assignees.length > 0 && newTask.id) {
          for (const userId of assignees) {
            // assignTask will check for duplicates, so safe to call
            await projectService.assignTask(newTask.id, userId, user?.id || '', profile);
          }
        }
        
        toast({
          title: "Success",
          description: "Task created successfully",
        });
      }

      // Reset form first
      setFormData({
        title: "",
        description: "",
        project_id: projectId || null,
        assignee_id: null,
        status: "todo",
        priority: "medium",
        due_date: null,
        start_date: null,
        estimated_hours: undefined,
        task_type: "",
      });
      setAssignees([]);
      setTags([]);
      setDependencies([]);
      setChecklistItems([]);
      
      // Close dialog and refresh
      setOpen(false);
      onTaskSaved();
    } catch (error: unknown) {
      console.error('Error saving task:', error);
      toast({
        title: "Error",
        description: error.message || "Failed to save task",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const defaultTrigger = (
    <Button>
      <Plus className="h-4 w-4 mr-2" />
      New Task
    </Button>
  );

  const editTrigger = (
    <Button variant="ghost" size="sm">
      <Edit className="h-4 w-4" />
    </Button>
  );

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      {!controlledOpen && (
        <DialogTrigger asChild>
          {trigger || (task ? editTrigger : defaultTrigger)}
        </DialogTrigger>
      )}
      <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{task ? "Edit Task" : "Create New Task"}</DialogTitle>
          <DialogDescription>
            {task ? "Update task details below." : "Fill in the details to create a new task."}
          </DialogDescription>
        </DialogHeader>
        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Basic Information */}
          <div className="space-y-4">
            <h3 className="text-sm font-semibold">Basic Information</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2 md:col-span-2">
                <Label htmlFor="title">Task Title *</Label>
                <Input
                  id="title"
                  value={formData.title}
                  onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                  placeholder="Enter task title"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="project">Project</Label>
                <Select
                  value={formData.project_id || "none"}
                  onValueChange={(value) => setFormData({ ...formData, project_id: value === "none" ? null : value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select project (optional)" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">No Project</SelectItem>
                    {projects.map((project) => (
                      <SelectItem key={project.id} value={project.id}>
                        {project.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="task_type">Task Type</Label>
                <Input
                  id="task_type"
                  value={formData.task_type || ""}
                  onChange={(e) => setFormData({ ...formData, task_type: e.target.value || null })}
                  placeholder="e.g., Bug, Feature, Research"
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="status">Status</Label>
                <Select
                  value={formData.status}
                  onValueChange={(value: unknown) => setFormData({ ...formData, status: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="todo">To Do</SelectItem>
                    <SelectItem value="in_progress">In Progress</SelectItem>
                    <SelectItem value="in_review">In Review</SelectItem>
                    <SelectItem value="blocked">Blocked</SelectItem>
                    <SelectItem value="completed">Completed</SelectItem>
                    <SelectItem value="cancelled">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="priority">Priority</Label>
                <Select
                  value={formData.priority}
                  onValueChange={(value: unknown) => setFormData({ ...formData, priority: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="critical">Critical</SelectItem>
                    <SelectItem value="urgent">Urgent</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description || ""}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Enter task description"
                rows={4}
              />
            </div>
          </div>

          {/* Dates & Time */}
          <div className="space-y-4">
            <h3 className="text-sm font-semibold">Timeline</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>Start Date</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !formData.start_date && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {formData.start_date ? (
                        format(new Date(formData.start_date), "PPP")
                      ) : (
                        <span>Pick a date</span>
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0">
                    <Calendar
                      mode="single"
                      selected={formData.start_date ? new Date(formData.start_date) : undefined}
                      onSelect={(date) => setFormData({ ...formData, start_date: date ? date.toISOString().split('T')[0] : null })}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
              </div>

              <div className="space-y-2">
                <Label>Due Date</Label>
                <Popover>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      className={cn(
                        "w-full justify-start text-left font-normal",
                        !formData.due_date && "text-muted-foreground"
                      )}
                    >
                      <CalendarIcon className="mr-2 h-4 w-4" />
                      {formData.due_date ? (
                        format(new Date(formData.due_date), "PPP")
                      ) : (
                        <span>Pick a date</span>
                      )}
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent className="w-auto p-0">
                    <Calendar
                      mode="single"
                      selected={formData.due_date ? new Date(formData.due_date) : undefined}
                      onSelect={(date) => setFormData({ ...formData, due_date: date ? date.toISOString().split('T')[0] : null })}
                      initialFocus
                    />
                  </PopoverContent>
                </Popover>
              </div>

              <div className="space-y-2">
                <Label htmlFor="estimated_hours">Estimated Hours</Label>
                <Input
                  id="estimated_hours"
                  type="number"
                  step="0.5"
                  min="0"
                  value={formData.estimated_hours || ""}
                  onChange={(e) => 
                    setFormData({ 
                      ...formData, 
                      estimated_hours: e.target.value ? parseFloat(e.target.value) : null 
                    })
                  }
                  placeholder="0"
                />
              </div>
            </div>
          </div>

          {/* Assignments */}
          <div className="space-y-4">
            <h3 className="text-sm font-semibold">Assignments</h3>
            <div className="space-y-2">
              <Label>Primary Assignee</Label>
              <Select
                value={formData.assignee_id || "none"}
                onValueChange={(value) => setFormData({ ...formData, assignee_id: value === "none" ? null : value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select primary assignee (optional)" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="none">No Assignee</SelectItem>
                  {employees.map((emp) => (
                    <SelectItem key={emp.id} value={emp.id}>
                      {emp.full_name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

              <div className="space-y-2">
                <Label>Additional Assignees</Label>
                <div className="flex gap-2">
                  <Select
                    value={assigneeInput || "none"}
                    onValueChange={(value) => {
                      if (value && value !== "none") {
                        setAssigneeInput(value);
                        addAssignee(value);
                      } else {
                        setAssigneeInput("none");
                      }
                    }}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Add assignee" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="none">Select assignee...</SelectItem>
                      {employees
                        .filter(emp => !assignees.includes(emp.id))
                        .map((emp) => (
                          <SelectItem key={emp.id} value={emp.id}>
                            {emp.full_name}
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>
              {assignees.length > 0 && (
                <div className="flex flex-wrap gap-2 mt-2">
                  {assignees.map((userId) => {
                    const emp = employees.find(e => e.id === userId);
                    return (
                      <Badge key={userId} variant="secondary" className="flex items-center gap-1">
                        <Users className="h-3 w-3" />
                        {emp?.full_name || userId}
                        <button
                          type="button"
                          onClick={() => removeAssignee(userId)}
                          className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                        >
                          <X className="h-3 w-3" />
                        </button>
                      </Badge>
                    );
                  })}
                </div>
              )}
            </div>
          </div>

          {/* Tags */}
          <div className="space-y-4">
            <h3 className="text-sm font-semibold">Tags</h3>
            <div className="flex gap-2">
              <Input
                value={tagInput}
                onChange={(e) => setTagInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    addTag();
                  }
                }}
                placeholder="Enter tag and press Enter"
              />
              <Button type="button" onClick={addTag} variant="outline">
                Add
              </Button>
            </div>
            {tags.length > 0 && (
              <div className="flex flex-wrap gap-2">
                {tags.map((tag) => (
                  <Badge key={tag} variant="outline" className="flex items-center gap-1">
                    {tag}
                    <button
                      type="button"
                      onClick={() => removeTag(tag)}
                      className="ml-1 hover:bg-destructive/20 rounded-full p-0.5"
                    >
                      <X className="h-3 w-3" />
                    </button>
                  </Badge>
                ))}
              </div>
            )}
          </div>

          {/* Checklist */}
          <div className="space-y-4">
            <h3 className="text-sm font-semibold">Checklist</h3>
            <div className="flex gap-2">
              <Input
                value={checklistInput}
                onChange={(e) => setChecklistInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    addChecklistItem();
                  }
                }}
                placeholder="Add checklist item"
              />
              <Button type="button" onClick={addChecklistItem} variant="outline">
                <CheckSquare className="h-4 w-4 mr-2" />
                Add
              </Button>
            </div>
            {checklistItems.length > 0 && (
              <div className="space-y-2">
                {checklistItems.map((item) => (
                  <div key={item.id} className="flex items-center gap-2 p-2 border rounded">
                    <input
                      type="checkbox"
                      checked={item.completed}
                      onChange={() => toggleChecklistItem(item.id)}
                      className="h-4 w-4"
                    />
                    <span className={cn("flex-1", item.completed && "line-through text-muted-foreground")}>
                      {item.text}
                    </span>
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      onClick={() => removeChecklistItem(item.id)}
                    >
                      <X className="h-4 w-4" />
                    </Button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? "Saving..." : task ? "Update Task" : "Create Task"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Input } from '@/components/ui/input';
import { useToast } from '@/hooks/use-toast';
import { Trash2, Download, Loader2, Search, Building2, Calendar, RefreshCw } from 'lucide-react';
import { DeleteAgencyDialog } from './DeleteAgencyDialog';
import {
  exportAgencyBackup,
  deleteAgency,
  fetchAgencyDetails,
  type AgencyDetails,
} from '@/services/api/agencies';
import { getApiEndpoint } from '@/config/services';
import type { AgencySummary as AgencyData } from '@/types/system';

interface AgencySettingsProps {
  agencies: AgencyData[];
  onRefresh: () => void;
}

export function AgencySettings({ agencies, onRefresh }: AgencySettingsProps) {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedAgency, setSelectedAgency] = useState<AgencyDetails | null>(null);
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [isExporting, setIsExporting] = useState<string | null>(null);
  const [isRepairing, setIsRepairing] = useState(false);
  const { toast } = useToast();

  const filteredAgencies = agencies.filter((agency) => {
    const searchLower = searchTerm.toLowerCase();
    return (
      agency.name.toLowerCase().includes(searchLower) ||
      agency.domain?.toLowerCase().includes(searchLower) ||
      agency.id.toLowerCase().includes(searchLower)
    );
  });

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  const handleExportBackup = async (agencyId: string, agencyName: string) => {
    setIsExporting(agencyId);
    try {
      await exportAgencyBackup(agencyId);
      toast({
        title: 'Backup Exported',
        description: `Backup for "${agencyName}" has been downloaded successfully.`,
      });
    } catch (error: unknown) {
      let errorMessage = error.message || 'Failed to export agency backup';
      
      // Provide more helpful error messages
      if (errorMessage.includes('NO_DATABASE') || errorMessage.includes('database not found')) {
        errorMessage = `Agency "${agencyName}" does not have a database assigned. Cannot export backup.`;
      } else if (errorMessage.includes('DATABASE_NOT_EXISTS') || errorMessage.includes('does not exist')) {
        errorMessage = `Database for agency "${agencyName}" does not exist. It may have been deleted.`;
      } else if (errorMessage.includes('Cannot connect')) {
        errorMessage = `Cannot connect to database for agency "${agencyName}". The database may be inaccessible.`;
      }
      
      toast({
        title: 'Export Failed',
        description: errorMessage,
        variant: 'destructive',
      });
    } finally {
      setIsExporting(null);
    }
  };

  const handleDeleteClick = async (agency: AgencyData) => {
    try {
      // First, fetch full agency details
      const details = await fetchAgencyDetails(agency.id);
      setSelectedAgency(details);
      setIsDeleteDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load agency details',
        variant: 'destructive',
      });
    }
  };

  const handleRepairDatabaseNames = async () => {
    setIsRepairing(true);
    try {
      const endpoint = getApiEndpoint('/system/agencies/repair-database-names');
      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
      };
      const token = window.localStorage.getItem('auth_token') || '';
      if (token) {
        headers['Authorization'] = `Bearer ${token}`;
      }

      const response = await fetch(endpoint, {
        method: 'POST',
        headers,
      });

      if (!response.ok) {
        const errorText = await response.text();
        let errorMessage = 'Failed to repair database names';
        try {
          const errorData = JSON.parse(errorText);
          errorMessage = errorData.error?.message || errorData.message || errorMessage;
        } catch {
          // If parsing fails, use default message
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      toast({
        title: 'Repair Complete',
        description: `Successfully repaired ${data.data.successful} of ${data.data.total} agencies.`,
      });
      
      // Refresh the list
      onRefresh();
    } catch (error: unknown) {
      toast({
        title: 'Repair Failed',
        description: error.message || 'Failed to repair database names',
        variant: 'destructive',
      });
    } finally {
      setIsRepairing(false);
    }
  };

  const handleDeleteConfirm = async () => {
    if (!selectedAgency) return;

    try {
      // First export backup
      await exportAgencyBackup(selectedAgency.id, selectedAgency.name);
      
      // Small delay to ensure download starts
      await new Promise((resolve) => setTimeout(resolve, 500));
      
      // Then delete
      await deleteAgency(selectedAgency.id);
      
      toast({
        title: 'Agency Deleted',
        description: `Agency "${selectedAgency.name}" has been permanently deleted.`,
      });
      
      // Refresh the list
      onRefresh();
    } catch (error: unknown) {
      throw error; // Let the dialog handle the error
    }
  };

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Agency Management</CardTitle>
              <CardDescription>
                Manage agencies and delete them permanently. Backups are automatically created before deletion.
              </CardDescription>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={handleRepairDatabaseNames}
              disabled={isRepairing}
            >
              {isRepairing ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Repairing...
                </>
              ) : (
                <>
                  <RefreshCw className="mr-2 h-4 w-4" />
                  Repair DB Names
                </>
              )}
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search agencies by name, domain, or ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>

            {/* Agencies Table */}
            {filteredAgencies.length === 0 ? (
              <div className="text-center py-8 text-muted-foreground">
                {agencies.length === 0 ? 'No agencies found' : 'No agencies match your search'}
              </div>
            ) : (
              <div className="border rounded-md">
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Agency</TableHead>
                      <TableHead>Domain</TableHead>
                      <TableHead>Plan</TableHead>
                      <TableHead>Users</TableHead>
                      <TableHead>Created</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredAgencies.map((agency) => (
                      <TableRow key={agency.id}>
                        <TableCell>
                          <div className="flex items-center gap-2">
                            <Building2 className="h-4 w-4 text-muted-foreground" />
                            <div>
                              <div className="font-medium">{agency.name}</div>
                              <div className="text-sm text-muted-foreground">
                                ID: {agency.id.slice(0, 8)}...
                              </div>
                            </div>
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="text-sm">{agency.domain || 'Not set'}</div>
                        </TableCell>
                        <TableCell>
                          <Badge variant="outline" className="capitalize">
                            {agency.subscription_plan}
                          </Badge>
                        </TableCell>
                        <TableCell>
                          <div className="text-sm">
                            {agency.user_count} / {agency.max_users || '∞'}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center gap-1 text-sm text-muted-foreground">
                            <Calendar className="h-3 w-3" />
                            {formatDate(agency.created_at)}
                          </div>
                        </TableCell>
                        <TableCell>
                          <Badge
                            variant={agency.is_active ? 'default' : 'secondary'}
                          >
                            {agency.is_active ? 'Active' : 'Inactive'}
                          </Badge>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-2">
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() =>
                                handleExportBackup(agency.id, agency.name)
                              }
                              disabled={isExporting === agency.id}
                            >
                              {isExporting === agency.id ? (
                                <Loader2 className="h-4 w-4 animate-spin" />
                              ) : (
                                <Download className="h-4 w-4" />
                              )}
                            </Button>
                            <Button
                              variant="destructive"
                              size="sm"
                              onClick={() => handleDeleteClick(agency)}
                              disabled={isExporting !== null}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Delete Confirmation Dialog */}
      <DeleteAgencyDialog
        agency={selectedAgency}
        open={isDeleteDialogOpen}
        onOpenChange={setIsDeleteDialogOpen}
        onConfirm={handleDeleteConfirm}
      />
    </>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Activity, Users, Clock, TrendingUp, Loader2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import { getApiEndpoint } from '@/config/services';

interface UsageMetrics {
  activeUsers: number;
  activeSessions: number;
  recentActions: number;
  peakHour: string;
  totalActionsToday: number;
  avgResponseTime: number;
}

interface RecentActivity {
  id: string;
  action_type: string;
  resource_type: string;
  timestamp: string;
  user_count: number;
}

function authHeaders() {
  if (typeof window === 'undefined') return {};
  const token = window.localStorage.getItem('auth_token') || '';
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
  };
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }
  return headers;
}

export const RealTimeUsageWidget = () => {
  const [metrics, setMetrics] = useState<UsageMetrics | null>(null);
  const [recentActivity, setRecentActivity] = useState<RecentActivity[]>([]);
  const [loading, setLoading] = useState(true);
  const { toast } = useToast();

  const fetchUsageMetrics = async () => {
    try {
      setLoading(true);

      const endpoint = getApiEndpoint('/system/usage/realtime');
      
      // Log API URL for debugging (only in development)
      if (typeof window !== 'undefined' && (window.location.hostname === 'localhost' || import.meta.env.DEV)) {
        console.log('[RealTime Usage] Fetching from URL:', endpoint);
      }

      const response = await fetch(endpoint, {
        method: 'GET',
        headers: {
          ...authHeaders(),
          'Accept': 'application/json',
        },
        mode: 'cors', // Explicitly enable CORS
        credentials: 'omit', // Don't send cookies (auth is header-based)
        cache: 'no-cache', // Always fetch fresh data
      });

      if (!response.ok) {
        const errorText = await response.text();
        let errorMessage = `Failed to fetch usage metrics: ${response.status}`;
        try {
          const errorData = JSON.parse(errorText);
          errorMessage = errorData.error?.message || errorData.message || errorMessage;
        } catch {
          // Use default error message
        }
        throw new Error(errorMessage);
      }

      const data = await response.json();
      
      if (data.success && data.data) {
        setMetrics(data.data.metrics);
        setRecentActivity(data.data.recentActivity || []);
      } else {
        throw new Error('Invalid response format');
      }

    } catch (error: unknown) {
      const errorMessage = error?.message || 'Failed to load real-time usage statistics';
      
      // Check for CORS errors specifically
      const isCorsError = errorMessage.includes('CORS') || 
                         errorMessage.includes('cross-origin') ||
                         errorMessage.includes('Access-Control') ||
                         (error.name === 'TypeError' && errorMessage.includes('Failed to fetch'));
      
      console.error('Error fetching usage metrics:', {
        message: errorMessage,
        error: error,
        stack: error?.stack,
        name: error?.name,
        isCorsError
      });
      
      let userMessage = errorMessage;
      if (isCorsError || errorMessage.includes('NetworkError') || errorMessage.includes('Failed to fetch')) {
        userMessage = 'Unable to connect to the server. This may be a CORS or network configuration issue.';
      }
      
      toast({
        title: "Error loading usage data",
        description: userMessage,
        variant: "destructive"
      });
      
      // Fallback to zero values on error
      setMetrics({
        activeUsers: 0,
        activeSessions: 0,
        recentActions: 0,
        peakHour: '00:00',
        totalActionsToday: 0,
        avgResponseTime: 0,
      });
      setRecentActivity([]);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsageMetrics();
    
    // Refresh every 30 seconds
    const interval = setInterval(fetchUsageMetrics, 30000);
    return () => clearInterval(interval);
  }, []);

  const formatActionType = (action: string) => {
    return action.split('_').map(word => 
      word.charAt(0).toUpperCase() + word.slice(1)
    ).join(' ');
  };

  const formatResourceType = (resource: string) => {
    return resource.split('_').map(word => 
      word.charAt(0).toUpperCase() + word.slice(1)
    ).join(' ');
  };

  if (loading && !metrics) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Activity className="h-5 w-5" />
            Real-Time Usage
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-48">
            <Loader2 className="h-8 w-8 animate-spin" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Activity className="h-5 w-5" />
          Real-Time Usage
          <Badge variant="outline" className="ml-auto">
            Live
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {metrics && (
          <>
            {/* Current Activity Metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="text-center">
                <div className="text-2xl font-bold text-green-600">{metrics.activeUsers}</div>
                <div className="text-xs text-muted-foreground flex items-center justify-center gap-1">
                  <Users className="h-3 w-3" />
                  Active Now
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-blue-600">{metrics.activeSessions}</div>
                <div className="text-xs text-muted-foreground flex items-center justify-center gap-1">
                  <Clock className="h-3 w-3" />
                  Sessions Today
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-purple-600">{metrics.recentActions}</div>
                <div className="text-xs text-muted-foreground flex items-center justify-center gap-1">
                  <TrendingUp className="h-3 w-3" />
                  Actions (5m)
                </div>
              </div>
              <div className="text-center">
                <div className="text-2xl font-bold text-orange-600">{metrics.peakHour}</div>
                <div className="text-xs text-muted-foreground">
                  Peak Hour
                </div>
              </div>
            </div>

            {/* Today's Summary */}
            <div className="border-t pt-4">
              <h4 className="font-medium mb-3">Today's Summary</h4>
              <div className="grid grid-cols-2 gap-4">
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Total Actions</span>
                  <span className="font-medium">{metrics.totalActionsToday}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm text-muted-foreground">Avg Response</span>
                  <span className="font-medium">{metrics.avgResponseTime.toFixed(0)}ms</span>
                </div>
              </div>
            </div>
          </>
        )}

        {/* Recent Activity */}
        <div className="border-t pt-4">
          <h4 className="font-medium mb-3">Recent Activity</h4>
          {recentActivity.length > 0 ? (
            <div className="space-y-2 max-h-48 overflow-y-auto">
              {recentActivity.map((activity) => (
                <div key={activity.id} className="flex items-center justify-between p-2 bg-muted/50 rounded">
                  <div className="flex-1">
                    <span className="text-sm font-medium">
                      {formatActionType(activity.action_type)}
                    </span>
                    <span className="text-sm text-muted-foreground ml-2">
                      {formatResourceType(activity.resource_type)}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge variant="secondary" className="text-xs">
                      {activity.user_count} users
                    </Badge>
                    <span className="text-xs text-muted-foreground">
                      {new Date(activity.timestamp).toLocaleTimeString()}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-4 text-muted-foreground">
              <Activity className="h-6 w-6 mx-auto mb-2 opacity-50" />
              <p className="text-sm">No recent activity</p>
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
};

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { TicketIcon, CheckCircle, TrendingUp, Plus, Edit, Trash2, Eye, MoreHorizontal, Loader2 } from 'lucide-react';
import { useToast } from '@/hooks/use-toast';
import {
  fetchTicketSummary,
  fetchTickets,
  fetchTicket,
  createTicket,
  updateTicket,
  deleteTicket,
  type TicketStats,
  type RecentTicket,
  type SupportTicket,
  type CreateTicketData,
} from '@/services/api/system';

export const SupportTicketsWidget = () => {
  const [stats, setStats] = useState<TicketStats | null>(null);
  const [recentTickets, setRecentTickets] = useState<RecentTicket[]>([]);
  const [allTickets, setAllTickets] = useState<SupportTicket[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedTicket, setSelectedTicket] = useState<SupportTicket | null>(null);
  const [isCreateDialogOpen, setIsCreateDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [isDeleting, setIsDeleting] = useState<string | null>(null);
  const { toast } = useToast();

  const [ticketForm, setTicketForm] = useState<CreateTicketData>({
    title: '',
    description: '',
    priority: 'medium',
    category: 'general',
    status: 'open',
  });

  const loadTicketStats = async () => {
    try {
      setLoading(true);
      const data = await fetchTicketSummary();
      setStats(data.stats || null);
      setRecentTickets(Array.isArray(data.recentTickets) ? data.recentTickets : []);

      // Also load all tickets for the list view
      const tickets = await fetchTickets({ limit: 100 });
      setAllTickets(Array.isArray(tickets) ? tickets : []);
    } catch (error: unknown) {
      // Set safe defaults on error to prevent crashes
      setStats(null);
      setRecentTickets([]);
      setAllTickets([]);

      toast({
        title: 'Error loading ticket data',
        description: error.message || 'Failed to load tickets',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTicketStats();
    const interval = setInterval(loadTicketStats, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleCreateTicket = async () => {
    if (!ticketForm.title || !ticketForm.description) {
      toast({
        title: 'Validation Error',
        description: 'Title and description are required',
        variant: 'destructive',
      });
      return;
    }

    try {
      await createTicket(ticketForm);
      toast({
        title: 'Success',
        description: 'Ticket created successfully',
      });
      setIsCreateDialogOpen(false);
      setTicketForm({
        title: '',
        description: '',
        priority: 'medium',
        category: 'general',
        status: 'open',
      });
      loadTicketStats();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create ticket',
        variant: 'destructive',
      });
    }
  };

  const handleViewTicket = async (ticketId: string) => {
    try {
      const ticket = await fetchTicket(ticketId);
      setSelectedTicket(ticket);
      setIsViewDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load ticket details',
        variant: 'destructive',
      });
    }
  };

  const handleEditTicket = async () => {
    if (!selectedTicket) return;

    try {
      await updateTicket(selectedTicket.id, {
        title: ticketForm.title || selectedTicket.title,
        description: ticketForm.description || selectedTicket.description,
        status: ticketForm.status || selectedTicket.status,
        priority: ticketForm.priority || selectedTicket.priority,
        category: ticketForm.category || selectedTicket.category,
      });
      toast({
        title: 'Success',
        description: 'Ticket updated successfully',
      });
      setIsEditDialogOpen(false);
      setSelectedTicket(null);
      loadTicketStats();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to update ticket',
        variant: 'destructive',
      });
    }
  };

  const handleDeleteTicket = async (ticketId: string) => {
    if (!confirm('Are you sure you want to delete this ticket? This action cannot be undone.')) {
      return;
    }

    try {
      setIsDeleting(ticketId);
      await deleteTicket(ticketId);
      toast({
        title: 'Success',
        description: 'Ticket deleted successfully',
      });
      loadTicketStats();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete ticket',
        variant: 'destructive',
      });
    } finally {
      setIsDeleting(null);
    }
  };

  const handleStatusChange = async (ticketId: string, newStatus: string) => {
    try {
      await updateTicket(ticketId, { status: newStatus as unknown });
      toast({
        title: 'Success',
        description: 'Ticket status updated',
      });
      loadTicketStats();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to update ticket status',
        variant: 'destructive',
      });
    }
  };

  const openEditDialog = (ticket: SupportTicket) => {
    setSelectedTicket(ticket);
    setTicketForm({
      title: ticket.title,
      description: ticket.description,
      priority: ticket.priority,
      category: ticket.category,
      status: ticket.status,
    });
    setIsEditDialogOpen(true);
  };

  const getPriorityColor = (priority: string) => {
    switch (priority) {
      case 'high': return 'destructive';
      case 'medium': return 'default';
      case 'low': return 'secondary';
      default: return 'outline';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'open': return 'destructive';
      case 'in_progress': return 'default';
      case 'resolved': return 'default';
      case 'closed': return 'secondary';
      default: return 'secondary';
    }
  };

  if (loading && !stats) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <TicketIcon className="h-5 w-5" />
            Support Tickets
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center h-48">
            <Loader2 className="h-8 w-8 animate-spin" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <TicketIcon className="h-5 w-5" />
              Support Tickets
            </CardTitle>
            <Dialog open={isCreateDialogOpen} onOpenChange={setIsCreateDialogOpen}>
              <DialogTrigger asChild>
                <Button size="sm" onClick={() => {
                  setTicketForm({
                    title: '',
                    description: '',
                    priority: 'medium',
                    category: 'general',
                    status: 'open',
                  });
                }}>
                  <Plus className="mr-2 h-4 w-4" />
                  New Ticket
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Create New Support Ticket</DialogTitle>
                  <DialogDescription>
                    Create a new support ticket to track customer issues and requests.
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div className="space-y-2">
                    <Label htmlFor="title">Title *</Label>
                    <Input
                      id="title"
                      value={ticketForm.title}
                      onChange={(e) => setTicketForm(prev => ({ ...prev, title: e.target.value }))}
                      placeholder="Brief description of the issue"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="description">Description *</Label>
                    <Textarea
                      id="description"
                      value={ticketForm.description}
                      onChange={(e) => setTicketForm(prev => ({ ...prev, description: e.target.value }))}
                      placeholder="Detailed description of the issue"
                      rows={5}
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="priority">Priority</Label>
                      <Select
                        value={ticketForm.priority}
                        onValueChange={(value) => setTicketForm(prev => ({ ...prev, priority: value as unknown }))}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="low">Low</SelectItem>
                          <SelectItem value="medium">Medium</SelectItem>
                          <SelectItem value="high">High</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor="category">Category</Label>
                      <Input
                        id="category"
                        value={ticketForm.category}
                        onChange={(e) => setTicketForm(prev => ({ ...prev, category: e.target.value }))}
                        placeholder="e.g., technical, billing, feature"
                      />
                    </div>
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setIsCreateDialogOpen(false)}>
                    Cancel
                  </Button>
                  <Button onClick={handleCreateTicket}>
                    Create Ticket
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="overview" className="space-y-4">
            <TabsList className="grid w-full grid-cols-3">
              <TabsTrigger value="overview">Overview</TabsTrigger>
              <TabsTrigger value="recent">Recent Tickets</TabsTrigger>
              <TabsTrigger value="all">All Tickets</TabsTrigger>
            </TabsList>

            <TabsContent value="overview" className="space-y-4">
              {stats && (
                <>
                  {/* Quick Stats */}
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                    <div className="text-center">
                      <div className="text-2xl font-bold">{stats.total}</div>
                      <div className="text-xs text-muted-foreground">Total</div>
                    </div>
                    <div className="text-center">
                      <div className="text-2xl font-bold text-red-600">{stats.open}</div>
                      <div className="text-xs text-muted-foreground">Open</div>
                    </div>
                    <div className="text-center">
                      <div className="text-2xl font-bold text-yellow-600">{stats.inProgress}</div>
                      <div className="text-xs text-muted-foreground">In Progress</div>
                    </div>
                    <div className="text-center">
                      <div className="text-2xl font-bold text-green-600">{stats.resolved}</div>
                      <div className="text-xs text-muted-foreground">Resolved</div>
                    </div>
                  </div>

                  {/* Today's Activity */}
                  <div className="border-t pt-4">
                    <h4 className="font-medium mb-3">Today's Activity</h4>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="flex items-center gap-2">
                        <TrendingUp className="h-4 w-4 text-blue-600" />
                        <span className="text-sm">New: {stats.newToday}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <CheckCircle className="h-4 w-4 text-green-600" />
                        <span className="text-sm">Resolved: {stats.resolvedToday}</span>
                      </div>
                    </div>
                    {stats.avgResolutionTime > 0 && (
                      <div className="mt-2 text-sm text-muted-foreground">
                        Avg Resolution Time: {stats.avgResolutionTime.toFixed(1)} hours
                      </div>
                    )}
                  </div>
                </>
              )}
            </TabsContent>

            <TabsContent value="recent" className="space-y-3">
              {recentTickets.length > 0 ? (
                <div className="space-y-3 max-h-64 overflow-y-auto">
                  {recentTickets.map((ticket) => (
                    <div key={ticket.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-muted/50 transition-colors">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-sm">{ticket.ticket_number}</span>
                          <Badge variant={getPriorityColor(ticket.priority)} className="text-xs">
                            {ticket.priority}
                          </Badge>
                          <Badge variant={getStatusColor(ticket.status)} className="text-xs">
                            {ticket.status.replace('_', ' ')}
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground truncate mt-1">
                          {ticket.title}
                        </p>
                        <div className="text-xs text-muted-foreground mt-1">
                          {ticket.category} • {new Date(ticket.created_at).toLocaleDateString()}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleViewTicket(ticket.id)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewTicket(ticket.id)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View Details
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => {
                              const fullTicket = allTickets.find(t => t.id === ticket.id);
                              if (fullTicket) openEditDialog(fullTicket);
                            }}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(ticket.id, 'in_progress')}>
                              Mark In Progress
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(ticket.id, 'resolved')}>
                              Mark Resolved
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              className="text-destructive"
                              onClick={() => handleDeleteTicket(ticket.id)}
                              disabled={isDeleting === ticket.id}
                            >
                              {isDeleting === ticket.id ? (
                                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              ) : (
                                <Trash2 className="mr-2 h-4 w-4" />
                              )}
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  <TicketIcon className="h-8 w-8 mx-auto mb-2 opacity-50" />
                  <p>No support tickets found</p>
                </div>
              )}
            </TabsContent>

            <TabsContent value="all" className="space-y-3">
              {allTickets.length > 0 ? (
                <div className="space-y-3 max-h-96 overflow-y-auto">
                  {allTickets.map((ticket) => (
                    <div key={ticket.id} className="flex items-center justify-between p-3 border rounded-lg hover:bg-muted/50 transition-colors">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="font-medium text-sm">{ticket.ticket_number}</span>
                          <Badge variant={getPriorityColor(ticket.priority)} className="text-xs">
                            {ticket.priority}
                          </Badge>
                          <Badge variant={getStatusColor(ticket.status)} className="text-xs">
                            {ticket.status.replace('_', ' ')}
                          </Badge>
                        </div>
                        <p className="text-sm font-medium mt-1">{ticket.title}</p>
                        <p className="text-sm text-muted-foreground truncate mt-1">
                          {ticket.description}
                        </p>
                        <div className="text-xs text-muted-foreground mt-1">
                          {ticket.category} • Created: {new Date(ticket.created_at).toLocaleString()}
                        </div>
                      </div>
                      <div className="flex items-center gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleViewTicket(ticket.id)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                              <MoreHorizontal className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewTicket(ticket.id)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View Details
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => openEditDialog(ticket)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(ticket.id, 'in_progress')}>
                              Mark In Progress
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleStatusChange(ticket.id, 'resolved')}>
                              Mark Resolved
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              className="text-destructive"
                              onClick={() => handleDeleteTicket(ticket.id)}
                              disabled={isDeleting === ticket.id}
                            >
                              {isDeleting === ticket.id ? (
                                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              ) : (
                                <Trash2 className="mr-2 h-4 w-4" />
                              )}
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  <TicketIcon className="h-8 w-8 mx-auto mb-2 opacity-50" />
                  <p>No support tickets found</p>
                </div>
              )}
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      {/* View Ticket Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Ticket Details</DialogTitle>
            <DialogDescription>
              View complete information about this support ticket
            </DialogDescription>
          </DialogHeader>
          {selectedTicket && (
            <div className="space-y-4 py-4 max-h-[70vh] overflow-y-auto">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Ticket Number</Label>
                  <p className="font-medium">{selectedTicket.ticket_number}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Status</Label>
                  <div>
                    <Badge variant={getStatusColor(selectedTicket.status)}>
                      {selectedTicket.status.replace('_', ' ')}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Priority</Label>
                  <div>
                    <Badge variant={getPriorityColor(selectedTicket.priority)}>
                      {selectedTicket.priority}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Category</Label>
                  <p className="font-medium">{selectedTicket.category}</p>
                </div>
                {selectedTicket.department && (
                  <div>
                    <Label className="text-muted-foreground">Department</Label>
                    <p className="font-medium">{selectedTicket.department}</p>
                  </div>
                )}
                {selectedTicket.page_url && (
                  <div>
                    <Label className="text-muted-foreground">Page URL</Label>
                    <p className="text-sm text-blue-600 break-all">
                      <a href={selectedTicket.page_url} target="_blank" rel="noopener noreferrer" className="hover:underline">
                        {selectedTicket.page_url}
                      </a>
                    </p>
                  </div>
                )}
              </div>
              <div>
                <Label className="text-muted-foreground">Title</Label>
                <p className="font-medium">{selectedTicket.title}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Description</Label>
                <p className="text-sm whitespace-pre-wrap bg-muted p-3 rounded-md">{selectedTicket.description}</p>
              </div>

              {/* Console Logs Section */}
              {selectedTicket.console_logs && (
                <div className="border rounded-lg p-4 bg-gray-50 dark:bg-gray-900">
                  <Label className="text-muted-foreground mb-2 block font-semibold">
                    Console Logs ({Array.isArray(selectedTicket.console_logs) ? selectedTicket.console_logs.length : 0} entries)
                  </Label>
                  <div className="max-h-48 overflow-y-auto space-y-2">
                    {Array.isArray(selectedTicket.console_logs) && selectedTicket.console_logs.map((log: unknown, idx: number) => (
                      <div key={idx} className="text-xs font-mono bg-white dark:bg-gray-800 p-2 rounded border">
                        <div className="flex items-center gap-2 mb-1">
                          <Badge variant={log.level === 'error' ? 'destructive' : log.level === 'warn' ? 'outline' : 'secondary'} className="text-xs">
                            {log.level}
                          </Badge>
                          <span className="text-muted-foreground">{new Date(log.timestamp).toLocaleString()}</span>
                        </div>
                        <pre className="whitespace-pre-wrap text-xs">{log.message}</pre>
                        {log.stack && (
                          <details className="mt-1">
                            <summary className="cursor-pointer text-xs text-muted-foreground">Stack Trace</summary>
                            <pre className="mt-1 text-xs text-red-600 dark:text-red-400 whitespace-pre-wrap">{log.stack}</pre>
                          </details>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Error Details Section */}
              {selectedTicket.error_details && (
                <div className="border rounded-lg p-4 bg-red-50 dark:bg-red-900/20">
                  <Label className="text-muted-foreground mb-2 block font-semibold">Error Details</Label>
                  <div className="space-y-2 text-sm">
                    {selectedTicket.error_details.error_count !== undefined && (
                      <div>
                        <span className="font-medium">Errors: </span>
                        <Badge variant="destructive">{selectedTicket.error_details.error_count}</Badge>
                      </div>
                    )}
                    {selectedTicket.error_details.warning_count !== undefined && (
                      <div>
                        <span className="font-medium">Warnings: </span>
                        <Badge variant="outline">{selectedTicket.error_details.warning_count}</Badge>
                      </div>
                    )}
                    {selectedTicket.error_details.recent_errors && selectedTicket.error_details.recent_errors.length > 0 && (
                      <div className="mt-2">
                        <Label className="text-xs text-muted-foreground">Recent Errors:</Label>
                        <div className="mt-1 space-y-1">
                          {selectedTicket.error_details.recent_errors.slice(0, 5).map((err: unknown, idx: number) => (
                            <div key={idx} className="text-xs bg-white dark:bg-gray-800 p-2 rounded">
                              {err.message}
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Browser Info Section */}
              {selectedTicket.browser_info && (
                <div className="border rounded-lg p-4 bg-blue-50 dark:bg-blue-900/20">
                  <Label className="text-muted-foreground mb-2 block font-semibold">Browser Information</Label>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    {selectedTicket.browser_info.userAgent && (
                      <div>
                        <span className="font-medium">User Agent: </span>
                        <span className="text-muted-foreground break-all">{selectedTicket.browser_info.userAgent}</span>
                      </div>
                    )}
                    {selectedTicket.browser_info.platform && (
                      <div>
                        <span className="font-medium">Platform: </span>
                        <span className="text-muted-foreground">{selectedTicket.browser_info.platform}</span>
                      </div>
                    )}
                    {selectedTicket.browser_info.viewport && (
                      <>
                        <div>
                          <span className="font-medium">Viewport: </span>
                          <span className="text-muted-foreground">
                            {selectedTicket.browser_info.viewport.width} × {selectedTicket.browser_info.viewport.height}
                          </span>
                        </div>
                        <div>
                          <span className="font-medium">Screen: </span>
                          <span className="text-muted-foreground">
                            {selectedTicket.browser_info.screen?.width} × {selectedTicket.browser_info.screen?.height}
                          </span>
                        </div>
                      </>
                    )}
                    {selectedTicket.browser_info.language && (
                      <div>
                        <span className="font-medium">Language: </span>
                        <span className="text-muted-foreground">{selectedTicket.browser_info.language}</span>
                      </div>
                    )}
                    {selectedTicket.browser_info.onLine !== undefined && (
                      <div>
                        <span className="font-medium">Online: </span>
                        <span className="text-muted-foreground">{selectedTicket.browser_info.onLine ? 'Yes' : 'No'}</span>
                      </div>
                    )}
                  </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4 pt-2 border-t">
                <div>
                  <Label className="text-muted-foreground">Created</Label>
                  <p className="text-sm">{new Date(selectedTicket.created_at).toLocaleString()}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Last Updated</Label>
                  <p className="text-sm">{new Date(selectedTicket.updated_at).toLocaleString()}</p>
                </div>
                {selectedTicket.resolved_at && (
                  <div>
                    <Label className="text-muted-foreground">Resolved</Label>
                    <p className="text-sm">{new Date(selectedTicket.resolved_at).toLocaleString()}</p>
                  </div>
                )}
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedTicket && (
              <Button onClick={() => {
                setIsViewDialogOpen(false);
                openEditDialog(selectedTicket);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit Ticket
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Edit Ticket Dialog */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Edit Support Ticket</DialogTitle>
            <DialogDescription>
              Update ticket information and status
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="edit-title">Title *</Label>
              <Input
                id="edit-title"
                value={ticketForm.title}
                onChange={(e) => setTicketForm(prev => ({ ...prev, title: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="edit-description">Description *</Label>
              <Textarea
                id="edit-description"
                value={ticketForm.description}
                onChange={(e) => setTicketForm(prev => ({ ...prev, description: e.target.value }))}
                rows={5}
              />
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="edit-status">Status</Label>
                <Select
                  value={ticketForm.status}
                  onValueChange={(value) => setTicketForm(prev => ({ ...prev, status: value as unknown }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="open">Open</SelectItem>
                    <SelectItem value="in_progress">In Progress</SelectItem>
                    <SelectItem value="resolved">Resolved</SelectItem>
                    <SelectItem value="closed">Closed</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="edit-priority">Priority</Label>
                <Select
                  value={ticketForm.priority}
                  onValueChange={(value) => setTicketForm(prev => ({ ...prev, priority: value as unknown }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="medium">Medium</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="edit-category">Category</Label>
                <Input
                  id="edit-category"
                  value={ticketForm.category}
                  onChange={(e) => setTicketForm(prev => ({ ...prev, category: e.target.value }))}
                />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsEditDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleEditTicket}>
              Save Changes
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
};

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Loader2, Save, RefreshCw, Settings, Search, Tag, Megaphone, Mail, Globe, Shield, Lock, Database, HardDrive, Code, FileText, Server, Archive, Key } from 'lucide-react';
import { fetchSystemSettings, updateSystemSettings, type SystemSettings } from '@/services/api/system';
import { IdentityTab, BrandingTab } from './settings-tabs';
import { useBranding } from '@/contexts/BrandingContext';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";

export function SystemSettings() {
  const [settings, setSettings] = useState<SystemSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [formData, setFormData] = useState<Partial<SystemSettings>>({});
  const [activeTab, setActiveTab] = useState('identity');
  const [isDirty, setIsDirty] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [pendingTab, setPendingTab] = useState<string | null>(null);
  const { toast } = useToast();
  const { refreshBranding } = useBranding();

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const data = await fetchSystemSettings();
      setSettings(data);
      setFormData(data);
      setIsDirty(false);
    } catch (error: unknown) {
      toast({
        title: 'Error Loading Settings',
        description: error.message || 'Failed to load system settings',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);

      // Only send changed fields to avoid "bad practice" of sending everything
      const changedData: Partial<SystemSettings> = {};
      if (settings) {
        Object.entries(formData).forEach(([key, value]) => {
          const k = key as keyof SystemSettings;
          if (JSON.stringify(value) !== JSON.stringify(settings[k])) {
            (changedData as unknown)[k] = value;
          }
        });
      }

      const payload = Object.keys(changedData).length > 0 ? changedData : formData;
      const updated = await updateSystemSettings(payload);
      setSettings(updated);
      setFormData(updated);
      setIsDirty(false);

      // Refresh branding context to update logo/title immediately
      await refreshBranding();

      toast({
        title: 'Settings Saved',
        description: 'System settings have been updated successfully.',
      });
    } catch (error: unknown) {
      toast({
        title: 'Error Saving Settings',
        description: error.message || 'Failed to save system settings',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  const handleChange = (field: keyof SystemSettings, value: unknown) => {
    setFormData((prev) => ({
      ...prev,
      [field]: value,
    }));
    setIsDirty(true);
  };

  const handleTabChange = (value: string) => {
    if (isDirty) {
      setPendingTab(value);
      setShowConfirm(true);
    } else {
      setActiveTab(value);
    }
  };

  const handleDiscardChanges = () => {
    if (settings) {
      setFormData(settings);
      setIsDirty(false);
    }
    if (pendingTab) {
      setActiveTab(pendingTab);
      setPendingTab(null);
    }
    setShowConfirm(false);
  };

  const handleConfirmSave = async () => {
    await handleSave();
    if (pendingTab) {
      setActiveTab(pendingTab);
      setPendingTab(null);
    }
    setShowConfirm(false);
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="pt-6">
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <Settings className="h-5 w-5" />
                System Settings
              </CardTitle>
              <CardDescription>
                Configure system-wide settings for branding, SEO, analytics, and more
              </CardDescription>
            </div>
            <div className="flex gap-2">
              <Button variant="outline" onClick={loadSettings} disabled={loading || saving}>
                <RefreshCw className="h-4 w-4 mr-2" />
                Refresh
              </Button>
              <Button onClick={handleSave} disabled={saving || loading}>
                {saving ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Saving...
                  </>
                ) : (
                  <>
                    <Save className="h-4 w-4 mr-2" />
                    Save Changes
                  </>
                )}
              </Button>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <Tabs value={activeTab} onValueChange={handleTabChange} className="space-y-6">
            <TabsList className="grid w-full grid-cols-4 lg:grid-cols-8 gap-1">
              <TabsTrigger value="identity">Identity</TabsTrigger>
              <TabsTrigger value="branding">Branding</TabsTrigger>
              <TabsTrigger value="seo">SEO</TabsTrigger>
              <TabsTrigger value="analytics">Analytics</TabsTrigger>
              <TabsTrigger value="email">Email</TabsTrigger>
              <TabsTrigger value="security">Security</TabsTrigger>
              <TabsTrigger value="storage">Storage</TabsTrigger>
              <TabsTrigger value="other">Other</TabsTrigger>
            </TabsList>

            <TabsContent value="identity" className="space-y-4">
              <IdentityTab formData={formData} onChange={handleChange} />
            </TabsContent>

            <TabsContent value="branding" className="space-y-6">
              <BrandingTab formData={formData} onChange={handleChange} />
            </TabsContent>

            {/* SEO Tab */}
