              </div>

              <div className="space-y-2">
                <Label htmlFor="max_file_size_mb">Max Upload Size (MB)</Label>
                <Input
                  id="max_file_size_mb"
                  type="number"
                  value={formData.max_file_size_mb ?? 10}
                  onChange={(e) => handleChange('max_file_size_mb', parseInt(e.target.value, 10) || 10)}
                  min={1}
                  max={100}
                />
