              </div>
            </TabsContent>


            {/* Other Settings Tab */}
            <TabsContent value="other" className="space-y-4">
              <div className="space-y-4">
                <h3 className="text-lg font-semibold">Contact Information</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="space-y-2">
