import React, { createContext, useContext, useEffect, useState } from 'react';
import { fetchBranding, getEffectiveFavicon, getEffectiveLogoLight, getEffectiveLogoDark, type Branding } from '@/services/api/system';

interface BrandingContextValue {
  branding: Branding | null;
  loading: boolean;
  favicon: string;
  logoLight: string;
  logoDark: string;
  systemName: string;
  systemTagline: string;
  systemDescription: string;
  // Contact
  supportEmail: string | null;
  supportPhone: string | null;
  supportAddress: string | null;
  // Social
  facebookUrl: string | null;
  twitterUrl: string | null;
  linkedinUrl: string | null;
  instagramUrl: string | null;
  youtubeUrl: string | null;
  // Legal
  termsOfServiceUrl: string | null;
  privacyPolicyUrl: string | null;
  cookiePolicyUrl: string | null;
  refreshBranding: () => Promise<void>;
}

const defaults = {
  branding: null,
  loading: true,
  favicon: '/images/landing/light.svg',
  logoLight: '/images/landing/light.svg',
  logoDark: '/images/landing/logo.svg',
  systemName: 'Oru ERP',
  systemTagline: '',
  systemDescription: '',
  supportEmail: null,
  supportPhone: null,
  supportAddress: null,
  facebookUrl: null,
  twitterUrl: null,
  linkedinUrl: null,
  instagramUrl: null,
  youtubeUrl: null,
  termsOfServiceUrl: null,
  privacyPolicyUrl: null,
  cookiePolicyUrl: null,
  refreshBranding: async () => { },
};

const BrandingContext = createContext<BrandingContextValue>(defaults);

export function BrandingProvider({ children }: { children: React.ReactNode }) {
  const [branding, setBranding] = useState<Branding | null>(null);
  const [loading, setLoading] = useState(true);

  const loadBranding = async () => {
    try {
      const b = await fetchBranding();
      setBranding(b);
      const favicon = getEffectiveFavicon(b);
      const link = document.querySelector('link[rel="icon"]') || document.querySelector('link[rel="shortcut icon"]');
      if (link) {
        link.setAttribute('href', favicon);
        if (favicon.startsWith('data:')) {
          link.setAttribute('type', favicon.match(/data:([^;]+)/)?.[1] || 'image/x-icon');
        } else if (favicon.endsWith('.svg')) {
          link.setAttribute('type', 'image/svg+xml');
        }
      } else {
        const el = document.createElement('link');
        el.rel = 'icon';
        el.href = favicon;
        if (favicon.startsWith('data:')) {
          el.type = favicon.match(/data:([^;]+)/)?.[1] || 'image/x-icon';
        } else if (favicon.endsWith('.svg')) {
          el.type = 'image/svg+xml';
        }
        document.head.appendChild(el);
      }

      // Update document title if system_name is available
      if (b?.system_name) {
        document.title = b.system_name;
      }
    } catch (err) {
      console.error('Failed to load branding', err);
    }
  };

  useEffect(() => {
    loadBranding().finally(() => setLoading(false));
  }, []);

  const value: BrandingContextValue = {
    branding,
    loading,
    favicon: getEffectiveFavicon(branding),
    logoLight: getEffectiveLogoLight(branding),
    logoDark: getEffectiveLogoDark(branding),
    systemName: branding?.system_name || 'Oru ERP',
    systemTagline: branding?.system_tagline || '',
    systemDescription: branding?.system_description || '',
    // Contact
    supportEmail: branding?.support_email || null,
    supportPhone: branding?.support_phone || null,
    supportAddress: branding?.support_address || null,
    // Social
    facebookUrl: branding?.facebook_url || null,
    twitterUrl: branding?.twitter_url || null,
    linkedinUrl: branding?.linkedin_url || null,
    instagramUrl: branding?.instagram_url || null,
    youtubeUrl: branding?.youtube_url || null,
    // Legal
    termsOfServiceUrl: branding?.terms_of_service_url || null,
    privacyPolicyUrl: branding?.privacy_policy_url || null,
    cookiePolicyUrl: branding?.cookie_policy_url || null,
    refreshBranding: loadBranding,
  };

  return (
    <BrandingContext.Provider value={value}>
      {children}
    </BrandingContext.Provider>
  );
}

export function useBranding() {
  return useContext(BrandingContext);
}

import React, { createContext, useContext, useState, ReactNode } from 'react';
import { AppRole } from '@/utils/roleUtils';

interface ViewAsUser {
  id: string;
  name: string;
  email: string;
  role: AppRole;
  avatar_url?: string;
}

interface ViewAsUserContextType {
  viewingAs: ViewAsUser | null;
  setViewingAs: (user: ViewAsUser | null) => void;
  exitViewAs: () => void;
  isViewingAs: boolean;
}

const ViewAsUserContext = createContext<ViewAsUserContextType | undefined>(undefined);

export function ViewAsUserProvider({ children }: { children: ReactNode }) {
  const [viewingAs, setViewingAsState] = useState<ViewAsUser | null>(() => {
    // Restore from localStorage on mount
    const stored = localStorage.getItem('viewing_as_user');
    if (stored) {
      try {
        return JSON.parse(stored);
      } catch {
        return null;
      }
    }
    return null;
  });

  const setViewingAs = (user: ViewAsUser | null) => {
    setViewingAsState(user);
    if (user) {
      localStorage.setItem('viewing_as_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('viewing_as_user');
    }
  };

  const exitViewAs = () => {
    setViewingAs(null);
  };

  return (
    <ViewAsUserContext.Provider
      value={{
        viewingAs,
        setViewingAs,
        exitViewAs,
        isViewingAs: !!viewingAs,
      }}
    >
      {children}
    </ViewAsUserContext.Provider>
  );
}

export function useViewAsUser() {
  const context = useContext(ViewAsUserContext);
  if (context === undefined) {
    throw new Error('useViewAsUser must be used within a ViewAsUserProvider');
  }
  return context;
}

import React, { Component, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home, Shield, Wifi, WifiOff } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { ROUTES, ERROR_TYPES, RETRY_CONFIG } from '@/constants';
import { ServiceUnavailable } from './ServiceUnavailable';

interface ErrorBoundaryState {
  hasError: boolean;
  errorType: 'network' | 'auth' | 'permission' | 'unknown';
  errorMessage?: string;
  errorDetails?: string;
  retryCount: number;
}

interface ErrorBoundaryProps {
  children: ReactNode;
  fallback?: (error: Error, errorInfo: React.ErrorInfo) => ReactNode;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  private retryTimeouts: NodeJS.Timeout[] = [];

  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      errorType: 'unknown',
      retryCount: 0
    };
  }

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    const errorMessage = error.message.toLowerCase();
    
    // Don't show error boundary for module loading errors - these are usually network/build issues
    // that should be handled by retrying or reloading, not by showing an error page
    if (errorMessage.includes('loading dynamically imported module') ||
        errorMessage.includes('disallowed mime type') ||
        errorMessage.includes('failed to fetch dynamically imported module') ||
        errorMessage.includes('error loading module')) {
      // Return null to prevent error boundary from catching these
      // The browser will handle retries automatically
      console.warn('[Error Boundary] Module loading error (will retry):', error.message);
      return {
        hasError: false, // Don't show error boundary for module loading errors
        errorType: 'unknown',
        errorMessage: error.message
      };
    }
    
    let errorType: ErrorBoundaryState['errorType'] = 'unknown';
    
    if (errorMessage.includes('network') || errorMessage.includes('fetch')) {
      errorType = 'network';
    } else if (errorMessage.includes('auth') || errorMessage.includes('unauthorized')) {
      errorType = 'auth';
    } else if (errorMessage.includes('permission') || errorMessage.includes('forbidden')) {
      errorType = 'permission';
    }

    return {
      hasError: true,
      errorType,
      errorMessage: error.message
    };
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    // Log error to console for debugging
    console.error('Error Boundary caught an error:', error, errorInfo);
    
    // Log to audit system if available
    if (typeof window !== 'undefined' && (window as any).logError) {
      (window as any).logError({
        error: error.message,
        stack: error.stack,
        componentStack: errorInfo.componentStack,
        timestamp: new Date().toISOString()
      });
    }

    this.setState({
      errorDetails: errorInfo.componentStack
    });
  }

  componentWillUnmount() {
    // Clear any pending retry timeouts
    this.retryTimeouts.forEach(timeout => clearTimeout(timeout));
  }

  handleRetry = () => {
    const { retryCount } = this.state;
    
    if (retryCount >= 3) {
      // Max retries reached, suggest page reload
      this.handleReload();
      return;
    }

    this.setState(prevState => ({
      hasError: false,
      retryCount: prevState.retryCount + 1
    }));

    // Auto-retry after delay for network errors
    if (this.state.errorType === 'network') {
      const timeout = setTimeout(() => {
        this.setState({ hasError: false });
      }, 2000);
      this.retryTimeouts.push(timeout);
    }
  };

  handleReload = () => {
    window.location.reload();
  };

  handleGoHome = () => {
    window.location.href = ROUTES.HOME;
  };

  renderErrorContent() {
    const { errorType, errorMessage, retryCount } = this.state;

    // For network errors (Docker/backend down), show the friendly early-man page
    if (errorType === 'network') {
      return (
        <ServiceUnavailable
          title="Service Temporarily Unavailable"
          description="Unable to connect to the server. The early man is working hard to reconnect everything!"
          showRetry={retryCount < 3}
          onRetry={this.handleRetry}
        />
      );
    }

    // For other errors, show the standard error UI
    const errorConfig = {
      auth: {
        icon: Shield,
        title: 'Authentication Required',
        description: 'You need to sign in to access this feature.',
        color: 'text-blue-600',
        bgColor: 'bg-blue-50',
        borderColor: 'border-blue-200'
      },
      permission: {
        icon: Shield,
        title: 'Access Denied',
        description: 'You don\'t have permission to access this resource.',
        color: 'text-red-600',
        bgColor: 'bg-red-50',
        borderColor: 'border-red-200'
      },
      unknown: {
        icon: AlertTriangle,
        title: 'Something went wrong',
        description: 'An unexpected error occurred. Please try again.',
        color: 'text-gray-600',
        bgColor: 'bg-gray-50',
        borderColor: 'border-gray-200'
      }
    };

    const config = errorConfig[errorType];
    const IconComponent = config.icon;

    return (
      <div className="min-h-screen flex items-center justify-center p-4">
        <Card className={`w-full max-w-md ${config.borderColor}`}>
          <CardHeader className={`text-center ${config.bgColor} rounded-t-lg`}>
            <div className={`mx-auto w-12 h-12 ${config.color} mb-4`}>
              <IconComponent size={48} />
            </div>
            <CardTitle className={config.color}>{config.title}</CardTitle>
            <CardDescription>{config.description}</CardDescription>
          </CardHeader>
          
          <CardContent className="pt-6">
            {errorMessage && (
              <Alert className="mb-4">
                <AlertDescription className="text-sm font-mono">
                  {errorMessage}
                </AlertDescription>
              </Alert>
            )}

            <div className="space-y-3">
              {retryCount < 3 ? (
                <Button 
                  onClick={this.handleRetry} 
                  className="w-full"
                  variant="default"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Try Again {retryCount > 0 && `(${retryCount}/3)`}
                </Button>
              ) : (
                <Button 
                  onClick={this.handleReload} 
                  className="w-full"
                  variant="default"
                >
                  <RefreshCw className="w-4 h-4 mr-2" />
                  Reload Page
                </Button>
              )}

              {errorType === 'auth' ? (
                <Button 
                  onClick={() => window.location.href = ROUTES.AUTH} 
                  className="w-full"
                  variant="outline"
                >
                  <Shield className="w-4 h-4 mr-2" />
                  Sign In
                </Button>
              ) : (
                <Button 
                  onClick={this.handleGoHome} 
                  className="w-full"
                  variant="outline"
                >
                  <Home className="w-4 h-4 mr-2" />
                  Go Home
                </Button>
              )}
            </div>

            {process.env.NODE_ENV === 'development' && this.state.errorDetails && (
              <details className="mt-4">
                <summary className="cursor-pointer text-sm text-muted-foreground">
                  Error Details (Development)
                </summary>
                <pre className="mt-2 text-xs bg-muted p-2 rounded overflow-auto max-h-32">
                  {this.state.errorDetails}
                </pre>
              </details>
            )}
          </CardContent>
        </Card>
      </div>
    );
  }

  render() {
    if (this.state.hasError) {
      return this.props.fallback ? 
        this.props.fallback(new Error(this.state.errorMessage || 'Unknown error'), { componentStack: this.state.errorDetails || '' }) :
        this.renderErrorContent();
    }

    return this.props.children;
  }
}

import { useState, useEffect, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import { logError } from '@/utils/consoleLogger';

export interface AgencyInfo {
  id: string;
  name: string;
  domain: string;
  status: string;
  subscriptionPlan: string | null;
  isActive: boolean;
  maxUsers: number | null;
  trialEndsAt: string | null;
  subscriptionEndsAt: string | null;
}

export interface AgencyMetrics {
  totalUsers: number;
  activeUsers: number;
  totalProjects: number;
  activeProjects: number;
  totalClients: number;
  totalInvoices: number;
  totalRevenue: number;
  monthlyRevenue: number;
  attendanceRecords: number;
  leaveRequests: {
    pending: number;
    approved: number;
    total: number;
  };
  recentActivity: {
    newUsers: number;
    newProjects: number;
    newInvoices: number;
  };
}

const DEFAULT_METRICS: AgencyMetrics = {
  totalUsers: 0,
  activeUsers: 0,
  totalProjects: 0,
  activeProjects: 0,
  totalClients: 0,
  totalInvoices: 0,
  totalRevenue: 0,
  monthlyRevenue: 0,
  attendanceRecords: 0,
  leaveRequests: { pending: 0, approved: 0, total: 0 },
  recentActivity: { newUsers: 0, newProjects: 0, newInvoices: 0 },
};

export const useAgencyAnalytics = () => {
  const [agency, setAgency] = useState<AgencyInfo | null>(null);
  const [metrics, setMetrics] = useState<AgencyMetrics>(DEFAULT_METRICS);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { toast } = useToast();

  const fetchAgencyMetrics = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const token = localStorage.getItem('auth_token');
      const res = await fetch('/api/agencies/me/dashboard', {
        headers: {
          'Authorization': token ? `Bearer ${token}` : '',
          'Content-Type': 'application/json',
        },
      });

      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body?.error || `HTTP ${res.status}`);
      }

      const json = await res.json();
      if (!json.success) {
        throw new Error(json.error || 'Failed to load dashboard data');
      }

      setAgency(json.data.agency ?? null);
      setMetrics(json.data.metrics ?? DEFAULT_METRICS);
    } catch (err: any) {
      logError('Error fetching agency metrics:', err);
      setError(err.message);
      toast({
        title: 'Error loading dashboard',
        description: err.message,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  }, [toast]);

  useEffect(() => {
    fetchAgencyMetrics();
  }, [fetchAgencyMetrics]);

  return {
    agency,
    metrics,
    loading,
    error,
    refreshMetrics: fetchAgencyMetrics,
  };
};

/**
 * Agency Pages Hook
 * Manages page assignments for agencies
 */

import { useState, useEffect, useCallback } from 'react';
import { getApiBaseUrl } from '@/config/api';
import { useAuth } from './useAuth';
import { useToast } from './use-toast';
import type { AgencyPageAssignment, AgencyPageRequest } from '@/types/pageCatalog';

export function useAgencyPages(agencyId?: string) {
  const { user, profile } = useAuth();
  const { toast } = useToast();
  const [pages, setPages] = useState<AgencyPageAssignment[]>([]);
  const [loading, setLoading] = useState(false);
  const [totalCost, setTotalCost] = useState(0);

  const fetchAgencyPages = useCallback(async () => {
    if (!user) return;
    if (!agencyId && !profile?.agency_id) return;

    const targetAgencyId = agencyId || profile?.agency_id;
    if (!targetAgencyId) return;

    setLoading(true);
    try {
      // Determine endpoint based on whether we're fetching for current agency or another
      const endpoint = agencyId 
        ? `/system/page-catalog/agencies/${agencyId}/pages`
        : `/system/page-catalog/agencies/me/pages`;

      const response = await fetch(`${getApiBaseUrl()}/api${endpoint}`, {
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
          'Content-Type': 'application/json'
        }
      });

      if (!response.ok) {
        throw new Error('Failed to fetch agency pages');
      }

      const data = await response.json();
      if (data.success) {
        setPages(data.data);
        if (data.summary) {
          setTotalCost(data.summary.total_cost || 0);
        } else {
          // Calculate total cost from pages
          const cost = data.data.reduce((sum: number, page: AgencyPageAssignment) => 
            sum + (page.final_cost || 0), 0);
          setTotalCost(cost);
        }
      }
    } catch (error) {
      logError('Error fetching agency pages:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch agency pages',
        variant: 'destructive'
      });
    } finally {
      setLoading(false);
    }
  }, [user, agencyId, toast]);

  useEffect(() => {
    fetchAgencyPages();
  }, [fetchAgencyPages]);

  const assignPages = useCallback(async (pageIds: string[], costOverrides?: Record<string, number>) => {
    if (!user) return;
    if (!agencyId && !profile?.agency_id) return;

    const targetAgencyId = agencyId || profile?.agency_id;
    if (!targetAgencyId) return;

    try {
      const response = await fetch(
        `${getApiBaseUrl()}/api/system/page-catalog/agencies/${targetAgencyId}/pages`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('token')}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            page_ids: pageIds,
            cost_overrides: costOverrides || {}
          })
        }
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error?.message || 'Failed to assign pages');
      }

      const data = await response.json();
      if (data.success) {
        toast({
          title: 'Success',
          description: data.message || 'Pages assigned successfully'
        });
        await fetchAgencyPages();
        return data.data;
      }
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to assign pages',
        variant: 'destructive'
      });
      throw error;
    }
  }, [user, agencyId, fetchAgencyPages, toast]);

  return {
    pages,
    loading,
    totalCost,
    fetchAgencyPages,
    assignPages
  };
}

export function useAgencyPageRequests() {
  const { user } = useAuth();
  const { toast } = useToast();
  const [requests, setRequests] = useState<AgencyPageRequest[]>([]);
  const [loading, setLoading] = useState(false);

  const getAuthToken = useCallback(() => {
    // Try both token keys for compatibility
    return localStorage.getItem('auth_token') || localStorage.getItem('token') || '';
  }, []);

  const fetchRequests = useCallback(async () => {
    if (!user) return;

    const token = getAuthToken();
    if (!token) {
      console.warn('[useAgencyPageRequests] No authentication token found');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(`${getApiBaseUrl()}/api/system/page-catalog/agencies/me/page-requests`, {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.status === 401) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || 'Authentication failed. Please log in again.');
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || `Failed to fetch page requests: ${response.statusText}`);
      }

      const data = await response.json();
      if (data.success) {
        setRequests(data.data || []);
      } else {
        throw new Error(data.error?.message || 'Failed to fetch page requests');
      }
    } catch (error) {
      logError('Error fetching page requests:', error);
      toast({
        title: 'Error',
        description: error instanceof Error ? error.message : 'Failed to fetch page requests',
        variant: 'destructive'
      });
    } finally {
      setLoading(false);
    }
  }, [user, toast, getAuthToken]);

  useEffect(() => {
    fetchRequests();
  }, [fetchRequests]);

  const requestPage = useCallback(async (pageId: string, reason?: string) => {
    if (!user) return;

    const token = getAuthToken();
    if (!token) {
      toast({
        title: 'Error',
        description: 'Authentication token not found',
        variant: 'destructive'
      });
      throw new Error('Authentication token not found');
    }

    try {
      const response = await fetch(`${getApiBaseUrl()}/api/system/page-catalog/agencies/me/page-requests`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          page_id: pageId,
          reason: reason || ''
        })
      });

      if (response.status === 401) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || 'Authentication failed. Please log in again.');
      }

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error?.message || 'Failed to request page');
      }

      const data = await response.json();
      if (data.success) {
        toast({
          title: 'Success',
          description: data.message || 'Page request submitted successfully'
        });
        await fetchRequests();
        return data.data;
      } else {
        throw new Error(data.error?.message || 'Failed to request page');
      }
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to request page',
        variant: 'destructive'
      });
      throw error;
    }
  }, [user, fetchRequests, toast, getAuthToken]);

  return {
    requests,
    loading,
    fetchRequests,
    requestPage
  };
}

import { useState, useEffect } from 'react';
import { selectOne, updateRecord, insertRecord } from '@/services/api/core';
import { fetchAgencySettings, updateAgencySettingsApi } from '@/services/api/agencies';
import { useAuth } from '@/hooks/useAuth';
import { getAgencyId } from '@/utils/agencyUtils';
import { getApiBaseUrl } from '@/config/api';

export interface AgencySettings {
  id?: string;
  agency_id?: string;
  agency_name: string;
  logo_url: string | null;
  domain: string | null;
  default_currency: string;
  currency?: string; // Legacy field for backward compatibility
  primary_color: string;
  secondary_color: string;
  timezone: string;
  date_format: string;
  fiscal_year_start: string;
  working_hours_start: string;
  working_hours_end: string;
  working_days: string[] | string; // Can be array or JSON string
  created_at?: string;
  updated_at?: string;
}

const DEFAULT_SETTINGS: Omit<AgencySettings, 'id' | 'agency_id' | 'created_at' | 'updated_at'> = {
  agency_name: '',
  logo_url: null,
  domain: null,
  default_currency: 'IN',
  primary_color: '#0a6ed1',
  secondary_color: '#0854a0',
  timezone: 'Asia/Kolkata',
  date_format: 'DD/MM/YYYY',
  fiscal_year_start: '04-01',
  working_hours_start: '09:00',
  working_hours_end: '18:00',
  working_days: ['monday', 'tuesday', 'wednesday', 'thursday', 'friday'],
};

export const useAgencySettings = () => {
  const { profile, user, userRole } = useAuth();
  const [settings, setSettings] = useState<AgencySettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchSettings = async () => {
    // Skip for super admins - they don't use agency settings
    if (userRole === 'super_admin') {
      setLoading(false);
      setSettings(null);
      return;
    }

    const storedAgencyId = typeof window !== 'undefined' ? localStorage.getItem('agency_id') : null;

    try {
      setLoading(true);
      setError(null);

      // Fetch agency settings via the proper API endpoint
      let agencySettings: AgencySettings | null = null;
      if (storedAgencyId) {
        try {
          const { settings } = await fetchAgencySettings(storedAgencyId);
          if (settings && Object.keys(settings).length > 0) {
            agencySettings = settings as AgencySettings;
          }
        } catch (apiErr) {
          console.warn('[useAgencySettings] Agencies API failed:', apiErr);
          // Don't fall back to raw SQL — it's blocked for non-admins
        }
      }

      // Also fetch from main database if agency_name is missing or default
      let mainDbSettings = null;
      const agencyId = storedAgencyId || await getAgencyId(profile, user?.id);
      const isValidAgencyId = agencyId && agencyId !== '00000000-0000-0000-0000-000000000000';
      if (isValidAgencyId && (!agencySettings?.agency_name || agencySettings.agency_name === 'My Agency' || agencySettings.agency_name === '')) {
        try {
          const apiBaseUrl = getApiBaseUrl();
          const response = await fetch(`${apiBaseUrl}/api/system/agency-settings/${encodeURIComponent(agencyId)}`, {
            method: 'GET',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${localStorage.getItem('auth_token') || ''}`,
            },
          });
          
          if (response.ok) {
            const data = await response.json();
            mainDbSettings = data?.data?.settings || data.settings;
            console.log('[useAgencySettings] Fetched main DB settings for agency_name:', mainDbSettings?.agency_name);
          }
        } catch (error) {
          console.warn('[useAgencySettings] Failed to fetch from main DB:', error);
        }
      }

      // Merge settings: prefer agency DB, but use main DB for agency_name if agency DB has default/empty
      const mergedSettings = agencySettings ? {
        ...agencySettings,
        // Use main DB agency_name if agency DB has default/empty value
        agency_name: (agencySettings.agency_name && agencySettings.agency_name !== 'My Agency' && agencySettings.agency_name !== '')
          ? agencySettings.agency_name
          : (mainDbSettings?.agency_name || agencySettings.agency_name),
      } : (mainDbSettings ? {
        ...mainDbSettings,
        // Map main DB fields to agency settings structure
        default_currency: mainDbSettings.default_currency || mainDbSettings.currency || DEFAULT_SETTINGS.default_currency,
      } : null);

      if (mergedSettings) {
        // Parse working_days if it's a string or handle JSONB
        let workingDays = mergedSettings.working_days;
        if (typeof workingDays === 'string') {
          try {
            // Try to parse as JSON
            const parsed = JSON.parse(workingDays);
            workingDays = Array.isArray(parsed) ? parsed : DEFAULT_SETTINGS.working_days;
          } catch {
            // If parsing fails, check if it's a comma-separated string
            if (workingDays.includes(',')) {
              workingDays = workingDays.split(',').map(d => d.trim());
            } else {
              // Use default if parsing fails
              workingDays = DEFAULT_SETTINGS.working_days;
            }
          }
        } else if (!Array.isArray(workingDays)) {
          // If it's not an array, use default
          workingDays = DEFAULT_SETTINGS.working_days;
        }

        const parsedSettings: AgencySettings = {
          ...mergedSettings,
          working_days: workingDays as string[],
          default_currency: mergedSettings.default_currency || mergedSettings.currency || DEFAULT_SETTINGS.default_currency,
          primary_color: mergedSettings.primary_color || DEFAULT_SETTINGS.primary_color,
          secondary_color: mergedSettings.secondary_color || DEFAULT_SETTINGS.secondary_color,
          timezone: mergedSettings.timezone || DEFAULT_SETTINGS.timezone,
          date_format: mergedSettings.date_format || DEFAULT_SETTINGS.date_format,
          fiscal_year_start: mergedSettings.fiscal_year_start || DEFAULT_SETTINGS.fiscal_year_start,
          working_hours_start: mergedSettings.working_hours_start || DEFAULT_SETTINGS.working_hours_start,
          working_hours_end: mergedSettings.working_hours_end || DEFAULT_SETTINGS.working_hours_end,
          // Ensure agency_name is set from merged settings
          agency_name: mergedSettings.agency_name || DEFAULT_SETTINGS.agency_name,
        };

        setSettings(parsedSettings);
        
        // Apply theme colors to CSS variables
        if (parsedSettings.primary_color) {
          document.documentElement.style.setProperty('--primary-color', parsedSettings.primary_color);
          // Convert hex to HSL for CSS variables if needed
          const hsl = hexToHsl(parsedSettings.primary_color);
          if (hsl) {
            document.documentElement.style.setProperty('--primary', `${hsl.h} ${hsl.s}% ${hsl.l}%`);
          }
        }
        if (parsedSettings.secondary_color) {
          document.documentElement.style.setProperty('--secondary-color', parsedSettings.secondary_color);
          const hsl = hexToHsl(parsedSettings.secondary_color);
          if (hsl) {
            document.documentElement.style.setProperty('--primary-dark', `${hsl.h} ${hsl.s}% ${hsl.l}%`);
          }
        }
      } else {
        // No settings found, use defaults
        // Note: agency_id is not included - agency_settings table doesn't have this column
        setSettings({
          ...DEFAULT_SETTINGS,
        } as AgencySettings);
      }
    } catch (err: unknown) {
      console.error('Error fetching agency settings:', err);
      setError(err.message || 'Failed to fetch agency settings');
      // Use defaults on error
      // Note: agency_id is not included - agency_settings table doesn't have this column
      setSettings({
        ...DEFAULT_SETTINGS,
      } as AgencySettings);
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async (newSettings: Partial<AgencySettings>) => {
    const agencyDatabase = typeof window !== 'undefined' ? localStorage.getItem('agency_database') : null;
    try {
      setError(null);
      
      // Remove agency_id from newSettings if present - agency_settings table doesn't have this column
      // Each agency has its own database, so agency is identified by database name, not a column
      const { agency_id: _, ...settingsWithoutAgencyId } = newSettings;
      
      // Only include fields that are actually provided (not undefined)
      const settingsToSave: unknown = {};
      
      // Copy only defined fields, but exclude large logo_url unless it's actually new
      Object.keys(settingsWithoutAgencyId).forEach(key => {
        const value = (settingsWithoutAgencyId as unknown)[key];
        
        // Special handling for logo_url: only include if it's a new/changed value
        // Don't send existing large base64 strings that haven't changed
        if (key === 'logo_url') {
          // Only include logo_url if:
          // 1. It's explicitly provided (not undefined/null)
          // 2. It's different from the existing value
          // 3. It's not an extremely large base64 string (> 1MB uncompressed)
          if (value !== undefined && value !== null && value !== '') {
            const existingLogo = settings?.logo_url;
            // If it's different from existing, include it
            if (value !== existingLogo) {
              // Check if it's a reasonable size (base64 is ~33% larger than binary)
              // If it's a data URL and larger than 1.5MB, it might cause issues
              if (typeof value === 'string' && value.startsWith('data:')) {
                const base64Length = value.length;
                // Approximate: base64 is ~4/3 the size of binary, so 1.5MB binary = ~2MB base64
                if (base64Length > 2 * 1024 * 1024) {
                  console.warn('Logo URL is very large, but including it anyway. Consider compressing the image.');
                }
              }
              settingsToSave[key] = value;
            }
            // If it's the same as existing, don't include it (saves bandwidth)
          } else if (value === '') {
            // Explicitly setting to empty string means remove logo
            settingsToSave[key] = '';
          }
        } else if (value !== undefined && value !== null) {
          settingsToSave[key] = value;
        }
      });

      // working_days: agencies API expects array (lowercase); core API expects JSON string
      if (settingsWithoutAgencyId.working_days !== undefined) {
        const wd = settingsWithoutAgencyId.working_days;
        const arr = Array.isArray(wd) ? wd : (typeof wd === 'string' ? (() => { try { return JSON.parse(wd); } catch { return DEFAULT_SETTINGS.working_days; } })() : DEFAULT_SETTINGS.working_days);
        settingsToSave.working_days = agencyDatabase ? arr : JSON.stringify(arr);
      }

      // Also save as currency for backward compatibility if default_currency is provided
      if (settingsWithoutAgencyId.default_currency) {
        settingsToSave.currency = settingsWithoutAgencyId.default_currency;
      } else if (settingsWithoutAgencyId.currency) {
        settingsToSave.currency = settingsWithoutAgencyId.currency;
      }

      // Final safety check: explicitly remove agency_id if it somehow got into settingsToSave
      // agency_settings table doesn't have this column - each agency has its own database
      delete settingsToSave.agency_id;
      
      if (agencyDatabase) {
        // Use agencies API (normalized tables)
        await updateAgencySettingsApi(agencyDatabase, settingsToSave);
        setSettings((prev) => (prev ? { ...prev, ...settingsToSave } : null));
      } else if (settings?.id) {
        // Fallback: update via core API
        const updated = await updateRecord<AgencySettings>(
          'agency_settings',
          settingsToSave,
          { id: settings.id }
        );
        setSettings(updated);
      } else {
        // Insert new settings
        const inserted = await insertRecord<AgencySettings>('agency_settings', settingsToSave);
        setSettings(inserted);
      }

      // Apply theme colors immediately
      if (newSettings.primary_color) {
        document.documentElement.style.setProperty('--primary-color', newSettings.primary_color);
        const hsl = hexToHsl(newSettings.primary_color);
        if (hsl) {
          document.documentElement.style.setProperty('--primary', `${hsl.h} ${hsl.s}% ${hsl.l}%`);
        }
      }
      if (newSettings.secondary_color) {
        document.documentElement.style.setProperty('--secondary-color', newSettings.secondary_color);
        const hsl = hexToHsl(newSettings.secondary_color);
        if (hsl) {
          document.documentElement.style.setProperty('--primary-dark', `${hsl.h} ${hsl.s}% ${hsl.l}%`);
        }
      }

      return { success: true };
    } catch (err: unknown) {
      console.error('Error saving agency settings:', err);
      setError(err.message || 'Failed to save agency settings');
      return { success: false, error: err.message };
    }
  };

  useEffect(() => {
    // Don't fetch for super admins - they don't use agency settings
    if (userRole === 'super_admin') {
      setLoading(false);
      setSettings(null);
      return;
    }
    // Only fetch if we have a profile or user (not super admin)
    if (profile || user) {
      fetchSettings();
    }
  }, [profile?.agency_id, userRole, profile, user]);

  return {
    settings,
    loading,
    error,
    fetchSettings,
    saveSettings,
  };
};

// Helper function to convert hex to HSL
function hexToHsl(hex: string): { h: number; s: number; l: number } | null {
  // Remove # if present
  hex = hex.replace('#', '');
  
  // Parse RGB
  const r = parseInt(hex.substring(0, 2), 16) / 255;
  const g = parseInt(hex.substring(2, 4), 16) / 255;
  const b = parseInt(hex.substring(4, 6), 16) / 255;

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  let h = 0, s = 0;
  const l = (max + min) / 2;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    
    switch (max) {
      case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break;
      case g: h = ((b - r) / d + 2) / 6; break;
      case b: h = ((r - g) / d + 4) / 6; break;
    }
  }

  return {
    h: Math.round(h * 360),
    s: Math.round(s * 100),
    l: Math.round(l * 100),
  };
}

import { createContext, useContext, useEffect, useState, ReactNode } from 'react';
import { toast } from '@/hooks/use-toast';
import { AppRole } from '@/utils/roleUtils';
import { selectRecords, selectOne } from '@/services/api/core';
import { loginUser, registerUser, loginSauth } from '@/services/api/auth';
import { logWarn, logError } from '@/utils/consoleLogger';

interface User {
  id: string;
  email: string;
  email_confirmed: boolean;
  is_active: boolean;
}

interface Session {
  access_token: string;
  token_type: string;
  expires_in: number;
  expires_at: number;
  refresh_token: string;
  user: User;
}

interface Profile {
  id: string;
  user_id: string;
  full_name: string | null;
  phone: string | null;
  department: string | null;
  position: string | null;
  hire_date: string | null;
  avatar_url: string | null;
  is_active: boolean;
  agency_id: string;
}

interface UserRole {
  role: AppRole;
}

interface AuthContextType {
  user: User | null;
  session: Session | null;
  profile: Profile | null;
  userRole: AppRole | null;
  loading: boolean;
  isSystemSuperAdmin: boolean; // Flag to identify system-level super admin
  signUp: (email: string, password: string, fullName: string) => Promise<{ error: any }>;
  signIn: (email: string, password: string) => Promise<{ error: any }>;
  signInSauth: (email: string, password: string) => Promise<{ error: any }>;
  signOut: () => Promise<void>;
  refreshProfile: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [userRole, setUserRole] = useState<AppRole | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSystemSuperAdmin, setIsSystemSuperAdmin] = useState(false);

  // Helper to validate token format
  const isValidTokenFormat = (token: string): boolean => {
    if (!token || typeof token !== 'string' || token.length < 10) {
      return false;
    }
    // Base64 should only contain A-Z, a-z, 0-9, +, /, and = for padding
    const base64Regex = /^[A-Za-z0-9+/]*={0,2}$/;
    // Check if it's base64 (our format) or JWT (legacy format with dots)
    return base64Regex.test(token) || (token.includes('.') && token.split('.').length === 3);
  };

  useEffect(() => {
    // Check for existing session on mount
    const token = localStorage.getItem('auth_token');
    if (token) {
      // Validate token format first
      if (!isValidTokenFormat(token)) {
        logWarn('[Auth] Invalid token format detected, clearing corrupted token');
        localStorage.removeItem('auth_token');
        localStorage.removeItem('agency_database');
        localStorage.removeItem('agency_id');
        setLoading(false);
        return;
      }

      try {
        // Verify token is still valid
        // Token can be either:
        // 1. Simple base64-encoded JSON (our format): btoa(JSON.stringify({...}))
        // 2. JWT format (legacy): header.payload.signature
        let decoded: { id?: string; userId?: string; email?: string; exp?: number };

        if (token.includes('.')) {
          // JWT format - decode the payload part
          const parts = token.split('.');
          if (parts.length !== 3) {
            throw new Error('Invalid JWT format');
          }
          decoded = JSON.parse(atob(parts[1]));
        } else {
          // Simple base64 format - decode directly
          decoded = JSON.parse(atob(token));
        }

        if (decoded.exp && decoded.exp * 1000 > Date.now()) {
          // Token is still valid – restore minimal user from token,
          // then hydrate full user/profile/roles from the database where possible
          const restoredUser: User = {
            id: decoded.id || decoded.userId || '',
            email: decoded.email || '',
            email_confirmed: true,
            is_active: true
          };
          setUser(restoredUser);

          // Prefer stored role from previous real login if available
          const storedRole = localStorage.getItem('user_role') as AppRole | null;
          if (storedRole) {
            setUserRole(storedRole);
            // Check if stored role is super_admin and user has no agency context
            if (storedRole === 'super_admin' && !localStorage.getItem('agency_database')) {
              setIsSystemSuperAdmin(true);
            }
          } else if (decoded.id || decoded.userId) {
            // Fallback to client-side DB lookup for legacy/mock flows
            const actualId = decoded.id || decoded.userId || '';
            fetchUserProfile(actualId);
            fetchUserRole(actualId);
          }
        } else {
          // Token expired
          localStorage.removeItem('auth_token');
        }
      } catch (error) {
        logWarn('[Auth] Failed to decode token, clearing corrupted token:', error);
        // Clear all auth-related localStorage items
        localStorage.removeItem('auth_token');
        localStorage.removeItem('agency_database');
        localStorage.removeItem('agency_id');
        localStorage.removeItem('user_role');
      }
    }
    setLoading(false);
  }, []);

  const fetchUserProfile = async (userId: string) => {
    try {
      // Don't fetch profile if user is super admin (they use main DB, not agency DB)
      const currentRole = localStorage.getItem('user_role');
      if (currentRole === 'super_admin') {
        return;
      }

      const data = await selectOne('profiles', { user_id: userId });
      if (data) {
        setProfile(data as Profile);
      }
    } catch (error) {
      logError('Error fetching profile:', error);
    }
  };

  const fetchUserRole = async (userId: string) => {
    try {
      // Query the database for roles
      const data = await selectRecords('user_roles', {
        where: { user_id: userId }
      });

      if (!data || data.length === 0) {
        setUserRole('employee');
        return;
      }

      // Define role hierarchy (lower number = higher priority)
      const roleHierarchy: Record<AppRole, number> = {
        'super_admin': 1,
        'agency_admin': 2,
        'manager': 3,
        'employee': 4,
        'auditor': 5,
        'viewer': 6,
        'custom': 7,
      };

      // Find the highest priority role
      const userRoles = (data as any[]).map(r => r.role as AppRole);
      const highestRole = userRoles.reduce((highest, current) => {
        const currentPriority = roleHierarchy[current] || 99;
        const highestPriority = roleHierarchy[highest] || 99;
        return currentPriority < highestPriority ? current : highest;
      });

      setUserRole(highestRole);
    } catch (error) {
      logError('Error fetching user role:', error);
    }
  };

  const refreshProfile = async () => {
    if (!user) return;
    await fetchUserProfile(user.id);
  };

  const signUp = async (email: string, password: string, fullName: string) => {
    try {
      // Get agency_id from current user's profile or localStorage
      let agencyId: string | null = null;
      if (profile?.agency_id) {
        agencyId = profile.agency_id;
      } else if (typeof window !== 'undefined') {
        agencyId = localStorage.getItem('agency_id') || null;
      }

      if (!agencyId) {
        throw new Error('Agency ID not found. Please ensure you are logged in to an agency account or provide an agency ID.');
      }

      const result = await registerUser({
        email,
        password,
        fullName,
        agencyId
      });

      // Store token
      localStorage.setItem('auth_token', result.token);

      // Set user state
      setUser(result.user as any);

      toast({
        title: "Sign up successful",
        description: "Welcome to Oru!"
      });

      return { error: null };
    } catch (error: any) {
      toast({
        title: "Sign up failed",
        description: error.message,
        variant: "destructive"
      });
      return { error };
    }
  };

  const signIn = async (email: string, password: string, domain?: string) => {
    // Real database login (domain-first for agency users; omit domain for super admin)
    try {
      const result = await loginUser({ email, password, domain });

      // Store token
      localStorage.setItem('auth_token', result.token);

      // Set user state from server response
      setUser(result.user as any);

      // Check if user is super admin - super admins don't need agency profiles
      const serverRoles = ((result.user as any).roles || []) as Array<{ role: AppRole } | AppRole>;
      const hasSuperAdminRole = serverRoles.some((r: any) => {
        const role = typeof r === 'string' ? r : r.role;
        return role === 'super_admin';
      });

      // Check if this is a system-level super admin (no agency database)
      // IMPORTANT: Only system-level super admins (with super_admin role AND no agency database)
      // should be treated as super_admin. Agency admins should NOT be treated as super_admin.
      const userAgency = (result.user as any).agency;
      const hasAgencyDatabase = !!(userAgency && userAgency.databaseName);
      const isSystemLevelSuperAdmin = hasSuperAdminRole && !hasAgencyDatabase;
      setIsSystemSuperAdmin(isSystemLevelSuperAdmin);

      // Clear agency context ONLY for system-level super admin
      // Agency admins should keep their agency context
      if (isSystemLevelSuperAdmin) {
        localStorage.removeItem('agency_database');
        localStorage.removeItem('agency_id');
      } else if (userAgency) {
        // Ensure agency context is set for agency users (including agency admins)
        if (userAgency.databaseName) {
          localStorage.setItem('agency_database', userAgency.databaseName);
        }
        if (userAgency.id) {
          localStorage.setItem('agency_id', userAgency.id);
        }
      }

      // If profile came back from server, use it directly
      const serverProfile = (result.user as any).profile;
      if (serverProfile) {
        setProfile(serverProfile as any);
      } else if (!isSystemLevelSuperAdmin) {
        // Only fetch profile for non-system-super-admin users (system super admins use main DB, not agency DB)
        fetchUserProfile(result.user.id);
      } else {
        // System-level super admin - set profile to null or minimal profile
        setProfile(null);
      }

      // Prefer roles returned by the server
      if (serverRoles.length > 0) {
        // Same hierarchy rules as fetchUserRole
        const roleHierarchy: Record<AppRole, number> = {
          'super_admin': 1,
          'agency_admin': 2,
          'manager': 3,
          'employee': 4,
          'auditor': 5,
          'viewer': 6,
          'custom': 7,
        };

        const roleArray = serverRoles.map(r => typeof r === 'string' ? r : r.role);
        const highestRole = roleArray.reduce((highest, current) => {
          const currentPriority = roleHierarchy[current] || 99;
          const highestPriority = roleHierarchy[highest] || 99;
          return currentPriority < highestPriority ? current : highest;
        });

        setUserRole(highestRole);
        // Persist role for future reloads so we don't have to guess
        localStorage.setItem('user_role', highestRole);
      } else {
        // Fallback: derive role from database if server didn't include it
        fetchUserRole(result.user.id);
      }

      toast({
        title: "Login successful",
        description: "Welcome back!"
      });

      return { error: null };
    } catch (error: any) {
      toast({
        title: "Login failed",
        description: error.message,
        variant: "destructive"
      });
      return { error };
    }
  };

  const signInSauth = async (email: string, password: string) => {
    try {
      const result = await loginSauth({ email, password });
      localStorage.setItem('auth_token', result.token);
      setUser(result.user as any);
      setIsSystemSuperAdmin(true);
      localStorage.removeItem('agency_database');
      localStorage.removeItem('agency_id');
      setProfile(null);
      setUserRole('super_admin');
      localStorage.setItem('user_role', 'super_admin');
      return { error: null };
    } catch (error: any) {
      return { error };
    }
  };

  const signOut = async () => {
    try {
      localStorage.removeItem('auth_token');
      localStorage.removeItem('user_role');
      localStorage.removeItem('agency_id');
      localStorage.removeItem('agency_database');
      setUser(null);
      setSession(null);
      setProfile(null);
      setUserRole(null);
      setIsSystemSuperAdmin(false);

      toast({
        title: "Logged out",
        description: "You have been logged out successfully"
      });
    } catch (error: any) {
      toast({
        title: "Logout failed",
        description: error.message,
        variant: "destructive"
      });
    }
  };

  const value = {
    user,
    session,
    profile,
    userRole,
    loading,
    isSystemSuperAdmin,
    signUp,
    signIn,
    signInSauth,
    signOut,
    refreshProfile
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import { useState, useEffect } from 'react';
import { GSTService, type GSTSettings, type GSTReturn, type GSTTransaction, type GSTLiability } from '@/services/api/financial';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';

// Re-export types for backward compatibility
export type { GSTSettings, GSTReturn, GSTTransaction, GSTLiability };

export const useGST = () => {
  const [settings, setSettings] = useState<GSTSettings | null>(null);
  const [returns, setReturns] = useState<GSTReturn[]>([]);
  const [transactions, setTransactions] = useState<GSTTransaction[]>([]);
  const [liability, setLiability] = useState<GSTLiability | null>(null);
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();
  const { user, profile, loading: authLoading } = useAuth();

  const fetchSettings = async () => {
    if (!user) {
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.getSettings();
      
      if (response.success && response.data) {
        setSettings(response.data);
      } else {
        setSettings(null);
      }
    } catch (error) {
      logError('Error fetching GST settings:', error);
      toast({
        title: "Error",
        description: "Failed to fetch GST settings",
        variant: "destructive"
      });
      setSettings(null);
    } finally {
      setLoading(false);
    }
  };

  const fetchReturns = async () => {
    if (!user) {
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.getReturns();
      
      if (response.success && response.data) {
        setReturns(response.data || []);
      } else {
        setReturns([]);
      }
    } catch (error) {
      logError('Error fetching GST returns:', error);
      toast({
        title: "Error",
        description: "Failed to fetch GST returns",
        variant: "destructive"
      });
      setReturns([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchTransactions = async (filters?: { 
    transaction_type?: string; 
    start_date?: string; 
    end_date?: string;
    invoice_number?: string;
  }) => {
    if (!user) {
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.getTransactions(filters);
      
      if (response.success && response.data) {
        setTransactions(response.data || []);
      } else {
        setTransactions([]);
      }
    } catch (error) {
      logError('Error fetching GST transactions:', error);
      toast({
        title: "Error",
        description: "Failed to fetch GST transactions",
        variant: "destructive"
      });
      setTransactions([]);
    } finally {
      setLoading(false);
    }
  };

  const fetchLiability = async (startDate: string, endDate: string) => {
    if (!user) {
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.calculateLiability(startDate, endDate);
      
      if (response.success && response.data) {
        setLiability(response.data);
      } else {
        setLiability({
          total_taxable_value: 0,
          total_cgst: 0,
          total_sgst: 0,
          total_igst: 0,
          total_cess: 0,
          total_tax: 0
        });
      }
    } catch (error) {
      logError('Error calculating GST liability:', error);
      toast({
        title: "Error",
        description: "Failed to calculate GST liability",
        variant: "destructive"
      });
      setLiability({
        total_taxable_value: 0,
        total_cgst: 0,
        total_sgst: 0,
        total_igst: 0,
        total_cess: 0,
        total_tax: 0
      });
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async (settingsData: Omit<GSTSettings, 'id' | 'agency_id' | 'created_at' | 'updated_at'>) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      
      let response;
      if (settings?.id) {
        response = await GSTService.updateSettings(settings.id, settingsData);
      } else {
        response = await GSTService.createSettings(settingsData);
      }
      
      if (response.success) {
        await fetchSettings();
        toast({
          title: "Success",
          description: "GST settings saved successfully"
        });
      } else {
        throw new Error(response.error || 'Failed to save GST settings');
      }
    } catch (error) {
      logError('Error saving GST settings:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to save GST settings",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const createTransaction = async (transaction: Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at' | 'updated_at'>) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.createTransaction(transaction);
      
      if (response.success) {
        await fetchTransactions();
        toast({
          title: "Success",
          description: "GST transaction created successfully"
        });
        return response.data;
      } else {
        throw new Error(response.error || 'Failed to create GST transaction');
      }
    } catch (error) {
      logError('Error creating GST transaction:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to create GST transaction",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const updateTransaction = async (transactionId: string, transaction: Partial<Omit<GSTTransaction, 'id' | 'agency_id' | 'created_at'>>) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.updateTransaction(transactionId, transaction);
      
      if (response.success) {
        await fetchTransactions();
        toast({
          title: "Success",
          description: "GST transaction updated successfully"
        });
        return response.data;
      } else {
        throw new Error(response.error || 'Failed to update GST transaction');
      }
    } catch (error) {
      logError('Error updating GST transaction:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to update GST transaction",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const deleteTransaction = async (transactionId: string) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.deleteTransaction(transactionId);
      
      if (response.success) {
        await fetchTransactions();
        toast({
          title: "Success",
          description: "GST transaction deleted successfully"
        });
      } else {
        throw new Error(response.error || 'Failed to delete GST transaction');
      }
    } catch (error) {
      logError('Error deleting GST transaction:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to delete GST transaction",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const generateReturn = async (returnType: 'GSTR1' | 'GSTR3B' | 'GSTR9' | 'GSTR4', filingPeriod: string) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.generateReturn(returnType, filingPeriod);
      
      if (response.success && response.data) {
        await fetchReturns();
        toast({
          title: "Success",
          description: "GST return generated successfully"
        });
        return response.data;
      } else {
        throw new Error(response.error || 'Failed to generate GST return');
      }
    } catch (error) {
      logError('Error generating GST return:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to generate GST return",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const updateReturn = async (returnId: string, gstReturn: Partial<Omit<GSTReturn, 'id' | 'agency_id' | 'created_at'>>) => {
    if (!user) {
      toast({
        title: "Error",
        description: "User not authenticated",
        variant: "destructive"
      });
      return;
    }

    try {
      setLoading(true);
      const response = await GSTService.updateReturn(returnId, gstReturn);
      
      if (response.success) {
        await fetchReturns();
        toast({
          title: "Success",
          description: "GST return updated successfully"
        });
        return response.data;
      } else {
        throw new Error(response.error || 'Failed to update GST return');
      }
    } catch (error) {
      logError('Error updating GST return:', error);
      toast({
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to update GST return",
        variant: "destructive"
      });
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const [hasFetched, setHasFetched] = useState(false);
  
  useEffect(() => {
    // Only fetch data ONCE when user is authenticated (with or without agency_id for super_admin)
    const hasAgencyContext = typeof window !== 'undefined' && localStorage.getItem('agency_database');
    const canFetch = user && (profile?.agency_id || hasAgencyContext);
    
    if (!authLoading && canFetch && !hasFetched) {
      setHasFetched(true);
      
      // Use a delay to batch requests
      const timeoutId = setTimeout(() => {
        fetchSettings();
        fetchReturns();
        fetchTransactions();
      }, 500);
      
      return () => clearTimeout(timeoutId);
    }
  }, [user?.id, profile?.agency_id, authLoading, hasFetched]); // Track if we've already fetched

  // For super_admin, check if they have agency_database context instead of agency_id
  const hasAgencyContext = typeof window !== 'undefined' && localStorage.getItem('agency_database');
  
  // Allow access if:
  // 1. User is authenticated AND has agency_id in profile, OR
  // 2. User is authenticated AND has agency_database context (for super_admin)
  const isAuthenticated = !!user && (!!profile?.agency_id || !!hasAgencyContext);

  return {
    settings,
    returns,
    transactions,
    liability,
    loading: loading || authLoading,
    fetchSettings,
    fetchReturns,
    fetchTransactions,
    fetchLiability,
    saveSettings,
    createTransaction,
    updateTransaction,
    deleteTransaction,
    generateReturn,
    updateReturn,
    isAuthenticated
  };
};

import { useState, useEffect } from 'react';
import { useToast } from '@/hooks/use-toast';
import {
  fetchPlans as fetchPlansApi,
  fetchFeatures as fetchFeaturesApi,
  updatePlanApi,
  createPlanApi,
  deactivatePlanApi,
  createFeatureApi,
  updateFeatureApi,
  deleteFeatureApi,
} from '@/services/api/system';

export interface PlanFeature {
  id: string;
  name: string;
  description: string;
  feature_key: string;
  enabled: boolean;
  is_active?: boolean;
  is_system?: boolean;
}

export interface SubscriptionPlan {
  id: string;
  name: string;
  description: string;
  price: number;
  currency: string;
  interval: string;
  is_active: boolean;
  max_users?: number;
  max_agencies?: number;
  max_storage_gb?: number;
  stripe_product_id?: string;
  stripe_price_id?: string;
