      type: "ERROR_CAPTURED",
      error: {
        message: event.message,
        stack: event.error?.stack,
        filename: event.filename,
        lineno: event.lineno,
        colno: event.colno,
        source: "window.onerror",
      },
      timestamp: Date.now(),
    });
  });

  window.addEventListener("unhandledrejection", (event) => {
    const reason: any = event.reason;
    const message =
      typeof reason === "object" && reason?.message
        ? String(reason.message)
        : String(reason);
    const stack = typeof reason === "object" ? reason?.stack : undefined;

    // Mirror to parent iframe as well
    sendToParent({
      type: "ERROR_CAPTURED",
      error: {
        message,
        stack,
        filename: undefined,
        lineno: undefined,
        colno: undefined,
        source: "unhandledrejection",
      },
      timestamp: Date.now(),
    });
  });
}

createRoot(document.getElementById("root")!).render(<App />);

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Progress } from '@/components/ui/progress';
import { Badge } from '@/components/ui/badge';
import { useToast } from '@/hooks/use-toast';
import { useAuth } from '@/hooks/useAuth';
import { getApiBaseUrl } from '@/config/api';
import { PageContainer, PageHeader } from '@/components/layout';
import {
  Loader2,
  Building2,
  Users,
  Settings,
  CheckCircle2,
  ArrowRight,
  FileText,
  DollarSign,
  Briefcase,
  TrendingUp,
  Calendar,
  AlertCircle,
} from 'lucide-react';

const SETUP_STEPS = [
  { id: 1, title: 'Company Profile', icon: Building2, description: 'Basic company information and branding' },
  { id: 2, title: 'Business Details', icon: FileText, description: 'Legal and tax information' },
  { id: 3, title: 'Departments', icon: Briefcase, description: 'Organizational structure' },
  { id: 4, title: 'Financial Setup', icon: DollarSign, description: 'Currency, payment, and billing' },
  { id: 5, title: 'Team Members', icon: Users, description: 'Add your team' },
  { id: 6, title: 'Preferences', icon: Settings, description: 'System preferences' },
  { id: 7, title: 'Review', icon: CheckCircle2, description: 'Review and complete' },
];

interface SetupProgress {
  setupComplete: boolean;
  progress: number;
  completedSteps: string[];
  totalSteps: number;
  lastUpdated: string | null;
  agencyName?: string;
}

export default function AgencySetupProgress() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const { userRole } = useAuth();
  const [loading, setLoading] = useState(true);
  const [progressData, setProgressData] = useState<SetupProgress | null>(null);

  // Redirect super admins immediately
  useEffect(() => {
    if (userRole === 'super_admin') {
      navigate('/system', { replace: true });
      return;
    }
  }, [userRole, navigate]);

  useEffect(() => {
    // Don't fetch if super admin (will be redirected)
    if (userRole === 'super_admin') {
      return;
    }
    
    const fetchProgress = async () => {
      try {
        const agencyDatabase = localStorage.getItem('agency_database');
        if (!agencyDatabase) {
          navigate('/dashboard');
          return;
        }

        const apiBaseUrl = getApiBaseUrl();
        
        const response = await fetch(`${apiBaseUrl}/api/agencies/check-setup?database=${encodeURIComponent(agencyDatabase)}&detailed=true`, {
          method: 'GET',
          headers: {
            'Authorization': `Bearer ${localStorage.getItem('auth_token')}`,
            'X-Agency-Database': agencyDatabase || '',
          },
        });

        if (response.ok) {
          const data = await response.json();
          // Ensure data has required structure with defaults
          const normalizedData: SetupProgress = {
            setupComplete: data.setupComplete || false,
            progress: data.progress || 0,
            completedSteps: Array.isArray(data.completedSteps) ? data.completedSteps : [],
            totalSteps: data.totalSteps || 7,
            lastUpdated: data.lastUpdated || null,
            agencyName: data.agencyName || '',
          };
          setProgressData(normalizedData);
          
          // If setup is complete, redirect to dashboard
          if (normalizedData.setupComplete) {
            toast({
              title: 'Setup Complete!',
              description: 'Your agency setup is already complete.',
            });
            setTimeout(() => navigate('/dashboard'), 2000);
          }
        } else {
          throw new Error('Failed to fetch progress');
        }
      } catch (error: unknown) {
        console.error('Error fetching setup progress:', error);
        toast({
          title: 'Error',
          description: 'Failed to load setup progress. Please try again.',
          variant: 'destructive',
        });
      } finally {
        setLoading(false);
      }
    };

    fetchProgress();
  }, [navigate, toast]);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center">
          <Loader2 className="h-12 w-12 animate-spin text-primary mx-auto mb-4" />
          <p className="text-muted-foreground">Loading setup progress...</p>
        </div>
      </div>
    );
  }

  if (!progressData) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Card className="max-w-md w-full">
          <CardContent className="p-6 text-center">
            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
            <h3 className="text-lg font-semibold mb-2">Unable to Load Progress</h3>
            <p className="text-muted-foreground mb-4">
              We couldn't load your setup progress. Please try again.
            </p>
            <Button onClick={() => window.location.reload()}>
              Retry
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  // Safely destructure with defaults to prevent undefined errors
  const { 
    progress = 0, 
    completedSteps = [], 
    totalSteps = 7, 
    lastUpdated = null, 
    agencyName = '', 
    setupComplete = false 
  } = progressData || {};

  return (
    <PageContainer>
      <PageHeader
        title="Agency setup progress"
        description={
          agencyName
            ? `${agencyName} – track and complete your initial configuration.`
            : 'Track your agency setup status and complete the remaining steps.'
        }
        actions={
          <Badge variant={setupComplete ? 'default' : 'outline'}>
            {progress}% complete
          </Badge>
        }
      />

      <div className="grid gap-6 md:grid-cols-[2fr,1fr]">
        {/* Left column: progress + checklist */}
        <div className="space-y-6">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="flex items-center gap-2">
                <TrendingUp className="h-4 w-4 text-primary" />
                Overall progress
              </CardTitle>
              <CardDescription>
                {setupComplete
                  ? 'Setup is complete. You can still review and adjust configuration at any time.'
                  : `${completedSteps.length} of ${totalSteps} steps completed`}
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <Progress value={progress} className="h-2" />
              <div className="flex justify-between text-xs text-muted-foreground">
                <span>{completedSteps.length} steps completed</span>
                <span>{totalSteps - completedSteps.length} steps remaining</span>
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">Setup checklist</CardTitle>
              <CardDescription>
                Work through each section to finalise your workspace.
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {SETUP_STEPS.map((step, index) => {
                  const isCompleted = completedSteps.includes(step.title);
                  const StepIcon = step.icon;

                  return (
                    <div
                      key={step.id}
                      className="flex items-center gap-3 rounded-md border bg-card px-3 py-2 text-sm"
                    >
                      <div className="flex h-8 w-8 items-center justify-center rounded-full border bg-muted">
                        {isCompleted ? (
                          <CheckCircle2 className="h-4 w-4 text-primary" />
                        ) : (
                          <StepIcon className="h-4 w-4 text-muted-foreground" />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{step.title}</span>
                          {isCompleted && (
                            <Badge variant="outline" className="text-[10px]">
                              Complete
                            </Badge>
                          )}
                        </div>
                        <p className="text-xs text-muted-foreground">
                          {step.description}
                        </p>
                      </div>
                      <span className="text-[11px] text-muted-foreground">
                        Step {index + 1}
                      </span>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Right column: meta + actions */}
        <div className="space-y-6">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base">Status & actions</CardTitle>
              <CardDescription>Key information about your setup.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between text-sm">
                <div className="space-y-0.5">
                  <p className="text-muted-foreground">Setup status</p>
                  <p className="font-medium">
                    {setupComplete ? 'Complete' : 'In progress'}
                  </p>
                </div>
                <Badge variant={setupComplete ? 'default' : 'secondary'}>
                  {setupComplete ? 'Ready to use' : 'Needs attention'}
                </Badge>
              </div>

              <div className="flex items-center justify-between text-sm">
                <div className="flex items-center gap-2">
                  <Calendar className="h-4 w-4 text-muted-foreground" />
                  <div className="space-y-0.5">
                    <p className="text-muted-foreground">Last updated</p>
                    <p className="text-xs">
                      {lastUpdated
                        ? new Date(lastUpdated).toLocaleString()
                        : 'Not updated yet'}
                    </p>
                  </div>
                </div>
              </div>

              <div className="pt-2 flex flex-col gap-2">
                <Button
                  variant="outline"
                  className="w-full"
                  onClick={() => navigate('/agency')}
                >
                  Go to dashboard
                </Button>
                {!setupComplete && (
                  <Button
                    className="w-full"
                    onClick={() => navigate('/agency-setup')}
                  >
                    Continue setup
                    <ArrowRight className="ml-2 h-4 w-4" />
                  </Button>
                )}
              </div>
            </CardContent>
          </Card>

          {setupComplete && (
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-base">Setup complete</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2 text-sm text-muted-foreground">
                <p>
                  Your agency has been fully configured. You can now focus on
                  day-to-day operations and use all available modules.
                </p>
                <p>
                  You can adjust these settings at any time from the{' '}
                  <Button
                    variant="link"
                    className="h-auto p-0 align-baseline text-primary"
                    onClick={() => navigate('/settings')}
                  >
                    Settings
                  </Button>{' '}
                  area.
                </p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </PageContainer>
  );
}

/**
 * Asset Categories Page
 * Complete asset category management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  FolderTree,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Filter,
  TrendingDown,
} from 'lucide-react';
import {
  getAssetCategories,
  createAssetCategory,
  updateAssetCategory,
  deleteAssetCategory,
  type AssetCategory,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';

export default function AssetCategories() {
  const { toast } = useToast();
  const [categories, setCategories] = useState<AssetCategory[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterActive, setFilterActive] = useState<boolean | undefined>(undefined);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState<AssetCategory | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<AssetCategory>>({
    code: '',
    name: '',
    description: '',
    parent_id: '',
    depreciation_method: 'straight_line',
    default_useful_life_years: undefined,
    default_depreciation_rate: undefined,
    is_active: true,
  });

  useEffect(() => {
    loadData();
  }, [filterActive]);

  const loadData = async () => {
    try {
      setLoading(true);
      const data = await getAssetCategories();
      setCategories(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load categories',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setFormData({
      code: '',
      name: '',
      description: '',
      parent_id: '',
      depreciation_method: 'straight_line',
      default_useful_life_years: undefined,
      default_depreciation_rate: undefined,
      is_active: true,
    });
    setSelectedCategory(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (category: AssetCategory) => {
    setFormData({
      ...category,
    });
    setSelectedCategory(category);
    setIsDialogOpen(true);
  };

  const handleView = (category: AssetCategory) => {
    setSelectedCategory(category);
    setIsViewDialogOpen(true);
  };

  const handleDelete = async (category: AssetCategory) => {
    if (!confirm(`Are you sure you want to delete category "${category.name}"?`)) {
      return;
    }

    try {
      await deleteAssetCategory(category.id);
      toast({
        title: 'Success',
        description: 'Category deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete category',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.code || !formData.name) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSubmitting(true);
      if (selectedCategory) {
        await updateAssetCategory(selectedCategory.id, formData);
        toast({
          title: 'Success',
          description: 'Category updated successfully',
        });
      } else {
        await createAssetCategory(formData);
        toast({
          title: 'Success',
          description: 'Category created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save category',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredCategories = categories.filter((category) => {
    const matchesSearch =
      category.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      category.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      category.description?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterActive === undefined || category.is_active === filterActive;
    return matchesSearch && matchesFilter;
  });

  // Build category tree for display
  const getCategoryPath = (category: AssetCategory): string => {
    const parent = categories.find((c) => c.id === category.parent_id);
    if (parent) {
      return `${getCategoryPath(parent)} > ${category.name}`;
    }
    return category.name;
  };

  const stats = {
    total: categories.length,
    active: categories.filter((c) => c.is_active).length,
    inactive: categories.filter((c) => !c.is_active).length,
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Categories</h1>
          <p className="text-muted-foreground">Manage asset categories and depreciation settings</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="mr-2 h-4 w-4" />
          Create Category
        </Button>
      </div>

      {/* Statistics */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Categories</CardTitle>
            <FolderTree className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Categories</CardTitle>
            <TrendingDown className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{stats.active}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Inactive Categories</CardTitle>
            <FolderTree className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-600">{stats.inactive}</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search categories..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select
                value={filterActive === undefined ? 'all' : filterActive ? 'active' : 'inactive'}
                onValueChange={(value) =>
                  setFilterActive(value === 'all' ? undefined : value === 'active')
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Categories Table */}
      <Card>
        <CardHeader>
          <CardTitle>Categories List</CardTitle>
          <CardDescription>Manage all asset categories</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : filteredCategories.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No categories found. Create your first category to get started.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Code</TableHead>
                  <TableHead>Name</TableHead>
                  <TableHead>Parent</TableHead>
                  <TableHead>Depreciation Method</TableHead>
                  <TableHead>Useful Life</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredCategories.map((category) => (
                  <TableRow key={category.id}>
                    <TableCell className="font-mono">{category.code}</TableCell>
                    <TableCell className="font-medium">{category.name}</TableCell>
                    <TableCell>
                      {category.parent_id
                        ? categories.find((c) => c.id === category.parent_id)?.name || '-'
                        : '-'}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {category.depreciation_method || 'straight_line'}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {category.default_useful_life_years
                        ? `${category.default_useful_life_years} years`
                        : '-'}
                    </TableCell>
                    <TableCell>
                      <Badge variant={category.is_active ? 'default' : 'secondary'}>
                        {category.is_active ? 'Active' : 'Inactive'}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {new Date(category.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(category)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(category)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(category)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{selectedCategory ? 'Edit Category' : 'Create Category'}</DialogTitle>
            <DialogDescription>
              {selectedCategory
                ? 'Update category details'
                : 'Create a new asset category'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="code">Code *</Label>
                  <Input
                    id="code"
                    value={formData.code || ''}
                    onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    placeholder="e.g., IT-EQUIP"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="name">Name *</Label>
                  <Input
                    id="name"
                    value={formData.name || ''}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., IT Equipment"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Category description..."
                  rows={3}
                />
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="parent_id">Parent Category</Label>
                  <Select
                    value={formData.parent_id || 'none'}
                    onValueChange={(value) =>
                      setFormData({
                        ...formData,
                        parent_id: value === 'none' ? undefined : value,
                      })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="None (Top Level)" />
                    </SelectTrigger>
                    <SelectContent>
                    <SelectItem value="none">None (Top Level)</SelectItem>
                      {categories
                        .filter((c) => c.id !== selectedCategory?.id)
                        .map((category) => (
                          <SelectItem key={category.id} value={category.id}>
                            {category.name} ({category.code})
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="depreciation_method">Depreciation Method</Label>
                  <Select
                    value={formData.depreciation_method || 'straight_line'}
                    onValueChange={(value) =>
                      setFormData({ ...formData, depreciation_method: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="straight_line">Straight Line</SelectItem>
                      <SelectItem value="declining_balance">Declining Balance</SelectItem>
                      <SelectItem value="units_of_production">Units of Production</SelectItem>
                      <SelectItem value="sum_of_years">Sum of Years</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="default_useful_life_years">Default Useful Life (Years)</Label>
                  <Input
                    id="default_useful_life_years"
                    type="number"
                    min="0"
                    value={formData.default_useful_life_years || ''}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        default_useful_life_years: e.target.value
                          ? parseInt(e.target.value)
                          : undefined,
                      })
                    }
                    placeholder="e.g., 5"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="default_depreciation_rate">Default Depreciation Rate (%)</Label>
                  <Input
                    id="default_depreciation_rate"
                    type="number"
                    step="0.01"
                    min="0"
                    max="100"
                    value={formData.default_depreciation_rate || ''}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        default_depreciation_rate: e.target.value
                          ? parseFloat(e.target.value)
                          : undefined,
                      })
                    }
                    placeholder="e.g., 20"
                  />
                </div>
              </div>
              <div className="space-y-2 flex items-center gap-4 pt-2">
                <Label htmlFor="is_active">Active</Label>
                <Switch
                  id="is_active"
                  checked={formData.is_active}
                  onCheckedChange={(checked) =>
                    setFormData({ ...formData, is_active: checked })
                  }
                />
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedCategory ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Category Details</DialogTitle>
            <DialogDescription>View category information</DialogDescription>
          </DialogHeader>
          {selectedCategory && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Code</Label>
                  <div className="mt-1 font-mono">{selectedCategory.code}</div>
                </div>
                <div>
                  <Label>Name</Label>
                  <div className="mt-1 font-medium">{selectedCategory.name}</div>
                </div>
                <div>
                  <Label>Parent Category</Label>
                  <div className="mt-1">
                    {selectedCategory.parent_id
                      ? categories.find((c) => c.id === selectedCategory.parent_id)?.name || '-'
                      : '-'}
                  </div>
                </div>
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">
                    <Badge variant={selectedCategory.is_active ? 'default' : 'secondary'}>
                      {selectedCategory.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label>Depreciation Method</Label>
                  <div className="mt-1">
                    <Badge variant="outline">
                      {selectedCategory.depreciation_method || 'straight_line'}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label>Default Useful Life</Label>
                  <div className="mt-1">
                    {selectedCategory.default_useful_life_years
                      ? `${selectedCategory.default_useful_life_years} years`
                      : '-'}
                  </div>
                </div>
                <div>
                  <Label>Default Depreciation Rate</Label>
                  <div className="mt-1">
                    {selectedCategory.default_depreciation_rate
                      ? `${selectedCategory.default_depreciation_rate}%`
                      : '-'}
                  </div>
                </div>
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedCategory.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
              {selectedCategory.description && (
                <div>
                  <Label>Description</Label>
                  <div className="mt-1 text-sm">{selectedCategory.description}</div>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedCategory && (
              <Button
                onClick={() => {
                  setIsViewDialogOpen(false);
                  handleEdit(selectedCategory);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Asset Depreciation Page
 * Complete asset depreciation tracking interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  TrendingDown,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Calendar,
  DollarSign,
  CheckCircle2,
  XCircle,
  Calculator,
} from 'lucide-react';
import {
  getAllDepreciation,
  createDepreciation,
  updateDepreciation,
  deleteDepreciation,
  getAssets,
  type DepreciationRecord,
  type Asset,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function AssetDepreciation() {
  const { toast } = useToast();
  const [depreciation, setDepreciation] = useState<DepreciationRecord[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [assetsLoading, setAssetsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterAsset, setFilterAsset] = useState<string>('all');
  const [filterPosted, setFilterPosted] = useState<string>('all');
  const [filterMethod, setFilterMethod] = useState<string>('all');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedDepreciation, setSelectedDepreciation] = useState<DepreciationRecord | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<DepreciationRecord>>({
    asset_id: '',
    depreciation_date: '',
    period_start: '',
    period_end: '',
    depreciation_amount: 0,
    accumulated_depreciation: 0,
    book_value: 0,
    depreciation_method: 'straight_line',
    is_posted: false,
    journal_entry_id: '',
    notes: '',
  });

  useEffect(() => {
    loadAssets();
    loadData();
  }, [filterAsset, filterPosted, filterMethod, dateFrom, dateTo]);

  const loadAssets = async () => {
    try {
      setAssetsLoading(true);
      const data = await getAssets();
      setAssets(data);
    } catch (error: unknown) {
      console.error('Failed to load assets:', error);
    } finally {
      setAssetsLoading(false);
    }
  };

  const loadData = async () => {
    try {
      setLoading(true);
      const filters: unknown = {};
      if (filterAsset !== 'all') filters.asset_id = filterAsset;
      if (filterPosted !== 'all') filters.is_posted = filterPosted === 'posted';
      if (filterMethod !== 'all') filters.depreciation_method = filterMethod;
      if (dateFrom) filters.date_from = dateFrom;
      if (dateTo) filters.date_to = dateTo;
      if (searchTerm) filters.search = searchTerm;

      const data = await getAllDepreciation(filters);
      setDepreciation(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load depreciation records',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setFormData({
      asset_id: '',
      depreciation_date: '',
      period_start: '',
      period_end: '',
      depreciation_amount: 0,
      accumulated_depreciation: 0,
      book_value: 0,
      depreciation_method: 'straight_line',
      is_posted: false,
      journal_entry_id: '',
      notes: '',
    });
    setSelectedDepreciation(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (record: DepreciationRecord) => {
    setFormData({
      ...record,
    });
    setSelectedDepreciation(record);
    setIsDialogOpen(true);
  };

  const handleView = (record: DepreciationRecord) => {
    setSelectedDepreciation(record);
    setIsViewDialogOpen(true);
  };

  const handleDelete = async (record: DepreciationRecord) => {
    if (!confirm(`Are you sure you want to delete depreciation record for ${record.asset_name || 'asset'}?`)) {
      return;
    }

    try {
      await deleteDepreciation(record.id);
      toast({
        title: 'Success',
        description: 'Depreciation record deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete depreciation record',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.asset_id || !formData.depreciation_date || !formData.period_start || !formData.period_end) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSubmitting(true);
      if (selectedDepreciation) {
        await updateDepreciation(selectedDepreciation.id, formData);
        toast({
          title: 'Success',
          description: 'Depreciation record updated successfully',
        });
      } else {
        await createDepreciation(formData);
        toast({
          title: 'Success',
          description: 'Depreciation record created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save depreciation record',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const stats = {
    total: depreciation.length,
    posted: depreciation.filter((d) => d.is_posted).length,
    unposted: depreciation.filter((d) => !d.is_posted).length,
    totalDepreciation: depreciation.reduce((sum, d) => {
      const amount = typeof d.depreciation_amount === 'number' ? d.depreciation_amount : parseFloat(String(d.depreciation_amount || 0));
      return sum + (isNaN(amount) ? 0 : amount);
    }, 0),
    totalAccumulated: depreciation.length > 0
      ? (typeof depreciation[0].accumulated_depreciation === 'number'
          ? depreciation[0].accumulated_depreciation
          : parseFloat(String(depreciation[0].accumulated_depreciation || 0)))
      : 0,
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Depreciation</h1>
          <p className="text-muted-foreground">Track and manage asset depreciation records</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="mr-2 h-4 w-4" />
          Create Depreciation
        </Button>
      </div>

      {/* Statistics */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Records</CardTitle>
            <Calculator className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Posted</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{stats.posted}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Unposted</CardTitle>
            <XCircle className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-orange-600">{stats.unposted}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Depreciation</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              ${(typeof stats.totalDepreciation === 'number' ? stats.totalDepreciation : parseFloat(String(stats.totalDepreciation || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-6">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search assets..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && loadData()}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Asset</Label>
              <Select value={filterAsset} onValueChange={setFilterAsset}>
                <SelectTrigger>
                  <SelectValue placeholder="All Assets" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Assets</SelectItem>
                  {assets.map((asset) => (
                    <SelectItem key={asset.id} value={asset.id}>
                      {asset.asset_number} - {asset.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Posted Status</Label>
              <Select value={filterPosted} onValueChange={setFilterPosted}>
                <SelectTrigger>
                  <SelectValue placeholder="All" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All</SelectItem>
                  <SelectItem value="posted">Posted</SelectItem>
                  <SelectItem value="unposted">Unposted</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Method</Label>
              <Select value={filterMethod} onValueChange={setFilterMethod}>
                <SelectTrigger>
                  <SelectValue placeholder="All Methods" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Methods</SelectItem>
                  <SelectItem value="straight_line">Straight Line</SelectItem>
                  <SelectItem value="declining_balance">Declining Balance</SelectItem>
                  <SelectItem value="units_of_production">Units of Production</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Date From</Label>
              <Input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label>Date To</Label>
              <Input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Depreciation Table */}
      <Card>
        <CardHeader>
          <CardTitle>Depreciation Records</CardTitle>
          <CardDescription>Manage all asset depreciation calculations</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : depreciation.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No depreciation records found. Create your first depreciation record to get started.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Asset</TableHead>
                  <TableHead>Depreciation Date</TableHead>
                  <TableHead>Period</TableHead>
                  <TableHead>Method</TableHead>
                  <TableHead>Depreciation Amount</TableHead>
                  <TableHead>Accumulated</TableHead>
                  <TableHead>Book Value</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {depreciation.map((record) => (
                  <TableRow key={record.id}>
                    <TableCell>
                      {record.asset_name ? (
                        <div>
                          <div className="font-mono text-sm">{record.asset_number}</div>
                          <div className="text-sm text-muted-foreground">{record.asset_name}</div>
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell>
                      {new Date(record.depreciation_date).toLocaleDateString()}
                    </TableCell>
                    <TableCell>
                      <div className="text-sm">
                        <div>{new Date(record.period_start).toLocaleDateString()}</div>
                        <div className="text-muted-foreground">to</div>
                        <div>{new Date(record.period_end).toLocaleDateString()}</div>
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {record.depreciation_method.replace('_', ' ')}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      ${(typeof record.depreciation_amount === 'number' ? record.depreciation_amount : parseFloat(String(record.depreciation_amount || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </TableCell>
                    <TableCell>
                      ${(typeof record.accumulated_depreciation === 'number' ? record.accumulated_depreciation : parseFloat(String(record.accumulated_depreciation || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </TableCell>
                    <TableCell>
                      ${(typeof record.book_value === 'number' ? record.book_value : parseFloat(String(record.book_value || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </TableCell>
                    <TableCell>
                      <Badge variant={record.is_posted ? 'default' : 'secondary'}>
                        {record.is_posted ? (
                          <>
                            <CheckCircle2 className="mr-1 h-3 w-3" />
                            Posted
                          </>
                        ) : (
                          <>
                            <XCircle className="mr-1 h-3 w-3" />
                            Unposted
                          </>
                        )}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(record)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        {!record.is_posted && (
                          <>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEdit(record)}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDelete(record)}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </>
                        )}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedDepreciation ? 'Edit Depreciation Record' : 'Create Depreciation Record'}
            </DialogTitle>
            <DialogDescription>
              {selectedDepreciation
                ? 'Update depreciation record details'
                : 'Create a new depreciation record'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="asset_id">Asset *</Label>
                  <Select
                    value={formData.asset_id || ''}
                    onValueChange={(value) => setFormData({ ...formData, asset_id: value })}
                    disabled={!!selectedDepreciation}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select asset" />
                    </SelectTrigger>
                    <SelectContent>
                      {assets.map((asset) => (
                        <SelectItem key={asset.id} value={asset.id}>
                          {asset.asset_number} - {asset.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="depreciation_date">Depreciation Date *</Label>
                  <Input
                    id="depreciation_date"
                    type="date"
                    value={formData.depreciation_date || ''}
                    onChange={(e) => setFormData({ ...formData, depreciation_date: e.target.value })}
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="period_start">Period Start *</Label>
                  <Input
                    id="period_start"
                    type="date"
                    value={formData.period_start || ''}
                    onChange={(e) => setFormData({ ...formData, period_start: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="period_end">Period End *</Label>
                  <Input
                    id="period_end"
                    type="date"
                    value={formData.period_end || ''}
                    onChange={(e) => setFormData({ ...formData, period_end: e.target.value })}
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="depreciation_method">Method</Label>
                  <Select
                    value={formData.depreciation_method || 'straight_line'}
                    onValueChange={(value: unknown) =>
                      setFormData({ ...formData, depreciation_method: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="straight_line">Straight Line</SelectItem>
                      <SelectItem value="declining_balance">Declining Balance</SelectItem>
                      <SelectItem value="units_of_production">Units of Production</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="depreciation_amount">Depreciation Amount</Label>
                  <Input
                    id="depreciation_amount"
                    type="number"
                    step="0.01"
                    value={formData.depreciation_amount || 0}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        depreciation_amount: parseFloat(e.target.value) || 0,
                      })
                    }
                    placeholder="0.00"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="accumulated_depreciation">Accumulated Depreciation</Label>
                  <Input
                    id="accumulated_depreciation"
                    type="number"
                    step="0.01"
                    value={formData.accumulated_depreciation || 0}
                    onChange={(e) =>
                      setFormData({
                        ...formData,
                        accumulated_depreciation: parseFloat(e.target.value) || 0,
                      })
                    }
                    placeholder="0.00"
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="book_value">Book Value</Label>
                  <Input
                    id="book_value"
                    type="number"
                    step="0.01"
                    value={formData.book_value || 0}
                    onChange={(e) =>
                      setFormData({ ...formData, book_value: parseFloat(e.target.value) || 0 })
                    }
                    placeholder="0.00"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="journal_entry_id">Journal Entry ID</Label>
                  <Input
                    id="journal_entry_id"
                    value={formData.journal_entry_id || ''}
                    onChange={(e) => setFormData({ ...formData, journal_entry_id: e.target.value })}
                    placeholder="Journal entry reference"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="notes">Notes</Label>
                <Textarea
                  id="notes"
                  value={formData.notes || ''}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={3}
                />
              </div>
              {selectedDepreciation && (
                <div className="space-y-2 flex items-center gap-4 pt-2">
                  <Label htmlFor="is_posted">Posted to Ledger</Label>
                  <Badge variant={formData.is_posted ? 'default' : 'secondary'}>
                    {formData.is_posted ? 'Posted' : 'Unposted'}
                  </Badge>
                </div>
              )}
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedDepreciation ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Depreciation Record Details</DialogTitle>
            <DialogDescription>View depreciation information</DialogDescription>
          </DialogHeader>
          {selectedDepreciation && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Asset</Label>
                  <div className="mt-1">
                    {selectedDepreciation.asset_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedDepreciation.asset_number}</div>
                        <div className="text-sm text-muted-foreground">
                          {selectedDepreciation.asset_name}
                        </div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Depreciation Date</Label>
                  <div className="mt-1">
                    {new Date(selectedDepreciation.depreciation_date).toLocaleDateString()}
                  </div>
                </div>
                <div>
                  <Label>Period Start</Label>
                  <div className="mt-1">
                    {new Date(selectedDepreciation.period_start).toLocaleDateString()}
                  </div>
                </div>
                <div>
                  <Label>Period End</Label>
                  <div className="mt-1">
                    {new Date(selectedDepreciation.period_end).toLocaleDateString()}
                  </div>
                </div>
                <div>
                  <Label>Method</Label>
                  <div className="mt-1">
                    <Badge variant="outline">
                      {selectedDepreciation.depreciation_method.replace('_', ' ')}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">
                    <Badge variant={selectedDepreciation.is_posted ? 'default' : 'secondary'}>
                      {selectedDepreciation.is_posted ? 'Posted' : 'Unposted'}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label>Depreciation Amount</Label>
                  <div className="mt-1">
                    $
                    {(typeof selectedDepreciation.depreciation_amount === 'number'
                      ? selectedDepreciation.depreciation_amount
                      : parseFloat(String(selectedDepreciation.depreciation_amount || 0))
                    ).toLocaleString('en-US', {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2,
                    })}
                  </div>
                </div>
                <div>
                  <Label>Accumulated Depreciation</Label>
                  <div className="mt-1">
                    $
                    {(typeof selectedDepreciation.accumulated_depreciation === 'number'
                      ? selectedDepreciation.accumulated_depreciation
                      : parseFloat(String(selectedDepreciation.accumulated_depreciation || 0))
                    ).toLocaleString('en-US', {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2,
                    })}
                  </div>
                </div>
                <div>
                  <Label>Book Value</Label>
                  <div className="mt-1">
                    $
                    {(typeof selectedDepreciation.book_value === 'number'
                      ? selectedDepreciation.book_value
                      : parseFloat(String(selectedDepreciation.book_value || 0))
                    ).toLocaleString('en-US', {
                      minimumFractionDigits: 2,
                      maximumFractionDigits: 2,
                    })}
                  </div>
                </div>
                {selectedDepreciation.journal_entry_id && (
                  <div>
                    <Label>Journal Entry ID</Label>
                    <div className="mt-1 font-mono text-sm">
                      {selectedDepreciation.journal_entry_id}
                    </div>
                  </div>
                )}
                {selectedDepreciation.posted_at && (
                  <div>
                    <Label>Posted At</Label>
                    <div className="mt-1">
                      {new Date(selectedDepreciation.posted_at).toLocaleString()}
                    </div>
                  </div>
                )}
                {selectedDepreciation.posted_by_email && (
                  <div>
                    <Label>Posted By</Label>
                    <div className="mt-1">{selectedDepreciation.posted_by_email}</div>
                  </div>
                )}
                {selectedDepreciation.notes && (
                  <div className="md:col-span-2">
                    <Label>Notes</Label>
                    <div className="mt-1">{selectedDepreciation.notes}</div>
                  </div>
                )}
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedDepreciation.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedDepreciation && !selectedDepreciation.is_posted && (
              <Button
                onClick={() => {
                  setIsViewDialogOpen(false);
                  handleEdit(selectedDepreciation);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Asset Disposals Page
 * Manage asset disposals and write-offs
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Trash2,
  Plus,
  Search,
  Loader2,
  Edit,
  Eye,
  Calendar,
  DollarSign,
  CheckCircle2,
  XCircle,
  Clock,
  AlertTriangle,
  FileText,
  TrendingDown,
} from 'lucide-react';
import {
  getAllDisposals,
  getDisposalById,
  createDisposal,
  updateDisposal,
  deleteDisposal,
  approveDisposal,
  getAssets,
  type DisposalRecord,
  type Asset,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function AssetDisposals() {
  const { toast } = useToast();
  const [disposals, setDisposals] = useState<DisposalRecord[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedDisposal, setSelectedDisposal] = useState<DisposalRecord | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<DisposalRecord>>({
    asset_id: '',
    disposal_date: '',
    disposal_type: 'sale',
    disposal_reason: '',
    disposal_value: 0,
    buyer_name: '',
    buyer_contact: '',
    disposal_method: '',
    approval_status: 'pending',
    disposal_cost: 0,
    notes: '',
    document_url: '',
  });

  useEffect(() => {
    loadData();
    loadAssets();
  }, [filterType, filterStatus]);

  const loadData = async () => {
    try {
      setLoading(true);
      const filters: unknown = {};
      if (filterType !== 'all') filters.disposal_type = filterType;
      if (filterStatus !== 'all') filters.approval_status = filterStatus;

      const data = await getAllDisposals(filters);
      let filteredData = data;

      if (searchTerm) {
        filteredData = data.filter(
          (disposal) =>
            disposal.disposal_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
            disposal.asset_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
            disposal.asset_number?.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }

      setDisposals(filteredData);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load disposals',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const loadAssets = async () => {
    try {
      const data = await getAssets({ status: 'active' });
      setAssets(data);
    } catch (error: unknown) {
      console.error('Failed to load assets:', error);
    }
  };

  const handleCreate = () => {
    setFormData({
      asset_id: '',
      disposal_date: '',
      disposal_type: 'sale',
      disposal_reason: '',
      disposal_value: 0,
      buyer_name: '',
      buyer_contact: '',
      disposal_method: '',
      approval_status: 'pending',
      disposal_cost: 0,
      notes: '',
      document_url: '',
    });
    setSelectedDisposal(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (disposal: DisposalRecord) => {
    setFormData({
      ...disposal,
    });
    setSelectedDisposal(disposal);
    setIsDialogOpen(true);
  };

  const handleView = async (disposal: DisposalRecord) => {
    try {
      const fullDisposal = await getDisposalById(disposal.id);
      setSelectedDisposal(fullDisposal);
      setIsViewDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load disposal details',
        variant: 'destructive',
      });
    }
  };

  const handleApprove = async (disposal: DisposalRecord) => {
    if (!confirm(`Are you sure you want to approve disposal "${disposal.disposal_number}"?`)) {
      return;
    }

    try {
      await approveDisposal(disposal.id);
      toast({
        title: 'Success',
        description: 'Disposal approved successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to approve disposal',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async () => {
    try {
      setIsSubmitting(true);
      if (selectedDisposal) {
        await updateDisposal(selectedDisposal.id, formData);
        toast({
          title: 'Success',
          description: 'Disposal updated successfully',
        });
      } else {
        await createDisposal(formData);
        toast({
          title: 'Success',
          description: 'Disposal created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save disposal',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (disposal: DisposalRecord) => {
    if (!confirm(`Are you sure you want to delete disposal "${disposal.disposal_number}"?`)) {
      return;
    }

    try {
      await deleteDisposal(disposal.id);
      toast({
        title: 'Success',
        description: 'Disposal deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete disposal',
        variant: 'destructive',
      });
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      approved: 'default',
      pending: 'secondary',
      rejected: 'destructive',
    };
    const icons: Record<string, unknown> = {
      approved: CheckCircle2,
      pending: Clock,
      rejected: XCircle,
    };
    const Icon = icons[status] || FileText;

    return (
      <Badge variant={variants[status] || 'secondary'}>
        <Icon className="w-3 h-3 mr-1" />
        {status}
      </Badge>
    );
  };

  const getTypeBadge = (type: string) => {
    const colors: Record<string, string> = {
      sale: 'bg-green-100 text-green-800',
      scrap: 'bg-gray-100 text-gray-800',
      donation: 'bg-blue-100 text-blue-800',
      write_off: 'bg-red-100 text-red-800',
      transfer: 'bg-purple-100 text-purple-800',
    };
    return (
      <Badge className={colors[type] || 'bg-gray-100 text-gray-800'}>
        {type.replace('_', ' ')}
      </Badge>
    );
  };

  const formatCurrency = (value: number | undefined) => {
    if (value === undefined || value === null) return '-';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'INR',
    }).format(numValue);
  };

  // Statistics
  const stats = {
    total: disposals.length,
    pending: disposals.filter((d) => d.approval_status === 'pending').length,
    approved: disposals.filter((d) => d.approval_status === 'approved').length,
    totalValue: disposals.reduce((sum, d) => {
      const value = typeof d.disposal_value === 'number' ? d.disposal_value : parseFloat(String(d.disposal_value || 0));
      return sum + value;
    }, 0),
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Disposals</h1>
          <p className="text-muted-foreground">Manage asset disposals and write-offs</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="w-4 h-4 mr-2" />
          New Disposal
        </Button>
      </div>

      {/* Statistics Cards */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Disposals</CardTitle>
            <Trash2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.pending}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Approved</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.approved}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <DollarSign className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatCurrency(stats.totalValue)}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Disposals</CardTitle>
              <CardDescription>Asset disposal records and approvals</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 mb-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search disposals..."
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    loadData();
                  }}
                  className="pl-8"
                />
              </div>
            </div>
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                <SelectItem value="sale">Sale</SelectItem>
                <SelectItem value="scrap">Scrap</SelectItem>
                <SelectItem value="donation">Donation</SelectItem>
                <SelectItem value="write_off">Write Off</SelectItem>
                <SelectItem value="transfer">Transfer</SelectItem>
              </SelectContent>
            </Select>
            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="pending">Pending</SelectItem>
                <SelectItem value="approved">Approved</SelectItem>
                <SelectItem value="rejected">Rejected</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : disposals.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No disposals found
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Disposal Number</TableHead>
                  <TableHead>Asset</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Date</TableHead>
                  <TableHead>Value</TableHead>
                  <TableHead>Net Proceeds</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {disposals.map((disposal) => (
                  <TableRow key={disposal.id}>
                    <TableCell className="font-medium">{disposal.disposal_number}</TableCell>
                    <TableCell>
                      <div>
                        <div className="font-medium">{disposal.asset_name || '-'}</div>
                        <div className="text-sm text-muted-foreground">
                          {disposal.asset_number || '-'}
                        </div>
                      </div>
                    </TableCell>
                    <TableCell>{getTypeBadge(disposal.disposal_type)}</TableCell>
                    <TableCell>
                      {disposal.disposal_date
                        ? new Date(disposal.disposal_date).toLocaleDateString()
                        : '-'}
                    </TableCell>
                    <TableCell>{formatCurrency(disposal.disposal_value)}</TableCell>
                    <TableCell>{formatCurrency(disposal.net_proceeds)}</TableCell>
                    <TableCell>{getStatusBadge(disposal.approval_status)}</TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(disposal)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                        {disposal.approval_status === 'pending' && (
                          <>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEdit(disposal)}
                            >
                              <Edit className="w-4 h-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleApprove(disposal)}
                              className="text-green-600"
                            >
                              <CheckCircle2 className="w-4 h-4" />
                            </Button>
                          </>
                        )}
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(disposal)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedDisposal ? 'Edit Disposal' : 'Create Disposal'}
            </DialogTitle>
            <DialogDescription>
              {selectedDisposal
                ? 'Update disposal details'
                : 'Create a new asset disposal record'}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Asset *</Label>
              <Select
                value={formData.asset_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, asset_id: value })
                }
                disabled={!!selectedDisposal}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select asset" />
                </SelectTrigger>
                <SelectContent>
                  {assets.map((asset) => (
                    <SelectItem key={asset.id} value={asset.id}>
                      {asset.name} ({asset.asset_number})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Disposal Date *</Label>
                <Input
                  type="date"
                  value={formData.disposal_date}
                  onChange={(e) =>
                    setFormData({ ...formData, disposal_date: e.target.value })
                  }
                />
              </div>
              <div>
                <Label>Disposal Type *</Label>
                <Select
                  value={formData.disposal_type}
                  onValueChange={(value) =>
                    setFormData({ ...formData, disposal_type: value as unknown })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="sale">Sale</SelectItem>
                    <SelectItem value="scrap">Scrap</SelectItem>
                    <SelectItem value="donation">Donation</SelectItem>
                    <SelectItem value="write_off">Write Off</SelectItem>
                    <SelectItem value="transfer">Transfer</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label>Disposal Reason</Label>
              <Textarea
                value={formData.disposal_reason}
                onChange={(e) =>
                  setFormData({ ...formData, disposal_reason: e.target.value })
                }
                placeholder="Reason for disposal"
                rows={3}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Disposal Value</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={formData.disposal_value}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      disposal_value: parseFloat(e.target.value) || 0,
                    })
                  }
                  placeholder="0.00"
                />
              </div>
              <div>
                <Label>Disposal Cost</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={formData.disposal_cost}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      disposal_cost: parseFloat(e.target.value) || 0,
                    })
                  }
                  placeholder="0.00"
                />
              </div>
            </div>
            {formData.disposal_type === 'sale' && (
              <>
                <div>
                  <Label>Buyer Name</Label>
                  <Input
                    value={formData.buyer_name}
                    onChange={(e) =>
                      setFormData({ ...formData, buyer_name: e.target.value })
                    }
                    placeholder="Buyer name"
                  />
                </div>
                <div>
                  <Label>Buyer Contact</Label>
                  <Input
                    value={formData.buyer_contact}
                    onChange={(e) =>
                      setFormData({ ...formData, buyer_contact: e.target.value })
                    }
                    placeholder="Contact information"
                  />
                </div>
                <div>
                  <Label>Disposal Method</Label>
                  <Select
                    value={formData.disposal_method}
                    onValueChange={(value) =>
                      setFormData({ ...formData, disposal_method: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select method" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="auction">Auction</SelectItem>
                      <SelectItem value="direct_sale">Direct Sale</SelectItem>
                      <SelectItem value="scrap_dealer">Scrap Dealer</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </>
            )}
            <div>
              <Label>Document URL</Label>
              <Input
                value={formData.document_url}
                onChange={(e) =>
                  setFormData({ ...formData, document_url: e.target.value })
                }
                placeholder="https://..."
              />
            </div>
            <div>
              <Label>Notes</Label>
              <Textarea
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Additional notes"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {selectedDisposal ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Disposal Details</DialogTitle>
            <DialogDescription>View disposal information</DialogDescription>
          </DialogHeader>
          {selectedDisposal && (
            <div className="space-y-4">
              <div>
                <Label className="text-muted-foreground">Disposal Number</Label>
                <p className="font-medium">{selectedDisposal.disposal_number}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Asset</Label>
                <p className="font-medium">
                  {selectedDisposal.asset_name} ({selectedDisposal.asset_number})
                </p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Disposal Type</Label>
                  <div className="mt-1">{getTypeBadge(selectedDisposal.disposal_type)}</div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Status</Label>
                  <div className="mt-1">{getStatusBadge(selectedDisposal.approval_status)}</div>
                </div>
              </div>
              <div>
                <Label className="text-muted-foreground">Disposal Date</Label>
                <p>
                  {selectedDisposal.disposal_date
                    ? new Date(selectedDisposal.disposal_date).toLocaleDateString()
                    : '-'}
                </p>
              </div>
              {selectedDisposal.disposal_reason && (
                <div>
                  <Label className="text-muted-foreground">Reason</Label>
                  <p className="whitespace-pre-wrap">{selectedDisposal.disposal_reason}</p>
                </div>
              )}
              <div className="grid grid-cols-3 gap-4">
                <div>
                  <Label className="text-muted-foreground">Disposal Value</Label>
                  <p className="font-medium">{formatCurrency(selectedDisposal.disposal_value)}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Disposal Cost</Label>
                  <p className="font-medium">{formatCurrency(selectedDisposal.disposal_cost)}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Net Proceeds</Label>
                  <p className="font-medium">{formatCurrency(selectedDisposal.net_proceeds)}</p>
                </div>
              </div>
              {selectedDisposal.buyer_name && (
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <Label className="text-muted-foreground">Buyer Name</Label>
                    <p>{selectedDisposal.buyer_name}</p>
                  </div>
                  <div>
                    <Label className="text-muted-foreground">Buyer Contact</Label>
                    <p>{selectedDisposal.buyer_contact}</p>
                  </div>
                </div>
              )}
              {selectedDisposal.notes && (
                <div>
                  <Label className="text-muted-foreground">Notes</Label>
                  <p className="whitespace-pre-wrap">{selectedDisposal.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Assets Page
 * Fixed asset management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Building2,
  Plus,
  Search,
  Loader2,
  Edit,
  Eye,
  Trash2,
  MoreVertical,
  MapPin,
  Tag,
  DollarSign,
  Calendar,
  User,
  Package,
  AlertCircle,
} from 'lucide-react';
import {
  getAssets,
  createAsset,
  updateAsset,
  getAssetCategories,
  getAssetLocations,
  type Asset,
  type AssetCategory,
  type AssetLocation,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

export default function Assets() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Assets
  const [assets, setAssets] = useState<Asset[]>([]);
  const [filteredAssets, setFilteredAssets] = useState<Asset[]>([]);
  const [selectedAsset, setSelectedAsset] = useState<Asset | null>(null);
  const [showAssetDialog, setShowAssetDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Related data
  const [categories, setCategories] = useState<AssetCategory[]>([]);
  const [locations, setLocations] = useState<AssetLocation[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [locationFilter, setLocationFilter] = useState<string>('all');

  // Asset form
  const [assetForm, setAssetForm] = useState({
    asset_number: '',
    name: '',
    description: '',
    category_id: '',
    location_id: '',
    purchase_date: '',
    purchase_cost: '',
    current_value: '',
    serial_number: '',
    model_number: '',
    manufacturer: '',
    status: 'active' as 'active' | 'maintenance' | 'disposed' | 'written_off',
    condition_status: 'good' as 'excellent' | 'good' | 'fair' | 'poor',
    warranty_start_date: '',
    warranty_end_date: '',
    notes: '',
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchAssets(),
          fetchCategories(),
          fetchLocations(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading assets data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load assets',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = assets;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(asset =>
        asset.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        asset.asset_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        asset.serial_number?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(asset => asset.status === statusFilter);
    }

    // Category filter
    if (categoryFilter !== 'all') {
      filtered = filtered.filter(asset => asset.category_id === categoryFilter);
    }

    // Location filter
    if (locationFilter !== 'all') {
      filtered = filtered.filter(asset => asset.location_id === locationFilter);
    }

    setFilteredAssets(filtered);
  }, [assets, searchTerm, statusFilter, categoryFilter, locationFilter]);

  const fetchAssets = async () => {
    try {
      setLoading(true);
      const data = await getAssets();
      setAssets(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch assets',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const data = await getAssetCategories();
      setCategories(data || []);
    } catch (error: unknown) {
      console.error('Error fetching categories:', error);
    }
  };

  const fetchLocations = async () => {
    try {
      const data = await getAssetLocations();
      setLocations(data || []);
    } catch (error: unknown) {
      console.error('Error fetching locations:', error);
    }
  };

  const handleCreateAsset = async () => {
    try {
      if (!assetForm.name || !assetForm.asset_number) {
        toast({
          title: 'Validation Error',
          description: 'Please provide asset name and number',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      const assetData: unknown = {
        ...assetForm,
        purchase_cost: assetForm.purchase_cost ? parseFloat(assetForm.purchase_cost.toString()) : 0,
        current_value: assetForm.current_value ? parseFloat(assetForm.current_value.toString()) : assetForm.purchase_cost ? parseFloat(assetForm.purchase_cost.toString()) : 0,
        category_id: assetForm.category_id || undefined,
        location_id: assetForm.location_id || undefined,
        purchase_date: assetForm.purchase_date || undefined,
        warranty_start_date: assetForm.warranty_start_date || undefined,
        warranty_end_date: assetForm.warranty_end_date || undefined,
      };

      if (isEditing && selectedAsset) {
        await updateAsset(selectedAsset.id, assetData);
        toast({
          title: 'Success',
          description: 'Asset updated successfully',
        });
      } else {
        await createAsset(assetData);
        toast({
          title: 'Success',
          description: 'Asset created successfully',
        });
      }

      setShowAssetDialog(false);
      resetForm();
      fetchAssets();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || `Failed to ${isEditing ? 'update' : 'create'} asset`,
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditAsset = (asset: Asset) => {
    setSelectedAsset(asset);
    setAssetForm({
      asset_number: asset.asset_number || '',
      name: asset.name || '',
      description: asset.description || '',
      category_id: asset.category_id || '',
      location_id: asset.location_id || '',
      purchase_date: asset.purchase_date ? asset.purchase_date.split('T')[0] : '',
      purchase_cost: typeof asset.purchase_cost === 'number' ? asset.purchase_cost.toString() : asset.purchase_cost || '',
      current_value: typeof asset.current_value === 'number' ? asset.current_value.toString() : asset.current_value || '',
      serial_number: asset.serial_number || '',
      model_number: asset.model_number || '',
      manufacturer: asset.manufacturer || '',
      status: asset.status || 'active',
      condition_status: asset.condition_status || 'good',
      warranty_start_date: asset.warranty_start_date ? asset.warranty_start_date.split('T')[0] : '',
      warranty_end_date: asset.warranty_end_date ? asset.warranty_end_date.split('T')[0] : '',
      notes: asset.notes || '',
    });
    setIsEditing(true);
    setShowAssetDialog(true);
  };

  const handleViewAsset = (asset: Asset) => {
    setSelectedAsset(asset);
    setShowViewDialog(true);
  };

  const resetForm = () => {
    setAssetForm({
      asset_number: '',
      name: '',
      description: '',
      category_id: '',
      location_id: '',
      purchase_date: '',
      purchase_cost: '',
      current_value: '',
      serial_number: '',
      model_number: '',
      manufacturer: '',
      status: 'active',
      condition_status: 'good',
      warranty_start_date: '',
      warranty_end_date: '',
      notes: '',
    });
    setSelectedAsset(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowAssetDialog(true);
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; label: string }> = {
      active: { variant: 'default', label: 'Active' },
      maintenance: { variant: 'outline', label: 'Maintenance' },
      disposed: { variant: 'secondary', label: 'Disposed' },
      written_off: { variant: 'destructive', label: 'Written Off' },
    };

    const config = statusConfig[status] || { variant: 'secondary', label: status };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  const getConditionBadge = (condition?: string) => {
    if (!condition) return null;
    const conditionConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; label: string }> = {
      excellent: { variant: 'default', label: 'Excellent' },
      good: { variant: 'default', label: 'Good' },
      fair: { variant: 'outline', label: 'Fair' },
      poor: { variant: 'destructive', label: 'Poor' },
    };

    const config = conditionConfig[condition] || { variant: 'secondary', label: condition };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  // Calculate statistics
  const totalAssets = assets.length;
  const activeAssets = assets.filter(asset => asset.status === 'active').length;
  const totalValue = assets.reduce((sum, asset) => {
    const value = typeof asset.current_value === 'number' ? asset.current_value : parseFloat(String(asset.current_value || 0));
    return sum + (isNaN(value) ? 0 : value);
  }, 0);
  const maintenanceAssets = assets.filter(asset => asset.status === 'maintenance').length;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Management</h1>
          <p className="text-muted-foreground mt-1">
            Manage fixed assets, depreciation, and maintenance
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Add Asset
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Assets</CardTitle>
            <Building2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalAssets}</div>
            <p className="text-xs text-muted-foreground">
              All assets
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active</CardTitle>
            <Package className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{activeAssets}</div>
            <p className="text-xs text-muted-foreground">
              In use
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">In Maintenance</CardTitle>
            <AlertCircle className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{maintenanceAssets}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {totalValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR' })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-4">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search assets..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="maintenance">Maintenance</SelectItem>
                  <SelectItem value="disposed">Disposed</SelectItem>
                  <SelectItem value="written_off">Written Off</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Category</Label>
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  {categories.map((category) => (
                    <SelectItem key={category.id} value={category.id}>
                      {category.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Location</Label>
              <Select value={locationFilter} onValueChange={setLocationFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All locations" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Locations</SelectItem>
                  {locations.map((location) => (
                    <SelectItem key={location.id} value={location.id}>
                      {location.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Assets Table */}
      <Card>
        <CardHeader>
          <CardTitle>Assets ({filteredAssets.length})</CardTitle>
          <CardDescription>
            Manage your fixed assets
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredAssets.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredAssets.length === 0 ? (
            <Alert>
              <AlertDescription>
                No assets found. {searchTerm || statusFilter !== 'all' || categoryFilter !== 'all' || locationFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first asset to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Asset Number</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Location</TableHead>
                    <TableHead>Purchase Cost</TableHead>
                    <TableHead>Current Value</TableHead>
                    <TableHead>Condition</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredAssets.map((asset) => (
                    <TableRow key={asset.id}>
                      <TableCell className="font-mono font-medium">{asset.asset_number}</TableCell>
                      <TableCell className="font-medium">{asset.name}</TableCell>
                      <TableCell>{asset.category_name || '-'}</TableCell>
                      <TableCell>
                        {asset.location_name ? (
                          <div className="flex items-center">
                            <MapPin className="h-3 w-3 mr-1 text-muted-foreground" />
                            {asset.location_name}
                          </div>
                        ) : (
                          '-'
                        )}
                      </TableCell>
                      <TableCell>
                        {(typeof asset.purchase_cost === 'number' ? asset.purchase_cost : parseFloat(String(asset.purchase_cost || 0))).toLocaleString('en-IN', {
                          style: 'currency',
                          currency: 'INR',
                        })}
                      </TableCell>
                      <TableCell className="font-medium">
                        {(typeof asset.current_value === 'number' ? asset.current_value : parseFloat(String(asset.current_value || 0))).toLocaleString('en-IN', {
                          style: 'currency',
                          currency: 'INR',
                        })}
                      </TableCell>
                      <TableCell>{getConditionBadge(asset.condition_status)}</TableCell>
                      <TableCell>{getStatusBadge(asset.status)}</TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewAsset(asset)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEditAsset(asset)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Asset Dialog */}
      <Dialog open={showAssetDialog} onOpenChange={setShowAssetDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Asset' : 'Add New Asset'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update asset information' : 'Create a new fixed asset record'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="asset_number">Asset Number *</Label>
                <Input
                  id="asset_number"
                  value={assetForm.asset_number}
                  onChange={(e) => setAssetForm({ ...assetForm, asset_number: e.target.value })}
                  placeholder="ASSET-001"
                  required
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="name">Asset Name *</Label>
                <Input
                  id="name"
                  value={assetForm.name}
                  onChange={(e) => setAssetForm({ ...assetForm, name: e.target.value })}
                  placeholder="Enter asset name"
                  required
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={assetForm.description}
                onChange={(e) => setAssetForm({ ...assetForm, description: e.target.value })}
                placeholder="Asset description"
                rows={3}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="category_id">Category</Label>
                <Select
                  value={assetForm.category_id}
                  onValueChange={(value) => setAssetForm({ ...assetForm, category_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">None</SelectItem>
                    {categories.map((category) => (
                      <SelectItem key={category.id} value={category.id}>
                        {category.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="location_id">Location</Label>
                <Select
                  value={assetForm.location_id}
                  onValueChange={(value) => setAssetForm({ ...assetForm, location_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select location" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">None</SelectItem>
                    {locations.map((location) => (
                      <SelectItem key={location.id} value={location.id}>
                        {location.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="purchase_date">Purchase Date</Label>
                <Input
                  id="purchase_date"
                  type="date"
                  value={assetForm.purchase_date}
                  onChange={(e) => setAssetForm({ ...assetForm, purchase_date: e.target.value })}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="purchase_cost">Purchase Cost</Label>
                <Input
                  id="purchase_cost"
                  type="number"
                  step="0.01"
                  value={assetForm.purchase_cost}
                  onChange={(e) => {
                    const value = e.target.value;
                    setAssetForm({ ...assetForm, purchase_cost: value });
                    if (!assetForm.current_value) {
                      setAssetForm(prev => ({ ...prev, current_value: value }));
                    }
                  }}
                  placeholder="0.00"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="current_value">Current Value</Label>
                <Input
                  id="current_value"
                  type="number"
                  step="0.01"
                  value={assetForm.current_value}
                  onChange={(e) => setAssetForm({ ...assetForm, current_value: e.target.value })}
                  placeholder="0.00"
                />
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="serial_number">Serial Number</Label>
                <Input
                  id="serial_number"
                  value={assetForm.serial_number}
                  onChange={(e) => setAssetForm({ ...assetForm, serial_number: e.target.value })}
                  placeholder="SN-12345"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="model_number">Model Number</Label>
                <Input
                  id="model_number"
                  value={assetForm.model_number}
                  onChange={(e) => setAssetForm({ ...assetForm, model_number: e.target.value })}
                  placeholder="Model-001"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="manufacturer">Manufacturer</Label>
                <Input
                  id="manufacturer"
                  value={assetForm.manufacturer}
                  onChange={(e) => setAssetForm({ ...assetForm, manufacturer: e.target.value })}
                  placeholder="Manufacturer name"
                />
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="status">Status</Label>
                <Select
                  value={assetForm.status}
                  onValueChange={(value: 'active' | 'maintenance' | 'disposed' | 'written_off') =>
                    setAssetForm({ ...assetForm, status: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="maintenance">Maintenance</SelectItem>
                    <SelectItem value="disposed">Disposed</SelectItem>
                    <SelectItem value="written_off">Written Off</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="condition_status">Condition</Label>
                <Select
                  value={assetForm.condition_status}
                  onValueChange={(value: 'excellent' | 'good' | 'fair' | 'poor') =>
                    setAssetForm({ ...assetForm, condition_status: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="excellent">Excellent</SelectItem>
                    <SelectItem value="good">Good</SelectItem>
                    <SelectItem value="fair">Fair</SelectItem>
                    <SelectItem value="poor">Poor</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="warranty_start_date">Warranty Start Date</Label>
                <Input
                  id="warranty_start_date"
                  type="date"
                  value={assetForm.warranty_start_date}
                  onChange={(e) => setAssetForm({ ...assetForm, warranty_start_date: e.target.value })}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="warranty_end_date">Warranty End Date</Label>
                <Input
                  id="warranty_end_date"
                  type="date"
                  value={assetForm.warranty_end_date}
                  onChange={(e) => setAssetForm({ ...assetForm, warranty_end_date: e.target.value })}
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={assetForm.notes}
                onChange={(e) => setAssetForm({ ...assetForm, notes: e.target.value })}
                placeholder="Additional notes"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAssetDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateAsset} disabled={loading || !assetForm.name || !assetForm.asset_number}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Asset
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Asset Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Asset Details</DialogTitle>
            <DialogDescription>
              View complete asset information
            </DialogDescription>
          </DialogHeader>
          {selectedAsset && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Asset Number</Label>
                  <p className="font-mono">{selectedAsset.asset_number}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Status</Label>
                  {getStatusBadge(selectedAsset.status)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Name</Label>
                  <p className="font-medium">{selectedAsset.name}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Condition</Label>
                  {getConditionBadge(selectedAsset.condition_status)}
                </div>
                {selectedAsset.category_name && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Category</Label>
                    <p>{selectedAsset.category_name}</p>
                  </div>
                )}
                {selectedAsset.location_name && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Location</Label>
                    <div className="flex items-center">
                      <MapPin className="h-4 w-4 mr-2 text-muted-foreground" />
                      <p>{selectedAsset.location_name}</p>
                    </div>
                  </div>
                )}
                {selectedAsset.purchase_date && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Purchase Date</Label>
                    <div className="flex items-center">
                      <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                      <p>{new Date(selectedAsset.purchase_date).toLocaleDateString()}</p>
                    </div>
                  </div>
                )}
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Purchase Cost</Label>
                  <p className="font-medium">
                    {(typeof selectedAsset.purchase_cost === 'number' ? selectedAsset.purchase_cost : parseFloat(String(selectedAsset.purchase_cost || 0))).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: 'INR',
                    })}
                  </p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Current Value</Label>
                  <p className="font-medium text-lg">
                    {(typeof selectedAsset.current_value === 'number' ? selectedAsset.current_value : parseFloat(String(selectedAsset.current_value || 0))).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: 'INR',
                    })}
                  </p>
                </div>
                {selectedAsset.serial_number && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Serial Number</Label>
                    <p className="font-mono">{selectedAsset.serial_number}</p>
                  </div>
                )}
                {selectedAsset.model_number && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Model Number</Label>
                    <p>{selectedAsset.model_number}</p>
                  </div>
                )}
                {selectedAsset.manufacturer && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Manufacturer</Label>
                    <p>{selectedAsset.manufacturer}</p>
                  </div>
                )}
              </div>
              {selectedAsset.description && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Description</Label>
                  <p className="text-sm text-muted-foreground">{selectedAsset.description}</p>
                </div>
              )}
              {selectedAsset.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedAsset.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
            {selectedAsset && (
              <Button onClick={() => {
                setShowViewDialog(false);
                handleEditAsset(selectedAsset);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Asset Locations Page
 * Complete asset location management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  MapPin,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Building,
  Phone,
  Mail,
} from 'lucide-react';
import {
  getAssetLocations,
  createAssetLocation,
  updateAssetLocation,
  deleteAssetLocation,
  type AssetLocation,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';

export default function AssetLocations() {
  const { toast } = useToast();
  const [locations, setLocations] = useState<AssetLocation[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterActive, setFilterActive] = useState<boolean | undefined>(undefined);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedLocation, setSelectedLocation] = useState<AssetLocation | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<AssetLocation>>({
    code: '',
    name: '',
    address: '',
    building: '',
    floor: '',
    room: '',
    contact_person: '',
    phone: '',
    email: '',
    is_active: true,
  });

  useEffect(() => {
    loadData();
  }, [filterActive]);

  const loadData = async () => {
    try {
      setLoading(true);
      const data = await getAssetLocations();
      setLocations(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load locations',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setFormData({
      code: '',
      name: '',
      address: '',
      building: '',
      floor: '',
      room: '',
      contact_person: '',
      phone: '',
      email: '',
      is_active: true,
    });
    setSelectedLocation(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (location: AssetLocation) => {
    setFormData({
      ...location,
    });
    setSelectedLocation(location);
    setIsDialogOpen(true);
  };

  const handleView = (location: AssetLocation) => {
    setSelectedLocation(location);
    setIsViewDialogOpen(true);
  };

  const handleDelete = async (location: AssetLocation) => {
    if (!confirm(`Are you sure you want to delete location "${location.name}"?`)) {
      return;
    }

    try {
      await deleteAssetLocation(location.id);
      toast({
        title: 'Success',
        description: 'Location deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete location',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.code || !formData.name) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSubmitting(true);
      if (selectedLocation) {
        await updateAssetLocation(selectedLocation.id, formData);
        toast({
          title: 'Success',
          description: 'Location updated successfully',
        });
      } else {
        await createAssetLocation(formData);
        toast({
          title: 'Success',
          description: 'Location created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save location',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const filteredLocations = locations.filter((location) => {
    const matchesSearch =
      location.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      location.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      location.address?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      location.building?.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterActive === undefined || location.is_active === filterActive;
    return matchesSearch && matchesFilter;
  });

  const stats = {
    total: locations.length,
    active: locations.filter((l) => l.is_active).length,
    inactive: locations.filter((l) => !l.is_active).length,
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Locations</h1>
          <p className="text-muted-foreground">Manage asset locations and physical addresses</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="mr-2 h-4 w-4" />
          Create Location
        </Button>
      </div>

      {/* Statistics */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Locations</CardTitle>
            <MapPin className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Locations</CardTitle>
            <Building className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{stats.active}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Inactive Locations</CardTitle>
            <MapPin className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-600">{stats.inactive}</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search locations..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <select
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
                value={filterActive === undefined ? 'all' : filterActive ? 'active' : 'inactive'}
                onChange={(e) =>
                  setFilterActive(e.target.value === 'all' ? undefined : e.target.value === 'active')
                }
              >
                <option value="all">All Status</option>
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Locations Table */}
      <Card>
        <CardHeader>
          <CardTitle>Locations List</CardTitle>
          <CardDescription>Manage all asset locations</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : filteredLocations.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No locations found. Create your first location to get started.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Code</TableHead>
                  <TableHead>Name</TableHead>
                  <TableHead>Address</TableHead>
                  <TableHead>Building/Floor/Room</TableHead>
                  <TableHead>Contact</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredLocations.map((location) => (
                  <TableRow key={location.id}>
                    <TableCell className="font-mono">{location.code}</TableCell>
                    <TableCell className="font-medium">{location.name}</TableCell>
                    <TableCell>
                      {location.address ? (
                        <div className="max-w-xs truncate" title={location.address}>
                          {location.address}
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell>
                      {location.building || location.floor || location.room ? (
                        <div className="text-sm">
                          {location.building && <div>{location.building}</div>}
                          {location.floor && <div>Floor: {location.floor}</div>}
                          {location.room && <div>Room: {location.room}</div>}
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell>
                      {location.contact_person ? (
                        <div className="text-sm">
                          <div className="font-medium">{location.contact_person}</div>
                          {location.phone && (
                            <div className="flex items-center gap-1 text-muted-foreground">
                              <Phone className="h-3 w-3" />
                              {location.phone}
                            </div>
                          )}
                          {location.email && (
                            <div className="flex items-center gap-1 text-muted-foreground">
                              <Mail className="h-3 w-3" />
                              {location.email}
                            </div>
                          )}
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge variant={location.is_active ? 'default' : 'secondary'}>
                        {location.is_active ? 'Active' : 'Inactive'}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {new Date(location.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(location)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(location)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(location)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{selectedLocation ? 'Edit Location' : 'Create Location'}</DialogTitle>
            <DialogDescription>
              {selectedLocation
                ? 'Update location details'
                : 'Create a new asset location'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="code">Code *</Label>
                  <Input
                    id="code"
                    value={formData.code || ''}
                    onChange={(e) => setFormData({ ...formData, code: e.target.value })}
                    placeholder="e.g., HQ-FLOOR1"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="name">Name *</Label>
                  <Input
                    id="name"
                    value={formData.name || ''}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., Headquarters - Floor 1"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="address">Address</Label>
                <Textarea
                  id="address"
                  value={formData.address || ''}
                  onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                  placeholder="Full address..."
                  rows={2}
                />
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="building">Building</Label>
                  <Input
                    id="building"
                    value={formData.building || ''}
                    onChange={(e) => setFormData({ ...formData, building: e.target.value })}
                    placeholder="Building name/number"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="floor">Floor</Label>
                  <Input
                    id="floor"
                    value={formData.floor || ''}
                    onChange={(e) => setFormData({ ...formData, floor: e.target.value })}
                    placeholder="Floor number"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="room">Room</Label>
                  <Input
                    id="room"
                    value={formData.room || ''}
                    onChange={(e) => setFormData({ ...formData, room: e.target.value })}
                    placeholder="Room number"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="contact_person">Contact Person</Label>
                <Input
                  id="contact_person"
                  value={formData.contact_person || ''}
                  onChange={(e) => setFormData({ ...formData, contact_person: e.target.value })}
                  placeholder="Contact person name"
                />
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="phone">Phone</Label>
                  <Input
                    id="phone"
                    type="tel"
                    value={formData.phone || ''}
                    onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                    placeholder="Phone number"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    value={formData.email || ''}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    placeholder="Email address"
                  />
                </div>
              </div>
              <div className="space-y-2 flex items-center gap-4 pt-2">
                <Label htmlFor="is_active">Active</Label>
                <Switch
                  id="is_active"
                  checked={formData.is_active}
                  onCheckedChange={(checked) =>
                    setFormData({ ...formData, is_active: checked })
                  }
                />
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedLocation ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Location Details</DialogTitle>
            <DialogDescription>View location information</DialogDescription>
          </DialogHeader>
          {selectedLocation && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Code</Label>
                  <div className="mt-1 font-mono">{selectedLocation.code}</div>
                </div>
                <div>
                  <Label>Name</Label>
                  <div className="mt-1 font-medium">{selectedLocation.name}</div>
                </div>
                {selectedLocation.address && (
                  <div className="md:col-span-2">
                    <Label>Address</Label>
                    <div className="mt-1">{selectedLocation.address}</div>
                  </div>
                )}
                {selectedLocation.building && (
                  <div>
                    <Label>Building</Label>
                    <div className="mt-1">{selectedLocation.building}</div>
                  </div>
                )}
                {selectedLocation.floor && (
                  <div>
                    <Label>Floor</Label>
                    <div className="mt-1">{selectedLocation.floor}</div>
                  </div>
                )}
                {selectedLocation.room && (
                  <div>
                    <Label>Room</Label>
                    <div className="mt-1">{selectedLocation.room}</div>
                  </div>
                )}
                {selectedLocation.contact_person && (
                  <div>
                    <Label>Contact Person</Label>
                    <div className="mt-1">{selectedLocation.contact_person}</div>
                  </div>
                )}
                {selectedLocation.phone && (
                  <div>
                    <Label>Phone</Label>
                    <div className="mt-1 flex items-center gap-2">
                      <Phone className="h-4 w-4" />
                      {selectedLocation.phone}
                    </div>
                  </div>
                )}
                {selectedLocation.email && (
                  <div>
                    <Label>Email</Label>
                    <div className="mt-1 flex items-center gap-2">
                      <Mail className="h-4 w-4" />
                      {selectedLocation.email}
                    </div>
                  </div>
                )}
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">
                    <Badge variant={selectedLocation.is_active ? 'default' : 'secondary'}>
                      {selectedLocation.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                </div>
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedLocation.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedLocation && (
              <Button
                onClick={() => {
                  setIsViewDialogOpen(false);
                  handleEdit(selectedLocation);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Asset Maintenance Page
 * Complete asset maintenance tracking interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Wrench,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Calendar,
  DollarSign,
  AlertCircle,
  CheckCircle2,
  Clock,
  XCircle,
} from 'lucide-react';
import {
  getAllMaintenance,
  createMaintenance,
  updateMaintenance,
  deleteMaintenance,
  getAssets,
  type MaintenanceRecord,
  type Asset,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function AssetMaintenance() {
  const { toast } = useToast();
  const [maintenance, setMaintenance] = useState<MaintenanceRecord[]>([]);
  const [assets, setAssets] = useState<Asset[]>([]);
  const [loading, setLoading] = useState(true);
  const [assetsLoading, setAssetsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [filterType, setFilterType] = useState<string>('all');
  const [filterPriority, setFilterPriority] = useState<string>('all');
  const [filterAsset, setFilterAsset] = useState<string>('all');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedMaintenance, setSelectedMaintenance] = useState<MaintenanceRecord | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<MaintenanceRecord>>({
    asset_id: '',
    maintenance_type: 'scheduled',
    title: '',
    description: '',
    scheduled_date: '',
    completed_date: '',
    due_date: '',
    status: 'scheduled',
    priority: 'normal',
    cost: 0,
    vendor_id: '',
    technician: '',
    technician_contact: '',
    parts_used: '',
    labor_hours: 0,
    notes: '',
    next_maintenance_date: '',
  });

  useEffect(() => {
    loadAssets();
    loadData();
  }, [filterStatus, filterType, filterPriority, filterAsset]);

  const loadAssets = async () => {
    try {
      setAssetsLoading(true);
      const data = await getAssets();
      setAssets(data);
    } catch (error: unknown) {
      console.error('Failed to load assets:', error);
    } finally {
      setAssetsLoading(false);
    }
  };

  const loadData = async () => {
    try {
      setLoading(true);
      const filters: unknown = {};
      if (filterStatus !== 'all') filters.status = filterStatus;
      if (filterType !== 'all') filters.maintenance_type = filterType;
      if (filterPriority !== 'all') filters.priority = filterPriority;
      if (filterAsset !== 'all') filters.asset_id = filterAsset;
      if (searchTerm) filters.search = searchTerm;

      const data = await getAllMaintenance(filters);
      setMaintenance(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load maintenance records',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setFormData({
      asset_id: '',
      maintenance_type: 'scheduled',
      title: '',
      description: '',
      scheduled_date: '',
      completed_date: '',
      due_date: '',
      status: 'scheduled',
      priority: 'normal',
      cost: 0,
      vendor_id: '',
      technician: '',
      technician_contact: '',
      parts_used: '',
      labor_hours: 0,
      notes: '',
      next_maintenance_date: '',
    });
    setSelectedMaintenance(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (record: MaintenanceRecord) => {
    setFormData({
      ...record,
    });
    setSelectedMaintenance(record);
    setIsDialogOpen(true);
  };

  const handleView = (record: MaintenanceRecord) => {
    setSelectedMaintenance(record);
    setIsViewDialogOpen(true);
  };

  const handleDelete = async (record: MaintenanceRecord) => {
    if (!confirm(`Are you sure you want to delete maintenance record "${record.title}"?`)) {
      return;
    }

    try {
      await deleteMaintenance(record.id);
      toast({
        title: 'Success',
        description: 'Maintenance record deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete maintenance record',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.asset_id || !formData.title) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSubmitting(true);
      if (selectedMaintenance) {
        await updateMaintenance(selectedMaintenance.id, formData);
        toast({
          title: 'Success',
          description: 'Maintenance record updated successfully',
        });
      } else {
        await createMaintenance(formData);
        toast({
          title: 'Success',
          description: 'Maintenance record created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save maintenance record',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      scheduled: 'outline',
      in_progress: 'default',
      completed: 'default',
      cancelled: 'secondary',
      overdue: 'destructive',
    };
    const icons: Record<string, unknown> = {
      scheduled: Clock,
      in_progress: AlertCircle,
      completed: CheckCircle2,
      cancelled: XCircle,
      overdue: AlertCircle,
    };
    const Icon = icons[status] || Clock;
    return (
      <Badge variant={variants[status] || 'outline'}>
        <Icon className="mr-1 h-3 w-3" />
        {status.replace('_', ' ').toUpperCase()}
      </Badge>
    );
  };

  const getPriorityBadge = (priority: string) => {
    const colors: Record<string, string> = {
      low: 'bg-gray-500',
      normal: 'bg-blue-500',
      high: 'bg-orange-500',
      urgent: 'bg-red-500',
    };
    return (
      <Badge className={colors[priority] || 'bg-gray-500'}>
        {priority.toUpperCase()}
      </Badge>
    );
  };

  const stats = {
    total: maintenance.length,
    scheduled: maintenance.filter((m) => m.status === 'scheduled').length,
    inProgress: maintenance.filter((m) => m.status === 'in_progress').length,
    completed: maintenance.filter((m) => m.status === 'completed').length,
    overdue: maintenance.filter((m) => m.status === 'overdue').length,
    totalCost: maintenance.reduce((sum, m) => {
      const cost = typeof m.cost === 'number' ? m.cost : parseFloat(String(m.cost || 0));
      return sum + (isNaN(cost) ? 0 : cost);
    }, 0),
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Maintenance</h1>
          <p className="text-muted-foreground">Track and manage asset maintenance records</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="mr-2 h-4 w-4" />
          Create Maintenance
        </Button>
      </div>

      {/* Statistics */}
      <div className="grid gap-4 md:grid-cols-5">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Records</CardTitle>
            <Wrench className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Scheduled</CardTitle>
            <Calendar className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-blue-600">{stats.scheduled}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">In Progress</CardTitle>
            <Clock className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-orange-600">{stats.inProgress}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Completed</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{stats.completed}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Cost</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              ${(typeof stats.totalCost === 'number' ? stats.totalCost : parseFloat(String(stats.totalCost || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-5">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search maintenance..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && loadData()}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Asset</Label>
              <Select value={filterAsset} onValueChange={setFilterAsset}>
                <SelectTrigger>
                  <SelectValue placeholder="All Assets" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Assets</SelectItem>
                  {assets.map((asset) => (
                    <SelectItem key={asset.id} value={asset.id}>
                      {asset.asset_number} - {asset.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={filterStatus} onValueChange={setFilterStatus}>
                <SelectTrigger>
                  <SelectValue placeholder="All Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="scheduled">Scheduled</SelectItem>
                  <SelectItem value="in_progress">In Progress</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                  <SelectItem value="overdue">Overdue</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={filterType} onValueChange={setFilterType}>
                <SelectTrigger>
                  <SelectValue placeholder="All Types" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="scheduled">Scheduled</SelectItem>
                  <SelectItem value="preventive">Preventive</SelectItem>
                  <SelectItem value="corrective">Corrective</SelectItem>
                  <SelectItem value="emergency">Emergency</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Priority</Label>
              <Select value={filterPriority} onValueChange={setFilterPriority}>
                <SelectTrigger>
                  <SelectValue placeholder="All Priorities" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Priorities</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="normal">Normal</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Maintenance Table */}
      <Card>
        <CardHeader>
          <CardTitle>Maintenance Records</CardTitle>
          <CardDescription>Manage all asset maintenance activities</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : maintenance.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No maintenance records found. Create your first maintenance record to get started.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Title</TableHead>
                  <TableHead>Asset</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Priority</TableHead>
                  <TableHead>Scheduled Date</TableHead>
                  <TableHead>Cost</TableHead>
                  <TableHead>Technician</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {maintenance.map((record) => (
                  <TableRow key={record.id}>
                    <TableCell className="font-medium">{record.title}</TableCell>
                    <TableCell>
                      {record.asset_name ? (
                        <div>
                          <div className="font-mono text-sm">{record.asset_number}</div>
                          <div className="text-sm text-muted-foreground">{record.asset_name}</div>
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{record.maintenance_type}</Badge>
                    </TableCell>
                    <TableCell>{getStatusBadge(record.status)}</TableCell>
                    <TableCell>{getPriorityBadge(record.priority)}</TableCell>
                    <TableCell>
                      {record.scheduled_date
                        ? new Date(record.scheduled_date).toLocaleDateString()
                        : '-'}
                    </TableCell>
                    <TableCell>
                      {record.cost
                        ? `$${(typeof record.cost === 'number' ? record.cost : parseFloat(String(record.cost || 0))).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
                        : '-'}
                    </TableCell>
                    <TableCell>
                      {record.technician ? (
                        <div className="text-sm">
                          <div>{record.technician}</div>
                          {record.technician_contact && (
                            <div className="text-muted-foreground">{record.technician_contact}</div>
                          )}
                        </div>
                      ) : (
                        '-'
                      )}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(record)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(record)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(record)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedMaintenance ? 'Edit Maintenance Record' : 'Create Maintenance Record'}
            </DialogTitle>
            <DialogDescription>
              {selectedMaintenance
                ? 'Update maintenance record details'
                : 'Create a new maintenance record'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="asset_id">Asset *</Label>
                  <Select
                    value={formData.asset_id || ''}
                    onValueChange={(value) => setFormData({ ...formData, asset_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select asset" />
                    </SelectTrigger>
                    <SelectContent>
                      {assets.map((asset) => (
                        <SelectItem key={asset.id} value={asset.id}>
                          {asset.asset_number} - {asset.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="title">Title *</Label>
                  <Input
                    id="title"
                    value={formData.title || ''}
                    onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                    placeholder="Maintenance title"
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="maintenance_type">Type</Label>
                  <Select
                    value={formData.maintenance_type || 'scheduled'}
                    onValueChange={(value: unknown) =>
                      setFormData({ ...formData, maintenance_type: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="scheduled">Scheduled</SelectItem>
                      <SelectItem value="preventive">Preventive</SelectItem>
                      <SelectItem value="corrective">Corrective</SelectItem>
                      <SelectItem value="emergency">Emergency</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="status">Status</Label>
                  <Select
                    value={formData.status || 'scheduled'}
                    onValueChange={(value: unknown) => setFormData({ ...formData, status: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="scheduled">Scheduled</SelectItem>
                      <SelectItem value="in_progress">In Progress</SelectItem>
                      <SelectItem value="completed">Completed</SelectItem>
                      <SelectItem value="cancelled">Cancelled</SelectItem>
                      <SelectItem value="overdue">Overdue</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="priority">Priority</Label>
                  <Select
                    value={formData.priority || 'normal'}
                    onValueChange={(value: unknown) => setFormData({ ...formData, priority: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="normal">Normal</SelectItem>
                      <SelectItem value="high">High</SelectItem>
                      <SelectItem value="urgent">Urgent</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="scheduled_date">Scheduled Date</Label>
                  <Input
                    id="scheduled_date"
                    type="date"
                    value={formData.scheduled_date || ''}
                    onChange={(e) => setFormData({ ...formData, scheduled_date: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="due_date">Due Date</Label>
                  <Input
                    id="due_date"
                    type="date"
                    value={formData.due_date || ''}
                    onChange={(e) => setFormData({ ...formData, due_date: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="completed_date">Completed Date</Label>
                  <Input
                    id="completed_date"
                    type="date"
                    value={formData.completed_date || ''}
                    onChange={(e) => setFormData({ ...formData, completed_date: e.target.value })}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="description">Description</Label>
                <Textarea
                  id="description"
                  value={formData.description || ''}
                  onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                  placeholder="Maintenance description..."
                  rows={3}
                />
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="cost">Cost</Label>
                  <Input
                    id="cost"
                    type="number"
                    step="0.01"
                    value={formData.cost || 0}
                    onChange={(e) =>
                      setFormData({ ...formData, cost: parseFloat(e.target.value) || 0 })
                    }
                    placeholder="0.00"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="labor_hours">Labor Hours</Label>
                  <Input
                    id="labor_hours"
                    type="number"
                    step="0.5"
                    value={formData.labor_hours || 0}
                    onChange={(e) =>
                      setFormData({ ...formData, labor_hours: parseFloat(e.target.value) || 0 })
                    }
                    placeholder="0.0"
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="technician">Technician</Label>
                  <Input
                    id="technician"
                    value={formData.technician || ''}
                    onChange={(e) => setFormData({ ...formData, technician: e.target.value })}
                    placeholder="Technician name"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="technician_contact">Technician Contact</Label>
                  <Input
                    id="technician_contact"
                    value={formData.technician_contact || ''}
                    onChange={(e) =>
                      setFormData({ ...formData, technician_contact: e.target.value })
                    }
                    placeholder="Phone or email"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="parts_used">Parts Used</Label>
                <Textarea
                  id="parts_used"
                  value={formData.parts_used || ''}
                  onChange={(e) => setFormData({ ...formData, parts_used: e.target.value })}
                  placeholder="List parts used..."
                  rows={2}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="notes">Notes</Label>
                <Textarea
                  id="notes"
                  value={formData.notes || ''}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={2}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="next_maintenance_date">Next Maintenance Date</Label>
                <Input
                  id="next_maintenance_date"
                  type="date"
                  value={formData.next_maintenance_date || ''}
                  onChange={(e) =>
                    setFormData({ ...formData, next_maintenance_date: e.target.value })
                  }
                />
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedMaintenance ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl">
          <DialogHeader>
            <DialogTitle>Maintenance Record Details</DialogTitle>
            <DialogDescription>View maintenance information</DialogDescription>
          </DialogHeader>
          {selectedMaintenance && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Title</Label>
                  <div className="mt-1 font-medium">{selectedMaintenance.title}</div>
                </div>
                <div>
                  <Label>Asset</Label>
                  <div className="mt-1">
                    {selectedMaintenance.asset_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedMaintenance.asset_number}</div>
                        <div className="text-sm text-muted-foreground">
                          {selectedMaintenance.asset_name}
                        </div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Type</Label>
                  <div className="mt-1">
                    <Badge variant="outline">{selectedMaintenance.maintenance_type}</Badge>
                  </div>
                </div>
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">{getStatusBadge(selectedMaintenance.status)}</div>
                </div>
                <div>
                  <Label>Priority</Label>
                  <div className="mt-1">{getPriorityBadge(selectedMaintenance.priority)}</div>
                </div>
                {selectedMaintenance.scheduled_date && (
                  <div>
                    <Label>Scheduled Date</Label>
                    <div className="mt-1">
                      {new Date(selectedMaintenance.scheduled_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {selectedMaintenance.due_date && (
                  <div>
                    <Label>Due Date</Label>
                    <div className="mt-1">
                      {new Date(selectedMaintenance.due_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {selectedMaintenance.completed_date && (
                  <div>
                    <Label>Completed Date</Label>
                    <div className="mt-1">
                      {new Date(selectedMaintenance.completed_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {selectedMaintenance.cost && (
                  <div>
                    <Label>Cost</Label>
                    <div className="mt-1">
                      $
                      {(typeof selectedMaintenance.cost === 'number'
                        ? selectedMaintenance.cost
                        : parseFloat(String(selectedMaintenance.cost || 0))
                      ).toLocaleString('en-US', {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2,
                      })}
                    </div>
                  </div>
                )}
                {selectedMaintenance.technician && (
                  <div>
                    <Label>Technician</Label>
                    <div className="mt-1">
                      <div>{selectedMaintenance.technician}</div>
                      {selectedMaintenance.technician_contact && (
                        <div className="text-sm text-muted-foreground">
                          {selectedMaintenance.technician_contact}
                        </div>
                      )}
                    </div>
                  </div>
                )}
                {selectedMaintenance.labor_hours && (
                  <div>
                    <Label>Labor Hours</Label>
                    <div className="mt-1">{selectedMaintenance.labor_hours}</div>
                  </div>
                )}
                {selectedMaintenance.description && (
                  <div className="md:col-span-2">
                    <Label>Description</Label>
                    <div className="mt-1">{selectedMaintenance.description}</div>
                  </div>
                )}
                {selectedMaintenance.parts_used && (
                  <div className="md:col-span-2">
                    <Label>Parts Used</Label>
                    <div className="mt-1">{selectedMaintenance.parts_used}</div>
                  </div>
                )}
                {selectedMaintenance.notes && (
                  <div className="md:col-span-2">
                    <Label>Notes</Label>
                    <div className="mt-1">{selectedMaintenance.notes}</div>
                  </div>
                )}
                {selectedMaintenance.next_maintenance_date && (
                  <div>
                    <Label>Next Maintenance Date</Label>
                    <div className="mt-1">
                      {new Date(selectedMaintenance.next_maintenance_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedMaintenance.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedMaintenance && (
              <Button
                onClick={() => {
                  setIsViewDialogOpen(false);
                  handleEdit(selectedMaintenance);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Asset Reports Page
 * Comprehensive asset analytics and reporting
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  BarChart3,
  TrendingUp,
  TrendingDown,
  Building2,
  DollarSign,
  Calendar,
  Download,
  RefreshCw,
  Loader2,
  Wrench,
  Trash2,
  Package,
  MapPin,
  FolderTree,
} from 'lucide-react';
import {
  getAssetReports,
  type AssetReports,
} from '@/services/api/assets';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';

export default function AssetReports() {
  const { toast } = useToast();
  const [reports, setReports] = useState<AssetReports | null>(null);
  const [loading, setLoading] = useState(true);
  const [dateFrom, setDateFrom] = useState(() => {
    const date = new Date();
    date.setDate(date.getDate() - 30);
    return date.toISOString().split('T')[0];
  });
  const [dateTo, setDateTo] = useState(() => {
    return new Date().toISOString().split('T')[0];
  });

  useEffect(() => {
    loadReports();
  }, [dateFrom, dateTo]);

  const loadReports = async () => {
    try {
      setLoading(true);
      const data = await getAssetReports({
        date_from: dateFrom,
        date_to: dateTo,
      });
      setReports(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load asset reports',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value: number | undefined) => {
    if (value === undefined || value === null) return '₹0.00';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 2,
    }).format(numValue);
  };

  const formatNumber = (value: number | undefined) => {
    if (value === undefined || value === null) return '0';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-IN').format(numValue);
  };

  const handleExport = () => {
    toast({
      title: 'Export',
      description: 'Export functionality coming soon',
    });
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      active: 'default',
      maintenance: 'secondary',
      disposed: 'destructive',
      written_off: 'outline',
    };
    return <Badge variant={variants[status] || 'secondary'}>{status}</Badge>;
  };

  if (loading && !reports) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  const summary = reports?.summary || {};
  const assetsByStatus = reports?.assets_by_status || [];
  const assetsByCategory = reports?.assets_by_category || [];
  const depreciationTrend = reports?.depreciation_trend || [];
  const maintenanceSummary = reports?.maintenance_summary || [];
  const topAssets = reports?.top_assets || [];

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Asset Reports</h1>
          <p className="text-muted-foreground">Comprehensive asset analytics and insights</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" />
            Export
          </Button>
          <Button variant="outline" onClick={loadReports}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
        </div>
      </div>

      {/* Date Range Filter */}
      <Card>
        <CardHeader>
          <CardTitle>Date Range</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4">
            <div className="flex-1">
              <Label>From Date</Label>
              <Input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
              />
            </div>
            <div className="flex-1">
              <Label>To Date</Label>
              <Input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Summary Statistics */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Assets</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatNumber(summary.total_assets)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.active_assets)} active
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Purchase Cost</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatCurrency(summary.total_purchase_cost)}</div>
            <p className="text-xs text-muted-foreground">
              Current: {formatCurrency(summary.total_current_value)}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Depreciation</CardTitle>
            <TrendingDown className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatCurrency(summary.total_depreciation)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.total_categories)} categories
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Locations</CardTitle>
            <MapPin className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatNumber(summary.total_locations)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.maintenance_assets)} in maintenance
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Detailed Reports */}
      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="status">By Status</TabsTrigger>
          <TabsTrigger value="category">By Category</TabsTrigger>
          <TabsTrigger value="depreciation">Depreciation</TabsTrigger>
          <TabsTrigger value="maintenance">Maintenance</TabsTrigger>
          <TabsTrigger value="top-assets">Top Assets</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Assets by Status</CardTitle>
              </CardHeader>
              <CardContent>
                {assetsByStatus.length === 0 ? (
                  <p className="text-muted-foreground text-center py-4">No data available</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Status</TableHead>
                        <TableHead>Count</TableHead>
                        <TableHead className="text-right">Purchase Cost</TableHead>
                        <TableHead className="text-right">Current Value</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {assetsByStatus.map((item) => (
                        <TableRow key={item.status}>
                          <TableCell>{getStatusBadge(item.status)}</TableCell>
                          <TableCell>{formatNumber(item.count)}</TableCell>
                          <TableCell className="text-right">
                            {formatCurrency(item.total_purchase_cost)}
                          </TableCell>
                          <TableCell className="text-right">
                            {formatCurrency(item.total_current_value)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Top Categories</CardTitle>
              </CardHeader>
              <CardContent>
                {assetsByCategory.length === 0 ? (
                  <p className="text-muted-foreground text-center py-4">No data available</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Category</TableHead>
                        <TableHead>Assets</TableHead>
                        <TableHead className="text-right">Total Value</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {assetsByCategory.map((item) => (
                        <TableRow key={item.id}>
                          <TableCell>
                            <div>
                              <div className="font-medium">{item.name}</div>
                              <div className="text-sm text-muted-foreground">{item.code}</div>
                            </div>
                          </TableCell>
                          <TableCell>{formatNumber(item.asset_count)}</TableCell>
                          <TableCell className="text-right">
                            {formatCurrency(item.total_current_value)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="status">
          <Card>
            <CardHeader>
              <CardTitle>Assets by Status</CardTitle>
              <CardDescription>Breakdown of assets by status</CardDescription>
            </CardHeader>
            <CardContent>
              {assetsByStatus.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No status data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Status</TableHead>
                      <TableHead>Count</TableHead>
                      <TableHead className="text-right">Purchase Cost</TableHead>
                      <TableHead className="text-right">Current Value</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {assetsByStatus.map((item) => (
                      <TableRow key={item.status}>
                        <TableCell>{getStatusBadge(item.status)}</TableCell>
                        <TableCell>{formatNumber(item.count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_purchase_cost)}
                        </TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_current_value)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="category">
          <Card>
            <CardHeader>
              <CardTitle>Assets by Category</CardTitle>
              <CardDescription>Breakdown of assets by category</CardDescription>
            </CardHeader>
            <CardContent>
              {assetsByCategory.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No category data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Category</TableHead>
                      <TableHead>Code</TableHead>
                      <TableHead>Asset Count</TableHead>
                      <TableHead className="text-right">Purchase Cost</TableHead>
                      <TableHead className="text-right">Current Value</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {assetsByCategory.map((item) => (
                      <TableRow key={item.id}>
                        <TableCell className="font-medium">{item.name}</TableCell>
                        <TableCell>{item.code}</TableCell>
                        <TableCell>{formatNumber(item.asset_count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_purchase_cost)}
                        </TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_current_value)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="depreciation">
          <Card>
            <CardHeader>
              <CardTitle>Depreciation Trends</CardTitle>
              <CardDescription>Monthly depreciation trends</CardDescription>
            </CardHeader>
            <CardContent>
              {depreciationTrend.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No depreciation data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Month</TableHead>
                      <TableHead>Records</TableHead>
                      <TableHead className="text-right">Total Depreciation</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {depreciationTrend.map((trend, index) => (
                      <TableRow key={index}>
                        <TableCell>
                          {new Date(trend.month).toLocaleDateString('en-US', {
                            month: 'long',
                            year: 'numeric',
                          })}
                        </TableCell>
                        <TableCell>{formatNumber(trend.record_count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(trend.total_depreciation)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="maintenance">
          <Card>
            <CardHeader>
              <CardTitle>Maintenance Summary</CardTitle>
              <CardDescription>Maintenance activities by type</CardDescription>
            </CardHeader>
            <CardContent>
              {maintenanceSummary.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No maintenance data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Maintenance Type</TableHead>
                      <TableHead>Count</TableHead>
                      <TableHead className="text-right">Total Cost</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {maintenanceSummary.map((item) => (
                      <TableRow key={item.maintenance_type}>
                        <TableCell className="font-medium">{item.maintenance_type}</TableCell>
                        <TableCell>{formatNumber(item.count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_cost)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="top-assets">
          <Card>
            <CardHeader>
              <CardTitle>Top Assets by Value</CardTitle>
              <CardDescription>Highest value assets</CardDescription>
            </CardHeader>
            <CardContent>
              {topAssets.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No asset data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Asset Number</TableHead>
                      <TableHead>Name</TableHead>
                      <TableHead>Category</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Purchase Cost</TableHead>
                      <TableHead className="text-right">Current Value</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {topAssets.map((asset) => (
                      <TableRow key={asset.id}>
                        <TableCell className="font-medium">{asset.asset_number}</TableCell>
                        <TableCell>{asset.name}</TableCell>
                        <TableCell>{asset.category_name || '-'}</TableCell>
                        <TableCell>{getStatusBadge(asset.status)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(asset.purchase_cost)}
                        </TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(asset.current_value)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Edit, Trash2, Phone, Mail, Calendar, Users2, FileText, CheckCircle2, XCircle, Clock, MapPin } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { fetchJson } from '@/utils/authApi';
import ActivityFormDialog from '@/components/shared/ActivityFormDialog';
import DeleteConfirmDialog from '@/components/shared/DeleteConfirmDialog';

const ActivityDetail = () => {
  const { activityId } = useParams<{ activityId: string }>();
  const navigate = useNavigate();
  const { toast } = useToast();
  const [activity, setActivity] = useState<unknown>(null);
  const [relatedLead, setRelatedLead] = useState<unknown>(null);
  const [relatedClient, setRelatedClient] = useState<unknown>(null);
  const [loading, setLoading] = useState(true);
  const [activityFormOpen, setActivityFormOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);

  useEffect(() => {
    if (activityId) {
      fetchActivityDetails();
    }
  }, [activityId]);

  const fetchActivityDetails = async () => {
    try {
      setLoading(true);
      const data = await fetchJson(`/crm/activities/${activityId}`);
      setActivity(data);

      // Fetch related lead
      if (data.lead_id) {
        try {
          const leadData = await fetchJson(`/crm/leads/${data.lead_id}`);
          setRelatedLead(leadData);
        } catch (e) {
          console.error('Error fetching related lead:', e);
        }
      }

      // Fetch related client
      if (data.client_id) {
        try {
          const clientData = await fetchJson(`/crm/clients/${data.client_id}`);
          setRelatedClient(clientData);
        } catch (e) {
          console.error('Error fetching related client:', e);
        }
      }
    } catch (error: unknown) {
      console.error('Error fetching activity:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch activity details',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = () => {
    setActivityFormOpen(true);
  };

  const handleDelete = () => {
    setDeleteDialogOpen(true);
  };

  const handleActivitySaved = () => {
    fetchActivityDetails();
    setActivityFormOpen(false);
  };

  const handleActivityDeleted = () => {
    if (relatedLead) {
      navigate(`/crm/leads/${relatedLead.id}`);
    } else {
      navigate('/crm');
    }
  };

  const getActivityIcon = (type: string) => {
    switch (type) {
      case 'call': return Phone;
      case 'email': return Mail;
      case 'meeting': return Calendar;
      case 'task': return FileText;
      case 'note': return FileText;
      default: return FileText;
    }
  };

  const getActivityStatusIcon = (status: string) => {
    switch (status) {
      case 'completed': return CheckCircle2;
      case 'in_progress': return Clock;
      case 'cancelled': return XCircle;
      default: return Clock;
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'completed': return 'bg-green-100 text-green-800';
      case 'in_progress': return 'bg-blue-100 text-blue-800';
      case 'pending': return 'bg-yellow-100 text-yellow-800';
      case 'cancelled': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!activity) {
    return (
      <div className="text-center py-8">
        <p className="text-muted-foreground">Activity not found</p>
        <Button onClick={() => navigate('/crm')} className="mt-4">
          Back to CRM
        </Button>
      </div>
    );
  }

  const ActivityIcon = getActivityIcon(activity.activity_type);
  const StatusIcon = getActivityStatusIcon(activity.status);

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col space-y-4 sm:flex-row sm:justify-between sm:items-start sm:space-y-0">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => {
            if (relatedLead) {
              navigate(`/crm/leads/${relatedLead.id}`);
            } else {
              navigate('/crm');
            }
          }}>
            <ArrowLeft className="h-4 w-4" />
          </Button>
          <div className="flex items-center gap-3">
            <ActivityIcon className="h-6 w-6 text-blue-600" />
            <div>
              <h1 className="text-2xl lg:text-3xl font-bold">{activity.subject}</h1>
              <p className="text-sm text-muted-foreground">
                {activity.activity_type} • {new Date(activity.activity_date).toLocaleString()}
              </p>
            </div>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleEdit}>
            <Edit className="h-4 w-4 mr-2" />
            Edit
          </Button>
          <Button variant="outline" onClick={handleDelete}>
            <Trash2 className="h-4 w-4 mr-2" />
            Delete
          </Button>
        </div>
      </div>

      {/* Status Badge */}
      <div className="flex gap-2">
        <Badge className={getStatusColor(activity.status)}>
          <StatusIcon className="h-3 w-3 mr-1" />
          {activity.status}
        </Badge>
        <Badge variant="outline">
          {activity.activity_type}
        </Badge>
      </div>

      {/* Main Content */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        {/* Main Information */}
        <div className="lg:col-span-2 space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Activity Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {activity.description && (
                <div>
                  <p className="text-sm text-muted-foreground mb-2">Description</p>
                  <p className="text-sm whitespace-pre-wrap">{activity.description}</p>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p className="text-sm text-muted-foreground">Activity Date</p>
                  <p className="font-medium">
                    {new Date(activity.activity_date).toLocaleString()}
                  </p>
                </div>
                {activity.due_date && (
                  <div>
                    <p className="text-sm text-muted-foreground">Due Date</p>
                    <p className="font-medium">
                      {new Date(activity.due_date).toLocaleString()}
                    </p>
                  </div>
                )}
                {activity.completed_date && (
                  <div>
                    <p className="text-sm text-muted-foreground">Completed Date</p>
                    <p className="font-medium">
                      {new Date(activity.completed_date).toLocaleString()}
                    </p>
                  </div>
                )}
                {activity.duration && (
                  <div>
                    <p className="text-sm text-muted-foreground">Duration</p>
                    <p className="font-medium">{activity.duration} minutes</p>
                  </div>
                )}
                {activity.location && (
                  <div className="flex items-center gap-2 md:col-span-2">
                    <MapPin className="h-4 w-4 text-muted-foreground" />
                    <div>
                      <p className="text-sm text-muted-foreground">Location</p>
                      <p className="font-medium">{activity.location}</p>
                    </div>
                  </div>
                )}
                {activity.outcome && (
                  <div className="md:col-span-2">
                    <p className="text-sm text-muted-foreground">Outcome</p>
                    <p className="font-medium">{activity.outcome}</p>
                  </div>
                )}
              </div>

              {activity.agenda && (
                <div>
                  <p className="text-sm text-muted-foreground mb-2">Agenda</p>
                  <p className="text-sm whitespace-pre-wrap">{activity.agenda}</p>
                </div>
              )}

              {activity.attendees && activity.attendees.length > 0 && (
                <div>
                  <p className="text-sm text-muted-foreground mb-2">Attendees</p>
                  <div className="flex flex-wrap gap-2">
                    {activity.attendees.map((attendee: string, index: number) => (
                      <Badge key={index} variant="outline">
                        <Users2 className="h-3 w-3 mr-1" />
                        {attendee}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}

              {activity.attachments && activity.attachments.length > 0 && (
                <div>
                  <p className="text-sm text-muted-foreground mb-2">Attachments</p>
                  <div className="space-y-2">
                    {activity.attachments.map((attachment: unknown, index: number) => (
                      <div key={index} className="flex items-center gap-2 p-2 border rounded">
                        <FileText className="h-4 w-4 text-muted-foreground" />
                        <span className="text-sm">{attachment.name || attachment.filename}</span>
                        {attachment.url && (
                          <Button variant="ghost" size="sm" asChild>
                            <a href={attachment.url} target="_blank" rel="noopener noreferrer">
                              View
                            </a>
                          </Button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-4">
          {relatedLead && (
            <Card>
              <CardHeader>
                <CardTitle>Related Lead</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <p className="font-semibold">{relatedLead.company_name || relatedLead.name}</p>
                  <p className="text-sm text-muted-foreground">{relatedLead.lead_number}</p>
                  <Button
                    variant="outline"
                    className="w-full"
                    onClick={() => navigate(`/crm/leads/${relatedLead.id}`)}
                  >
                    View Lead
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          {relatedClient && (
            <Card>
              <CardHeader>
                <CardTitle>Related Client</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  <p className="font-semibold">{relatedClient.name || relatedClient.company_name}</p>
                  <p className="text-sm text-muted-foreground">{relatedClient.client_number}</p>
                  <Button
                    variant="outline"
                    className="w-full"
                    onClick={() => navigate(`/clients/${relatedClient.id}`)}
                  >
                    View Client
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          <Card>
            <CardHeader>
              <CardTitle>Timeline</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <p className="text-xs text-muted-foreground">Created</p>
                <p className="text-sm font-medium">
                  {new Date(activity.created_at).toLocaleString()}
                </p>
              </div>
              <div>
                <p className="text-xs text-muted-foreground">Last Updated</p>
                <p className="text-sm font-medium">
                  {new Date(activity.updated_at).toLocaleString()}
                </p>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>

      {/* Dialogs */}
      <ActivityFormDialog
        isOpen={activityFormOpen}
        onClose={() => setActivityFormOpen(false)}
        activity={activity}
        leadId={activity.lead_id}
        onActivitySaved={handleActivitySaved}
      />

      <DeleteConfirmDialog
        isOpen={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onDeleted={handleActivityDeleted}
        itemType="Activity"
        itemName={activity.subject}
        itemId={activity.id}
        tableName="crm_activities"
      />
    </div>
  );
};

export default ActivityDetail;

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { fetchJson, fetchMutate } from '@/utils/authApi';

export const useClients = (filters?: { status?: string; search?: string }) => {
    return useQuery({
        queryKey: ['clients', filters],
        queryFn: async () => {
            const query = new URLSearchParams(filters as any).toString();
            return fetchJson(`/crm/clients${query ? `?${query}` : ''}`);
        }
    });
};

export const useClient = (id: string) => {
    return useQuery({
        queryKey: ['clients', id],
        queryFn: () => fetchJson(`/crm/clients/${id}`),
        enabled: !!id
    });
};

export const useClientMutations = () => {
    const queryClient = useQueryClient();

    const createClient = useMutation({
        mutationFn: (data: any) => fetchMutate('/crm/clients', 'POST', data),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    const updateClient = useMutation({
        mutationFn: ({ id, data }: { id: string; data: any }) => fetchMutate(`/crm/clients/${id}`, 'PUT', data),
        onSuccess: (_, variables) => {
            queryClient.invalidateQueries({ queryKey: ['clients'] });
            queryClient.invalidateQueries({ queryKey: ['clients', variables.id] });
        }
    });

    const deleteClient = useMutation({
        mutationFn: (id: string) => fetchMutate(`/crm/clients/${id}`, 'DELETE'),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['clients'] })
    });

    return { createClient, updateClient, deleteClient };
};

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Search, Filter, Edit, Trash2, Mail, Phone, MapPin, Building, Calendar, User, DollarSign, FileText, ExternalLink, TrendingUp, Activity } from "lucide-react";
import { useState, useEffect } from "react";
import { useToast } from "@/hooks/use-toast";
import { fetchJson } from '@/utils/authApi';
import DeleteConfirmDialog from "@/components/shared/DeleteConfirmDialog";
import { useAuth } from "@/hooks/useAuth";
import { getAgencyId } from "@/utils/agencyUtils";
import { RoleGuard } from "@/components/RoleGuard";
import { hasRoleOrHigher, AppRole } from "@/utils/roleUtils";
import { useNavigate } from "react-router-dom";

import { getProjectsForSelectionAuto } from "@/services/api/projects";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Progress } from "@/components/ui/progress";

const Clients = () => {
  const { toast } = useToast();
  const { user, profile, userRole } = useAuth();
  const navigate = useNavigate();
  const [clients, setClients] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTab, setSelectedTab] = useState('all');
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);
  const [selectedClient, setSelectedClient] = useState<unknown>(null);
  const [expandedClientId, setExpandedClientId] = useState<string | null>(null);
  const [clientProjects, setClientProjects] = useState<Record<string, unknown[]>>({});
  const [clientInvoices, setClientInvoices] = useState<Record<string, unknown[]>>({});
  const [clientFinancials, setClientFinancials] = useState<Record<string, unknown>>({});
  const [clientActivities, setClientActivities] = useState<Record<string, unknown[]>>({});
  const [loadingIntegration, setLoadingIntegration] = useState<Record<string, boolean>>({});
  const [clientStats, setClientStats] = useState({
    totalClients: 0,
    activeClients: 0,
    inactiveClients: 0,
    suspendedClients: 0
  });

  const canManageClients = userRole ? hasRoleOrHigher(userRole, 'manager') : false;
  const canDeleteClients = userRole ? hasRoleOrHigher(userRole, 'agency_admin') : false;

  useEffect(() => {
    fetchClients();
  }, []);

  const fetchClients = async () => {
    try {
      setLoading(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({
          title: 'Error',
          description: 'Agency context is missing. Please re-login.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      const data = await fetchJson('/crm/clients');

      setClients(data || []);
      
      // Calculate stats
      const total = data?.length || 0;
      const active = data?.filter(c => c.status === 'active').length || 0;
      const inactive = data?.filter(c => c.status === 'inactive').length || 0;
      const suspended = data?.filter(c => c.status === 'suspended').length || 0;
      
      setClientStats({
        totalClients: total,
        activeClients: active,
        inactiveClients: inactive,
        suspendedClients: suspended
      });
    } catch (error) {
      console.error('Error fetching clients:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch clients',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditClient = (client: unknown) => {
    navigate('/clients/edit/' + client.id, { state: { client } });
  };

  const handleDeleteClient = (client: unknown) => {
    setSelectedClient(client);
    setIsDeleteDialogOpen(true);
  };

  const handleClientSaved = () => {
    fetchClients();
    setSelectedClient(null);
  };

  const handleClientDeleted = () => {
    fetchClients();
    setSelectedClient(null);
  };

  const filteredClients = clients.filter(client => {
    const matchesSearch = client.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         client.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         client.phone?.includes(searchTerm) ||
                         client.contact_person?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesTab = selectedTab === 'all' || client.status === selectedTab;
    
    return matchesSearch && matchesTab;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'active': return 'default';
      case 'inactive': return 'secondary';
      case 'suspended': return 'destructive';
      default: return 'secondary';
    }
  };

  const getIndustryColor = (industry: string) => {
    switch (industry?.toLowerCase()) {
      case 'technology': return 'bg-blue-100 text-blue-800';
      case 'healthcare': return 'bg-green-100 text-green-800';
      case 'software': return 'bg-purple-100 text-purple-800';
      case 'marketing': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const loadClientIntegrationData = async (clientId: string) => {
    if (loadingIntegration[clientId]) return;
    
    setLoadingIntegration(prev => ({ ...prev, [clientId]: true }));
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) return;

      // Load projects for client
      try {
        const projects = await getProjectsForSelectionAuto(profile, user?.id, {
          clientId: clientId,
          includeInactive: false
        });
        setClientProjects(prev => ({ ...prev, [clientId]: projects }));
      } catch (error) {
        console.error('Error loading client projects:', error);
      }

      // Load invoices for client
      try {
        const invoices: any[] = [];
        setClientInvoices(prev => ({ ...prev, [clientId]: invoices }));

        setClientFinancials(prev => ({
          ...prev,
          [clientId]: {
            totalInvoiced: 0,
            totalPaid: 0,
            outstanding: 0,
            invoiceCount: 0
          }
        }));
      } catch (error) {
        console.error('Error loading client invoices:', error);
      }

      try {
        const activities = await fetchJson(`/crm/activities?clientId=${clientId}`);
        setClientActivities(prev => ({ ...prev, [clientId]: activities || [] }));
      } catch (error) {
        console.error('Error loading client activities:', error);
      }
    } catch (error) {
      console.error('Error loading client integration data:', error);
    } finally {
      setLoadingIntegration(prev => ({ ...prev, [clientId]: false }));
    }
  };

  const handleClientExpand = (clientId: string) => {
    if (expandedClientId === clientId) {
      setExpandedClientId(null);
    } else {
      setExpandedClientId(clientId);
      loadClientIntegrationData(clientId);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD'
    }).format(amount);
  };

  const ClientCard = ({ client }: { client: unknown }) => {
    const isExpanded = expandedClientId === client.id;
    const projects = clientProjects[client.id] || [];
    const invoices = clientInvoices[client.id] || [];
    const financials = clientFinancials[client.id];
    const activities = clientActivities[client.id] || [];
    const isLoading = loadingIntegration[client.id];

    return (
    <Card>
      <CardContent className="pt-6">
        <div className="flex items-start justify-between mb-4">
          <div className="flex items-start space-x-4">
            <div className="w-12 h-12 bg-primary/10 rounded-full flex items-center justify-center">
              <Building className="h-6 w-6 text-primary" />
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-3 mb-2">
                <h3 className="text-lg font-semibold">{client.name}</h3>
                <span className="text-sm text-muted-foreground">#{client.client_number}</span>
                <Badge variant={getStatusColor(client.status)}>
                  {client.status}
                </Badge>
                {client.industry && (
                  <span className={`text-xs px-2 py-1 rounded-full ${getIndustryColor(client.industry)}`}>
                    {client.industry}
                  </span>
                )}
              </div>
              
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="space-y-2">
                  {client.contact_person && (
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <User className="h-3 w-3" />
                      <span>{client.contact_person}</span>
                    </div>
                  )}
                  {client.email && (
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Mail className="h-3 w-3" />
                      <span>{client.email}</span>
                    </div>
                  )}
                  {client.phone && (
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Phone className="h-3 w-3" />
                      <span>{client.phone}</span>
                    </div>
                  )}
                  {client.address && (
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <MapPin className="h-3 w-3" />
                      <span>{client.address}</span>
                    </div>
                  )}
                </div>
                
                <div className="space-y-2">
                  {client.company_name && (
                    <div>
                      <p className="text-muted-foreground">Company</p>
                      <p className="font-medium">{client.company_name}</p>
                    </div>
                  )}
                  {client.payment_terms && (
                    <div>
                      <p className="text-muted-foreground">Payment Terms</p>
                      <p className="font-medium">{client.payment_terms} days</p>
                    </div>
                  )}
                  <div>
                    <p className="text-muted-foreground">Created</p>
                    <p className="font-medium">{new Date(client.created_at).toLocaleDateString()}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
          
          <div className="flex gap-2">
            {canManageClients && (
              <Button variant="outline" size="sm" onClick={() => handleEditClient(client)}>
                <Edit className="h-4 w-4" />
              </Button>
            )}
            {canDeleteClients && (
              <Button 
                variant="outline" 
                size="sm"
                onClick={() => handleDeleteClient(client)}
              >
                <Trash2 className="h-4 w-4" />
              </Button>
            )}
          </div>
        </div>
        <div className="mt-4 flex flex-wrap gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => handleClientExpand(client.id)}
          >
            {isExpanded ? 'Hide Details' : 'View Details'}
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => navigate(`/projects?client_id=${client.id}`)}
          >
            View Projects
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => navigate(`/invoices?client_id=${client.id}`)}
          >
            View Invoices
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => navigate(`/quotations?client_id=${client.id}`)}
          >
            View Quotations
          </Button>
        </div>

        {/* Expanded Integration Details */}
        {isExpanded && (
          <div className="mt-6 border-t pt-6">
            <Tabs defaultValue="projects" className="w-full">
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="projects">
                  Projects ({projects.length})
                </TabsTrigger>
                <TabsTrigger value="financials">
                  Financial Summary
                </TabsTrigger>
                <TabsTrigger value="activities">
                  CRM Activities ({activities.length})
                </TabsTrigger>
              </TabsList>

              <TabsContent value="projects" className="mt-4">
                {isLoading ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary mx-auto mb-2"></div>
                    <p className="text-sm text-muted-foreground">Loading projects...</p>
                  </div>
                ) : projects.length > 0 ? (
                  <div className="space-y-3">
                    {projects.map((project: unknown) => (
                      <Card key={project.id}>
                        <CardContent className="pt-4">
                          <div className="flex items-center justify-between">
                            <div className="flex-1">
                              <div className="flex items-center gap-2 mb-2">
                                <h4 className="font-semibold">{project.name}</h4>
                                {project.project_code && (
                                  <Badge variant="outline">{project.project_code}</Badge>
                                )}
                                <Badge variant={
                                  project.status === 'completed' ? 'default' :
                                  project.status === 'in_progress' ? 'secondary' :
                                  'outline'
                                }>
                                  {project.status}
                                </Badge>
                              </div>
                              <div className="flex items-center gap-4 text-sm text-muted-foreground">
                                {project.start_date && (
                                  <span>Start: {new Date(project.start_date).toLocaleDateString()}</span>
                                )}
                                {project.budget && (
                                  <span>Budget: {formatCurrency(project.budget)}</span>
                                )}
                                <span>Progress: {project.progress}%</span>
                              </div>
                              {project.progress > 0 && (
                                <Progress value={project.progress} className="mt-2 h-2" />
                              )}
                            </div>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => navigate(`/project-management/${project.id}`)}
                            >
                              View <ExternalLink className="h-3 w-3 ml-1" />
                            </Button>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <FileText className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-sm text-muted-foreground">No projects found for this client</p>
                    <Button
                      variant="outline"
                      size="sm"
                      className="mt-4"
                      onClick={() => navigate(`/project-management?client_id=${client.id}`)}
                    >
                      Create Project
                    </Button>
                  </div>
                )}
              </TabsContent>

              <TabsContent value="financials" className="mt-4">
                {isLoading ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary mx-auto mb-2"></div>
                    <p className="text-sm text-muted-foreground">Loading financial data...</p>
                  </div>
                ) : financials ? (
                  <div className="space-y-4">
                    <div className="grid grid-cols-3 gap-4">
                      <Card>
                        <CardContent className="pt-4">
                          <p className="text-sm text-muted-foreground mb-1">Total Invoiced</p>
                          <p className="text-2xl font-bold">{formatCurrency(financials.totalInvoiced)}</p>
                        </CardContent>
                      </Card>
                      <Card>
                        <CardContent className="pt-4">
                          <p className="text-sm text-muted-foreground mb-1">Total Paid</p>
                          <p className="text-2xl font-bold text-green-600">{formatCurrency(financials.totalPaid)}</p>
                        </CardContent>
                      </Card>
                      <Card>
                        <CardContent className="pt-4">
                          <p className="text-sm text-muted-foreground mb-1">Outstanding</p>
                          <p className="text-2xl font-bold text-orange-600">{formatCurrency(financials.outstanding)}</p>
                        </CardContent>
                      </Card>
                    </div>
                    
                    {invoices.length > 0 && (
                      <Card>
                        <CardHeader>
                          <CardTitle className="text-lg">Recent Invoices</CardTitle>
                        </CardHeader>
                        <CardContent>
                          <Table>
                            <TableHeader>
                              <TableRow>
                                <TableHead>Invoice #</TableHead>
                                <TableHead>Date</TableHead>
                                <TableHead>Status</TableHead>
                                <TableHead className="text-right">Amount</TableHead>
                              </TableRow>
                            </TableHeader>
                            <TableBody>
                              {invoices.slice(0, 5).map((invoice: unknown) => (
                                <TableRow key={invoice.id}>
                                  <TableCell className="font-medium">{invoice.invoice_number}</TableCell>
                                  <TableCell>{new Date(invoice.issue_date).toLocaleDateString()}</TableCell>
                                  <TableCell>
                                    <Badge variant={
                                      invoice.status === 'paid' ? 'default' :
                                      invoice.status === 'overdue' ? 'destructive' :
                                      'secondary'
                                    }>
                                      {invoice.status}
                                    </Badge>
                                  </TableCell>
                                  <TableCell className="text-right font-medium">
                                    {formatCurrency(invoice.total_amount || 0)}
                                  </TableCell>
                                </TableRow>
                              ))}
                            </TableBody>
                          </Table>
                          <div className="mt-4">
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => navigate(`/invoices?client_id=${client.id}`)}
                            >
                              View All Invoices <ExternalLink className="h-3 w-3 ml-1" />
                            </Button>
                          </div>
                        </CardContent>
                      </Card>
                    )}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <DollarSign className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-sm text-muted-foreground">No financial data available</p>
                  </div>
                )}
              </TabsContent>

              <TabsContent value="activities" className="mt-4">
                {isLoading ? (
                  <div className="text-center py-8">
                    <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-primary mx-auto mb-2"></div>
                    <p className="text-sm text-muted-foreground">Loading activities...</p>
                  </div>
                ) : activities.length > 0 ? (
                  <div className="space-y-3">
                    {activities.map((activity: unknown) => (
                      <Card key={activity.id}>
                        <CardContent className="pt-4">
                          <div className="flex items-start justify-between">
                            <div className="flex-1">
                              <div className="flex items-center gap-2 mb-2">
                                <Activity className="h-4 w-4 text-muted-foreground" />
                                <h4 className="font-semibold">{activity.title || activity.type}</h4>
                                <Badge variant="outline">{activity.type}</Badge>
                              </div>
                              {activity.description && (
                                <p className="text-sm text-muted-foreground mb-2">{activity.description}</p>
                              )}
                              <p className="text-xs text-muted-foreground">
                                {new Date(activity.created_at).toLocaleString()}
                              </p>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-8">
                    <Activity className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                    <p className="text-sm text-muted-foreground">No CRM activities found</p>
                  </div>
                )}
              </TabsContent>
            </Tabs>
          </div>
        )}
      </CardContent>
    </Card>
    );
  };

  if (loading) {
    return (
      <div className="p-6">
        <div className="flex justify-center items-center min-h-[400px]">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
            <p className="text-muted-foreground">Loading clients...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Clients</h1>
          <p className="text-muted-foreground">Manage client relationships and project details</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline">
            <Filter className="mr-2 h-4 w-4" />
            Export List
          </Button>
          {canManageClients && (
            <Button onClick={() => navigate('/clients/create')}>
              <Plus className="mr-2 h-4 w-4" />
              Add Client
            </Button>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <Building className="h-8 w-8 text-blue-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Clients</p>
                <p className="text-2xl font-bold">{clientStats.totalClients}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <FileText className="h-8 w-8 text-green-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Active Clients</p>
                <p className="text-2xl font-bold">{clientStats.activeClients}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <DollarSign className="h-8 w-8 text-purple-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Inactive Clients</p>
                <p className="text-2xl font-bold">{clientStats.inactiveClients}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <Calendar className="h-8 w-8 text-orange-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Suspended Clients</p>
                <p className="text-2xl font-bold">{clientStats.suspendedClients}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card className="mb-6">
        <CardContent className="pt-6">
          <div className="flex gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search clients..." 
                className="pl-10"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <Button variant="outline">
              <Filter className="mr-2 h-4 w-4" />
              Filter
            </Button>
          </div>
        </CardContent>
      </Card>

      <Tabs value={selectedTab} onValueChange={setSelectedTab} className="w-full">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="all">All Clients ({clientStats.totalClients})</TabsTrigger>
          <TabsTrigger value="active">Active ({clientStats.activeClients})</TabsTrigger>
          <TabsTrigger value="inactive">Inactive ({clientStats.inactiveClients})</TabsTrigger>
          <TabsTrigger value="suspended">Suspended ({clientStats.suspendedClients})</TabsTrigger>
        </TabsList>
        
        <TabsContent value={selectedTab} className="mt-6">
          {filteredClients.length === 0 ? (
            <Card>
              <CardContent className="pt-6">
                <div className="text-center py-8">
                  <Building className="mx-auto h-12 w-12 text-muted-foreground/50 mb-4" />
                  <h3 className="text-lg font-medium text-muted-foreground mb-2">No clients found</h3>
                  <p className="text-sm text-muted-foreground mb-4">
                    {searchTerm ? 'Try adjusting your search terms.' : 'Get started by adding your first client.'}
                  </p>
                  {canManageClients && (
                    <Button onClick={() => navigate('/clients/create')}>
                      <Plus className="mr-2 h-4 w-4" />
                      Add Client
                    </Button>
                  )}
                </div>
              </CardContent>
            </Card>
          ) : (
            <div className="grid gap-4">
              {filteredClients.map((client) => (
                <ClientCard key={client.id} client={client} />
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>


      <DeleteConfirmDialog
        isOpen={isDeleteDialogOpen}
        onClose={() => {
          setIsDeleteDialogOpen(false);
          setSelectedClient(null);
        }}
        onDeleted={handleClientDeleted}
        itemType="Client"
        itemName={selectedClient?.name || ''}
        itemId={selectedClient?.id || ''}
        tableName="clients"
        softDelete={true}
        userId={user?.id}
      />
    </div>
  );
};

export default Clients;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation, useParams } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { fetchJson, fetchMutate } from "@/utils/authApi";
import { generateUUID } from "@/lib/uuid";
import { useAuth } from "@/hooks/useAuth";
import { getAgencyId } from "@/utils/agencyUtils";
import { ArrowLeft, Save, Building2, User, MapPin, CreditCard, FileText, AlertCircle, UserPlus, Clock, Edit } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";

interface ClientFormData {
  name: string;
  company_name: string;
  industry: string;
  email: string;
  phone: string;
  address: string;
  city: string;
  state: string;
  postal_code: string;
  country: string;
  website: string;
  contact_person: string;
  contact_position: string;
  contact_email: string;
  contact_phone: string;
  status: string;
  billing_address: string;
  billing_city: string;
  billing_state: string;
  billing_postal_code: string;
  billing_country: string;
  tax_id: string;
  payment_terms: string;
  notes: string;
}

const DRAFT_STORAGE_KEY = 'client_form_draft';

const CreateClient: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { id } = useParams<{ id: string }>();
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(false);
  const [loadingClient, setLoadingClient] = useState(false);
  const [hasDraft, setHasDraft] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [clientId, setClientId] = useState<string | null>(id || null);
  const [creatorInfo, setCreatorInfo] = useState<{
    name: string;
    email: string;
    created_at: string;
  } | null>(null);
  const [updaterInfo, setUpdaterInfo] = useState<{
    name: string;
    email: string;
    updated_at: string;
  } | null>(null);

  const [formData, setFormData] = useState<ClientFormData>({
    name: '',
    company_name: '',
    industry: '',
    email: '',
    phone: '',
    address: '',
    city: '',
    state: '',
    postal_code: '',
    country: '',
    website: '',
    contact_person: '',
    contact_position: '',
    contact_email: '',
    contact_phone: '',
    status: 'active',
    billing_address: '',
    billing_city: '',
    billing_state: '',
    billing_postal_code: '',
    billing_country: '',
    tax_id: '',
    payment_terms: '30',
    notes: '',
  });

  // Load client data if editing
  useEffect(() => {
    const loadClient = async () => {
      if (id) {
        setLoadingClient(true);
        try {
          const agencyId = await getAgencyId(profile, user?.id);
          if (!agencyId) {
            toast({
              title: 'Error',
              description: 'Agency context is missing. Please re-login.',
              variant: 'destructive',
            });
            navigate('/clients');
            return;
          }

          const data = await fetchJson(`/crm/clients/${id}`);

          if (data) {
            setClientId(data.id);
            setFormData({
              name: data.name || '',
              company_name: data.company_name || '',
              industry: data.industry || '',
              email: data.email || '',
              phone: data.phone || '',
              address: data.address || '',
              city: data.city || '',
              state: data.state || '',
              postal_code: data.postal_code || '',
              country: data.country || '',
              website: data.website || '',
              contact_person: data.contact_person || '',
              contact_position: data.contact_position || '',
              contact_email: data.contact_email || '',
              contact_phone: data.contact_phone || '',
              status: data.status || 'active',
              billing_address: data.billing_address || '',
              billing_city: data.billing_city || '',
              billing_state: data.billing_state || '',
              billing_postal_code: data.billing_postal_code || '',
              billing_country: data.billing_country || '',
              tax_id: data.tax_id || '',
              payment_terms: data.payment_terms?.toString() || '30',
              notes: data.notes || '',
            });

            // Fetch creator information (Simplified for REST)
            if (data.created_by) {
               setCreatorInfo({
                 name: 'System User', // Provide a fallback since we don't have users/profiles endpoint yet
                 email: '',
                 created_at: data.created_at || '',
               });
            }

            // Fetch updater information (if updated_at is different from created_at)
            if (data.updated_at && data.updated_at !== data.created_at) {
              setUpdaterInfo({
                name: 'System',
                email: '',
                updated_at: data.updated_at || '',
              });
            }
          }
        } catch (error: unknown) {
          console.error('Error loading client:', error);
          toast({
            title: 'Error',
            description: error.message || 'Failed to load client',
            variant: 'destructive',
          });
          navigate('/clients');
        } finally {
          setLoadingClient(false);
        }
      }
    };

    loadClient();
  }, [id, profile, user?.id, navigate, toast]);

  // Load draft from localStorage on mount (only if not editing)
  useEffect(() => {
    if (!id) {
      const savedDraft = localStorage.getItem(DRAFT_STORAGE_KEY);
      if (savedDraft) {
        try {
          const parsed = JSON.parse(savedDraft);
          setFormData(parsed);
          setHasDraft(true);
        } catch (error) {
          console.error('Error loading draft:', error);
        }
      }
    }
  }, [id]);

  // Save draft to localStorage whenever form data changes (only if not editing)
  useEffect(() => {
    if (!id) {
      const hasData = Object.values(formData).some(value => value !== '' && value !== 'active' && value !== '30');
      if (hasData) {
        const draftData = {
          ...formData,
          timestamp: new Date().toISOString(),
        };
        localStorage.setItem(DRAFT_STORAGE_KEY, JSON.stringify(draftData));
        setHasDraft(true);
      }
    }
  }, [formData, id]);


  const clearDraft = () => {
    localStorage.removeItem(DRAFT_STORAGE_KEY);
    setHasDraft(false);
    setFormData({
      name: '',
      company_name: '',
      industry: '',
      email: '',
      phone: '',
      address: '',
      city: '',
      state: '',
      postal_code: '',
      country: '',
      website: '',
      contact_person: '',
      contact_position: '',
      contact_email: '',
      contact_phone: '',
      status: 'active',
      billing_address: '',
      billing_city: '',
      billing_state: '',
      billing_postal_code: '',
      billing_country: '',
      tax_id: '',
      payment_terms: '30',
      notes: '',
    });
  };

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {};

    if (!formData.name.trim()) {
      newErrors.name = 'Client name is required';
    }

    if (formData.email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }

    if (formData.contact_email && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.contact_email)) {
      newErrors.contact_email = 'Please enter a valid contact email address';
    }

    if (formData.website && !/^https?:\/\/.+/.test(formData.website)) {
      newErrors.website = 'Website must start with http:// or https://';
    }

    if (formData.payment_terms && isNaN(Number(formData.payment_terms))) {
      newErrors.payment_terms = 'Payment terms must be a number';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!validateForm()) {
      toast({
        title: 'Validation Error',
        description: 'Please fix the errors in the form',
        variant: 'destructive',
      });
      return;
    }

    setLoading(true);

    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({
          title: 'Error',
          description: 'Agency context is missing. Please re-login.',
          variant: 'destructive',
        });
        setLoading(false);
        return;
      }

      // Generate client number (fallback since RPC is gone)
      const clientNumberData = null;

      // Prepare data for submission
      const dataToSubmit: unknown = {
        name: formData.name.trim(),
        company_name: formData.company_name.trim() || null,
        industry: formData.industry.trim() || null,
        email: formData.email.trim() || null,
        phone: formData.phone.trim() || null,
        address: formData.address.trim() || null,
        city: formData.city.trim() || null,
        state: formData.state.trim() || null,
        postal_code: formData.postal_code.trim() || null,
        country: formData.country.trim() || null,
        website: formData.website.trim() || null,
        contact_person: formData.contact_person.trim() || null,
        contact_position: formData.contact_position.trim() || null,
        contact_email: formData.contact_email.trim() || null,
        contact_phone: formData.contact_phone.trim() || null,
        status: formData.status,
        billing_address: formData.billing_address.trim() || null,
        billing_city: formData.billing_city.trim() || null,
        billing_state: formData.billing_state.trim() || null,
        billing_postal_code: formData.billing_postal_code.trim() || null,
        billing_country: formData.billing_country.trim() || null,
        tax_id: formData.tax_id.trim() || null,
        payment_terms: formData.payment_terms && formData.payment_terms.trim() ? formData.payment_terms.trim() : null,
        notes: formData.notes.trim() || null,
      };

      if (clientId) {
        // Update existing client
        // Remove fields that shouldn't be updated
        const { id, client_number, created_by, created_at, updated_at, ...updateData } = dataToSubmit as any;
        
        const updatedClient = await fetchMutate(`/crm/clients/${clientId}`, 'PUT', updateData);

        // Update updater info after successful update
        const actualUpdatedAt = updatedClient?.updated_at || new Date().toISOString();
        setUpdaterInfo({
          name: profile?.full_name || user?.email || 'Current User',
          email: user?.email || '',
          updated_at: actualUpdatedAt,
        });

        toast({
          title: 'Success',
          description: 'Client updated successfully',
        });
      } else {
        // Insert new client
        const newClientId = generateUUID();
        const payload = {
            id: newClientId,
            ...dataToSubmit as any,
            client_number: clientNumberData || `CLT-${Date.now().toString(36).toUpperCase()}`,
            agency_id: agencyId,
            is_active: true,
            created_by: user?.id,
        };
        const insertedData = await fetchMutate('/crm/clients', 'POST', payload);

        // Clear draft on success
        clearDraft();

        // Set creator info after successful creation
        const createdAt = insertedData?.created_at || new Date().toISOString();
        setCreatorInfo({
          name: profile?.full_name || user?.email || 'Current User',
          email: user?.email || '',
          created_at: createdAt,
        });
        setClientId(newClientId);

        toast({
          title: 'Success',
          description: 'Client created successfully',
        });
      }

      // Navigate back to clients list
      navigate('/clients');
    } catch (error: unknown) {
      console.error('Error creating client:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to create client',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (field: keyof ClientFormData, value: string) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error for this field when user starts typing
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };

  const isEditing = !!clientId;

  if (loadingClient) {
    return (
      <div className="container max-w-6xl mx-auto p-6">
        <div className="flex items-center justify-center min-h-[400px]">
          <div className="text-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mx-auto mb-4"></div>
            <p className="text-muted-foreground">Loading client data...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
