                            <Clock className="h-3 w-3 inline mr-1" />
                            {new Date(updaterInfo.updated_at).toLocaleString()}
                          </p>
                        </div>
                      </div>
                    )}
                  </>
                ) : isEditing ? (
                  <div className="text-center py-2 text-muted-foreground text-xs">
                    Loading record information...
                  </div>
                ) : (
                  <div className="space-y-1">
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <UserPlus className="h-3 w-3" />
                      <span className="text-xs font-medium">Will be created by</span>
                    </div>
                    <div className="pl-5">
                      <p className="font-medium">{profile?.full_name || user?.email || 'Current User'}</p>
                      {user?.email && (
                        <p className="text-xs text-muted-foreground">{user.email}</p>
                      )}
                    </div>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>
        </div>
      </form>
    </div>
  );
};

export default CreateClient;

/**
 * Hook for activity actions (create, edit, delete)
 */

import { useState, useCallback } from 'react';

export const useActivityActions = (onActivitiesChange: () => void) => {
  const [selectedActivity, setSelectedActivity] = useState<any>(null);
  const [activityFormOpen, setActivityFormOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [activityToDelete, setActivityToDelete] = useState<any>(null);

  const handleNewActivity = useCallback((leadId?: string) => {
    setSelectedActivity(leadId ? { lead_id: leadId } : null);
    setActivityFormOpen(true);
  }, []);

  const handleEditActivity = useCallback((activity: any) => {
    setSelectedActivity(activity);
    setActivityFormOpen(true);
  }, []);

  const handleDeleteActivity = useCallback((activity: any) => {
    setActivityToDelete(activity);
    setDeleteDialogOpen(true);
  }, []);

  const handleActivitySaved = useCallback(() => {
    onActivitiesChange();
    setActivityFormOpen(false);
    setSelectedActivity(null);
  }, [onActivitiesChange]);

  const handleActivityDeleted = useCallback(() => {
    onActivitiesChange();
    setDeleteDialogOpen(false);
    setActivityToDelete(null);
  }, [onActivitiesChange]);

  return {
    selectedActivity,
    setSelectedActivity,
    activityFormOpen,
    setActivityFormOpen,
    deleteDialogOpen,
    setDeleteDialogOpen,
    activityToDelete,
    setActivityToDelete,
    handleNewActivity,
    handleEditActivity,
    handleDeleteActivity,
    handleActivitySaved,
    handleActivityDeleted,
  };
};

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { fetchJson, fetchMutate } from '@/utils/authApi';

// Leads
export const useLeads = (filters?: { status?: string; priority?: string; search?: string }) => {
    return useQuery({
        queryKey: ['crm_leads', filters],
        queryFn: async () => {
            const query = new URLSearchParams(filters as any).toString();
            return fetchJson(`/crm/leads${query ? `?${query}` : ''}`);
        }
    });
};

export const useLead = (id: string) => {
    return useQuery({
        queryKey: ['crm_leads', id],
        queryFn: () => fetchJson(`/crm/leads/${id}`),
        enabled: !!id
    });
};

export const useLeadMutations = () => {
    const queryClient = useQueryClient();

    const createLead = useMutation({
        mutationFn: (data: any) => fetchMutate('/crm/leads', 'POST', data),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_leads'] })
    });

    const updateLead = useMutation({
        mutationFn: ({ id, data }: { id: string; data: any }) => fetchMutate(`/crm/leads/${id}`, 'PUT', data),
        onSuccess: (_, variables) => {
            queryClient.invalidateQueries({ queryKey: ['crm_leads'] });
            queryClient.invalidateQueries({ queryKey: ['crm_leads', variables.id] });
        }
    });

    const deleteLead = useMutation({
        mutationFn: (id: string) => fetchMutate(`/crm/leads/${id}`, 'DELETE'),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_leads'] })
    });

    const convertLead = useMutation({
        mutationFn: (id: string) => fetchMutate(`/crm/leads/${id}/convert`, 'POST'),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_leads'] })
    });

    return { createLead, updateLead, deleteLead, convertLead };
};

// Activities
export const useActivities = (filters?: { leadId?: string; clientId?: string }) => {
    return useQuery({
        queryKey: ['crm_activities', filters],
        queryFn: async () => {
            const query = new URLSearchParams(filters as any).toString();
            return fetchJson(`/crm/activities${query ? `?${query}` : ''}`);
        }
    });
};

export const useActivityMutations = () => {
    const queryClient = useQueryClient();

    const createActivity = useMutation({
        mutationFn: (data: any) => fetchMutate('/crm/activities', 'POST', data),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_activities'] })
    });

    const updateActivity = useMutation({
        mutationFn: ({ id, data }: { id: string; data: any }) => fetchMutate(`/crm/activities/${id}`, 'PUT', data),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_activities'] })
    });

    const deleteActivity = useMutation({
        mutationFn: (id: string) => fetchMutate(`/crm/activities/${id}`, 'DELETE'),
        onSuccess: () => queryClient.invalidateQueries({ queryKey: ['crm_activities'] })
    });

    return { createActivity, updateActivity, deleteActivity };
};

// Metrics
export const useCrmMetrics = () => {
    return useQuery({
        queryKey: ['crm_metrics'],
        queryFn: () => fetchJson('/crm/metrics')
    });
};

