import { useState, useCallback } from 'react';
import { useToast } from '@/hooks/use-toast';
import { useLeadMutations } from './useCrm';

export const useLeadStatusChange = (onLeadsChange: () => void) => {
  const { toast } = useToast();
  const [draggedLead, setDraggedLead] = useState<string | null>(null);
  const { updateLead } = useLeadMutations();

  const handleLeadStatusChange = useCallback(async (leadId: string, newStatus: string) => {
    try {
      await updateLead.mutateAsync({ id: leadId, data: { status: newStatus } });

      toast({
        title: 'Success',
        description: 'Lead status updated successfully',
      });

      onLeadsChange();
    } catch (error: any) {
      console.error('Error updating lead status:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to update lead status',
        variant: 'destructive',
      });
    }
  }, [toast, onLeadsChange, updateLead]);

  const onDragStart = useCallback((e: React.DragEvent, leadId: string) => {
    setDraggedLead(leadId);
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', leadId);
    if (e.currentTarget instanceof HTMLElement) {
      e.currentTarget.style.opacity = '0.5';
    }
  }, []);

  const onDragEnd = useCallback((e: React.DragEvent) => {
    setDraggedLead(null);
    if (e.currentTarget instanceof HTMLElement) {
      e.currentTarget.style.opacity = '1';
    }
  }, []);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    e.dataTransfer.dropEffect = 'move';
    const target = e.currentTarget as HTMLElement;
    const dropZone = target.querySelector('.bg-gray-50') as HTMLElement;
    if (dropZone) {
      dropZone.classList.add('border-blue-500', 'bg-blue-50');
    }
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    const target = e.currentTarget as HTMLElement;
    const dropZone = target.querySelector('.bg-gray-50') as HTMLElement;
    if (dropZone) {
      dropZone.classList.remove('border-blue-500', 'bg-blue-50');
    }
  }, []);

  const onDrop = useCallback((e: React.DragEvent, newStatus: string, leads: any[]) => {
    e.preventDefault();
    e.stopPropagation();
    const leadId = e.dataTransfer.getData('text/plain');

    const target = e.currentTarget as HTMLElement;
    const dropZone = target.querySelector('.bg-gray-50') as HTMLElement;
    if (dropZone) {
      dropZone.classList.remove('border-blue-500', 'bg-blue-50');
    }

    if (leadId) {
      const lead = leads.find(l => l.id === leadId);
      if (lead && lead.status !== newStatus) {
        handleLeadStatusChange(leadId, newStatus);
      }
    }

    setDraggedLead(null);
  }, [handleLeadStatusChange]);

  return {
    draggedLead,
    handleLeadStatusChange,
    onDragStart,
    onDragEnd,
    onDragOver,
    onDragLeave,
    onDrop,
  };
};

/**
 * CRM Page
 * Customer Relationship Management interface
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import LeadFormDialog from '@/components/shared/LeadFormDialog';
import ActivityFormDialog from '@/components/shared/ActivityFormDialog';
import DeleteConfirmDialog from '@/components/shared/DeleteConfirmDialog';
import ConvertLeadToClientDialog from '@/components/shared/ConvertLeadToClientDialog';
import { PipelineBoard } from '@/components/crm/PipelineBoard';

// Hooks
import { useLeads } from './hooks/useLeads';
import { useActivities } from './hooks/useActivities';
import { useLeadActions } from './hooks/useLeadActions';
import { useActivityActions } from './hooks/useActivityActions';
import { useCRMFilters } from './hooks/useCRMFilters';

// Components
import { CRMMetrics } from './components/CRMMetrics';
import { CRMFilters } from './components/CRMFilters';
import { LeadsTab } from './components/LeadsTab';
import { ActivitiesTab } from './components/ActivitiesTab';
import { ReportsTab } from './components/ReportsTab';

// Utils
import { calculateCRMStats, filterLeads } from './utils/crmUtils';

const CRM = () => {
  const navigate = useNavigate();
  const { leads, loading, fetchLeads } = useLeads();
  const { activities, loading: activitiesLoading, fetchActivities } = useActivities();
  const filters = useCRMFilters();
  
  const leadActions = useLeadActions(fetchLeads);
  const activityActions = useActivityActions(fetchActivities);

  // Initial data load
  // eslint-disable-next-line react-hooks/rules-of-hooks
  useEffect(() => {
    fetchLeads();
    fetchActivities();
  }, [fetchLeads, fetchActivities]);

  // Calculate stats
  const crmStats = calculateCRMStats(leads);

  // Filter leads
  const filteredLeads = filterLeads(leads, filters.searchTerm, filters.statusFilter, filters.priorityFilter);

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col space-y-4 sm:flex-row sm:justify-between sm:items-center sm:space-y-0">
        <div>
          <h1 className="text-2xl lg:text-3xl font-bold">CRM</h1>
          <p className="text-sm lg:text-base text-muted-foreground">Manage customer relationships and sales pipeline</p>
        </div>
        <Button onClick={leadActions.handleNewLead} className="w-full sm:w-auto">
          <Plus className="h-4 w-4 mr-2" />
          New Lead
        </Button>
      </div>

      <CRMMetrics
        totalLeads={crmStats.totalLeads}
        activeLeads={crmStats.activeLeads}
        conversionRate={crmStats.conversionRate}
        pipelineValue={crmStats.pipelineValue}
      />

      <CRMFilters
        searchTerm={filters.searchTerm}
        onSearchChange={filters.setSearchTerm}
        statusFilter={filters.statusFilter}
        onStatusFilterChange={filters.setStatusFilter}
        priorityFilter={filters.priorityFilter}
        onPriorityFilterChange={filters.setPriorityFilter}
      />

      <Tabs defaultValue="leads" className="space-y-4">
        <TabsList>
          <TabsTrigger value="leads">Leads</TabsTrigger>
          <TabsTrigger value="activities">Activities</TabsTrigger>
          <TabsTrigger value="pipeline">Pipeline</TabsTrigger>
          <TabsTrigger value="reports">Reports</TabsTrigger>
        </TabsList>
        
        <TabsContent value="leads" className="space-y-4">
          <LeadsTab
            leads={filteredLeads}
            loading={loading}
            onEditLead={leadActions.handleEditLead}
            onDeleteLead={leadActions.handleDeleteLead}
            onNewActivity={activityActions.handleNewActivity}
            onConvertToClient={leadActions.handleConvertToClient}
            onCreateQuotation={leadActions.handleCreateQuotation}
          />
        </TabsContent>
        
        <TabsContent value="activities" className="space-y-4">
          <ActivitiesTab
            activities={activities}
            loading={activitiesLoading}
            onNewActivity={activityActions.handleNewActivity}
            onEditActivity={activityActions.handleEditActivity}
            onDeleteActivity={activityActions.handleDeleteActivity}
          />
        </TabsContent>
        
        <TabsContent value="pipeline" className="space-y-4">
          <PipelineBoard
            onLeadClick={(lead) => navigate(`/crm/leads/${lead.id}`)}
            onLeadEdit={leadActions.handleEditLead}
            onLeadDelete={leadActions.handleDeleteLead}
            onLeadConvert={leadActions.handleConvertToClient}
            onScheduleActivity={(lead) => activityActions.handleNewActivity(lead.id)}
            onAddLead={leadActions.handleNewLead}
          />
        </TabsContent>

        <TabsContent value="reports" className="space-y-4">
          <ReportsTab
            leads={leads}
            activities={activities}
            loading={loading}
            activitiesLoading={activitiesLoading}
          />
        </TabsContent>
      </Tabs>

      <LeadFormDialog
        isOpen={leadActions.leadFormOpen}
        onClose={() => leadActions.setLeadFormOpen(false)}
        lead={leadActions.selectedLead}
        onLeadSaved={leadActions.handleLeadSaved}
      />

      <ActivityFormDialog
        isOpen={activityActions.activityFormOpen}
        onClose={() => {
          activityActions.setActivityFormOpen(false);
          activityActions.setSelectedActivity(null);
        }}
        activity={activityActions.selectedActivity}
        leadId={activityActions.selectedActivity?.lead_id}
        onActivitySaved={activityActions.handleActivitySaved}
      />

      <DeleteConfirmDialog
        isOpen={leadActions.deleteDialogOpen}
        onClose={() => leadActions.setDeleteDialogOpen(false)}
        onDeleted={leadActions.handleLeadDeleted}
        itemType="Lead"
        itemName={leadActions.leadToDelete?.company_name || ''}
        itemId={leadActions.leadToDelete?.id || ''}
        tableName="leads"
      />

      <DeleteConfirmDialog
        isOpen={activityActions.deleteDialogOpen}
        onClose={() => activityActions.setDeleteDialogOpen(false)}
        onDeleted={activityActions.handleActivityDeleted}
        itemType="Activity"
        itemName={activityActions.activityToDelete?.subject || ''}
        itemId={activityActions.activityToDelete?.id || ''}
        tableName="crm_activities"
      />

      <ConvertLeadToClientDialog
        isOpen={leadActions.convertDialogOpen}
        onClose={() => {
          leadActions.setConvertDialogOpen(false);
          leadActions.setLeadToConvert(null);
        }}
        lead={leadActions.leadToConvert}
        onConverted={leadActions.handleLeadConverted}
      />
    </div>
  );
};

export default CRM;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Edit, Trash2, UserCheck, FileText, Calendar, Phone, Mail, MapPin, Globe, Briefcase, Building2, Tag, Plus, CheckCircle2, XCircle, Clock } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { useToast } from '@/hooks/use-toast';
import { fetchJson } from '@/utils/authApi';
import LeadFormDialog from '@/components/shared/LeadFormDialog';
import ActivityFormDialog from '@/components/shared/ActivityFormDialog';
import ConvertLeadToClientDialog from '@/components/shared/ConvertLeadToClientDialog';
import DeleteConfirmDialog from '@/components/shared/DeleteConfirmDialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Progress } from '@/components/ui/progress';

const LeadDetail = () => {
  const { leadId } = useParams<{ leadId: string }>();
  const navigate = useNavigate();
  const { toast } = useToast();
  const [lead, setLead] = useState<unknown>(null);
  const [activities, setActivities] = useState<unknown[]>([]);
  const [relatedProjects, setRelatedProjects] = useState<unknown[]>([]);
  const [relatedQuotations, setRelatedQuotations] = useState<unknown[]>([]);
  const [relatedClient, setRelatedClient] = useState<unknown>(null);
  const [loading, setLoading] = useState(true);
  const [leadFormOpen, setLeadFormOpen] = useState(false);
  const [activityFormOpen, setActivityFormOpen] = useState(false);
  const [convertDialogOpen, setConvertDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);

  useEffect(() => {
    if (leadId) {
      fetchLeadDetails();
      fetchActivities();
      fetchRelatedRecords();
    }
  }, [leadId]);

  const fetchLeadDetails = async () => {
    try {
      setLoading(true);
      const data = await fetchJson(`/crm/leads/${leadId}`);
      setLead(data);
    } catch (error: unknown) {
      console.error('Error fetching lead:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch lead details',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchActivities = async () => {
    try {
      const data = await fetchJson(`/crm/activities?leadId=${leadId}`);
      setActivities(data || []);
    } catch (error: unknown) {
      console.error('Error fetching activities:', error);
    }
  };

  const fetchRelatedRecords = async () => {
    try {
      // Fetch related client if converted
      if (lead?.converted_to_client_id) {
        try {
          const clientData = await fetchJson(`/crm/clients/${lead.converted_to_client_id}`);
          setRelatedClient(clientData);
        } catch (e) {
          console.error('Error fetching client:', e);
        }
      }

      // Fetch related projects (if client exists)
      if (lead?.converted_to_client_id) {
        try {
          const projectsData = await fetchJson(`/projects?clientId=${lead.converted_to_client_id}`);
          setRelatedProjects(projectsData || []);
        } catch (e) {
          console.error('Error fetching projects:', e);
        }
      }

      // Fetch related quotations (if client exists)
      if (lead?.converted_to_client_id) {
        try {
          const quotationsData = await fetchJson(`/quotations?clientId=${lead.converted_to_client_id}`);
          setRelatedQuotations(quotationsData || []);
        } catch (e) {
          console.error('Error fetching quotations:', e);
        }
      }
    } catch (error: unknown) {
      console.error('Error fetching related records:', error);
    }
  };

  const handleEdit = () => {
    setLeadFormOpen(true);
  };

  const handleDelete = () => {
    setDeleteDialogOpen(true);
  };

  const handleConvert = () => {
    setConvertDialogOpen(true);
  };

  const handleNewActivity = () => {
    setActivityFormOpen(true);
  };

  const handleLeadSaved = () => {
    fetchLeadDetails();
    setLeadFormOpen(false);
  };

  const handleActivitySaved = () => {
    fetchActivities();
    setActivityFormOpen(false);
  };

  const handleLeadDeleted = () => {
    navigate('/crm');
  };

  const handleLeadConverted = () => {
    fetchLeadDetails();
    fetchRelatedRecords();
    setConvertDialogOpen(false);
  };

  const handleCreateQuotation = async () => {
    try {
      if (!lead?.converted_to_client_id) {
        toast({
          title: 'Error',
          description: 'Please convert this lead to a client first',
          variant: 'destructive',
        });
        return;
      }
      navigate('/quotations', {
        state: {
          fromLead: true,
          clientId: lead.converted_to_client_id,
          leadData: lead,
        },
      });
