                      <div className="flex items-center gap-2">
                        <Globe className="h-4 w-4 text-muted-foreground" />
                        <div>
                          <p className="text-sm text-muted-foreground">Website</p>
                          <a href={lead.website} target="_blank" rel="noopener noreferrer" className="font-medium text-blue-600 hover:underline">
                            {lead.website}
                          </a>
                        </div>
                      </div>
                    )}
                    {lead.job_title && (
                      <div className="flex items-center gap-2">
                        <Briefcase className="h-4 w-4 text-muted-foreground" />
                        <div>
                          <p className="text-sm text-muted-foreground">Job Title</p>
                          <p className="font-medium">{lead.job_title}</p>
                        </div>
                      </div>
                    )}
                    {lead.industry && (
                      <div className="flex items-center gap-2">
                        <Building2 className="h-4 w-4 text-muted-foreground" />
                        <div>
                          <p className="text-sm text-muted-foreground">Industry</p>
                          <p className="font-medium">{lead.industry}</p>
                        </div>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Sales Information</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <p className="text-sm text-muted-foreground">Estimated Value</p>
                      <p className="text-xl font-semibold">
                        {lead.estimated_value || lead.value
                          ? `₹${parseFloat((lead.estimated_value || lead.value || 0).toString()).toLocaleString('en-IN', { maximumFractionDigits: 0 })}`
                          : '₹0'}
                      </p>
                    </div>
                    <div>
                      <p className="text-sm text-muted-foreground">Probability</p>
                      <div className="flex items-center gap-2">
                        <Progress value={lead.probability || 0} className="flex-1" />
                        <span className="text-sm font-medium">{lead.probability || 0}%</span>
                      </div>
                    </div>
                    {lead.expected_close_date && (
                      <div>
                        <p className="text-sm text-muted-foreground">Expected Close Date</p>
                        <p className="font-medium">
                          {new Date(lead.expected_close_date).toLocaleDateString()}
                        </p>
                      </div>
                    )}
                    {lead.due_date && (
                      <div>
                        <p className="text-sm text-muted-foreground">Due Date</p>
                        <p className="font-medium">
                          {new Date(lead.due_date).toLocaleDateString()}
                        </p>
                      </div>
                    )}
                    {lead.follow_up_date && (
                      <div>
                        <p className="text-sm text-muted-foreground">Follow-up Date</p>
                        <p className="font-medium">
                          {new Date(lead.follow_up_date).toLocaleDateString()}
                        </p>
                      </div>
                    )}
                  </div>
                </CardContent>
              </Card>

              {(lead.notes || lead.description) && (
                <Card>
                  <CardHeader>
                    <CardTitle>Notes</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <p className="text-sm whitespace-pre-wrap">{lead.notes || lead.description}</p>
                  </CardContent>
                </Card>
              )}

              {lead.tags && lead.tags.length > 0 && (
                <Card>
                  <CardHeader>
                    <CardTitle>Tags</CardTitle>
                  </CardHeader>
                  <CardContent>
                    <div className="flex flex-wrap gap-2">
                      {lead.tags.map((tag: string, index: number) => (
                        <Badge key={index} variant="outline">
                          <Tag className="h-3 w-3 mr-1" />
                          {tag}
                        </Badge>
                      ))}
                    </div>
                  </CardContent>
                </Card>
              )}
            </div>

            {/* Sidebar */}
            <div className="space-y-4">
              <Card>
                <CardHeader>
                  <CardTitle>Quick Actions</CardTitle>
                </CardHeader>
                <CardContent className="space-y-2">
                  <Button className="w-full" onClick={handleNewActivity}>
                    <Plus className="h-4 w-4 mr-2" />
                    Add Activity
                  </Button>
                  {lead.status !== 'won' && lead.status !== 'lost' && (
                    <Button variant="outline" className="w-full" onClick={handleConvert}>
                      <UserCheck className="h-4 w-4 mr-2" />
                      Convert to Client
                    </Button>
                  )}
                  {lead.converted_to_client_id && (
                    <Button variant="outline" className="w-full" onClick={handleCreateQuotation}>
                      <FileText className="h-4 w-4 mr-2" />
                      Create Quotation
                    </Button>
                  )}
                </CardContent>
              </Card>

              <Card>
                <CardHeader>
                  <CardTitle>Timeline</CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  <div>
                    <p className="text-xs text-muted-foreground">Created</p>
                    <p className="text-sm font-medium">
                      {new Date(lead.created_at).toLocaleDateString()}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs text-muted-foreground">Last Updated</p>
                    <p className="text-sm font-medium">
                      {new Date(lead.updated_at).toLocaleDateString()}
                    </p>
                  </div>
                </CardContent>
              </Card>
            </div>
          </div>
        </TabsContent>

        <TabsContent value="activities" className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-lg font-semibold">Activity Timeline</h3>
            <Button onClick={handleNewActivity}>
              <Plus className="h-4 w-4 mr-2" />
              New Activity
            </Button>
          </div>
          {activities.length === 0 ? (
            <Card>
              <CardContent className="py-8 text-center text-muted-foreground">
                No activities found. Create your first activity to get started.
              </CardContent>
            </Card>
          ) : (
            <div className="space-y-4">
              {activities.map((activity) => {
                const ActivityIcon = getActivityIcon(activity.activity_type);
                const StatusIcon = getActivityStatusIcon(activity.status);
                return (
                  <Card key={activity.id}>
                    <CardContent className="p-4">
                      <div className="flex items-start gap-4">
                        <ActivityIcon className="h-5 w-5 text-blue-600 mt-1" />
                        <div className="flex-1">
                          <div className="flex items-center justify-between">
                            <h4 className="font-semibold">{activity.subject}</h4>
                            <Badge variant={activity.status === 'completed' ? 'default' : 'secondary'}>
                              <StatusIcon className="h-3 w-3 mr-1" />
                              {activity.status}
                            </Badge>
                          </div>
                          <p className="text-sm text-muted-foreground mt-1">
                            {activity.activity_type} • {new Date(activity.activity_date).toLocaleString()}
                          </p>
                          {activity.description && (
                            <p className="text-sm mt-2">{activity.description}</p>
                          )}
                          {activity.due_date && (
                            <p className="text-xs text-muted-foreground mt-2">
                              Due: {new Date(activity.due_date).toLocaleString()}
                            </p>
                          )}
                        </div>
                        <Button
                          variant="ghost"
                          size="icon"
                          onClick={() => navigate(`/crm/activities/${activity.id}`)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          )}
        </TabsContent>

        <TabsContent value="related" className="space-y-4">
          {relatedClient && (
            <Card>
              <CardHeader>
                <CardTitle>Converted Client</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center justify-between">
                  <div>
                    <p className="font-semibold">{relatedClient.name || relatedClient.company_name}</p>
                    <p className="text-sm text-muted-foreground">{relatedClient.client_number}</p>
                  </div>
                  <Button variant="outline" onClick={() => navigate(`/clients/${relatedClient.id}`)}>
                    View Client
                  </Button>
                </div>
              </CardContent>
            </Card>
          )}

          {relatedProjects.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Related Projects ({relatedProjects.length})</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {relatedProjects.map((project) => (
                    <div key={project.id} className="flex items-center justify-between p-2 border rounded">
                      <div>
                        <p className="font-medium">{project.name}</p>
                        <p className="text-sm text-muted-foreground">{project.status}</p>
                      </div>
                      <Button variant="outline" size="sm" onClick={() => navigate(`/projects/${project.id}`)}>
                        View
                      </Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {relatedQuotations.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Related Quotations ({relatedQuotations.length})</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {relatedQuotations.map((quotation) => (
                    <div key={quotation.id} className="flex items-center justify-between p-2 border rounded">
                      <div>
                        <p className="font-medium">{quotation.title || quotation.quote_number}</p>
                        <p className="text-sm text-muted-foreground">{quotation.status}</p>
                      </div>
                      <Button variant="outline" size="sm" onClick={() => navigate(`/quotations/${quotation.id}`)}>
                        View
                      </Button>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}

          {!relatedClient && relatedProjects.length === 0 && relatedQuotations.length === 0 && (
            <Card>
              <CardContent className="py-8 text-center text-muted-foreground">
                No related records found. Convert this lead to a client to see related projects and quotations.
              </CardContent>
            </Card>
          )}
        </TabsContent>
      </Tabs>

      {/* Dialogs */}
      <LeadFormDialog
        isOpen={leadFormOpen}
        onClose={() => setLeadFormOpen(false)}
        lead={lead}
        onLeadSaved={handleLeadSaved}
      />

      <ActivityFormDialog
        isOpen={activityFormOpen}
        onClose={() => setActivityFormOpen(false)}
        leadId={leadId}
        onActivitySaved={handleActivitySaved}
      />

      <ConvertLeadToClientDialog
        isOpen={convertDialogOpen}
        onClose={() => setConvertDialogOpen(false)}
        lead={lead}
        onConverted={handleLeadConverted}
      />

      <DeleteConfirmDialog
        isOpen={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onDeleted={handleLeadDeleted}
        itemType="Lead"
        itemName={lead.company_name || lead.name}
        itemId={lead.id}
        tableName="leads"
      />
    </div>
  );
};

export default LeadDetail;

import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { useAgencyAnalytics } from '@/hooks/useAgencyAnalytics';
import { useToast } from '@/hooks/use-toast';
import { Navigate } from 'react-router-dom';
import { GridPattern, GlowOrb } from '@/components/landing/fragments';
import {
  Users,
  Building,
  DollarSign,
  FileText,
  Calendar,
  CalendarDays,
  Settings,
  BarChart3,
  Briefcase,
  UserPlus,
  FolderKanban,
  Clock,
  CheckCircle2,
  AlertCircle,
  ArrowRight,
  RefreshCw,
  Activity,
  Crown,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

type Color = 'blue' | 'emerald' | 'purple' | 'orange' | 'cyan';

const COLOR_MAP: Record<Color, { bg: string; border: string; icon: string; glow: string }> = {
  blue:    { bg: 'bg-blue-500/10',    border: 'border-blue-500/20',    icon: 'text-blue-400',    glow: 'shadow-blue-500/5' },
  emerald: { bg: 'bg-emerald-500/10', border: 'border-emerald-500/20', icon: 'text-emerald-400', glow: 'shadow-emerald-500/5' },
  purple:  { bg: 'bg-purple-500/10',  border: 'border-purple-500/20',  icon: 'text-purple-400',  glow: 'shadow-purple-500/5' },
  orange:  { bg: 'bg-orange-500/10',  border: 'border-orange-500/20',  icon: 'text-orange-400',  glow: 'shadow-orange-500/5' },
  cyan:    { bg: 'bg-cyan-500/10',    border: 'border-cyan-500/20',    icon: 'text-cyan-400',    glow: 'shadow-cyan-500/5' },
};

const StatCard = ({
  title,
  value,
  subtitle,
  icon: Icon,
  trend,
  color = 'blue',
  onClick,
}: {
  title: string;
  value: string | number;
  subtitle?: string;
  icon: React.ElementType;
  trend?: string;
  color?: Color;
  onClick?: () => void;
}) => {
  const c = COLOR_MAP[color];
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      className={cn(
        'group relative rounded-xl border bg-card p-4 transition-all duration-300 hover:border-primary/50 hover:shadow-lg',
        onClick && 'cursor-pointer',
        c.glow,
      )}
      onClick={onClick}
    >
      <div className="flex items-start justify-between mb-3">
        <div className={cn('p-2 rounded-lg', c.bg)}>
          <Icon className={cn('w-4 h-4', c.icon)} />
        </div>
        {trend && (
          <Badge variant="outline" className="text-xs border-emerald-500/20 bg-emerald-500/10 text-emerald-400">
            {trend}
          </Badge>
        )}
      </div>
      <div className="space-y-1">
        <div className="text-2xl font-semibold text-foreground font-display tracking-tight">{value}</div>
        <div className="text-xs text-muted-foreground">{title}</div>
        {subtitle && <div className="text-xs text-muted-foreground/70 mt-1">{subtitle}</div>}
      </div>
      {onClick && (
        <ArrowRight className="absolute bottom-4 right-4 w-4 h-4 text-muted-foreground opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
      )}
    </motion.div>
  );
};

const QuickActionCard = ({
  title,
  description,
  icon: Icon,
  href,
  color = 'blue',
  badge,
}: {
  title: string;
  description: string;
  icon: React.ElementType;
  href: string;
  color?: Color;
  badge?: string;
}) => {
  const navigate = useNavigate();
  const c = COLOR_MAP[color];
  return (
    <motion.div
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4 }}
      onClick={() => navigate(href)}
      className={cn(
        'group relative rounded-xl border bg-card p-5 transition-all duration-500 cursor-pointer',
        `hover:${c.border.replace('border-', 'border-')}`,
        'hover:shadow-lg hover:scale-[1.01]',
      )}
    >
      <div className="absolute inset-0 bg-gradient-to-br from-white/[0.02] to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 rounded-xl" />
      <div className="relative z-10">
        <div className="flex items-start gap-3 mb-3">
          <div className={cn('p-2.5 rounded-xl', c.bg)}>
            <Icon className={cn('w-5 h-5', c.icon)} />
          </div>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <h3 className="text-base font-semibold text-foreground font-display tracking-tight">{title}</h3>
              {badge && (
                <Badge variant="outline" className="text-[10px] px-1.5 py-0">{badge}</Badge>
              )}
            </div>
            <p className="text-xs text-muted-foreground mt-1 leading-relaxed">{description}</p>
          </div>
          <ArrowRight className="w-4 h-4 text-muted-foreground opacity-0 group-hover:opacity-100 group-hover:translate-x-1 transition-all" />
        </div>
      </div>
    </motion.div>
  );
};

const AgencyAdminDashboard = () => {
  const navigate = useNavigate();
  const { user, userRole, profile } = useAuth();
  const { agency, metrics, loading, error, refreshMetrics } = useAgencyAnalytics();
  const { toast } = useToast();
  const [lastRefresh, setLastRefresh] = useState<Date>(new Date());

  if (userRole === 'super_admin') {
    return <Navigate to="/super-admin" replace />;
  }

  useEffect(() => {
    const interval = setInterval(() => {
      refreshMetrics();
      setLastRefresh(new Date());
    }, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, [refreshMetrics]);

  const handleManualRefresh = () => {
    refreshMetrics();
    setLastRefresh(new Date());
    toast({ title: 'Dashboard Refreshed', description: 'Agency metrics have been updated.' });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[400px]">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex items-center justify-center min-h-[400px] p-4">
        <Card className="w-full max-w-md">
          <CardContent className="pt-6">
            <div className="flex flex-col items-center gap-4 text-center">
              <AlertCircle className="h-8 w-8 text-destructive" />
              <div>
                <h3 className="text-lg font-semibold mb-1">Error Loading Dashboard</h3>
                <p className="text-sm text-muted-foreground">{error}</p>
              </div>
              <Button onClick={handleManualRefresh} className="w-full">
                <RefreshCw className="mr-2 h-4 w-4" />
                Retry
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  const quickActions = [
    { title: 'Manage Team', description: 'Add, edit, and manage team members', icon: Users, href: '/employees', color: 'blue' as Color },
    { title: 'Projects', description: 'Track and manage all projects', icon: FolderKanban, href: '/projects', color: 'purple' as Color },
    { title: 'Financial Management', description: 'Invoices, expenses, and revenue', icon: DollarSign, href: '/financial-management', color: 'emerald' as Color },
    { title: 'CRM & Clients', description: 'Manage client relationships', icon: Briefcase, href: '/crm', color: 'orange' as Color },
    { title: 'Reports', description: 'View detailed reports and insights', icon: BarChart3, href: '/reports', color: 'cyan' as Color },
    { title: 'Settings', description: 'Configure agency settings', icon: Settings, href: '/settings', color: 'blue' as Color },
    { title: 'Calendar & Events', description: 'Manage events and holidays', icon: Calendar, href: '/calendar', color: 'purple' as Color },
    { title: 'Attendance', description: 'Track team attendance records', icon: Clock, href: '/attendance', color: 'emerald' as Color },
  ];

  const agencyName = agency?.name || profile?.agency_name || 'Your Agency';
  const agencyPlan = agency?.subscriptionPlan;
  const monthlyTrend = metrics.totalRevenue > 0 && metrics.monthlyRevenue > 0
    ? `${Math.round((metrics.monthlyRevenue / metrics.totalRevenue) * 100)}% of total`
    : undefined;

  return (
    <div className="relative w-full min-h-full bg-background antialiased overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none -z-10">
        <div className="relative w-full h-full">
          <GridPattern />
          <GlowOrb color="blue" size={300} className="top-[10%] right-[5%] opacity-15" blur={60} />
          <GlowOrb color="emerald" size={250} className="bottom-[10%] right-[5%] opacity-15" blur={60} />
          <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_center,transparent_0%,rgba(0,0,0,0.15)_100%)]" />
        </div>
      </div>

      <div className="relative z-10 w-full space-y-6">
        {/* Header */}
        <section className="w-full">
          <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4 mb-6">
            <div>
              <motion.div
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6 }}
                className="flex items-center gap-3 mb-1"
              >
                <h1 className="text-2xl sm:text-3xl md:text-4xl font-display font-semibold text-foreground leading-[1.1] tracking-[-0.02em]">
                  {agencyName}
                </h1>
                {agencyPlan && (
                  <Badge variant="outline" className="border-purple-500/20 bg-purple-500/10 text-purple-400 capitalize gap-1">
                    <Crown className="w-3 h-3" />
                    {agencyPlan}
                  </Badge>
                )}
              </motion.div>
              <motion.p
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.6, delay: 0.1 }}
                className="text-sm sm:text-base text-muted-foreground"
              >
                Welcome back, {profile?.first_name || user?.email?.split('@')[0] || 'Admin'} — here's your agency overview
              </motion.p>
            </div>
            <div className="flex items-center gap-3">
              <div className="text-xs text-muted-foreground hidden sm:block">
                Updated: {lastRefresh.toLocaleTimeString()}
              </div>
              <Button onClick={handleManualRefresh} variant="outline" size="sm" disabled={loading}>
                <RefreshCw className={cn('mr-2 h-4 w-4', loading && 'animate-spin')} />
                Refresh
              </Button>
            </div>
          </div>

          {/* Key Stats */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            <StatCard
              title="Total Users"
              value={metrics.totalUsers}
              subtitle={`${metrics.activeUsers} active`}
              icon={Users}
              color="blue"
              onClick={() => navigate('/employees')}
            />
            <StatCard
              title="Projects"
              value={metrics.totalProjects}
              subtitle={`${metrics.activeProjects} active`}
              icon={Building}
              color="purple"
              onClick={() => navigate('/projects')}
            />
            <StatCard
              title="Total Revenue"
              value={`$${metrics.totalRevenue.toLocaleString()}`}
              subtitle={`$${metrics.monthlyRevenue.toLocaleString()} this month`}
              icon={DollarSign}
              color="emerald"
              trend={monthlyTrend}
              onClick={() => navigate('/financial-management')}
            />
            <StatCard
              title="Invoices"
              value={metrics.totalInvoices}
              subtitle={`${metrics.totalClients} clients`}
              icon={FileText}
              color="orange"
              onClick={() => navigate('/financial-management')}
            />
          </div>
        </section>

        {/* Quick Actions */}
        <section className="w-full">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="mb-6"
          >
            <h2 className="text-2xl font-semibold text-foreground font-display tracking-tight mb-2">Quick Actions</h2>
            <p className="text-sm text-muted-foreground">Access all your agency management tools</p>
          </motion.div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {quickActions.map((action) => (
              <QuickActionCard key={action.href} {...action} />
            ))}
          </div>
        </section>

        {/* Activity & Status */}
        <section className="w-full">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Recent Activity */}
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.3 }}
              className="lg:col-span-2 rounded-xl border bg-card p-6"
            >
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-semibold text-foreground font-display">Recent Activity (30 days)</h3>
                <Activity className="w-5 h-5 text-muted-foreground" />
              </div>
              <div className="space-y-4">
