          />
        </>
      )}

      {/* Lock/Unlock Button */}
      <div className="absolute top-2 right-2 z-10">
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0"
          onClick={(e) => {
            e.stopPropagation();
            onToggleLock(dept.id);
          }}
          title={isLocked ? "Unlock node" : "Lock node"}
        >
          {isLocked ? (
            <Lock className="h-3 w-3" />
