        {/* Stats */}
        <div className="flex items-center gap-2 flex-wrap mt-1">
          <Badge variant="secondary" className="text-xs px-1.5 py-0">
            <Users className="h-2.5 w-2.5 mr-1" />
            {dept._count?.team_assignments || 0}
