                    <p className="text-xs text-muted-foreground text-center">
                      +{members.length - 2} more
                    </p>
                  )}
                </div>
              </div>
            ) : (
              <p className="text-xs text-muted-foreground text-center py-1">
                No members
              </p>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

