// Department Hierarchy Tree Component
interface DepartmentHierarchyViewProps {
  departments: Department[];
  expandedDepartments: Set<string>;
  setExpandedDepartments: (set: Set<string> | ((prev: Set<string>) => Set<string>)) => void;
  departmentMembers: Record<string, Array<{
    id: string;
    full_name: string;
    position_title?: string;
    role_in_department: string;
  }>>;
  setDepartmentMembers: (members: Record<string, Array<{
    id: string;
    full_name: string;
    position_title?: string;
    role_in_department: string;
  }>>) => void;
  onDepartmentClick: (dept: Department) => void;
  db: unknown;
  onRefresh?: () => void;
}

export const DepartmentHierarchyView: React.FC<DepartmentHierarchyViewProps> = ({
  departments,
  expandedDepartments,
  setExpandedDepartments,
  departmentMembers,
  setDepartmentMembers,
  onDepartmentClick,
  db,
  onRefresh,
}) => {
  const { toast } = useToast();
  const [loadingMembers, setLoadingMembers] = useState<Set<string>>(new Set());
  const reactFlowInstance = useRef<unknown>(null);
  const [connectionMode, setConnectionMode] = useState(false);
  const [lockedNodes, setLockedNodes] = useState<Set<string>>(new Set());
  const [pendingConnections, setPendingConnections] = useState<Map<string, string>>(new Map());
  const [isSaving, setIsSaving] = useState(false);
  const [showInactiveDepartments, setShowInactiveDepartments] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [filterManager, setFilterManager] = useState<string>("all");
  const [showStats, setShowStats] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(1);

  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // Filter departments
  const filteredDepartments = useMemo(() => {
    let filtered = showInactiveDepartments 
      ? departments 
      : departments.filter(d => d.is_active);
    
    if (searchTerm.trim()) {
      filtered = filtered.filter(dept => 
        dept.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        dept.description?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        dept.manager?.full_name.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }
    
    if (filterManager !== "all") {
      filtered = filtered.filter(dept => dept.manager_id === filterManager);
    }
    
    return filtered;
  }, [departments, showInactiveDepartments, searchTerm, filterManager]);

  // Simple layout: organize by levels
  const buildHierarchy = useCallback(() => {
    if (filteredDepartments.length === 0) {
      setNodes([]);
      setEdges([]);
      return;
    }

    const HORIZONTAL_SPACING = 200;
    const VERTICAL_SPACING = 180;
    const START_Y = 50;
    const CARD_WIDTH = 220;

    // Build parent-child map
    const childrenMap = new Map<string, Department[]>();
    const parentMap = new Map<string, string>();
    
    filteredDepartments.forEach(dept => {
      if (dept.parent_department_id && dept.parent_department_id.trim() !== "") {
        const parentId = dept.parent_department_id;
        if (!childrenMap.has(parentId)) {
          childrenMap.set(parentId, []);
        }
        childrenMap.get(parentId)!.push(dept);
        parentMap.set(dept.id, parentId);
      }
    });

    // Find root departments (no parent or parent not in filtered list)
    const roots = filteredDepartments.filter(dept => {
      if (!dept.parent_department_id || dept.parent_department_id.trim() === "") {
        return true;
      }
      return !filteredDepartments.some(d => d.id === dept.parent_department_id);
    });

    // Calculate levels
    const getLevel = (deptId: string, visited = new Set<string>()): number => {
      if (visited.has(deptId)) return 0; // Cycle protection
      visited.add(deptId);
      
      const parentId = parentMap.get(deptId);
      if (!parentId || !filteredDepartments.some(d => d.id === parentId)) {
        return 0;
      }
      return getLevel(parentId, visited) + 1;
    };

    // Group by level
    const levelMap = new Map<number, Department[]>();
    filteredDepartments.forEach(dept => {
      const level = getLevel(dept.id);
      if (!levelMap.has(level)) {
        levelMap.set(level, []);
      }
      levelMap.get(level)!.push(dept);
    });

    // Position nodes by level
    const nodePositions = new Map<string, { x: number; y: number }>();
    const maxLevel = Math.max(...Array.from(levelMap.keys()));

    for (let level = 0; level <= maxLevel; level++) {
      const levelDepts = levelMap.get(level) || [];
      const levelWidth = levelDepts.length * (CARD_WIDTH + HORIZONTAL_SPACING) - HORIZONTAL_SPACING;
      let currentX = -levelWidth / 2;

      levelDepts.forEach(dept => {
        const y = START_Y + (level * VERTICAL_SPACING);
        nodePositions.set(dept.id, { x: currentX, y });
        currentX += CARD_WIDTH + HORIZONTAL_SPACING;
      });
    }

    // Create nodes
    const newNodes: Node[] = filteredDepartments.map(dept => {
      const pos = nodePositions.get(dept.id) || { x: 0, y: 0 };
      const hasChildren = childrenMap.has(dept.id);
      const isExpanded = expandedDepartments.has(dept.id);
      const members = departmentMembers[dept.id] || [];
      const isLoading = loadingMembers.has(dept.id);
      const level = getLevel(dept.id);

      return {
        id: dept.id,
        type: 'department',
        position: pos,
        data: {
          dept,
          level,
          onDepartmentClick,
          onExpand: (id: string) => {
            setExpandedDepartments(prev => {
              const next = new Set(prev);
              if (next.has(id)) {
                next.delete(id);
              } else {
                next.add(id);
                fetchDepartmentMembers(id);
              }
              return next;
            });
          },
          isExpanded,
          hasChildren,
          members,
          isLoading,
          isLocked: lockedNodes.has(dept.id),
          onToggleLock: (id: string) => {
            setLockedNodes(prev => {
              const next = new Set(prev);
              if (next.has(id)) {
                next.delete(id);
              } else {
                next.add(id);
              }
              return next;
            });
          },
          connectionMode,
        },
        sourcePosition: Position.Bottom,
        targetPosition: Position.Top,
        draggable: !lockedNodes.has(dept.id),
      };
    });

    // Create edges
    const newEdges: Edge[] = [];
    filteredDepartments.forEach(dept => {
      if (dept.parent_department_id && filteredDepartments.some(d => d.id === dept.parent_department_id)) {
        newEdges.push({
          id: `edge-${dept.parent_department_id}-${dept.id}`,
          source: dept.parent_department_id,
          target: dept.id,
          type: 'smoothstep',
          animated: true,
          style: { 
            stroke: '#3b82f6',
            strokeWidth: 2,
          },
          markerEnd: {
            type: MarkerType.ArrowClosed,
            color: '#3b82f6',
            width: 20,
            height: 20,
          },
        });
      }
    });

    setNodes(newNodes);
    setEdges(newEdges);
  }, [filteredDepartments, expandedDepartments, departmentMembers, loadingMembers, lockedNodes, connectionMode, onDepartmentClick, setExpandedDepartments]);

  // Fetch department members
  const fetchDepartmentMembers = useCallback(async (departmentId: string) => {
    if (departmentMembers[departmentId]) return;
    
    setLoadingMembers(prev => new Set(prev).add(departmentId));
    try {
      const { data: assignmentsData, error: assignmentsError } = await db
        .from("team_assignments")
        .select("id, user_id, position_title, role_in_department")
        .eq("department_id", departmentId)
        .eq("is_active", true);

      if (assignmentsError) throw assignmentsError;

      if (!assignmentsData || assignmentsData.length === 0) {
        setDepartmentMembers((prev: Record<string, { id: string; full_name: string; position_title?: string; role_in_department: string; }[]>) => ({ ...prev, [departmentId]: [] }));
        return;
      }

      const userIds = assignmentsData.map((ta: unknown) => ta.user_id);
      const { data: profilesData, error: profilesError } = await db
        .from("profiles")
        .select("user_id, full_name")
        .in("user_id", userIds);

      if (profilesError) throw profilesError;

      const profileMap = new Map((profilesData || []).map((p: unknown) => [p.user_id, p.full_name]));
      
      const members = assignmentsData.map((ta: unknown) => ({
        id: ta.id,
        full_name: profileMap.get(ta.user_id) || "Unknown",
        position_title: ta.position_title,
        role_in_department: ta.role_in_department,
      }));

      setDepartmentMembers((prev: Record<string, { id: string; full_name: string; position_title?: string; role_in_department: string; }[]>) => ({ ...prev, [departmentId]: members }));
    } catch (error: unknown) {
      console.error("Error fetching members:", error);
      toast({
        title: "Error",
        description: "Failed to fetch department members",
        variant: "destructive",
      });
    } finally {
      setLoadingMembers(prev => {
        const next = new Set(prev);
        next.delete(departmentId);
        return next;
      });
    }
  }, [departmentMembers, db, toast, setDepartmentMembers]);

  // Build hierarchy when dependencies change
  useEffect(() => {
    buildHierarchy();
  }, [buildHierarchy]);

  // Auto-expand on initial load
  useEffect(() => {
    if (departments.length > 0 && expandedDepartments.size === 0) {
      setExpandedDepartments(new Set(departments.map(d => d.id)));
    }
  }, [departments, expandedDepartments.size, setExpandedDepartments]);

  // Handle connections
  const onConnect = useCallback((params: Connection) => {
    if (!params.source || !params.target) return;
    
    if (params.source === params.target) {
      toast({
        title: "Invalid Connection",
        description: "A department cannot be connected to itself",
        variant: "destructive",
      });
      return;
    }

    const targetDept = departments.find(d => d.id === params.target);
    if (targetDept?.parent_department_id && targetDept.parent_department_id !== params.source) {
      toast({
        title: "Connection Exists",
        description: "This department already has a parent. Remove the existing connection first.",
        variant: "destructive",
      });
      return;
    }

    setPendingConnections(prev => {
      const next = new Map(prev);
      next.set(params.target!, params.source!);
      return next;
    });

    // Add edge immediately
    const newEdge: Edge = {
      id: `edge-${params.source}-${params.target}`,
      source: params.source,
      target: params.target,
      type: 'smoothstep',
      animated: true,
      style: { 
        stroke: '#3b82f6',
        strokeWidth: 2,
        strokeDasharray: '5,5',
      },
      markerEnd: {
        type: MarkerType.ArrowClosed,
        color: '#3b82f6',
        width: 20,
        height: 20,
      },
    };

    setEdges(prev => addEdge(newEdge, prev));
  }, [departments, toast, setEdges]);

  // Handle edge deletion
  const onEdgesDelete = useCallback((deletedEdges: Edge[]) => {
    deletedEdges.forEach(edge => {
      setPendingConnections(prev => {
        const next = new Map(prev);
        next.delete(edge.target);
        return next;
      });
    });
  }, []);

  // Save connections
  const saveConnections = useCallback(async () => {
    if (pendingConnections.size === 0) {
      toast({
        title: "No Changes",
        description: "No new connections to save",
      });
      return;
    }

    setIsSaving(true);
    try {
      const updates = Array.from(pendingConnections.entries()).map(async ([childId, parentId]) => {
        const { error } = await db
          .from("departments")
          .update({ parent_department_id: parentId })
          .eq("id", childId);
        if (error) throw error;
      });

      await Promise.all(updates);

      // Convert dashed edges to solid
      setEdges(prevEdges => prevEdges.map(edge => {
        if (pendingConnections.has(edge.target)) {
          return {
            ...edge,
            style: {
              ...edge.style,
              strokeDasharray: undefined,
            },
          };
        }
        return edge;
      }));

      toast({
        title: "Success",
        description: `Saved ${pendingConnections.size} connection(s) successfully`,
      });

      setPendingConnections(new Map());
      
      if (onRefresh) {
        onRefresh();
      }
    } catch (error: unknown) {
      console.error("Error saving connections:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to save connections",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  }, [pendingConnections, db, toast, onRefresh, setEdges]);

  // Statistics
  const stats = useMemo(() => ({
    total: departments.length,
    active: departments.filter(d => d.is_active).length,
    inactive: departments.filter(d => !d.is_active).length,
    withManager: departments.filter(d => d.manager_id).length,
    rootDepartments: departments.filter(d => !d.parent_department_id || d.parent_department_id.trim() === "").length,
    totalEmployees: departments.reduce((sum, d) => sum + (d._count?.team_assignments || 0), 0),
    totalBudget: departments.reduce((sum, d) => sum + (d.budget || 0), 0),
  }), [departments]);

  // Managers for filter
  const managers = useMemo(() => {
    const unique = new Map<string, string>();
    departments
      .filter(d => d.manager_id && d.manager)
      .forEach(d => unique.set(d.manager_id!, d.manager!.full_name));
    return Array.from(unique.entries()).map(([id, name]) => ({ id, name }));
  }, [departments]);

  // Check for roots
  const hasRootDepartments = filteredDepartments.some(
    d => (!d.parent_department_id || d.parent_department_id.trim() === "") ||
         !filteredDepartments.some(p => p.id === d.parent_department_id)
  );

  // Zoom controls
  const handleZoomIn = () => {
    reactFlowInstance.current?.zoomIn();
    setZoomLevel(prev => Math.min(prev + 0.1, 2));
  };

  const handleZoomOut = () => {
    reactFlowInstance.current?.zoomOut();
    setZoomLevel(prev => Math.max(prev - 0.1, 0.1));
  };

  const handleFitView = () => {
    reactFlowInstance.current?.fitView({ padding: 0.3, duration: 400 });
    setZoomLevel(1);
  };

  // Export hierarchy document
  const exportHierarchyDocument = useCallback(() => {
    const lines: string[] = [];
    lines.push("=".repeat(60));
    lines.push("DEPARTMENT HIERARCHY STRUCTURE");
    lines.push("=".repeat(60));
    lines.push(`Generated on: ${new Date().toLocaleString()}`);
    lines.push("");
    lines.push("DETAILED RELATIONSHIPS:");
    lines.push("-".repeat(60));
    lines.push("");

    departments.forEach(dept => {
      if (dept.parent_department_id && dept.parent_department_id.trim() !== "") {
        const parent = departments.find(p => p.id === dept.parent_department_id);
        if (parent) {
          lines.push(`• ${dept.name} is under ${parent.name}`);
        }
      } else {
        lines.push(`• ${dept.name} (Root Department - No Parent)`);
      }
    });

    lines.push("");
    lines.push("-".repeat(60));
    lines.push("STATISTICS:");
    lines.push("-".repeat(60));
    lines.push(`Total Departments: ${stats.total}`);
    lines.push(`Active Departments: ${stats.active}`);
    lines.push(`Root Departments: ${stats.rootDepartments}`);
    lines.push(`Total Employees: ${stats.totalEmployees}`);
    lines.push("=".repeat(60));

    const textContent = lines.join("\n");
    const blob = new Blob([textContent], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `department-hierarchy-${new Date().toISOString().split('T')[0]}.txt`;
    link.click();
    URL.revokeObjectURL(url);

    toast({
      title: "Success",
      description: "Hierarchy document exported successfully",
    });
  }, [departments, stats, toast]);

  if (!hasRootDepartments) {
    return (
      <div className="text-center py-12">
        <Building2 className="h-12 w-12 mx-auto text-muted-foreground/50 mb-4" />
        <p className="text-muted-foreground">
          No department hierarchy available. Create departments and set parent departments to build the hierarchy.
        </p>
      </div>
    );
  }

  return (
    <div className="w-full space-y-2">
      {/* Search and Filter Bar */}
      <Card>
        <CardContent className="p-3">
          <div className="flex items-center gap-2 flex-wrap">
            <div className="relative flex-1 min-w-[200px]">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
              <Input
                placeholder="Search departments..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="pl-10"
              />
            </div>
            <Select value={filterManager} onValueChange={setFilterManager}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Filter by Manager" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Managers</SelectItem>
                {managers.map(m => (
                  <SelectItem key={m.id} value={m.id}>
                    {m.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              variant={showStats ? "default" : "outline"}
              size="sm"
              onClick={() => setShowStats(!showStats)}
            >
              <BarChart3 className="h-4 w-4 mr-2" />
              Statistics
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={exportHierarchyDocument}
            >
              <Download className="h-4 w-4 mr-2" />
              Export
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Statistics Panel */}
      {showStats && (
        <Card>
          <CardContent className="p-4">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div>
                <p className="text-2xl font-bold">{stats.total}</p>
                <p className="text-sm text-muted-foreground">Total Departments</p>
              </div>
              <div>
                <p className="text-2xl font-bold text-green-600">{stats.active}</p>
                <p className="text-sm text-muted-foreground">Active</p>
              </div>
              <div>
                <p className="text-2xl font-bold">{stats.rootDepartments}</p>
                <p className="text-sm text-muted-foreground">Root Departments</p>
              </div>
              <div>
                <p className="text-2xl font-bold">{stats.totalEmployees}</p>
                <p className="text-sm text-muted-foreground">Total Employees</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Toolbar */}
      <Card>
        <CardContent className="p-3">
          <div className="flex items-center justify-between flex-wrap gap-2">
            <div className="flex items-center gap-2">
              <Button
                variant={connectionMode ? "default" : "outline"}
                size="sm"
                onClick={() => setConnectionMode(!connectionMode)}
              >
                <Link className="h-4 w-4 mr-2" />
                {connectionMode ? "Exit Connection Mode" : "Connection Mode"}
              </Button>
              
              {!connectionMode && (
                <>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={buildHierarchy}
                    title="Reset layout"
                  >
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Reset Layout
                  </Button>
                  <Button
                    variant={showInactiveDepartments ? "default" : "outline"}
                    size="sm"
                    onClick={() => setShowInactiveDepartments(!showInactiveDepartments)}
                  >
                    <Eye className="h-4 w-4 mr-2" />
                    {showInactiveDepartments ? "Show Active Only" : "Show All"}
                  </Button>
                  <div className="flex items-center gap-1 border rounded-md">
                    <Button variant="ghost" size="sm" onClick={handleZoomOut} className="h-8 px-2">
                      <ZoomOut className="h-4 w-4" />
                    </Button>
                    <span className="text-xs text-muted-foreground px-2 min-w-[50px] text-center">
                      {Math.round(zoomLevel * 100)}%
                    </span>
                    <Button variant="ghost" size="sm" onClick={handleZoomIn} className="h-8 px-2">
                      <ZoomIn className="h-4 w-4" />
                    </Button>
                    <Button variant="ghost" size="sm" onClick={handleFitView} className="h-8 px-2">
                      <Maximize2 className="h-4 w-4" />
                    </Button>
                  </div>
                </>
              )}
              
              {pendingConnections.size > 0 && (
                <>
                  <Button
                    variant="default"
                    size="sm"
                    onClick={saveConnections}
                    disabled={isSaving}
                  >
                    <Save className="h-4 w-4 mr-2" />
                    {isSaving ? "Saving..." : `Save ${pendingConnections.size} Connection(s)`}
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      setPendingConnections(new Map());
                      setEdges(prev => prev.filter(e => !pendingConnections.has(e.target)));
                    }}
                  >
                    <X className="h-4 w-4 mr-2" />
                    Cancel
                  </Button>
                </>
              )}
            </div>
            
            <div className="text-sm text-muted-foreground">
              {connectionMode ? (
                "Drag from one department to another to create a connection"
              ) : (
                <>
                  Drag nodes to reposition • <kbd className="px-1.5 py-0.5 bg-muted rounded text-xs">Ctrl/Cmd</kbd> + Drag to pan
                </>
              )}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* ReactFlow Canvas */}
      <div className="w-full h-[700px] border rounded-lg bg-background overflow-hidden relative">
        {nodes.length > 0 ? (
          <ReactFlow
            nodes={nodes}
            edges={edges}
            onNodesChange={onNodesChange}
            onEdgesChange={onEdgesChange}
            onConnect={connectionMode ? onConnect : undefined}
            onEdgesDelete={onEdgesDelete}
            nodeTypes={nodeTypes}
            connectionMode={ConnectionMode.Loose}
            defaultEdgeOptions={{
              type: 'smoothstep',
              animated: true,
              style: {
                stroke: '#3b82f6',
                strokeWidth: 2,
              },
              markerEnd: {
                type: MarkerType.ArrowClosed,
                color: '#3b82f6',
                width: 20,
                height: 20,
              },
            }}
            connectionLineStyle={{
              stroke: '#3b82f6',
              strokeWidth: 2,
            }}
            fitViewOptions={{ padding: 0.3, duration: 400 }}
            minZoom={0.1}
            maxZoom={2}
            proOptions={{ hideAttribution: true }}
            onInit={(instance) => {
              reactFlowInstance.current = instance;
              setTimeout(() => {
                if (nodes.length > 0) {
                  instance.fitView({ padding: 0.3, duration: 400 });
                }
              }, 300);
            }}
            onMove={(_, viewport) => {
              setZoomLevel(viewport.zoom);
            }}
          >
            <Controls />
            <Background color="#e5e7eb" gap={16} />
            <MiniMap 
              nodeColor={(node) => {
                return node.data?.level === 0 ? '#3b82f6' : '#94a3b8';
              }}
              maskColor="rgba(0, 0, 0, 0.1)"
            />
          </ReactFlow>
        ) : (
          <div className="flex items-center justify-center h-full">
            <div className="text-center">
              <RefreshCw className="h-8 w-8 animate-spin text-muted-foreground mx-auto mb-4" />
              <p className="text-muted-foreground">Loading hierarchy...</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import { useState, useEffect, useMemo, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Trash2, Search, Download, Filter, Grid3x3, List, Table2, RefreshCw } from "lucide-react";
import { db } from "@/lib/database";
import { useAuth } from "@/hooks/useAuth";
import { useToast } from "@/hooks/use-toast";
import { fetchJson } from "@/utils/authApi";
import { getAgencyId } from "@/utils/agencyUtils";
import {
  fetchDepartmentsList,
  fetchDepartmentsStats,
  createDepartment,
  updateDepartment,
  deleteDepartment,
  type DepartmentStats as ApiDepartmentStats,
} from "@/services/api/departments";
import {
  DepartmentFormDialog,
  DepartmentHierarchyView,
  DepartmentStatsCards,
  DepartmentFilters,
  DepartmentTable,
  DepartmentListView,
  DepartmentCardView,
  DepartmentDetailsDialog,
  type Department,
  type ViewMode,
  type SortField,
  type SortDirection,
} from "./components";
import { TeamAssignmentPanel } from "@/components/TeamAssignmentPanel";
import DeleteConfirmDialog from "@/components/shared/DeleteConfirmDialog";

export default function DepartmentManagement() {
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [showDepartmentForm, setShowDepartmentForm] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [showDetailsDialog, setShowDetailsDialog] = useState(false);
  const [selectedDepartment, setSelectedDepartment] = useState<Department | null>(null);
  const [selectedDepartments, setSelectedDepartments] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<ViewMode>("cards");
  const [sortField, setSortField] = useState<SortField>("name");
  const [sortDirection, setSortDirection] = useState<SortDirection>("asc");
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(10);
  const [showFilters, setShowFilters] = useState(false);
  const [activeTab, setActiveTab] = useState<string>("departments");

  const [filterStatus, setFilterStatus] = useState<string>("all");
  const [filterManager, setFilterManager] = useState<string>("all");
  const [filterParent, setFilterParent] = useState<string>("all");
  const [minBudget, setMinBudget] = useState<string>("");
  const [maxBudget, setMaxBudget] = useState<string>("");

  const [managers, setManagers] = useState<Array<{ user_id: string; full_name: string }>>([]);
  const [parentDepartments, setParentDepartments] = useState<Array<{ id: string; name: string }>>([]);
  const [departmentEmployees, setDepartmentEmployees] = useState<Array<{
    id: string;
    user_id: string;
    position_title?: string;
    role_in_department: string;
    full_name: string;
  }>>([]);
  const [loadingEmployees, setLoadingEmployees] = useState(false);
  const [expandedDepartments, setExpandedDepartments] = useState<Set<string>>(new Set());
  const [departmentMembers, setDepartmentMembers] = useState<Record<string, Array<{
    id: string;
    full_name: string;
    position_title?: string;
    role_in_department: string;
  }>>>({});
  const [listTotal, setListTotal] = useState(0);
  const [apiStats, setApiStats] = useState<ApiDepartmentStats | null>(null);

  const { user, userRole, profile } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();

  const isAdmin = userRole === "agency_admin" || userRole === "super_admin" || userRole === "manager";
  const isHR = false; // hr role removed; managers handle HR functions


  const fetchStats = async () => {
    try {
      const s = await fetchDepartmentsStats();
      setApiStats(s);
    } catch {
      setApiStats({ active: 0, inactive: 0, totalBudget: 0, totalEmployees: 0 });
    }
  };

  const fetchDepartments = useCallback(async () => {
    setLoading(true);
    try {
      await fetchStats();
      const isDeactivated = activeTab === "deactivated";
      const isHierarchy = activeTab === "hierarchy";
      const limit = isHierarchy ? 2000 : pageSize;
      const offset = isHierarchy ? 0 : (currentPage - 1) * pageSize;
      const { departments: list, total } = await fetchDepartmentsList({
        limit,
        offset,
        sortBy: sortField === "employees" ? "employees" : sortField === "created_at" ? "created_at" : "name",
        sortDir: sortDirection,
        search: searchTerm.trim() || undefined,
        is_active: isHierarchy ? undefined : !isDeactivated,
        manager_id: filterManager !== "all" ? filterManager : undefined,
        parent_department_id: filterParent !== "all" ? filterParent : undefined,
        min_budget: minBudget || undefined,
        max_budget: maxBudget || undefined,
      });
      setDepartments(list);
      setListTotal(total);
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({
        title: "Error",
        description: err?.message || "Failed to fetch departments.",
        variant: "destructive",
      });
      setDepartments([]);
      setListTotal(0);
    } finally {
      setLoading(false);
    }
  }, [activeTab, currentPage, pageSize, sortField, sortDirection, searchTerm, filterManager, filterParent, minBudget, maxBudget, toast]);

  useEffect(() => {
    if (activeTab === "departments" || activeTab === "deactivated" || activeTab === "hierarchy") {
      fetchDepartments();
    }
  }, [fetchDepartments, activeTab]);

  const fetchManagers = useCallback(async () => {
    try {
      const res = await fetchJson(`/hr/employees`);
      if (res) {
        setManagers(res.map((emp: any) => ({
          user_id: emp.id,
          full_name: `${emp.first_name} ${emp.last_name}`
        })));
      }
    } catch {
      // Silently handle
    }
  }, []);

  const fetchParentDepartments = useCallback(async () => {
    try {
      const { departments } = await fetchDepartmentsList({ limit: 1000 });
      setParentDepartments(departments.map(d => ({ id: d.id, name: d.name })));
    } catch {
      // Silently handle
    }
  }, []);

  useEffect(() => {
    fetchManagers();
    fetchParentDepartments();
  }, [fetchManagers, fetchParentDepartments]);

  const fetchDepartmentEmployees = async (departmentId: string) => {
    setLoadingEmployees(true);
    try {
      const res = await fetchJson(`/hr/employees?departmentId=${departmentId}`);
      if (res) {
        setDepartmentEmployees(res.map((emp: any) => ({
          id: emp.id,
          user_id: emp.id,
          position_title: emp.position || "",
          role_in_department: emp.role || "member",
          full_name: `${emp.first_name} ${emp.last_name}`,
        })));
      } else {
        setDepartmentEmployees([]);
      }
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({
        title: "Error",
        description: err?.message || "Failed to fetch department employees",
        variant: "destructive",
      });
      setDepartmentEmployees([]);
    } finally {
      setLoadingEmployees(false);
    }
  };

  const paginatedDepartments = activeTab === "departments" ? departments : [];
  const paginatedDeactivatedDepartments = activeTab === "deactivated" ? departments : [];
  const totalPages = Math.max(1, Math.ceil(listTotal / pageSize));
  const totalDeactivatedPages = Math.max(1, Math.ceil(listTotal / pageSize));

  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection((d) => (d === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortDirection("asc");
    }
  };

  const handleEdit = (department: Department) => {
    setSelectedDepartment(department);
    setShowDepartmentForm(true);
  };

  const handleDelete = (department: Department) => {
    setSelectedDepartment(department);
    setShowDeleteDialog(true);
  };

  const handleViewDetails = async (department: Department) => {
    setSelectedDepartment(department);
    setShowDetailsDialog(true);
    if (department.id) {
      try {
        fetchDepartmentEmployees(department.id);
      } catch {
        // Fallback
        setDepartmentEmployees([]);
      }
    }
  };

  const handleViewEmployees = (departmentId: string, departmentName: string) => {
    navigate(`/employee-management?department=${departmentId}&name=${encodeURIComponent(departmentName)}`);
  };
  const handleViewProjects = (departmentId: string, departmentName: string) => {
    navigate(`/projects?department=${departmentId}&name=${encodeURIComponent(departmentName)}`);
  };
  const handleViewAttendance = (departmentId: string, departmentName: string) => {
    navigate(`/attendance?department=${departmentId}&name=${encodeURIComponent(departmentName)}`);
  };
  const handleViewPayroll = (departmentId: string, departmentName: string) => {
    navigate(`/payroll?department=${departmentId}&name=${encodeURIComponent(departmentName)}`);
  };

  const handleDuplicate = async (department: Department) => {
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({ title: "Error", description: "Agency ID not found.", variant: "destructive" });
        return;
      }
      await createDepartment({
        name: `${department.name} (Copy)`,
        description: department.description ?? undefined,
        manager_id: department.manager_id ?? undefined,
        parent_department_id: department.parent_department_id ?? undefined,
        budget: department.budget ?? 0,
        agency_id: agencyId,
      });
      toast({ title: "Success", description: "Department duplicated successfully" });
      fetchDepartments();
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({ title: "Error", description: err?.message || "Failed to duplicate department", variant: "destructive" });
    }
  };

  const handleArchive = async (department: Department) => {
    try {
      await deleteDepartment(department.id, false);
      toast({ title: "Success", description: "Department archived successfully" });
      fetchDepartments();
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({ title: "Error", description: err?.message || "Failed to archive department", variant: "destructive" });
    }
  };

  const handleRestore = async (department: Department) => {
    try {
      await updateDepartment(department.id, { is_active: true });
      toast({ title: "Success", description: "Department restored successfully" });
      fetchDepartments();
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({ title: "Error", description: err?.message || "Failed to restore department", variant: "destructive" });
    }
  };

  const handleBulkDelete = async () => {
    if (selectedDepartments.size === 0) return;
    try {
      await Promise.all(Array.from(selectedDepartments).map((id) => deleteDepartment(id, false)));
      toast({ title: "Success", description: `${selectedDepartments.size} department(s) archived successfully` });
      setSelectedDepartments(new Set());
      fetchDepartments();
    } catch (error: unknown) {
      const err = error as { message?: string };
      toast({ title: "Error", description: err?.message || "Failed to archive departments", variant: "destructive" });
    }
  };

  const handleSelectAll = () => {
    const list = activeTab === "deactivated" ? paginatedDeactivatedDepartments : paginatedDepartments;
    if (selectedDepartments.size === list.length) {
      setSelectedDepartments(new Set());
    } else {
      setSelectedDepartments(new Set(list.map((d) => d.id)));
    }
  };

  const handleSelectDepartment = (id: string) => {
    const newSelected = new Set(selectedDepartments);
    if (newSelected.has(id)) newSelected.delete(id);
    else newSelected.add(id);
    setSelectedDepartments(newSelected);
  };

  const exportToCSV = () => {
    const headers = ["Name", "Description", "Manager", "Parent Department", "Budget", "Employees", "Status", "Created At"];
    const rows = departments.map((dept) => [
      dept.name,
      dept.description || "",
      dept.manager?.full_name || "",
      dept.parent_department?.name || "",
      (dept.budget || 0).toString(),
      (dept._count?.team_assignments || 0).toString(),
      dept.is_active ? "Active" : "Inactive",
      new Date(dept.created_at).toLocaleDateString(),
    ]);
    const csvContent = [headers.join(","), ...rows.map((row) => row.map((cell) => `"${cell}"`).join(","))].join("\n");
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `departments_${new Date().toISOString().split("T")[0]}.csv`;
    link.style.visibility = "hidden";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast({ title: "Success", description: "Departments exported to CSV successfully" });
  };

  const stats = useMemo(() => {
    const s = apiStats ?? { active: 0, inactive: 0, totalBudget: 0, totalEmployees: 0 };
    const active = s.active;
    const inactive = s.inactive;
    const total = active + inactive;
    const totalBudget = s.totalBudget;
    const totalEmployees = s.totalEmployees;
    const avgBudget = active > 0 ? totalBudget / active : 0;
    const avgEmployees = active > 0 ? totalEmployees / active : 0;
    return {
      active,
      inactive,
      total,
      totalBudget: Number(totalBudget.toFixed(2)),
      totalEmployees,
      avgBudget: Number(avgBudget.toFixed(2)),
      avgEmployees: Number(avgEmployees.toFixed(1)),
      departmentsWithManager: 0,
      departmentsWithParent: 0,
    };
  }, [apiStats]);

  const searchAndFiltersBar = (
    <div className="flex items-center gap-4 flex-wrap">
      <div className="relative flex-1 min-w-[200px]">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
        <Input
          placeholder={activeTab === "deactivated" ? "Search deactivated departments..." : "Search departments..."}
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="pl-10"
        />
      </div>
      <Button variant="outline" size="sm" onClick={() => setShowFilters(!showFilters)}>
        <Filter className="h-4 w-4 mr-2" />
        Filters
      </Button>
      <div className="flex items-center gap-2">
        <Button variant={viewMode === "cards" ? "default" : "outline"} size="sm" onClick={() => setViewMode("cards")}>
          <Grid3x3 className="h-4 w-4" />
        </Button>
        <Button variant={viewMode === "table" ? "default" : "outline"} size="sm" onClick={() => setViewMode("table")}>
          <Table2 className="h-4 w-4" />
        </Button>
        <Button variant={viewMode === "list" ? "default" : "outline"} size="sm" onClick={() => setViewMode("list")}>
          <List className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );

  const tablePaginationProps = {
    currentPage,
    pageSize,
    totalPages: activeTab === "deactivated" ? totalDeactivatedPages : totalPages,
    totalCount: listTotal,
    onPageChange: setCurrentPage,
    onPageSizeChange: (size: number) => {
      setPageSize(size);
      setCurrentPage(1);
    },
  };

  const actionsProps = {
    onViewDetails: handleViewDetails,
    onViewEmployees: handleViewEmployees,
    onViewProjects: handleViewProjects,
    onViewAttendance: handleViewAttendance,
    onViewPayroll: handleViewPayroll,
    onEdit: handleEdit,
    onDuplicate: handleDuplicate,
    onArchive: handleArchive,
    onRestore: handleRestore,
    onDelete: handleDelete,
  };

  if (!isAdmin && !isHR) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="flex items-center justify-center h-32">
            <p className="text-muted-foreground">You don&apos;t have permission to access department management.</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-4 sm:p-6 space-y-4 sm:space-y-6 w-full max-w-full overflow-hidden">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 w-full">
        <div className="flex-1 min-w-0">
          <h1 className="text-2xl sm:text-3xl font-bold truncate">Department Management</h1>
          <p className="text-sm sm:text-base text-muted-foreground mt-1">Manage organizational structure and team assignments</p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          {isAdmin && selectedDepartments.size > 0 && (
            <Button variant="destructive" size="sm" onClick={handleBulkDelete} className="whitespace-nowrap">
              <Trash2 className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">Archive Selected</span>
              <span className="sm:hidden">Archive</span>
              <span className="ml-1">({selectedDepartments.size})</span>
            </Button>
          )}
          <Button variant="outline" size="sm" onClick={exportToCSV} className="whitespace-nowrap">
            <Download className="h-4 w-4 mr-2" />
            <span className="hidden sm:inline">Export CSV</span>
            <span className="sm:hidden">Export</span>
          </Button>
          {isAdmin && (
            <Button onClick={() => { setSelectedDepartment(null); setShowDepartmentForm(true); }} className="whitespace-nowrap">
              <Plus className="h-4 w-4 mr-2" />
              <span className="hidden sm:inline">Create Department</span>
              <span className="sm:hidden">Create</span>
            </Button>
          )}
        </div>
      </div>

      <DepartmentStatsCards stats={stats} />

      <Tabs value={activeTab} onValueChange={(v) => { setActiveTab(v); setCurrentPage(1); }} className="space-y-4">
        <TabsList>
          <TabsTrigger value="departments">Departments</TabsTrigger>
          {isAdmin && <TabsTrigger value="deactivated">Deactivated ({stats.inactive})</TabsTrigger>}
          {(isAdmin || isHR) && <TabsTrigger value="assignments">Team Assignments</TabsTrigger>}
          <TabsTrigger value="hierarchy">Hierarchy</TabsTrigger>
        </TabsList>

        <TabsContent value="departments" className="space-y-4">
          {searchAndFiltersBar}
          {showFilters && (
            <DepartmentFilters
              filterStatus={filterStatus}
              setFilterStatus={setFilterStatus}
              filterManager={filterManager}
              setFilterManager={setFilterManager}
              filterParent={filterParent}
              setFilterParent={setFilterParent}
              minBudget={minBudget}
              setMinBudget={setMinBudget}
              maxBudget={maxBudget}
              setMaxBudget={setMaxBudget}
              managers={managers}
              parentDepartments={parentDepartments}
              includeStatusFilter
            />
          )}
          {loading ? (
            <Card>
              <CardContent className="flex items-center justify-center h-32">
                <p>Loading departments...</p>
              </CardContent>
            </Card>
          ) : activeTab === "departments" && listTotal === 0 ? (
            <Card>
              <CardContent className="flex items-center justify-center h-32">
                <p className="text-muted-foreground">No departments found</p>
              </CardContent>
            </Card>
          ) : viewMode === "table" ? (
            <DepartmentTable
              departments={paginatedDepartments}
              isAdmin={isAdmin}
              selectedDepartments={selectedDepartments}
              onSelectAll={handleSelectAll}
              onSelectDepartment={handleSelectDepartment}
              sortField={sortField}
              sortDirection={sortDirection}
              onSort={handleSort}
              {...tablePaginationProps}
              {...actionsProps}
            />
          ) : viewMode === "list" ? (
            <DepartmentListView
              departments={paginatedDepartments}
              isAdmin={isAdmin}
              selectedDepartments={selectedDepartments}
              onSelectDepartment={handleSelectDepartment}
              {...tablePaginationProps}
              {...actionsProps}
            />
          ) : (
            <DepartmentCardView
              departments={paginatedDepartments}
              isAdmin={isAdmin}
              {...tablePaginationProps}
              {...actionsProps}
            />
          )}
        </TabsContent>

        <TabsContent value="deactivated" className="space-y-4">
          {searchAndFiltersBar}
          {showFilters && (
            <DepartmentFilters
              filterStatus={filterStatus}
              setFilterStatus={setFilterStatus}
              filterManager={filterManager}
              setFilterManager={setFilterManager}
              filterParent={filterParent}
              setFilterParent={setFilterParent}
              minBudget={minBudget}
              setMinBudget={setMinBudget}
              maxBudget={maxBudget}
              setMaxBudget={setMaxBudget}
              managers={managers}
              parentDepartments={parentDepartments}
              includeStatusFilter={false}
            />
          )}
          {loading ? (
            <Card>
              <CardContent className="flex items-center justify-center h-32">
                <p>Loading deactivated departments...</p>
              </CardContent>
            </Card>
          ) : activeTab === "deactivated" && listTotal === 0 ? (
            <Card>
              <CardContent className="flex items-center justify-center h-32">
                <p className="text-muted-foreground">No deactivated departments found</p>
              </CardContent>
            </Card>
          ) : viewMode === "table" ? (
            <DepartmentTable
              departments={paginatedDeactivatedDepartments}
              isAdmin={isAdmin}
              selectedDepartments={selectedDepartments}
              onSelectAll={handleSelectAll}
              onSelectDepartment={handleSelectDepartment}
              sortField={sortField}
              sortDirection={sortDirection}
              onSort={handleSort}
              {...tablePaginationProps}
              countLabel="deactivated departments"
              {...actionsProps}
              isDeactivated
            />
          ) : viewMode === "list" ? (
            <DepartmentListView
              departments={paginatedDeactivatedDepartments}
              isAdmin={isAdmin}
              selectedDepartments={selectedDepartments}
              onSelectDepartment={handleSelectDepartment}
              {...tablePaginationProps}
              countLabel="deactivated departments"
              {...actionsProps}
              isDeactivated
            />
          ) : (
            <DepartmentCardView
              departments={paginatedDeactivatedDepartments}
              isAdmin={isAdmin}
              {...tablePaginationProps}
              countLabel="deactivated departments"
              {...actionsProps}
              isDeactivated
            />
          )}
        </TabsContent>

        <TabsContent value="assignments">
          <TeamAssignmentPanel />
        </TabsContent>

        <TabsContent value="hierarchy">
          <Card>
            <CardHeader>
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle>Department Hierarchy</CardTitle>
                  <p className="text-sm text-muted-foreground mt-1">Visual representation of your organizational structure</p>
                </div>
                <Button variant="outline" size="sm" onClick={fetchDepartments}>
                  <RefreshCw className="h-4 w-4 mr-2" />
                  Refresh
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div className="flex items-center justify-center py-12">
                  <RefreshCw className="h-6 w-6 animate-spin text-muted-foreground" />
                </div>
              ) : (
                <DepartmentHierarchyView
                  departments={departments}
                  expandedDepartments={expandedDepartments}
                  setExpandedDepartments={setExpandedDepartments}
                  departmentMembers={departmentMembers}
                  setDepartmentMembers={setDepartmentMembers}
                  onDepartmentClick={(dept) => handleViewDetails(dept)}
                  db={db}
                  onRefresh={fetchDepartments}
                />
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      <DepartmentDetailsDialog
        open={showDetailsDialog}
        onOpenChange={(open) => {
          setShowDetailsDialog(open);
          if (!open) {
            setDepartmentEmployees([]);
            setSelectedDepartment(null);
          }
        }}
        department={selectedDepartment}
        employees={departmentEmployees}
        loadingEmployees={loadingEmployees}
        onViewEmployees={handleViewEmployees}
        onViewProjects={handleViewProjects}
        onViewAttendance={handleViewAttendance}
        onViewPayroll={handleViewPayroll}
      />

      <DepartmentFormDialog
        open={showDepartmentForm}
        onOpenChange={setShowDepartmentForm}
        department={selectedDepartment ?? undefined}
        onDepartmentSaved={() => {
          setShowDepartmentForm(false);
          setSelectedDepartment(null);
          fetchDepartments();
        }}
      />

      <DeleteConfirmDialog
        isOpen={showDeleteDialog}
        onClose={() => {
          setShowDeleteDialog(false);
          setSelectedDepartment(null);
        }}
        onDeleted={fetchDepartments}
        itemType="Department"
        itemName={selectedDepartment?.name || ""}
        itemId={selectedDepartment?.id || ""}
        tableName="departments"
        softDelete={false}
        description="This will permanently delete the department. This action cannot be undone."
        onConfirm={async (softDelete) => {
          if (selectedDepartment) await deleteDepartment(selectedDepartment.id, !softDelete);
        }}
      />
    </div>
  );
}

/**
 * Employee utility functions
 * Helper functions for employee data processing
 */

import { ROLE_CATEGORIES } from '@/utils/roleUtils';
import { Crown, Shield, Star } from 'lucide-react';

/**
 * Get role icon component
 */
export const getRoleIcon = (role?: string | null) => {
  if (!role) return Star;
  if (ROLE_CATEGORIES.system.includes(role as any)) return Crown;
  if (ROLE_CATEGORIES.management.includes(role as any)) return Shield;
  return Star;
};

/**
 * Get role badge variant
 */
export const getRoleBadgeVariant = (role?: string | null): 'default' | 'secondary' | 'outline' => {
  if (!role) return 'outline';
  if (ROLE_CATEGORIES.system.includes(role as any)) return 'default';
  if (ROLE_CATEGORIES.management.includes(role as any)) return 'secondary';
  return 'outline';
};

/**
 * Get employment type label
 */
export const getEmploymentTypeLabel = (type?: string): string => {
  switch (type) {
    case 'full_time':
    case 'full-time':
      return 'Full Time';
    case 'part_time':
    case 'part-time':
      return 'Part Time';
    case 'contract': return 'Contract';
    case 'intern': return 'Intern';
    default: return type || 'Full Time';
  }
};

/**
 * Normalize employment_type to database format (hyphens)
 */
export const normalizeEmploymentType = (type?: string): string => {
  if (!type) return 'full-time';
  // Convert underscores to hyphens (replace all occurrences)
  return type.replace(/_/g, '-');
};

/**
 * Get initials from name
 */
export const getInitials = (name: string): string => {
  return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
};

/**
 * Calculate employee statistics
 */
export const calculateEmployeeStats = (employees: unknown[]) => {
  return {
    total: employees.length,
    active: employees.filter(e => e.is_active).length,
    inactive: employees.filter(e => !e.is_active).length,
    admins: employees.filter(e => e.is_active && ['super_admin', 'agency_admin'].includes(e.role)).length,
    managers: employees.filter(e => e.is_active && ROLE_CATEGORIES.management.includes(e.role as unknown)).length,
    departments: new Set(employees.map(e => e.department).filter(Boolean)).size,
  };
};

/**
 * Hook for fetching all financial data
 * Centralized data fetching for financial management
 */

import { useState, useEffect } from 'react';
import { useToast } from '@/hooks/use-toast';
import { logWarn, logError } from '@/utils/consoleLogger';
import { getAgencyId } from '@/utils/agencyUtils';
import { useJobs } from './useJobs';
import { useChartOfAccounts } from './useChartOfAccounts';
import { useJournalEntries } from './useJournalEntries';
import { useTransactions } from './useTransactions';
import { useProjects } from './useProjects';

export const useFinancialData = (user: unknown, profile: unknown) => {
  const { toast } = useToast();
  const [agencyId, setAgencyId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const {
    jobs,
    setJobs,
    loading: jobsLoading,
    fetchJobs,
  } = useJobs(agencyId);

  const {
    projects,
    loading: projectsLoading,
    fetchProjects,
  } = useProjects(agencyId, profile, user);

  const {
    chartOfAccounts,
    setChartOfAccounts,
    loading: accountsLoading,
    fetchChartOfAccounts,
  } = useChartOfAccounts(agencyId);

  const {
    journalEntries,
    setJournalEntries,
    loading: entriesLoading,
    fetchJournalEntries,
  } = useJournalEntries(agencyId);

  const {
    transactions,
    loading: transactionsLoading,
    fetchTransactions,
  } = useTransactions(agencyId);

  useEffect(() => {
    const initializeAgency = async () => {
      const agencyDatabase = localStorage.getItem('agency_database');
      
      let id: string | null = null;
      
      const storedAgencyId = localStorage.getItem('agency_id');
      if (storedAgencyId) {
        id = storedAgencyId;
      } else {
        id = await getAgencyId(profile, user?.id);
      }
      
      if (agencyDatabase || id) {
        setAgencyId(id || '00000000-0000-0000-0000-000000000000');
      }
    };

    if (user?.id) {
      initializeAgency();
    }
  }, [user?.id, profile?.agency_id]);

  useEffect(() => {
    const fetchAllData = async () => {
      if (!agencyId) {
        logWarn('No agency_id available, cannot fetch data');
        setLoading(false);
        return;
      }

      setLoading(true);
      try {
        await Promise.all([
          fetchJobs(agencyId),
          fetchProjects(agencyId),
          fetchChartOfAccounts(agencyId),
          fetchJournalEntries(agencyId),
          fetchTransactions(agencyId),
        ]);
      } catch (error) {
        logError('Error fetching financial data:', error);
        toast({
          title: 'Error',
          description: 'Failed to load financial data',
          variant: 'destructive',
        });
      } finally {
        setLoading(false);
      }
    };

    if (agencyId) {
      fetchAllData();
    }
  }, [agencyId]);

  const refetchAll = async () => {
    if (!agencyId) return;
    
    setLoading(true);
    try {
      await Promise.all([
        fetchJobs(agencyId),
        fetchProjects(agencyId),
        fetchChartOfAccounts(agencyId),
        fetchJournalEntries(agencyId),
        fetchTransactions(agencyId),
      ]);
    } catch (error) {
      logError('Error refetching financial data:', error);
    } finally {
      setLoading(false);
    }
  };

  return {
    agencyId,
    jobs,
    projects,
    chartOfAccounts,
    journalEntries,
    transactions,
    loading: loading || jobsLoading || projectsLoading || accountsLoading || entriesLoading || transactionsLoading,
    refetchAll,
    fetchJobs,
    fetchProjects,
    fetchChartOfAccounts,
    fetchJournalEntries,
    fetchTransactions,
    setJobs,
    setChartOfAccounts,
    setJournalEntries,
  };
};

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, Search, Filter, Download, TrendingUp, TrendingDown, DollarSign, Calendar, ArrowUpRight, ArrowDownRight, Loader2 } from "lucide-react";
import { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { selectRecords, selectOne } from '@/services/api/core';
import { logDebug, logWarn, logError } from '@/utils/consoleLogger';

interface Transaction {
  id: string;
  date: string;
  description: string;
  category: string;
  type: 'credit' | 'debit';
  amount: number;
  balance: number;
  reference: string;
}

interface LedgerSummary {
  totalBalance: number;
  monthlyIncome: number;
  monthlyExpenses: number;
  netProfit: number;
}

const Ledger = () => {
  const navigate = useNavigate();
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const [loading, setLoading] = useState(true);
  const [ledgerSummary, setLedgerSummary] = useState<LedgerSummary>({
    totalBalance: 0,
    monthlyIncome: 0,
    monthlyExpenses: 0,
    netProfit: 0
  });
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [searchTerm, setSearchTerm] = useState("");
  const [error, setError] = useState<string | null>(null);

  const fetchLedgerData = useCallback(async () => {
    
    try {
      setLoading(true);
      setError(null);
      
      // Get agency_id - try profile first, then try to fetch from database
      let agencyId = profile?.agency_id;
      
      if (!agencyId && user?.id) {
        try {
          const userProfile = await selectOne('profiles', { user_id: user.id });
          agencyId = userProfile?.agency_id;
        } catch (err) {
          logWarn('Could not fetch profile:', err);
        }
      }

      // Fetch all posted journal entries
      const entries = await selectRecords('journal_entries', {
        where: { status: 'posted' },
        orderBy: 'entry_date DESC',
        limit: 500,
      }).catch((err: unknown) => {
        if ((err as any)?.code === '42P01') return [];
        throw err;
      });

      logDebug('Fetched journal entries:', entries?.length || 0, 'entries');

      // If no entries, still show the page with empty state
      if (!entries || entries.length === 0) {
        logDebug('No journal entries found');
        setTransactions([]);
        setLedgerSummary({
          totalBalance: 0,
          monthlyIncome: 0,
          monthlyExpenses: 0,
          netProfit: 0
        });
        setLoading(false);
        return;
      }

      // Filter by agency_id if available
      const agencyEntries = (entries || []).filter((e: unknown) => 
        !agencyId || !e.agency_id || e.agency_id === agencyId
      );

      // Fetch journal entry lines to get account details
      const entryIds = agencyEntries.map((e: unknown) => e.id) || [];
      let lines: unknown[] = [];
      
      if (entryIds.length > 0) {
        lines = await selectRecords('journal_entry_lines', {
          filters: [{ column: 'journal_entry_id', operator: 'in', value: entryIds }],
        }).catch((err: unknown) => {
          if ((err as any)?.code === '42P01') return [];
          throw err;
        });
      }

      // Fetch chart of accounts for category mapping
      let accounts: unknown[] = [];
      try {
        const where: Record<string, unknown> = { is_active: true };
        if (agencyId) {
          // Prefer agency scoped data when column exists
          where.agency_id = agencyId;
        }
        accounts = await selectRecords('chart_of_accounts', {
          where,
          orderBy: 'account_code ASC'
        });
      } catch (err: unknown) {
        // Fallback if agency_id column does not exist in current schema
        if (err?.code === '42703' || String(err?.message || '').includes('agency_id')) {
          logWarn('chart_of_accounts has no agency_id column, falling back to global accounts');
          accounts = await selectRecords('chart_of_accounts', {
            where: { is_active: true },
            orderBy: 'account_code ASC'
          });
        } else {
          throw err;
        }
      }

      const accountMap = new Map((accounts || []).map((acc: unknown) => [acc.id, acc]));

      // Calculate total balance from all posted entries
      let totalBalance = 0;
      const accountBalances: Record<string, number> = {};

      // Calculate balances per account
      lines.forEach((line: unknown) => {
        if (!line || !line.account_id) return;
        
        const account = accountMap.get(line.account_id);
        if (!account) return;

        const accountType = String(account.account_type || '').toLowerCase();
        const debit = parseFloat(line.debit_amount || 0);
        const credit = parseFloat(line.credit_amount || 0);

        if (!accountBalances[line.account_id]) {
          accountBalances[line.account_id] = 0;
        }

        // For asset and expense: balance = debits - credits
        // For liability, equity, revenue: balance = credits - debits
        if (accountType === 'asset' || accountType === 'expense') {
          accountBalances[line.account_id] += (debit - credit);
        } else {
          accountBalances[line.account_id] += (credit - debit);
        }
      });

      // Sum all asset account balances (excluding expenses)
      Object.entries(accountBalances).forEach(([accountId, balance]) => {
        const account = accountMap.get(accountId);
        if (account) {
          const accountType = String(account.account_type || '').toLowerCase();
          if (accountType === 'asset') {
            totalBalance += balance;
          }
        }
      });

      // Transform journal entries to transactions for display
      const transformedTransactions: Transaction[] = [];
      let runningBalance = 0;

      agencyEntries.forEach((entry: unknown) => {
        if (!entry || !entry.id) return;
        
        const entryLines = lines.filter((l: unknown) => l && l.journal_entry_id === entry.id);
        
        entryLines.forEach((line: unknown) => {
          if (!line || !line.id) return;
          
          const account = line.account_id ? accountMap.get(line.account_id) : null;
          const isCredit = (line.credit_amount || 0) > 0;
          const amount = isCredit ? (line.credit_amount || 0) : (line.debit_amount || 0);
          
          if (amount > 0) {
            runningBalance += isCredit ? amount : -amount;
            
            // Determine category from account type
            let category = 'Other';
            if (account?.account_type) {
              const accountType = String(account.account_type).toLowerCase();
              if (accountType.includes('revenue') || accountType.includes('income')) {
                category = 'Revenue';
              } else if (accountType.includes('expense')) {
                category = 'Operating Expenses';
              } else if (accountType.includes('payroll') || accountType.includes('salary')) {
                category = 'Payroll';
              }
            }

            const entryDate = entry.entry_date || entry.created_at || new Date().toISOString();
            const description = line.description || entry.description || 'Transaction';
            const reference = entry.reference || entry.entry_number || `JE-${String(entry.id).substring(0, 8)}`;

            transformedTransactions.push({
              id: String(line.id),
              date: entryDate,
              description: description,
              category,
              type: isCredit ? 'credit' : 'debit',
              amount,
              balance: runningBalance,
              reference: reference
            });
          }
        });
      });

      // Sort by date descending
      transformedTransactions.sort((a, b) => {
        try {
          const dateA = new Date(a.date).getTime();
          const dateB = new Date(b.date).getTime();
          return dateB - dateA;
        } catch {
          return 0;
        }
      });

      setTransactions(transformedTransactions);

      // Calculate summary for current month
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      const monthlyTransactions = transformedTransactions.filter(t => {
        try {
          const tDate = new Date(t.date);
          return tDate.getMonth() === currentMonth && tDate.getFullYear() === currentYear;
        } catch {
          return false;
        }
      });

      const monthlyIncome = monthlyTransactions
        .filter(t => t.type === 'credit')
        .reduce((sum, t) => sum + (t.amount || 0), 0);
      
      const monthlyExpenses = monthlyTransactions
        .filter(t => t.type === 'debit')
        .reduce((sum, t) => sum + (t.amount || 0), 0);

      setLedgerSummary({
        totalBalance: totalBalance || 0,
        monthlyIncome: monthlyIncome || 0,
        monthlyExpenses: monthlyExpenses || 0,
        netProfit: (monthlyIncome || 0) - (monthlyExpenses || 0)
      });

    } catch (error: unknown) {
      logError('Error fetching ledger data:', error);
      const errorMessage = error?.message || 'Failed to load ledger data. Please try again.';
      setError(errorMessage);
      toast({
        title: "Error",
        description: errorMessage,
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [profile?.agency_id, user?.id, toast]);

  useEffect(() => {
    // Try to fetch data - don't wait indefinitely for profile
    const timer = setTimeout(() => {
      fetchLedgerData();
    }, 100);

    return () => clearTimeout(timer);
  }, [fetchLedgerData]);

  const handleExportLedger = () => {
    try {
      const headers = [
        'Date',
        'Reference',
        'Description',
        'Category',
        'Type',
        'Amount',
        'Balance'
      ];

      const rows = transactions.map(t => [
        new Date(t.date).toLocaleDateString(),
        t.reference,
        t.description,
        t.category,
        t.type.toUpperCase(),
        (typeof t.amount === 'number' ? t.amount : parseFloat(t.amount) || 0).toFixed(2),
        (typeof t.balance === 'number' ? t.balance : parseFloat(t.balance) || 0).toFixed(2)
      ]);

      const csvContent = [
        headers.map(h => `"${h}"`).join(','),
        ...rows.map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `ledger_export_${new Date().toISOString().split('T')[0]}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      toast({
        title: "Success",
        description: "Ledger exported successfully",
      });
    } catch (error: unknown) {
      logError('Error exporting ledger:', error);
      toast({
        title: "Error",
        description: "Failed to export ledger. Please try again.",
        variant: "destructive",
      });
    }
  };

  const handleAddTransaction = () => {
    navigate('/ledger/create-entry');
  };

  const filteredTransactions = transactions.filter(transaction => {
    if (!transaction) return false;
    const searchLower = searchTerm.toLowerCase();
    return (
      (transaction.description || '').toLowerCase().includes(searchLower) ||
      (transaction.reference || '').toLowerCase().includes(searchLower) ||
      (transaction.category || '').toLowerCase().includes(searchLower)
    );
  });

  if (loading) {
    return (
      <div className="p-6">
        <div className="flex flex-col justify-center items-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin" />
          <span className="ml-2 text-muted-foreground mt-4">Loading ledger data...</span>
          {!profile?.agency_id && (
            <p className="text-sm text-muted-foreground mt-2">
              Waiting for user profile...
            </p>
          )}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="p-6">
        <div className="flex flex-col justify-center items-center min-h-[400px]">
          <p className="text-lg font-semibold text-destructive mb-2">Error Loading Ledger</p>
          <p className="text-sm text-muted-foreground mb-4">{error}</p>
          <Button onClick={fetchLedgerData}>Retry</Button>
        </div>
      </div>
    );
  }

  const getTransactionIcon = (type: string) => {
    return type === 'credit' ? (
      <ArrowUpRight className="h-4 w-4 text-green-600" />
    ) : (
      <ArrowDownRight className="h-4 w-4 text-red-600" />
    );
  };

  const getTransactionColor = (type: string) => {
    return type === 'credit' ? 'text-green-600' : 'text-red-600';
  };

  const getCategoryColor = (category: string) => {
    switch (category.toLowerCase()) {
      case 'revenue': return 'bg-green-100 text-green-800';
      case 'operating expenses': return 'bg-red-100 text-red-800';
      case 'payroll': return 'bg-blue-100 text-blue-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const formatCurrency = (amount: number) => {
    return `₹${Math.abs(amount).toLocaleString('en-IN', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    })}`;
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-6">
        <div>
          <h1 className="text-2xl sm:text-3xl font-bold">General Ledger</h1>
          <p className="text-sm sm:text-base text-muted-foreground mt-1">
            Track all financial transactions and account balances
          </p>
        </div>
        <div className="flex flex-col sm:flex-row gap-2 w-full sm:w-auto">
          <Button 
            variant="outline" 
            onClick={handleExportLedger}
            className="w-full sm:w-auto"
          >
            <Download className="mr-2 h-4 w-4" />
            Export Ledger
          </Button>
          <Button 
            onClick={handleAddTransaction}
            className="w-full sm:w-auto"
          >
            <Plus className="mr-2 h-4 w-4" />
            Add Transaction
          </Button>
        </div>
      </div>

      {/* Summary Cards - Improved Layout */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
        <Card className="overflow-hidden">
          <CardContent className="pt-4 pb-4 px-4">
            <div className="flex items-start justify-between">
              <div className="flex-1 min-w-0">
                <p className="text-xs sm:text-sm font-medium text-muted-foreground mb-1 truncate">
                  Total Balance
                </p>
                <p className="text-xl sm:text-2xl font-bold truncate" title={formatCurrency(ledgerSummary.totalBalance)}>
                  {formatCurrency(ledgerSummary.totalBalance)}
                </p>
              </div>
              <DollarSign className="h-6 w-6 sm:h-8 sm:w-8 text-blue-600 flex-shrink-0 ml-2" />
            </div>
          </CardContent>
        </Card>

        <Card className="overflow-hidden">
          <CardContent className="pt-4 pb-4 px-4">
            <div className="flex items-start justify-between">
              <div className="flex-1 min-w-0">
                <p className="text-xs sm:text-sm font-medium text-muted-foreground mb-1 truncate">
                  Monthly Income
                </p>
                <p className="text-xl sm:text-2xl font-bold text-green-600 truncate" title={formatCurrency(ledgerSummary.monthlyIncome)}>
                  {formatCurrency(ledgerSummary.monthlyIncome)}
                </p>
              </div>
              <TrendingUp className="h-6 w-6 sm:h-8 sm:w-8 text-green-600 flex-shrink-0 ml-2" />
            </div>
          </CardContent>
        </Card>

        <Card className="overflow-hidden">
          <CardContent className="pt-4 pb-4 px-4">
            <div className="flex items-start justify-between">
              <div className="flex-1 min-w-0">
                <p className="text-xs sm:text-sm font-medium text-muted-foreground mb-1 truncate">
                  Monthly Expenses
                </p>
                <p className="text-xl sm:text-2xl font-bold text-red-600 truncate" title={formatCurrency(ledgerSummary.monthlyExpenses)}>
                  {formatCurrency(ledgerSummary.monthlyExpenses)}
                </p>
              </div>
              <TrendingDown className="h-6 w-6 sm:h-8 sm:w-8 text-red-600 flex-shrink-0 ml-2" />
            </div>
          </CardContent>
        </Card>

        <Card className="overflow-hidden">
          <CardContent className="pt-4 pb-4 px-4">
            <div className="flex items-start justify-between">
              <div className="flex-1 min-w-0">
                <p className="text-xs sm:text-sm font-medium text-muted-foreground mb-1 truncate">
                  Net Profit
                </p>
                <p className={`text-xl sm:text-2xl font-bold truncate ${
                  ledgerSummary.netProfit >= 0 ? 'text-purple-600' : 'text-red-600'
                }`} title={formatCurrency(ledgerSummary.netProfit)}>
                  {formatCurrency(ledgerSummary.netProfit)}
                </p>
              </div>
              <Calendar className="h-6 w-6 sm:h-8 sm:w-8 text-purple-600 flex-shrink-0 ml-2" />
            </div>
          </CardContent>
        </Card>
      </div>

      <Card className="mb-6">
        <CardContent className="pt-6">
          <div className="flex flex-col sm:flex-row gap-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
              <Input 
                placeholder="Search transactions..." 
                className="pl-10"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <Button variant="outline" className="w-full sm:w-auto">
              <Filter className="mr-2 h-4 w-4" />
              Filter
            </Button>
          </div>
        </CardContent>
      </Card>

      <Tabs defaultValue="all" className="w-full">
        <TabsList className="grid w-full grid-cols-2 sm:grid-cols-4">
          <TabsTrigger value="all" className="text-xs sm:text-sm">All Transactions</TabsTrigger>
          <TabsTrigger value="credits" className="text-xs sm:text-sm">Credits</TabsTrigger>
          <TabsTrigger value="debits" className="text-xs sm:text-sm">Debits</TabsTrigger>
          <TabsTrigger value="summary" className="text-xs sm:text-sm">Account Summary</TabsTrigger>
        </TabsList>
        
        <TabsContent value="all" className="mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Transaction History</CardTitle>
              <CardDescription>Complete record of all financial transactions</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {filteredTransactions.length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">
                      {searchTerm ? 'No transactions found matching your search.' : 'No transactions found.'}
                    </p>
                  </div>
                ) : (
                  filteredTransactions
                    .filter(transaction => transaction != null)
                    .map((transaction) => (
                      <div key={transaction.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 border rounded-lg gap-4">
                        <div className="flex items-center space-x-4 flex-1 min-w-0">
                          <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center flex-shrink-0">
                            {getTransactionIcon(transaction.type)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <h3 className="font-semibold truncate">{transaction.description}</h3>
                            <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                              <span className="truncate">{transaction.id.substring(0, 8)}</span>
                              <span>•</span>
                              <span className="truncate">Ref: {transaction.reference}</span>
                            </div>
                            <span className={`inline-block text-xs px-2 py-1 rounded-full mt-1 ${getCategoryColor(transaction.category)}`}>
                              {transaction.category}
                            </span>
                          </div>
                        </div>
                        <div className="text-left sm:text-right flex-shrink-0">
                          <p className={`font-bold text-lg ${getTransactionColor(transaction.type)}`}>
                            {transaction.type === 'credit' ? '+' : '-'}{formatCurrency(transaction.amount)}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            Balance: {formatCurrency(transaction.balance)}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {(() => {
                              try {
                                return new Date(transaction.date).toLocaleDateString();
                              } catch {
                                return 'Invalid Date';
                              }
                            })()}
                          </p>
                        </div>
                      </div>
                    ))
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
        
        <TabsContent value="credits" className="mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Credit Transactions</CardTitle>
              <CardDescription>Income and credit entries</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {filteredTransactions.filter(t => t && t.type === 'credit').length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">No credit transactions found.</p>
                  </div>
                ) : (
                  filteredTransactions
                    .filter(t => t != null && t.type === 'credit')
                    .map((transaction) => (
                      <div key={transaction.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 border rounded-lg gap-4">
                        <div className="flex items-center space-x-4 flex-1 min-w-0">
                          <div className="w-10 h-10 bg-green-100 rounded-full flex items-center justify-center flex-shrink-0">
                            {getTransactionIcon(transaction.type)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <h3 className="font-semibold truncate">{transaction.description}</h3>
                            <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                              <span className="truncate">{transaction.id.substring(0, 8)}</span>
                              <span>•</span>
                              <span className="truncate">Ref: {transaction.reference}</span>
                            </div>
                            <span className={`inline-block text-xs px-2 py-1 rounded-full mt-1 ${getCategoryColor(transaction.category)}`}>
                              {transaction.category}
                            </span>
                          </div>
                        </div>
                        <div className="text-left sm:text-right flex-shrink-0">
                          <p className="font-bold text-lg text-green-600">
                            +{formatCurrency(transaction.amount)}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            Balance: {formatCurrency(transaction.balance)}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {(() => {
                              try {
                                return new Date(transaction.date).toLocaleDateString();
                              } catch {
                                return 'Invalid Date';
                              }
                            })()}
                          </p>
                        </div>
                      </div>
                    ))
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
        
        <TabsContent value="debits" className="mt-6">
          <Card>
            <CardHeader>
              <CardTitle>Debit Transactions</CardTitle>
              <CardDescription>Expenses and debit entries</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {filteredTransactions.filter(t => t && t.type === 'debit').length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">No debit transactions found.</p>
                  </div>
                ) : (
                  filteredTransactions
                    .filter(t => t != null && t.type === 'debit')
                    .map((transaction) => (
                      <div key={transaction.id} className="flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 border rounded-lg gap-4">
                        <div className="flex items-center space-x-4 flex-1 min-w-0">
                          <div className="w-10 h-10 bg-red-100 rounded-full flex items-center justify-center flex-shrink-0">
                            {getTransactionIcon(transaction.type)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <h3 className="font-semibold truncate">{transaction.description}</h3>
                            <div className="flex items-center gap-2 text-sm text-muted-foreground flex-wrap">
                              <span className="truncate">{transaction.id.substring(0, 8)}</span>
                              <span>•</span>
                              <span className="truncate">Ref: {transaction.reference}</span>
                            </div>
                            <span className={`inline-block text-xs px-2 py-1 rounded-full mt-1 ${getCategoryColor(transaction.category)}`}>
                              {transaction.category}
                            </span>
                          </div>
                        </div>
                        <div className="text-left sm:text-right flex-shrink-0">
                          <p className="font-bold text-lg text-red-600">
                            -{formatCurrency(transaction.amount)}
                          </p>
                          <p className="text-sm text-muted-foreground">
                            Balance: {formatCurrency(transaction.balance)}
                          </p>
                          <p className="text-xs text-muted-foreground">
                            {(() => {
                              try {
                                return new Date(transaction.date).toLocaleDateString();
                              } catch {
                                return 'Invalid Date';
                              }
                            })()}
                          </p>
                        </div>
                      </div>
                    ))
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
        
        <TabsContent value="summary" className="mt-6">
          <div className="grid gap-6">
            <Card>
              <CardHeader>
                <CardTitle>Account Summary</CardTitle>
                <CardDescription>Overview of account balances and performance</CardDescription>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <div className="text-center p-4 border rounded-lg">
                    <h3 className="font-semibold text-lg">Revenue</h3>
                    <p className="text-2xl sm:text-3xl font-bold text-green-600">
                      {formatCurrency(ledgerSummary.monthlyIncome)}
                    </p>
                    <p className="text-sm text-muted-foreground">This month</p>
                  </div>
                  <div className="text-center p-4 border rounded-lg">
                    <h3 className="font-semibold text-lg">Expenses</h3>
                    <p className="text-2xl sm:text-3xl font-bold text-red-600">
                      {formatCurrency(ledgerSummary.monthlyExpenses)}
                    </p>
                    <p className="text-sm text-muted-foreground">This month</p>
                  </div>
                  <div className="text-center p-4 border rounded-lg">
                    <h3 className="font-semibold text-lg">Net Income</h3>
                    <p className={`text-2xl sm:text-3xl font-bold ${
                      ledgerSummary.netProfit >= 0 ? 'text-blue-600' : 'text-red-600'
                    }`}>
                      {formatCurrency(ledgerSummary.netProfit)}
                    </p>
                    <p className="text-sm text-muted-foreground">This month</p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>

    </div>
  );
};

export default Ledger;

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { DollarSign, Download, Calculator, Users, Calendar, Loader2, Plus, Edit, Trash2, Search, Building2, CheckSquare, Square } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Checkbox } from "@/components/ui/checkbox";
import { useState, useEffect, useCallback } from "react";
import { useSearchParams } from "react-router-dom";
import { selectRecords, deleteRecord, selectOne, updateRecord } from '@/services/api/core';
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import PayrollFormDialog from "@/components/shared/PayrollFormDialog";
import PayrollPeriodFormDialog from "@/components/PayrollPeriodFormDialog";
import DeleteConfirmDialog from "@/components/shared/DeleteConfirmDialog";

interface PayrollRecord {
  id: string;
  employee: string;
  position: string;
  baseSalary: number;
  overtime: number;
  deductions: number;
  netPay: number;
  status: string;
  payPeriod: string;
  employee_id?: string;
}

interface PayrollSummary {
  totalEmployees: number;
  totalPayroll: number;
  averageSalary: number;
  pendingPayroll: number;
}

const Payroll = () => {
  const { toast } = useToast();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  
  // Get department filter from URL
  const urlDepartmentId = searchParams.get('department');
  const urlDepartmentName = searchParams.get('name');
  
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedPeriod, setSelectedPeriod] = useState<string>('');
  const [payrollSummary, setPayrollSummary] = useState<PayrollSummary>({
    totalEmployees: 0,
    totalPayroll: 0,
    averageSalary: 0,
    pendingPayroll: 0
  });
  const [payrollRecords, setPayrollRecords] = useState<PayrollRecord[]>([]);
  const [payrollPeriods, setPayrollPeriods] = useState<unknown[]>([]);
  const [payrollFormOpen, setPayrollFormOpen] = useState(false);
  const [selectedPayroll, setSelectedPayroll] = useState<unknown>(null);
  const [periodFormOpen, setPeriodFormOpen] = useState(false);
  const [selectedPeriodObj, setSelectedPeriodObj] = useState<unknown>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<{ type: string; item: unknown } | null>(null);
  const [selectedRecords, setSelectedRecords] = useState<Set<string>>(new Set());
  const [bulkActionLoading, setBulkActionLoading] = useState(false);

  useEffect(() => {
    fetchPayrollData();
    fetchPayrollPeriods();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (selectedPeriod) {
      fetchPayrollData();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedPeriod, urlDepartmentId]);

  const fetchPayrollPeriods = useCallback(async () => {
    try {
      const periods = await selectRecords('payroll_periods', {
        orderBy: 'end_date DESC',
      });
      setPayrollPeriods(periods || []);
      if (periods && periods.length > 0 && !selectedPeriod) {
        setSelectedPeriod(periods[0].id);
      }
    } catch (error) {
      console.error('Error fetching payroll periods:', error);
    }
  }, [selectedPeriod]);

  const fetchPayrollData = useCallback(async () => {
    try {
      setLoading(true);
      
      // If filtering by department, get user IDs in that department
      let departmentUserIds: string[] = [];
      if (urlDepartmentId) {
        const assignments = await selectRecords('team_assignments', {
          where: { department_id: urlDepartmentId, is_active: true },
          select: 'user_id',
        });
        departmentUserIds = (assignments || []).map((ta: unknown) => (ta as any).user_id).filter(Boolean);
      }
      
      // Get selected or most recent pay period
      let periodId = selectedPeriod;
      if (!periodId && payrollPeriods.length > 0) {
        periodId = payrollPeriods[0].id;
        setSelectedPeriod(periodId);
      }

      // Fetch payroll records for selected period
      let payrollData: unknown[] = [];
      if (periodId) {
        payrollData = await selectRecords('payroll', {
          where: { payroll_period_id: periodId },
          orderBy: 'created_at DESC',
        });
      }

      // Filter by department if specified
      // Note: payroll.employee_id is employee_details.id, not user_id
      // So we need to map employee_details.id to user_id first
      if (urlDepartmentId && departmentUserIds.length > 0) {
        // Get employee_details for the payroll records to find their user_ids
        const payrollEmployeeIds = payrollData.map(p => p.employee_id).filter(Boolean);
        if (payrollEmployeeIds.length > 0) {
          const payrollEmployees = await selectRecords('employee_details', {
            filters: [
              { column: 'id', operator: 'in', value: payrollEmployeeIds }
            ]
          });
          
          const employeeIdToUserId = new Map(payrollEmployees.map((e: unknown) => [e.id, e.user_id]));
          
          // Filter payroll records where employee's user_id is in department
          payrollData = payrollData.filter((p: unknown) => {
            const userId = employeeIdToUserId.get(p.employee_id);
            return userId && departmentUserIds.includes(userId);
          });
        } else {
          payrollData = [];
        }
      }

      // Fetch employee details and profiles for names
      // IMPORTANT: payroll.employee_id is employee_details.id, not user_id
      const employeeDetailIds = payrollData.map(p => p.employee_id).filter(Boolean);
      let employees: unknown[] = [];
      let profiles: unknown[] = [];

      if (employeeDetailIds.length > 0) {
        // Fetch employee_details using their id (not user_id)
        employees = await selectRecords('employee_details', {
          filters: [
            { column: 'id', operator: 'in', value: employeeDetailIds }
          ]
        });

        const userIds = employees.map((e: unknown) => e.user_id).filter(Boolean);
        if (userIds.length > 0) {
          profiles = await selectRecords('profiles', {
            filters: [
              { column: 'user_id', operator: 'in', value: userIds }
            ]
          });
        }
      }

      const profileMap = new Map(profiles.map((p: unknown) => [p.user_id, p.full_name]));
      // Map by employee_details.id for payroll lookup
      const employeeMap = new Map(employees.map((e: unknown) => [e.id, e]));

      // Get current period info
      const currentPeriod = payrollPeriods.find(p => p.id === periodId) || payrollPeriods[0];

      // Transform payroll data - map database field names to frontend field names
      const transformedRecords: PayrollRecord[] = payrollData.map((record: unknown) => {
        const employee = employeeMap.get(record.employee_id); // employee_id is employee_details.id
        const fullName = employee?.user_id 
          ? (profileMap.get(employee.user_id) || `${employee.first_name} ${employee.last_name}`.trim())
          : 'Unknown Employee';
        const position = employee?.emp_position || employee?.employment_type || 'N/A';

        // Map database fields to frontend fields
        const baseSalary = Number(record.base_salary || 0);
        const overtime = Number(record.overtime_pay || 0);
        const deductions = Number(record.deductions || 0);
        // Database uses net_salary, but frontend expects net_pay
        const netPay = Number(record.net_salary || record.net_pay || 0);

        const periodName = currentPeriod 
          ? `${new Date(currentPeriod.start_date).toLocaleDateString('en-US', { month: 'long', year: 'numeric' })}`
          : 'Current Period';

        return {
          id: record.id,
          employee: fullName,
          position,
          baseSalary,
          overtime,
          deductions,
          netPay,
          status: record.status || 'draft',
          payPeriod: periodName,
          employee_id: record.employee_id // This is employee_details.id
        };
      });

      setPayrollRecords(transformedRecords);

      // Calculate summary
      const totalPayroll = transformedRecords.reduce((sum, r) => sum + r.netPay, 0);
      const averageSalary = transformedRecords.length > 0 
        ? totalPayroll / transformedRecords.length 
        : 0;
      const pendingPayroll = transformedRecords.filter(r => r.status === 'draft').length;

      // Get total active employees
      const activeEmployees = await selectRecords('employee_details', {
        where: { is_active: true },
      });

      setPayrollSummary({
        totalEmployees: activeEmployees?.length || 0,
        totalPayroll,
        averageSalary: Math.round(averageSalary),
        pendingPayroll
      });

    } catch (error: unknown) {
      console.error('Error fetching payroll data:', error);
      toast({
        title: "Error",
        description: "Failed to load payroll data. Please try again.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  }, [urlDepartmentId, selectedPeriod, payrollPeriods, toast]);

  if (loading) {
    return (
      <div className="p-6">
        <div className="flex justify-center items-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin" />
          <span className="ml-2 text-muted-foreground">Loading payroll data...</span>
        </div>
      </div>
    );
  }


  const handleNewPayroll = () => {
    setSelectedPayroll(null);
    setPayrollFormOpen(true);
  };

  const handleEditPayroll = async (payroll: unknown) => {
    try {
      // Fetch full payroll record from database
      const fullRecord = await selectOne('payroll', { id: payroll.id });
      if (fullRecord) {
        // Map database field names to frontend field names
        setSelectedPayroll({
          id: fullRecord.id,
          employee_id: fullRecord.employee_id, // This is employee_details.id
          payroll_period_id: fullRecord.payroll_period_id,
          base_salary: parseFloat(String(fullRecord.base_salary || 0)),
          overtime_pay: parseFloat(String(fullRecord.overtime_pay || 0)),
          bonuses: parseFloat(String(fullRecord.allowances || 0)), // allowances maps to bonuses in UI
          deductions: parseFloat(String(fullRecord.deductions || 0)),
          gross_pay: parseFloat(String(fullRecord.gross_salary || fullRecord.gross_pay || 0)), // gross_salary maps to gross_pay
          tax_deductions: parseFloat(String(fullRecord.tax_amount || fullRecord.tax_deductions || 0)), // tax_amount maps to tax_deductions
          net_pay: parseFloat(String(fullRecord.net_salary || fullRecord.net_pay || 0)), // net_salary maps to net_pay
          hours_worked: parseFloat(String(fullRecord.hours_worked || 0)),
          overtime_hours: parseFloat(String(fullRecord.overtime_hours || 0)),
          status: fullRecord.status,
          notes: fullRecord.notes || '',
        });
      }
      setPayrollFormOpen(true);
    } catch (error) {
      console.error('Error fetching payroll record:', error);
      toast({
        title: 'Error',
        description: 'Failed to load payroll record details',
        variant: 'destructive',
      });
    }
  };

  const handleDeletePayroll = (payroll: unknown) => {
    setItemToDelete({ type: 'payroll', item: payroll });
    setDeleteDialogOpen(true);
  };

  const handleNewPeriod = () => {
    setSelectedPeriodObj(null);
    setPeriodFormOpen(true);
  };

  const handleEditPeriod = (period: unknown) => {
    setSelectedPeriodObj(period);
    setPeriodFormOpen(true);
  };

  const handleDeletePeriod = (period: unknown) => {
    setItemToDelete({ type: 'period', item: period });
    setDeleteDialogOpen(true);
  };

  const handlePayrollSaved = () => {
    fetchPayrollData();
  };

  const handlePeriodSaved = () => {
    fetchPayrollPeriods();
    fetchPayrollData();
  };

  const handleDeleted = async () => {
    if (!itemToDelete) return;

    try {
      if (itemToDelete.type === 'payroll') {
        await deleteRecord('payroll', { id: itemToDelete.item.id });
        toast({
          title: 'Success',
          description: 'Payroll record deleted successfully',
        });
        fetchPayrollData();
      } else if (itemToDelete.type === 'period') {
        await deleteRecord('payroll_periods', { id: itemToDelete.item.id });
        toast({
          title: 'Success',
          description: 'Payroll period deleted successfully',
        });
        fetchPayrollPeriods();
        if (selectedPeriod === itemToDelete.item.id) {
          setSelectedPeriod('');
        }
      }
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete item',
        variant: 'destructive',
      });
    }

    setItemToDelete(null);
    setDeleteDialogOpen(false);
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'paid': return 'default';
      case 'approved': return 'default';
      case 'draft': return 'secondary';
      case 'processing': return 'secondary';
      default: return 'secondary';
    }
  };

  const handleExportReport = async () => {
    try {
      if (filteredRecords.length === 0) {
        toast({
          title: 'No Data',
          description: 'No payroll records to export',
          variant: 'destructive',
        });
        return;
      }

      // Prepare CSV data
      const headers = ['Employee', 'Position', 'Base Salary', 'Overtime', 'Deductions', 'Net Pay', 'Status', 'Period'];
      const rows = filteredRecords.map(record => [
        record.employee,
        record.position,
        record.baseSalary.toFixed(2),
        record.overtime.toFixed(2),
        record.deductions.toFixed(2),
        record.netPay.toFixed(2),
        record.status,
        record.payPeriod
      ]);

      // Create CSV content
      const csvContent = [
        headers.join(','),
        ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
      ].join('\n');

      // Create and download file
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `payroll-report-${selectedPeriod || 'all'}-${new Date().toISOString().split('T')[0]}.csv`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast({
        title: 'Success',
        description: 'Payroll report exported successfully',
      });
    } catch (error: unknown) {
      console.error('Error exporting report:', error);
      toast({
        title: 'Error',
        description: 'Failed to export payroll report',
        variant: 'destructive',
      });
    }
  };

  const handleDownloadPaySlip = async (record: PayrollRecord) => {
    try {
      // Fetch full payroll record
      const fullRecord = await selectOne('payroll', { id: record.id });
      
      if (!fullRecord) {
        toast({
          title: 'Error',
          description: 'Payroll record not found',
          variant: 'destructive',
        });
        return;
      }

      // Fetch employee details
      const employee = await selectOne('employee_details', { id: record.employee_id });
      if (!employee) {
        toast({
          title: 'Error',
          description: 'Employee details not found',
          variant: 'destructive',
        });
        return;
      }

      // Fetch profile for full name
      const profile = await selectOne('profiles', { user_id: employee.user_id });
      const employeeName = profile?.full_name || `${employee.first_name} ${employee.last_name}`.trim();

      // Fetch payroll period
      const period = await selectOne('payroll_periods', { id: fullRecord.payroll_period_id });

      // Generate pay slip HTML
      const paySlipHTML = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Pay Slip - ${employeeName}</title>
  <style>
    body { font-family: Arial, sans-serif; padding: 20px; }
    .header { text-align: center; margin-bottom: 30px; }
    .details { margin-bottom: 20px; }
    .details table { width: 100%; border-collapse: collapse; }
    .details td { padding: 8px; border-bottom: 1px solid #ddd; }
    .details td:first-child { font-weight: bold; width: 40%; }
    .summary { margin-top: 30px; }
    .summary table { width: 100%; border-collapse: collapse; }
    .summary td { padding: 10px; border: 1px solid #ddd; }
    .summary td:first-child { font-weight: bold; }
    .total { font-size: 18px; font-weight: bold; color: #059669; }
  </style>
</head>
<body>
  <div class="header">
    <h1>PAY SLIP</h1>
    <p>${period?.name || 'Payroll Period'}</p>
  </div>
  
  <div class="details">
    <table>
      <tr><td>Employee Name:</td><td>${employeeName}</td></tr>
      <tr><td>Employee ID:</td><td>${employee.employee_id || record.employee_id.substring(0, 8)}</td></tr>
      <tr><td>Position:</td><td>${record.position}</td></tr>
      <tr><td>Period:</td><td>${period ? `${new Date(period.start_date).toLocaleDateString()} - ${new Date(period.end_date).toLocaleDateString()}` : 'N/A'}</td></tr>
      <tr><td>Status:</td><td>${record.status.toUpperCase()}</td></tr>
    </table>
  </div>
  
  <div class="summary">
    <h2>Earnings & Deductions</h2>
    <table>
      <tr>
        <td>Base Salary</td>
        <td style="text-align: right;">₹${record.baseSalary.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
      </tr>
      <tr>
        <td>Overtime Pay</td>
        <td style="text-align: right;">₹${record.overtime.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
      </tr>
      <tr>
        <td>Deductions</td>
        <td style="text-align: right; color: #dc2626;">-₹${record.deductions.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
      </tr>
      <tr class="total">
        <td>Net Pay</td>
        <td style="text-align: right;">₹${record.netPay.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</td>
      </tr>
    </table>
  </div>
  
  <div style="margin-top: 40px; text-align: center; color: #666; font-size: 12px;">
    <p>This is a computer-generated pay slip.</p>
    <p>Generated on: ${new Date().toLocaleString()}</p>
  </div>
</body>
</html>
      `;

      // Create and download file
      const blob = new Blob([paySlipHTML], { type: 'text/html;charset=utf-8;' });
      const link = document.createElement('a');
      const url = URL.createObjectURL(blob);
      link.setAttribute('href', url);
      link.setAttribute('download', `payslip-${employeeName.replace(/\s+/g, '-')}-${period?.name?.replace(/\s+/g, '-') || 'period'}.html`);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast({
        title: 'Success',
        description: 'Pay slip downloaded successfully',
      });
    } catch (error: unknown) {
      console.error('Error generating pay slip:', error);
      toast({
        title: 'Error',
        description: 'Failed to generate pay slip',
        variant: 'destructive',
      });
    }
  };

  const handleBulkApprove = async () => {
    if (selectedRecords.size === 0) {
      toast({
        title: 'No Selection',
        description: 'Please select at least one payroll record',
        variant: 'destructive',
      });
      return;
    }

    setBulkActionLoading(true);
    try {
      
      const updates = Array.from(selectedRecords).map(id => 
        updateRecord('payroll', { status: 'approved' }, { id }, user?.id)
      );

      await Promise.all(updates);
      
      toast({
        title: 'Success',
        description: `${selectedRecords.size} payroll record(s) approved successfully`,
      });
      
      setSelectedRecords(new Set());
      fetchPayrollData();
    } catch (error: unknown) {
      console.error('Error approving payroll records:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to approve payroll records',
        variant: 'destructive',
      });
    } finally {
      setBulkActionLoading(false);
    }
  };

  const handleBulkMarkPaid = async () => {
    if (selectedRecords.size === 0) {
      toast({
        title: 'No Selection',
        description: 'Please select at least one payroll record',
        variant: 'destructive',
      });
      return;
    }

    setBulkActionLoading(true);
    try {
      
      const updates = Array.from(selectedRecords).map(id => 
        updateRecord('payroll', { 
          status: 'paid',
          paid_at: new Date().toISOString()
        }, { id }, user?.id)
      );

      await Promise.all(updates);
      
      toast({
        title: 'Success',
        description: `${selectedRecords.size} payroll record(s) marked as paid`,
      });
      
      setSelectedRecords(new Set());
      fetchPayrollData();
    } catch (error: unknown) {
      console.error('Error marking payroll records as paid:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to mark payroll records as paid',
        variant: 'destructive',
      });
    } finally {
      setBulkActionLoading(false);
    }
  };

  const handleSelectRecord = (id: string) => {
    setSelectedRecords(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      return newSet;
    });
  };

  const handleSelectAll = () => {
    if (selectedRecords.size === filteredRecords.length) {
      setSelectedRecords(new Set());
    } else {
      setSelectedRecords(new Set(filteredRecords.map(r => r.id)));
    }
  };

  const filteredRecords = payrollRecords.filter(record =>
    record.employee.toLowerCase().includes(searchTerm.toLowerCase()) ||
    record.position.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-3xl font-bold">Payroll</h1>
            {urlDepartmentName && (
              <Badge variant="secondary" className="text-sm">
                <Building2 className="h-3 w-3 mr-1" />
                {decodeURIComponent(urlDepartmentName)}
              </Badge>
            )}
          </div>
          <p className="text-muted-foreground">
            {urlDepartmentName 
              ? `Payroll for ${decodeURIComponent(urlDepartmentName)} department`
              : "Manage employee compensation and payroll processing"}
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleNewPeriod}>
            <Plus className="mr-2 h-4 w-4" />
            New Period
          </Button>
          <Button variant="outline" onClick={handleNewPayroll}>
            <Plus className="mr-2 h-4 w-4" />
            New Payroll
          </Button>
          <Button variant="outline" onClick={handleExportReport}>
            <Download className="mr-2 h-4 w-4" />
            Export Report
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-6">
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <Users className="h-8 w-8 text-blue-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Employees</p>
                <p className="text-2xl font-bold">{payrollSummary.totalEmployees}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <DollarSign className="h-8 w-8 text-green-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Payroll</p>
                <p className="text-2xl font-bold">₹{payrollSummary.totalPayroll.toLocaleString()}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <Calculator className="h-8 w-8 text-purple-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Average Salary</p>
                <p className="text-2xl font-bold">₹{payrollSummary.averageSalary.toLocaleString()}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center">
              <Calendar className="h-8 w-8 text-orange-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Pending</p>
                <p className="text-2xl font-bold">{payrollSummary.pendingPayroll}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      <Tabs defaultValue="payroll" className="space-y-4">
        <TabsList>
          <TabsTrigger value="payroll">Payroll Records</TabsTrigger>
          <TabsTrigger value="periods">Payroll Periods</TabsTrigger>
        </TabsList>

        <TabsContent value="payroll" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <div>
                  <CardTitle>Payroll Records</CardTitle>
                  <CardDescription>
                    {selectedPeriod && payrollPeriods.find(p => p.id === selectedPeriod) 
                      ? `Payroll for ${payrollPeriods.find(p => p.id === selectedPeriod)?.name}`
                      : 'Select a payroll period'}
                    {selectedRecords.size > 0 && (
                      <span className="ml-2 text-primary font-medium">
                        ({selectedRecords.size} selected)
                      </span>
                    )}
                  </CardDescription>
                </div>
                <div className="flex gap-2">
                  {selectedRecords.size > 0 && (
                    <>
                      <Button 
                        size="sm" 
                        variant="outline" 
                        onClick={handleBulkApprove}
                        disabled={bulkActionLoading}
                      >
                        Approve Selected
                      </Button>
                      <Button 
                        size="sm" 
                        variant="outline" 
                        onClick={handleBulkMarkPaid}
                        disabled={bulkActionLoading}
                      >
                        Mark Paid
                      </Button>
                    </>
                  )}
                  <Select value={selectedPeriod} onValueChange={setSelectedPeriod}>
                    <SelectTrigger className="w-[200px]">
                      <SelectValue placeholder="Select period" />
                    </SelectTrigger>
                    <SelectContent>
                      {payrollPeriods.map((period) => (
                        <SelectItem key={period.id} value={period.id}>
                          {period.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
              </div>
            </CardHeader>
            <CardContent>
              <div className="mb-4">
                <div className="relative">
                  <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
                  <Input
                    placeholder="Search employees..."
                    className="pl-10"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                  />
                </div>
              </div>
              <div className="space-y-4">
                {loading ? (
                  <div className="text-center py-8">
                    <Loader2 className="h-8 w-8 animate-spin mx-auto" />
                    <p className="text-muted-foreground mt-2">Loading payroll data...</p>
                  </div>
                ) : filteredRecords.length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">
                      {searchTerm ? 'No payroll records found matching your search.' : 'No payroll records found for the selected period.'}
                    </p>
                    {!searchTerm && (
                      <Button className="mt-4" onClick={handleNewPayroll}>
                        <Plus className="mr-2 h-4 w-4" />
                        Create First Payroll Record
                      </Button>
                    )}
                  </div>
                ) : (
                  <>
                    {filteredRecords.length > 0 && (
                      <div className="mb-4 flex items-center gap-2 pb-2 border-b">
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={handleSelectAll}
                          className="h-8"
                        >
                          {selectedRecords.size === filteredRecords.length ? (
                            <CheckSquare className="h-4 w-4 mr-2" />
                          ) : (
                            <Square className="h-4 w-4 mr-2" />
                          )}
                          Select All
                        </Button>
                      </div>
                    )}
                    {filteredRecords.map((record) => (
                      <div key={record.id} className="border rounded-lg p-4">
                        <div className="flex items-center justify-between mb-4">
                          <div className="flex items-center gap-3 flex-1">
                            <Checkbox
                              checked={selectedRecords.has(record.id)}
                              onCheckedChange={() => handleSelectRecord(record.id)}
                              className="mt-1"
                            />
                            <div className="flex-1">
                              <h3 className="font-semibold">{record.employee}</h3>
                              <p className="text-sm text-muted-foreground">{record.position}</p>
                              <p className="text-xs text-muted-foreground">{record.payPeriod}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <Badge variant={getStatusColor(record.status)}>
                              {record.status}
                            </Badge>
                            <Button size="sm" variant="outline" onClick={() => handleEditPayroll(record)}>
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button size="sm" variant="outline" onClick={() => handleDeletePayroll(record)}>
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </div>
                      
                        <div className="grid grid-cols-2 md:grid-cols-5 gap-4 text-sm">
                          <div>
                            <p className="text-muted-foreground">Base Salary</p>
                            <p className="font-medium">₹{record.baseSalary.toLocaleString()}</p>
                          </div>
                          <div>
                            <p className="text-muted-foreground">Overtime</p>
                            <p className="font-medium text-green-600">+₹{record.overtime}</p>
                          </div>
                          <div>
                            <p className="text-muted-foreground">Deductions</p>
                            <p className="font-medium text-red-600">-₹{record.deductions}</p>
                          </div>
                          <div>
                            <p className="text-muted-foreground">Net Pay</p>
                            <p className="font-bold text-lg">₹{record.netPay.toLocaleString()}</p>
                          </div>
                          <div className="flex justify-end">
                            <Button size="sm" variant="outline" onClick={() => handleDownloadPaySlip(record)}>
                              <Download className="mr-1 h-3 w-3" />
                              Pay Slip
                            </Button>
                          </div>
                        </div>
                      </div>
                    ))}
                  </>
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="periods" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <div>
                  <CardTitle>Payroll Periods</CardTitle>
                  <CardDescription>Manage payroll periods for organizing payroll records</CardDescription>
                </div>
                <Button onClick={handleNewPeriod}>
                  <Plus className="mr-2 h-4 w-4" />
                  New Period
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              <div className="space-y-4">
                {payrollPeriods.length === 0 ? (
                  <div className="text-center py-8">
                    <p className="text-muted-foreground">No payroll periods found. Create your first period to get started.</p>
                  </div>
                ) : (
                  payrollPeriods.map((period) => (
                    <div key={period.id} className="border rounded-lg p-4">
                      <div className="flex items-center justify-between">
                        <div>
                          <h3 className="font-semibold">{period.name}</h3>
                          <p className="text-sm text-muted-foreground">
                            {new Date(period.start_date).toLocaleDateString()} - {new Date(period.end_date).toLocaleDateString()}
                          </p>
                          {period.pay_date && (
                            <p className="text-xs text-muted-foreground">
                              Pay Date: {new Date(period.pay_date).toLocaleDateString()}
                            </p>
                          )}
                        </div>
                        <div className="flex items-center gap-2">
                          <Badge variant={
                            period.status === 'paid' ? 'default' : 
                            period.status === 'approved' ? 'default' : 
                            period.status === 'processing' ? 'secondary' : 
                            'outline'
                          }>
                            {period.status}
                          </Badge>
                          <Button size="sm" variant="outline" onClick={() => handleEditPeriod(period)}>
                            <Edit className="h-4 w-4" />
                          </Button>
                          <Button size="sm" variant="outline" onClick={() => handleDeletePeriod(period)}>
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      <PayrollFormDialog
        isOpen={payrollFormOpen}
        onClose={() => setPayrollFormOpen(false)}
        payroll={selectedPayroll}
        onPayrollSaved={handlePayrollSaved}
        payrollPeriodId={selectedPeriod}
      />

      <PayrollPeriodFormDialog
        isOpen={periodFormOpen}
        onClose={() => setPeriodFormOpen(false)}
        period={selectedPeriodObj}
        onPeriodSaved={handlePeriodSaved}
      />

      <DeleteConfirmDialog
        isOpen={deleteDialogOpen}
        onClose={() => {
          setDeleteDialogOpen(false);
          setItemToDelete(null);
        }}
        onDeleted={handleDeleted}
        itemType={itemToDelete?.type === 'payroll' ? 'Payroll Record' : 'Payroll Period'}
        itemName={itemToDelete?.item?.employee || itemToDelete?.item?.name || ''}
        itemId={itemToDelete?.item?.id || ''}
        tableName={itemToDelete?.type === 'payroll' ? 'payroll' : 'payroll_periods'}
      />
    </div>
  );
};

export default Payroll;

import React, { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ReimbursementFormDialog } from "@/components/shared/ReimbursementFormDialog";
import { ReimbursementReviewDialog } from "@/components/ReimbursementReviewDialog";
import { useToast } from "@/hooks/use-toast";
import { db } from '@/lib/database';
import { useAuth } from "@/hooks/useAuth";
import { Plus, Search, DollarSign, Clock, CheckCircle, XCircle, Eye, Edit, Trash2 } from "lucide-react";
import { format } from "date-fns";

interface ReimbursementRequest {
  id: string;
  employee_id: string;
  amount: number;
  currency: string;
  expense_date: string;
  description: string;
  business_purpose: string;
  status: string;
  submitted_at: string;
  created_at: string;
  expense_categories: {
    name: string;
  };
  profiles?: {
    full_name: string;
  };
}

export const Reimbursements: React.FC = () => {
  const { user, userRole } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [showReviewDialog, setShowReviewDialog] = useState(false);
  const [selectedRequest, setSelectedRequest] = useState<ReimbursementRequest | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [requests, setRequests] = useState<ReimbursementRequest[]>([]);
  const [stats, setStats] = useState({
    total: 0,
    pending: 0,
    approved: 0,
    rejected: 0,
    totalAmount: 0,
  });

  const isFinanceManager = userRole === 'agency_admin' || userRole === 'manager' || userRole === 'super_admin';

  useEffect(() => {
    if (user) {
      fetchReimbursements();
    }
  }, [user]);

  const fetchReimbursements = async () => {
    try {
      setLoading(true);
      
      // Fetch reimbursement requests
      let query = db
        .from("reimbursement_requests")
        .select("*");
      
      // Filter by employee if not finance manager
      // Use employee_id if available, otherwise fall back to user_id
      if (!isFinanceManager && user) {
        // Try employee_id first, fall back to user_id
        query = query.or(`employee_id.eq.${user.id},user_id.eq.${user.id}`);
      }
      
      const { data: requestsData, error: requestsError } = await query
        .order("created_at", { ascending: false });

      let requests: unknown[] = [];
      if (requestsError) {
        // If employee_id column doesn't exist, try with user_id only
        if (requestsError.message?.includes('employee_id') || requestsError.code === '42703') {
          let fallbackQuery = db
            .from("reimbursement_requests")
            .select("*");
          
          if (!isFinanceManager && user) {
            fallbackQuery = fallbackQuery.eq("user_id", user.id);
          }
          
          const { data: fallbackData, error: fallbackError } = await fallbackQuery
            .order("created_at", { ascending: false });
          
          if (fallbackError) throw fallbackError;
          requests = (fallbackData as unknown[]) || [];
        } else {
          throw requestsError;
        }
      } else {
        requests = (requestsData as unknown[]) || [];
      }
      
      // Fetch expense categories
      const categoryIds = [...new Set(requests.map((r: unknown) => r.category_id).filter(Boolean))];
      let categories: unknown[] = [];
      if (categoryIds.length > 0) {
        const { data: categoriesData, error: categoriesError } = await db
          .from("expense_categories")
          .select("id, name")
          .in("id", categoryIds);
        
        if (!categoriesError) {
          categories = (categoriesData as unknown) || [];
        }
      }

      // Fetch profiles for employee names
      // Use employee_id if available, otherwise use user_id
      const employeeIds = [...new Set(
        requests
          .map((r: unknown) => r.employee_id || r.user_id)
          .filter(Boolean)
      )];
      let profiles: unknown[] = [];
      if (employeeIds.length > 0) {
        const { data: profilesData, error: profilesError } = await db
          .from("profiles")
          .select("user_id, full_name")
          .in("user_id", employeeIds);
        
        if (!profilesError) {
          profiles = (profilesData as unknown) || [];
        }
      }

      // Create maps for quick lookup
      const categoryMap = new Map(categories.map((c: unknown) => [c.id, c]));
      const profileMap = new Map(profiles.map((p: unknown) => [p.user_id, p]));

      // Combine data
      const enrichedRequests: ReimbursementRequest[] = requests.map((req: unknown) => ({
        ...req,
        expense_categories: categoryMap.get(req.category_id) || { name: "Unknown" },
        profiles: profileMap.get(req.employee_id) || undefined,
      }));

      setRequests(enrichedRequests);
      
      // Calculate stats
      const totalAmount = enrichedRequests.reduce((sum, req) => sum + Number(req.amount), 0);
      const pending = enrichedRequests.filter(req => req.status === 'submitted' || req.status === 'draft').length;
      const approved = enrichedRequests.filter(req => req.status === 'approved').length;
      const rejected = enrichedRequests.filter(req => req.status === 'rejected').length;

      setStats({
        total: enrichedRequests.length,
        pending,
        approved,
        rejected,
        totalAmount,
      });
    } catch (error: unknown) {
      console.error("Error fetching reimbursements:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to load reimbursement requests",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewRequest = (request: ReimbursementRequest) => {
    setSelectedRequest(request);
    setShowReviewDialog(true);
  };

  const handleEditRequest = (request: ReimbursementRequest) => {
    setSelectedRequest(request);
    setShowForm(true);
  };

  const handleDeleteRequest = async (request: ReimbursementRequest) => {
    if (!window.confirm(`Are you sure you want to delete this reimbursement request? This action cannot be undone.`)) {
      return;
    }

    try {
      // First delete attachments if any
      const { error: attachmentsError } = await db
        .from("reimbursement_attachments")
        .delete()
        .eq("reimbursement_id", request.id);

      if (attachmentsError) {
        console.error("Error deleting attachments:", attachmentsError);
      }

      // Then delete the request
      const { error } = await db
        .from("reimbursement_requests")
        .delete()
        .eq("id", request.id);

      if (error) throw error;

      toast({
        title: "Success",
        description: "Reimbursement request deleted successfully",
      });

      fetchReimbursements();
    } catch (error: unknown) {
      console.error("Error deleting reimbursement:", error);
      toast({
        title: "Error",
        description: error?.message || "Failed to delete reimbursement request",
        variant: "destructive",
      });
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case "draft":
        return "bg-muted text-muted-foreground";
      case "submitted":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-300";
      case "approved":
        return "bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-300";
      case "rejected":
        return "bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-300";
      case "paid":
        return "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-300";
      default:
        return "bg-muted text-muted-foreground";
    }
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "submitted":
        return <Clock className="h-4 w-4" />;
      case "approved":
      case "paid":
        return <CheckCircle className="h-4 w-4" />;
      case "rejected":
        return <XCircle className="h-4 w-4" />;
      default:
        return null;
    }
  };

  const filteredRequests = requests.filter(request =>
    request.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
    request.expense_categories?.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold text-foreground">
            {isFinanceManager ? "Reimbursement Requests" : "My Reimbursements"}
          </h1>
          <p className="text-muted-foreground">
            {isFinanceManager 
              ? "Review and approve employee reimbursement requests" 
              : "Submit and track your expense reimbursement requests"
            }
          </p>
        </div>
        <Button onClick={() => setShowForm(true)} className="flex items-center gap-2">
          <Plus className="h-4 w-4" />
          New Request
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Requests</p>
                <p className="text-2xl font-bold">{stats.total}</p>
              </div>
              <DollarSign className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Pending</p>
                <p className="text-2xl font-bold text-blue-600">{stats.pending}</p>
              </div>
              <Clock className="h-8 w-8 text-blue-600" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Approved</p>
                <p className="text-2xl font-bold text-green-600">{stats.approved}</p>
              </div>
              <CheckCircle className="h-8 w-8 text-green-600" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-muted-foreground">Total Amount</p>
                <p className="text-2xl font-bold">${stats.totalAmount.toFixed(2)}</p>
              </div>
              <DollarSign className="h-8 w-8 text-muted-foreground" />
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Search and Filter */}
      <Card>
        <CardHeader>
          <div className="flex flex-col sm:flex-row gap-4 items-start sm:items-center justify-between">
            <CardTitle>Reimbursement Requests</CardTitle>
            <div className="flex items-center gap-2">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground h-4 w-4" />
                <Input
                  placeholder="Search requests..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 w-64"
                />
              </div>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="text-center py-8">Loading...</div>
          ) : filteredRequests.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              {requests.length === 0 ? "No reimbursement requests yet." : "No requests match your search."}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Date</TableHead>
                    {isFinanceManager && <TableHead>Employee</TableHead>}
                    <TableHead>Category</TableHead>
                    <TableHead>Description</TableHead>
                    <TableHead>Amount</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Submitted</TableHead>
                    <TableHead>Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredRequests.map((request) => (
                    <TableRow key={request.id}>
                      <TableCell>
                        {format(new Date(request.expense_date), "MMM dd, yyyy")}
                      </TableCell>
                      {isFinanceManager && (
                        <TableCell>
                          <span className="font-medium">
                            {request.profiles?.full_name || "Unknown Employee"}
                          </span>
                        </TableCell>
                      )}
                      <TableCell>
                        <span className="font-medium">
                          {request.expense_categories?.name || "Unknown"}
                        </span>
                      </TableCell>
                      <TableCell>
                        <div>
                          <p className="font-medium">{request.description}</p>
                          {request.business_purpose && (
                            <p className="text-sm text-muted-foreground">
                              {request.business_purpose}
                            </p>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <span className="font-medium">
                          {request.currency} {Number(request.amount).toFixed(2)}
                        </span>
                      </TableCell>
                      <TableCell>
                        <Badge className={`flex items-center gap-1 ${getStatusColor(request.status)}`}>
                          {getStatusIcon(request.status)}
                          {request.status.charAt(0).toUpperCase() + request.status.slice(1)}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {request.submitted_at
                          ? format(new Date(request.submitted_at), "MMM dd, yyyy")
                          : "Not submitted"}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center gap-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => handleViewRequest(request)}
                            className="flex items-center gap-1"
                          >
                            <Eye className="h-4 w-4" />
                            {isFinanceManager ? "Review" : "View"}
                          </Button>
                          {(request.status === 'draft' || (!isFinanceManager && request.status === 'submitted')) && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleEditRequest(request)}
                              className="flex items-center gap-1"
                            >
                              <Edit className="h-4 w-4" />
                              Edit
                            </Button>
                          )}
                          {(request.status === 'draft' || (!isFinanceManager && request.status === 'submitted')) && (
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => handleDeleteRequest(request)}
                              className="flex items-center gap-1 text-destructive hover:text-destructive"
                            >
                              <Trash2 className="h-4 w-4" />
                              Delete
                            </Button>
                          )}
                        </div>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      <ReimbursementFormDialog
        open={showForm}
        onOpenChange={(open) => {
          setShowForm(open);
          if (!open) {
            setSelectedRequest(null);
          }
        }}
        onSuccess={fetchReimbursements}
        request={selectedRequest}
      />

      <ReimbursementReviewDialog
        open={showReviewDialog}
        onOpenChange={setShowReviewDialog}
        request={selectedRequest}
        onSuccess={fetchReimbursements}
      />
    </div>
  );
};

/**
 * Inventory Adjustments Page
 * Inventory adjustment and correction management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Edit,
  Plus,
  Search,
  Loader2,
  Eye,
  Package,
  Warehouse,
  Calendar,
  MoreVertical,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
} from 'lucide-react';
import {
  getProducts,
  getWarehouses,
  createAdjustment,
  getInventoryTransactions,
  type Product,
  type Warehouse as WarehouseType,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface Adjustment {
  id: string;
  product_id: string;
  variant_id?: string;
  warehouse_id: string;
  quantity: number;
  unit_cost?: number;
  reason?: string;
  notes?: string;
  created_at: string;
  product_name?: string;
  product_sku?: string;
  warehouse_name?: string;
  warehouse_code?: string;
  transaction_type?: string;
}

export default function InventoryAdjustments() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Data
  const [adjustments, setAdjustments] = useState<Adjustment[]>([]);
  const [filteredAdjustments, setFilteredAdjustments] = useState<Adjustment[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);
  const [selectedAdjustment, setSelectedAdjustment] = useState<Adjustment | null>(null);
  const [showAdjustmentDialog, setShowAdjustmentDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [productFilter, setProductFilter] = useState<string>('all');
  const [warehouseFilter, setWarehouseFilter] = useState<string>('all');
  const [typeFilter, setTypeFilter] = useState<string>('all');

  // Adjustment form
  const [adjustmentForm, setAdjustmentForm] = useState({
    product_id: '',
    variant_id: '',
    warehouse_id: '',
    quantity: '',
    unit_cost: '',
    reason: '',
    notes: '',
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchAdjustments(),
          fetchProducts(),
          fetchWarehouses(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading adjustments data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load adjustments',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = adjustments;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(a =>
        a.product_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        a.product_sku?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        a.warehouse_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        a.reason?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Product filter
    if (productFilter !== 'all') {
      filtered = filtered.filter(a => a.product_id === productFilter);
    }

    // Warehouse filter
    if (warehouseFilter !== 'all') {
      filtered = filtered.filter(a => a.warehouse_id === warehouseFilter);
    }

    // Type filter (positive/negative adjustment)
    if (typeFilter !== 'all') {
      if (typeFilter === 'increase') {
        filtered = filtered.filter(a => {
          const qty = typeof a.quantity === 'number' ? a.quantity : parseFloat(String(a.quantity || 0));
          return qty > 0;
        });
      } else if (typeFilter === 'decrease') {
        filtered = filtered.filter(a => {
          const qty = typeof a.quantity === 'number' ? a.quantity : parseFloat(String(a.quantity || 0));
          return qty < 0;
        });
      }
    }

    setFilteredAdjustments(filtered);
  }, [adjustments, searchTerm, productFilter, warehouseFilter, typeFilter]);

  const fetchAdjustments = async () => {
    try {
      setLoading(true);
      // Get adjustments from inventory transactions
      const transactions = await getInventoryTransactions({ transaction_type: 'ADJUSTMENT' });
      
      const adjustmentList: Adjustment[] = transactions.map((tx: unknown) => ({
        id: tx.id,
        product_id: tx.product_id || '',
        variant_id: tx.variant_id,
        warehouse_id: tx.warehouse_id || '',
        quantity: tx.quantity,
        unit_cost: tx.unit_cost,
        reason: tx.notes,
        notes: tx.notes,
        created_at: tx.created_at,
        product_name: tx.product_name,
        product_sku: tx.product_sku,
        warehouse_name: tx.warehouse_name,
        warehouse_code: tx.warehouse_code,
        transaction_type: tx.transaction_type,
      }));

      setAdjustments(adjustmentList);
    } catch (error: unknown) {
      console.error('Error fetching adjustments:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch adjustments',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const data = await getProducts({ is_active: true });
      setProducts(data || []);
    } catch (error: unknown) {
      console.error('Error fetching products:', error);
    }
  };

  const fetchWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      console.error('Error fetching warehouses:', error);
    }
  };

  const handleCreateAdjustment = async () => {
    try {
      if (!adjustmentForm.product_id || !adjustmentForm.warehouse_id || !adjustmentForm.quantity) {
        toast({
          title: 'Validation Error',
          description: 'Please fill in all required fields',
          variant: 'destructive',
        });
        return;
      }

      if (!adjustmentForm.reason) {
        toast({
          title: 'Validation Error',
          description: 'Please provide a reason for this adjustment',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      await createAdjustment({
        product_id: adjustmentForm.product_id,
        variant_id: adjustmentForm.variant_id || undefined,
        warehouse_id: adjustmentForm.warehouse_id,
        quantity: parseFloat(adjustmentForm.quantity) || 0,
        unit_cost: adjustmentForm.unit_cost ? parseFloat(adjustmentForm.unit_cost) : undefined,
        reason: adjustmentForm.reason,
        notes: adjustmentForm.notes || undefined,
      });

      toast({
        title: 'Success',
        description: 'Adjustment created successfully',
      });

      setShowAdjustmentDialog(false);
      resetForm();
      fetchAdjustments();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create adjustment',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewAdjustment = (adjustment: Adjustment) => {
    setSelectedAdjustment(adjustment);
    setShowViewDialog(true);
  };

  const resetForm = () => {
    setAdjustmentForm({
      product_id: '',
      variant_id: '',
      warehouse_id: '',
      quantity: '',
      unit_cost: '',
      reason: '',
      notes: '',
    });
  };

  const openCreateDialog = () => {
    resetForm();
    setShowAdjustmentDialog(true);
  };

  // Calculate statistics
  const totalAdjustments = adjustments.length;
  const increaseCount = adjustments.filter(a => {
    const qty = typeof a.quantity === 'number' ? a.quantity : parseFloat(String(a.quantity || 0));
    return qty > 0;
  }).length;
  const decreaseCount = adjustments.filter(a => {
    const qty = typeof a.quantity === 'number' ? a.quantity : parseFloat(String(a.quantity || 0));
    return qty < 0;
  }).length;
  const totalQuantityChange = adjustments.reduce((sum, a) => {
    const qty = typeof a.quantity === 'number' ? a.quantity : parseFloat(String(a.quantity || 0));
    return sum + (isNaN(qty) ? 0 : qty);
  }, 0);

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Inventory Adjustments</h1>
          <p className="text-muted-foreground mt-1">
            Manage inventory adjustments and corrections
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create Adjustment
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Adjustments</CardTitle>
            <Edit className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalAdjustments}</div>
            <p className="text-xs text-muted-foreground">
              All time adjustments
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Increases</CardTitle>
            <TrendingUp className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{increaseCount}</div>
            <p className="text-xs text-muted-foreground">
              Stock increases
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Decreases</CardTitle>
            <TrendingDown className="h-4 w-4 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">{decreaseCount}</div>
            <p className="text-xs text-muted-foreground">
              Stock decreases
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Net Change</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className={`text-2xl font-bold ${totalQuantityChange >= 0 ? 'text-green-600' : 'text-red-600'}`}>
              {totalQuantityChange >= 0 ? '+' : ''}{totalQuantityChange.toLocaleString()}
            </div>
            <p className="text-xs text-muted-foreground">
              Total quantity change
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-4">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search adjustments..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Product</Label>
              <Select value={productFilter} onValueChange={setProductFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All products" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Products</SelectItem>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Warehouse</Label>
              <Select value={warehouseFilter} onValueChange={setWarehouseFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All warehouses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Warehouses</SelectItem>
                  {warehouses.map((warehouse) => (
                    <SelectItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={typeFilter} onValueChange={setTypeFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All types" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="increase">Increases Only</SelectItem>
                  <SelectItem value="decrease">Decreases Only</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Adjustments Table */}
      <Card>
        <CardHeader>
          <CardTitle>Adjustments ({filteredAdjustments.length})</CardTitle>
          <CardDescription>
            Inventory adjustments and corrections
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredAdjustments.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredAdjustments.length === 0 ? (
            <Alert>
              <AlertDescription>
                No adjustments found. {searchTerm || productFilter !== 'all' || warehouseFilter !== 'all' || typeFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first adjustment to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead className="text-right">Quantity Change</TableHead>
                    <TableHead className="text-right">Unit Cost</TableHead>
                    <TableHead>Reason</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredAdjustments.map((adjustment) => {
                    const qty = typeof adjustment.quantity === 'number' ? adjustment.quantity : parseFloat(String(adjustment.quantity || 0));
                    const isIncrease = qty > 0;
                    
                    return (
                      <TableRow key={adjustment.id}>
                        <TableCell>
                          <div className="flex flex-col">
                            <span className="font-medium">{adjustment.product_name || 'N/A'}</span>
                            {adjustment.product_sku && (
                              <span className="text-xs text-muted-foreground font-mono">
                                {adjustment.product_sku}
                              </span>
                            )}
                          </div>
                        </TableCell>
                        <TableCell>
                          <div className="flex items-center">
                            <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                            {adjustment.warehouse_name || 'N/A'}
                          </div>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className={`font-medium flex items-center justify-end ${isIncrease ? 'text-green-600' : 'text-red-600'}`}>
                            {isIncrease ? (
                              <TrendingUp className="h-4 w-4 mr-1" />
                            ) : (
                              <TrendingDown className="h-4 w-4 mr-1" />
                            )}
                            {isIncrease ? '+' : ''}{qty.toLocaleString()}
                          </div>
                        </TableCell>
                        <TableCell className="text-right">
                          {adjustment.unit_cost
                            ? (typeof adjustment.unit_cost === 'number' ? adjustment.unit_cost : parseFloat(String(adjustment.unit_cost || 0))).toLocaleString('en-IN', {
                                style: 'currency',
                                currency: 'INR',
                              })
                            : '-'}
                        </TableCell>
                        <TableCell>
                          <div className="max-w-xs truncate" title={adjustment.reason || adjustment.notes || 'N/A'}>
                            {adjustment.reason || adjustment.notes || 'N/A'}
                          </div>
                        </TableCell>
                        <TableCell>
                          {new Date(adjustment.created_at).toLocaleDateString()}
                        </TableCell>
                        <TableCell className="text-right">
                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button variant="ghost" size="sm">
                                <MoreVertical className="h-4 w-4" />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem onClick={() => handleViewAdjustment(adjustment)}>
                                <Eye className="mr-2 h-4 w-4" />
                                View Details
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create Adjustment Dialog */}
      <Dialog open={showAdjustmentDialog} onOpenChange={setShowAdjustmentDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Create Inventory Adjustment</DialogTitle>
            <DialogDescription>
              Adjust inventory quantity (use positive for increase, negative for decrease)
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="product">Product *</Label>
              <Select
                value={adjustmentForm.product_id}
                onValueChange={(value) => setAdjustmentForm({ ...adjustmentForm, product_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select product" />
                </SelectTrigger>
                <SelectContent>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="warehouse">Warehouse *</Label>
              <Select
                value={adjustmentForm.warehouse_id}
                onValueChange={(value) => setAdjustmentForm({ ...adjustmentForm, warehouse_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select warehouse" />
                </SelectTrigger>
                <SelectContent>
                  {warehouses.map((warehouse) => (
                    <SelectItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="quantity">Quantity Change *</Label>
                <Input
                  id="quantity"
                  type="number"
                  step="0.01"
                  value={adjustmentForm.quantity}
                  onChange={(e) => setAdjustmentForm({ ...adjustmentForm, quantity: e.target.value })}
                  placeholder="+10 or -5"
                  required
                />
                <p className="text-xs text-muted-foreground">
                  Use positive for increase, negative for decrease
                </p>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="unit_cost">Unit Cost</Label>
                <Input
                  id="unit_cost"
                  type="number"
                  step="0.01"
                  value={adjustmentForm.unit_cost}
                  onChange={(e) => setAdjustmentForm({ ...adjustmentForm, unit_cost: e.target.value })}
                  placeholder="0.00"
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="reason">Reason *</Label>
              <Input
                id="reason"
                value={adjustmentForm.reason}
                onChange={(e) => setAdjustmentForm({ ...adjustmentForm, reason: e.target.value })}
                placeholder="e.g., Stock count correction, Damage, Found stock"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="notes">Additional Notes</Label>
              <Textarea
                id="notes"
                value={adjustmentForm.notes}
                onChange={(e) => setAdjustmentForm({ ...adjustmentForm, notes: e.target.value })}
                placeholder="Additional details about this adjustment"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowAdjustmentDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateAdjustment} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Create Adjustment
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Adjustment Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Adjustment Details</DialogTitle>
            <DialogDescription>
              View complete adjustment information
            </DialogDescription>
          </DialogHeader>
          {selectedAdjustment && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Product</Label>
                <div>
                  <p className="font-medium">{selectedAdjustment.product_name || 'N/A'}</p>
                  {selectedAdjustment.product_sku && (
                    <p className="text-sm text-muted-foreground font-mono">
                      SKU: {selectedAdjustment.product_sku}
                    </p>
                  )}
                </div>
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Warehouse</Label>
                <div className="flex items-center">
                  <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                  <p>{selectedAdjustment.warehouse_name || 'N/A'}</p>
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Quantity Change</Label>
                  {(() => {
                    const qty = typeof selectedAdjustment.quantity === 'number' ? selectedAdjustment.quantity : parseFloat(String(selectedAdjustment.quantity || 0));
                    const isIncrease = qty > 0;
                    return (
                      <p className={`font-medium text-lg flex items-center ${isIncrease ? 'text-green-600' : 'text-red-600'}`}>
                        {isIncrease ? (
                          <TrendingUp className="h-5 w-5 mr-1" />
                        ) : (
                          <TrendingDown className="h-5 w-5 mr-1" />
                        )}
                        {isIncrease ? '+' : ''}{qty.toLocaleString()}
                      </p>
                    );
                  })()}
                </div>
                {selectedAdjustment.unit_cost && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Unit Cost</Label>
                    <p className="font-medium">
                      {(typeof selectedAdjustment.unit_cost === 'number' ? selectedAdjustment.unit_cost : parseFloat(String(selectedAdjustment.unit_cost || 0))).toLocaleString('en-IN', {
                        style: 'currency',
                        currency: 'INR',
                      })}
                    </p>
                  </div>
                )}
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Reason</Label>
                <p className="text-sm">{selectedAdjustment.reason || 'N/A'}</p>
              </div>
              {selectedAdjustment.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedAdjustment.notes}</p>
                </div>
              )}
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Date</Label>
                <div className="flex items-center">
                  <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                  <p>{new Date(selectedAdjustment.created_at).toLocaleString()}</p>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Inventory BOM (Bill of Materials) Page
 * Complete BOM management interface
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  FileText,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Filter,
  Package,
  X,
  Save,
} from 'lucide-react';
import {
  getBoms,
  getBomById,
  createBom,
  updateBom,
  deleteBom,
  getProducts,
  type Bom,
  type BomItem,
  type Product,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Switch } from '@/components/ui/switch';

export default function InventoryBOM() {
  const navigate = useNavigate();
  const { toast } = useToast();
  const [boms, setBoms] = useState<Bom[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterActive, setFilterActive] = useState<boolean | undefined>(undefined);
  const [selectedProduct, setSelectedProduct] = useState<string>('all');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedBom, setSelectedBom] = useState<Bom | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<Bom>>({
    product_id: '',
    name: '',
    version: '',
    is_active: true,
    notes: '',
    items: [],
  });

  useEffect(() => {
    loadData();
  }, [filterActive, selectedProduct]);

  const loadData = async () => {
    try {
      setLoading(true);
      const [bomsData, productsData] = await Promise.all([
        getBoms({
          product_id: selectedProduct === 'all' ? undefined : selectedProduct,
          is_active: filterActive,
        }),
        getProducts(),
      ]);
      setBoms(bomsData);
      setProducts(productsData);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load BOMs',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = () => {
    setFormData({
      product_id: '',
      name: '',
      version: '',
      is_active: true,
      notes: '',
      items: [],
    });
    setSelectedBom(null);
    setIsDialogOpen(true);
  };

  const handleEdit = async (bom: Bom) => {
    try {
      const fullBom = await getBomById(bom.id);
      setFormData({
        ...fullBom,
        items: fullBom.items || [],
      });
      setSelectedBom(fullBom);
      setIsDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load BOM details',
        variant: 'destructive',
      });
    }
  };

  const handleView = async (bom: Bom) => {
    try {
      const fullBom = await getBomById(bom.id);
      setSelectedBom(fullBom);
      setIsViewDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load BOM details',
        variant: 'destructive',
      });
    }
  };

  const handleDelete = async (bom: Bom) => {
    if (!confirm(`Are you sure you want to delete BOM "${bom.name}"?`)) {
      return;
    }

    try {
      await deleteBom(bom.id);
      toast({
        title: 'Success',
        description: 'BOM deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete BOM',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.product_id || !formData.name) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSubmitting(true);
      if (selectedBom) {
        await updateBom(selectedBom.id, formData);
        toast({
          title: 'Success',
          description: 'BOM updated successfully',
        });
      } else {
        await createBom(formData);
        toast({
          title: 'Success',
          description: 'BOM created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save BOM',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const addBomItem = () => {
    setFormData({
      ...formData,
      items: [
        ...(formData.items || []),
        {
          id: '',
          bom_id: '',
          component_product_id: '',
          quantity: 1,
          unit_of_measure: 'pcs',
          sequence: (formData.items?.length || 0) + 1,
          notes: '',
        } as BomItem,
      ],
    });
  };

  const removeBomItem = (index: number) => {
    const newItems = [...(formData.items || [])];
    newItems.splice(index, 1);
    setFormData({ ...formData, items: newItems });
  };

  const updateBomItem = (index: number, field: keyof BomItem, value: unknown) => {
    const newItems = [...(formData.items || [])];
    newItems[index] = { ...newItems[index], [field]: value };
    setFormData({ ...formData, items: newItems });
  };

  const filteredBoms = boms.filter((bom) => {
    const matchesSearch =
      bom.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      bom.product_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      bom.product_sku?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      bom.version?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesSearch;
  });

  const stats = {
    total: boms.length,
    active: boms.filter((b) => b.is_active).length,
    inactive: boms.filter((b) => !b.is_active).length,
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Bill of Materials</h1>
          <p className="text-muted-foreground">Manage product BOMs and component lists</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="mr-2 h-4 w-4" />
          Create BOM
        </Button>
      </div>

      {/* Statistics */}
      <div className="grid gap-4 md:grid-cols-3">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total BOMs</CardTitle>
            <FileText className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active BOMs</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-green-600">{stats.active}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Inactive BOMs</CardTitle>
            <FileText className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-gray-600">{stats.inactive}</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search BOMs..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Product</Label>
              <Select value={selectedProduct} onValueChange={setSelectedProduct}>
                <SelectTrigger>
                  <SelectValue placeholder="All Products" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Products</SelectItem>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select
                value={filterActive === undefined ? 'all' : filterActive ? 'active' : 'inactive'}
                onValueChange={(value) =>
                  setFilterActive(value === 'all' ? undefined : value === 'active')
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="All Status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* BOMs Table */}
      <Card>
        <CardHeader>
          <CardTitle>BOMs List</CardTitle>
          <CardDescription>Manage all Bill of Materials</CardDescription>
        </CardHeader>
        <CardContent>
          {loading ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : filteredBoms.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No BOMs found. Create your first BOM to get started.
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Product</TableHead>
                  <TableHead>BOM Name</TableHead>
                  <TableHead>Version</TableHead>
                  <TableHead>Items</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead>Created</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {filteredBoms.map((bom) => (
                  <TableRow key={bom.id}>
                    <TableCell>
                      <div>
                        <div className="font-medium">{bom.product_name}</div>
                        <div className="text-sm text-muted-foreground">{bom.product_sku}</div>
                      </div>
                    </TableCell>
                    <TableCell className="font-medium">{bom.name}</TableCell>
                    <TableCell>{bom.version || '-'}</TableCell>
                    <TableCell>{bom.item_count || 0} items</TableCell>
                    <TableCell>
                      <Badge variant={bom.is_active ? 'default' : 'secondary'}>
                        {bom.is_active ? 'Active' : 'Inactive'}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      {new Date(bom.created_at).toLocaleDateString()}
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(bom)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(bom)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(bom)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{selectedBom ? 'Edit BOM' : 'Create BOM'}</DialogTitle>
            <DialogDescription>
              {selectedBom ? 'Update BOM details' : 'Create a new Bill of Materials'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmit}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="product_id">Product *</Label>
                  <Select
                    value={formData.product_id || ''}
                    onValueChange={(value) => setFormData({ ...formData, product_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select Product" />
                    </SelectTrigger>
                    <SelectContent>
                      {products.map((product) => (
                        <SelectItem key={product.id} value={product.id}>
                          {product.name} ({product.sku})
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="name">BOM Name *</Label>
                  <Input
                    id="name"
                    value={formData.name || ''}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., Main Assembly BOM"
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="version">Version</Label>
                  <Input
                    id="version"
                    value={formData.version || ''}
                    onChange={(e) => setFormData({ ...formData, version: e.target.value })}
                    placeholder="e.g., v1.0"
                  />
                </div>
                <div className="space-y-2 flex items-center gap-4 pt-6">
                  <Label htmlFor="is_active">Active</Label>
                  <Switch
                    id="is_active"
                    checked={formData.is_active}
                    onCheckedChange={(checked) =>
                      setFormData({ ...formData, is_active: checked })
                    }
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="notes">Notes</Label>
                <Textarea
                  id="notes"
                  value={formData.notes || ''}
                  onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={3}
                />
              </div>

              {/* BOM Items */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <Label>BOM Items</Label>
                  <Button type="button" variant="outline" size="sm" onClick={addBomItem}>
                    <Plus className="mr-2 h-4 w-4" />
                    Add Item
                  </Button>
                </div>
                {formData.items && formData.items.length > 0 ? (
                  <div className="space-y-2">
                    {formData.items.map((item, index) => (
                      <Card key={index}>
                        <CardContent className="pt-4">
                          <div className="grid gap-4 md:grid-cols-5">
                            <div className="space-y-2">
                              <Label>Component Product *</Label>
                              <Select
                                value={item.component_product_id}
                                onValueChange={(value) =>
                                  updateBomItem(index, 'component_product_id', value)
                                }
                              >
                                <SelectTrigger>
                                  <SelectValue placeholder="Select Product" />
                                </SelectTrigger>
                                <SelectContent>
                                  {products
                                    .filter((p) => p.id !== formData.product_id)
                                    .map((product) => (
                                      <SelectItem key={product.id} value={product.id}>
                                        {product.name} ({product.sku})
                                      </SelectItem>
                                    ))}
                                </SelectContent>
                              </Select>
                            </div>
                            <div className="space-y-2">
                              <Label>Quantity *</Label>
                              <Input
                                type="number"
                                step="0.01"
                                min="0"
                                value={item.quantity}
                                onChange={(e) =>
                                  updateBomItem(
                                    index,
                                    'quantity',
                                    parseFloat(e.target.value) || 0
                                  )
                                }
                              />
                            </div>
                            <div className="space-y-2">
                              <Label>Unit</Label>
                              <Input
                                value={item.unit_of_measure}
                                onChange={(e) =>
                                  updateBomItem(index, 'unit_of_measure', e.target.value)
                                }
                                placeholder="pcs"
                              />
                            </div>
                            <div className="space-y-2">
                              <Label>Sequence</Label>
                              <Input
                                type="number"
                                value={item.sequence}
                                onChange={(e) =>
                                  updateBomItem(index, 'sequence', parseInt(e.target.value) || 0)
                                }
                              />
                            </div>
                            <div className="space-y-2 flex items-end">
                              <Button
                                type="button"
                                variant="ghost"
                                size="sm"
                                onClick={() => removeBomItem(index)}
                              >
                                <X className="h-4 w-4" />
                              </Button>
                            </div>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-4 text-muted-foreground border rounded">
                    No items added. Click "Add Item" to add components.
                  </div>
                )}
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting}>
                {isSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedBom ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>BOM Details</DialogTitle>
            <DialogDescription>View BOM information and components</DialogDescription>
          </DialogHeader>
          {selectedBom && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Product</Label>
                  <div className="mt-1">
                    <div className="font-medium">{selectedBom.product_name}</div>
                    <div className="text-sm text-muted-foreground">{selectedBom.product_sku}</div>
                  </div>
                </div>
                <div>
                  <Label>BOM Name</Label>
                  <div className="mt-1 font-medium">{selectedBom.name}</div>
                </div>
                <div>
                  <Label>Version</Label>
                  <div className="mt-1">{selectedBom.version || '-'}</div>
                </div>
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">
                    <Badge variant={selectedBom.is_active ? 'default' : 'secondary'}>
                      {selectedBom.is_active ? 'Active' : 'Inactive'}
                    </Badge>
                  </div>
                </div>
              </div>
              {selectedBom.notes && (
                <div>
                  <Label>Notes</Label>
                  <div className="mt-1 text-sm">{selectedBom.notes}</div>
                </div>
              )}
              {selectedBom.items && selectedBom.items.length > 0 && (
                <div>
                  <Label>Components</Label>
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Product</TableHead>
                        <TableHead>Quantity</TableHead>
                        <TableHead>Unit</TableHead>
                        <TableHead>Sequence</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {selectedBom.items.map((item) => (
                        <TableRow key={item.id}>
                          <TableCell>
                            <div>
                              <div className="font-medium">{item.component_name}</div>
                              <div className="text-sm text-muted-foreground">
                                {item.component_sku}
                              </div>
                            </div>
                          </TableCell>
                          <TableCell>{item.quantity}</TableCell>
                          <TableCell>{item.unit_of_measure}</TableCell>
                          <TableCell>{item.sequence}</TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
            {selectedBom && (
              <Button onClick={() => {
                setIsViewDialogOpen(false);
                handleEdit(selectedBom);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Inventory Products Page
 * Complete product catalog management interface
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Package,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  QrCode,
  Eye,
  Filter,
  Download,
  Upload,
  MoreVertical,
} from 'lucide-react';
import {
  getProducts,
  getProductById,
  createProduct,
  updateProduct,
  deleteProduct,
  getProductCategories,
  createProductCategory,
  generateProductCode,
  type Product,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Switch } from '@/components/ui/switch';

export default function InventoryProducts() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Products
  const [products, setProducts] = useState<Product[]>([]);
  const [filteredProducts, setFilteredProducts] = useState<Product[]>([]);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [showProductDialog, setShowProductDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Categories
  const [categories, setCategories] = useState<Array<{ id: string; name: string; description?: string }>>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  // Product form
  const [productForm, setProductForm] = useState({
    sku: '',
    name: '',
    description: '',
    category_id: '',
    brand: '',
    unit_of_measure: 'pcs',
    barcode: '',
    weight: '',
    dimensions: '',
    is_trackable: false,
    track_by: 'none' as 'serial' | 'batch' | 'none',
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchProducts(),
          fetchCategories(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading products data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load products',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = products;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(p =>
        p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        p.sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (p.barcode && p.barcode.toLowerCase().includes(searchTerm.toLowerCase()))
      );
    }

    // Category filter
    if (categoryFilter !== 'all') {
      filtered = filtered.filter(p => p.category_id === categoryFilter);
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(p =>
        statusFilter === 'active' ? p.is_active : !p.is_active
      );
    }

    setFilteredProducts(filtered);
  }, [products, searchTerm, categoryFilter, statusFilter]);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const data = await getProducts();
      setProducts(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch products',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchCategories = async () => {
    try {
      const data = await getProductCategories();
      setCategories(data || []);
    } catch (error: unknown) {
      console.error('Error fetching categories:', error);
    }
  };

  const handleCreateProduct = async () => {
    try {
      setLoading(true);
      if (isEditing && selectedProduct) {
        // Convert weight from string to number if provided
        const productData: Partial<ProductType> = {
          ...productForm,
          weight: productForm.weight ? parseFloat(productForm.weight) || undefined : undefined,
        };
        await updateProduct(selectedProduct.id, productData);
        toast({
          title: 'Success',
          description: 'Product updated successfully',
        });
      } else {
        // Convert weight from string to number if provided
        const productData: Partial<ProductType> = {
          ...productForm,
          weight: productForm.weight ? parseFloat(productForm.weight) || undefined : undefined,
        };
        await createProduct(productData);
        toast({
          title: 'Success',
          description: 'Product created successfully',
        });
      }
      setShowProductDialog(false);
      resetForm();
      fetchProducts();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save product',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditProduct = async (product: Product) => {
    setSelectedProduct(product);
    setIsEditing(true);
    setProductForm({
      sku: product.sku,
      name: product.name,
      description: product.description || '',
      category_id: product.category_id || '',
      brand: product.brand || '',
      unit_of_measure: product.unit_of_measure,
      barcode: product.barcode || '',
      weight: product.weight?.toString() || '',
      dimensions: product.dimensions || '',
      is_trackable: product.is_trackable,
      track_by: product.track_by || 'none',
    });
    setShowProductDialog(true);
  };

  const handleViewProduct = async (productId: string) => {
    try {
      const product = await getProductById(productId);
      setSelectedProduct(product);
      setShowViewDialog(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch product details',
        variant: 'destructive',
      });
    }
  };

  const handleDeleteProduct = async (product: Product) => {
    if (!confirm(`Are you sure you want to delete "${product.name}"?`)) {
      return;
    }

    try {
      setLoading(true);
      await deleteProduct(product.id);
      toast({
        title: 'Success',
        description: 'Product deleted successfully',
      });
      fetchProducts();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete product',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateCode = async (productId: string, codeType: 'barcode' | 'qr') => {
    try {
      setLoading(true);
      const code = await generateProductCode(productId, codeType);
      toast({
        title: 'Success',
        description: `${codeType.toUpperCase()} code generated: ${code}`,
      });
      fetchProducts();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to generate code',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setProductForm({
      sku: '',
      name: '',
      description: '',
      category_id: '',
      brand: '',
      unit_of_measure: 'pcs',
      barcode: '',
      weight: '',
      dimensions: '',
      is_trackable: false,
      track_by: 'none',
    });
    setSelectedProduct(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowProductDialog(true);
  };

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Product Catalog</h1>
          <p className="text-muted-foreground mt-1">
            Manage your product catalog, categories, and product information
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Add Product
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Products</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{products.length}</div>
            <p className="text-xs text-muted-foreground">
              {products.filter(p => p.is_active).length} active
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Categories</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{categories.length}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Trackable Products</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {products.filter(p => p.is_trackable).length}
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">With Barcodes</CardTitle>
            <QrCode className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {products.filter(p => p.barcode).length}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search products..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Category</Label>
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All categories" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  {categories.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Products Table */}
      <Card>
        <CardHeader>
          <CardTitle>Products ({filteredProducts.length})</CardTitle>
          <CardDescription>
            Manage your product catalog
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredProducts.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredProducts.length === 0 ? (
            <Alert>
              <AlertDescription>
                No products found. {searchTerm || categoryFilter !== 'all' || statusFilter !== 'all' 
                  ? 'Try adjusting your filters.' 
                  : 'Create your first product to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>SKU</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Category</TableHead>
                    <TableHead>Brand</TableHead>
                    <TableHead>Unit</TableHead>
                    <TableHead>Tracking</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredProducts.map((product) => (
                    <TableRow key={product.id}>
                      <TableCell className="font-mono text-sm">{product.sku}</TableCell>
                      <TableCell className="font-medium">{product.name}</TableCell>
                      <TableCell>
                        {categories.find(c => c.id === product.category_id)?.name || '-'}
                      </TableCell>
                      <TableCell>{product.brand || '-'}</TableCell>
                      <TableCell>{product.unit_of_measure}</TableCell>
                      <TableCell>
                        {product.is_trackable ? (
                          <Badge variant="secondary">{product.track_by}</Badge>
                        ) : (
                          <span className="text-muted-foreground">None</span>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge variant={product.is_active ? 'default' : 'secondary'}>
                          {product.is_active ? 'Active' : 'Inactive'}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewProduct(product.id)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEditProduct(product)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleGenerateCode(product.id, 'barcode')}
                            >
                              <QrCode className="mr-2 h-4 w-4" />
                              Generate Barcode
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleGenerateCode(product.id, 'qr')}
                            >
                              <QrCode className="mr-2 h-4 w-4" />
                              Generate QR Code
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => navigate(`/inventory/stock-levels?product=${product.id}`)}
                            >
                              View Stock Levels
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleDeleteProduct(product)}
                              className="text-destructive"
                            >
                              <Trash2 className="mr-2 h-4 w-4" />
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Product Dialog */}
      <Dialog open={showProductDialog} onOpenChange={setShowProductDialog}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Product' : 'Create New Product'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update product information' : 'Add a new product to your catalog'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="sku">SKU *</Label>
              <Input
                id="sku"
                value={productForm.sku}
                onChange={(e) => setProductForm({ ...productForm, sku: e.target.value })}
                placeholder="PROD-001"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="name">Product Name *</Label>
              <Input
                id="name"
                value={productForm.name}
                onChange={(e) => setProductForm({ ...productForm, name: e.target.value })}
                placeholder="Enter product name"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={productForm.description}
                onChange={(e) => setProductForm({ ...productForm, description: e.target.value })}
                placeholder="Product description"
                rows={3}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="category">Category</Label>
                <Select
                  value={productForm.category_id}
                  onValueChange={(value) => setProductForm({ ...productForm, category_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select category" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="">None</SelectItem>
                    {categories.map((cat) => (
                      <SelectItem key={cat.id} value={cat.id}>
                        {cat.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="brand">Brand</Label>
                <Input
                  id="brand"
                  value={productForm.brand}
                  onChange={(e) => setProductForm({ ...productForm, brand: e.target.value })}
                  placeholder="Brand name"
                />
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="unit">Unit of Measure</Label>
                <Select
                  value={productForm.unit_of_measure}
                  onValueChange={(value) => setProductForm({ ...productForm, unit_of_measure: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="pcs">Pieces (pcs)</SelectItem>
                    <SelectItem value="kg">Kilograms (kg)</SelectItem>
                    <SelectItem value="g">Grams (g)</SelectItem>
                    <SelectItem value="l">Liters (l)</SelectItem>
                    <SelectItem value="ml">Milliliters (ml)</SelectItem>
                    <SelectItem value="m">Meters (m)</SelectItem>
                    <SelectItem value="cm">Centimeters (cm)</SelectItem>
                    <SelectItem value="box">Box</SelectItem>
                    <SelectItem value="pack">Pack</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="weight">Weight</Label>
                <Input
                  id="weight"
                  type="number"
                  value={productForm.weight}
                  onChange={(e) => setProductForm({ ...productForm, weight: e.target.value })}
                  placeholder="0.00"
                  step="0.01"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="dimensions">Dimensions</Label>
                <Input
                  id="dimensions"
                  value={productForm.dimensions}
                  onChange={(e) => setProductForm({ ...productForm, dimensions: e.target.value })}
                  placeholder="L x W x H"
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="barcode">Barcode</Label>
              <Input
                id="barcode"
                value={productForm.barcode}
                onChange={(e) => setProductForm({ ...productForm, barcode: e.target.value })}
                placeholder="Barcode number"
              />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="flex items-center space-x-2">
                <Switch
                  id="trackable"
                  checked={productForm.is_trackable}
                  onCheckedChange={(checked) =>
                    setProductForm({ ...productForm, is_trackable: checked })
                  }
                />
                <Label htmlFor="trackable">Trackable Product</Label>
              </div>
              {productForm.is_trackable && (
                <div className="grid gap-2">
                  <Label htmlFor="track_by">Track By</Label>
                  <Select
                    value={productForm.track_by}
                    onValueChange={(value: 'serial' | 'batch' | 'none') =>
                      setProductForm({ ...productForm, track_by: value })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="serial">Serial Number</SelectItem>
                      <SelectItem value="batch">Batch/Lot Number</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              )}
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowProductDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateProduct} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Product
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Product Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Product Details</DialogTitle>
            <DialogDescription>
              View complete product information
            </DialogDescription>
          </DialogHeader>
          {selectedProduct && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label className="text-sm font-medium">SKU</Label>
                <p className="font-mono">{selectedProduct.sku}</p>
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Name</Label>
                <p>{selectedProduct.name}</p>
              </div>
              {selectedProduct.description && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Description</Label>
                  <p className="text-sm text-muted-foreground">{selectedProduct.description}</p>
                </div>
              )}
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Brand</Label>
                  <p>{selectedProduct.brand || '-'}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Unit of Measure</Label>
                  <p>{selectedProduct.unit_of_measure}</p>
                </div>
              </div>
              {selectedProduct.barcode && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Barcode</Label>
                  <p className="font-mono">{selectedProduct.barcode}</p>
                </div>
              )}
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Status</Label>
                <Badge variant={selectedProduct.is_active ? 'default' : 'secondary'}>
                  {selectedProduct.is_active ? 'Active' : 'Inactive'}
                </Badge>
              </div>
              {selectedProduct.is_trackable && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Tracking</Label>
                  <Badge variant="secondary">{selectedProduct.track_by}</Badge>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
            {selectedProduct && (
              <Button onClick={() => {
                setShowViewDialog(false);
                handleEditProduct(selectedProduct);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Inventory Reports Page
 * Comprehensive inventory analytics and reporting
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  BarChart3,
  TrendingUp,
  TrendingDown,
  Package,
  Warehouse,
  DollarSign,
  AlertTriangle,
  Loader2,
  Download,
  Calendar,
  Filter,
} from 'lucide-react';
import {
  getInventoryReports,
  getStockValueReport,
  getMovementReport,
  getWarehouseUtilizationReport,
  getWarehouses,
  getProducts,
  type InventoryReportSummary,
  type StockValueReportItem,
  type MovementReportItem,
  type WarehouseUtilizationItem,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

export default function InventoryReports() {
  const { toast } = useToast();
  const [loading, setLoading] = useState(true);
  const [reports, setReports] = useState<InventoryReportSummary | null>(null);
  const [stockValueReport, setStockValueReport] = useState<StockValueReportItem[]>([]);
  const [movementReport, setMovementReport] = useState<MovementReportItem[]>([]);
  const [warehouseUtilization, setWarehouseUtilization] = useState<WarehouseUtilizationItem[]>([]);
  const [warehouses, setWarehouses] = useState<unknown[]>([]);
  const [products, setProducts] = useState<unknown[]>([]);

  // Filters
  const [dateFrom, setDateFrom] = useState(
    new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const [dateTo, setDateTo] = useState(new Date().toISOString().split('T')[0]);
  const [filterWarehouse, setFilterWarehouse] = useState<string>('all');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [lowStockOnly, setLowStockOnly] = useState(false);

  useEffect(() => {
    loadWarehouses();
    loadProducts();
    loadReports();
  }, [dateFrom, dateTo]);

  useEffect(() => {
    loadStockValueReport();
    loadWarehouseUtilization();
  }, [filterWarehouse, filterCategory, lowStockOnly]);

  useEffect(() => {
    loadMovementReport();
  }, [dateFrom, dateTo, filterWarehouse]);

  const loadWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data.filter((w) => w.is_active));
    } catch (error: unknown) {
      console.error('Failed to load warehouses:', error);
    }
  };

  const loadProducts = async () => {
    try {
      const data = await getProducts({ is_active: true });
      setProducts(data);
    } catch (error: unknown) {
      console.error('Failed to load products:', error);
    }
  };

  const loadReports = async () => {
    try {
      setLoading(true);
      const data = await getInventoryReports({
        date_from: dateFrom,
        date_to: dateTo,
      });
      setReports(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load reports',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const loadStockValueReport = async () => {
    try {
      const filters: unknown = {};
      if (filterWarehouse !== 'all') filters.warehouse_id = filterWarehouse;
      if (filterCategory !== 'all') filters.category_id = filterCategory;
      if (lowStockOnly) filters.low_stock_only = true;

      const data = await getStockValueReport(filters);
      setStockValueReport(data);
    } catch (error: unknown) {
      console.error('Failed to load stock value report:', error);
    }
  };

  const loadMovementReport = async () => {
    try {
      const filters: unknown = {
        date_from: dateFrom,
        date_to: dateTo,
      };
      if (filterWarehouse !== 'all') filters.warehouse_id = filterWarehouse;

      const data = await getMovementReport(filters);
      setMovementReport(data);
    } catch (error: unknown) {
      console.error('Failed to load movement report:', error);
    }
  };

  const loadWarehouseUtilization = async () => {
    try {
      const data = await getWarehouseUtilizationReport();
      setWarehouseUtilization(data);
    } catch (error: unknown) {
      console.error('Failed to load warehouse utilization:', error);
    }
  };

  const handleExport = () => {
    toast({
      title: 'Export',
      description: 'Export functionality coming soon',
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-screen">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Inventory Reports</h1>
          <p className="text-muted-foreground">Comprehensive inventory analytics and insights</p>
        </div>
        <Button onClick={handleExport}>
          <Download className="mr-2 h-4 w-4" />
          Export Report
        </Button>
      </div>

      {/* Date Range Filter */}
      <Card>
        <CardHeader>
          <CardTitle>Date Range</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>From Date</Label>
              <Input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label>To Date</Label>
              <Input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
              />
            </div>
            <div className="flex items-end">
              <Button onClick={loadReports} className="w-full">
                <Filter className="mr-2 h-4 w-4" />
                Apply Filters
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Summary Statistics */}
      {reports && (
        <div className="grid gap-4 md:grid-cols-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Products</CardTitle>
              <Package className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {reports.summary.total_products || 0}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Warehouses</CardTitle>
              <Warehouse className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {reports.summary.total_warehouses || 0}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Quantity</CardTitle>
              <TrendingUp className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {(typeof reports.summary.total_quantity === 'number'
                  ? reports.summary.total_quantity
                  : parseFloat(String(reports.summary.total_quantity || 0))
                ).toLocaleString()}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Value</CardTitle>
              <DollarSign className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                $
                {(typeof reports.summary.total_value === 'number'
                  ? reports.summary.total_value
                  : parseFloat(String(reports.summary.total_value || 0))
                ).toLocaleString('en-US', {
                  minimumFractionDigits: 2,
                  maximumFractionDigits: 2,
                })}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Low Stock Items</CardTitle>
              <AlertTriangle className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-orange-600">
                {reports.summary.low_stock_items || 0}
              </div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Inventory Records</CardTitle>
              <BarChart3 className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {reports.summary.total_inventory_records || 0}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="stock-value">Stock Value</TabsTrigger>
          <TabsTrigger value="movement">Movement</TabsTrigger>
          <TabsTrigger value="warehouses">Warehouses</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-4">
          {/* Transaction Summary */}
          {reports && reports.transactions && reports.transactions.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Transaction Summary</CardTitle>
                <CardDescription>
                  Transactions from {dateFrom} to {dateTo}
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Transaction Type</TableHead>
                      <TableHead>Count</TableHead>
                      <TableHead>Total Quantity</TableHead>
                      <TableHead>Total Cost</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {reports.transactions.map((txn, idx) => (
                      <TableRow key={idx}>
                        <TableCell>
                          <Badge variant="outline">{txn.transaction_type}</Badge>
                        </TableCell>
                        <TableCell>{txn.count}</TableCell>
                        <TableCell>
                          {(typeof txn.total_quantity === 'number'
                            ? txn.total_quantity
                            : parseFloat(String(txn.total_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof txn.total_cost === 'number'
                            ? txn.total_cost
                            : parseFloat(String(txn.total_cost || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          )}

          {/* Top Products by Value */}
          {reports && reports.top_products && reports.top_products.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle>Top Products by Value</CardTitle>
                <CardDescription>Products with highest inventory value</CardDescription>
              </CardHeader>
              <CardContent>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>SKU</TableHead>
                      <TableHead>Product Name</TableHead>
                      <TableHead>Quantity</TableHead>
                      <TableHead>Available</TableHead>
                      <TableHead>Total Value</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {reports.top_products.map((product) => (
                      <TableRow key={product.id}>
                        <TableCell className="font-mono">{product.sku}</TableCell>
                        <TableCell className="font-medium">{product.name}</TableCell>
                        <TableCell>
                          {(typeof product.total_quantity === 'number'
                            ? product.total_quantity
                            : parseFloat(String(product.total_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          {(typeof product.available_quantity === 'number'
                            ? product.available_quantity
                            : parseFloat(String(product.available_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof product.total_value === 'number'
                            ? product.total_value
                            : parseFloat(String(product.total_value || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
          )}
        </TabsContent>

        {/* Stock Value Tab */}
        <TabsContent value="stock-value" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Stock Value Report</CardTitle>
              <CardDescription>Detailed inventory valuation by product and warehouse</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-3 mb-4">
                <div className="space-y-2">
                  <Label>Warehouse</Label>
                  <Select value={filterWarehouse} onValueChange={setFilterWarehouse}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Warehouses" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Warehouses</SelectItem>
                      {warehouses.map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.code} - {warehouse.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Low Stock Only</Label>
                  <Select
                    value={lowStockOnly ? 'yes' : 'no'}
                    onValueChange={(v) => setLowStockOnly(v === 'yes')}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="no">All Items</SelectItem>
                      <SelectItem value="yes">Low Stock Only</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>SKU</TableHead>
                    <TableHead>Product</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead>Quantity</TableHead>
                    <TableHead>Available</TableHead>
                    <TableHead>Avg Cost</TableHead>
                    <TableHead>Stock Value</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {stockValueReport.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={8} className="text-center text-muted-foreground">
                        No data available
                      </TableCell>
                    </TableRow>
                  ) : (
                    stockValueReport.map((item) => (
                      <TableRow key={`${item.id}-${item.warehouse_id}`}>
                        <TableCell className="font-mono">{item.sku}</TableCell>
                        <TableCell className="font-medium">{item.name}</TableCell>
                        <TableCell>
                          <div>
                            <div className="font-mono text-sm">{item.warehouse_code}</div>
                            <div className="text-sm text-muted-foreground">{item.warehouse_name}</div>
                          </div>
                        </TableCell>
                        <TableCell>
                          {(typeof item.quantity === 'number'
                            ? item.quantity
                            : parseFloat(String(item.quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          {(typeof item.available_quantity === 'number'
                            ? item.available_quantity
                            : parseFloat(String(item.available_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof item.average_cost === 'number'
                            ? item.average_cost
                            : parseFloat(String(item.average_cost || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof item.stock_value === 'number'
                            ? item.stock_value
                            : parseFloat(String(item.stock_value || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                        <TableCell>
                          {item.is_low_stock ? (
                            <Badge variant="destructive">
                              <AlertTriangle className="mr-1 h-3 w-3" />
                              Low Stock
                            </Badge>
                          ) : (
                            <Badge variant="default">OK</Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Movement Tab */}
        <TabsContent value="movement" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Movement Report</CardTitle>
              <CardDescription>Inventory transactions and movements over time</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Date</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Product</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead>Quantity</TableHead>
                    <TableHead>Cost</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {movementReport.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={6} className="text-center text-muted-foreground">
                        No transactions found for the selected period
                      </TableCell>
                    </TableRow>
                  ) : (
                    movementReport.map((item, idx) => (
                      <TableRow key={idx}>
                        <TableCell>{new Date(item.date).toLocaleDateString()}</TableCell>
                        <TableCell>
                          <Badge variant="outline">{item.transaction_type}</Badge>
                        </TableCell>
                        <TableCell>
                          <div>
                            <div className="font-mono text-sm">{item.sku}</div>
                            <div className="text-sm text-muted-foreground">{item.product_name}</div>
                          </div>
                        </TableCell>
                        <TableCell>
                          {item.warehouse_name ? (
                            <div>
                              <div className="font-mono text-sm">{item.warehouse_code}</div>
                              <div className="text-sm text-muted-foreground">{item.warehouse_name}</div>
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          {(typeof item.total_quantity === 'number'
                            ? item.total_quantity
                            : parseFloat(String(item.total_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof item.total_cost === 'number'
                            ? item.total_cost
                            : parseFloat(String(item.total_cost || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Warehouses Tab */}
        <TabsContent value="warehouses" className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle>Warehouse Utilization</CardTitle>
              <CardDescription>Inventory distribution across warehouses</CardDescription>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Warehouse</TableHead>
                    <TableHead>Products</TableHead>
                    <TableHead>Total Quantity</TableHead>
                    <TableHead>Available</TableHead>
                    <TableHead>Reserved</TableHead>
                    <TableHead>Total Value</TableHead>
                    <TableHead>Low Stock Items</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {warehouseUtilization.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={7} className="text-center text-muted-foreground">
                        No warehouse data available
                      </TableCell>
                    </TableRow>
                  ) : (
                    warehouseUtilization.map((warehouse) => (
                      <TableRow key={warehouse.id}>
                        <TableCell>
                          <div>
                            <div className="font-mono font-medium">{warehouse.code}</div>
                            <div className="text-sm text-muted-foreground">{warehouse.name}</div>
                          </div>
                        </TableCell>
                        <TableCell>{warehouse.product_count || 0}</TableCell>
                        <TableCell>
                          {(typeof warehouse.total_quantity === 'number'
                            ? warehouse.total_quantity
                            : parseFloat(String(warehouse.total_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          {(typeof warehouse.available_quantity === 'number'
                            ? warehouse.available_quantity
                            : parseFloat(String(warehouse.available_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          {(typeof warehouse.reserved_quantity === 'number'
                            ? warehouse.reserved_quantity
                            : parseFloat(String(warehouse.reserved_quantity || 0))
                          ).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          $
                          {(typeof warehouse.total_value === 'number'
                            ? warehouse.total_value
                            : parseFloat(String(warehouse.total_value || 0))
                          ).toLocaleString('en-US', {
                            minimumFractionDigits: 2,
                            maximumFractionDigits: 2,
                          })}
                        </TableCell>
                        <TableCell>
                          {warehouse.low_stock_count > 0 ? (
                            <Badge variant="destructive">
                              {warehouse.low_stock_count} items
                            </Badge>
                          ) : (
                            <Badge variant="default">None</Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    ))
                  )}
                </TableBody>
              </Table>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

/**
 * Inventory Serial/Batch Tracking Page
 * Complete serial number and batch tracking interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Hash,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Package,
  Calendar,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Clock,
} from 'lucide-react';
import {
  getSerialNumbers,
  createSerialNumber,
  updateSerialNumber,
  deleteSerialNumber,
  getBatches,
  createBatch,
  updateBatch,
  deleteBatch,
  getProducts,
  getWarehouses,
  type SerialNumber,
  type Batch,
  type Product,
  type Warehouse,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

export default function InventorySerialBatch() {
  const { toast } = useToast();
  const [activeTab, setActiveTab] = useState<'serial' | 'batch'>('serial');
  
  // Serial Numbers State
  const [serialNumbers, setSerialNumbers] = useState<SerialNumber[]>([]);
  const [serialLoading, setSerialLoading] = useState(true);
  const [serialSearch, setSerialSearch] = useState('');
  const [serialFilterProduct, setSerialFilterProduct] = useState<string>('all');
  const [serialFilterWarehouse, setSerialFilterWarehouse] = useState<string>('all');
  const [serialFilterStatus, setSerialFilterStatus] = useState<string>('all');
  const [isSerialDialogOpen, setIsSerialDialogOpen] = useState(false);
  const [isSerialViewDialogOpen, setIsSerialViewDialogOpen] = useState(false);
  const [selectedSerial, setSelectedSerial] = useState<SerialNumber | null>(null);
  const [isSerialSubmitting, setIsSerialSubmitting] = useState(false);
  
  // Batches State
  const [batches, setBatches] = useState<Batch[]>([]);
  const [batchLoading, setBatchLoading] = useState(true);
  const [batchSearch, setBatchSearch] = useState('');
  const [batchFilterProduct, setBatchFilterProduct] = useState<string>('all');
  const [batchFilterWarehouse, setBatchFilterWarehouse] = useState<string>('all');
  const [batchFilterStatus, setBatchFilterStatus] = useState<string>('all');
  const [isBatchDialogOpen, setIsBatchDialogOpen] = useState(false);
  const [isBatchViewDialogOpen, setIsBatchViewDialogOpen] = useState(false);
  const [selectedBatch, setSelectedBatch] = useState<Batch | null>(null);
  const [isBatchSubmitting, setIsBatchSubmitting] = useState(false);
  
  // Shared State
  const [products, setProducts] = useState<Product[]>([]);
  const [warehouses, setWarehouses] = useState<Warehouse[]>([]);
  const [productsLoading, setProductsLoading] = useState(false);

  // Form state
  const [serialFormData, setSerialFormData] = useState<Partial<SerialNumber>>({
    product_id: '',
    serial_number: '',
    warehouse_id: '',
    status: 'available',
    notes: '',
  });

  const [batchFormData, setBatchFormData] = useState<Partial<Batch>>({
    product_id: '',
    batch_number: '',
    warehouse_id: '',
    quantity: 0,
    manufacture_date: '',
    expiry_date: '',
    cost_per_unit: 0,
    status: 'active',
    notes: '',
  });

  useEffect(() => {
    loadProducts();
    loadWarehouses();
  }, []);

  useEffect(() => {
    if (activeTab === 'serial') {
      loadSerialNumbers();
    } else {
      loadBatches();
    }
  }, [activeTab, serialFilterProduct, serialFilterWarehouse, serialFilterStatus, batchFilterProduct, batchFilterWarehouse, batchFilterStatus]);

  const loadProducts = async () => {
    try {
      setProductsLoading(true);
      const data = await getProducts({ is_active: true });
      setProducts(data);
    } catch (error: unknown) {
      console.error('Failed to load products:', error);
    } finally {
      setProductsLoading(false);
    }
  };

  const loadWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data.filter((w) => w.is_active));
    } catch (error: unknown) {
      console.error('Failed to load warehouses:', error);
    }
  };

  const loadSerialNumbers = async () => {
    try {
      setSerialLoading(true);
      const filters: unknown = {};
      if (serialFilterProduct !== 'all') filters.product_id = serialFilterProduct;
      if (serialFilterWarehouse !== 'all') filters.warehouse_id = serialFilterWarehouse;
      if (serialFilterStatus !== 'all') filters.status = serialFilterStatus;
      if (serialSearch) filters.search = serialSearch;

      const data = await getSerialNumbers(filters);
      setSerialNumbers(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load serial numbers',
        variant: 'destructive',
      });
    } finally {
      setSerialLoading(false);
    }
  };

  const loadBatches = async () => {
    try {
      setBatchLoading(true);
      const filters: unknown = {};
      if (batchFilterProduct !== 'all') filters.product_id = batchFilterProduct;
      if (batchFilterWarehouse !== 'all') filters.warehouse_id = batchFilterWarehouse;
      if (batchFilterStatus !== 'all') filters.status = batchFilterStatus;
      if (batchSearch) filters.search = batchSearch;

      const data = await getBatches(filters);
      setBatches(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load batches',
        variant: 'destructive',
      });
    } finally {
      setBatchLoading(false);
    }
  };

  // Serial Number Handlers
  const handleCreateSerial = () => {
    setSerialFormData({
      product_id: '',
      serial_number: '',
      warehouse_id: '',
      status: 'available',
      notes: '',
    });
    setSelectedSerial(null);
    setIsSerialDialogOpen(true);
  };

  const handleEditSerial = (serial: SerialNumber) => {
    setSerialFormData({
      ...serial,
    });
    setSelectedSerial(serial);
    setIsSerialDialogOpen(true);
  };

  const handleViewSerial = (serial: SerialNumber) => {
    setSelectedSerial(serial);
    setIsSerialViewDialogOpen(true);
  };

  const handleDeleteSerial = async (serial: SerialNumber) => {
    if (!confirm(`Are you sure you want to delete serial number "${serial.serial_number}"?`)) {
      return;
    }

    try {
      await deleteSerialNumber(serial.id);
      toast({
        title: 'Success',
        description: 'Serial number deleted successfully',
      });
      loadSerialNumbers();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete serial number',
        variant: 'destructive',
      });
    }
  };

  const handleSubmitSerial = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!serialFormData.product_id || !serialFormData.serial_number) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsSerialSubmitting(true);
      if (selectedSerial) {
        await updateSerialNumber(selectedSerial.id, serialFormData);
        toast({
          title: 'Success',
          description: 'Serial number updated successfully',
        });
      } else {
        await createSerialNumber(serialFormData);
        toast({
          title: 'Success',
          description: 'Serial number created successfully',
        });
      }
      setIsSerialDialogOpen(false);
      loadSerialNumbers();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save serial number',
        variant: 'destructive',
      });
    } finally {
      setIsSerialSubmitting(false);
    }
  };

  // Batch Handlers
  const handleCreateBatch = () => {
    setBatchFormData({
      product_id: '',
      batch_number: '',
      warehouse_id: '',
      quantity: 0,
      manufacture_date: '',
      expiry_date: '',
      cost_per_unit: 0,
      status: 'active',
      notes: '',
    });
    setSelectedBatch(null);
    setIsBatchDialogOpen(true);
  };

  const handleEditBatch = (batch: Batch) => {
    setBatchFormData({
      ...batch,
    });
    setSelectedBatch(batch);
    setIsBatchDialogOpen(true);
  };

  const handleViewBatch = (batch: Batch) => {
    setSelectedBatch(batch);
    setIsBatchViewDialogOpen(true);
  };

  const handleDeleteBatch = async (batch: Batch) => {
    if (!confirm(`Are you sure you want to delete batch "${batch.batch_number}"?`)) {
      return;
    }

    try {
      await deleteBatch(batch.id);
      toast({
        title: 'Success',
        description: 'Batch deleted successfully',
      });
      loadBatches();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete batch',
        variant: 'destructive',
      });
    }
  };

  const handleSubmitBatch = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!batchFormData.product_id || !batchFormData.batch_number) {
      toast({
        title: 'Validation Error',
        description: 'Please fill in all required fields',
        variant: 'destructive',
      });
      return;
    }

    try {
      setIsBatchSubmitting(true);
      if (selectedBatch) {
        await updateBatch(selectedBatch.id, batchFormData);
        toast({
          title: 'Success',
          description: 'Batch updated successfully',
        });
      } else {
        await createBatch(batchFormData);
        toast({
          title: 'Success',
          description: 'Batch created successfully',
        });
      }
      setIsBatchDialogOpen(false);
      loadBatches();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save batch',
        variant: 'destructive',
      });
    } finally {
      setIsBatchSubmitting(false);
    }
  };

  const getSerialStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      available: 'default',
      reserved: 'outline',
      sold: 'secondary',
      returned: 'outline',
      damaged: 'destructive',
    };
    const icons: Record<string, unknown> = {
      available: CheckCircle2,
      reserved: Clock,
      sold: Package,
      returned: XCircle,
      damaged: AlertTriangle,
    };
    const Icon = icons[status] || CheckCircle2;
    return (
      <Badge variant={variants[status] || 'outline'}>
        <Icon className="mr-1 h-3 w-3" />
        {status.toUpperCase()}
      </Badge>
    );
  };

  const getBatchStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      active: 'default',
      expired: 'destructive',
      consumed: 'secondary',
      damaged: 'destructive',
    };
    return (
      <Badge variant={variants[status] || 'outline'}>
        {status.toUpperCase()}
      </Badge>
    );
  };

  const serialStats = {
    total: serialNumbers.length,
    available: serialNumbers.filter((s) => s.status === 'available').length,
    reserved: serialNumbers.filter((s) => s.status === 'reserved').length,
    sold: serialNumbers.filter((s) => s.status === 'sold').length,
  };

  const batchStats = {
    total: batches.length,
    active: batches.filter((b) => b.status === 'active').length,
    expired: batches.filter((b) => b.status === 'expired').length,
    totalQuantity: batches.reduce((sum, b) => {
      const qty = typeof b.quantity === 'number' ? b.quantity : parseFloat(String(b.quantity || 0));
      return sum + (isNaN(qty) ? 0 : qty);
    }, 0),
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Serial & Batch Tracking</h1>
          <p className="text-muted-foreground">Manage serial numbers and batch tracking</p>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as 'serial' | 'batch')}>
        <TabsList>
          <TabsTrigger value="serial">Serial Numbers</TabsTrigger>
          <TabsTrigger value="batch">Batches</TabsTrigger>
        </TabsList>

        {/* Serial Numbers Tab */}
        <TabsContent value="serial" className="space-y-6">
          {/* Statistics */}
          <div className="grid gap-4 md:grid-cols-4">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Total Serial Numbers</CardTitle>
                <Hash className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{serialStats.total}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Available</CardTitle>
                <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-green-600">{serialStats.available}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Reserved</CardTitle>
                <Clock className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-orange-600">{serialStats.reserved}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Sold</CardTitle>
                <Package className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-blue-600">{serialStats.sold}</div>
              </CardContent>
            </Card>
          </div>

          {/* Filters */}
          <Card>
            <CardHeader>
              <CardTitle>Filters</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-5">
                <div className="space-y-2">
                  <Label>Search</Label>
                  <div className="relative">
                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search serial numbers..."
                      value={serialSearch}
                      onChange={(e) => setSerialSearch(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && loadSerialNumbers()}
                      className="pl-8"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Product</Label>
                  <Select value={serialFilterProduct} onValueChange={setSerialFilterProduct}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Products" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Products</SelectItem>
                      {products.map((product) => (
                        <SelectItem key={product.id} value={product.id}>
                          {product.sku} - {product.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Warehouse</Label>
                  <Select value={serialFilterWarehouse} onValueChange={setSerialFilterWarehouse}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Warehouses" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Warehouses</SelectItem>
                      {warehouses.map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.code} - {warehouse.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Status</Label>
                  <Select value={serialFilterStatus} onValueChange={setSerialFilterStatus}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Status" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Status</SelectItem>
                      <SelectItem value="available">Available</SelectItem>
                      <SelectItem value="reserved">Reserved</SelectItem>
                      <SelectItem value="sold">Sold</SelectItem>
                      <SelectItem value="returned">Returned</SelectItem>
                      <SelectItem value="damaged">Damaged</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex items-end">
                  <Button onClick={handleCreateSerial} className="w-full">
                    <Plus className="mr-2 h-4 w-4" />
                    Create Serial
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Serial Numbers Table */}
          <Card>
            <CardHeader>
              <CardTitle>Serial Numbers</CardTitle>
              <CardDescription>Manage all serial number tracking</CardDescription>
            </CardHeader>
            <CardContent>
              {serialLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                </div>
              ) : serialNumbers.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  No serial numbers found. Create your first serial number to get started.
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Serial Number</TableHead>
                      <TableHead>Product</TableHead>
                      <TableHead>Warehouse</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead>Created</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {serialNumbers.map((serial) => (
                      <TableRow key={serial.id}>
                        <TableCell className="font-mono font-medium">{serial.serial_number}</TableCell>
                        <TableCell>
                          {serial.product_name ? (
                            <div>
                              <div className="font-mono text-sm">{serial.product_sku}</div>
                              <div className="text-sm text-muted-foreground">{serial.product_name}</div>
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          {serial.warehouse_name ? (
                            <div>
                              <div className="font-mono text-sm">{serial.warehouse_code}</div>
                              <div className="text-sm text-muted-foreground">{serial.warehouse_name}</div>
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>{getSerialStatusBadge(serial.status)}</TableCell>
                        <TableCell>
                          {new Date(serial.created_at).toLocaleDateString()}
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleViewSerial(serial)}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEditSerial(serial)}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDeleteSerial(serial)}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Batches Tab */}
        <TabsContent value="batch" className="space-y-6">
          {/* Statistics */}
          <div className="grid gap-4 md:grid-cols-4">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Total Batches</CardTitle>
                <Package className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{batchStats.total}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Active</CardTitle>
                <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-green-600">{batchStats.active}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Expired</CardTitle>
                <AlertTriangle className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold text-red-600">{batchStats.expired}</div>
              </CardContent>
            </Card>
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Total Quantity</CardTitle>
                <Hash className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">
                  {(typeof batchStats.totalQuantity === 'number' ? batchStats.totalQuantity : parseFloat(String(batchStats.totalQuantity || 0))).toLocaleString()}
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Filters */}
          <Card>
            <CardHeader>
              <CardTitle>Filters</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid gap-4 md:grid-cols-5">
                <div className="space-y-2">
                  <Label>Search</Label>
                  <div className="relative">
                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search batches..."
                      value={batchSearch}
                      onChange={(e) => setBatchSearch(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && loadBatches()}
                      className="pl-8"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Product</Label>
                  <Select value={batchFilterProduct} onValueChange={setBatchFilterProduct}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Products" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Products</SelectItem>
                      {products.map((product) => (
                        <SelectItem key={product.id} value={product.id}>
                          {product.sku} - {product.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Warehouse</Label>
                  <Select value={batchFilterWarehouse} onValueChange={setBatchFilterWarehouse}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Warehouses" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Warehouses</SelectItem>
                      {warehouses.map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.code} - {warehouse.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Status</Label>
                  <Select value={batchFilterStatus} onValueChange={setBatchFilterStatus}>
                    <SelectTrigger>
                      <SelectValue placeholder="All Status" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Status</SelectItem>
                      <SelectItem value="active">Active</SelectItem>
                      <SelectItem value="expired">Expired</SelectItem>
                      <SelectItem value="consumed">Consumed</SelectItem>
                      <SelectItem value="damaged">Damaged</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="flex items-end">
                  <Button onClick={handleCreateBatch} className="w-full">
                    <Plus className="mr-2 h-4 w-4" />
                    Create Batch
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Batches Table */}
          <Card>
            <CardHeader>
              <CardTitle>Batches</CardTitle>
              <CardDescription>Manage all batch tracking</CardDescription>
            </CardHeader>
            <CardContent>
              {batchLoading ? (
                <div className="flex items-center justify-center py-8">
                  <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
                </div>
              ) : batches.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  No batches found. Create your first batch to get started.
                </div>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Batch Number</TableHead>
                      <TableHead>Product</TableHead>
                      <TableHead>Warehouse</TableHead>
                      <TableHead>Quantity</TableHead>
                      <TableHead>Expiry Date</TableHead>
                      <TableHead>Status</TableHead>
                      <TableHead className="text-right">Actions</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {batches.map((batch) => (
                      <TableRow key={batch.id}>
                        <TableCell className="font-mono font-medium">{batch.batch_number}</TableCell>
                        <TableCell>
                          {batch.product_name ? (
                            <div>
                              <div className="font-mono text-sm">{batch.product_sku}</div>
                              <div className="text-sm text-muted-foreground">{batch.product_name}</div>
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          {batch.warehouse_name ? (
                            <div>
                              <div className="font-mono text-sm">{batch.warehouse_code}</div>
                              <div className="text-sm text-muted-foreground">{batch.warehouse_name}</div>
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>
                          {(typeof batch.quantity === 'number' ? batch.quantity : parseFloat(String(batch.quantity || 0))).toLocaleString()}
                        </TableCell>
                        <TableCell>
                          {batch.expiry_date ? (
                            <div className="flex items-center gap-2">
                              {new Date(batch.expiry_date) < new Date() && (
                                <AlertTriangle className="h-4 w-4 text-red-500" />
                              )}
                              {new Date(batch.expiry_date).toLocaleDateString()}
                            </div>
                          ) : (
                            '-'
                          )}
                        </TableCell>
                        <TableCell>{getBatchStatusBadge(batch.status)}</TableCell>
                        <TableCell className="text-right">
                          <div className="flex justify-end gap-2">
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleViewBatch(batch)}
                            >
                              <Eye className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleEditBatch(batch)}
                            >
                              <Edit className="h-4 w-4" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleDeleteBatch(batch)}
                            >
                              <Trash2 className="h-4 w-4" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Serial Number Create/Edit Dialog */}
      <Dialog open={isSerialDialogOpen} onOpenChange={setIsSerialDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {selectedSerial ? 'Edit Serial Number' : 'Create Serial Number'}
            </DialogTitle>
            <DialogDescription>
              {selectedSerial
                ? 'Update serial number details'
                : 'Create a new serial number record'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmitSerial}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="product_id">Product *</Label>
                  <Select
                    value={serialFormData.product_id || ''}
                    onValueChange={(value) => setSerialFormData({ ...serialFormData, product_id: value })}
                    disabled={!!selectedSerial}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select product" />
                    </SelectTrigger>
                    <SelectContent>
                      {products.map((product) => (
                        <SelectItem key={product.id} value={product.id}>
                          {product.sku} - {product.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="serial_number">Serial Number *</Label>
                  <Input
                    id="serial_number"
                    value={serialFormData.serial_number || ''}
                    onChange={(e) => setSerialFormData({ ...serialFormData, serial_number: e.target.value })}
                    placeholder="Enter serial number"
                    disabled={!!selectedSerial}
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="warehouse_id">Warehouse</Label>
                  <Select
                    value={serialFormData.warehouse_id || ''}
                    onValueChange={(value) => setSerialFormData({ ...serialFormData, warehouse_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select warehouse" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="">None</SelectItem>
                      {warehouses.map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.code} - {warehouse.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="status">Status</Label>
                  <Select
                    value={serialFormData.status || 'available'}
                    onValueChange={(value: unknown) => setSerialFormData({ ...serialFormData, status: value })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="available">Available</SelectItem>
                      <SelectItem value="reserved">Reserved</SelectItem>
                      <SelectItem value="sold">Sold</SelectItem>
                      <SelectItem value="returned">Returned</SelectItem>
                      <SelectItem value="damaged">Damaged</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="notes">Notes</Label>
                <Textarea
                  id="notes"
                  value={serialFormData.notes || ''}
                  onChange={(e) => setSerialFormData({ ...serialFormData, notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={3}
                />
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsSerialDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSerialSubmitting}>
                {isSerialSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedSerial ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Serial Number View Dialog */}
      <Dialog open={isSerialViewDialogOpen} onOpenChange={setIsSerialViewDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Serial Number Details</DialogTitle>
            <DialogDescription>View serial number information</DialogDescription>
          </DialogHeader>
          {selectedSerial && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Serial Number</Label>
                  <div className="mt-1 font-mono font-medium">{selectedSerial.serial_number}</div>
                </div>
                <div>
                  <Label>Product</Label>
                  <div className="mt-1">
                    {selectedSerial.product_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedSerial.product_sku}</div>
                        <div className="text-sm text-muted-foreground">{selectedSerial.product_name}</div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Warehouse</Label>
                  <div className="mt-1">
                    {selectedSerial.warehouse_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedSerial.warehouse_code}</div>
                        <div className="text-sm text-muted-foreground">{selectedSerial.warehouse_name}</div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">{getSerialStatusBadge(selectedSerial.status)}</div>
                </div>
                {selectedSerial.notes && (
                  <div className="md:col-span-2">
                    <Label>Notes</Label>
                    <div className="mt-1">{selectedSerial.notes}</div>
                  </div>
                )}
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedSerial.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsSerialViewDialogOpen(false)}>
              Close
            </Button>
            {selectedSerial && (
              <Button
                onClick={() => {
                  setIsSerialViewDialogOpen(false);
                  handleEditSerial(selectedSerial);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Batch Create/Edit Dialog */}
      <Dialog open={isBatchDialogOpen} onOpenChange={setIsBatchDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {selectedBatch ? 'Edit Batch' : 'Create Batch'}
            </DialogTitle>
            <DialogDescription>
              {selectedBatch
                ? 'Update batch details'
                : 'Create a new batch record'}
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSubmitBatch}>
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="batch_product_id">Product *</Label>
                  <Select
                    value={batchFormData.product_id || ''}
                    onValueChange={(value) => setBatchFormData({ ...batchFormData, product_id: value })}
                    disabled={!!selectedBatch}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select product" />
                    </SelectTrigger>
                    <SelectContent>
                      {products.map((product) => (
                        <SelectItem key={product.id} value={product.id}>
                          {product.sku} - {product.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="batch_number">Batch Number *</Label>
                  <Input
                    id="batch_number"
                    value={batchFormData.batch_number || ''}
                    onChange={(e) => setBatchFormData({ ...batchFormData, batch_number: e.target.value })}
                    placeholder="Enter batch number"
                    disabled={!!selectedBatch}
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="space-y-2">
                  <Label htmlFor="warehouse_id_batch">Warehouse</Label>
                  <Select
                    value={batchFormData.warehouse_id || ''}
                    onValueChange={(value) => setBatchFormData({ ...batchFormData, warehouse_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select warehouse" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="">None</SelectItem>
                      {warehouses.map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.code} - {warehouse.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label htmlFor="quantity">Quantity</Label>
                  <Input
                    id="quantity"
                    type="number"
                    step="0.01"
                    value={batchFormData.quantity || 0}
                    onChange={(e) =>
                      setBatchFormData({ ...batchFormData, quantity: parseFloat(e.target.value) || 0 })
                    }
                    placeholder="0.00"
                  />
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-3">
                <div className="space-y-2">
                  <Label htmlFor="manufacture_date">Manufacture Date</Label>
                  <Input
                    id="manufacture_date"
                    type="date"
                    value={batchFormData.manufacture_date || ''}
                    onChange={(e) => setBatchFormData({ ...batchFormData, manufacture_date: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="expiry_date">Expiry Date</Label>
                  <Input
                    id="expiry_date"
                    type="date"
                    value={batchFormData.expiry_date || ''}
                    onChange={(e) => setBatchFormData({ ...batchFormData, expiry_date: e.target.value })}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="cost_per_unit">Cost Per Unit</Label>
                  <Input
                    id="cost_per_unit"
                    type="number"
                    step="0.01"
                    value={batchFormData.cost_per_unit || 0}
                    onChange={(e) =>
                      setBatchFormData({ ...batchFormData, cost_per_unit: parseFloat(e.target.value) || 0 })
                    }
                    placeholder="0.00"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="status_batch">Status</Label>
                <Select
                  value={batchFormData.status || 'active'}
                  onValueChange={(value: unknown) => setBatchFormData({ ...batchFormData, status: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="expired">Expired</SelectItem>
                    <SelectItem value="consumed">Consumed</SelectItem>
                    <SelectItem value="damaged">Damaged</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label htmlFor="notes_batch">Notes</Label>
                <Textarea
                  id="notes_batch"
                  value={batchFormData.notes || ''}
                  onChange={(e) => setBatchFormData({ ...batchFormData, notes: e.target.value })}
                  placeholder="Additional notes..."
                  rows={3}
                />
              </div>
            </div>
            <DialogFooter className="mt-6">
              <Button type="button" variant="outline" onClick={() => setIsBatchDialogOpen(false)}>
                Cancel
              </Button>
              <Button type="submit" disabled={isBatchSubmitting}>
                {isBatchSubmitting && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
                {selectedBatch ? 'Update' : 'Create'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      {/* Batch View Dialog */}
      <Dialog open={isBatchViewDialogOpen} onOpenChange={setIsBatchViewDialogOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Batch Details</DialogTitle>
            <DialogDescription>View batch information</DialogDescription>
          </DialogHeader>
          {selectedBatch && (
            <div className="space-y-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Label>Batch Number</Label>
                  <div className="mt-1 font-mono font-medium">{selectedBatch.batch_number}</div>
                </div>
                <div>
                  <Label>Product</Label>
                  <div className="mt-1">
                    {selectedBatch.product_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedBatch.product_sku}</div>
                        <div className="text-sm text-muted-foreground">{selectedBatch.product_name}</div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Warehouse</Label>
                  <div className="mt-1">
                    {selectedBatch.warehouse_name ? (
                      <div>
                        <div className="font-mono text-sm">{selectedBatch.warehouse_code}</div>
                        <div className="text-sm text-muted-foreground">{selectedBatch.warehouse_name}</div>
                      </div>
                    ) : (
                      '-'
                    )}
                  </div>
                </div>
                <div>
                  <Label>Quantity</Label>
                  <div className="mt-1">
                    {(typeof selectedBatch.quantity === 'number' ? selectedBatch.quantity : parseFloat(String(selectedBatch.quantity || 0))).toLocaleString()}
                  </div>
                </div>
                {selectedBatch.manufacture_date && (
                  <div>
                    <Label>Manufacture Date</Label>
                    <div className="mt-1">
                      {new Date(selectedBatch.manufacture_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {selectedBatch.expiry_date && (
                  <div>
                    <Label>Expiry Date</Label>
                    <div className="mt-1 flex items-center gap-2">
                      {new Date(selectedBatch.expiry_date) < new Date() && (
                        <AlertTriangle className="h-4 w-4 text-red-500" />
                      )}
                      {new Date(selectedBatch.expiry_date).toLocaleDateString()}
                    </div>
                  </div>
                )}
                {selectedBatch.cost_per_unit && (
                  <div>
                    <Label>Cost Per Unit</Label>
                    <div className="mt-1">
                      $
                      {(typeof selectedBatch.cost_per_unit === 'number'
                        ? selectedBatch.cost_per_unit
                        : parseFloat(String(selectedBatch.cost_per_unit || 0))
                      ).toLocaleString('en-US', {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2,
                      })}
                    </div>
                  </div>
                )}
                <div>
                  <Label>Status</Label>
                  <div className="mt-1">{getBatchStatusBadge(selectedBatch.status)}</div>
                </div>
                {selectedBatch.notes && (
                  <div className="md:col-span-2">
                    <Label>Notes</Label>
                    <div className="mt-1">{selectedBatch.notes}</div>
                  </div>
                )}
                <div>
                  <Label>Created</Label>
                  <div className="mt-1">
                    {new Date(selectedBatch.created_at).toLocaleString()}
                  </div>
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsBatchViewDialogOpen(false)}>
              Close
            </Button>
            {selectedBatch && (
              <Button
                onClick={() => {
                  setIsBatchViewDialogOpen(false);
                  handleEditBatch(selectedBatch);
                }}
              >
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Inventory Settings Page
 * Configure inventory module settings and preferences
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Settings,
  Save,
  Loader2,
  Package,
  AlertTriangle,
  DollarSign,
  Warehouse,
  RefreshCw,
} from 'lucide-react';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Separator } from '@/components/ui/separator';
import { getWarehouses, type Warehouse as WarehouseType } from '@/services/api/inventory';

interface InventorySettings {
  // Valuation
  default_valuation_method: 'FIFO' | 'LIFO' | 'weighted_average';
  
  // Reorder Settings
  auto_reorder_enabled: boolean;
  low_stock_alert_enabled: boolean;
  low_stock_threshold_percentage: number;
  
  // Defaults
  default_unit_of_measure: string;
  default_warehouse_id?: string;
  
  // Tracking
  enable_serial_tracking: boolean;
  enable_batch_tracking: boolean;
  require_serial_on_sale: boolean;
  
  // Costing
  auto_calculate_cost: boolean;
  include_shipping_in_cost: boolean;
  
  // Notifications
  notify_on_low_stock: boolean;
  notify_on_reorder: boolean;
  notify_on_stock_adjustment: boolean;
}

export default function InventorySettings() {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);
  const [settings, setSettings] = useState<InventorySettings>({
    default_valuation_method: 'weighted_average',
    auto_reorder_enabled: false,
    low_stock_alert_enabled: true,
    low_stock_threshold_percentage: 20,
    default_unit_of_measure: 'pcs',
    enable_serial_tracking: false,
    enable_batch_tracking: false,
    require_serial_on_sale: false,
    auto_calculate_cost: true,
    include_shipping_in_cost: false,
    notify_on_low_stock: true,
    notify_on_reorder: true,
    notify_on_stock_adjustment: false,
  });

  useEffect(() => {
    loadSettings();
    loadWarehouses();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const { getInventorySettings } = await import('@/services/api/system');
      const data = await getInventorySettings();
      setSettings(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load settings',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const loadWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      logError('Failed to load warehouses:', error);
      // Don't show toast for warehouses as it's not critical
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      const { updateInventorySettings } = await import('@/services/api/system');
      await updateInventorySettings(settings);
      toast({
        title: 'Success',
        description: 'Settings saved successfully',
      });
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save settings',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Inventory Settings</h1>
          <p className="text-muted-foreground">Configure inventory module preferences and defaults</p>
        </div>
        <Button onClick={handleSave} disabled={saving}>
          {saving ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="w-4 h-4 mr-2" />
              Save Settings
            </>
          )}
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        {/* Valuation Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <DollarSign className="w-5 h-5" />
              Valuation Settings
            </CardTitle>
            <CardDescription>Configure how inventory costs are calculated</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Default Valuation Method</Label>
              <Select
                value={settings.default_valuation_method}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_valuation_method: value as unknown })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="FIFO">FIFO (First In, First Out)</SelectItem>
                  <SelectItem value="LIFO">LIFO (Last In, First Out)</SelectItem>
                  <SelectItem value="weighted_average">Weighted Average</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto Calculate Cost</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically calculate product costs from purchase orders
                </p>
              </div>
              <Switch
                checked={settings.auto_calculate_cost}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, auto_calculate_cost: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Include Shipping in Cost</Label>
                <p className="text-sm text-muted-foreground">
                  Include shipping costs when calculating product costs
                </p>
              </div>
              <Switch
                checked={settings.include_shipping_in_cost}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, include_shipping_in_cost: checked })
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* Reorder Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <RefreshCw className="w-5 h-5" />
              Reorder Settings
            </CardTitle>
            <CardDescription>Configure automatic reordering and alerts</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto Reorder Enabled</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically create purchase orders when stock is low
                </p>
              </div>
              <Switch
                checked={settings.auto_reorder_enabled}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, auto_reorder_enabled: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Low Stock Alerts</Label>
                <p className="text-sm text-muted-foreground">
                  Enable alerts when stock falls below reorder point
                </p>
              </div>
              <Switch
                checked={settings.low_stock_alert_enabled}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, low_stock_alert_enabled: checked })
                }
              />
            </div>
            <div>
              <Label>Low Stock Threshold (%)</Label>
              <Input
                type="number"
                min="0"
                max="100"
                value={settings.low_stock_threshold_percentage}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    low_stock_threshold_percentage: parseInt(e.target.value) || 0,
                  })
                }
              />
              <p className="text-sm text-muted-foreground mt-1">
                Alert when stock is below this percentage of reorder point
              </p>
            </div>
          </CardContent>
        </Card>

        {/* Defaults */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Package className="w-5 h-5" />
              Default Settings
            </CardTitle>
            <CardDescription>Set default values for new products</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Default Unit of Measure</Label>
              <Select
                value={settings.default_unit_of_measure}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_unit_of_measure: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="pcs">Pieces (pcs)</SelectItem>
                  <SelectItem value="kg">Kilograms (kg)</SelectItem>
                  <SelectItem value="g">Grams (g)</SelectItem>
                  <SelectItem value="l">Liters (l)</SelectItem>
                  <SelectItem value="ml">Milliliters (ml)</SelectItem>
                  <SelectItem value="m">Meters (m)</SelectItem>
                  <SelectItem value="cm">Centimeters (cm)</SelectItem>
                  <SelectItem value="box">Box</SelectItem>
                  <SelectItem value="pack">Pack</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Default Warehouse (Optional)</Label>
              <Select
                value={settings.default_warehouse_id || ''}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_warehouse_id: value || undefined })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="No default warehouse" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="">No default warehouse</SelectItem>
                  {warehouses.map((warehouse) => (
                    <SelectItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.name} {warehouse.is_primary && '(Primary)'}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>

        {/* Tracking Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Warehouse className="w-5 h-5" />
              Tracking Settings
            </CardTitle>
            <CardDescription>Configure serial number and batch tracking</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Enable Serial Tracking</Label>
                <p className="text-sm text-muted-foreground">
                  Allow tracking products by serial number
                </p>
              </div>
              <Switch
                checked={settings.enable_serial_tracking}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, enable_serial_tracking: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Enable Batch Tracking</Label>
                <p className="text-sm text-muted-foreground">
                  Allow tracking products by batch/lot number
                </p>
              </div>
              <Switch
                checked={settings.enable_batch_tracking}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, enable_batch_tracking: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Require Serial on Sale</Label>
                <p className="text-sm text-muted-foreground">
                  Require serial number when selling tracked products
                </p>
              </div>
              <Switch
                checked={settings.require_serial_on_sale}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, require_serial_on_sale: checked })
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* Notification Settings */}
        <Card className="md:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              Notification Settings
            </CardTitle>
            <CardDescription>Configure when to receive notifications</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Low Stock Notifications</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when stock is low
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_low_stock}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_low_stock: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Reorder Notifications</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when reorder is triggered
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_reorder}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_reorder: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Stock Adjustment Notifications</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify on stock adjustments
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_stock_adjustment}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_stock_adjustment: checked })
                  }
                />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

/**
 * Inventory Stock Levels Page
 * Real-time stock tracking and inventory visibility
 */

import { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Package,
  Search,
  Loader2,
  TrendingUp,
  TrendingDown,
  AlertTriangle,
  Warehouse,
  Filter,
  Download,
  RefreshCw,
  Eye,
} from 'lucide-react';
import {
  getProducts,
  getWarehouses,
  getInventoryLevels,
  getLowStockAlerts,
  type Product,
  type Warehouse as WarehouseType,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

interface InventoryLevel {
  id: string;
  product_id: string;
  variant_id?: string;
  warehouse_id: string;
  quantity: number;
  reserved_quantity: number;
  available_quantity: number;
  reorder_point: number;
  reorder_quantity: number;
  product_name: string;
  product_sku: string;
  warehouse_name: string;
  warehouse_code: string;
}

interface LowStockAlert {
  id: string;
  product_id: string;
  warehouse_id: string;
  product_name: string;
  product_sku: string;
  warehouse_name: string;
  available_quantity: number;
  reorder_point: number;
  shortage: number;
}

export default function InventoryStockLevels() {
  const [searchParams] = useSearchParams();
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Data
  const [inventoryLevels, setInventoryLevels] = useState<InventoryLevel[]>([]);
  const [filteredLevels, setFilteredLevels] = useState<InventoryLevel[]>([]);
  const [lowStockAlerts, setLowStockAlerts] = useState<LowStockAlert[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);

  // Filters
  const [productFilter, setProductFilter] = useState<string>(
    searchParams.get('product') || 'all'
  );
  const [warehouseFilter, setWarehouseFilter] = useState<string>(
    searchParams.get('warehouse') || 'all'
  );
  const [searchTerm, setSearchTerm] = useState('');
  const [viewMode, setViewMode] = useState<'all' | 'low-stock' | 'out-of-stock'>('all');

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchInventoryLevels(),
          fetchLowStockAlerts(),
          fetchProducts(),
          fetchWarehouses(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading stock data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load stock levels',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, [productFilter, warehouseFilter]);

  // Apply filters
  useEffect(() => {
    let filtered = inventoryLevels;

    // Product filter
    if (productFilter !== 'all') {
      filtered = filtered.filter(level => level.product_id === productFilter);
    }

    // Warehouse filter
    if (warehouseFilter !== 'all') {
      filtered = filtered.filter(level => level.warehouse_id === warehouseFilter);
    }

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(level =>
        level.product_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        level.product_sku.toLowerCase().includes(searchTerm.toLowerCase()) ||
        level.warehouse_name.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // View mode filter
    if (viewMode === 'low-stock') {
      filtered = filtered.filter(level => 
        level.available_quantity <= level.reorder_point && level.reorder_point > 0
      );
    } else if (viewMode === 'out-of-stock') {
      filtered = filtered.filter(level => level.available_quantity <= 0);
    }

    setFilteredLevels(filtered);
  }, [inventoryLevels, productFilter, warehouseFilter, searchTerm, viewMode]);

  const fetchInventoryLevels = async () => {
    try {
      setLoading(true);
      let levels: InventoryLevel[] = [];

      if (productFilter !== 'all') {
        // Get levels for specific product
        const productLevels = await getInventoryLevels(productFilter);
        levels = productLevels as unknown;
      } else {
        // Get all products and their levels
        const allProducts = await getProducts();
        const allLevels: InventoryLevel[] = [];

        for (const product of allProducts) {
          try {
            const productLevels = await getInventoryLevels(product.id);
            if (Array.isArray(productLevels)) {
              allLevels.push(...(productLevels as unknown));
            }
          } catch (error) {
            // Product might not have inventory levels yet
            console.warn(`No inventory levels for product ${product.id}`);
          }
        }

        levels = allLevels;
      }

      setInventoryLevels(levels);
    } catch (error: unknown) {
      console.error('Error fetching inventory levels:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch inventory levels',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchLowStockAlerts = async () => {
    try {
      const alerts = await getLowStockAlerts();
      setLowStockAlerts(alerts as unknown);
    } catch (error: unknown) {
      console.error('Error fetching low stock alerts:', error);
    }
  };

  const fetchProducts = async () => {
    try {
      const data = await getProducts();
      setProducts(data || []);
    } catch (error: unknown) {
      console.error('Error fetching products:', error);
    }
  };

  const fetchWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      console.error('Error fetching warehouses:', error);
    }
  };

  const handleRefresh = () => {
    fetchInventoryLevels();
    fetchLowStockAlerts();
    toast({
      title: 'Refreshed',
      description: 'Stock levels updated',
    });
  };

  // Calculate statistics
  const totalValue = inventoryLevels.reduce((sum, level) => {
    // This would need unit cost from products - simplified for now
    return sum + level.quantity;
  }, 0);

  const lowStockCount = inventoryLevels.filter(
    level => level.available_quantity <= level.reorder_point && level.reorder_point > 0
  ).length;

  const outOfStockCount = inventoryLevels.filter(
    level => level.available_quantity <= 0
  ).length;

  const totalProducts = new Set(inventoryLevels.map(level => level.product_id)).size;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Stock Levels</h1>
          <p className="text-muted-foreground mt-1">
            Real-time inventory tracking and stock visibility
          </p>
        </div>
        <Button onClick={handleRefresh} variant="outline">
          <RefreshCw className="mr-2 h-4 w-4" />
          Refresh
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Products</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalProducts}</div>
            <p className="text-xs text-muted-foreground">
              Products with inventory
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Low Stock</CardTitle>
            <AlertTriangle className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-yellow-600">{lowStockCount}</div>
            <p className="text-xs text-muted-foreground">
              Below reorder point
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Out of Stock</CardTitle>
            <AlertTriangle className="h-4 w-4 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold text-red-600">{outOfStockCount}</div>
            <p className="text-xs text-muted-foreground">
              Zero inventory
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Quantity</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {inventoryLevels.reduce((sum, level) => {
                const qty = typeof level.quantity === 'number' ? level.quantity : parseFloat(String(level.quantity || 0));
                return sum + (isNaN(qty) ? 0 : qty);
              }, 0).toLocaleString()}
            </div>
            <p className="text-xs text-muted-foreground">
              Units across all warehouses
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Low Stock Alerts */}
      {lowStockAlerts.length > 0 && (
        <Alert className="border-yellow-500 bg-yellow-50">
          <AlertTriangle className="h-4 w-4 text-yellow-600" />
          <AlertDescription className="text-yellow-800">
            <strong>{lowStockAlerts.length} products</strong> are below reorder point and need restocking.
          </AlertDescription>
        </Alert>
      )}

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-4">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search products..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Product</Label>
              <Select value={productFilter} onValueChange={setProductFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All products" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Products</SelectItem>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Warehouse</Label>
              <Select value={warehouseFilter} onValueChange={setWarehouseFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All warehouses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Warehouses</SelectItem>
                  {warehouses.map((warehouse) => (
                    <SelectItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>View Mode</Label>
              <Select value={viewMode} onValueChange={(value: unknown) => setViewMode(value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Stock</SelectItem>
                  <SelectItem value="low-stock">Low Stock</SelectItem>
                  <SelectItem value="out-of-stock">Out of Stock</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Stock Levels Table */}
      <Card>
        <CardHeader>
          <CardTitle>Inventory Levels ({filteredLevels.length})</CardTitle>
          <CardDescription>
            Current stock levels across all warehouses
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredLevels.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredLevels.length === 0 ? (
            <Alert>
              <AlertDescription>
                No inventory levels found. {searchTerm || productFilter !== 'all' || warehouseFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Products will appear here once inventory is added.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>SKU</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead className="text-right">Available</TableHead>
                    <TableHead className="text-right">Reserved</TableHead>
                    <TableHead className="text-right">Total</TableHead>
                    <TableHead className="text-right">Reorder Point</TableHead>
                    <TableHead>Status</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredLevels.map((level) => {
                    const isLowStock = level.available_quantity <= level.reorder_point && level.reorder_point > 0;
                    const isOutOfStock = level.available_quantity <= 0;
                    const status = isOutOfStock ? 'out-of-stock' : isLowStock ? 'low-stock' : 'in-stock';

                    return (
                      <TableRow key={level.id}>
                        <TableCell className="font-medium">{level.product_name}</TableCell>
                        <TableCell className="font-mono text-sm">{level.product_sku}</TableCell>
                        <TableCell>
                          <div className="flex items-center">
                            <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                            {level.warehouse_name}
                          </div>
                        </TableCell>
                        <TableCell className="text-right font-medium">
                          {(typeof level.available_quantity === 'number' ? level.available_quantity : parseFloat(String(level.available_quantity || 0))).toLocaleString()}
                        </TableCell>
                        <TableCell className="text-right text-muted-foreground">
                          {(typeof level.reserved_quantity === 'number' ? level.reserved_quantity : parseFloat(String(level.reserved_quantity || 0))).toLocaleString()}
                        </TableCell>
                        <TableCell className="text-right">
                          {(typeof level.quantity === 'number' ? level.quantity : parseFloat(String(level.quantity || 0))).toLocaleString()}
                        </TableCell>
                        <TableCell className="text-right">
                          {(() => {
                            const reorderPoint = typeof level.reorder_point === 'number' ? level.reorder_point : parseFloat(String(level.reorder_point || 0));
                            return reorderPoint > 0 ? reorderPoint.toLocaleString() : '-';
                          })()}
                        </TableCell>
                        <TableCell>
                          {status === 'out-of-stock' && (
                            <Badge variant="destructive">Out of Stock</Badge>
                          )}
                          {status === 'low-stock' && (
                            <Badge variant="outline" className="border-yellow-500 text-yellow-700">
                              Low Stock
                            </Badge>
                          )}
                          {status === 'in-stock' && (
                            <Badge variant="default">In Stock</Badge>
                          )}
                        </TableCell>
                      </TableRow>
                    );
                  })}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Low Stock Alerts Table */}
      {lowStockAlerts.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <AlertTriangle className="h-5 w-5 mr-2 text-yellow-600" />
              Low Stock Alerts ({lowStockAlerts.length})
            </CardTitle>
            <CardDescription>
              Products that need immediate attention
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>SKU</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead className="text-right">Available</TableHead>
                    <TableHead className="text-right">Reorder Point</TableHead>
                    <TableHead className="text-right">Shortage</TableHead>
                    <TableHead className="text-right">Reorder Qty</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {lowStockAlerts.map((alert) => (
                    <TableRow key={alert.id}>
                      <TableCell className="font-medium">{alert.product_name}</TableCell>
                      <TableCell className="font-mono text-sm">{alert.product_sku}</TableCell>
                      <TableCell>{alert.warehouse_name}</TableCell>
                      <TableCell className="text-right font-medium text-red-600">
                        {(typeof alert.available_quantity === 'number' ? alert.available_quantity : parseFloat(String(alert.available_quantity || 0))).toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right">
                        {(typeof alert.reorder_point === 'number' ? alert.reorder_point : parseFloat(String(alert.reorder_point || 0))).toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right font-medium text-red-600">
                        {(typeof alert.shortage === 'number' ? alert.shortage : parseFloat(String(alert.shortage || 0))).toLocaleString()}
                      </TableCell>
                      <TableCell className="text-right">
                        {/* This would come from inventory level */}
                        -
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * Inventory Transfers Page
 * Inter-warehouse transfer management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  ArrowRightLeft,
  Plus,
  Search,
  Loader2,
  Eye,
  Package,
  Warehouse,
  Calendar,
  MoreVertical,
  CheckCircle2,
  Clock,
  XCircle,
} from 'lucide-react';
import {
  getProducts,
  getWarehouses,
  createTransfer,
  getInventoryTransactions,
  type Product,
  type Warehouse as WarehouseType,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface Transfer {
  id: string;
  product_id: string;
  variant_id?: string;
  from_warehouse_id: string;
  to_warehouse_id: string;
  quantity: number;
  notes?: string;
  created_at: string;
  product_name?: string;
  product_sku?: string;
  from_warehouse_name?: string;
  to_warehouse_name?: string;
  status?: string;
}

interface InventoryTransaction {
  id: string;
  inventory_id: string;
  transaction_type: string;
  quantity: number;
  reference_type?: string;
  reference_id?: string;
  from_warehouse_id?: string;
  to_warehouse_id?: string;
  notes?: string;
  created_at: string;
  product_name?: string;
  product_sku?: string;
  warehouse_name?: string;
  warehouse_code?: string;
}

export default function InventoryTransfers() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Data
  const [transfers, setTransfers] = useState<Transfer[]>([]);
  const [filteredTransfers, setFilteredTransfers] = useState<Transfer[]>([]);
  const [products, setProducts] = useState<Product[]>([]);
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);
  const [selectedTransfer, setSelectedTransfer] = useState<Transfer | null>(null);
  const [showTransferDialog, setShowTransferDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [productFilter, setProductFilter] = useState<string>('all');
  const [warehouseFilter, setWarehouseFilter] = useState<string>('all');

  // Transfer form
  const [transferForm, setTransferForm] = useState({
    product_id: '',
    variant_id: '',
    from_warehouse_id: '',
    to_warehouse_id: '',
    quantity: '',
    notes: '',
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchTransfers(),
          fetchProducts(),
          fetchWarehouses(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading transfers data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load transfers',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = transfers;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(t =>
        t.product_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.product_sku?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.from_warehouse_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        t.to_warehouse_name?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Product filter
    if (productFilter !== 'all') {
      filtered = filtered.filter(t => t.product_id === productFilter);
    }

    // Warehouse filter
    if (warehouseFilter !== 'all') {
      filtered = filtered.filter(t =>
        t.from_warehouse_id === warehouseFilter || t.to_warehouse_id === warehouseFilter
      );
    }

    setFilteredTransfers(filtered);
  }, [transfers, searchTerm, productFilter, warehouseFilter]);

  const fetchTransfers = async () => {
    try {
      setLoading(true);
      // Get transfers from inventory transactions
      const transactions = await getInventoryTransactions({ transaction_type: 'TRANSFER' });
      
      // Group transactions by reference_id to create transfer pairs
      const transferMap = new Map<string, unknown>();
      
      transactions.forEach((tx: InventoryTransaction) => {
        if (tx.reference_id) {
          if (!transferMap.has(tx.reference_id)) {
            transferMap.set(tx.reference_id, {
              id: tx.reference_id,
              product_id: tx.product_name ? '' : '',
              from_warehouse_id: tx.from_warehouse_id || '',
              to_warehouse_id: tx.to_warehouse_id || '',
              quantity: Math.abs(tx.quantity),
              notes: tx.notes,
              created_at: tx.created_at,
              product_name: tx.product_name,
              product_sku: tx.product_sku,
              from_warehouse_name: tx.warehouse_name,
              to_warehouse_name: tx.to_warehouse_id ? '' : '',
              status: 'completed',
            });
          }
        } else {
          // Standalone transfer transaction
          transferMap.set(tx.id, {
            id: tx.id,
            product_id: '',
            from_warehouse_id: tx.from_warehouse_id || '',
            to_warehouse_id: tx.to_warehouse_id || '',
            quantity: Math.abs(tx.quantity),
            notes: tx.notes,
            created_at: tx.created_at,
            product_name: tx.product_name,
            product_sku: tx.product_sku,
            from_warehouse_name: tx.from_warehouse_id ? tx.warehouse_name : '',
            to_warehouse_name: tx.to_warehouse_id ? tx.warehouse_name : '',
            status: 'completed',
          });
        }
      });

      setTransfers(Array.from(transferMap.values()));
    } catch (error: unknown) {
      console.error('Error fetching transfers:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch transfers',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const data = await getProducts({ is_active: true });
      setProducts(data || []);
    } catch (error: unknown) {
      console.error('Error fetching products:', error);
    }
  };

  const fetchWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      console.error('Error fetching warehouses:', error);
    }
  };

  const handleCreateTransfer = async () => {
    try {
      if (!transferForm.product_id || !transferForm.from_warehouse_id || !transferForm.to_warehouse_id || !transferForm.quantity) {
        toast({
          title: 'Validation Error',
          description: 'Please fill in all required fields',
          variant: 'destructive',
        });
        return;
      }

      if (transferForm.from_warehouse_id === transferForm.to_warehouse_id) {
        toast({
          title: 'Validation Error',
          description: 'Source and destination warehouses must be different',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      await createTransfer({
        product_id: transferForm.product_id,
        variant_id: transferForm.variant_id || undefined,
        from_warehouse_id: transferForm.from_warehouse_id,
        to_warehouse_id: transferForm.to_warehouse_id,
        quantity: parseFloat(transferForm.quantity) || 0,
        notes: transferForm.notes || undefined,
      });

      toast({
        title: 'Success',
        description: 'Transfer created successfully',
      });

      setShowTransferDialog(false);
      resetForm();
      fetchTransfers();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create transfer',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewTransfer = (transfer: Transfer) => {
    setSelectedTransfer(transfer);
    setShowViewDialog(true);
  };

  const resetForm = () => {
    setTransferForm({
      product_id: '',
      variant_id: '',
      from_warehouse_id: '',
      to_warehouse_id: '',
      quantity: '',
      notes: '',
    });
  };

  const openCreateDialog = () => {
    resetForm();
    setShowTransferDialog(true);
  };

  // Calculate statistics
  const totalTransfers = transfers.length;
  const totalQuantity = transfers.reduce((sum, t) => {
    const qty = typeof t.quantity === 'number' ? t.quantity : parseFloat(String(t.quantity || 0));
    return sum + (isNaN(qty) ? 0 : qty);
  }, 0);
  const uniqueProducts = new Set(transfers.map(t => t.product_id)).size;
  const uniqueWarehouses = new Set([
    ...transfers.map(t => t.from_warehouse_id),
    ...transfers.map(t => t.to_warehouse_id),
  ]).size;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Inventory Transfers</h1>
          <p className="text-muted-foreground mt-1">
            Manage inter-warehouse inventory transfers
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create Transfer
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Transfers</CardTitle>
            <ArrowRightLeft className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalTransfers}</div>
            <p className="text-xs text-muted-foreground">
              All time transfers
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Quantity</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalQuantity.toLocaleString()}</div>
            <p className="text-xs text-muted-foreground">
              Units transferred
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Products</CardTitle>
            <Package className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{uniqueProducts}</div>
            <p className="text-xs text-muted-foreground">
              Unique products
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Warehouses</CardTitle>
            <Warehouse className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{uniqueWarehouses}</div>
            <p className="text-xs text-muted-foreground">
              Involved warehouses
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search transfers..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Product</Label>
              <Select value={productFilter} onValueChange={setProductFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All products" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Products</SelectItem>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Warehouse</Label>
              <Select value={warehouseFilter} onValueChange={setWarehouseFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All warehouses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Warehouses</SelectItem>
                  {warehouses.map((warehouse) => (
                    <SelectItem key={warehouse.id} value={warehouse.id}>
                      {warehouse.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Transfers Table */}
      <Card>
        <CardHeader>
          <CardTitle>Transfers ({filteredTransfers.length})</CardTitle>
          <CardDescription>
            Inter-warehouse inventory transfers
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredTransfers.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredTransfers.length === 0 ? (
            <Alert>
              <AlertDescription>
                No transfers found. {searchTerm || productFilter !== 'all' || warehouseFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first transfer to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Product</TableHead>
                    <TableHead>From Warehouse</TableHead>
                    <TableHead>To Warehouse</TableHead>
                    <TableHead className="text-right">Quantity</TableHead>
                    <TableHead>Date</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredTransfers.map((transfer) => (
                    <TableRow key={transfer.id}>
                      <TableCell>
                        <div className="flex flex-col">
                          <span className="font-medium">{transfer.product_name || 'N/A'}</span>
                          {transfer.product_sku && (
                            <span className="text-xs text-muted-foreground font-mono">
                              {transfer.product_sku}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center">
                          <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                          {transfer.from_warehouse_name || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center">
                          <ArrowRightLeft className="h-4 w-4 mr-2 text-blue-500" />
                          <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                          {transfer.to_warehouse_name || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell className="text-right font-medium">
                        {(typeof transfer.quantity === 'number' ? transfer.quantity : parseFloat(String(transfer.quantity || 0))).toLocaleString()}
                      </TableCell>
                      <TableCell>
                        {new Date(transfer.created_at).toLocaleDateString()}
                      </TableCell>
                      <TableCell>
                        <Badge variant="default">
                          <CheckCircle2 className="h-3 w-3 mr-1" />
                          Completed
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewTransfer(transfer)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View Details
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create Transfer Dialog */}
      <Dialog open={showTransferDialog} onOpenChange={setShowTransferDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Create Inventory Transfer</DialogTitle>
            <DialogDescription>
              Transfer inventory from one warehouse to another
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="product">Product *</Label>
              <Select
                value={transferForm.product_id}
                onValueChange={(value) => setTransferForm({ ...transferForm, product_id: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select product" />
                </SelectTrigger>
                <SelectContent>
                  {products.map((product) => (
                    <SelectItem key={product.id} value={product.id}>
                      {product.name} ({product.sku})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="from_warehouse">From Warehouse *</Label>
                <Select
                  value={transferForm.from_warehouse_id}
                  onValueChange={(value) => setTransferForm({ ...transferForm, from_warehouse_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select source warehouse" />
                  </SelectTrigger>
                  <SelectContent>
                    {warehouses.map((warehouse) => (
                      <SelectItem key={warehouse.id} value={warehouse.id}>
                        {warehouse.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="to_warehouse">To Warehouse *</Label>
                <Select
                  value={transferForm.to_warehouse_id}
                  onValueChange={(value) => setTransferForm({ ...transferForm, to_warehouse_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select destination warehouse" />
                  </SelectTrigger>
                  <SelectContent>
                    {warehouses
                      .filter(w => w.id !== transferForm.from_warehouse_id)
                      .map((warehouse) => (
                        <SelectItem key={warehouse.id} value={warehouse.id}>
                          {warehouse.name}
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="quantity">Quantity *</Label>
              <Input
                id="quantity"
                type="number"
                min="1"
                step="0.01"
                value={transferForm.quantity}
                onChange={(e) => setTransferForm({ ...transferForm, quantity: e.target.value })}
                placeholder="Enter quantity"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={transferForm.notes}
                onChange={(e) => setTransferForm({ ...transferForm, notes: e.target.value })}
                placeholder="Additional notes about this transfer"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowTransferDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateTransfer} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Create Transfer
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Transfer Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Transfer Details</DialogTitle>
            <DialogDescription>
              View complete transfer information
            </DialogDescription>
          </DialogHeader>
          {selectedTransfer && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Product</Label>
                <div>
                  <p className="font-medium">{selectedTransfer.product_name || 'N/A'}</p>
                  {selectedTransfer.product_sku && (
                    <p className="text-sm text-muted-foreground font-mono">
                      SKU: {selectedTransfer.product_sku}
                    </p>
                  )}
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">From Warehouse</Label>
                  <div className="flex items-center">
                    <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{selectedTransfer.from_warehouse_name || 'N/A'}</p>
                  </div>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">To Warehouse</Label>
                  <div className="flex items-center">
                    <ArrowRightLeft className="h-4 w-4 mr-2 text-blue-500" />
                    <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{selectedTransfer.to_warehouse_name || 'N/A'}</p>
                  </div>
                </div>
              </div>
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Quantity</Label>
                  <p className="font-medium text-lg">
                    {(typeof selectedTransfer.quantity === 'number' ? selectedTransfer.quantity : parseFloat(String(selectedTransfer.quantity || 0))).toLocaleString()}
                  </p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Date</Label>
                  <div className="flex items-center">
                    <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{new Date(selectedTransfer.created_at).toLocaleString()}</p>
                  </div>
                </div>
              </div>
              {selectedTransfer.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedTransfer.notes}</p>
                </div>
              )}
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Status</Label>
                <Badge variant="default">
                  <CheckCircle2 className="h-3 w-3 mr-1" />
                  Completed
                </Badge>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Inventory Warehouses Page
 * Multi-warehouse management interface
 */

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Warehouse,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  MapPin,
  Phone,
  Mail,
  Building2,
  MoreVertical,
  Eye,
} from 'lucide-react';
import {
  getWarehouses,
  createWarehouse,
  updateWarehouse,
  deleteWarehouse,
  type Warehouse as WarehouseType,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import { Switch } from '@/components/ui/switch';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

export default function InventoryWarehouses() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Warehouses
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);
  const [filteredWarehouses, setFilteredWarehouses] = useState<WarehouseType[]>([]);
  const [selectedWarehouse, setSelectedWarehouse] = useState<WarehouseType | null>(null);
  const [showWarehouseDialog, setShowWarehouseDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');

  // Warehouse form
  const [warehouseForm, setWarehouseForm] = useState({
    code: '',
    name: '',
    address: '',
    city: '',
    state: '',
    postal_code: '',
    country: 'India',
    contact_person: '',
    phone: '',
    email: '',
    is_primary: false,
  });

  // Fetch data
  useEffect(() => {
    fetchWarehouses();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = warehouses;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(w =>
        w.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        w.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (w.city && w.city.toLowerCase().includes(searchTerm.toLowerCase()))
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(w =>
        statusFilter === 'active' ? w.is_active : !w.is_active
      );
    }

    setFilteredWarehouses(filtered);
  }, [warehouses, searchTerm, statusFilter]);

  const fetchWarehouses = async () => {
    try {
      setInitialLoad(true);
      setLoading(true);
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch warehouses',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
      setInitialLoad(false);
    }
  };

  const handleCreateWarehouse = async () => {
    try {
      setLoading(true);
      if (isEditing && selectedWarehouse) {
        await updateWarehouse(selectedWarehouse.id, warehouseForm);
        toast({
          title: 'Success',
          description: 'Warehouse updated successfully',
        });
      } else {
        await createWarehouse(warehouseForm);
        toast({
          title: 'Success',
          description: 'Warehouse created successfully',
        });
      }
      setShowWarehouseDialog(false);
      resetForm();
      fetchWarehouses();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save warehouse',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditWarehouse = (warehouse: WarehouseType) => {
    setSelectedWarehouse(warehouse);
    setIsEditing(true);
    setWarehouseForm({
      code: warehouse.code,
      name: warehouse.name,
      address: warehouse.address || '',
      city: warehouse.city || '',
      state: warehouse.state || '',
      postal_code: warehouse.postal_code || '',
      country: warehouse.country || 'India',
      contact_person: warehouse.contact_person || '',
      phone: warehouse.phone || '',
      email: warehouse.email || '',
      is_primary: warehouse.is_primary,
    });
    setShowWarehouseDialog(true);
  };

  const handleViewWarehouse = (warehouse: WarehouseType) => {
    setSelectedWarehouse(warehouse);
    setShowViewDialog(true);
  };

  const handleDeleteWarehouse = async (warehouse: WarehouseType) => {
    if (!confirm(`Are you sure you want to delete "${warehouse.name}"?`)) {
      return;
    }

    try {
      setLoading(true);
      await deleteWarehouse(warehouse.id);
      toast({
        title: 'Success',
        description: 'Warehouse deleted successfully',
      });
      fetchWarehouses();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete warehouse',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setWarehouseForm({
      code: '',
      name: '',
      address: '',
      city: '',
      state: '',
      postal_code: '',
      country: 'India',
      contact_person: '',
      phone: '',
      email: '',
      is_primary: false,
    });
    setSelectedWarehouse(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowWarehouseDialog(true);
  };

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Warehouse Management</h1>
          <p className="text-muted-foreground mt-1">
            Manage your warehouse locations and inventory storage
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Add Warehouse
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Warehouses</CardTitle>
            <Warehouse className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{warehouses.length}</div>
            <p className="text-xs text-muted-foreground">
              {warehouses.filter(w => w.is_active).length} active
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Primary Warehouse</CardTitle>
            <Building2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {warehouses.filter(w => w.is_primary).length}
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Warehouses</CardTitle>
            <Warehouse className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {warehouses.filter(w => w.is_active).length}
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Locations</CardTitle>
            <MapPin className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {new Set(warehouses.map(w => w.city).filter(Boolean)).size}
            </div>
            <p className="text-xs text-muted-foreground">Unique cities</p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-2">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search warehouses..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background"
              >
                <option value="all">All Status</option>
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Warehouses Table */}
      <Card>
        <CardHeader>
          <CardTitle>Warehouses ({filteredWarehouses.length})</CardTitle>
          <CardDescription>
            Manage your warehouse locations
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredWarehouses.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredWarehouses.length === 0 ? (
            <Alert>
              <AlertDescription>
                No warehouses found. {searchTerm || statusFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first warehouse to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Code</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Location</TableHead>
                    <TableHead>Contact</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredWarehouses.map((warehouse) => (
                    <TableRow key={warehouse.id}>
                      <TableCell className="font-mono text-sm">{warehouse.code}</TableCell>
                      <TableCell className="font-medium">{warehouse.name}</TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          {warehouse.city && <span>{warehouse.city}</span>}
                          {warehouse.state && (
                            <span className="text-xs text-muted-foreground">
                              {warehouse.state}, {warehouse.country}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          {warehouse.contact_person && (
                            <span className="text-sm">{warehouse.contact_person}</span>
                          )}
                          {warehouse.phone && (
                            <span className="text-xs text-muted-foreground flex items-center">
                              <Phone className="h-3 w-3 mr-1" />
                              {warehouse.phone}
                            </span>
                          )}
                          {warehouse.email && (
                            <span className="text-xs text-muted-foreground flex items-center">
                              <Mail className="h-3 w-3 mr-1" />
                              {warehouse.email}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        {warehouse.is_primary ? (
                          <Badge variant="default">Primary</Badge>
                        ) : (
                          <span className="text-muted-foreground">Standard</span>
                        )}
                      </TableCell>
                      <TableCell>
                        <Badge variant={warehouse.is_active ? 'default' : 'secondary'}>
                          {warehouse.is_active ? 'Active' : 'Inactive'}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewWarehouse(warehouse)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEditWarehouse(warehouse)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => navigate(`/inventory/stock-levels?warehouse=${warehouse.id}`)}
                            >
                              View Stock
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              onClick={() => handleDeleteWarehouse(warehouse)}
                              className="text-destructive"
                            >
                              <Trash2 className="mr-2 h-4 w-4" />
                              Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Warehouse Dialog */}
      <Dialog open={showWarehouseDialog} onOpenChange={setShowWarehouseDialog}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Warehouse' : 'Create New Warehouse'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update warehouse information' : 'Add a new warehouse location'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="code">Warehouse Code *</Label>
                <Input
                  id="code"
                  value={warehouseForm.code}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, code: e.target.value })}
                  placeholder="WH-001"
                  required
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="name">Warehouse Name *</Label>
                <Input
                  id="name"
                  value={warehouseForm.name}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, name: e.target.value })}
                  placeholder="Main Warehouse"
                  required
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="address">Address</Label>
              <Textarea
                id="address"
                value={warehouseForm.address}
                onChange={(e) => setWarehouseForm({ ...warehouseForm, address: e.target.value })}
                placeholder="Street address"
                rows={2}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="city">City</Label>
                <Input
                  id="city"
                  value={warehouseForm.city}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, city: e.target.value })}
                  placeholder="City"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="state">State</Label>
                <Input
                  id="state"
                  value={warehouseForm.state}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, state: e.target.value })}
                  placeholder="State"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="postal_code">Postal Code</Label>
                <Input
                  id="postal_code"
                  value={warehouseForm.postal_code}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, postal_code: e.target.value })}
                  placeholder="123456"
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="country">Country</Label>
              <Input
                id="country"
                value={warehouseForm.country}
                onChange={(e) => setWarehouseForm({ ...warehouseForm, country: e.target.value })}
                placeholder="Country"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="contact_person">Contact Person</Label>
              <Input
                id="contact_person"
                value={warehouseForm.contact_person}
                onChange={(e) => setWarehouseForm({ ...warehouseForm, contact_person: e.target.value })}
                placeholder="Contact person name"
              />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="phone">Phone</Label>
                <Input
                  id="phone"
                  value={warehouseForm.phone}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, phone: e.target.value })}
                  placeholder="+91 1234567890"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={warehouseForm.email}
                  onChange={(e) => setWarehouseForm({ ...warehouseForm, email: e.target.value })}
                  placeholder="warehouse@example.com"
                />
              </div>
            </div>
            <div className="flex items-center space-x-2">
              <Switch
                id="primary"
                checked={warehouseForm.is_primary}
                onCheckedChange={(checked) =>
                  setWarehouseForm({ ...warehouseForm, is_primary: checked })
                }
              />
              <Label htmlFor="primary">Set as Primary Warehouse</Label>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowWarehouseDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateWarehouse} disabled={loading}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Warehouse
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Warehouse Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Warehouse Details</DialogTitle>
            <DialogDescription>
              View complete warehouse information
            </DialogDescription>
          </DialogHeader>
          {selectedWarehouse && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Code</Label>
                <p className="font-mono">{selectedWarehouse.code}</p>
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Name</Label>
                <p>{selectedWarehouse.name}</p>
              </div>
              {selectedWarehouse.address && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Address</Label>
                  <p className="text-sm text-muted-foreground">{selectedWarehouse.address}</p>
                </div>
              )}
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">City</Label>
                  <p>{selectedWarehouse.city || '-'}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">State</Label>
                  <p>{selectedWarehouse.state || '-'}</p>
                </div>
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Country</Label>
                <p>{selectedWarehouse.country || '-'}</p>
              </div>
              {selectedWarehouse.contact_person && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Contact Person</Label>
                  <p>{selectedWarehouse.contact_person}</p>
                </div>
              )}
              {(selectedWarehouse.phone || selectedWarehouse.email) && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Contact Information</Label>
                  <div className="space-y-1">
                    {selectedWarehouse.phone && (
                      <p className="text-sm flex items-center">
                        <Phone className="h-4 w-4 mr-2" />
                        {selectedWarehouse.phone}
                      </p>
                    )}
                    {selectedWarehouse.email && (
                      <p className="text-sm flex items-center">
                        <Mail className="h-4 w-4 mr-2" />
                        {selectedWarehouse.email}
                      </p>
                    )}
                  </div>
                </div>
              )}
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Status</Label>
                <div className="flex gap-2">
                  <Badge variant={selectedWarehouse.is_active ? 'default' : 'secondary'}>
                    {selectedWarehouse.is_active ? 'Active' : 'Inactive'}
                  </Badge>
                  {selectedWarehouse.is_primary && (
                    <Badge variant="default">Primary</Badge>
                  )}
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
            {selectedWarehouse && (
              <Button onClick={() => {
                setShowViewDialog(false);
                handleEditWarehouse(selectedWarehouse);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Plus, Search, Filter, Briefcase, Clock, DollarSign, Target, Edit, Trash2, X, Download } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { selectRecords, updateRecord } from '@/services/api/core';
import JobFormDialog from '@/components/shared/JobFormDialog';
import DeleteConfirmDialog from '@/components/shared/DeleteConfirmDialog';
import JobCostItemsDialog from '@/components/JobCostItemsDialog';
import { useAuth } from '@/hooks/useAuth';
import { useNavigate } from 'react-router-dom';

const JobCosting = () => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [jobs, setJobs] = useState<unknown[]>([]);
  const [clients, setClients] = useState<unknown[]>([]);
  const [loading, setLoading] = useState(true);
  const [jobFormOpen, setJobFormOpen] = useState(false);
  const [selectedJob, setSelectedJob] = useState<unknown>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<unknown>(null);
  const [costItemsDialogOpen, setCostItemsDialogOpen] = useState(false);
  const [selectedJobForCosts, setSelectedJobForCosts] = useState<unknown>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [clientFilter, setClientFilter] = useState<string>('all');
  const [dateRangeFilter, setDateRangeFilter] = useState({ start: '', end: '' });
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize] = useState(10);

  useEffect(() => {
    fetchJobs();
    fetchClients();
  }, []);

  const fetchJobs = async () => {
    try {
      setLoading(true);
      if (!profile?.agency_id) {
        setJobs([]);
        setLoading(false);
        return;
      }

      const jobsData = await selectRecords('jobs', {
        where: { agency_id: profile.agency_id },
        orderBy: 'created_at DESC',
      });

      // Fetch client names for display
      const clientIds = [...new Set(jobsData.map((j: unknown) => j.client_id).filter(Boolean))];
      const clientMap = new Map();
      if (clientIds.length > 0) {
        const clientsData = await selectRecords('clients', {
          filters: [{ column: 'id', operator: 'in', value: clientIds }],
        });
        clientsData.forEach((c: unknown) => {
          clientMap.set(c.id, c.company_name || c.name || 'Unknown Client');
        });
      }

      // Add client names to jobs
      const jobsWithClients = jobsData.map((job: unknown) => ({
        ...job,
        client_name: clientMap.get(job.client_id) || 'No Client',
      }));

      setJobs(jobsWithClients);
    } catch (error) {
      console.error('Error fetching jobs:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch jobs',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchClients = async () => {
    try {
      if (!profile?.agency_id) return;
      const clientsData = await selectRecords('clients', {
        where: { agency_id: profile.agency_id },
        orderBy: 'company_name ASC',
      });
      setClients(clientsData || []);
    } catch (error) {
      console.error('Error fetching clients:', error);
    }
  };

  const handleNewJob = () => {
    setSelectedJob(null);
    setJobFormOpen(true);
  };

  const handleEditJob = (job: unknown) => {
    setSelectedJob(job);
    setJobFormOpen(true);
  };

  const handleDeleteJob = (job: unknown) => {
    setJobToDelete(job);
    setDeleteDialogOpen(true);
  };

  const handleJobSaved = () => {
    fetchJobs();
  };

  const handleJobDeleted = () => {
    fetchJobs();
  };

  const handleAddCosts = (job: unknown) => {
    setSelectedJobForCosts(job);
    setCostItemsDialogOpen(true);
  };

  const handleCostItemsUpdated = async () => {
    // Recalculate actual_cost for the job
    if (selectedJobForCosts?.id) {
      try {
        const costItems = await selectRecords('job_cost_items', {
          where: { job_id: selectedJobForCosts.id },
        });
        const totalCost = costItems.reduce((sum: number, item: unknown) => {
          return sum + (parseFloat(item.total_cost?.toString() || '0') || 0);
        }, 0);

        await updateRecord('jobs', { actual_cost: totalCost }, { id: selectedJobForCosts.id }, user?.id);

        // Update the selected job in state
        setSelectedJobForCosts((prev: unknown) => ({
          ...prev,
          actual_cost: totalCost,
        }));

        fetchJobs(); // Refresh jobs list
      } catch (error) {
        console.error('Error updating actual cost:', error);
        toast({
          title: 'Warning',
          description: 'Cost items saved but failed to update job total. Please refresh.',
          variant: 'destructive',
        });
      }
    }
  };

  // Mock data for demonstration - replace with real data from jobs state
  const jobStats = {
    totalJobs: jobs.length,
    activeJobs: jobs.filter(job => job.status === 'in_progress').length,
    totalBudget: jobs.reduce((sum, job) => sum + (job.budget || 0), 0),
    actualCosts: jobs.reduce((sum, job) => sum + (job.actual_cost || 0), 0),
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'planning': return 'bg-blue-100 text-blue-800';
      case 'in_progress': return 'bg-orange-100 text-orange-800';
      case 'completed': return 'bg-green-100 text-green-800';
      case 'cancelled': return 'bg-red-100 text-red-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredJobs = jobs.filter(job => {
    const matchesSearch = 
      job.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.job_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      job.client_name?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesStatus = statusFilter === 'all' || job.status === statusFilter;
    const matchesClient = clientFilter === 'all' || job.client_id === clientFilter;
    
    const matchesDateRange = 
      !dateRangeFilter.start && !dateRangeFilter.end ||
      (!dateRangeFilter.start || (job.start_date && job.start_date >= dateRangeFilter.start)) &&
      (!dateRangeFilter.end || (job.end_date && job.end_date <= dateRangeFilter.end));
    
    return matchesSearch && matchesStatus && matchesClient && matchesDateRange;
  });

  // Pagination
  const totalPages = Math.ceil(filteredJobs.length / pageSize);
  const paginatedJobs = filteredJobs.slice(
    (currentPage - 1) * pageSize,
    currentPage * pageSize
  );

  // Calculate profit/loss
  const calculateProfit = (job: unknown) => {
    const budget = parseFloat(job.budget?.toString() || '0') || 0;
    const actual = parseFloat(job.actual_cost?.toString() || '0') || 0;
    return budget - actual;
  };

  const exportToCSV = () => {
    const headers = ['Job Number', 'Title', 'Client', 'Status', 'Budget', 'Actual Cost', 'Profit/Loss', 'Start Date', 'End Date'];
    const rows = filteredJobs.map(job => [
      job.job_number || '',
      job.title || '',
      job.client_name || '',
      job.status || '',
      job.budget || 0,
      job.actual_cost || 0,
      calculateProfit(job),
      job.start_date || '',
      job.end_date || '',
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(row => row.map(cell => `"${cell}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `jobs_export_${new Date().toISOString().split('T')[0]}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);

    toast({
      title: 'Success',
      description: 'Jobs exported to CSV',
    });
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Job Costing</h1>
          <p className="text-muted-foreground">Track and manage job costs and profitability</p>
        </div>
        <Button onClick={handleNewJob}>
          <Plus className="h-4 w-4 mr-2" />
          New Job
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
              <Briefcase className="h-8 w-8 text-blue-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Jobs</p>
                <p className="text-2xl font-bold">{jobStats.totalJobs}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
              <Clock className="h-8 w-8 text-orange-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Active Jobs</p>
                <p className="text-2xl font-bold">{jobStats.activeJobs}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
              <Target className="h-8 w-8 text-green-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Budget</p>
                <p className="text-2xl font-bold">₹{jobStats.totalBudget.toLocaleString()}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
              <DollarSign className="h-8 w-8 text-purple-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Actual Costs</p>
                <p className="text-2xl font-bold">₹{jobStats.actualCosts.toLocaleString()}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Search and Filters */}
      <div className="space-y-4">
        <div className="flex gap-4">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search jobs by title, number, or client..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-10"
            />
          </div>
          <Button variant="outline" onClick={() => setShowFilters(!showFilters)}>
            <Filter className="h-4 w-4 mr-2" />
            Filter
          </Button>
          <Button variant="outline" onClick={exportToCSV}>
            <Download className="h-4 w-4 mr-2" />
            Export
          </Button>
        </div>

        {showFilters && (
          <Card>
            <CardContent className="p-4">
              <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div className="space-y-2">
                  <label className="text-sm font-medium">Status</label>
                  <Select value={statusFilter} onValueChange={setStatusFilter}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Statuses</SelectItem>
                      <SelectItem value="planning">Planning</SelectItem>
                      <SelectItem value="in_progress">In Progress</SelectItem>
                      <SelectItem value="completed">Completed</SelectItem>
                      <SelectItem value="cancelled">Cancelled</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Client</label>
                  <Select value={clientFilter} onValueChange={setClientFilter}>
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="all">All Clients</SelectItem>
                      {clients.map((client) => (
                        <SelectItem key={client.id} value={client.id}>
                          {client.company_name || client.name || client.id}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">Start Date From</label>
                  <Input
                    type="date"
                    value={dateRangeFilter.start}
                    onChange={(e) => setDateRangeFilter(prev => ({ ...prev, start: e.target.value }))}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-sm font-medium">End Date To</label>
                  <Input
                    type="date"
                    value={dateRangeFilter.end}
                    onChange={(e) => setDateRangeFilter(prev => ({ ...prev, end: e.target.value }))}
                  />
                </div>
              </div>
              <div className="mt-4 flex justify-end">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setStatusFilter('all');
                    setClientFilter('all');
                    setDateRangeFilter({ start: '', end: '' });
                  }}
                >
                  <X className="h-4 w-4 mr-2" />
                  Clear Filters
                </Button>
              </div>
            </CardContent>
          </Card>
        )}
      </div>

      {/* Jobs Content */}
      <Tabs defaultValue="list" className="space-y-4">
        <TabsList>
          <TabsTrigger value="list">Job List</TabsTrigger>
          <TabsTrigger value="analytics">Cost Analytics</TabsTrigger>
        </TabsList>
        
        <TabsContent value="list" className="space-y-4">
          {loading ? (
            <div className="text-center py-8">Loading jobs...</div>
          ) : (
            <div className="grid gap-4">
              {filteredJobs.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  No jobs found. Create your first job to get started.
                </div>
              ) : (
                <>
                  {paginatedJobs.map((job) => (
                  <Card key={job.id} className="hover:shadow-md transition-shadow">
                    <CardHeader className="pb-3">
                      <div className="flex justify-between items-start">
                        <div>
                          <CardTitle className="text-lg">{job.title}</CardTitle>
                          <p className="text-sm text-muted-foreground">
                            {job.job_number} • {job.client_name || 'No client assigned'}
                          </p>
                        </div>
                        <Badge className={getStatusColor(job.status)}>
                          {job.status?.replace('_', ' ')}
                        </Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                        <div>
                          <p className="text-sm text-muted-foreground">Budget</p>
                          <p className="font-semibold">₹{(job.budget || 0).toLocaleString()}</p>
                        </div>
                        <div>
                          <p className="text-sm text-muted-foreground">Actual Cost</p>
                          <p className="font-semibold">₹{(job.actual_cost || 0).toLocaleString()}</p>
                        </div>
                        <div>
                          <p className="text-sm text-muted-foreground">Hours (Est/Act)</p>
                          <p className="font-semibold">{job.estimated_hours || 0}/{job.actual_hours || 0}</p>
                        </div>
                        <div>
                          <p className="text-sm text-muted-foreground">Profit/Loss</p>
                          <p className={`font-semibold ${calculateProfit(job) >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                            ₹{calculateProfit(job).toLocaleString()}
                          </p>
                        </div>
                      </div>
                      <div className="mt-4 flex justify-between items-center">
                        <div className="text-sm text-muted-foreground">
                          {job.start_date && job.end_date && (
                            <>
                              {new Date(job.start_date).toLocaleDateString()} - {new Date(job.end_date).toLocaleDateString()}
                            </>
                          )}
                        </div>
                        <div className="flex gap-2">
                          <Button variant="outline" size="sm" onClick={() => handleEditJob(job)}>
                            <Edit className="h-4 w-4 mr-1" />
                            Edit
                          </Button>
                          <Button variant="outline" size="sm" onClick={() => handleAddCosts(job)}>
                            <DollarSign className="h-4 w-4 mr-1" />
                            Add Costs
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => navigate(`/invoices?job_id=${job.id}&client_id=${job.client_id}`)}
                            title="Create invoice for this job"
                          >
                            Invoice
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => navigate(`/quotations?job_id=${job.id}&client_id=${job.client_id}`)}
                            title="Create quotation for this job"
                          >
                            Quote
                          </Button>
                          <Button 
                            variant="outline" 
                            size="sm"
                            onClick={() => navigate(`/project-management?job_id=${job.id}`)}
                            title="Link to project"
                          >
                            Project
                          </Button>
                          <Button variant="outline" size="sm" onClick={() => handleDeleteJob(job)}>
                            <Trash2 className="h-4 w-4 mr-1" />
                            Delete
                          </Button>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                  ))}
                  {totalPages > 1 && (
                    <div className="flex justify-center items-center gap-2 mt-4">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                        disabled={currentPage === 1}
                      >
                        Previous
                      </Button>
                      <span className="text-sm text-muted-foreground">
                        Page {currentPage} of {totalPages}
                      </span>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                        disabled={currentPage === totalPages}
                      >
                        Next
                      </Button>
                    </div>
                  )}
                </>
              )}
            </div>
          )}
        </TabsContent>
        
        <TabsContent value="analytics">
          <div className="grid gap-6">
            {/* Budget vs Actual */}
            <Card>
              <CardHeader>
                <CardTitle>Budget vs Actual Costs</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {jobs.length === 0 ? (
                    <p className="text-center text-muted-foreground py-8">No jobs to analyze</p>
                  ) : (
                    jobs.map((job) => {
                      const budget = parseFloat(job.budget?.toString() || '0') || 0;
                      const actual = parseFloat(job.actual_cost?.toString() || '0') || 0;
                      const percentage = budget > 0 ? (actual / budget) * 100 : 0;
                      const isOverBudget = actual > budget;
                      
                      return (
                        <div key={job.id} className="space-y-2">
                          <div className="flex justify-between text-sm">
                            <span className="font-medium">{job.title}</span>
                            <span className={isOverBudget ? 'text-red-600' : 'text-green-600'}>
                              {percentage.toFixed(1)}%
                            </span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-4 relative">
                            <div
                              className={`h-4 rounded-full ${isOverBudget ? 'bg-red-500' : 'bg-green-500'}`}
                              style={{ width: `${Math.min(percentage, 100)}%` }}
                            />
                            {percentage > 100 && (
                              <div
                                className="bg-red-600 h-4 rounded-full absolute top-0"
                                style={{ width: `${((percentage - 100) / percentage) * 100}%`, left: '100%' }}
                              />
                            )}
                          </div>
                          <div className="flex justify-between text-xs text-muted-foreground">
                            <span>Budget: ₹{budget.toLocaleString()}</span>
                            <span>Actual: ₹{actual.toLocaleString()}</span>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>
              </CardContent>
            </Card>

            {/* Cost Breakdown by Category */}
            <Card>
              <CardHeader>
                <CardTitle>Cost Breakdown by Category</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-4">
                  {(() => {
                    const categoryTotals: { [key: string]: number } = {};
                    jobs.forEach((job: unknown) => {
                      // This would need to fetch cost items, but for now show placeholder
                    });
                    
                    return (
                      <p className="text-center text-muted-foreground py-8">
                        Cost breakdown will be calculated from job cost items
                      </p>
                    );
                  })()}
                </div>
              </CardContent>
            </Card>

            {/* Profitability Summary */}
            <Card>
              <CardHeader>
                <CardTitle>Profitability Summary</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <div>
                    <p className="text-sm text-muted-foreground">Total Budget</p>
                    <p className="text-2xl font-bold">₹{jobStats.totalBudget.toLocaleString()}</p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">Total Actual</p>
                    <p className="text-2xl font-bold">₹{jobStats.actualCosts.toLocaleString()}</p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">Total Profit</p>
                    <p className={`text-2xl font-bold ${(jobStats.totalBudget - jobStats.actualCosts) >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                      ₹{(jobStats.totalBudget - jobStats.actualCosts).toLocaleString()}
                    </p>
                  </div>
                  <div>
                    <p className="text-sm text-muted-foreground">Profit Margin</p>
                    <p className={`text-2xl font-bold ${jobStats.totalBudget > 0 && ((jobStats.totalBudget - jobStats.actualCosts) / jobStats.totalBudget * 100) >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                      {jobStats.totalBudget > 0 
                        ? `${((jobStats.totalBudget - jobStats.actualCosts) / jobStats.totalBudget * 100).toFixed(1)}%`
                        : '0%'}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        </TabsContent>
      </Tabs>

      <JobFormDialog
        isOpen={jobFormOpen}
        onClose={() => setJobFormOpen(false)}
        job={selectedJob}
        onJobSaved={handleJobSaved}
      />

      <DeleteConfirmDialog
        isOpen={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onDeleted={handleJobDeleted}
        itemType="Job"
        itemName={jobToDelete?.title || ''}
        itemId={jobToDelete?.id || ''}
        tableName="jobs"
      />

      <JobCostItemsDialog
        isOpen={costItemsDialogOpen}
        onClose={() => {
          setCostItemsDialogOpen(false);
          setSelectedJobForCosts(null);
        }}
        jobId={selectedJobForCosts?.id || ''}
        jobTitle={selectedJobForCosts?.title}
        onItemsUpdated={handleCostItemsUpdated}
      />
    </div>
  );
};

export default JobCosting;

import React, { useState, useEffect } from 'react';
import { 
  Bell, 
  Check, 
  X, 
  ExternalLink, 
  Clock, 
  AlertTriangle, 
  Info, 
  CheckCircle, 
  Trash2,
  Search,
  Filter,
  Send,
  Users,
  Mail,
  Eye,
  EyeOff,
  MoreVertical,
  Archive
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Checkbox } from '@/components/ui/checkbox';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { db } from '@/lib/database';
import { useToast } from '@/hooks/use-toast';
import { LoadingSpinner } from '@/components/LoadingSpinner';
import { useAsyncOperation } from '@/hooks/useAsyncOperation';
import { useAuth } from '@/hooks/useAuth';
import { AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent, AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle } from '@/components/ui/alert-dialog';

interface Notification {
  id: string;
  user_id: string;
  type: 'email' | 'in_app' | 'push';
  category: 'approval' | 'reminder' | 'update' | 'alert' | 'system';
  title: string;
  message: string;
  metadata: unknown;
  read_at: string | null;
  sent_at: string | null;
  priority: 'low' | 'normal' | 'high' | 'urgent';
  expires_at: string | null;
  action_url: string | null;
  created_at: string;
  updated_at: string;
}

interface User {
  id: string;
  email: string;
  full_name?: string;
}

const Notifications = () => {
  const { user, userRole } = useAuth();
  const { toast } = useToast();
  const [notifications, setNotifications] = useState<Notification[]>([]);
  const [filteredNotifications, setFilteredNotifications] = useState<Notification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [activeTab, setActiveTab] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [selectedNotifications, setSelectedNotifications] = useState<Set<string>>(new Set());
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [notificationToDelete, setNotificationToDelete] = useState<string | null>(null);
  const [sendDialogOpen, setSendDialogOpen] = useState(false);
  const [users, setUsers] = useState<User[]>([]);
  
  // Send notification form state
  const [sendForm, setSendForm] = useState({
    userIds: [] as string[],
    type: 'in_app' as 'email' | 'in_app' | 'push',
    category: 'system' as 'approval' | 'reminder' | 'update' | 'alert' | 'system',
    title: '',
    message: '',
    priority: 'normal' as 'low' | 'normal' | 'high' | 'urgent',
    actionUrl: '',
    expiresAt: '',
  });

  const isAdmin = userRole === 'agency_admin' || userRole === 'manager' || userRole === 'super_admin';

  const { execute: fetchNotifications, loading: loadingNotifications } = useAsyncOperation({
    onError: (error) => {
      if (!error.message?.includes('does not exist') && !error.message?.includes('42P01')) {
        toast({ variant: 'destructive', title: 'Failed to load notifications', description: error.message });
      }
    }
  });

  const { execute: markAsRead, loading: markingRead } = useAsyncOperation({
    onSuccess: () => {
      setUnreadCount(prev => Math.max(0, prev - 1));
    }
  });

  const { execute: deleteNotification, loading: deleting } = useAsyncOperation({
    onSuccess: () => {
      toast({ title: 'Notification deleted successfully' });
      loadNotifications();
    },
    onError: (error) => {
      toast({ variant: 'destructive', title: 'Failed to delete notification', description: error.message });
    }
  });

  const { execute: sendNotification, loading: sending } = useAsyncOperation({
    onSuccess: () => {
      toast({ title: 'Notification sent successfully' });
      setSendDialogOpen(false);
      setSendForm({
        userIds: [],
        type: 'in_app',
        category: 'system',
        title: '',
        message: '',
        priority: 'normal',
        actionUrl: '',
        expiresAt: '',
      });
      loadNotifications();
    },
    onError: (error) => {
      toast({ variant: 'destructive', title: 'Failed to send notification', description: error.message });
    }
  });

  const loadNotifications = async () => {
    if (!user) return;
    
    return fetchNotifications(async () => {
      const { data, error } = await db
        .from('notifications')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false });

      if (error) {
        if (error.message?.includes('does not exist') || error.message?.includes('42P01')) {
          setNotifications([]);
          setFilteredNotifications([]);
          setUnreadCount(0);
          return [];
        }
        throw error;
      }
      
      const notificationsData = (data || []) as Notification[];
      setNotifications(notificationsData);
      
      const unreadNotifications = notificationsData.filter(n => !n.read_at);
      setUnreadCount(unreadNotifications.length);
      
      return data;
    });
  };

  const loadUsers = async () => {
    if (!isAdmin) return;
    
    try {
      // Use unified_employees view which has all user data including full_name
      const { data, error } = await db
        .from('unified_employees')
        .select('user_id, email, display_name, full_name')
        .order('email', { ascending: true });

      if (error) throw error;
      
      // Transform the data to match User interface
      const transformedUsers = (data || []).map((user: unknown) => ({
        id: user.user_id,
        email: user.email,
        full_name: user.full_name || user.display_name || null
      }));
      
      setUsers(transformedUsers as User[]);
    } catch (error: unknown) {
      console.error('Failed to load users:', error);
      // Fallback: get users and profiles separately
      try {
        const { data: usersData } = await db
          .from('users')
          .select('id, email')
          .order('email', { ascending: true });
        
        if (usersData && usersData.length > 0) {
          const userIds = usersData.map((u: unknown) => u.id);
          const { data: profilesData } = await db
            .from('profiles')
            .select('user_id, full_name')
            .in('user_id', userIds);
          
          const profileMap = new Map((profilesData || []).map((p: unknown) => [p.user_id, p.full_name]));
          
          const usersWithNames = usersData.map((u: unknown) => ({
            id: u.id,
            email: u.email,
            full_name: profileMap.get(u.id) || null
          }));
          
          setUsers(usersWithNames as User[]);
        }
      } catch (fallbackErr) {
        console.error('Fallback also failed:', fallbackErr);
      }
    }
  };

  useEffect(() => {
    if (user) {
      loadNotifications();
      if (isAdmin) {
        loadUsers();
      }
    }
  }, [user]);

  // Filter notifications based on search, category, priority, and tab
  useEffect(() => {
    let filtered = [...notifications];

    // Apply tab filter
    if (activeTab === 'unread') {
      filtered = filtered.filter(n => !n.read_at);
    } else if (activeTab !== 'all') {
      filtered = filtered.filter(n => n.category === activeTab);
    }

    // Apply category filter
    if (categoryFilter !== 'all') {
      filtered = filtered.filter(n => n.category === categoryFilter);
    }

    // Apply priority filter
    if (priorityFilter !== 'all') {
      filtered = filtered.filter(n => n.priority === priorityFilter);
    }

    // Apply search filter
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(n => 
        n.title.toLowerCase().includes(query) || 
        n.message.toLowerCase().includes(query)
      );
    }

    setFilteredNotifications(filtered);
  }, [notifications, activeTab, categoryFilter, priorityFilter, searchQuery]);

  const handleMarkAsRead = async (notificationId: string) => {
    return markAsRead(async () => {
      try {
        const { error } = await db.rpc('mark_notification_read', {
          p_notification_id: notificationId
        });

        if (error && !error.message?.includes('does not exist') && !error.message?.includes('42P01')) {
          throw error;
        }
      } catch (error: unknown) {
        if (!error.message?.includes('does not exist') && !error.message?.includes('42P01')) {
          throw error;
        }
      }

      setNotifications(prev => 
        prev.map(notif => 
          notif.id === notificationId 
            ? { ...notif, read_at: new Date().toISOString() }
            : notif
        )
      );
    });
  };

  const handleMarkAllAsRead = async () => {
    const unreadNotifications = notifications.filter(n => !n.read_at);
    
    for (const notification of unreadNotifications) {
      await handleMarkAsRead(notification.id);
    }
    
    toast({ title: 'All notifications marked as read' });
  };

  const handleDeleteNotification = async (notificationId: string) => {
    return deleteNotification(async () => {
      const { error } = await db
        .from('notifications')
        .delete()
        .eq('id', notificationId);

      if (error) throw error;

      setNotifications(prev => prev.filter(n => n.id !== notificationId));
      setSelectedNotifications(prev => {
        const next = new Set(prev);
        next.delete(notificationId);
        return next;
      });
    });
  };

  const handleBulkDelete = async () => {
    if (selectedNotifications.size === 0) return;

    const ids = Array.from(selectedNotifications);
    try {
      for (const id of ids) {
        const { error } = await db
          .from('notifications')
          .delete()
          .eq('id', id);

        if (error) throw error;
      }

      setNotifications(prev => prev.filter(n => !selectedNotifications.has(n.id)));
      setSelectedNotifications(new Set());
      toast({ title: `${ids.length} notification(s) deleted successfully` });
    } catch (error: unknown) {
      toast({ variant: 'destructive', title: 'Failed to delete notifications', description: error.message });
    }
  };

  const handleBulkMarkAsRead = async () => {
    if (selectedNotifications.size === 0) return;

    const ids = Array.from(selectedNotifications);
    for (const id of ids) {
      await handleMarkAsRead(id);
    }
    
    setSelectedNotifications(new Set());
    toast({ title: `${ids.length} notification(s) marked as read` });
  };

  const handleSendNotification = async () => {
    if (!sendForm.title.trim() || !sendForm.message.trim()) {
      toast({ variant: 'destructive', title: 'Title and message are required' });
      return;
    }

    if (sendForm.userIds.length === 0) {
      toast({ variant: 'destructive', title: 'Please select at least one user' });
      return;
    }

    return sendNotification(async () => {
      const promises = sendForm.userIds.map(userId => 
        db.rpc('create_notification', {
          p_user_id: userId,
          p_type: sendForm.type,
          p_category: sendForm.category,
          p_title: sendForm.title,
          p_message: sendForm.message,
          p_metadata: {},
          p_priority: sendForm.priority,
          p_action_url: sendForm.actionUrl || null,
          p_expires_at: sendForm.expiresAt || null,
        })
      );

      const results = await Promise.all(promises);
      const errors = results.filter(r => r.error);
      
      if (errors.length > 0) {
        throw new Error(`Failed to send ${errors.length} notification(s)`);
      }
    });
  };

  const handleNotificationClick = (notification: Notification) => {
    if (!notification.read_at) {
      handleMarkAsRead(notification.id);
    }
    
    if (notification.action_url) {
      window.open(notification.action_url, '_blank');
    }
  };

  const toggleSelection = (notificationId: string) => {
    setSelectedNotifications(prev => {
      const next = new Set(prev);
      if (next.has(notificationId)) {
        next.delete(notificationId);
      } else {
        next.add(notificationId);
      }
      return next;
    });
  };

  const toggleSelectAll = () => {
    if (selectedNotifications.size === filteredNotifications.length) {
      setSelectedNotifications(new Set());
    } else {
      setSelectedNotifications(new Set(filteredNotifications.map(n => n.id)));
    }
  };

  const getPriorityIcon = (priority: string) => {
    switch (priority) {
      case 'urgent': return <AlertTriangle className="w-4 h-4 text-red-500" />;
      case 'high': return <AlertTriangle className="w-4 h-4 text-orange-500" />;
      case 'normal': return <Info className="w-4 h-4 text-blue-500" />;
      case 'low': return <Info className="w-4 h-4 text-gray-500" />;
      default: return <Info className="w-4 h-4 text-blue-500" />;
    }
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'approval': return 'bg-yellow-100 text-yellow-800';
      case 'reminder': return 'bg-blue-100 text-blue-800';
      case 'update': return 'bg-green-100 text-green-800';
      case 'alert': return 'bg-red-100 text-red-800';
      case 'system': return 'bg-gray-100 text-gray-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const formatDate = (dateString: string) => {
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins} minute${diffMins !== 1 ? 's' : ''} ago`;
    if (diffHours < 24) return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;
    if (diffDays < 7) return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold tracking-tight">Notifications</h1>
          <p className="text-muted-foreground">
            Manage and view all your notifications
          </p>
        </div>
        <div className="flex items-center gap-2">
          {isAdmin && (
            <Dialog open={sendDialogOpen} onOpenChange={setSendDialogOpen}>
              <DialogTrigger asChild>
                <Button>
                  <Send className="w-4 h-4 mr-2" />
                  Send Notification
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
                <DialogHeader>
                  <DialogTitle>Send Notification</DialogTitle>
                  <DialogDescription>
                    Send a notification to one or more users
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="users">Recipients *</Label>
                    <Select
                      value={sendForm.userIds.length > 0 ? 'selected' : ''}
                      onValueChange={() => {}}
                    >
                      <SelectTrigger>
                        <SelectValue placeholder="Select users" />
                      </SelectTrigger>
                      <SelectContent>
                        <ScrollArea className="h-60">
                          {users.map(u => (
                            <div key={u.id} className="flex items-center space-x-2 px-2 py-1.5">
                              <Checkbox
                                checked={sendForm.userIds.includes(u.id)}
                                onCheckedChange={(checked) => {
                                  setSendForm(prev => ({
                                    ...prev,
                                    userIds: checked
                                      ? [...prev.userIds, u.id]
                                      : prev.userIds.filter(id => id !== u.id)
                                  }));
                                }}
                              />
                              <Label className="font-normal cursor-pointer">
                                {u.full_name || u.email}
                              </Label>
                            </div>
                          ))}
                        </ScrollArea>
                      </SelectContent>
                    </Select>
                    {sendForm.userIds.length > 0 && (
                      <p className="text-sm text-muted-foreground">
                        {sendForm.userIds.length} user(s) selected
                      </p>
                    )}
                  </div>

                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label htmlFor="type">Type</Label>
                      <Select
                        value={sendForm.type}
                        onValueChange={(value: 'email' | 'in_app' | 'push') => 
                          setSendForm(prev => ({ ...prev, type: value }))
                        }
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="in_app">In-App</SelectItem>
                          <SelectItem value="email">Email</SelectItem>
                          <SelectItem value="push">Push</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="space-y-2">
                      <Label htmlFor="category">Category</Label>
                      <Select
                        value={sendForm.category}
                        onValueChange={(value: 'approval' | 'reminder' | 'update' | 'alert' | 'system') => 
                          setSendForm(prev => ({ ...prev, category: value }))
                        }
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="system">System</SelectItem>
                          <SelectItem value="approval">Approval</SelectItem>
                          <SelectItem value="reminder">Reminder</SelectItem>
                          <SelectItem value="update">Update</SelectItem>
                          <SelectItem value="alert">Alert</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="priority">Priority</Label>
                    <Select
                      value={sendForm.priority}
                      onValueChange={(value: 'low' | 'normal' | 'high' | 'urgent') => 
                        setSendForm(prev => ({ ...prev, priority: value }))
                      }
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="low">Low</SelectItem>
                        <SelectItem value="normal">Normal</SelectItem>
                        <SelectItem value="high">High</SelectItem>
                        <SelectItem value="urgent">Urgent</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="title">Title *</Label>
                    <Input
                      id="title"
                      value={sendForm.title}
                      onChange={(e) => setSendForm(prev => ({ ...prev, title: e.target.value }))}
                      placeholder="Notification title"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="message">Message *</Label>
                    <Textarea
                      id="message"
                      value={sendForm.message}
                      onChange={(e) => setSendForm(prev => ({ ...prev, message: e.target.value }))}
                      placeholder="Notification message"
                      rows={4}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="actionUrl">Action URL (optional)</Label>
                    <Input
                      id="actionUrl"
                      value={sendForm.actionUrl}
                      onChange={(e) => setSendForm(prev => ({ ...prev, actionUrl: e.target.value }))}
                      placeholder="https://example.com"
                    />
                  </div>

                  <div className="space-y-2">
                    <Label htmlFor="expiresAt">Expires At (optional)</Label>
                    <Input
                      id="expiresAt"
                      type="datetime-local"
                      value={sendForm.expiresAt}
                      onChange={(e) => setSendForm(prev => ({ ...prev, expiresAt: e.target.value }))}
                    />
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setSendDialogOpen(false)}>
                    Cancel
                  </Button>
                  <Button onClick={handleSendNotification} disabled={sending}>
                    {sending ? <LoadingSpinner size="sm" /> : 'Send Notification'}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          )}
          
          {unreadCount > 0 && (
            <Button variant="outline" onClick={handleMarkAllAsRead} disabled={markingRead}>
              <CheckCircle className="w-4 h-4 mr-2" />
              Mark All Read
            </Button>
          )}
        </div>
      </div>

      {/* Filters and Search */}
      <Card>
        <CardContent className="pt-6">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground w-4 h-4" />
                <Input
                  placeholder="Search notifications..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
            <div className="flex gap-2">
              <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                <SelectTrigger className="w-[150px]">
                  <SelectValue placeholder="Category" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Categories</SelectItem>
                  <SelectItem value="approval">Approval</SelectItem>
                  <SelectItem value="reminder">Reminder</SelectItem>
                  <SelectItem value="update">Update</SelectItem>
                  <SelectItem value="alert">Alert</SelectItem>
                  <SelectItem value="system">System</SelectItem>
                </SelectContent>
              </Select>
              <Select value={priorityFilter} onValueChange={setPriorityFilter}>
                <SelectTrigger className="w-[150px]">
                  <SelectValue placeholder="Priority" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Priorities</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="normal">Normal</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Bulk Actions */}
      {selectedNotifications.size > 0 && (
        <Card>
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <p className="text-sm text-muted-foreground">
                {selectedNotifications.size} notification(s) selected
              </p>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={handleBulkMarkAsRead}>
                  <CheckCircle className="w-4 h-4 mr-2" />
                  Mark as Read
                </Button>
                <Button variant="outline" size="sm" onClick={handleBulkDelete}>
                  <Trash2 className="w-4 h-4 mr-2" />
                  Delete
                </Button>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Notifications List */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Your Notifications</CardTitle>
              <CardDescription>
                {unreadCount} unread • {notifications.length} total
              </CardDescription>
            </div>
            {filteredNotifications.length > 0 && (
              <Button variant="ghost" size="sm" onClick={toggleSelectAll}>
                {selectedNotifications.size === filteredNotifications.length ? (
                  <>
                    <EyeOff className="w-4 h-4 mr-2" />
                    Deselect All
                  </>
                ) : (
                  <>
                    <Eye className="w-4 h-4 mr-2" />
                    Select All
                  </>
                )}
              </Button>
            )}
          </div>
        </CardHeader>
        <CardContent>
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <TabsList className="grid w-full grid-cols-5">
              <TabsTrigger value="all">All</TabsTrigger>
              <TabsTrigger value="unread">Unread ({unreadCount})</TabsTrigger>
              <TabsTrigger value="approval">Approval</TabsTrigger>
              <TabsTrigger value="alert">Alerts</TabsTrigger>
              <TabsTrigger value="system">System</TabsTrigger>
            </TabsList>
            
            <TabsContent value={activeTab} className="mt-4">
              {loadingNotifications ? (
                <div className="flex justify-center py-12">
                  <LoadingSpinner size="md" text="Loading notifications..." />
                </div>
              ) : filteredNotifications.length === 0 ? (
                <div className="text-center py-12 text-muted-foreground">
                  <Bell className="w-12 h-12 mx-auto mb-4 opacity-50" />
                  <p className="text-lg font-medium">No notifications found</p>
                  <p className="text-sm">Try adjusting your filters or search query</p>
                </div>
              ) : (
                <ScrollArea className="h-[600px]">
                  <div className="space-y-2">
                    {filteredNotifications.map((notification) => (
                      <div
                        key={notification.id}
                        className={`p-4 rounded-lg border transition-colors ${
                          !notification.read_at ? 'bg-blue-50/50 border-blue-200' : 'bg-card'
                        } ${
                          selectedNotifications.has(notification.id) ? 'ring-2 ring-primary' : ''
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <Checkbox
                            checked={selectedNotifications.has(notification.id)}
                            onCheckedChange={() => toggleSelection(notification.id)}
                            className="mt-1"
                          />
                          
                          <div
                            className="flex-1 cursor-pointer"
                            onClick={() => handleNotificationClick(notification)}
                          >
                            <div className="flex items-start justify-between mb-2">
                              <div className="flex items-center gap-2 flex-1">
                                {getPriorityIcon(notification.priority)}
                                <h4 className="font-semibold text-base">
                                  {notification.title}
                                </h4>
                                {!notification.read_at && (
                                  <div className="w-2 h-2 bg-blue-500 rounded-full flex-shrink-0" />
                                )}
                              </div>
                              <div className="flex items-center gap-2">
                                <Badge 
                                  variant="secondary" 
                                  className={`text-xs ${getCategoryColor(notification.category)}`}
                                >
                                  {notification.category}
                                </Badge>
                                <Popover>
                                  <PopoverTrigger asChild>
                                    <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                                      <MoreVertical className="w-4 h-4" />
                                    </Button>
                                  </PopoverTrigger>
                                  <PopoverContent className="w-48 p-2">
                                    <div className="space-y-1">
                                      {!notification.read_at && (
                                        <Button
                                          variant="ghost"
                                          size="sm"
                                          className="w-full justify-start"
                                          onClick={() => handleMarkAsRead(notification.id)}
                                        >
                                          <Check className="w-4 h-4 mr-2" />
                                          Mark as Read
                                        </Button>
                                      )}
                                      <Button
                                        variant="ghost"
                                        size="sm"
                                        className="w-full justify-start text-destructive"
                                        onClick={() => {
                                          setNotificationToDelete(notification.id);
                                          setDeleteDialogOpen(true);
                                        }}
                                      >
                                        <Trash2 className="w-4 h-4 mr-2" />
                                        Delete
                                      </Button>
                                    </div>
                                  </PopoverContent>
                                </Popover>
                              </div>
                            </div>
                            
                            <p className="text-sm text-muted-foreground mb-3">
                              {notification.message}
                            </p>
                            
                            <div className="flex items-center justify-between text-xs text-muted-foreground">
                              <div className="flex items-center gap-4">
                                <div className="flex items-center">
                                  <Clock className="w-3 h-3 mr-1" />
                                  {formatDate(notification.created_at)}
                                </div>
                                {notification.action_url && (
                                  <div className="flex items-center text-primary">
                                    <ExternalLink className="w-3 h-3 mr-1" />
                                    Has action
                                  </div>
                                )}
                              </div>
                              {notification.expires_at && (
                                <div className="text-orange-600">
                                  Expires: {new Date(notification.expires_at).toLocaleDateString()}
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              )}
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      {/* Delete Confirmation Dialog */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Notification</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete this notification? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setNotificationToDelete(null)}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (notificationToDelete) {
                  handleDeleteNotification(notificationToDelete);
                  setNotificationToDelete(null);
                  setDeleteDialogOpen(false);
                }
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
};

export default Notifications;

/**
 * Procurement Goods Receipts Page
 * Goods Receipt Note (GRN) management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  PackageCheck,
  Plus,
  Search,
  Loader2,
  Eye,
  CheckCircle2,
  Clock,
  XCircle,
  AlertCircle,
  MoreVertical,
  FileText,
  Warehouse,
  Calendar,
} from 'lucide-react';
import {
  getGoodsReceipts,
  createGoodsReceipt,
  getPurchaseOrders,
  type GoodsReceipt,
  type PurchaseOrder,
} from '@/services/api/procurement';
import {
  getWarehouses,
  type Warehouse as WarehouseType,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface GRNItem {
  po_item_id: string;
  product_id?: string;
  ordered_quantity: number;
  received_quantity: number;
  accepted_quantity: number;
  rejected_quantity: number;
  unit_price?: number;
  batch_number?: string;
  expiry_date?: string;
  quality_status: 'passed' | 'failed' | 'partial';
  notes?: string;
  product_name?: string;
  product_sku?: string;
}

export default function ProcurementGoodsReceipts() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Goods Receipts
  const [goodsReceipts, setGoodsReceipts] = useState<GoodsReceipt[]>([]);
  const [filteredReceipts, setFilteredReceipts] = useState<GoodsReceipt[]>([]);
  const [selectedReceipt, setSelectedReceipt] = useState<GoodsReceipt | null>(null);
  const [showGRNDialog, setShowGRNDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);

  // Related data
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [warehouses, setWarehouses] = useState<WarehouseType[]>([]);
  const [selectedPO, setSelectedPO] = useState<PurchaseOrder | null>(null);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [poFilter, setPoFilter] = useState<string>('all');

  // GRN form
  const [grnForm, setGrnForm] = useState({
    po_id: '',
    warehouse_id: '',
    received_date: new Date().toISOString().split('T')[0],
    inspection_notes: '',
    notes: '',
    items: [] as GRNItem[],
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchGoodsReceipts(),
          fetchPurchaseOrders(),
          fetchWarehouses(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading goods receipts data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load goods receipts',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = goodsReceipts;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(grn =>
        grn.grn_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        grn.po_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        grn.warehouse_name?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(grn => grn.status === statusFilter);
    }

    // PO filter
    if (poFilter !== 'all') {
      filtered = filtered.filter(grn => grn.po_id === poFilter);
    }

    setFilteredReceipts(filtered);
  }, [goodsReceipts, searchTerm, statusFilter, poFilter]);

  const fetchGoodsReceipts = async () => {
    try {
      setLoading(true);
      const data = await getGoodsReceipts();
      setGoodsReceipts(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch goods receipts',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchPurchaseOrders = async () => {
    try {
      const data = await getPurchaseOrders();
      setPurchaseOrders(data || []);
    } catch (error: unknown) {
      console.error('Error fetching purchase orders:', error);
    }
  };

  const fetchWarehouses = async () => {
    try {
      const data = await getWarehouses();
      setWarehouses(data || []);
    } catch (error: unknown) {
      console.error('Error fetching warehouses:', error);
    }
  };

  const handlePOSelection = async (poId: string) => {
    try {
      const po = purchaseOrders.find(p => p.id === poId);
      if (po) {
        setSelectedPO(po);
        // Load PO items if available
        if ((po as unknown).items) {
          const items: GRNItem[] = (po as unknown).items.map((item: unknown) => ({
            po_item_id: item.id || '',
            product_id: item.product_id,
            ordered_quantity: typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0)),
            received_quantity: typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0)),
            accepted_quantity: typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0)),
            rejected_quantity: 0,
            unit_price: typeof item.unit_price === 'number' ? item.unit_price : parseFloat(String(item.unit_price || 0)),
            quality_status: 'passed',
            product_name: item.product_name,
            product_sku: item.product_sku,
          }));
          setGrnForm({ ...grnForm, po_id: poId, items });
        }
      }
    } catch (error: unknown) {
      console.error('Error loading PO details:', error);
    }
  };

  const handleCreateGRN = async () => {
    try {
      if (!grnForm.po_id || !grnForm.warehouse_id || grnForm.items.length === 0) {
        toast({
          title: 'Validation Error',
          description: 'Please fill in all required fields and add items',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      await createGoodsReceipt({
        po_id: grnForm.po_id,
        warehouse_id: grnForm.warehouse_id,
        received_date: grnForm.received_date,
        inspection_notes: grnForm.inspection_notes || undefined,
        notes: grnForm.notes || undefined,
        items: grnForm.items.map(item => ({
          po_item_id: item.po_item_id,
          received_quantity: item.received_quantity,
          accepted_quantity: item.accepted_quantity,
          rejected_quantity: item.rejected_quantity,
          batch_number: item.batch_number || undefined,
          expiry_date: item.expiry_date || undefined,
          quality_status: item.quality_status,
          notes: item.notes || undefined,
        })),
      });

      toast({
        title: 'Success',
        description: 'Goods receipt created successfully',
      });

      setShowGRNDialog(false);
      resetForm();
      fetchGoodsReceipts();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create goods receipt',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewReceipt = (receipt: GoodsReceipt) => {
    setSelectedReceipt(receipt);
    setShowViewDialog(true);
  };

  const updateItem = (index: number, field: keyof GRNItem, value: unknown) => {
    const updatedItems = [...grnForm.items];
    updatedItems[index] = {
      ...updatedItems[index],
      [field]: value,
    };
    // Auto-calculate accepted quantity
    if (field === 'received_quantity' || field === 'rejected_quantity') {
      const received = typeof updatedItems[index].received_quantity === 'number' 
        ? updatedItems[index].received_quantity 
        : parseFloat(String(updatedItems[index].received_quantity || 0));
      const rejected = typeof updatedItems[index].rejected_quantity === 'number'
        ? updatedItems[index].rejected_quantity
        : parseFloat(String(updatedItems[index].rejected_quantity || 0));
      updatedItems[index].accepted_quantity = Math.max(0, received - rejected);
    }
    setGrnForm({ ...grnForm, items: updatedItems });
  };

  const resetForm = () => {
    setGrnForm({
      po_id: '',
      warehouse_id: '',
      received_date: new Date().toISOString().split('T')[0],
      inspection_notes: '',
      notes: '',
      items: [],
    });
    setSelectedPO(null);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowGRNDialog(true);
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; icon: unknown; label: string }> = {
      pending: { variant: 'outline', icon: Clock, label: 'Pending' },
      inspected: { variant: 'default', icon: PackageCheck, label: 'Inspected' },
      approved: { variant: 'default', icon: CheckCircle2, label: 'Approved' },
      rejected: { variant: 'destructive', icon: XCircle, label: 'Rejected' },
    };

    const config = statusConfig[status] || { variant: 'secondary', icon: FileText, label: status };
    const Icon = config.icon;
    return (
      <Badge variant={config.variant}>
        <Icon className="h-3 w-3 mr-1" />
        {config.label}
      </Badge>
    );
  };

  const getQualityBadge = (quality?: string) => {
    if (!quality) return null;
    const qualityConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; label: string }> = {
      passed: { variant: 'default', label: 'Passed' },
      failed: { variant: 'destructive', label: 'Failed' },
      partial: { variant: 'outline', label: 'Partial' },
    };
    const config = qualityConfig[quality] || { variant: 'secondary', label: quality };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  // Calculate statistics
  const totalReceipts = goodsReceipts.length;
  const pendingReceipts = goodsReceipts.filter(grn => grn.status === 'pending').length;
  const approvedReceipts = goodsReceipts.filter(grn => grn.status === 'approved').length;
  const inspectedReceipts = goodsReceipts.filter(grn => grn.status === 'inspected').length;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Goods Receipts (GRN)</h1>
          <p className="text-muted-foreground mt-1">
            Manage goods receipt notes and inventory receiving
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create GRN
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total GRNs</CardTitle>
            <PackageCheck className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalReceipts}</div>
            <p className="text-xs text-muted-foreground">
              All goods receipts
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{pendingReceipts}</div>
            <p className="text-xs text-muted-foreground">
              Awaiting inspection
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Inspected</CardTitle>
            <PackageCheck className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{inspectedReceipts}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Approved</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{approvedReceipts}</div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search GRN numbers..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="inspected">Inspected</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Purchase Order</Label>
              <Select value={poFilter} onValueChange={setPoFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All POs" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Purchase Orders</SelectItem>
                  {purchaseOrders.map((po) => (
                    <SelectItem key={po.id} value={po.id}>
                      {po.po_number}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Goods Receipts Table */}
      <Card>
        <CardHeader>
          <CardTitle>Goods Receipts ({filteredReceipts.length})</CardTitle>
          <CardDescription>
            Manage your goods receipt notes
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredReceipts.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredReceipts.length === 0 ? (
            <Alert>
              <AlertDescription>
                No goods receipts found. {searchTerm || statusFilter !== 'all' || poFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first GRN to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>GRN Number</TableHead>
                    <TableHead>PO Number</TableHead>
                    <TableHead>Warehouse</TableHead>
                    <TableHead>Received Date</TableHead>
                    <TableHead>Quality Status</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredReceipts.map((receipt) => (
                    <TableRow key={receipt.id}>
                      <TableCell className="font-mono font-medium">{receipt.grn_number}</TableCell>
                      <TableCell className="font-mono">{receipt.po_number || 'N/A'}</TableCell>
                      <TableCell>
                        <div className="flex items-center">
                          <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                          {receipt.warehouse_name || receipt.warehouse_code || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell>
                        {new Date(receipt.received_date).toLocaleDateString()}
                      </TableCell>
                      <TableCell>
                        {getQualityBadge(receipt.quality_status)}
                      </TableCell>
                      <TableCell>{getStatusBadge(receipt.status)}</TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewReceipt(receipt)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create GRN Dialog */}
      <Dialog open={showGRNDialog} onOpenChange={setShowGRNDialog}>
        <DialogContent className="max-w-5xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Create Goods Receipt (GRN)</DialogTitle>
            <DialogDescription>
              Record goods received against a purchase order
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="po_id">Purchase Order *</Label>
                <Select
                  value={grnForm.po_id}
                  onValueChange={handlePOSelection}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select purchase order" />
                  </SelectTrigger>
                  <SelectContent>
                    {purchaseOrders
                      .filter(po => ['sent', 'acknowledged', 'partial', 'received'].includes(po.status))
                      .map((po) => (
                        <SelectItem key={po.id} value={po.id}>
                          {po.po_number} - {po.supplier_name || po.supplier_code || 'N/A'}
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="warehouse_id">Warehouse *</Label>
                <Select
                  value={grnForm.warehouse_id}
                  onValueChange={(value) => setGrnForm({ ...grnForm, warehouse_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select warehouse" />
                  </SelectTrigger>
                  <SelectContent>
                    {warehouses.map((warehouse) => (
                      <SelectItem key={warehouse.id} value={warehouse.id}>
                        {warehouse.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="received_date">Received Date *</Label>
              <Input
                id="received_date"
                type="date"
                value={grnForm.received_date}
                onChange={(e) => setGrnForm({ ...grnForm, received_date: e.target.value })}
                required
              />
            </div>

            {/* Items Section */}
            {grnForm.items.length > 0 && (
              <div className="space-y-2">
                <Label>Received Items</Label>
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Product</TableHead>
                        <TableHead className="text-right">Ordered</TableHead>
                        <TableHead className="text-right">Received</TableHead>
                        <TableHead className="text-right">Accepted</TableHead>
                        <TableHead className="text-right">Rejected</TableHead>
                        <TableHead>Batch/Lot</TableHead>
                        <TableHead>Expiry</TableHead>
                        <TableHead>Quality</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {grnForm.items.map((item, index) => (
                        <TableRow key={index}>
                          <TableCell>
                            <div className="flex flex-col">
                              <span className="font-medium">{item.product_name || 'N/A'}</span>
                              {item.product_sku && (
                                <span className="text-xs text-muted-foreground font-mono">
                                  {item.product_sku}
                                </span>
                              )}
                            </div>
                          </TableCell>
                          <TableCell className="text-right">
                            {item.ordered_quantity.toLocaleString()}
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              min="0"
                              value={item.received_quantity}
                              onChange={(e) => updateItem(index, 'received_quantity', parseFloat(e.target.value) || 0)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell className="text-right font-medium">
                            {item.accepted_quantity.toLocaleString()}
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              min="0"
                              value={item.rejected_quantity}
                              onChange={(e) => updateItem(index, 'rejected_quantity', parseFloat(e.target.value) || 0)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.batch_number || ''}
                              onChange={(e) => updateItem(index, 'batch_number', e.target.value)}
                              placeholder="Batch #"
                              className="w-24"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="date"
                              value={item.expiry_date || ''}
                              onChange={(e) => updateItem(index, 'expiry_date', e.target.value)}
                              className="w-32"
                            />
                          </TableCell>
                          <TableCell>
                            <Select
                              value={item.quality_status}
                              onValueChange={(value: 'passed' | 'failed' | 'partial') =>
                                updateItem(index, 'quality_status', value)
                              }
                            >
                              <SelectTrigger className="w-28">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="passed">Passed</SelectItem>
                                <SelectItem value="failed">Failed</SelectItem>
                                <SelectItem value="partial">Partial</SelectItem>
                              </SelectContent>
                            </Select>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              </div>
            )}

            {grnForm.items.length === 0 && selectedPO && (
              <Alert>
                <AlertDescription>
                  No items found in the selected purchase order. Please select a different PO.
                </AlertDescription>
              </Alert>
            )}

            <div className="grid gap-2">
              <Label htmlFor="inspection_notes">Inspection Notes</Label>
              <Textarea
                id="inspection_notes"
                value={grnForm.inspection_notes}
                onChange={(e) => setGrnForm({ ...grnForm, inspection_notes: e.target.value })}
                placeholder="Quality inspection notes"
                rows={3}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="notes">Additional Notes</Label>
              <Textarea
                id="notes"
                value={grnForm.notes}
                onChange={(e) => setGrnForm({ ...grnForm, notes: e.target.value })}
                placeholder="Additional notes"
                rows={2}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowGRNDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateGRN} disabled={loading || !grnForm.po_id || !grnForm.warehouse_id || grnForm.items.length === 0}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              Create GRN
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View GRN Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Goods Receipt Details</DialogTitle>
            <DialogDescription>
              View complete GRN information
            </DialogDescription>
          </DialogHeader>
          {selectedReceipt && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">GRN Number</Label>
                  <p className="font-mono">{selectedReceipt.grn_number}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">PO Number</Label>
                  <p className="font-mono">{selectedReceipt.po_number || 'N/A'}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Warehouse</Label>
                  <div className="flex items-center">
                    <Warehouse className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{selectedReceipt.warehouse_name || selectedReceipt.warehouse_code || 'N/A'}</p>
                  </div>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Received Date</Label>
                  <div className="flex items-center">
                    <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{new Date(selectedReceipt.received_date).toLocaleDateString()}</p>
                  </div>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Quality Status</Label>
                  {getQualityBadge(selectedReceipt.quality_status)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Status</Label>
                  {getStatusBadge(selectedReceipt.status)}
                </div>
              </div>
              {selectedReceipt.inspection_notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Inspection Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedReceipt.inspection_notes}</p>
                </div>
              )}
              {selectedReceipt.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedReceipt.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Procurement Management Page
 * Complete procurement management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import {
  ShoppingCart,
  FileText,
  PackageCheck,
  Plus,
  Loader2,
  CheckCircle2,
  Clock,
  XCircle,
  AlertCircle,
} from 'lucide-react';
import {
  getPurchaseRequisitions,
  createPurchaseRequisition,
  getPurchaseOrders,
  createPurchaseOrder,
  getGoodsReceipts,
  createGoodsReceipt,
  type PurchaseRequisition,
  type PurchaseOrder,
  type GoodsReceipt,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';

export default function ProcurementManagement() {
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(false);
  const { toast } = useToast();

  // Requisitions
  const [requisitions, setRequisitions] = useState<PurchaseRequisition[]>([]);
  const [showRequisitionDialog, setShowRequisitionDialog] = useState(false);
  const [requisitionForm, setRequisitionForm] = useState({
    department_id: '',
    priority: 'normal' as 'low' | 'normal' | 'high' | 'urgent',
    required_date: '',
    notes: '',
    items: [] as Array<{
      product_id?: string;
      description: string;
      quantity: string;
      unit_price?: string;
      unit_of_measure: string;
      notes?: string;
    }>,
  });

  // Purchase Orders
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [showPODialog, setShowPODialog] = useState(false);
  const [poForm, setPoForm] = useState({
    requisition_id: '',
    supplier_id: '',
    expected_delivery_date: '',
    delivery_address: '',
    payment_terms: '',
    currency: 'INR',
    tax_amount: '',
    shipping_cost: '',
    discount_amount: '',
    notes: '',
    items: [] as Array<{
      requisition_item_id?: string;
      product_id?: string;
      description: string;
      quantity: string;
      unit_price: string;
      unit_of_measure: string;
      notes?: string;
    }>,
  });

  // Goods Receipts
  const [goodsReceipts, setGoodsReceipts] = useState<GoodsReceipt[]>([]);
  const [showGRNDialog, setShowGRNDialog] = useState(false);
  const [grnForm, setGrnForm] = useState({
    po_id: '',
    warehouse_id: '',
    received_date: new Date().toISOString().split('T')[0],
    notes: '',
    items: [] as Array<{
      po_item_id: string;
      product_id?: string;
      ordered_quantity: string;
      received_quantity: string;
      accepted_quantity: string;
      rejected_quantity: string;
      unit_price?: string;
      batch_number?: string;
      expiry_date?: string;
      quality_status: 'passed' | 'failed' | 'partial';
      notes?: string;
    }>,
  });

  // Fetch data
  useEffect(() => {
    fetchRequisitions();
    fetchPurchaseOrders();
    fetchGoodsReceipts();
  }, []);

  const fetchRequisitions = async () => {
    try {
      setLoading(true);
      const data = await getPurchaseRequisitions();
      setRequisitions(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch requisitions',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchPurchaseOrders = async () => {
    try {
      const data = await getPurchaseOrders();
      setPurchaseOrders(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch purchase orders',
        variant: 'destructive',
      });
    }
  };

  const fetchGoodsReceipts = async () => {
    try {
      const data = await getGoodsReceipts();
      setGoodsReceipts(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch goods receipts',
        variant: 'destructive',
      });
    }
  };

  const handleCreateRequisition = async () => {
    try {
      setLoading(true);
      await createPurchaseRequisition(requisitionForm);
      toast({
        title: 'Success',
        description: 'Purchase requisition created successfully',
      });
      setShowRequisitionDialog(false);
      setRequisitionForm({
        department_id: '',
        priority: 'normal',
        required_date: '',
        notes: '',
        items: [],
      });
      fetchRequisitions();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create requisition',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePO = async () => {
    try {
      setLoading(true);
      await createPurchaseOrder({
        ...poForm,
        tax_amount: poForm.tax_amount ? parseFloat(poForm.tax_amount) : 0,
        shipping_cost: poForm.shipping_cost ? parseFloat(poForm.shipping_cost) : 0,
        discount_amount: poForm.discount_amount ? parseFloat(poForm.discount_amount) : 0,
      });
      toast({
        title: 'Success',
        description: 'Purchase order created successfully',
      });
      setShowPODialog(false);
      setPoForm({
        requisition_id: '',
        supplier_id: '',
        expected_delivery_date: '',
        delivery_address: '',
        payment_terms: '',
        currency: 'INR',
        tax_amount: '',
        shipping_cost: '',
        discount_amount: '',
        notes: '',
        items: [],
      });
      fetchPurchaseOrders();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create purchase order',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleCreateGRN = async () => {
    try {
      setLoading(true);
      await createGoodsReceipt({
        ...grnForm,
        items: grnForm.items.map(item => ({
          ...item,
          ordered_quantity: parseFloat(item.ordered_quantity),
          received_quantity: parseFloat(item.received_quantity),
          accepted_quantity: parseFloat(item.accepted_quantity),
          rejected_quantity: parseFloat(item.rejected_quantity),
          unit_price: item.unit_price ? parseFloat(item.unit_price) : undefined,
        })),
      });
      toast({
        title: 'Success',
        description: 'Goods receipt created successfully',
      });
      setShowGRNDialog(false);
      setGrnForm({
        po_id: '',
        warehouse_id: '',
        received_date: new Date().toISOString().split('T')[0],
        notes: '',
        items: [],
      });
      fetchGoodsReceipts();
      fetchPurchaseOrders(); // Refresh PO status
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create goods receipt',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'destructive' | 'outline'; icon: unknown }> = {
      draft: { variant: 'secondary', icon: FileText },
      pending: { variant: 'outline', icon: Clock },
      approved: { variant: 'default', icon: CheckCircle2 },
      rejected: { variant: 'destructive', icon: XCircle },
      sent: { variant: 'default', icon: CheckCircle2 },
      received: { variant: 'default', icon: PackageCheck },
      partial: { variant: 'outline', icon: AlertCircle },
    };

    const config = statusConfig[status] || { variant: 'secondary', icon: FileText };
    const Icon = config.icon;

    return (
      <Badge variant={config.variant}>
        <Icon className="mr-1 h-3 w-3" />
        {status.charAt(0).toUpperCase() + status.slice(1)}
      </Badge>
    );
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-3xl font-bold">Procurement Management</h1>
          <p className="text-muted-foreground">Manage purchase requisitions, orders, and goods receipts</p>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-4">
        <TabsList className="grid w-full grid-cols-4">
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="requisitions">Requisitions</TabsTrigger>
          <TabsTrigger value="purchase-orders">Purchase Orders</TabsTrigger>
          <TabsTrigger value="goods-receipts">Goods Receipts</TabsTrigger>
        </TabsList>

        {/* Overview Tab */}
        <TabsContent value="overview" className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Requisitions</CardTitle>
                <FileText className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{requisitions.length}</div>
                <p className="text-xs text-muted-foreground">
                  {requisitions.filter(r => r.status === 'pending').length} pending approval
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Purchase Orders</CardTitle>
                <ShoppingCart className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{purchaseOrders.length}</div>
                <p className="text-xs text-muted-foreground">
                  {purchaseOrders.filter(po => po.status === 'partial' || po.status === 'sent').length} in progress
                </p>
              </CardContent>
            </Card>

            <Card>
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">Goods Receipts</CardTitle>
                <PackageCheck className="h-4 w-4 text-muted-foreground" />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{goodsReceipts.length}</div>
                <p className="text-xs text-muted-foreground">
                  {goodsReceipts.filter(gr => gr.status === 'pending').length} pending inspection
                </p>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Requisitions Tab */}
        <TabsContent value="requisitions" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <div>
                  <CardTitle>Purchase Requisitions</CardTitle>
                  <CardDescription>Request items for purchase</CardDescription>
                </div>
                <Dialog open={showRequisitionDialog} onOpenChange={setShowRequisitionDialog}>
                  <DialogTrigger asChild>
                    <Button>
                      <Plus className="mr-2 h-4 w-4" />
                      New Requisition
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                      <DialogTitle>Create Purchase Requisition</DialogTitle>
                      <DialogDescription>Request items for purchase</DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="req-priority">Priority</Label>
                          <Select
                            value={requisitionForm.priority}
                            onValueChange={(value: 'low' | 'normal' | 'high' | 'urgent') =>
                              setRequisitionForm(prev => ({ ...prev, priority: value }))
                            }
                          >
                            <SelectTrigger>
                              <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                              <SelectItem value="low">Low</SelectItem>
                              <SelectItem value="normal">Normal</SelectItem>
                              <SelectItem value="high">High</SelectItem>
                              <SelectItem value="urgent">Urgent</SelectItem>
                            </SelectContent>
                          </Select>
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="req-date">Required Date</Label>
                          <Input
                            id="req-date"
                            type="date"
                            value={requisitionForm.required_date}
                            onChange={(e) => setRequisitionForm(prev => ({ ...prev, required_date: e.target.value }))}
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label>Items</Label>
                        <div className="space-y-2 border rounded-lg p-4">
                          {requisitionForm.items.map((item, index) => (
                            <div key={index} className="grid grid-cols-12 gap-2 items-end">
                              <div className="col-span-5">
                                <Input
                                  placeholder="Description"
                                  value={item.description}
                                  onChange={(e) => {
                                    const newItems = [...requisitionForm.items];
                                    newItems[index].description = e.target.value;
                                    setRequisitionForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  type="number"
                                  step="0.01"
                                  placeholder="Qty"
                                  value={item.quantity}
                                  onChange={(e) => {
                                    const newItems = [...requisitionForm.items];
                                    newItems[index].quantity = e.target.value;
                                    setRequisitionForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  type="number"
                                  step="0.01"
                                  placeholder="Unit Price"
                                  value={item.unit_price}
                                  onChange={(e) => {
                                    const newItems = [...requisitionForm.items];
                                    newItems[index].unit_price = e.target.value;
                                    setRequisitionForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  placeholder="Unit"
                                  value={item.unit_of_measure}
                                  onChange={(e) => {
                                    const newItems = [...requisitionForm.items];
                                    newItems[index].unit_of_measure = e.target.value;
                                    setRequisitionForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-1">
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() => {
                                    const newItems = requisitionForm.items.filter((_, i) => i !== index);
                                    setRequisitionForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                >
                                  ×
                                </Button>
                              </div>
                            </div>
                          ))}
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setRequisitionForm(prev => ({
                                ...prev,
                                items: [...prev.items, {
                                  description: '',
                                  quantity: '',
                                  unit_price: '',
                                  unit_of_measure: 'pcs',
                                }],
                              }));
                            }}
                          >
                            <Plus className="mr-2 h-4 w-4" />
                            Add Item
                          </Button>
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label htmlFor="req-notes">Notes</Label>
                        <Textarea
                          id="req-notes"
                          value={requisitionForm.notes}
                          onChange={(e) => setRequisitionForm(prev => ({ ...prev, notes: e.target.value }))}
                          placeholder="Additional notes..."
                        />
                      </div>

                      <div className="flex justify-end gap-2">
                        <Button variant="outline" onClick={() => setShowRequisitionDialog(false)}>
                          Cancel
                        </Button>
                        <Button
                          onClick={handleCreateRequisition}
                          disabled={loading || requisitionForm.items.length === 0}
                        >
                          {loading ? (
                            <>
                              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              Creating...
                            </>
                          ) : (
                            'Create Requisition'
                          )}
                        </Button>
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              </div>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Requisition #</TableHead>
                      <TableHead>Requested By</TableHead>
                      <TableHead>Priority</TableHead>
                      <TableHead>Required Date</TableHead>
                      <TableHead>Total Amount</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {requisitions.map((req) => (
                      <TableRow key={req.id}>
                        <TableCell className="font-mono">{req.requisition_number}</TableCell>
                        <TableCell>{req.requested_by_name || req.requested_by_email || '-'}</TableCell>
                        <TableCell>
                          <Badge variant={req.priority === 'urgent' ? 'destructive' : 'outline'}>
                            {req.priority}
                          </Badge>
                        </TableCell>
                        <TableCell>{req.required_date || '-'}</TableCell>
                        <TableCell className="font-mono">
                          ₹{typeof req.total_amount === 'number' ? req.total_amount.toFixed(2) : (parseFloat(String(req.total_amount || 0))).toFixed(2)}
                        </TableCell>
                        <TableCell>{getStatusBadge(req.status)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
        </TabsContent>

        {/* Purchase Orders Tab */}
        <TabsContent value="purchase-orders" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <div>
                  <CardTitle>Purchase Orders</CardTitle>
                  <CardDescription>Manage purchase orders to suppliers</CardDescription>
                </div>
                <Dialog open={showPODialog} onOpenChange={setShowPODialog}>
                  <DialogTrigger asChild>
                    <Button>
                      <Plus className="mr-2 h-4 w-4" />
                      New Purchase Order
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                      <DialogTitle>Create Purchase Order</DialogTitle>
                      <DialogDescription>Create a new purchase order to supplier</DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="po-supplier">Supplier *</Label>
                          <Input
                            id="po-supplier"
                            value={poForm.supplier_id}
                            onChange={(e) => setPoForm(prev => ({ ...prev, supplier_id: e.target.value }))}
                            placeholder="Supplier ID"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="po-delivery-date">Expected Delivery Date</Label>
                          <Input
                            id="po-delivery-date"
                            type="date"
                            value={poForm.expected_delivery_date}
                            onChange={(e) => setPoForm(prev => ({ ...prev, expected_delivery_date: e.target.value }))}
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label>Items</Label>
                        <div className="space-y-2 border rounded-lg p-4">
                          {poForm.items.map((item, index) => (
                            <div key={index} className="grid grid-cols-12 gap-2 items-end">
                              <div className="col-span-4">
                                <Input
                                  placeholder="Description"
                                  value={item.description}
                                  onChange={(e) => {
                                    const newItems = [...poForm.items];
                                    newItems[index].description = e.target.value;
                                    setPoForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  type="number"
                                  step="0.01"
                                  placeholder="Qty"
                                  value={item.quantity}
                                  onChange={(e) => {
                                    const newItems = [...poForm.items];
                                    newItems[index].quantity = e.target.value;
                                    setPoForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  type="number"
                                  step="0.01"
                                  placeholder="Unit Price"
                                  value={item.unit_price}
                                  onChange={(e) => {
                                    const newItems = [...poForm.items];
                                    newItems[index].unit_price = e.target.value;
                                    setPoForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Input
                                  placeholder="Unit"
                                  value={item.unit_of_measure}
                                  onChange={(e) => {
                                    const newItems = [...poForm.items];
                                    newItems[index].unit_of_measure = e.target.value;
                                    setPoForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() => {
                                    const newItems = poForm.items.filter((_, i) => i !== index);
                                    setPoForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                >
                                  ×
                                </Button>
                              </div>
                            </div>
                          ))}
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setPoForm(prev => ({
                                ...prev,
                                items: [...prev.items, {
                                  description: '',
                                  quantity: '',
                                  unit_price: '',
                                  unit_of_measure: 'pcs',
                                }],
                              }));
                            }}
                          >
                            <Plus className="mr-2 h-4 w-4" />
                            Add Item
                          </Button>
                        </div>
                      </div>

                      <div className="grid grid-cols-3 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="po-tax">Tax Amount</Label>
                          <Input
                            id="po-tax"
                            type="number"
                            step="0.01"
                            value={poForm.tax_amount}
                            onChange={(e) => setPoForm(prev => ({ ...prev, tax_amount: e.target.value }))}
                            placeholder="0.00"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="po-shipping">Shipping Cost</Label>
                          <Input
                            id="po-shipping"
                            type="number"
                            step="0.01"
                            value={poForm.shipping_cost}
                            onChange={(e) => setPoForm(prev => ({ ...prev, shipping_cost: e.target.value }))}
                            placeholder="0.00"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="po-discount">Discount</Label>
                          <Input
                            id="po-discount"
                            type="number"
                            step="0.01"
                            value={poForm.discount_amount}
                            onChange={(e) => setPoForm(prev => ({ ...prev, discount_amount: e.target.value }))}
                            placeholder="0.00"
                          />
                        </div>
                      </div>

                      <div className="flex justify-end gap-2">
                        <Button variant="outline" onClick={() => setShowPODialog(false)}>
                          Cancel
                        </Button>
                        <Button
                          onClick={handleCreatePO}
                          disabled={loading || !poForm.supplier_id || poForm.items.length === 0}
                        >
                          {loading ? (
                            <>
                              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              Creating...
                            </>
                          ) : (
                            'Create Purchase Order'
                          )}
                        </Button>
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              </div>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>PO Number</TableHead>
                      <TableHead>Supplier</TableHead>
                      <TableHead>Order Date</TableHead>
                      <TableHead>Expected Delivery</TableHead>
                      <TableHead>Total Amount</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {purchaseOrders.map((po) => (
                      <TableRow key={po.id}>
                        <TableCell className="font-mono">{po.po_number}</TableCell>
                        <TableCell>{po.supplier_name || po.supplier_code || '-'}</TableCell>
                        <TableCell>{new Date(po.order_date).toLocaleDateString()}</TableCell>
                        <TableCell>{po.expected_delivery_date ? new Date(po.expected_delivery_date).toLocaleDateString() : '-'}</TableCell>
                        <TableCell className="font-mono">
                          {po.currency} {typeof po.total_amount === 'number' ? po.total_amount.toFixed(2) : (parseFloat(String(po.total_amount || 0))).toFixed(2)}
                        </TableCell>
                        <TableCell>{getStatusBadge(po.status)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
        </TabsContent>

        {/* Goods Receipts Tab */}
        <TabsContent value="goods-receipts" className="space-y-4">
          <Card>
            <CardHeader>
              <div className="flex justify-between items-center">
                <div>
                  <CardTitle>Goods Receipts (GRN)</CardTitle>
                  <CardDescription>Record goods received from suppliers</CardDescription>
                </div>
                <Dialog open={showGRNDialog} onOpenChange={setShowGRNDialog}>
                  <DialogTrigger asChild>
                    <Button>
                      <Plus className="mr-2 h-4 w-4" />
                      New Goods Receipt
                    </Button>
                  </DialogTrigger>
                  <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
                    <DialogHeader>
                      <DialogTitle>Create Goods Receipt (GRN)</DialogTitle>
                      <DialogDescription>Record goods received against a purchase order</DialogDescription>
                    </DialogHeader>
                    <div className="space-y-4 py-4">
                      <div className="grid grid-cols-2 gap-4">
                        <div className="space-y-2">
                          <Label htmlFor="grn-po">Purchase Order *</Label>
                          <Input
                            id="grn-po"
                            value={grnForm.po_id}
                            onChange={(e) => setGrnForm(prev => ({ ...prev, po_id: e.target.value }))}
                            placeholder="PO ID"
                          />
                        </div>
                        <div className="space-y-2">
                          <Label htmlFor="grn-warehouse">Warehouse *</Label>
                          <Input
                            id="grn-warehouse"
                            value={grnForm.warehouse_id}
                            onChange={(e) => setGrnForm(prev => ({ ...prev, warehouse_id: e.target.value }))}
                            placeholder="Warehouse ID"
                          />
                        </div>
                      </div>

                      <div className="space-y-2">
                        <Label>Received Items</Label>
                        <div className="space-y-2 border rounded-lg p-4">
                          {grnForm.items.map((item, index) => (
                            <div key={index} className="grid grid-cols-12 gap-2 items-end border-b pb-2">
                              <div className="col-span-2">
                                <Label className="text-xs">Ordered</Label>
                                <Input
                                  type="number"
                                  step="0.01"
                                  value={item.ordered_quantity}
                                  onChange={(e) => {
                                    const newItems = [...grnForm.items];
                                    newItems[index].ordered_quantity = e.target.value;
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Label className="text-xs">Received</Label>
                                <Input
                                  type="number"
                                  step="0.01"
                                  value={item.received_quantity}
                                  onChange={(e) => {
                                    const newItems = [...grnForm.items];
                                    newItems[index].received_quantity = e.target.value;
                                    newItems[index].accepted_quantity = e.target.value;
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Label className="text-xs">Accepted</Label>
                                <Input
                                  type="number"
                                  step="0.01"
                                  value={item.accepted_quantity}
                                  onChange={(e) => {
                                    const newItems = [...grnForm.items];
                                    newItems[index].accepted_quantity = e.target.value;
                                    const received = parseFloat(newItems[index].received_quantity) || 0;
                                    const accepted = parseFloat(e.target.value) || 0;
                                    newItems[index].rejected_quantity = String(received - accepted);
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                />
                              </div>
                              <div className="col-span-2">
                                <Label className="text-xs">Quality</Label>
                                <Select
                                  value={item.quality_status}
                                  onValueChange={(value: 'passed' | 'failed' | 'partial') => {
                                    const newItems = [...grnForm.items];
                                    newItems[index].quality_status = value;
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                >
                                  <SelectTrigger>
                                    <SelectValue />
                                  </SelectTrigger>
                                  <SelectContent>
                                    <SelectItem value="passed">Passed</SelectItem>
                                    <SelectItem value="failed">Failed</SelectItem>
                                    <SelectItem value="partial">Partial</SelectItem>
                                  </SelectContent>
                                </Select>
                              </div>
                              <div className="col-span-2">
                                <Label className="text-xs">Batch #</Label>
                                <Input
                                  value={item.batch_number}
                                  onChange={(e) => {
                                    const newItems = [...grnForm.items];
                                    newItems[index].batch_number = e.target.value;
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                  placeholder="Batch number"
                                />
                              </div>
                              <div className="col-span-2">
                                <Button
                                  variant="ghost"
                                  size="sm"
                                  onClick={() => {
                                    const newItems = grnForm.items.filter((_, i) => i !== index);
                                    setGrnForm(prev => ({ ...prev, items: newItems }));
                                  }}
                                >
                                  ×
                                </Button>
                              </div>
                            </div>
                          ))}
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => {
                              setGrnForm(prev => ({
                                ...prev,
                                items: [...prev.items, {
                                  po_item_id: '',
                                  ordered_quantity: '',
                                  received_quantity: '',
                                  accepted_quantity: '',
                                  rejected_quantity: '0',
                                  quality_status: 'passed',
                                }],
                              }));
                            }}
                          >
                            <Plus className="mr-2 h-4 w-4" />
                            Add Item
                          </Button>
                        </div>
                      </div>

                      <div className="flex justify-end gap-2">
                        <Button variant="outline" onClick={() => setShowGRNDialog(false)}>
                          Cancel
                        </Button>
                        <Button
                          onClick={handleCreateGRN}
                          disabled={loading || !grnForm.po_id || !grnForm.warehouse_id || grnForm.items.length === 0}
                        >
                          {loading ? (
                            <>
                              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              Creating...
                            </>
                          ) : (
                            'Create GRN'
                          )}
                        </Button>
                      </div>
                    </div>
                  </DialogContent>
                </Dialog>
              </div>
            </CardHeader>
            <CardContent>
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>GRN Number</TableHead>
                      <TableHead>PO Number</TableHead>
                      <TableHead>Warehouse</TableHead>
                      <TableHead>Received Date</TableHead>
                      <TableHead>Status</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {goodsReceipts.map((gr) => (
                      <TableRow key={gr.id}>
                        <TableCell className="font-mono">{gr.grn_number}</TableCell>
                        <TableCell className="font-mono">{gr.po_number || '-'}</TableCell>
                        <TableCell>{gr.warehouse_name || gr.warehouse_code || '-'}</TableCell>
                        <TableCell>{new Date(gr.received_date).toLocaleDateString()}</TableCell>
                        <TableCell>{getStatusBadge(gr.status)}</TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              </CardContent>
            </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

/**
 * Procurement Purchase Orders Page
 * Complete purchase order management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  ShoppingCart,
  Plus,
  Search,
  Loader2,
  Edit,
  Eye,
  FileText,
  MoreVertical,
  CheckCircle2,
  Clock,
  XCircle,
  Package,
  DollarSign,
  Calendar,
} from 'lucide-react';
import {
  getPurchaseOrders,
  createPurchaseOrder,
  getPurchaseOrderById,
  updatePurchaseOrder,
  getSuppliers,
  type PurchaseOrder,
  type Supplier,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface PurchaseOrderItem {
  id?: string;
  requisition_item_id?: string;
  product_id?: string;
  description: string;
  quantity: number;
  unit_price: number;
  unit_of_measure: string;
  total_price?: number;
  notes?: string;
  product_name?: string;
  product_sku?: string;
}

interface PurchaseOrderWithItems extends PurchaseOrder {
  items?: PurchaseOrderItem[];
}

export default function ProcurementPurchaseOrders() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Purchase Orders
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [filteredOrders, setFilteredOrders] = useState<PurchaseOrder[]>([]);
  const [selectedOrder, setSelectedOrder] = useState<PurchaseOrderWithItems | null>(null);
  const [showOrderDialog, setShowOrderDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Suppliers
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [supplierFilter, setSupplierFilter] = useState<string>('all');

  // Purchase Order form
  const [poForm, setPoForm] = useState({
    supplier_id: '',
    expected_delivery_date: '',
    delivery_address: '',
    payment_terms: '',
    currency: 'INR',
    exchange_rate: '1',
    tax_amount: '',
    shipping_cost: '',
    discount_amount: '',
    notes: '',
    terms_conditions: '',
    items: [] as PurchaseOrderItem[],
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchPurchaseOrders(),
          fetchSuppliers(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading purchase orders data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load purchase orders',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = purchaseOrders;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(po =>
        po.po_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        po.supplier_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        po.supplier_code?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(po => po.status === statusFilter);
    }

    // Supplier filter
    if (supplierFilter !== 'all') {
      filtered = filtered.filter(po => po.supplier_id === supplierFilter);
    }

    setFilteredOrders(filtered);
  }, [purchaseOrders, searchTerm, statusFilter, supplierFilter]);

  const fetchPurchaseOrders = async () => {
    try {
      setLoading(true);
      const data = await getPurchaseOrders();
      setPurchaseOrders(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch purchase orders',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchSuppliers = async () => {
    try {
      const data = await getSuppliers({ is_active: true });
      setSuppliers(data || []);
    } catch (error: unknown) {
      console.error('Error fetching suppliers:', error);
    }
  };

  const handleCreateOrder = async () => {
    try {
      setLoading(true);
      const orderData = {
        ...poForm,
        supplier_id: poForm.supplier_id,
        expected_delivery_date: poForm.expected_delivery_date || undefined,
        delivery_address: poForm.delivery_address || undefined,
        payment_terms: poForm.payment_terms || undefined,
        currency: poForm.currency,
        exchange_rate: parseFloat(poForm.exchange_rate) || 1,
        tax_amount: parseFloat(poForm.tax_amount) || 0,
        shipping_cost: parseFloat(poForm.shipping_cost) || 0,
        discount_amount: parseFloat(poForm.discount_amount) || 0,
        notes: poForm.notes || undefined,
        terms_conditions: poForm.terms_conditions || undefined,
        items: poForm.items.map(item => ({
          requisition_item_id: item.requisition_item_id,
          product_id: item.product_id,
          description: item.description,
          quantity: item.quantity,
          unit_price: item.unit_price,
          unit_of_measure: item.unit_of_measure || 'pcs',
          notes: item.notes,
        })),
      };

      if (isEditing && selectedOrder) {
        await updatePurchaseOrder(selectedOrder.id, orderData);
        toast({
          title: 'Success',
          description: 'Purchase order updated successfully',
        });
      } else {
        await createPurchaseOrder(orderData);
        toast({
          title: 'Success',
          description: 'Purchase order created successfully',
        });
      }
      setShowOrderDialog(false);
      resetForm();
      fetchPurchaseOrders();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save purchase order',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditOrder = async (order: PurchaseOrder) => {
    try {
      const fullOrder = await getPurchaseOrderById(order.id);
      setSelectedOrder(fullOrder as PurchaseOrderWithItems);
      setIsEditing(true);
      setPoForm({
        supplier_id: fullOrder.supplier_id,
        expected_delivery_date: fullOrder.expected_delivery_date || '',
        delivery_address: fullOrder.delivery_address || '',
        payment_terms: fullOrder.payment_terms || '',
        currency: fullOrder.currency,
        exchange_rate: fullOrder.exchange_rate.toString(),
        tax_amount: fullOrder.tax_amount.toString(),
        shipping_cost: fullOrder.shipping_cost.toString(),
        discount_amount: fullOrder.discount_amount.toString(),
        notes: fullOrder.notes || '',
        terms_conditions: fullOrder.terms_conditions || '',
        items: (fullOrder as PurchaseOrderWithItems).items || [],
      });
      setShowOrderDialog(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load purchase order details',
        variant: 'destructive',
      });
    }
  };

  const handleViewOrder = async (order: PurchaseOrder) => {
    try {
      const fullOrder = await getPurchaseOrderById(order.id);
      setSelectedOrder(fullOrder as PurchaseOrderWithItems);
      setShowViewDialog(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load purchase order details',
        variant: 'destructive',
      });
    }
  };

  const addItem = () => {
    setPoForm({
      ...poForm,
      items: [
        ...poForm.items,
        {
          description: '',
          quantity: 1,
          unit_price: 0,
          unit_of_measure: 'pcs',
        },
      ],
    });
  };

  const removeItem = (index: number) => {
    setPoForm({
      ...poForm,
      items: poForm.items.filter((_, i) => i !== index),
    });
  };

  const updateItem = (index: number, field: keyof PurchaseOrderItem, value: unknown) => {
    const updatedItems = [...poForm.items];
    updatedItems[index] = {
      ...updatedItems[index],
      [field]: value,
    };
    // Calculate total_price
    if (field === 'quantity' || field === 'unit_price') {
      updatedItems[index].total_price =
        updatedItems[index].quantity * updatedItems[index].unit_price;
    }
    setPoForm({ ...poForm, items: updatedItems });
  };

  const calculateSubtotal = () => {
    return poForm.items.reduce((sum, item) => sum + (item.total_price || item.quantity * item.unit_price), 0);
  };

  const calculateTotal = () => {
    const subtotal = calculateSubtotal();
    const tax = parseFloat(poForm.tax_amount) || 0;
    const shipping = parseFloat(poForm.shipping_cost) || 0;
    const discount = parseFloat(poForm.discount_amount) || 0;
    return subtotal + tax + shipping - discount;
  };

  const resetForm = () => {
    setPoForm({
      supplier_id: '',
      expected_delivery_date: '',
      delivery_address: '',
      payment_terms: '',
      currency: 'INR',
      exchange_rate: '1',
      tax_amount: '',
      shipping_cost: '',
      discount_amount: '',
      notes: '',
      terms_conditions: '',
      items: [],
    });
    setSelectedOrder(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowOrderDialog(true);
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; label: string }> = {
      draft: { variant: 'secondary', label: 'Draft' },
      sent: { variant: 'outline', label: 'Sent' },
      acknowledged: { variant: 'default', label: 'Acknowledged' },
      partial: { variant: 'outline', label: 'Partial' },
      received: { variant: 'default', label: 'Received' },
      completed: { variant: 'default', label: 'Completed' },
      cancelled: { variant: 'destructive', label: 'Cancelled' },
    };

    const config = statusConfig[status] || { variant: 'secondary', label: status };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  // Calculate statistics
  const totalOrders = purchaseOrders.length;
  const draftOrders = purchaseOrders.filter(po => po.status === 'draft').length;
  const pendingOrders = purchaseOrders.filter(po => ['sent', 'acknowledged'].includes(po.status)).length;
  const totalValue = purchaseOrders.reduce((sum, po) => {
    const amount = typeof po.total_amount === 'number' ? po.total_amount : parseFloat(String(po.total_amount || 0));
    return sum + (isNaN(amount) ? 0 : amount);
  }, 0);

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Purchase Orders</h1>
          <p className="text-muted-foreground mt-1">
            Manage purchase orders and procurement transactions
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create PO
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Orders</CardTitle>
            <ShoppingCart className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalOrders}</div>
            <p className="text-xs text-muted-foreground">
              All purchase orders
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Draft</CardTitle>
            <FileText className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{draftOrders}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{pendingOrders}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {totalValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR' })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search PO numbers..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="sent">Sent</SelectItem>
                  <SelectItem value="acknowledged">Acknowledged</SelectItem>
                  <SelectItem value="partial">Partial</SelectItem>
                  <SelectItem value="received">Received</SelectItem>
                  <SelectItem value="completed">Completed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Supplier</Label>
              <Select value={supplierFilter} onValueChange={setSupplierFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All suppliers" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Suppliers</SelectItem>
                  {suppliers.map((supplier) => (
                    <SelectItem key={supplier.id} value={supplier.id}>
                      {supplier.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Purchase Orders Table */}
      <Card>
        <CardHeader>
          <CardTitle>Purchase Orders ({filteredOrders.length})</CardTitle>
          <CardDescription>
            Manage your purchase orders
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredOrders.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredOrders.length === 0 ? (
            <Alert>
              <AlertDescription>
                No purchase orders found. {searchTerm || statusFilter !== 'all' || supplierFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first purchase order to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>PO Number</TableHead>
                    <TableHead>Supplier</TableHead>
                    <TableHead>Order Date</TableHead>
                    <TableHead>Expected Delivery</TableHead>
                    <TableHead className="text-right">Total Amount</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredOrders.map((order) => (
                    <TableRow key={order.id}>
                      <TableCell className="font-mono font-medium">{order.po_number}</TableCell>
                      <TableCell>
                        {order.supplier_name || order.supplier_code || 'N/A'}
                      </TableCell>
                      <TableCell>
                        {new Date(order.order_date).toLocaleDateString()}
                      </TableCell>
                      <TableCell>
                        {order.expected_delivery_date
                          ? new Date(order.expected_delivery_date).toLocaleDateString()
                          : '-'}
                      </TableCell>
                      <TableCell className="text-right font-medium">
                        {(typeof order.total_amount === 'number' ? order.total_amount : parseFloat(String(order.total_amount || 0))).toLocaleString('en-IN', {
                          style: 'currency',
                          currency: order.currency || 'INR',
                        })}
                      </TableCell>
                      <TableCell>{getStatusBadge(order.status)}</TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewOrder(order)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEditOrder(order)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <FileText className="mr-2 h-4 w-4" />
                              Print
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Purchase Order Dialog */}
      <Dialog open={showOrderDialog} onOpenChange={setShowOrderDialog}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Purchase Order' : 'Create New Purchase Order'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update purchase order information' : 'Create a new purchase order'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="supplier">Supplier *</Label>
                <Select
                  value={poForm.supplier_id}
                  onValueChange={(value) => setPoForm({ ...poForm, supplier_id: value })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select supplier" />
                  </SelectTrigger>
                  <SelectContent>
                    {suppliers.map((supplier) => (
                      <SelectItem key={supplier.id} value={supplier.id}>
                        {supplier.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="expected_delivery_date">Expected Delivery Date</Label>
                <Input
                  id="expected_delivery_date"
                  type="date"
                  value={poForm.expected_delivery_date}
                  onChange={(e) => setPoForm({ ...poForm, expected_delivery_date: e.target.value })}
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="delivery_address">Delivery Address</Label>
              <Textarea
                id="delivery_address"
                value={poForm.delivery_address}
                onChange={(e) => setPoForm({ ...poForm, delivery_address: e.target.value })}
                placeholder="Delivery address"
                rows={2}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="currency">Currency</Label>
                <Select
                  value={poForm.currency}
                  onValueChange={(value) => setPoForm({ ...poForm, currency: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="INR">INR</SelectItem>
                    <SelectItem value="USD">USD</SelectItem>
                    <SelectItem value="EUR">EUR</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="payment_terms">Payment Terms</Label>
                <Input
                  id="payment_terms"
                  value={poForm.payment_terms}
                  onChange={(e) => setPoForm({ ...poForm, payment_terms: e.target.value })}
                  placeholder="e.g., Net 30"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="exchange_rate">Exchange Rate</Label>
                <Input
                  id="exchange_rate"
                  type="number"
                  step="0.0001"
                  value={poForm.exchange_rate}
                  onChange={(e) => setPoForm({ ...poForm, exchange_rate: e.target.value })}
                />
              </div>
            </div>

            {/* Items Section */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Items</Label>
                <Button type="button" variant="outline" size="sm" onClick={addItem}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Item
                </Button>
              </div>
              {poForm.items.length === 0 ? (
                <Alert>
                  <AlertDescription>No items added. Click "Add Item" to add items to this purchase order.</AlertDescription>
                </Alert>
              ) : (
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Description</TableHead>
                        <TableHead>Quantity</TableHead>
                        <TableHead>Unit Price</TableHead>
                        <TableHead>Unit</TableHead>
                        <TableHead className="text-right">Total</TableHead>
                        <TableHead></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {poForm.items.map((item, index) => (
                        <TableRow key={index}>
                          <TableCell>
                            <Input
                              value={item.description}
                              onChange={(e) => updateItem(index, 'description', e.target.value)}
                              placeholder="Item description"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              min="1"
                              value={item.quantity}
                              onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              step="0.01"
                              value={item.unit_price}
                              onChange={(e) => updateItem(index, 'unit_price', parseFloat(e.target.value) || 0)}
                              className="w-24"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.unit_of_measure}
                              onChange={(e) => updateItem(index, 'unit_of_measure', e.target.value)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell className="text-right font-medium">
                            {(item.total_price || item.quantity * item.unit_price).toLocaleString('en-IN', {
                              style: 'currency',
                              currency: poForm.currency,
                            })}
                          </TableCell>
                          <TableCell>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => removeItem(index)}
                            >
                              <XCircle className="h-4 w-4" />
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </div>

            {/* Totals */}
            <div className="grid gap-4 md:grid-cols-2 border-t pt-4">
              <div className="space-y-2">
                <div className="grid gap-2">
                  <Label htmlFor="tax_amount">Tax Amount</Label>
                  <Input
                    id="tax_amount"
                    type="number"
                    step="0.01"
                    value={poForm.tax_amount}
                    onChange={(e) => setPoForm({ ...poForm, tax_amount: e.target.value })}
                  />
                </div>
                <div className="grid gap-2">
                  <Label htmlFor="shipping_cost">Shipping Cost</Label>
                  <Input
                    id="shipping_cost"
                    type="number"
                    step="0.01"
                    value={poForm.shipping_cost}
                    onChange={(e) => setPoForm({ ...poForm, shipping_cost: e.target.value })}
                  />
                </div>
                <div className="grid gap-2">
                  <Label htmlFor="discount_amount">Discount Amount</Label>
                  <Input
                    id="discount_amount"
                    type="number"
                    step="0.01"
                    value={poForm.discount_amount}
                    onChange={(e) => setPoForm({ ...poForm, discount_amount: e.target.value })}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <div className="flex justify-between">
                  <span className="text-sm">Subtotal:</span>
                  <span className="font-medium">
                    {calculateSubtotal().toLocaleString('en-IN', {
                      style: 'currency',
                      currency: poForm.currency,
                    })}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm">Tax:</span>
                  <span className="font-medium">
                    {(parseFloat(poForm.tax_amount) || 0).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: poForm.currency,
                    })}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm">Shipping:</span>
                  <span className="font-medium">
                    {(parseFloat(poForm.shipping_cost) || 0).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: poForm.currency,
                    })}
                  </span>
                </div>
                <div className="flex justify-between">
                  <span className="text-sm">Discount:</span>
                  <span className="font-medium text-red-600">
                    -{(parseFloat(poForm.discount_amount) || 0).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: poForm.currency,
                    })}
                  </span>
                </div>
                <div className="flex justify-between border-t pt-2 font-bold text-lg">
                  <span>Total:</span>
                  <span>
                    {calculateTotal().toLocaleString('en-IN', {
                      style: 'currency',
                      currency: poForm.currency,
                    })}
                  </span>
                </div>
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={poForm.notes}
                onChange={(e) => setPoForm({ ...poForm, notes: e.target.value })}
                placeholder="Additional notes"
                rows={2}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="terms_conditions">Terms & Conditions</Label>
              <Textarea
                id="terms_conditions"
                value={poForm.terms_conditions}
                onChange={(e) => setPoForm({ ...poForm, terms_conditions: e.target.value })}
                placeholder="Terms and conditions"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowOrderDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateOrder} disabled={loading || !poForm.supplier_id || poForm.items.length === 0}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Purchase Order
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Purchase Order Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Purchase Order Details</DialogTitle>
            <DialogDescription>
              View complete purchase order information
            </DialogDescription>
          </DialogHeader>
          {selectedOrder && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">PO Number</Label>
                  <p className="font-mono">{selectedOrder.po_number}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Supplier</Label>
                  <p>{selectedOrder.supplier_name || selectedOrder.supplier_code || 'N/A'}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Order Date</Label>
                  <p>{new Date(selectedOrder.order_date).toLocaleDateString()}</p>
                </div>
                {selectedOrder.expected_delivery_date && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Expected Delivery</Label>
                    <p>{new Date(selectedOrder.expected_delivery_date).toLocaleDateString()}</p>
                  </div>
                )}
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Status</Label>
                  {getStatusBadge(selectedOrder.status)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Total Amount</Label>
                  <p className="font-bold text-lg">
                    {selectedOrder.total_amount.toLocaleString('en-IN', {
                      style: 'currency',
                      currency: selectedOrder.currency || 'INR',
                    })}
                  </p>
                </div>
              </div>

              {selectedOrder.items && selectedOrder.items.length > 0 && (
                <div className="space-y-2">
                  <Label className="text-sm font-medium">Items</Label>
                  <div className="rounded-md border">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Description</TableHead>
                          <TableHead>Quantity</TableHead>
                          <TableHead>Unit Price</TableHead>
                          <TableHead>Unit</TableHead>
                          <TableHead className="text-right">Total</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {selectedOrder.items.map((item, index) => (
                          <TableRow key={index}>
                            <TableCell>{item.description}</TableCell>
                            <TableCell>{item.quantity}</TableCell>
                            <TableCell>
                              {(typeof item.unit_price === 'number' ? item.unit_price : parseFloat(String(item.unit_price || 0))).toLocaleString('en-IN', {
                                style: 'currency',
                                currency: selectedOrder.currency || 'INR',
                              })}
                            </TableCell>
                            <TableCell>{item.unit_of_measure}</TableCell>
                            <TableCell className="text-right font-medium">
                              {(() => {
                                const qty = typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0));
                                const price = typeof item.unit_price === 'number' ? item.unit_price : parseFloat(String(item.unit_price || 0));
                                const total = item.total_price || (qty * price);
                                return (typeof total === 'number' ? total : parseFloat(String(total || 0))).toLocaleString('en-IN', {
                                  style: 'currency',
                                  currency: selectedOrder.currency || 'INR',
                                });
                              })()}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </div>
                </div>
              )}

              <div className="grid gap-4 md:grid-cols-2 border-t pt-4">
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span className="text-sm">Subtotal:</span>
                    <span className="font-medium">
                      {(typeof selectedOrder.subtotal === 'number' ? selectedOrder.subtotal : parseFloat(String(selectedOrder.subtotal || 0))).toLocaleString('en-IN', {
                        style: 'currency',
                        currency: selectedOrder.currency || 'INR',
                      })}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-sm">Tax:</span>
                    <span className="font-medium">
                      {(typeof selectedOrder.tax_amount === 'number' ? selectedOrder.tax_amount : parseFloat(String(selectedOrder.tax_amount || 0))).toLocaleString('en-IN', {
                        style: 'currency',
                        currency: selectedOrder.currency || 'INR',
                      })}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-sm">Shipping:</span>
                    <span className="font-medium">
                      {(typeof selectedOrder.shipping_cost === 'number' ? selectedOrder.shipping_cost : parseFloat(String(selectedOrder.shipping_cost || 0))).toLocaleString('en-IN', {
                        style: 'currency',
                        currency: selectedOrder.currency || 'INR',
                      })}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-sm">Discount:</span>
                    <span className="font-medium text-red-600">
                      -{(typeof selectedOrder.discount_amount === 'number' ? selectedOrder.discount_amount : parseFloat(String(selectedOrder.discount_amount || 0))).toLocaleString('en-IN', {
                        style: 'currency',
                        currency: selectedOrder.currency || 'INR',
                      })}
                    </span>
                  </div>
                </div>
                <div className="flex justify-between border-t pt-2 font-bold text-lg">
                  <span>Total:</span>
                  <span>
                    {(typeof selectedOrder.total_amount === 'number' ? selectedOrder.total_amount : parseFloat(String(selectedOrder.total_amount || 0))).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: selectedOrder.currency || 'INR',
                    })}
                  </span>
                </div>
              </div>

              {selectedOrder.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedOrder.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
            {selectedOrder && (
              <Button onClick={() => {
                setShowViewDialog(false);
                handleEditOrder(selectedOrder);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Procurement Reports Page
 * Comprehensive procurement analytics and reporting
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  BarChart3,
  TrendingUp,
  ShoppingCart,
  FileText,
  Users,
  DollarSign,
  Calendar,
  Download,
  RefreshCw,
  Loader2,
  CheckCircle2,
  Clock,
  Package,
  Building2,
} from 'lucide-react';
import {
  getProcurementReports,
  type ProcurementReports,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Badge } from '@/components/ui/badge';

export default function ProcurementReports() {
  const { toast } = useToast();
  const [reports, setReports] = useState<ProcurementReports | null>(null);
  const [loading, setLoading] = useState(true);
  const [dateFrom, setDateFrom] = useState(() => {
    const date = new Date();
    date.setDate(date.getDate() - 30);
    return date.toISOString().split('T')[0];
  });
  const [dateTo, setDateTo] = useState(() => {
    return new Date().toISOString().split('T')[0];
  });

  useEffect(() => {
    loadReports();
  }, [dateFrom, dateTo]);

  const loadReports = async () => {
    try {
      setLoading(true);
      const data = await getProcurementReports({
        date_from: dateFrom,
        date_to: dateTo,
      });
      setReports(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load procurement reports',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (value: number | undefined) => {
    if (value === undefined || value === null) return '₹0.00';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      minimumFractionDigits: 2,
    }).format(numValue);
  };

  const formatNumber = (value: number | undefined) => {
    if (value === undefined || value === null) return '0';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-IN').format(numValue);
  };

  const handleExport = () => {
    toast({
      title: 'Export',
      description: 'Export functionality coming soon',
    });
  };

  if (loading && !reports) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  const summary = reports?.summary || {};
  const requisitionsByStatus = reports?.requisitions_by_status || [];
  const poByStatus = reports?.purchase_orders_by_status || [];
  const topSuppliers = reports?.top_suppliers || [];
  const monthlyTrend = reports?.monthly_trend || [];

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Procurement Reports</h1>
          <p className="text-muted-foreground">Comprehensive procurement analytics and insights</p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExport}>
            <Download className="w-4 h-4 mr-2" />
            Export
          </Button>
          <Button variant="outline" onClick={loadReports}>
            <RefreshCw className="w-4 h-4 mr-2" />
            Refresh
          </Button>
        </div>
      </div>

      {/* Date Range Filter */}
      <Card>
        <CardHeader>
          <CardTitle>Date Range</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4">
            <div className="flex-1">
              <Label>From Date</Label>
              <Input
                type="date"
                value={dateFrom}
                onChange={(e) => setDateFrom(e.target.value)}
              />
            </div>
            <div className="flex-1">
              <Label>To Date</Label>
              <Input
                type="date"
                value={dateTo}
                onChange={(e) => setDateTo(e.target.value)}
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Summary Statistics */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Requisitions</CardTitle>
            <FileText className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatNumber(summary.total_requisitions)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.approved_requisitions)} approved
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Purchase Orders</CardTitle>
            <ShoppingCart className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatNumber(summary.total_purchase_orders)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.completed_orders)} completed
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total PO Value</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatCurrency(summary.total_po_value)}</div>
            <p className="text-xs text-muted-foreground">
              {formatCurrency(summary.completed_po_value)} completed
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Suppliers</CardTitle>
            <Building2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatNumber(summary.total_suppliers)}</div>
            <p className="text-xs text-muted-foreground">
              {formatNumber(summary.total_goods_receipts)} goods receipts
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Detailed Reports */}
      <Tabs defaultValue="overview" className="space-y-4">
        <TabsList>
          <TabsTrigger value="overview">Overview</TabsTrigger>
          <TabsTrigger value="requisitions">Requisitions</TabsTrigger>
          <TabsTrigger value="purchase-orders">Purchase Orders</TabsTrigger>
          <TabsTrigger value="suppliers">Top Suppliers</TabsTrigger>
          <TabsTrigger value="trends">Monthly Trends</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="space-y-4">
          <div className="grid gap-4 md:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle>Requisitions by Status</CardTitle>
              </CardHeader>
              <CardContent>
                {requisitionsByStatus.length === 0 ? (
                  <p className="text-muted-foreground text-center py-4">No data available</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Status</TableHead>
                        <TableHead>Count</TableHead>
                        <TableHead className="text-right">Total Amount</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {requisitionsByStatus.map((item) => (
                        <TableRow key={item.status}>
                          <TableCell>
                            <Badge variant="secondary">{item.status}</Badge>
                          </TableCell>
                          <TableCell>{formatNumber(item.count)}</TableCell>
                          <TableCell className="text-right">
                            {formatCurrency(item.total_amount)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Purchase Orders by Status</CardTitle>
              </CardHeader>
              <CardContent>
                {poByStatus.length === 0 ? (
                  <p className="text-muted-foreground text-center py-4">No data available</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Status</TableHead>
                        <TableHead>Count</TableHead>
                        <TableHead className="text-right">Total Amount</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {poByStatus.map((item) => (
                        <TableRow key={item.status}>
                          <TableCell>
                            <Badge variant="secondary">{item.status}</Badge>
                          </TableCell>
                          <TableCell>{formatNumber(item.count)}</TableCell>
                          <TableCell className="text-right">
                            {formatCurrency(item.total_amount)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        <TabsContent value="requisitions">
          <Card>
            <CardHeader>
              <CardTitle>Requisitions Analysis</CardTitle>
              <CardDescription>Breakdown of purchase requisitions by status</CardDescription>
            </CardHeader>
            <CardContent>
              {requisitionsByStatus.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No requisitions data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Status</TableHead>
                      <TableHead>Count</TableHead>
                      <TableHead className="text-right">Total Amount</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {requisitionsByStatus.map((item) => (
                      <TableRow key={item.status}>
                        <TableCell>
                          <Badge variant="secondary">{item.status}</Badge>
                        </TableCell>
                        <TableCell>{formatNumber(item.count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_amount)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="purchase-orders">
          <Card>
            <CardHeader>
              <CardTitle>Purchase Orders Analysis</CardTitle>
              <CardDescription>Breakdown of purchase orders by status</CardDescription>
            </CardHeader>
            <CardContent>
              {poByStatus.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No purchase orders data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Status</TableHead>
                      <TableHead>Count</TableHead>
                      <TableHead className="text-right">Total Amount</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {poByStatus.map((item) => (
                      <TableRow key={item.status}>
                        <TableCell>
                          <Badge variant="secondary">{item.status}</Badge>
                        </TableCell>
                        <TableCell>{formatNumber(item.count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(item.total_amount)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="suppliers">
          <Card>
            <CardHeader>
              <CardTitle>Top Suppliers</CardTitle>
              <CardDescription>Suppliers ranked by order value</CardDescription>
            </CardHeader>
            <CardContent>
              {topSuppliers.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No supplier data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Supplier</TableHead>
                      <TableHead>Code</TableHead>
                      <TableHead>Orders</TableHead>
                      <TableHead>Completed</TableHead>
                      <TableHead className="text-right">Total Value</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {topSuppliers.map((supplier) => (
                      <TableRow key={supplier.id}>
                        <TableCell className="font-medium">{supplier.name}</TableCell>
                        <TableCell>{supplier.code}</TableCell>
                        <TableCell>{formatNumber(supplier.order_count)}</TableCell>
                        <TableCell>{formatNumber(supplier.completed_orders)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(supplier.total_order_value)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        <TabsContent value="trends">
          <Card>
            <CardHeader>
              <CardTitle>Monthly Trends</CardTitle>
              <CardDescription>Purchase order trends over time</CardDescription>
            </CardHeader>
            <CardContent>
              {monthlyTrend.length === 0 ? (
                <p className="text-muted-foreground text-center py-8">No trend data available</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Month</TableHead>
                      <TableHead>Order Count</TableHead>
                      <TableHead className="text-right">Total Amount</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {monthlyTrend.map((trend, index) => (
                      <TableRow key={index}>
                        <TableCell>
                          {new Date(trend.month).toLocaleDateString('en-US', {
                            month: 'long',
                            year: 'numeric',
                          })}
                        </TableCell>
                        <TableCell>{formatNumber(trend.order_count)}</TableCell>
                        <TableCell className="text-right">
                          {formatCurrency(trend.total_amount)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>
    </div>
  );
}

/**
 * Procurement Requisitions Page
 * Purchase requisition management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  FileText,
  Plus,
  Search,
  Loader2,
  Edit,
  Eye,
  CheckCircle2,
  Clock,
  XCircle,
  AlertCircle,
  MoreVertical,
  DollarSign,
  Calendar,
  User,
} from 'lucide-react';
import {
  getPurchaseRequisitions,
  createPurchaseRequisition,
  type PurchaseRequisition,
} from '@/services/api/procurement';
import {
  getProducts,
  type Product,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface RequisitionItem {
  product_id?: string;
  description: string;
  quantity: number;
  unit_price?: number;
  unit_of_measure: string;
  notes?: string;
}

export default function ProcurementRequisitions() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Requisitions
  const [requisitions, setRequisitions] = useState<PurchaseRequisition[]>([]);
  const [filteredRequisitions, setFilteredRequisitions] = useState<PurchaseRequisition[]>([]);
  const [selectedRequisition, setSelectedRequisition] = useState<PurchaseRequisition | null>(null);
  const [showRequisitionDialog, setShowRequisitionDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Products
  const [products, setProducts] = useState<Product[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');

  // Requisition form
  const [requisitionForm, setRequisitionForm] = useState({
    department_id: '',
    priority: 'normal' as 'low' | 'normal' | 'high' | 'urgent',
    required_date: '',
    notes: '',
    items: [] as RequisitionItem[],
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchRequisitions(),
          fetchProducts(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading requisitions data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load requisitions',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = requisitions;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(req =>
        req.requisition_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requested_by_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        req.requested_by_email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(req => req.status === statusFilter);
    }

    // Priority filter
    if (priorityFilter !== 'all') {
      filtered = filtered.filter(req => req.priority === priorityFilter);
    }

    setFilteredRequisitions(filtered);
  }, [requisitions, searchTerm, statusFilter, priorityFilter]);

  const fetchRequisitions = async () => {
    try {
      setLoading(true);
      const data = await getPurchaseRequisitions();
      setRequisitions(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch requisitions',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const data = await getProducts({ is_active: true });
      setProducts(data || []);
    } catch (error: unknown) {
      console.error('Error fetching products:', error);
    }
  };

  const handleCreateRequisition = async () => {
    try {
      if (requisitionForm.items.length === 0) {
        toast({
          title: 'Validation Error',
          description: 'Please add at least one item to the requisition',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      await createPurchaseRequisition({
        department_id: requisitionForm.department_id || undefined,
        priority: requisitionForm.priority,
        required_date: requisitionForm.required_date || undefined,
        notes: requisitionForm.notes || undefined,
        items: requisitionForm.items.map(item => ({
          product_id: item.product_id,
          description: item.description,
          quantity: item.quantity,
          unit_price: item.unit_price,
          unit_of_measure: item.unit_of_measure || 'pcs',
          notes: item.notes,
        })),
      });

      toast({
        title: 'Success',
        description: 'Purchase requisition created successfully',
      });

      setShowRequisitionDialog(false);
      resetForm();
      fetchRequisitions();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create requisition',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewRequisition = (requisition: PurchaseRequisition) => {
    setSelectedRequisition(requisition);
    setShowViewDialog(true);
  };

  const addItem = () => {
    setRequisitionForm({
      ...requisitionForm,
      items: [
        ...requisitionForm.items,
        {
          description: '',
          quantity: 1,
          unit_price: 0,
          unit_of_measure: 'pcs',
        },
      ],
    });
  };

  const removeItem = (index: number) => {
    setRequisitionForm({
      ...requisitionForm,
      items: requisitionForm.items.filter((_, i) => i !== index),
    });
  };

  const updateItem = (index: number, field: keyof RequisitionItem, value: unknown) => {
    const updatedItems = [...requisitionForm.items];
    updatedItems[index] = {
      ...updatedItems[index],
      [field]: value,
    };
    setRequisitionForm({ ...requisitionForm, items: updatedItems });
  };

  const calculateTotal = () => {
    return requisitionForm.items.reduce((sum, item) => {
      const qty = typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0));
      const price = typeof item.unit_price === 'number' ? item.unit_price : parseFloat(String(item.unit_price || 0));
      return sum + (qty * price);
    }, 0);
  };

  const resetForm = () => {
    setRequisitionForm({
      department_id: '',
      priority: 'normal',
      required_date: '',
      notes: '',
      items: [],
    });
    setSelectedRequisition(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowRequisitionDialog(true);
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; icon: unknown; label: string }> = {
      draft: { variant: 'secondary', icon: FileText, label: 'Draft' },
      pending: { variant: 'outline', icon: Clock, label: 'Pending' },
      approved: { variant: 'default', icon: CheckCircle2, label: 'Approved' },
      rejected: { variant: 'destructive', icon: XCircle, label: 'Rejected' },
      cancelled: { variant: 'secondary', icon: XCircle, label: 'Cancelled' },
    };

    const config = statusConfig[status] || { variant: 'secondary', icon: FileText, label: status };
    const Icon = config.icon;
    return (
      <Badge variant={config.variant}>
        <Icon className="h-3 w-3 mr-1" />
        {config.label}
      </Badge>
    );
  };

  const getPriorityBadge = (priority: string) => {
    const priorityConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; label: string }> = {
      low: { variant: 'secondary', label: 'Low' },
      normal: { variant: 'outline', label: 'Normal' },
      high: { variant: 'default', label: 'High' },
      urgent: { variant: 'destructive', label: 'Urgent' },
    };

    const config = priorityConfig[priority] || { variant: 'secondary', label: priority };
    return <Badge variant={config.variant}>{config.label}</Badge>;
  };

  // Calculate statistics
  const totalRequisitions = requisitions.length;
  const pendingRequisitions = requisitions.filter(req => req.status === 'pending').length;
  const approvedRequisitions = requisitions.filter(req => req.status === 'approved').length;
  const totalValue = requisitions.reduce((sum, req) => {
    const amount = typeof req.total_amount === 'number' ? req.total_amount : parseFloat(String(req.total_amount || 0));
    return sum + (isNaN(amount) ? 0 : amount);
  }, 0);

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Purchase Requisitions</h1>
          <p className="text-muted-foreground mt-1">
            Manage purchase requisitions and approval workflow
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create Requisition
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Requisitions</CardTitle>
            <FileText className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalRequisitions}</div>
            <p className="text-xs text-muted-foreground">
              All requisitions
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Pending</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{pendingRequisitions}</div>
            <p className="text-xs text-muted-foreground">
              Awaiting approval
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Approved</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{approvedRequisitions}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <DollarSign className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">
              {totalValue.toLocaleString('en-IN', { style: 'currency', currency: 'INR' })}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search requisitions..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="pending">Pending</SelectItem>
                  <SelectItem value="approved">Approved</SelectItem>
                  <SelectItem value="rejected">Rejected</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Priority</Label>
              <Select value={priorityFilter} onValueChange={setPriorityFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All priorities" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Priorities</SelectItem>
                  <SelectItem value="low">Low</SelectItem>
                  <SelectItem value="normal">Normal</SelectItem>
                  <SelectItem value="high">High</SelectItem>
                  <SelectItem value="urgent">Urgent</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Requisitions Table */}
      <Card>
        <CardHeader>
          <CardTitle>Requisitions ({filteredRequisitions.length})</CardTitle>
          <CardDescription>
            Manage your purchase requisitions
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredRequisitions.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredRequisitions.length === 0 ? (
            <Alert>
              <AlertDescription>
                No requisitions found. {searchTerm || statusFilter !== 'all' || priorityFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first requisition to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Requisition #</TableHead>
                    <TableHead>Requested By</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Required Date</TableHead>
                    <TableHead className="text-right">Total Amount</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredRequisitions.map((requisition) => (
                    <TableRow key={requisition.id}>
                      <TableCell className="font-mono font-medium">{requisition.requisition_number}</TableCell>
                      <TableCell>
                        <div className="flex items-center">
                          <User className="h-4 w-4 mr-2 text-muted-foreground" />
                          {requisition.requested_by_name || requisition.requested_by_email || 'N/A'}
                        </div>
                      </TableCell>
                      <TableCell>{getPriorityBadge(requisition.priority)}</TableCell>
                      <TableCell>
                        {requisition.required_date
                          ? new Date(requisition.required_date).toLocaleDateString()
                          : '-'}
                      </TableCell>
                      <TableCell className="text-right font-medium">
                        {(typeof requisition.total_amount === 'number' ? requisition.total_amount : parseFloat(String(requisition.total_amount || 0))).toLocaleString('en-IN', {
                          style: 'currency',
                          currency: 'INR',
                        })}
                      </TableCell>
                      <TableCell>{getStatusBadge(requisition.status)}</TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewRequisition(requisition)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            {requisition.status === 'draft' && (
                              <DropdownMenuItem>
                                <Edit className="mr-2 h-4 w-4" />
                                Edit
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create Requisition Dialog */}
      <Dialog open={showRequisitionDialog} onOpenChange={setShowRequisitionDialog}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Requisition' : 'Create Purchase Requisition'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update requisition information' : 'Create a new purchase requisition'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="priority">Priority</Label>
                <Select
                  value={requisitionForm.priority}
                  onValueChange={(value: 'low' | 'normal' | 'high' | 'urgent') =>
                    setRequisitionForm({ ...requisitionForm, priority: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="low">Low</SelectItem>
                    <SelectItem value="normal">Normal</SelectItem>
                    <SelectItem value="high">High</SelectItem>
                    <SelectItem value="urgent">Urgent</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="required_date">Required Date</Label>
                <Input
                  id="required_date"
                  type="date"
                  value={requisitionForm.required_date}
                  onChange={(e) => setRequisitionForm({ ...requisitionForm, required_date: e.target.value })}
                />
              </div>
            </div>

            {/* Items Section */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Items</Label>
                <Button type="button" variant="outline" size="sm" onClick={addItem}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Item
                </Button>
              </div>
              {requisitionForm.items.length === 0 ? (
                <Alert>
                  <AlertDescription>No items added. Click "Add Item" to add items to this requisition.</AlertDescription>
                </Alert>
              ) : (
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Product</TableHead>
                        <TableHead>Description</TableHead>
                        <TableHead>Quantity</TableHead>
                        <TableHead>Unit Price</TableHead>
                        <TableHead>Unit</TableHead>
                        <TableHead className="text-right">Total</TableHead>
                        <TableHead></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {requisitionForm.items.map((item, index) => (
                        <TableRow key={index}>
                          <TableCell>
                            <Select
                              value={item.product_id || ''}
                              onValueChange={(value) => {
                                const product = products.find(p => p.id === value);
                                updateItem(index, 'product_id', value);
                                if (product) {
                                  updateItem(index, 'description', product.name);
                                }
                              }}
                            >
                              <SelectTrigger className="w-48">
                                <SelectValue placeholder="Select product" />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="">None</SelectItem>
                                {products.map((product) => (
                                  <SelectItem key={product.id} value={product.id}>
                                    {product.name} ({product.sku})
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.description}
                              onChange={(e) => updateItem(index, 'description', e.target.value)}
                              placeholder="Item description"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              min="1"
                              value={item.quantity}
                              onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              step="0.01"
                              value={item.unit_price || ''}
                              onChange={(e) => updateItem(index, 'unit_price', parseFloat(e.target.value) || 0)}
                              className="w-24"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.unit_of_measure}
                              onChange={(e) => updateItem(index, 'unit_of_measure', e.target.value)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell className="text-right font-medium">
                            {((typeof item.quantity === 'number' ? item.quantity : parseFloat(String(item.quantity || 0))) *
                              (typeof item.unit_price === 'number' ? item.unit_price : parseFloat(String(item.unit_price || 0)))).toLocaleString('en-IN', {
                              style: 'currency',
                              currency: 'INR',
                            })}
                          </TableCell>
                          <TableCell>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => removeItem(index)}
                            >
                              <XCircle className="h-4 w-4" />
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </div>

            {/* Total */}
            <div className="flex justify-end border-t pt-4">
              <div className="flex items-center gap-4">
                <span className="text-sm font-medium">Total:</span>
                <span className="text-lg font-bold">
                  {calculateTotal().toLocaleString('en-IN', {
                    style: 'currency',
                    currency: 'INR',
                  })}
                </span>
              </div>
            </div>

            <div className="grid gap-2">
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={requisitionForm.notes}
                onChange={(e) => setRequisitionForm({ ...requisitionForm, notes: e.target.value })}
                placeholder="Additional notes about this requisition"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRequisitionDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateRequisition} disabled={loading || requisitionForm.items.length === 0}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Requisition
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Requisition Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Requisition Details</DialogTitle>
            <DialogDescription>
              View complete requisition information
            </DialogDescription>
          </DialogHeader>
          {selectedRequisition && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Requisition Number</Label>
                  <p className="font-mono">{selectedRequisition.requisition_number}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Status</Label>
                  {getStatusBadge(selectedRequisition.status)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Priority</Label>
                  {getPriorityBadge(selectedRequisition.priority)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Requested By</Label>
                  <div className="flex items-center">
                    <User className="h-4 w-4 mr-2 text-muted-foreground" />
                    <p>{selectedRequisition.requested_by_name || selectedRequisition.requested_by_email || 'N/A'}</p>
                  </div>
                </div>
                {selectedRequisition.required_date && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Required Date</Label>
                    <div className="flex items-center">
                      <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                      <p>{new Date(selectedRequisition.required_date).toLocaleDateString()}</p>
                    </div>
                  </div>
                )}
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Total Amount</Label>
                  <p className="font-bold text-lg">
                    {(typeof selectedRequisition.total_amount === 'number' ? selectedRequisition.total_amount : parseFloat(String(selectedRequisition.total_amount || 0))).toLocaleString('en-IN', {
                      style: 'currency',
                      currency: 'INR',
                    })}
                  </p>
                </div>
              </div>
              {selectedRequisition.notes && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Notes</Label>
                  <p className="text-sm text-muted-foreground">{selectedRequisition.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Procurement RFQ/RFP Page
 * Request for Quotation/Proposal management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  FileSearch,
  Plus,
  Search,
  Loader2,
  Edit,
  Eye,
  CheckCircle2,
  Clock,
  XCircle,
  MoreVertical,
  Calendar,
  DollarSign,
  AlertCircle,
} from 'lucide-react';
import {
  getRfqRfp,
  createRfqRfp,
  type RfqRfp,
} from '@/services/api/procurement';
import {
  getProducts,
  type Product,
} from '@/services/api/inventory';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';

interface RfqItem {
  product_id?: string;
  description: string;
  quantity: number;
  unit_of_measure: string;
  specifications?: string;
}

export default function ProcurementRFQ() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // RFQ/RFP
  const [rfqs, setRfqs] = useState<RfqRfp[]>([]);
  const [filteredRfqs, setFilteredRfqs] = useState<RfqRfp[]>([]);
  const [selectedRfq, setSelectedRfq] = useState<RfqRfp | null>(null);
  const [showRfqDialog, setShowRfqDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Products
  const [products, setProducts] = useState<Product[]>([]);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [typeFilter, setTypeFilter] = useState<string>('all');

  // RFQ form
  const [rfqForm, setRfqForm] = useState({
    title: '',
    description: '',
    type: 'RFQ' as 'RFQ' | 'RFP',
    status: 'draft',
    published_date: '',
    closing_date: '',
    currency: 'INR',
    terms_conditions: '',
    items: [] as RfqItem[],
  });

  // Fetch data
  useEffect(() => {
    const loadData = async () => {
      try {
        setInitialLoad(true);
        await Promise.all([
          fetchRfqs(),
          fetchProducts(),
        ]);
      } catch (error: unknown) {
        console.error('Error loading RFQ data:', error);
        toast({
          title: 'Error',
          description: error.message || 'Failed to load RFQ/RFP',
          variant: 'destructive',
        });
      } finally {
        setInitialLoad(false);
      }
    };
    loadData();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = rfqs;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(rfq =>
        rfq.rfq_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
        rfq.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        rfq.description?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(rfq => rfq.status === statusFilter);
    }

    // Type filter
    if (typeFilter !== 'all') {
      filtered = filtered.filter(rfq => rfq.type === typeFilter);
    }

    setFilteredRfqs(filtered);
  }, [rfqs, searchTerm, statusFilter, typeFilter]);

  const fetchRfqs = async () => {
    try {
      setLoading(true);
      const data = await getRfqRfp();
      setRfqs(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch RFQ/RFP',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchProducts = async () => {
    try {
      const data = await getProducts({ is_active: true });
      setProducts(data || []);
    } catch (error: unknown) {
      console.error('Error fetching products:', error);
    }
  };

  const handleCreateRfq = async () => {
    try {
      if (!rfqForm.title) {
        toast({
          title: 'Validation Error',
          description: 'Please provide a title for the RFQ/RFP',
          variant: 'destructive',
        });
        return;
      }

      setLoading(true);
      await createRfqRfp({
        title: rfqForm.title,
        description: rfqForm.description || undefined,
        type: rfqForm.type,
        status: rfqForm.status,
        published_date: rfqForm.published_date || undefined,
        closing_date: rfqForm.closing_date || undefined,
        currency: rfqForm.currency,
        terms_conditions: rfqForm.terms_conditions || undefined,
        items: rfqForm.items.map(item => ({
          product_id: item.product_id,
          description: item.description,
          quantity: item.quantity,
          unit_of_measure: item.unit_of_measure || 'pcs',
          specifications: item.specifications,
        })),
      });

      toast({
        title: 'Success',
        description: `${rfqForm.type} created successfully`,
      });

      setShowRfqDialog(false);
      resetForm();
      fetchRfqs();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to create RFQ/RFP',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleViewRfq = (rfq: RfqRfp) => {
    setSelectedRfq(rfq);
    setShowViewDialog(true);
  };

  const addItem = () => {
    setRfqForm({
      ...rfqForm,
      items: [
        ...rfqForm.items,
        {
          description: '',
          quantity: 1,
          unit_of_measure: 'pcs',
        },
      ],
    });
  };

  const removeItem = (index: number) => {
    setRfqForm({
      ...rfqForm,
      items: rfqForm.items.filter((_, i) => i !== index),
    });
  };

  const updateItem = (index: number, field: keyof RfqItem, value: unknown) => {
    const updatedItems = [...rfqForm.items];
    updatedItems[index] = {
      ...updatedItems[index],
      [field]: value,
    };
    setRfqForm({ ...rfqForm, items: updatedItems });
  };

  const resetForm = () => {
    setRfqForm({
      title: '',
      description: '',
      type: 'RFQ',
      status: 'draft',
      published_date: '',
      closing_date: '',
      currency: 'INR',
      terms_conditions: '',
      items: [],
    });
    setSelectedRfq(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowRfqDialog(true);
  };

  const getStatusBadge = (status: string) => {
    const statusConfig: Record<string, { variant: 'default' | 'secondary' | 'outline' | 'destructive'; icon: unknown; label: string }> = {
      draft: { variant: 'secondary', icon: FileSearch, label: 'Draft' },
      published: { variant: 'default', icon: CheckCircle2, label: 'Published' },
      closed: { variant: 'outline', icon: XCircle, label: 'Closed' },
      cancelled: { variant: 'destructive', icon: XCircle, label: 'Cancelled' },
    };

    const config = statusConfig[status] || { variant: 'secondary', icon: FileSearch, label: status };
    const Icon = config.icon;
    return (
      <Badge variant={config.variant}>
        <Icon className="h-3 w-3 mr-1" />
        {config.label}
      </Badge>
    );
  };

  // Calculate statistics
  const totalRfqs = rfqs.length;
  const rfqCount = rfqs.filter(rfq => rfq.type === 'RFQ').length;
  const rfpCount = rfqs.filter(rfq => rfq.type === 'RFP').length;
  const publishedCount = rfqs.filter(rfq => rfq.status === 'published').length;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">RFQ / RFP Management</h1>
          <p className="text-muted-foreground mt-1">
            Manage Request for Quotation and Request for Proposal
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Create RFQ/RFP
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total RFQ/RFP</CardTitle>
            <FileSearch className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{totalRfqs}</div>
            <p className="text-xs text-muted-foreground">
              All requests
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">RFQ</CardTitle>
            <FileSearch className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{rfqCount}</div>
            <p className="text-xs text-muted-foreground">
              Quotations
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">RFP</CardTitle>
            <FileSearch className="h-4 w-4 text-purple-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{rfpCount}</div>
            <p className="text-xs text-muted-foreground">
              Proposals
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Published</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{publishedCount}</div>
            <p className="text-xs text-muted-foreground">
              Active requests
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search RFQ/RFP..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={typeFilter} onValueChange={setTypeFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All types" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="RFQ">RFQ</SelectItem>
                  <SelectItem value="RFP">RFP</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="draft">Draft</SelectItem>
                  <SelectItem value="published">Published</SelectItem>
                  <SelectItem value="closed">Closed</SelectItem>
                  <SelectItem value="cancelled">Cancelled</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* RFQ/RFP Table */}
      <Card>
        <CardHeader>
          <CardTitle>RFQ / RFP ({filteredRfqs.length})</CardTitle>
          <CardDescription>
            Manage your request for quotations and proposals
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredRfqs.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredRfqs.length === 0 ? (
            <Alert>
              <AlertDescription>
                No RFQ/RFP found. {searchTerm || statusFilter !== 'all' || typeFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first RFQ/RFP to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>RFQ/RFP Number</TableHead>
                    <TableHead>Title</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Published Date</TableHead>
                    <TableHead>Closing Date</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredRfqs.map((rfq) => (
                    <TableRow key={rfq.id}>
                      <TableCell className="font-mono font-medium">{rfq.rfq_number}</TableCell>
                      <TableCell className="font-medium">{rfq.title}</TableCell>
                      <TableCell>
                        <Badge variant={rfq.type === 'RFQ' ? 'default' : 'outline'}>
                          {rfq.type}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        {rfq.published_date
                          ? new Date(rfq.published_date).toLocaleDateString()
                          : '-'}
                      </TableCell>
                      <TableCell>
                        {rfq.closing_date
                          ? new Date(rfq.closing_date).toLocaleDateString()
                          : '-'}
                      </TableCell>
                      <TableCell>{getStatusBadge(rfq.status)}</TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewRfq(rfq)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            {rfq.status === 'draft' && (
                              <DropdownMenuItem>
                                <Edit className="mr-2 h-4 w-4" />
                                Edit
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create RFQ/RFP Dialog */}
      <Dialog open={showRfqDialog} onOpenChange={setShowRfqDialog}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit RFQ/RFP' : 'Create RFQ/RFP'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update RFQ/RFP information' : 'Create a new Request for Quotation or Proposal'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="type">Type *</Label>
                <Select
                  value={rfqForm.type}
                  onValueChange={(value: 'RFQ' | 'RFP') =>
                    setRfqForm({ ...rfqForm, type: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="RFQ">RFQ (Request for Quotation)</SelectItem>
                    <SelectItem value="RFP">RFP (Request for Proposal)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="grid gap-2">
                <Label htmlFor="status">Status</Label>
                <Select
                  value={rfqForm.status}
                  onValueChange={(value) => setRfqForm({ ...rfqForm, status: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">Draft</SelectItem>
                    <SelectItem value="published">Published</SelectItem>
                    <SelectItem value="closed">Closed</SelectItem>
                    <SelectItem value="cancelled">Cancelled</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="title">Title *</Label>
              <Input
                id="title"
                value={rfqForm.title}
                onChange={(e) => setRfqForm({ ...rfqForm, title: e.target.value })}
                placeholder="Enter RFQ/RFP title"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={rfqForm.description}
                onChange={(e) => setRfqForm({ ...rfqForm, description: e.target.value })}
                placeholder="Detailed description of requirements"
                rows={4}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="published_date">Published Date</Label>
                <Input
                  id="published_date"
                  type="date"
                  value={rfqForm.published_date}
                  onChange={(e) => setRfqForm({ ...rfqForm, published_date: e.target.value })}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="closing_date">Closing Date</Label>
                <Input
                  id="closing_date"
                  type="date"
                  value={rfqForm.closing_date}
                  onChange={(e) => setRfqForm({ ...rfqForm, closing_date: e.target.value })}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="currency">Currency</Label>
                <Select
                  value={rfqForm.currency}
                  onValueChange={(value) => setRfqForm({ ...rfqForm, currency: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="INR">INR</SelectItem>
                    <SelectItem value="USD">USD</SelectItem>
                    <SelectItem value="EUR">EUR</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Items Section */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label>Items / Requirements</Label>
                <Button type="button" variant="outline" size="sm" onClick={addItem}>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Item
                </Button>
              </div>
              {rfqForm.items.length === 0 ? (
                <Alert>
                  <AlertDescription>No items added. Click "Add Item" to add requirements to this RFQ/RFP.</AlertDescription>
                </Alert>
              ) : (
                <div className="rounded-md border">
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>Product</TableHead>
                        <TableHead>Description</TableHead>
                        <TableHead>Quantity</TableHead>
                        <TableHead>Unit</TableHead>
                        <TableHead>Specifications</TableHead>
                        <TableHead></TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {rfqForm.items.map((item, index) => (
                        <TableRow key={index}>
                          <TableCell>
                            <Select
                              value={item.product_id || ''}
                              onValueChange={(value) => {
                                const product = products.find(p => p.id === value);
                                updateItem(index, 'product_id', value);
                                if (product) {
                                  updateItem(index, 'description', product.name);
                                }
                              }}
                            >
                              <SelectTrigger className="w-48">
                                <SelectValue placeholder="Select product" />
                              </SelectTrigger>
                              <SelectContent>
                                <SelectItem value="">None</SelectItem>
                                {products.map((product) => (
                                  <SelectItem key={product.id} value={product.id}>
                                    {product.name} ({product.sku})
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.description}
                              onChange={(e) => updateItem(index, 'description', e.target.value)}
                              placeholder="Item description"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              type="number"
                              min="1"
                              value={item.quantity}
                              onChange={(e) => updateItem(index, 'quantity', parseFloat(e.target.value) || 0)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.unit_of_measure}
                              onChange={(e) => updateItem(index, 'unit_of_measure', e.target.value)}
                              className="w-20"
                            />
                          </TableCell>
                          <TableCell>
                            <Input
                              value={item.specifications || ''}
                              onChange={(e) => updateItem(index, 'specifications', e.target.value)}
                              placeholder="Specifications"
                            />
                          </TableCell>
                          <TableCell>
                            <Button
                              type="button"
                              variant="ghost"
                              size="sm"
                              onClick={() => removeItem(index)}
                            >
                              <XCircle className="h-4 w-4" />
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </div>
              )}
            </div>

            <div className="grid gap-2">
              <Label htmlFor="terms_conditions">Terms & Conditions</Label>
              <Textarea
                id="terms_conditions"
                value={rfqForm.terms_conditions}
                onChange={(e) => setRfqForm({ ...rfqForm, terms_conditions: e.target.value })}
                placeholder="Terms and conditions for vendors"
                rows={4}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowRfqDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateRfq} disabled={loading || !rfqForm.title}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} {rfqForm.type}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View RFQ/RFP Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>RFQ/RFP Details</DialogTitle>
            <DialogDescription>
              View complete RFQ/RFP information
            </DialogDescription>
          </DialogHeader>
          {selectedRfq && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-4 md:grid-cols-2">
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">RFQ/RFP Number</Label>
                  <p className="font-mono">{selectedRfq.rfq_number}</p>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Type</Label>
                  <Badge variant={selectedRfq.type === 'RFQ' ? 'default' : 'outline'}>
                    {selectedRfq.type}
                  </Badge>
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Status</Label>
                  {getStatusBadge(selectedRfq.status)}
                </div>
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Currency</Label>
                  <p>{selectedRfq.currency}</p>
                </div>
                {selectedRfq.published_date && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Published Date</Label>
                    <div className="flex items-center">
                      <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                      <p>{new Date(selectedRfq.published_date).toLocaleDateString()}</p>
                    </div>
                  </div>
                )}
                {selectedRfq.closing_date && (
                  <div className="grid gap-2">
                    <Label className="text-sm font-medium">Closing Date</Label>
                    <div className="flex items-center">
                      <Calendar className="h-4 w-4 mr-2 text-muted-foreground" />
                      <p>{new Date(selectedRfq.closing_date).toLocaleDateString()}</p>
                    </div>
                  </div>
                )}
              </div>
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Title</Label>
                <p className="font-medium">{selectedRfq.title}</p>
              </div>
              {selectedRfq.description && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Description</Label>
                  <p className="text-sm text-muted-foreground">{selectedRfq.description}</p>
                </div>
              )}
              {selectedRfq.terms_conditions && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Terms & Conditions</Label>
                  <p className="text-sm text-muted-foreground">{selectedRfq.terms_conditions}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Procurement Settings Page
 * Configure procurement module settings and preferences
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Settings,
  Save,
  Loader2,
  ShoppingCart,
  AlertTriangle,
  DollarSign,
  FileText,
  CheckCircle2,
} from 'lucide-react';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

interface ProcurementSettings {
  // Approval Settings
  require_approval_for_po: boolean;
  require_approval_for_requisition: boolean;
  auto_approve_below_amount: number;
  
  // Defaults
  default_currency: string;
  default_payment_terms: string;
  default_delivery_terms: string;
  
  // Workflow
  auto_create_po_from_requisition: boolean;
  auto_receive_goods: boolean;
  
  // Notifications
  notify_on_po_created: boolean;
  notify_on_po_approved: boolean;
  notify_on_po_received: boolean;
  notify_on_requisition_created: boolean;
  notify_on_requisition_approved: boolean;
  
  // RFQ Settings
  enable_rfq: boolean;
  rfq_validity_days: number;
  require_multiple_quotes: boolean;
}

export default function ProcurementSettings() {
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<ProcurementSettings>({
    require_approval_for_po: true,
    require_approval_for_requisition: true,
    auto_approve_below_amount: 10000,
    default_currency: 'INR',
    default_payment_terms: 'Net 30',
    default_delivery_terms: 'FOB',
    auto_create_po_from_requisition: false,
    auto_receive_goods: false,
    notify_on_po_created: true,
    notify_on_po_approved: true,
    notify_on_po_received: true,
    notify_on_requisition_created: true,
    notify_on_requisition_approved: true,
    enable_rfq: true,
    rfq_validity_days: 30,
    require_multiple_quotes: false,
  });

  useEffect(() => {
    loadSettings();
  }, []);

  const loadSettings = async () => {
    try {
      setLoading(true);
      const { getProcurementSettings } = await import('@/services/api/system');
      const data = await getProcurementSettings();
      setSettings(data);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load settings',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      const { updateProcurementSettings } = await import('@/services/api/system');
      await updateProcurementSettings(settings);
      toast({
        title: 'Success',
        description: 'Settings saved successfully',
      });
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save settings',
        variant: 'destructive',
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Procurement Settings</h1>
          <p className="text-muted-foreground">Configure procurement module preferences and defaults</p>
        </div>
        <Button onClick={handleSave} disabled={saving}>
          {saving ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="w-4 h-4 mr-2" />
              Save Settings
            </>
          )}
        </Button>
      </div>

      <div className="grid gap-6 md:grid-cols-2">
        {/* Approval Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <CheckCircle2 className="w-5 h-5" />
              Approval Settings
            </CardTitle>
            <CardDescription>Configure approval requirements</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Require Approval for PO</Label>
                <p className="text-sm text-muted-foreground">
                  Require approval before creating purchase orders
                </p>
              </div>
              <Switch
                checked={settings.require_approval_for_po}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, require_approval_for_po: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Require Approval for Requisition</Label>
                <p className="text-sm text-muted-foreground">
                  Require approval before creating purchase requisitions
                </p>
              </div>
              <Switch
                checked={settings.require_approval_for_requisition}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, require_approval_for_requisition: checked })
                }
              />
            </div>
            <div>
              <Label>Auto Approve Below Amount</Label>
              <Input
                type="number"
                min="0"
                value={settings.auto_approve_below_amount}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    auto_approve_below_amount: parseFloat(e.target.value) || 0,
                  })
                }
              />
              <p className="text-sm text-muted-foreground mt-1">
                Automatically approve orders below this amount
              </p>
            </div>
          </CardContent>
        </Card>

        {/* Default Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Settings className="w-5 h-5" />
              Default Settings
            </CardTitle>
            <CardDescription>Set default values for new orders</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label>Default Currency</Label>
              <Select
                value={settings.default_currency}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_currency: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="INR">INR - Indian Rupee</SelectItem>
                  <SelectItem value="USD">USD - US Dollar</SelectItem>
                  <SelectItem value="EUR">EUR - Euro</SelectItem>
                  <SelectItem value="GBP">GBP - British Pound</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Default Payment Terms</Label>
              <Select
                value={settings.default_payment_terms}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_payment_terms: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Net 15">Net 15</SelectItem>
                  <SelectItem value="Net 30">Net 30</SelectItem>
                  <SelectItem value="Net 45">Net 45</SelectItem>
                  <SelectItem value="Net 60">Net 60</SelectItem>
                  <SelectItem value="Due on Receipt">Due on Receipt</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Default Delivery Terms</Label>
              <Select
                value={settings.default_delivery_terms}
                onValueChange={(value) =>
                  setSettings({ ...settings, default_delivery_terms: value })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="FOB">FOB - Free On Board</SelectItem>
                  <SelectItem value="CIF">CIF - Cost, Insurance & Freight</SelectItem>
                  <SelectItem value="EXW">EXW - Ex Works</SelectItem>
                  <SelectItem value="DDP">DDP - Delivered Duty Paid</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </CardContent>
        </Card>

        {/* Workflow Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <FileText className="w-5 h-5" />
              Workflow Settings
            </CardTitle>
            <CardDescription>Automate procurement processes</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto Create PO from Requisition</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically create purchase orders from approved requisitions
                </p>
              </div>
              <Switch
                checked={settings.auto_create_po_from_requisition}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, auto_create_po_from_requisition: checked })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Auto Receive Goods</Label>
                <p className="text-sm text-muted-foreground">
                  Automatically receive goods when PO is marked as delivered
                </p>
              </div>
              <Switch
                checked={settings.auto_receive_goods}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, auto_receive_goods: checked })
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* RFQ Settings */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ShoppingCart className="w-5 h-5" />
              RFQ Settings
            </CardTitle>
            <CardDescription>Configure Request for Quotation settings</CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Enable RFQ</Label>
                <p className="text-sm text-muted-foreground">
                  Enable Request for Quotation functionality
                </p>
              </div>
              <Switch
                checked={settings.enable_rfq}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, enable_rfq: checked })
                }
              />
            </div>
            <div>
              <Label>RFQ Validity (Days)</Label>
              <Input
                type="number"
                min="1"
                value={settings.rfq_validity_days}
                onChange={(e) =>
                  setSettings({
                    ...settings,
                    rfq_validity_days: parseInt(e.target.value) || 30,
                  })
                }
              />
            </div>
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Require Multiple Quotes</Label>
                <p className="text-sm text-muted-foreground">
                  Require quotes from multiple suppliers
                </p>
              </div>
              <Switch
                checked={settings.require_multiple_quotes}
                onCheckedChange={(checked) =>
                  setSettings({ ...settings, require_multiple_quotes: checked })
                }
              />
            </div>
          </CardContent>
        </Card>

        {/* Notification Settings */}
        <Card className="md:col-span-2">
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              Notification Settings
            </CardTitle>
            <CardDescription>Configure when to receive notifications</CardDescription>
          </CardHeader>
          <CardContent>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>PO Created</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when PO is created
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_po_created}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_po_created: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>PO Approved</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when PO is approved
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_po_approved}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_po_approved: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>PO Received</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when goods are received
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_po_received}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_po_received: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Requisition Created</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when requisition is created
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_requisition_created}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_requisition_created: checked })
                  }
                />
              </div>
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Requisition Approved</Label>
                  <p className="text-sm text-muted-foreground">
                    Notify when requisition is approved
                  </p>
                </div>
                <Switch
                  checked={settings.notify_on_requisition_approved}
                  onCheckedChange={(checked) =>
                    setSettings({ ...settings, notify_on_requisition_approved: checked })
                  }
                />
              </div>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

/**
 * Vendor Contracts Page
 * Manage vendor contracts and agreements
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  FileText,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Calendar,
  DollarSign,
  CheckCircle2,
  XCircle,
  Clock,
  AlertTriangle,
  FileSignature,
} from 'lucide-react';
import {
  getVendorContracts,
  getVendorContractById,
  createVendorContract,
  updateVendorContract,
  deleteVendorContract,
  getSuppliers,
  type VendorContract,
  type Supplier,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function ProcurementVendorContracts() {
  const { toast } = useToast();
  const [contracts, setContracts] = useState<VendorContract[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [filterType, setFilterType] = useState<string>('all');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedContract, setSelectedContract] = useState<VendorContract | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<VendorContract>>({
    supplier_id: '',
    title: '',
    contract_type: '',
    start_date: '',
    end_date: '',
    value: undefined,
    currency: 'INR',
    terms_conditions: '',
    renewal_terms: '',
    status: 'draft',
    signed_date: '',
    document_url: '',
    notes: '',
  });

  useEffect(() => {
    loadData();
    loadSuppliers();
  }, [filterStatus, filterType]);

  const loadData = async () => {
    try {
      setLoading(true);
      const filters: unknown = {};
      if (filterStatus !== 'all') filters.status = filterStatus;
      if (filterType !== 'all') filters.contract_type = filterType;

      const data = await getVendorContracts(filters);
      let filteredData = data;

      if (searchTerm) {
        filteredData = data.filter(
          (contract) =>
            contract.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
            contract.contract_number.toLowerCase().includes(searchTerm.toLowerCase()) ||
            contract.supplier_name?.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }

      setContracts(filteredData);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load vendor contracts',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const loadSuppliers = async () => {
    try {
      const data = await getSuppliers({ is_active: true });
      setSuppliers(data);
    } catch (error: unknown) {
      console.error('Failed to load suppliers:', error);
    }
  };

  const handleCreate = () => {
    setFormData({
      supplier_id: '',
      title: '',
      contract_type: '',
      start_date: '',
      end_date: '',
      value: undefined,
      currency: 'INR',
      terms_conditions: '',
      renewal_terms: '',
      status: 'draft',
      signed_date: '',
      document_url: '',
      notes: '',
    });
    setSelectedContract(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (contract: VendorContract) => {
    setFormData({
      ...contract,
    });
    setSelectedContract(contract);
    setIsDialogOpen(true);
  };

  const handleView = async (contract: VendorContract) => {
    try {
      const fullContract = await getVendorContractById(contract.id);
      setSelectedContract(fullContract);
      setIsViewDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load contract details',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async () => {
    try {
      setIsSubmitting(true);
      if (selectedContract) {
        await updateVendorContract(selectedContract.id, formData);
        toast({
          title: 'Success',
          description: 'Contract updated successfully',
        });
      } else {
        await createVendorContract(formData);
        toast({
          title: 'Success',
          description: 'Contract created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save contract',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (contract: VendorContract) => {
    if (!confirm(`Are you sure you want to delete "${contract.title}"?`)) {
      return;
    }

    try {
      await deleteVendorContract(contract.id);
      toast({
        title: 'Success',
        description: 'Contract deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete contract',
        variant: 'destructive',
      });
    }
  };

  const getStatusBadge = (status: string) => {
    const variants: Record<string, 'default' | 'secondary' | 'destructive' | 'outline'> = {
      active: 'default',
      draft: 'secondary',
      expired: 'destructive',
      terminated: 'outline',
    };
    const icons: Record<string, unknown> = {
      active: CheckCircle2,
      draft: Clock,
      expired: XCircle,
      terminated: AlertTriangle,
    };
    const Icon = icons[status] || FileText;

    return (
      <Badge variant={variants[status] || 'secondary'}>
        <Icon className="w-3 h-3 mr-1" />
        {status}
      </Badge>
    );
  };

  const formatCurrency = (value: number | undefined) => {
    if (value === undefined || value === null) return '-';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'INR',
    }).format(numValue);
  };

  // Statistics
  const stats = {
    total: contracts.length,
    active: contracts.filter((c) => c.status === 'active').length,
    expired: contracts.filter((c) => c.status === 'expired').length,
    draft: contracts.filter((c) => c.status === 'draft').length,
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Vendor Contracts</h1>
          <p className="text-muted-foreground">Manage vendor contracts and agreements</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="w-4 h-4 mr-2" />
          New Contract
        </Button>
      </div>

      {/* Statistics Cards */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Contracts</CardTitle>
            <FileSignature className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active</CardTitle>
            <CheckCircle2 className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.active}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Draft</CardTitle>
            <Clock className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.draft}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Expired</CardTitle>
            <XCircle className="h-4 w-4 text-red-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.expired}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Contracts</CardTitle>
              <CardDescription>Manage vendor contracts and agreements</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 mb-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search contracts..."
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    loadData();
                  }}
                  className="pl-8"
                />
              </div>
            </div>
            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Status</SelectItem>
                <SelectItem value="draft">Draft</SelectItem>
                <SelectItem value="active">Active</SelectItem>
                <SelectItem value="expired">Expired</SelectItem>
                <SelectItem value="terminated">Terminated</SelectItem>
              </SelectContent>
            </Select>
            <Select value={filterType} onValueChange={setFilterType}>
              <SelectTrigger className="w-[180px]">
                <SelectValue placeholder="Type" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Types</SelectItem>
                <SelectItem value="service">Service</SelectItem>
                <SelectItem value="goods">Goods</SelectItem>
                <SelectItem value="maintenance">Maintenance</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : contracts.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No contracts found
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Contract Number</TableHead>
                  <TableHead>Title</TableHead>
                  <TableHead>Supplier</TableHead>
                  <TableHead>Type</TableHead>
                  <TableHead>Value</TableHead>
                  <TableHead>Start Date</TableHead>
                  <TableHead>End Date</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {contracts.map((contract) => (
                  <TableRow key={contract.id}>
                    <TableCell className="font-medium">{contract.contract_number}</TableCell>
                    <TableCell>{contract.title}</TableCell>
                    <TableCell>{contract.supplier_name || '-'}</TableCell>
                    <TableCell>{contract.contract_type || '-'}</TableCell>
                    <TableCell>{formatCurrency(contract.value)}</TableCell>
                    <TableCell>
                      {contract.start_date
                        ? new Date(contract.start_date).toLocaleDateString()
                        : '-'}
                    </TableCell>
                    <TableCell>
                      {contract.end_date
                        ? new Date(contract.end_date).toLocaleDateString()
                        : '-'}
                    </TableCell>
                    <TableCell>{getStatusBadge(contract.status)}</TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(contract)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(contract)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(contract)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedContract ? 'Edit Contract' : 'Create Contract'}
            </DialogTitle>
            <DialogDescription>
              {selectedContract
                ? 'Update contract details'
                : 'Create a new vendor contract'}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Supplier *</Label>
              <Select
                value={formData.supplier_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, supplier_id: value })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select supplier" />
                </SelectTrigger>
                <SelectContent>
                  {suppliers.map((supplier) => (
                    <SelectItem key={supplier.id} value={supplier.id}>
                      {supplier.name} ({supplier.code})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Title *</Label>
              <Input
                value={formData.title}
                onChange={(e) => setFormData({ ...formData, title: e.target.value })}
                placeholder="Contract title"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Contract Type</Label>
                <Select
                  value={formData.contract_type}
                  onValueChange={(value) =>
                    setFormData({ ...formData, contract_type: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="service">Service</SelectItem>
                    <SelectItem value="goods">Goods</SelectItem>
                    <SelectItem value="maintenance">Maintenance</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label>Status</Label>
                <Select
                  value={formData.status}
                  onValueChange={(value) =>
                    setFormData({ ...formData, status: value as unknown })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="draft">Draft</SelectItem>
                    <SelectItem value="active">Active</SelectItem>
                    <SelectItem value="expired">Expired</SelectItem>
                    <SelectItem value="terminated">Terminated</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Start Date *</Label>
                <Input
                  type="date"
                  value={formData.start_date}
                  onChange={(e) =>
                    setFormData({ ...formData, start_date: e.target.value })
                  }
                />
              </div>
              <div>
                <Label>End Date</Label>
                <Input
                  type="date"
                  value={formData.end_date}
                  onChange={(e) =>
                    setFormData({ ...formData, end_date: e.target.value })
                  }
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Value</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={formData.value}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      value: e.target.value ? parseFloat(e.target.value) : undefined,
                    })
                  }
                  placeholder="0.00"
                />
              </div>
              <div>
                <Label>Currency</Label>
                <Select
                  value={formData.currency}
                  onValueChange={(value) =>
                    setFormData({ ...formData, currency: value })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="INR">INR</SelectItem>
                    <SelectItem value="USD">USD</SelectItem>
                    <SelectItem value="EUR">EUR</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div>
              <Label>Terms & Conditions</Label>
              <Textarea
                value={formData.terms_conditions}
                onChange={(e) =>
                  setFormData({ ...formData, terms_conditions: e.target.value })
                }
                placeholder="Contract terms and conditions"
                rows={4}
              />
            </div>
            <div>
              <Label>Renewal Terms</Label>
              <Textarea
                value={formData.renewal_terms}
                onChange={(e) =>
                  setFormData({ ...formData, renewal_terms: e.target.value })
                }
                placeholder="Renewal terms and conditions"
                rows={3}
              />
            </div>
            <div>
              <Label>Signed Date</Label>
              <Input
                type="date"
                value={formData.signed_date}
                onChange={(e) =>
                  setFormData({ ...formData, signed_date: e.target.value })
                }
              />
            </div>
            <div>
              <Label>Document URL</Label>
              <Input
                value={formData.document_url}
                onChange={(e) =>
                  setFormData({ ...formData, document_url: e.target.value })
                }
                placeholder="https://..."
              />
            </div>
            <div>
              <Label>Notes</Label>
              <Textarea
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Additional notes"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {selectedContract ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Contract Details</DialogTitle>
            <DialogDescription>View contract information</DialogDescription>
          </DialogHeader>
          {selectedContract && (
            <div className="space-y-4">
              <div>
                <Label className="text-muted-foreground">Contract Number</Label>
                <p className="font-medium">{selectedContract.contract_number}</p>
              </div>
              <div>
                <Label className="text-muted-foreground">Title</Label>
                <p className="font-medium">{selectedContract.title}</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Supplier</Label>
                  <p>{selectedContract.supplier_name || '-'}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Type</Label>
                  <p>{selectedContract.contract_type || '-'}</p>
                </div>
              </div>
              <div>
                <Label className="text-muted-foreground">Status</Label>
                <div className="mt-1">{getStatusBadge(selectedContract.status)}</div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Start Date</Label>
                  <p>
                    {selectedContract.start_date
                      ? new Date(selectedContract.start_date).toLocaleDateString()
                      : '-'}
                  </p>
                </div>
                <div>
                  <Label className="text-muted-foreground">End Date</Label>
                  <p>
                    {selectedContract.end_date
                      ? new Date(selectedContract.end_date).toLocaleDateString()
                      : '-'}
                  </p>
                </div>
              </div>
              <div>
                <Label className="text-muted-foreground">Value</Label>
                <p className="font-medium">{formatCurrency(selectedContract.value)}</p>
              </div>
              {selectedContract.terms_conditions && (
                <div>
                  <Label className="text-muted-foreground">Terms & Conditions</Label>
                  <p className="whitespace-pre-wrap">{selectedContract.terms_conditions}</p>
                </div>
              )}
              {selectedContract.renewal_terms && (
                <div>
                  <Label className="text-muted-foreground">Renewal Terms</Label>
                  <p className="whitespace-pre-wrap">{selectedContract.renewal_terms}</p>
                </div>
              )}
              {selectedContract.notes && (
                <div>
                  <Label className="text-muted-foreground">Notes</Label>
                  <p className="whitespace-pre-wrap">{selectedContract.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Vendor Performance Page
 * Track and evaluate vendor performance metrics
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  TrendingUp,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Eye,
  Star,
  Calendar,
  Package,
  DollarSign,
  Clock,
  AlertTriangle,
  CheckCircle2,
} from 'lucide-react';
import {
  getVendorPerformance,
  getVendorPerformanceById,
  createVendorPerformance,
  updateVendorPerformance,
  deleteVendorPerformance,
  getSuppliers,
  type VendorPerformance,
  type Supplier,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function ProcurementVendorPerformance() {
  const { toast } = useToast();
  const [performance, setPerformance] = useState<VendorPerformance[]>([]);
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterSupplier, setFilterSupplier] = useState<string>('all');
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isViewDialogOpen, setIsViewDialogOpen] = useState(false);
  const [selectedPerformance, setSelectedPerformance] = useState<VendorPerformance | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Form state
  const [formData, setFormData] = useState<Partial<VendorPerformance>>({
    supplier_id: '',
    period_start: '',
    period_end: '',
    total_orders: 0,
    total_order_value: 0,
    on_time_delivery_rate: 0,
    quality_rating: 0,
    cost_rating: 0,
    communication_rating: 0,
    overall_rating: 0,
    late_deliveries: 0,
    rejected_items: 0,
    notes: '',
  });

  useEffect(() => {
    loadData();
    loadSuppliers();
  }, [filterSupplier]);

  const loadData = async () => {
    try {
      setLoading(true);
      const filters: unknown = {};
      if (filterSupplier !== 'all') filters.supplier_id = filterSupplier;

      const data = await getVendorPerformance(filters);
      let filteredData = data;

      if (searchTerm) {
        filteredData = data.filter(
          (perf) =>
            perf.supplier_name?.toLowerCase().includes(searchTerm.toLowerCase())
        );
      }

      setPerformance(filteredData);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load vendor performance',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const loadSuppliers = async () => {
    try {
      const data = await getSuppliers({ is_active: true });
      setSuppliers(data);
    } catch (error: unknown) {
      console.error('Failed to load suppliers:', error);
    }
  };

  const handleCreate = () => {
    setFormData({
      supplier_id: '',
      period_start: '',
      period_end: '',
      total_orders: 0,
      total_order_value: 0,
      on_time_delivery_rate: 0,
      quality_rating: 0,
      cost_rating: 0,
      communication_rating: 0,
      overall_rating: 0,
      late_deliveries: 0,
      rejected_items: 0,
      notes: '',
    });
    setSelectedPerformance(null);
    setIsDialogOpen(true);
  };

  const handleEdit = (perf: VendorPerformance) => {
    setFormData({
      ...perf,
    });
    setSelectedPerformance(perf);
    setIsDialogOpen(true);
  };

  const handleView = async (perf: VendorPerformance) => {
    try {
      const fullPerformance = await getVendorPerformanceById(perf.id);
      setSelectedPerformance(fullPerformance);
      setIsViewDialogOpen(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load performance details',
        variant: 'destructive',
      });
    }
  };

  const handleSubmit = async () => {
    try {
      setIsSubmitting(true);
      if (selectedPerformance) {
        await updateVendorPerformance(selectedPerformance.id, formData);
        toast({
          title: 'Success',
          description: 'Performance record updated successfully',
        });
      } else {
        await createVendorPerformance(formData);
        toast({
          title: 'Success',
          description: 'Performance record created successfully',
        });
      }
      setIsDialogOpen(false);
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save performance record',
        variant: 'destructive',
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleDelete = async (perf: VendorPerformance) => {
    if (!confirm(`Are you sure you want to delete this performance record?`)) {
      return;
    }

    try {
      await deleteVendorPerformance(perf.id);
      toast({
        title: 'Success',
        description: 'Performance record deleted successfully',
      });
      loadData();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete performance record',
        variant: 'destructive',
      });
    }
  };

  const getRatingBadge = (rating: number) => {
    const numRating = typeof rating === 'number' ? rating : parseFloat(String(rating || 0));
    let variant: 'default' | 'secondary' | 'destructive' | 'outline' = 'secondary';
    if (numRating >= 4) variant = 'default';
    else if (numRating >= 3) variant = 'secondary';
    else if (numRating >= 2) variant = 'outline';
    else variant = 'destructive';

    return (
      <Badge variant={variant}>
        <Star className="w-3 h-3 mr-1 fill-current" />
        {numRating.toFixed(1)}/5.0
      </Badge>
    );
  };

  const formatCurrency = (value: number | undefined) => {
    if (value === undefined || value === null) return '-';
    const numValue = typeof value === 'number' ? value : parseFloat(String(value || 0));
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'INR',
    }).format(numValue);
  };

  // Statistics
  const stats = {
    total: performance.length,
    avgRating: performance.length > 0
      ? performance.reduce((sum, p) => {
          const rating = typeof p.overall_rating === 'number' ? p.overall_rating : parseFloat(String(p.overall_rating || 0));
          return sum + rating;
        }, 0) / performance.length
      : 0,
    totalOrders: performance.reduce((sum, p) => sum + (p.total_orders || 0), 0),
    totalValue: performance.reduce((sum, p) => {
      const value = typeof p.total_order_value === 'number' ? p.total_order_value : parseFloat(String(p.total_order_value || 0));
      return sum + value;
    }, 0),
  };

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Vendor Performance</h1>
          <p className="text-muted-foreground">Track and evaluate vendor performance metrics</p>
        </div>
        <Button onClick={handleCreate}>
          <Plus className="w-4 h-4 mr-2" />
          New Performance Record
        </Button>
      </div>

      {/* Statistics Cards */}
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Records</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.total}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Average Rating</CardTitle>
            <Star className="h-4 w-4 text-yellow-500 fill-current" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.avgRating.toFixed(1)}/5.0</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Orders</CardTitle>
            <Package className="h-4 w-4 text-blue-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{stats.totalOrders}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Value</CardTitle>
            <DollarSign className="h-4 w-4 text-green-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{formatCurrency(stats.totalValue)}</div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Performance Records</CardTitle>
              <CardDescription>Vendor performance evaluation and metrics</CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex gap-4 mb-4">
            <div className="flex-1">
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search vendors..."
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    loadData();
                  }}
                  className="pl-8"
                />
              </div>
            </div>
            <Select value={filterSupplier} onValueChange={setFilterSupplier}>
              <SelectTrigger className="w-[250px]">
                <SelectValue placeholder="All Suppliers" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Suppliers</SelectItem>
                {suppliers.map((supplier) => (
                  <SelectItem key={supplier.id} value={supplier.id}>
                    {supplier.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {loading ? (
            <div className="flex justify-center py-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : performance.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              No performance records found
            </div>
          ) : (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Supplier</TableHead>
                  <TableHead>Period</TableHead>
                  <TableHead>Orders</TableHead>
                  <TableHead>Order Value</TableHead>
                  <TableHead>On-Time Rate</TableHead>
                  <TableHead>Overall Rating</TableHead>
                  <TableHead>Late Deliveries</TableHead>
                  <TableHead>Rejected Items</TableHead>
                  <TableHead className="text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {performance.map((perf) => (
                  <TableRow key={perf.id}>
                    <TableCell className="font-medium">
                      {perf.supplier_name || '-'}
                    </TableCell>
                    <TableCell>
                      <div className="text-sm">
                        {new Date(perf.period_start).toLocaleDateString()} -{' '}
                        {new Date(perf.period_end).toLocaleDateString()}
                      </div>
                    </TableCell>
                    <TableCell>{perf.total_orders || 0}</TableCell>
                    <TableCell>{formatCurrency(perf.total_order_value)}</TableCell>
                    <TableCell>
                      {typeof perf.on_time_delivery_rate === 'number'
                        ? perf.on_time_delivery_rate.toFixed(1)
                        : parseFloat(String(perf.on_time_delivery_rate || 0)).toFixed(1)}
                      %
                    </TableCell>
                    <TableCell>{getRatingBadge(perf.overall_rating)}</TableCell>
                    <TableCell>
                      <Badge variant={perf.late_deliveries > 0 ? 'destructive' : 'secondary'}>
                        {perf.late_deliveries || 0}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant={perf.rejected_items > 0 ? 'destructive' : 'secondary'}>
                        {perf.rejected_items || 0}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <div className="flex justify-end gap-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleView(perf)}
                        >
                          <Eye className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEdit(perf)}
                        >
                          <Edit className="w-4 h-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleDelete(perf)}
                        >
                          <Trash2 className="w-4 h-4" />
                        </Button>
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {selectedPerformance ? 'Edit Performance Record' : 'Create Performance Record'}
            </DialogTitle>
            <DialogDescription>
              {selectedPerformance
                ? 'Update vendor performance metrics'
                : 'Create a new vendor performance evaluation'}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4">
            <div>
              <Label>Supplier *</Label>
              <Select
                value={formData.supplier_id}
                onValueChange={(value) =>
                  setFormData({ ...formData, supplier_id: value })
                }
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select supplier" />
                </SelectTrigger>
                <SelectContent>
                  {suppliers.map((supplier) => (
                    <SelectItem key={supplier.id} value={supplier.id}>
                      {supplier.name} ({supplier.code})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Period Start *</Label>
                <Input
                  type="date"
                  value={formData.period_start}
                  onChange={(e) =>
                    setFormData({ ...formData, period_start: e.target.value })
                  }
                />
              </div>
              <div>
                <Label>Period End *</Label>
                <Input
                  type="date"
                  value={formData.period_end}
                  onChange={(e) =>
                    setFormData({ ...formData, period_end: e.target.value })
                  }
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Total Orders</Label>
                <Input
                  type="number"
                  value={formData.total_orders}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      total_orders: parseInt(e.target.value) || 0,
                    })
                  }
                />
              </div>
              <div>
                <Label>Total Order Value</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={formData.total_order_value}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      total_order_value: parseFloat(e.target.value) || 0,
                    })
                  }
                />
              </div>
            </div>
            <div>
              <Label>On-Time Delivery Rate (%)</Label>
              <Input
                type="number"
                step="0.01"
                min="0"
                max="100"
                value={formData.on_time_delivery_rate}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    on_time_delivery_rate: parseFloat(e.target.value) || 0,
                  })
                }
              />
            </div>
            <div className="grid grid-cols-4 gap-4">
              <div>
                <Label>Quality Rating (0-5)</Label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="5"
                  value={formData.quality_rating}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      quality_rating: parseFloat(e.target.value) || 0,
                    })
                  }
                />
              </div>
              <div>
                <Label>Cost Rating (0-5)</Label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="5"
                  value={formData.cost_rating}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      cost_rating: parseFloat(e.target.value) || 0,
                    })
                  }
                />
              </div>
              <div>
                <Label>Communication Rating (0-5)</Label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="5"
                  value={formData.communication_rating}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      communication_rating: parseFloat(e.target.value) || 0,
                    })
                  }
                />
              </div>
              <div>
                <Label>Overall Rating (0-5)</Label>
                <Input
                  type="number"
                  step="0.1"
                  min="0"
                  max="5"
                  value={formData.overall_rating}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      overall_rating: parseFloat(e.target.value) || 0,
                    })
                  }
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <Label>Late Deliveries</Label>
                <Input
                  type="number"
                  value={formData.late_deliveries}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      late_deliveries: parseInt(e.target.value) || 0,
                    })
                  }
                />
              </div>
              <div>
                <Label>Rejected Items</Label>
                <Input
                  type="number"
                  value={formData.rejected_items}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      rejected_items: parseInt(e.target.value) || 0,
                    })
                  }
                />
              </div>
            </div>
            <div>
              <Label>Notes</Label>
              <Textarea
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Performance evaluation notes"
                rows={4}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSubmit} disabled={isSubmitting}>
              {isSubmitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              {selectedPerformance ? 'Update' : 'Create'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Dialog */}
      <Dialog open={isViewDialogOpen} onOpenChange={setIsViewDialogOpen}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>Performance Details</DialogTitle>
            <DialogDescription>View vendor performance metrics</DialogDescription>
          </DialogHeader>
          {selectedPerformance && (
            <div className="space-y-4">
              <div>
                <Label className="text-muted-foreground">Supplier</Label>
                <p className="font-medium">{selectedPerformance.supplier_name || '-'}</p>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Period Start</Label>
                  <p>
                    {new Date(selectedPerformance.period_start).toLocaleDateString()}
                  </p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Period End</Label>
                  <p>
                    {new Date(selectedPerformance.period_end).toLocaleDateString()}
                  </p>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Total Orders</Label>
                  <p className="font-medium">{selectedPerformance.total_orders || 0}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Total Order Value</Label>
                  <p className="font-medium">{formatCurrency(selectedPerformance.total_order_value)}</p>
                </div>
              </div>
              <div>
                <Label className="text-muted-foreground">On-Time Delivery Rate</Label>
                <p className="font-medium">
                  {typeof selectedPerformance.on_time_delivery_rate === 'number'
                    ? selectedPerformance.on_time_delivery_rate.toFixed(1)
                    : parseFloat(String(selectedPerformance.on_time_delivery_rate || 0)).toFixed(1)}
                  %
                </p>
              </div>
              <div className="grid grid-cols-4 gap-4">
                <div>
                  <Label className="text-muted-foreground">Quality Rating</Label>
                  <div className="mt-1">
                    {getRatingBadge(selectedPerformance.quality_rating)}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Cost Rating</Label>
                  <div className="mt-1">
                    {getRatingBadge(selectedPerformance.cost_rating)}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Communication Rating</Label>
                  <div className="mt-1">
                    {getRatingBadge(selectedPerformance.communication_rating)}
                  </div>
                </div>
                <div>
                  <Label className="text-muted-foreground">Overall Rating</Label>
                  <div className="mt-1">
                    {getRatingBadge(selectedPerformance.overall_rating)}
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <Label className="text-muted-foreground">Late Deliveries</Label>
                  <p className="font-medium">{selectedPerformance.late_deliveries || 0}</p>
                </div>
                <div>
                  <Label className="text-muted-foreground">Rejected Items</Label>
                  <p className="font-medium">{selectedPerformance.rejected_items || 0}</p>
                </div>
              </div>
              {selectedPerformance.notes && (
                <div>
                  <Label className="text-muted-foreground">Notes</Label>
                  <p className="whitespace-pre-wrap">{selectedPerformance.notes}</p>
                </div>
              )}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewDialogOpen(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Procurement Vendors Page
 * Complete vendor/supplier management interface
 */

import { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useToast } from '@/hooks/use-toast';
import {
  Building2,
  Plus,
  Search,
  Loader2,
  Edit,
  Trash2,
  Phone,
  Mail,
  MapPin,
  Star,
  TrendingUp,
  MoreVertical,
  Eye,
  FileText,
} from 'lucide-react';
import {
  getSuppliers,
  createSupplier,
  getSupplierById,
  updateSupplier,
  type Supplier,
} from '@/services/api/procurement';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Badge } from '@/components/ui/badge';
import { Textarea } from '@/components/ui/textarea';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';

export default function ProcurementVendors() {
  const [loading, setLoading] = useState(false);
  const [initialLoad, setInitialLoad] = useState(true);
  const { toast } = useToast();

  // Suppliers
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [filteredSuppliers, setFilteredSuppliers] = useState<Supplier[]>([]);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null);
  const [showSupplierDialog, setShowSupplierDialog] = useState(false);
  const [showViewDialog, setShowViewDialog] = useState(false);
  const [isEditing, setIsEditing] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [ratingFilter, setRatingFilter] = useState<string>('all');

  // Supplier form
  const [supplierForm, setSupplierForm] = useState({
    code: '',
    name: '',
    company_name: '',
    contact_person: '',
    email: '',
    phone: '',
    alternate_phone: '',
    address: '',
    city: '',
    state: '',
    postal_code: '',
    country: 'India',
    tax_id: '',
    payment_terms: '',
    credit_limit: '',
    rating: 0,
    is_preferred: false,
    notes: '',
  });

  // Fetch data
  useEffect(() => {
    fetchSuppliers();
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = suppliers;

    // Search filter
    if (searchTerm) {
      filtered = filtered.filter(s =>
        s.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.company_name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.code?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        s.email?.toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    // Status filter
    if (statusFilter !== 'all') {
      filtered = filtered.filter(s =>
        statusFilter === 'active' ? s.is_active : !s.is_active
      );
    }

    // Rating filter
    if (ratingFilter !== 'all') {
      const minRating = parseInt(ratingFilter);
      filtered = filtered.filter(s => (s.rating || 0) >= minRating);
    }

    setFilteredSuppliers(filtered);
  }, [suppliers, searchTerm, statusFilter, ratingFilter]);

  const fetchSuppliers = async () => {
    try {
      setInitialLoad(true);
      setLoading(true);
      const data = await getSuppliers();
      setSuppliers(data || []);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch suppliers',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
      setInitialLoad(false);
    }
  };

  const handleCreateSupplier = async () => {
    try {
      setLoading(true);
      const supplierData = {
        ...supplierForm,
        credit_limit: supplierForm.credit_limit ? parseFloat(supplierForm.credit_limit) : null,
        rating: supplierForm.rating || 0,
      };

      if (isEditing && selectedSupplier) {
        await updateSupplier(selectedSupplier.id, supplierData);
        toast({
          title: 'Success',
          description: 'Supplier updated successfully',
        });
      } else {
        await createSupplier(supplierData);
        toast({
          title: 'Success',
          description: 'Supplier created successfully',
        });
      }
      setShowSupplierDialog(false);
      resetForm();
      fetchSuppliers();
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to save supplier',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleEditSupplier = async (supplier: Supplier) => {
    try {
      const fullSupplier = await getSupplierById(supplier.id);
      setSelectedSupplier(fullSupplier);
      setIsEditing(true);
      setSupplierForm({
        code: fullSupplier.code || '',
        name: fullSupplier.name,
        company_name: fullSupplier.company_name || '',
        contact_person: fullSupplier.contact_person || '',
        email: fullSupplier.email || '',
        phone: fullSupplier.phone || '',
        alternate_phone: fullSupplier.alternate_phone || '',
        address: fullSupplier.address || '',
        city: fullSupplier.city || '',
        state: fullSupplier.state || '',
        postal_code: fullSupplier.postal_code || '',
        country: fullSupplier.country || 'India',
        tax_id: fullSupplier.tax_id || '',
        payment_terms: fullSupplier.payment_terms || '',
        credit_limit: fullSupplier.credit_limit?.toString() || '',
        rating: fullSupplier.rating || 0,
        is_preferred: fullSupplier.is_preferred,
        notes: fullSupplier.notes || '',
      });
      setShowSupplierDialog(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load supplier details',
        variant: 'destructive',
      });
    }
  };

  const handleViewSupplier = async (supplier: Supplier) => {
    try {
      const fullSupplier = await getSupplierById(supplier.id);
      setSelectedSupplier(fullSupplier);
      setShowViewDialog(true);
    } catch (error: unknown) {
      toast({
        title: 'Error',
        description: error.message || 'Failed to load supplier details',
        variant: 'destructive',
      });
    }
  };

  const resetForm = () => {
    setSupplierForm({
      code: '',
      name: '',
      company_name: '',
      contact_person: '',
      email: '',
      phone: '',
      alternate_phone: '',
      address: '',
      city: '',
      state: '',
      postal_code: '',
      country: 'India',
      tax_id: '',
      payment_terms: '',
      credit_limit: '',
      rating: 0,
      is_preferred: false,
      notes: '',
    });
    setSelectedSupplier(null);
    setIsEditing(false);
  };

  const openCreateDialog = () => {
    resetForm();
    setShowSupplierDialog(true);
  };

  // Calculate statistics
  const activeSuppliers = suppliers.filter(s => s.is_active).length;
  const preferredSuppliers = suppliers.filter(s => s.is_preferred).length;
  const averageRating = suppliers.length > 0
    ? suppliers.reduce((sum, s) => {
        const rating = typeof s.rating === 'number' ? s.rating : parseFloat(String(s.rating || 0));
        return sum + (isNaN(rating) ? 0 : rating);
      }, 0) / suppliers.length
    : 0;

  if (initialLoad) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-8 w-8 animate-spin" />
      </div>
    );
  }

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold">Vendor Management</h1>
          <p className="text-muted-foreground mt-1">
            Manage your suppliers and vendor relationships
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="mr-2 h-4 w-4" />
          Add Vendor
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid gap-4 md:grid-cols-4">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Total Vendors</CardTitle>
            <Building2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{suppliers.length}</div>
            <p className="text-xs text-muted-foreground">
              {activeSuppliers} active
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Preferred Vendors</CardTitle>
            <Star className="h-4 w-4 text-yellow-500" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{preferredSuppliers}</div>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Average Rating</CardTitle>
            <TrendingUp className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{averageRating.toFixed(1)}</div>
            <p className="text-xs text-muted-foreground">
              Out of 5.0
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
            <CardTitle className="text-sm font-medium">Active Vendors</CardTitle>
            <Building2 className="h-4 w-4 text-muted-foreground" />
          </CardHeader>
          <CardContent>
            <div className="text-2xl font-bold">{activeSuppliers}</div>
            <p className="text-xs text-muted-foreground">
              {((activeSuppliers / suppliers.length) * 100).toFixed(0)}% of total
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle>Filters</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
              <Label>Search</Label>
              <div className="relative">
                <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                <Input
                  placeholder="Search vendors..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-8"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Status</Label>
              <Select value={statusFilter} onValueChange={setStatusFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All statuses" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Status</SelectItem>
                  <SelectItem value="active">Active</SelectItem>
                  <SelectItem value="inactive">Inactive</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Minimum Rating</Label>
              <Select value={ratingFilter} onValueChange={setRatingFilter}>
                <SelectTrigger>
                  <SelectValue placeholder="All ratings" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Ratings</SelectItem>
                  <SelectItem value="4">4+ Stars</SelectItem>
                  <SelectItem value="3">3+ Stars</SelectItem>
                  <SelectItem value="2">2+ Stars</SelectItem>
                  <SelectItem value="1">1+ Star</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Suppliers Table */}
      <Card>
        <CardHeader>
          <CardTitle>Vendors ({filteredSuppliers.length})</CardTitle>
          <CardDescription>
            Manage your supplier relationships
          </CardDescription>
        </CardHeader>
        <CardContent>
          {loading && filteredSuppliers.length === 0 ? (
            <div className="flex items-center justify-center p-8">
              <Loader2 className="h-8 w-8 animate-spin" />
            </div>
          ) : filteredSuppliers.length === 0 ? (
            <Alert>
              <AlertDescription>
                No vendors found. {searchTerm || statusFilter !== 'all' || ratingFilter !== 'all'
                  ? 'Try adjusting your filters.'
                  : 'Create your first vendor to get started.'}
              </AlertDescription>
            </Alert>
          ) : (
            <div className="rounded-md border">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Code</TableHead>
                    <TableHead>Name</TableHead>
                    <TableHead>Company</TableHead>
                    <TableHead>Contact</TableHead>
                    <TableHead>Location</TableHead>
                    <TableHead>Rating</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead className="text-right">Actions</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filteredSuppliers.map((supplier) => (
                    <TableRow key={supplier.id}>
                      <TableCell className="font-mono text-sm">{supplier.code || '-'}</TableCell>
                      <TableCell className="font-medium">{supplier.name}</TableCell>
                      <TableCell>{supplier.company_name || '-'}</TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          {supplier.contact_person && (
                            <span className="text-sm">{supplier.contact_person}</span>
                          )}
                          {supplier.phone && (
                            <span className="text-xs text-muted-foreground flex items-center">
                              <Phone className="h-3 w-3 mr-1" />
                              {supplier.phone}
                            </span>
                          )}
                          {supplier.email && (
                            <span className="text-xs text-muted-foreground flex items-center">
                              <Mail className="h-3 w-3 mr-1" />
                              {supplier.email}
                            </span>
                          )}
                        </div>
                      </TableCell>
                      <TableCell>
                        {supplier.city && (
                          <div className="flex items-center">
                            <MapPin className="h-3 w-3 mr-1 text-muted-foreground" />
                            <span className="text-sm">
                              {supplier.city}
                              {supplier.state && `, ${supplier.state}`}
                            </span>
                          </div>
                        )}
                      </TableCell>
                      <TableCell>
                        <div className="flex items-center">
                          <Star className={`h-4 w-4 mr-1 ${(supplier.rating || 0) >= 4 ? 'text-yellow-500 fill-yellow-500' : 'text-muted-foreground'}`} />
                          <span className="text-sm">{supplier.rating || 0}</span>
                        </div>
                      </TableCell>
                      <TableCell>
                        <div className="flex gap-1">
                          <Badge variant={supplier.is_active ? 'default' : 'secondary'}>
                            {supplier.is_active ? 'Active' : 'Inactive'}
                          </Badge>
                          {supplier.is_preferred && (
                            <Badge variant="outline" className="border-yellow-500 text-yellow-700">
                              Preferred
                            </Badge>
                          )}
                        </div>
                      </TableCell>
                      <TableCell className="text-right">
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="sm">
                              <MoreVertical className="h-4 w-4" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => handleViewSupplier(supplier)}>
                              <Eye className="mr-2 h-4 w-4" />
                              View
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => handleEditSupplier(supplier)}>
                              <Edit className="mr-2 h-4 w-4" />
                              Edit
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <FileText className="mr-2 h-4 w-4" />
                              View Contracts
                            </DropdownMenuItem>
                            <DropdownMenuItem>
                              <TrendingUp className="mr-2 h-4 w-4" />
                              View Performance
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Create/Edit Supplier Dialog */}
      <Dialog open={showSupplierDialog} onOpenChange={setShowSupplierDialog}>
        <DialogContent className="max-w-3xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{isEditing ? 'Edit Vendor' : 'Create New Vendor'}</DialogTitle>
            <DialogDescription>
              {isEditing ? 'Update vendor information' : 'Add a new vendor/supplier'}
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="code">Vendor Code</Label>
                <Input
                  id="code"
                  value={supplierForm.code}
                  onChange={(e) => setSupplierForm({ ...supplierForm, code: e.target.value })}
                  placeholder="VENDOR-001"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="name">Vendor Name *</Label>
                <Input
                  id="name"
                  value={supplierForm.name}
                  onChange={(e) => setSupplierForm({ ...supplierForm, name: e.target.value })}
                  placeholder="Vendor name"
                  required
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="company_name">Company Name</Label>
              <Input
                id="company_name"
                value={supplierForm.company_name}
                onChange={(e) => setSupplierForm({ ...supplierForm, company_name: e.target.value })}
                placeholder="Company name"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="contact_person">Contact Person</Label>
              <Input
                id="contact_person"
                value={supplierForm.contact_person}
                onChange={(e) => setSupplierForm({ ...supplierForm, contact_person: e.target.value })}
                placeholder="Contact person name"
              />
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="phone">Phone</Label>
                <Input
                  id="phone"
                  value={supplierForm.phone}
                  onChange={(e) => setSupplierForm({ ...supplierForm, phone: e.target.value })}
                  placeholder="+91 1234567890"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="email">Email</Label>
                <Input
                  id="email"
                  type="email"
                  value={supplierForm.email}
                  onChange={(e) => setSupplierForm({ ...supplierForm, email: e.target.value })}
                  placeholder="vendor@example.com"
                />
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="address">Address</Label>
              <Textarea
                id="address"
                value={supplierForm.address}
                onChange={(e) => setSupplierForm({ ...supplierForm, address: e.target.value })}
                placeholder="Street address"
                rows={2}
              />
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="city">City</Label>
                <Input
                  id="city"
                  value={supplierForm.city}
                  onChange={(e) => setSupplierForm({ ...supplierForm, city: e.target.value })}
                  placeholder="City"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="state">State</Label>
                <Input
                  id="state"
                  value={supplierForm.state}
                  onChange={(e) => setSupplierForm({ ...supplierForm, state: e.target.value })}
                  placeholder="State"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="postal_code">Postal Code</Label>
                <Input
                  id="postal_code"
                  value={supplierForm.postal_code}
                  onChange={(e) => setSupplierForm({ ...supplierForm, postal_code: e.target.value })}
                  placeholder="123456"
                />
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-3">
              <div className="grid gap-2">
                <Label htmlFor="tax_id">Tax ID / GSTIN</Label>
                <Input
                  id="tax_id"
                  value={supplierForm.tax_id}
                  onChange={(e) => setSupplierForm({ ...supplierForm, tax_id: e.target.value })}
                  placeholder="GSTIN or Tax ID"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="payment_terms">Payment Terms</Label>
                <Input
                  id="payment_terms"
                  value={supplierForm.payment_terms}
                  onChange={(e) => setSupplierForm({ ...supplierForm, payment_terms: e.target.value })}
                  placeholder="e.g., Net 30"
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="credit_limit">Credit Limit</Label>
                <Input
                  id="credit_limit"
                  type="number"
                  value={supplierForm.credit_limit}
                  onChange={(e) => setSupplierForm({ ...supplierForm, credit_limit: e.target.value })}
                  placeholder="0.00"
                  step="0.01"
                />
              </div>
            </div>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="grid gap-2">
                <Label htmlFor="rating">Rating (0-5)</Label>
                <Input
                  id="rating"
                  type="number"
                  min="0"
                  max="5"
                  step="0.1"
                  value={supplierForm.rating}
                  onChange={(e) => setSupplierForm({ ...supplierForm, rating: parseFloat(e.target.value) || 0 })}
                  placeholder="0"
                />
              </div>
              <div className="flex items-center space-x-2 pt-6">
                <Switch
                  id="preferred"
                  checked={supplierForm.is_preferred}
                  onCheckedChange={(checked) =>
                    setSupplierForm({ ...supplierForm, is_preferred: checked })
                  }
                />
                <Label htmlFor="preferred">Preferred Vendor</Label>
              </div>
            </div>
            <div className="grid gap-2">
              <Label htmlFor="notes">Notes</Label>
              <Textarea
                id="notes"
                value={supplierForm.notes}
                onChange={(e) => setSupplierForm({ ...supplierForm, notes: e.target.value })}
                placeholder="Additional notes"
                rows={3}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowSupplierDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleCreateSupplier} disabled={loading || !supplierForm.name}>
              {loading && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}
              {isEditing ? 'Update' : 'Create'} Vendor
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* View Supplier Dialog */}
      <Dialog open={showViewDialog} onOpenChange={setShowViewDialog}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle>Vendor Details</DialogTitle>
            <DialogDescription>
              View complete vendor information
            </DialogDescription>
          </DialogHeader>
          {selectedSupplier && (
            <div className="grid gap-4 py-4">
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Name</Label>
                <p>{selectedSupplier.name}</p>
              </div>
              {selectedSupplier.company_name && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Company</Label>
                  <p>{selectedSupplier.company_name}</p>
                </div>
              )}
              {selectedSupplier.contact_person && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Contact Person</Label>
                  <p>{selectedSupplier.contact_person}</p>
                </div>
              )}
              {(selectedSupplier.phone || selectedSupplier.email) && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Contact Information</Label>
                  <div className="space-y-1">
                    {selectedSupplier.phone && (
                      <p className="text-sm flex items-center">
                        <Phone className="h-4 w-4 mr-2" />
                        {selectedSupplier.phone}
                      </p>
                    )}
                    {selectedSupplier.email && (
                      <p className="text-sm flex items-center">
                        <Mail className="h-4 w-4 mr-2" />
                        {selectedSupplier.email}
                      </p>
                    )}
                  </div>
                </div>
              )}
              {selectedSupplier.address && (
                <div className="grid gap-2">
                  <Label className="text-sm font-medium">Address</Label>
                  <p className="text-sm text-muted-foreground">{selectedSupplier.address}</p>
                </div>
              )}
              <div className="grid gap-2">
                <Label className="text-sm font-medium">Status</Label>
                <div className="flex gap-2">
                  <Badge variant={selectedSupplier.is_active ? 'default' : 'secondary'}>
                    {selectedSupplier.is_active ? 'Active' : 'Inactive'}
                  </Badge>
                  {selectedSupplier.is_preferred && (
                    <Badge variant="outline" className="border-yellow-500 text-yellow-700">
                      Preferred
                    </Badge>
                  )}
                  {selectedSupplier.rating && (
                    <Badge variant="outline">
                      <Star className="h-3 w-3 mr-1" />
                      {selectedSupplier.rating}
                    </Badge>
                  )}
                </div>
              </div>
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setShowViewDialog(false)}>
              Close
            </Button>
            {selectedSupplier && (
              <Button onClick={() => {
                setShowViewDialog(false);
                handleEditSupplier(selectedSupplier);
              }}>
                <Edit className="mr-2 h-4 w-4" />
                Edit
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Projects Page
 * Main orchestrator for project management functionality
 * Refactored from 1,417 lines to ~250 lines
 */

import { useState, useEffect, useMemo } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Plus, List, GanttChart, Download, Loader2, Building2, Users } from "lucide-react";
import { useSearchParams } from "react-router-dom";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/hooks/useAuth";
import { DepartmentBreadcrumb } from "@/components/department-management";
import { useDepartmentNavigation } from "@/hooks/useDepartmentNavigation";
import ProjectFormDialog from "@/components/shared/ProjectFormDialog";
import DeleteConfirmDialog from "@/components/shared/DeleteConfirmDialog";
import ProjectDetailsDialog from "@/components/ProjectDetailsDialog";
import { useProjects } from './hooks/useProjects';
import { useProjectFilters } from './hooks/useProjectFilters';
import { useProjectPipeline } from './hooks/useProjectPipeline';
import { useProjectFilterOptions } from './hooks/useProjectFilterOptions';
import { calculateProjectStats, Project } from './utils/projectUtils';
import { exportProjectsToCSV } from './utils/projectExport';
import { ProjectMetrics } from './components/ProjectMetrics';
import { ProjectFilters } from './components/ProjectFilters';
import { ProjectCard } from './components/ProjectCard';
import { ProjectPipeline } from './components/ProjectPipeline';
import { ProjectPagination } from './components/ProjectPagination';

const Projects = () => {
  const { toast } = useToast();
  const { user, profile } = useAuth();
  const {
    departmentId: urlDepartmentId,
    departmentName: urlDepartmentName,
    employeeId: urlEmployeeId,
    employeeName: urlEmployeeName,
    navigateToDepartment,
    navigateToEmployees,
    navigateToAttendance,
    navigateToPayroll,
  } = useDepartmentNavigation();
  
  const [searchParams] = useSearchParams();
  const legacyDepartmentId = searchParams.get('department');
  const legacyDepartmentName = searchParams.get('name');
  const clientFilterId = searchParams.get('client_id');
  
  // Local state
  const [searchTerm, setSearchTerm] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [priorityFilter, setPriorityFilter] = useState<string>("all");
  const [clientFilter, setClientFilter] = useState<string>(clientFilterId || "all");
  const [managerFilter, setManagerFilter] = useState<string>("all");
  const [departmentFilter, setDepartmentFilter] = useState<string>("all");
  const [sortBy, setSortBy] = useState<string>("created_at");
  const [sortOrder, setSortOrder] = useState<'asc' | 'desc'>('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(25);
  const [projectFormOpen, setProjectFormOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState<Project | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [projectToDelete, setProjectToDelete] = useState<Project | null>(null);
  const [detailsDialogOpen, setDetailsDialogOpen] = useState(false);
  const [projectToView, setProjectToView] = useState<Project | null>(null);
  const [showAdvancedFilters, setShowAdvancedFilters] = useState(false);

  // Hooks
  const { projects, loading, fetchProjects } = useProjects(
    urlDepartmentId || undefined,
    urlEmployeeId || undefined,
    legacyDepartmentId || undefined,
    clientFilterId || undefined
  );
  const { clients, employees, departments } = useProjectFilterOptions();
  const {
    projectsByStatus,
    draggedProject,
    onDragStart,
    onDragEnd,
    onDragOver,
    onDragLeave,
    onDrop,
  } = useProjectPipeline(projects, () => {
    fetchProjects(statusFilter, priorityFilter, clientFilter, managerFilter, departmentFilter, searchTerm);
  });

  // Filter and sort projects
  const filteredProjects = useProjectFilters(
    projects,
    searchTerm,
    statusFilter,
    priorityFilter,
    sortBy,
    sortOrder
  );

  // Calculate stats
  const projectStats = useMemo(() => calculateProjectStats(projects), [projects]);

  // Pagination
  const totalPages = Math.ceil(filteredProjects.length / pageSize);
  const paginatedProjects = useMemo(() => {
    const start = (currentPage - 1) * pageSize;
    return filteredProjects.slice(start, start + pageSize);
  }, [filteredProjects, currentPage, pageSize]);

  // Fetch projects when filters change
  useEffect(() => {
    fetchProjects(statusFilter, priorityFilter, clientFilter, managerFilter, departmentFilter, searchTerm);
  }, [urlDepartmentId, urlEmployeeId, legacyDepartmentId, statusFilter, priorityFilter, clientFilter, managerFilter, departmentFilter, fetchProjects]);

  // Handlers
  const handleNewProject = () => {
    setSelectedProject(null);
    setProjectFormOpen(true);
  };

  const handleEditProject = (project: Project) => {
    setSelectedProject(project);
    setProjectFormOpen(true);
  };

  const handleDeleteProject = (project: Project) => {
    setProjectToDelete(project);
    setDeleteDialogOpen(true);
  };

  const handleViewProject = (project: Project) => {
    setProjectToView(project);
    setDetailsDialogOpen(true);
  };

  const handleProjectSaved = () => {
    fetchProjects(statusFilter, priorityFilter, clientFilter, managerFilter, departmentFilter, searchTerm);
    setSelectedProject(null);
  };

  const handleProjectDeleted = () => {
    fetchProjects(statusFilter, priorityFilter, clientFilter, managerFilter, departmentFilter, searchTerm);
    setProjectToDelete(null);
  };

  const handleExportCSV = () => {
    exportProjectsToCSV(filteredProjects);
    toast({
      title: 'Success',
      description: 'Projects exported to CSV successfully',
    });
  };

  if (loading) {
    return (
      <div className="p-6">
        <div className="flex justify-center items-center min-h-[400px]">
          <Loader2 className="h-8 w-8 animate-spin" />
          <span className="ml-2 text-muted-foreground">Loading projects...</span>
        </div>
      </div>
    );
  }

  const displayDepartmentName = urlDepartmentName || (legacyDepartmentName ? decodeURIComponent(legacyDepartmentName) : null);
  const displayEmployeeName = urlEmployeeName;

  return (
    <div className="container mx-auto p-6 space-y-6">
      {/* Breadcrumb */}
      <DepartmentBreadcrumb currentPage="projects" />
      
      {/* Header */}
      <div className="flex flex-col space-y-4 sm:flex-row sm:justify-between sm:items-center sm:space-y-0">
        <div>
          <div className="flex items-center gap-2 flex-wrap">
            <h1 className="text-2xl lg:text-3xl font-bold">Projects</h1>
            {displayDepartmentName && (
              <Badge 
                variant="secondary" 
                className="text-sm cursor-pointer hover:bg-secondary/80 transition-colors"
                onClick={() => navigateToDepartment(urlDepartmentId || legacyDepartmentId || undefined, displayDepartmentName || undefined)}
              >
                <Building2 className="h-3 w-3 mr-1" />
                {displayDepartmentName}
              </Badge>
            )}
            {displayEmployeeName && (
              <Badge 
                variant="outline" 
                className="text-sm cursor-pointer hover:bg-accent transition-colors"
                onClick={() => navigateToEmployees({ employeeId: urlEmployeeId || undefined, employeeName: displayEmployeeName || undefined })}
              >
                <Users className="h-3 w-3 mr-1" />
                {displayEmployeeName}
              </Badge>
            )}
          </div>
          <p className="text-sm lg:text-base text-muted-foreground mt-1">
            {displayEmployeeName 
              ? `Projects for ${displayEmployeeName}`
              : displayDepartmentName 
              ? `Projects for ${displayDepartmentName} department`
              : "Manage and track project progress"}
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleExportCSV} className="w-full sm:w-auto" disabled={filteredProjects.length === 0}>
            <Download className="mr-2 h-4 w-4" />
            Export CSV
          </Button>
          <Button onClick={handleNewProject} className="w-full sm:w-auto">
            <Plus className="mr-2 h-4 w-4" />
            New Project
          </Button>
        </div>
      </div>

      {/* Statistics Cards */}
      <ProjectMetrics stats={projectStats} />

      {/* Search and Filter Card */}
      <ProjectFilters
        searchTerm={searchTerm}
        onSearchChange={(value) => {
          setSearchTerm(value);
          setCurrentPage(1);
        }}
        statusFilter={statusFilter}
        onStatusFilterChange={(value) => {
          setStatusFilter(value);
          setCurrentPage(1);
        }}
        priorityFilter={priorityFilter}
        onPriorityFilterChange={(value) => {
          setPriorityFilter(value);
          setCurrentPage(1);
        }}
        sortBy={sortBy}
        onSortByChange={setSortBy}
        showAdvancedFilters={showAdvancedFilters}
        onToggleAdvancedFilters={() => setShowAdvancedFilters(!showAdvancedFilters)}
        clientFilter={clientFilter}
        onClientFilterChange={(value) => {
          setClientFilter(value);
          setCurrentPage(1);
        }}
        managerFilter={managerFilter}
        onManagerFilterChange={(value) => {
          setManagerFilter(value);
          setCurrentPage(1);
        }}
        departmentFilter={departmentFilter}
        onDepartmentFilterChange={(value) => {
          setDepartmentFilter(value);
          setCurrentPage(1);
        }}
        clients={clients}
        employees={employees}
        departments={departments}
      />

      {/* Projects Content with Tabs */}
      <Tabs defaultValue="list" className="space-y-4">
        <TabsList>
          <TabsTrigger value="list">
            <List className="h-4 w-4 mr-2" />
            List View
          </TabsTrigger>
          <TabsTrigger value="pipeline">
            <GanttChart className="h-4 w-4 mr-2" />
            Pipeline View
          </TabsTrigger>
        </TabsList>

        <TabsContent value="list" className="space-y-4">
          {filteredProjects.length === 0 ? (
            <Card>
              <CardContent className="pt-6">
                <div className="text-center py-8">
                  <p className="text-muted-foreground">
                    {searchTerm ? 'No projects found matching your search.' : 'No projects found.'}
                  </p>
                  {!searchTerm && (
                    <Button 
                      className="mt-4" 
                      onClick={handleNewProject}
                    >
                      <Plus className="mr-2 h-4 w-4" />
                      Create First Project
                    </Button>
                  )}
                </div>
              </CardContent>
            </Card>
          ) : (
            <>
              <ProjectPagination
                currentPage={currentPage}
                totalPages={totalPages}
                pageSize={pageSize}
                totalItems={filteredProjects.length}
                onPageChange={setCurrentPage}
                onPageSizeChange={(size) => {
                  setPageSize(size);
                  setCurrentPage(1);
                }}
              />
              <div className="grid gap-4 lg:gap-6">
                {paginatedProjects.map((project) => (
                  <ProjectCard
                    key={project.id}
                    project={project}
                    onView={handleViewProject}
                    onEdit={handleEditProject}
                    onDelete={handleDeleteProject}
                    onNavigateToEmployees={navigateToEmployees}
                    onNavigateToAttendance={navigateToAttendance}
                    onNavigateToPayroll={navigateToPayroll}
                    onNavigateToDepartment={navigateToDepartment}
                    urlDepartmentId={urlDepartmentId}
                    legacyDepartmentId={legacyDepartmentId}
                    displayDepartmentName={displayDepartmentName}
                  />
                ))}
              </div>
              {totalPages > 1 && (
                <ProjectPagination
                  currentPage={currentPage}
                  totalPages={totalPages}
                  pageSize={pageSize}
                  totalItems={filteredProjects.length}
                  onPageChange={setCurrentPage}
                  onPageSizeChange={(size) => {
                    setPageSize(size);
                    setCurrentPage(1);
                  }}
                />
              )}
            </>
          )}
        </TabsContent>

        <TabsContent value="pipeline" className="space-y-4">
          <ProjectPipeline
            projects={projects}
            projectsByStatus={projectsByStatus}
            draggedProject={draggedProject}
            searchTerm={searchTerm}
            statusFilter={statusFilter}
            priorityFilter={priorityFilter}
            onDragStart={onDragStart}
            onDragEnd={onDragEnd}
            onDragOver={onDragOver}
            onDragLeave={onDragLeave}
            onDrop={onDrop}
            onView={handleViewProject}
            onEdit={handleEditProject}
            onDelete={handleDeleteProject}
          />
        </TabsContent>
      </Tabs>

      {/* Dialogs */}
      <ProjectFormDialog
        isOpen={projectFormOpen}
        onClose={() => setProjectFormOpen(false)}
        project={selectedProject}
        onProjectSaved={handleProjectSaved}
      />

      <DeleteConfirmDialog
        isOpen={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onDeleted={handleProjectDeleted}
        itemType="Project"
        itemName={projectToDelete?.name || ''}
        itemId={projectToDelete?.id || ''}
        tableName="projects"
      />

      <ProjectDetailsDialog
        isOpen={detailsDialogOpen}
        onClose={() => {
          setDetailsDialogOpen(false);
          setProjectToView(null);
        }}
        project={projectToView}
        onEdit={() => {
          setDetailsDialogOpen(false);
          if (projectToView) {
            setSelectedProject(projectToView);
            setProjectFormOpen(true);
          }
        }}
      />
    </div>
  );
};

export default Projects;

import React, { useState, useEffect } from 'react';
import { Plus, Search, Filter, FileCheck, Send, DollarSign, Calendar, Edit, Trash2, Eye } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { useToast } from '@/hooks/use-toast';
import { db } from '@/lib/database';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useAuth } from '@/hooks/useAuth';
import { getAgencyId } from '@/utils/agencyUtils';
import DeleteConfirmDialog from '@/components/shared/DeleteConfirmDialog';
import QuotationTemplateDialog from '@/components/QuotationTemplateDialog';
import QuotationPreviewDialog from '@/components/QuotationPreviewDialog';

interface Quotation {
  id: string;
  quote_number: string;
  client_id: string;
  template_id?: string | null;
  title: string;
  description?: string;
  status: string;
  valid_until: string;
  subtotal: number;
  tax_rate: number;
  tax_amount: number;
  total_amount: number;
  terms_conditions?: string;
  notes?: string;
  created_at: string;
  updated_at: string;
  client?: {
    id: string;
    name: string;
    company_name?: string;
  };
  line_items?: Array<{
    id: string;
    item_name: string;
    description?: string;
    quantity: number;
    unit_price: number;
    discount_percentage: number;
    line_total: number;
  }>;
}

interface QuotationTemplate {
  id: string;
  name: string;
  description?: string;
  template_data?: unknown;
  is_active: boolean;
  last_used?: string;
  created_at: string;
}

const Quotations = () => {
  const { toast } = useToast();
  const navigate = useNavigate();
  const auth = useAuth();
  const user = auth?.user;
  const profile = auth?.profile;
  const [searchTerm, setSearchTerm] = useState('');
  const [quotations, setQuotations] = useState<Quotation[]>([]);
  const [templates, setTemplates] = useState<QuotationTemplate[]>([]);
  const [loading, setLoading] = useState(true);
  const [templateDialogOpen, setTemplateDialogOpen] = useState(false);
  const [selectedTemplate, setSelectedTemplate] = useState<QuotationTemplate | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [previewDialogOpen, setPreviewDialogOpen] = useState(false);
  const [previewQuotationId, setPreviewQuotationId] = useState<string | null>(null);
  const [searchParams] = useSearchParams();
  const clientFilterId = searchParams.get('client_id');

  useEffect(() => {
    fetchQuotations();
    fetchTemplates();
  }, []);

  const fetchQuotations = async () => {
    try {
      setLoading(true);
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        console.warn('No agency_id available for fetching quotations');
        setQuotations([]);
        setLoading(false);
        return;
      }

      const query = db
        .from('quotations')
        .select('*')
        .eq('agency_id', agencyId)
        .order('created_at', { ascending: false });

      const { data, error } = await query;

      if (error) throw error;

      // Fetch client names (filtered by agency)
      const clientIds = [...new Set((data || []).map((q: unknown) => q.client_id).filter(Boolean))];
      let clientsMap = new Map();

      if (clientIds.length > 0) {
        const { data: clientsData, error: clientsError } = await db
          .from('clients')
          .select('id, name, company_name')
          .eq('agency_id', agencyId)
          .eq('is_active', true)
          .in('id', clientIds);

        if (!clientsError && clientsData) {
          clientsMap = new Map(clientsData.map((c: unknown) => [c.id, c]));
        }
      }

      // Fetch line items for all quotations
      const quotationIds = (data || []).map((q: unknown) => q.id);
      const lineItemsMap = new Map();

      if (quotationIds.length > 0) {
        const { data: lineItemsData, error: lineItemsError } = await db
          .from('quotation_line_items')
          .select('*')
          .in('quotation_id', quotationIds)
          .order('sort_order', { ascending: true });

        if (!lineItemsError && lineItemsData) {
          lineItemsData.forEach((item: unknown) => {
            if (!lineItemsMap.has(item.quotation_id)) {
              lineItemsMap.set(item.quotation_id, []);
            }
            lineItemsMap.get(item.quotation_id).push(item);
          });
        }
      }

      // Combine data
      let quotationsWithDetails = (data || []).map((quote: unknown) => ({
        ...quote,
        client: clientsMap.get(quote.client_id),
        line_items: lineItemsMap.get(quote.id) || [],
      }));

      // If filtering by client from URL, apply client filter
      if (clientFilterId) {
        quotationsWithDetails = quotationsWithDetails.filter((q: unknown) => q.client_id === clientFilterId);
      }

      setQuotations(quotationsWithDetails);
    } catch (error: unknown) {
      console.error('Error fetching quotations:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to fetch quotations',
        variant: 'destructive',
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchTemplates = async () => {
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        console.warn('No agency_id available for fetching templates');
        setTemplates([]);
        return;
      }

      const { data, error } = await db
        .from('quotation_templates')
        .select('*')
        .eq('agency_id', agencyId)
        .order('name', { ascending: true });

      if (error) throw error;
      setTemplates(data || []);
    } catch (error: unknown) {
      console.error('Error fetching templates:', error);
      toast({
        title: 'Error',
        description: 'Failed to fetch templates',
        variant: 'destructive',
      });
    }
  };

  const handleNewQuotation = () => {
    navigate('/quotations/new');
  };

  const handleEditQuotation = (quotation: Quotation) => {
    navigate(`/quotations/${quotation.id}`);
  };

  const handlePreviewQuotation = (quotation: Quotation) => {
    setPreviewQuotationId(quotation.id);
    setPreviewDialogOpen(true);
  };

  const handleDeleteQuotation = async (quotation: Quotation) => {
    if (!confirm(`Are you sure you want to delete quotation "${quotation.title}"? This will also delete all associated line items. This action cannot be undone.`)) {
      return;
    }

    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({
          title: 'Error',
          description: 'Agency ID not found',
          variant: 'destructive',
        });
        return;
      }

      // Delete line items first
      const { error: lineItemsError } = await db
        .from('quotation_line_items')
        .delete()
        .eq('quotation_id', quotation.id);

      if (lineItemsError) throw lineItemsError;

      // Delete quotation (with agency check)
      const { error: quotationError } = await db
        .from('quotations')
        .delete()
        .eq('id', quotation.id)
        .eq('agency_id', agencyId);

      if (quotationError) throw quotationError;

      toast({
        title: 'Success',
        description: 'Quotation deleted successfully',
      });

      fetchQuotations();
    } catch (error: unknown) {
      console.error('Error deleting quotation:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to delete quotation',
        variant: 'destructive',
      });
    }
  };

  const handleSendQuotation = async (quotation: Quotation) => {
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({
          title: 'Error',
          description: 'Agency ID not found',
          variant: 'destructive',
        });
        return;
      }

      const { error } = await db
        .from('quotations')
        .update({ 
          status: 'sent',
        })
        .eq('id', quotation.id)
        .eq('agency_id', agencyId);

      if (error) throw error;

      toast({
        title: 'Success',
        description: 'Quotation sent successfully',
      });

      fetchQuotations();
    } catch (error: unknown) {
      console.error('Error sending quotation:', error);
      toast({
        title: 'Error',
        description: error.message || 'Failed to send quotation',
        variant: 'destructive',
      });
    }
  };

  const handleUseTemplate = async (template: QuotationTemplate) => {
    setSelectedQuotation(null);
    setQuotationFormOpen(true);
    
    // Update template last_used if column exists
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (agencyId) {
        await db
          .from('quotation_templates')
          .update({ 
            last_used: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .eq('id', template.id)
          .eq('agency_id', agencyId);
        
        fetchTemplates();
      }
    } catch (error) {
      // Column might not exist, ignore error
      console.error('Error updating template:', error);
    }
  };

  const handleNewTemplate = () => {
    setSelectedTemplate(null);
    setTemplateDialogOpen(true);
  };

  const handleEditTemplate = (template: QuotationTemplate) => {
    setSelectedTemplate(template);
    setTemplateDialogOpen(true);
  };

  const handleDeleteTemplate = async (template: QuotationTemplate) => {
    try {
      const agencyId = await getAgencyId(profile, user?.id);
      if (!agencyId) {
        toast({
          title: 'Error',
          description: 'Agency ID not found',
          variant: 'destructive',
        });
        return;
      }

      // Check if any quotations are using this template
      const { data: quotationsUsingTemplate, error: checkError } = await db
        .from('quotations')
        .select('id, title')
        .eq('template_id', template.id)
        .eq('agency_id', agencyId);

      if (checkError) throw checkError;

      const quotationCount = quotationsUsingTemplate?.length || 0;

      if (quotationCount > 0) {
        const quotationList = quotationsUsingTemplate
          ?.slice(0, 5)
          .map(q => `"${q.title}"`)
          .join(', ');
        const moreText = quotationCount > 5 ? ` and ${quotationCount - 5} more` : '';
        
        const message = `Cannot delete template "${template.name}" because it is being used by ${quotationCount} quotation(s): ${quotationList}${moreText}.\n\nPlease remove the template reference from these quotations first, or delete the quotations.`;
        
        toast({
          title: 'Cannot Delete Template',
          description: message,
          variant: 'destructive',
        });
        return;
      }

      // Confirm deletion if no quotations are using it
      if (!confirm(`Are you sure you want to delete template "${template.name}"? This action cannot be undone.`)) {
        return;
      }

      // Delete the template
      const { error } = await db
        .from('quotation_templates')
        .delete()
        .eq('id', template.id)
        .eq('agency_id', agencyId);

      if (error) {
        // Check if it's a foreign key constraint error
        if (error.message?.includes('foreign key constraint') || error.message?.includes('violates foreign key')) {
          toast({
            title: 'Cannot Delete Template',
            description: `This template is being used by one or more quotations. Please remove the template reference from those quotations first.`,
            variant: 'destructive',
          });
          return;
        }
        throw error;
      }

      toast({
        title: 'Success',
        description: 'Template deleted successfully',
      });

      fetchTemplates();
    } catch (error: unknown) {
      console.error('Error deleting template:', error);
      
      // Provide user-friendly error messages
      let errorMessage = 'Failed to delete template';
      if (error.message?.includes('foreign key constraint') || error.message?.includes('violates foreign key')) {
        errorMessage = 'This template is being used by one or more quotations. Please remove the template reference from those quotations first.';
      } else if (error.message) {
        errorMessage = error.message;
      }
      
      toast({
        title: 'Error',
        description: errorMessage,
        variant: 'destructive',
      });
    }
  };

  const handleQuotationSaved = () => {
    fetchQuotations();
  };

  const handleQuotationDeleted = () => {
    fetchQuotations();
  };

  const handleTemplateSaved = () => {
    fetchTemplates();
  };

  // Calculate stats from real data
  const quotationStats = {
    totalQuotations: quotations.length,
    pending: quotations.filter(q => q.status === 'sent').length,
    accepted: quotations.filter(q => q.status === 'accepted').length,
    totalValue: quotations.reduce((sum, q) => sum + (q.total_amount || 0), 0),
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'draft': return 'bg-gray-100 text-gray-800';
      case 'sent': return 'bg-blue-100 text-blue-800';
      case 'accepted': return 'bg-green-100 text-green-800';
      case 'rejected': return 'bg-red-100 text-red-800';
      case 'expired': return 'bg-orange-100 text-orange-800';
      default: return 'bg-gray-100 text-gray-800';
    }
  };

  const filteredQuotations = quotations.filter(quote => {
    const matchesSearch = 
      quote.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      quote.quote_number?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      quote.client?.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      quote.client?.company_name?.toLowerCase().includes(searchTerm.toLowerCase());
    
    const matchesStatus = statusFilter === 'all' || quote.status === statusFilter;
    
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="container mx-auto p-6 space-y-6">
      <div className="flex flex-col space-y-4 sm:flex-row sm:justify-between sm:items-center sm:space-y-0">
        <div>
          <h1 className="text-2xl lg:text-3xl font-bold">Quotations</h1>
          <p className="text-sm lg:text-base text-muted-foreground">Manage quotes and estimates for potential clients</p>
        </div>
        <Button onClick={handleNewQuotation} className="w-full sm:w-auto">
          <Plus className="h-4 w-4 mr-2" />
          New Quotation
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
              <FileCheck className="h-8 w-8 text-blue-600" />
              <div className="ml-4">
                <p className="text-sm font-medium text-muted-foreground">Total Quotes</p>
                <p className="text-2xl font-bold">{quotationStats.totalQuotations}</p>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center">
