import { getApiBaseUrl } from '@/config/api';

/**
 * A simple, thin wrapper around fetch to provide an axios-like interface
 * for the public components.
 */
export const api = {
  get: async (endpoint: string) => {
    const baseUrl = getApiBaseUrl();
    const url = endpoint.startsWith('http') ? endpoint : `${baseUrl}/api${endpoint.startsWith('/') ? '' : '/'}${endpoint}`;

    const response = await fetch(url, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
      },
    });

    if (!response.ok) {
      throw new Error(`API Error: ${response.statusText}`);
    }

    const data = await response.json();
    return { data };
  },

  post: async (endpoint: string, body: any) => {
    const baseUrl = getApiBaseUrl();
    const url = endpoint.startsWith('http') ? endpoint : `${baseUrl}/api${endpoint.startsWith('/') ? '' : '/'}${endpoint}`;

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(body),
    });

    if (!response.ok) {
      throw new Error(`API Error: ${response.statusText}`);
    }

    const data = await response.json();
    return { data };
  }
};

import { getApiBaseUrl } from '@/config/api';

const token = () => localStorage.getItem('auth_token') ?? '';

export const fetchJson = async (path: string, options?: RequestInit) => {
  const baseUrl = getApiBaseUrl();
  const url = path.startsWith('http') ? path : `${baseUrl}/api${path.startsWith('/') ? '' : '/'}${path}`;

  const headers = new Headers(options?.headers);
  headers.set('Authorization', `Bearer ${token()}`);
  if (!headers.has('Content-Type') && !(options?.body instanceof FormData)) {
      headers.set('Content-Type', 'application/json');
  }

  const res = await fetch(url, {
    ...options,
    headers,
  });

  if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
  }

  const responseData = await res.json();
  // Ensure we return the data payload if wrapped in standard Fastify envelope
  if (responseData && typeof responseData === 'object' && 'data' in responseData) {
      return responseData.data;
  }
  return responseData;
};

export const fetchMutate = async (path: string, method: 'POST' | 'PUT' | 'DELETE' | 'PATCH', body?: any) => {
    return fetchJson(path, {
        method,
        body: body ? JSON.stringify(body) : undefined
    });
};

/**
 * Console Log Capture Utility
 * Intercepts console errors and warnings for ticket reporting
 */

export interface ConsoleLogEntry {
  level: 'error' | 'warn' | 'info' | 'log';
  message: string;
  timestamp: string;
  stack?: string;
  url?: string;
  line?: number;
  column?: number;
}

class ConsoleLogger {
  private logs: ConsoleLogEntry[] = [];
  private maxLogs = 100; // Keep last 100 logs
  private originalConsole: {
    error: typeof console.error;
    warn: typeof console.warn;
    log: typeof console.log;
    info: typeof console.info;
  };

  constructor() {
    try {
      // Store original console methods
      this.originalConsole = {
        error: console.error.bind(console),
        warn: console.warn.bind(console),
        log: console.log.bind(console),
        info: console.info.bind(console),
      };

      this.setupInterceptors();
      this.setupErrorHandlers();
    } catch (error) {
      // Fallback if console interception fails
      console.warn('Console logger initialization failed:', error);
      this.originalConsole = {
        error: console.error.bind(console),
        warn: console.warn.bind(console),
        log: console.log.bind(console),
        info: console.info.bind(console),
      };
    }
  }

  private setupInterceptors() {
    try {
      // Intercept console.error
      const originalError = console.error;
      console.error = (...args: any[]) => {
        this.captureLog('error', args);
        originalError.apply(console, args);
      };

      // Intercept console.warn
      const originalWarn = console.warn;
      console.warn = (...args: any[]) => {
        this.captureLog('warn', args);
        originalWarn.apply(console, args);
      };

      // Intercept console.log (optional, for debugging)
      const originalLog = console.log;
      console.log = (...args: any[]) => {
        this.captureLog('log', args);
        originalLog.apply(console, args);
      };

      // Intercept console.info
      const originalInfo = console.info;
      console.info = (...args: any[]) => {
        this.captureLog('info', args);
        originalInfo.apply(console, args);
      };
    } catch (error) {
      // Silently fail if interception fails
      this.originalConsole.error('Failed to setup console interceptors:', error);
    }
  }

  private setupErrorHandlers() {
    // Capture unhandled errors
    window.addEventListener('error', (event) => {
      this.captureLog('error', [
        event.message,
        event.filename,
        event.lineno,
        event.colno,
        event.error?.stack,
      ]);
    });

    // Capture unhandled promise rejections
    window.addEventListener('unhandledrejection', (event) => {
      this.captureLog('error', [
        `Unhandled Promise Rejection: ${event.reason}`,
        event.reason?.stack || '',
      ]);
    });
  }

  private captureLog(level: ConsoleLogEntry['level'], args: any[]) {
    try {
      const message = args
        .map((arg) => {
          if (arg instanceof Error) {
            return `${arg.message}\n${arg.stack || ''}`;
          }
          if (typeof arg === 'object') {
            return JSON.stringify(arg, null, 2);
          }
          return String(arg);
        })
        .join(' ');

      const entry: ConsoleLogEntry = {
        level,
        message,
        timestamp: new Date().toISOString(),
      };

      // Try to extract stack trace from error objects
      if (args[0] instanceof Error && args[0].stack) {
        entry.stack = args[0].stack;
      } else if (typeof args[0] === 'string' && args[1]?.stack) {
        entry.stack = args[1].stack;
      }

      this.logs.push(entry);

      // Keep only last maxLogs entries
      if (this.logs.length > this.maxLogs) {
        this.logs = this.logs.slice(-this.maxLogs);
      }
    } catch (error) {
      // Silently fail if logging fails
      this.originalConsole.error('Failed to capture log:', error);
    }
  }

  /**
   * Get all captured logs
   */
  getLogs(): ConsoleLogEntry[] {
    return [...this.logs];
  }

  /**
   * Get logs filtered by level
   */
  getLogsByLevel(level: ConsoleLogEntry['level']): ConsoleLogEntry[] {
    return this.logs.filter((log) => log.level === level);
  }

  /**
   * Get recent error and warning logs (most relevant for tickets)
   */
  getErrorLogs(limit: number = 50): ConsoleLogEntry[] {
    return this.logs
      .filter((log) => log.level === 'error' || log.level === 'warn')
      .slice(-limit);
  }

  /**
   * Clear all logs
   */
  clearLogs() {
    this.logs = [];
  }

  /**
   * Get browser information
   */
  getBrowserInfo() {
    try {
      return {
        userAgent: navigator?.userAgent || 'Unknown',
        platform: navigator?.platform || 'Unknown',
        language: navigator?.language || 'Unknown',
        cookieEnabled: navigator?.cookieEnabled ?? false,
        onLine: navigator?.onLine ?? false,
        screen: {
          width: window?.screen?.width || 0,
          height: window?.screen?.height || 0,
          availWidth: window?.screen?.availWidth || 0,
          availHeight: window?.screen?.availHeight || 0,
        },
        viewport: {
          width: window?.innerWidth || 0,
          height: window?.innerHeight || 0,
        },
        url: window?.location?.href || 'Unknown',
        referrer: document?.referrer || 'None',
        timestamp: new Date().toISOString(),
      };
    } catch (error) {
      return {
        error: 'Failed to collect browser info',
        timestamp: new Date().toISOString(),
      };
    }
  }
}

// Create singleton instance
let consoleLoggerInstance: ConsoleLogger | null = null;

export function getConsoleLogger(): ConsoleLogger {
  if (!consoleLoggerInstance) {
    consoleLoggerInstance = new ConsoleLogger();
  }
  return consoleLoggerInstance;
}

// Initialize on module load
if (typeof window !== 'undefined') {
  getConsoleLogger();
}

/**
 * Environment-aware logging helpers for application code.
 * Use these instead of raw console.log / console.warn for non-critical messages.
 * - In development: logs go through the normal console (and are captured for tickets).
 * - In production: debug/info/warn logs are suppressed to keep the console clean.
 */

export const logDebug = (...args: unknown[]): void => {
  if (import.meta.env.DEV) {
     
    console.log(...args);
  }
};

export const logInfo = (...args: unknown[]): void => {
  if (import.meta.env.DEV) {
     
    console.info(...args);
  }
};

export const logWarn = (...args: unknown[]): void => {
  if (import.meta.env.DEV) {
     
    console.warn(...args);
  }
};

// For errors, we still allow logging in production, but callers should also
// surface a user-facing message (toast, notification, etc.) where appropriate.
export const logError = (...args: unknown[]): void => {
   
  console.error(...args);
};

import { ERROR_TYPES, ERROR_MESSAGES, ROUTES, type ErrorType } from '@/constants';
import { useAppStore } from '@/stores/appStore';

export interface ErrorInfo {
  type: ErrorType;
  message: string;
  details?: string;
  code?: string;
  statusCode?: number;
  retryable: boolean;
  requiresAuth: boolean;
  userMessage: string;
}

export class ErrorHandler {
  static analyzeError(error: any): ErrorInfo {
    const errorMessage = typeof error === 'string' ? error : error?.message || '';
    const errorCode = error?.code || error?.error_code || '';
    const statusCode = error?.status || error?.statusCode;

    // Determine error type
    let type: ErrorType = ERROR_TYPES.UNKNOWN;
    let retryable = false;
    let requiresAuth = false;
    let userMessage: string = ERROR_MESSAGES.SERVER_ERROR;

    if (errorMessage.toLowerCase().includes('network') || 
        errorMessage.toLowerCase().includes('fetch') ||
        statusCode >= 500) {
      type = ERROR_TYPES.NETWORK;
      retryable = true;
      userMessage = ERROR_MESSAGES.NETWORK_ERROR;
    } else if (errorMessage.toLowerCase().includes('auth') || 
               errorMessage.toLowerCase().includes('unauthorized') ||
               statusCode === 401) {
      type = ERROR_TYPES.AUTH;
      requiresAuth = true;
      userMessage = ERROR_MESSAGES.UNAUTHORIZED;
    } else if (errorMessage.toLowerCase().includes('permission') || 
               errorMessage.toLowerCase().includes('forbidden') ||
               statusCode === 403) {
      type = ERROR_TYPES.PERMISSION;
      userMessage = ERROR_MESSAGES.FORBIDDEN;
    } else if (errorMessage.toLowerCase().includes('validation') ||
               statusCode === 400) {
      type = ERROR_TYPES.VALIDATION;
      userMessage = ERROR_MESSAGES.VALIDATION_FAILED;
    } else if (statusCode === 404) {
      userMessage = ERROR_MESSAGES.NOT_FOUND;
    }

    return {
      type,
      message: errorMessage,
      details: error?.details || error?.error_description,
      code: errorCode,
      statusCode,
      retryable,
      requiresAuth,
      userMessage
    };
  }

  static handleError(error: any, options: {
    showNotification?: boolean;
    logToConsole?: boolean;
    redirectOnAuth?: boolean;
  } = {}): ErrorInfo {
    const {
      showNotification = true,
      logToConsole = true,
      redirectOnAuth = true
    } = options;

    const errorInfo = this.analyzeError(error);

    // Log to console in development
    if (logToConsole && process.env.NODE_ENV === 'development') {
      console.error('Error Handler:', {
        original: error,
        analyzed: errorInfo
      });
    }

    // Show notification
    if (showNotification) {
      const { addNotification } = useAppStore.getState();
      addNotification({
        type: 'error',
        title: this.getErrorTitle(errorInfo.type),
        message: errorInfo.userMessage,
        priority: errorInfo.type === ERROR_TYPES.AUTH ? 'high' : 'medium'
      });
    }

    // Handle auth redirects
    if (redirectOnAuth && errorInfo.requiresAuth) {
      this.redirectToAuth();
    }

    return errorInfo;
  }

  static handleSuccess(message: string, options: {
    showNotification?: boolean;
    title?: string;
  } = {}) {
    const { showNotification = true, title = 'Success' } = options;

    if (showNotification) {
      const { addNotification } = useAppStore.getState();
      addNotification({
        type: 'success',
        title,
        message,
        priority: 'low'
      });
    }
  }

  private static getErrorTitle(type: ErrorType): string {
    switch (type) {
      case ERROR_TYPES.NETWORK:
        return 'Connection Error';
      case ERROR_TYPES.AUTH:
        return 'Authentication Required';
      case ERROR_TYPES.PERMISSION:
        return 'Access Denied';
      case ERROR_TYPES.VALIDATION:
        return 'Validation Error';
      default:
        return 'Error';
    }
  }

  private static redirectToAuth() {
    // Use setTimeout to avoid issues with React state updates
    setTimeout(() => {
      window.location.href = ROUTES.AUTH;
    }, 100);
  }

  static createRetryableOperation<T>(
    operation: () => Promise<T>,
    maxRetries: number = 3,
    delay: number = 1000
  ): () => Promise<T> {
    return async () => {
      let lastError: any;

      for (let attempt = 0; attempt <= maxRetries; attempt++) {
        try {
          return await operation();
        } catch (error) {
          lastError = error;
          const errorInfo = this.analyzeError(error);

          // Don't retry non-retryable errors
          if (!errorInfo.retryable || attempt === maxRetries) {
            throw error;
          }

          // Wait before retrying
          await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, attempt)));
        }
      }

      throw lastError;
    };
  }

  static async withErrorHandling<T>(
    operation: () => Promise<T>,
    errorOptions?: Parameters<typeof ErrorHandler.handleError>[1]
  ): Promise<T | null> {
    try {
      return await operation();
    } catch (error) {
      this.handleError(error, errorOptions);
      return null;
    }
  }
}
